//! The resumable-function IR (PLAN §4.5): generator and async function bodies
//! compile to a linear `Vec<Step>` with an explicit instruction pointer, so
//! `yield`/`await` suspend and resume exactly like the spec's generator
//! resume algorithm. This is the seed of the Phase 18 bytecode VM.
//!
//! Every expression and statement compiles to `Step`s; suspension is just
//! more bytecode (`Yield`/`Await`), so generators and async functions are
//! ordinary compiled bodies. Control flow is explicit jumps; lexical
//! environments mirror the compiler's scope stack on the VM side;
//! `try`/`catch`/`finally` use a handler table plus a runtime try stack and
//! a pending-control slot.

use std::collections::{HashMap, HashSet};

use crux::error::{ErrorKind, JsError};
use crux::handle::Handle;
use crux::heap::{GcAny, Trace};
use crux::property::PropertyKey;
use crux::string::JsString;
use crux::value::{Value, ValueKind, is_callable};
use syntax::ast::{
    Argument, ArrayBindingElement, ArrayElement, ArrowBody, AssignOp, BinaryOp, BindingElement,
    BindingPattern, Block, Class, ClassElement, ClassElementName, Expr, ExprKind, ForBinding,
    ForInit, Function, LogicalOp, MemberExpr, MemberProperty, ObjectLiteral, ObjectProperty,
    PropertyName, Stmt, StmtKind, SwitchCase, UnaryOp, UpdateOp, VarDeclKind, VarDeclarator,
};

use crate::agent::Agent;
use crate::context::{
    get_new_target, get_super_base, get_super_constructor, get_this_environment,
    resolve_this_binding,
};
use crate::env::{DeclarativeEnv, EnvRecord, EnvRef, new_declarative_environment};
use crate::eval::block_declaration_instantiation;
use crate::expr::{get_iterator, iterator_close, iterator_step};
use crate::flow::Completion;
use crate::function::EcmaFunction;

/// Which `Function.prototype` method a `Step::CallApply` site recognized: the
/// compiler matches the member-call's property name; the handler compares the
/// resolved function against the realm's intrinsic and calls the receiver
/// directly on a match (see the step).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ApplyKind {
    Apply,
    Call,
}

/// One resumable-function instruction.
#[derive(Debug, Clone)]
pub enum Step {
    // ----- stack -----
    Push(Value),
    Pop,
    Dup,
    /// Duplicate the top two values in order: `[a, b] -> [a, b, a, b]` — a
    /// computed member/super compound assignment needs the (base, key) pair
    /// twice: once for the read, once for the write.
    Dup2,
    // ----- expression continuation steps -----
    Unary(UnaryOp),
    Binary(BinaryOp),
    /// A binary op whose right operand is a compile-time `Number` literal:
    /// the constant stays in the step, skipping the `Push`/`Pop` round-trip
    /// (Ignition's `LdaSmi`-style small-int immediates).
    BinaryImm {
        op: BinaryOp,
        imm: f64,
    },
    GetMemberName {
        name: crux::AtomId,
    },
    GetMemberComputed,
    /// The compound/update variant of GetMemberComputed: convert the key once
    /// (after the nullish check) and leave the converted key for the write.
    GetMemberComputedKeep,
    /// The compound/update variant of GetSuperComputed.
    GetSuperComputedKeep,
    GetSuperName {
        name: crux::AtomId,
    },
    GetSuperComputed,
    GetPrivate {
        atom: crux::AtomId,
    },
    ThisValue,
    /// Resolve a bare identifier reference (TDZ check included) and push its
    /// current value (spec 13.1.2).
    LoadIdent {
        name: crux::AtomId,
    },
    /// Push a frame-slot binding's value (Cut 3 fast path); a TDZ marker
    /// throws the ReferenceError.
    LoadLocal {
        slot: usize,
    },
    /// Pop into a frame slot (assignment to a binding; a TDZ-marker current
    /// value throws for `let`/`const`-like bindings).
    StoreLocal {
        slot: usize,
    },
    /// Cut 34: store to a frame slot AND set the statement completion to the
    /// stored value in one step — a statement-position assignment's result
    /// is otherwise dup'd purely so `SetCompletion` can pop it. Same TDZ
    /// check as `StoreLocal`.
    FusedStoreLocal {
        slot: usize,
    },
    /// Cut 34: the `FusedStoreLocal` analogue for a declared top-level var.
    FusedStoreGlobal {
        name: crux::AtomId,
    },
    /// Pop into a frame slot, no TDZ check (the declaration's first write).
    InitLocal {
        slot: usize,
    },
    /// Apply a `++`/`--` to a frame-slot binding: read the slot, compute the
    /// new value, store it, and push the result (old for postfix, new for
    /// prefix).
    UpdateLocal {
        slot: usize,
        op: UpdateOp,
        prefix: bool,
    },
    /// Fused `i++` in a value-discarding position (the `for` update): read
    /// the slot, add 1, store, push nothing (Cut 4).
    Inc {
        slot: usize,
    },
    /// Fused `i--` in a value-discarding position: read the slot, subtract 1,
    /// store, push nothing (Cut 4).
    Dec {
        slot: usize,
    },
    GetSuperBase,
    AssignIdent {
        name: crux::AtomId,
        op: AssignOp,
        set_name: bool,
    },
    AssignMemberName {
        name: crux::AtomId,
        op: AssignOp,
    },
    AssignMemberComputed {
        op: AssignOp,
    },
    AssignSuperName {
        name: crux::AtomId,
        op: AssignOp,
    },
    AssignSuperComputed {
        op: AssignOp,
    },
    AssignPrivate {
        atom: crux::AtomId,
        op: AssignOp,
    },
    Destructure {
        pattern: BindingPattern,
    },
    // ----- step-based destructuring (suspension-capable) -----
    /// Pop the value and GetIterator, pushing the record on the destructure
    /// stack.
    DestructureBegin,
    /// Step the innermost destructure iterator, pushing the value; when
    /// exhausted the element still receives *undefined* (a default
    /// initializer must run and may suspend) and the iterator is marked done
    /// so the trailing close is skipped.
    DestructureNext,
    /// Pop the value; if undefined, jump to `use_default` (the value is
    /// consumed); otherwise push it back for the assignment.
    DestructureUndef {
        use_default: usize,
    },
    /// Collect the remaining values of the innermost destructure iterator
    /// into a fresh array, push it, and pop the iterator (no close).
    DestructureRest,
    /// Pop the value; if it is null or undefined throw a TypeError, else
    /// push it back (RequireObjectCoercible of an object pattern).
    DestructureObjCoercible,
    /// Pop the object (a dup) and push the value of the constant property
    /// key.
    DestructureObjKey {
        key: crux::property::PropertyKey,
    },
    /// Pop the key then the object (a dup) and push the property value.
    DestructureObjKeyComputed,
    /// Store the converted computed key (an `ObjectKeyToPropertyKey` result)
    /// for the later `DestructureObjKeyGet`: the pattern's PropertyName is
    /// evaluated before the assignment target's reference, while the property
    /// read runs after it (spec 13.15.5.6).
    DestructureObjKeyStore,
    /// Pop the stored computed key and push the object's property value.
    DestructureObjKeyGet,
    /// Pop the object (a dup), CopyDataProperties into a fresh rest object,
    /// and push it.
    DestructureObjRest {
        excluded: Vec<crux::property::PropertyKey>,
    },
    /// Pop the innermost destructure iterator and close it (a normal
    /// completion: the pattern consumed fewer values than the iterator
    /// held).
    DestructureClose,
    /// Pop the object pattern's base object off the object stack.
    DestructureObjEnd,
    /// Initialize a let/const/using declaration's binding in the current
    /// lexical environment; the binding was created uninitialized by
    /// declaration instantiation (unlike `Destructure`, which puts a value
    /// into an already-initialized binding).
    DeclInit {
        pattern: BindingPattern,
    },
    /// Resolve a `var` declaration's binding before its initializer runs
    /// (spec 14.3.2 step 2): a `with` object's property is the assignment
    /// target even when the initializer mutates the object.
    ResolveVarIdent {
        name: crux::AtomId,
    },
    /// Resolve a private member reference: pop the receiver, resolve the
    /// private name, and push the reference — the base stays off the value
    /// stack, so a short-circuited `&&=`/`||=`/`??=` leaves only the old
    /// value as the result.
    ResolvePrivateRef {
        atom: crux::AtomId,
    },
    /// Resolve a named member reference the same way: pop the receiver and
    /// push the reference.
    ResolveMemberRefName {
        name: crux::AtomId,
    },
    /// Resolve a computed member reference: pop the key (converting it to a
    /// property key once, spec 13.15.4: ToPropertyKey runs before the read)
    /// and the receiver, then push the reference.
    ResolveMemberRefComputed,
    /// Push the value of the reference on top of the var-reference stack —
    /// the assignment target resolved before its RHS evaluated (spec
    /// 13.15.3 steps 1-5: PutValue uses the initially created reference even
    /// if the binding is gone by then).
    GetVarReference,
    /// Push the call `this` of the reference on top of the var-reference
    /// stack — the base object for a property reference, the with base
    /// object for an environment reference, `undefined` otherwise (spec
    /// 13.4.3 step 4). Used for plain-identifier callees inside a `with`.
    GetVarReferenceThis,
    /// Assign a `var` declaration's value to the pre-resolved reference.
    PutVarReference,
    /// Discard the pre-resolved reference without assigning (a
    /// short-circuited `&&=`/`||=`/`??=` never reaches PutVarReference).
    PopVarReference,
    /// Resolve a super property reference: GetThisBinding then GetSuperBase
    /// (spec 13.3.7.1), the receiver recorded in [[ThisValue]].
    ResolveSuperRefName {
        name: crux::AtomId,
    },
    /// Resolve a computed super property reference: the base copy is already
    /// on the stack (GetSuperBase ran the this-check first), the converted
    /// key on top; both are consumed and the reference recorded.
    ResolveSuperRefComputed,
    /// Apply a compound assignment (`+=`, ...) to the pre-resolved
    /// reference: pop the new value and the old value, compute the result,
    /// and put it.
    PutVarReferenceOp {
        op: AssignOp,
    },
    /// Apply a `++`/`--` to the pre-resolved reference.
    UpdateVarReference {
        op: UpdateOp,
        prefix: bool,
    },
    /// Evaluate a `using`/`await using` initializer: register the value as a
    /// disposable resource on the current lexical environment, then bind it
    /// (spec 9.3.1 / 14.2.2).
    UsingInit {
        pattern: BindingPattern,
        is_await: bool,
    },
    /// Set the `name` property of the value on top of the stack (NamedEvaluation,
    /// spec 14.2.2 step 2.d): pop, set, push.
    SetFunctionName {
        name: crux::AtomId,
    },
    /// An upstream `?.` short-circuited: the rest of the chain is skipped
    /// (spec 13.4.3 optional chains propagate undefined without evaluating
    /// the remaining links).
    SetChainShort,
    ClearChainShort,
    JumpIfChainShort(usize),
    UpdateIdent {
        name: crux::AtomId,
        op: UpdateOp,
        prefix: bool,
    },
    UpdateMemberName {
        name: crux::AtomId,
        op: UpdateOp,
        prefix: bool,
    },
    UpdateMemberComputed {
        op: UpdateOp,
        prefix: bool,
    },
    UpdateSuperName {
        name: crux::AtomId,
        op: UpdateOp,
        prefix: bool,
    },
    UpdateSuperComputed {
        op: UpdateOp,
        prefix: bool,
    },
    UpdatePrivate {
        atom: crux::AtomId,
        op: UpdateOp,
        prefix: bool,
    },
    DeleteIdent {
        name: crux::AtomId,
    },
    DeleteMemberName {
        name: crux::AtomId,
    },
    DeleteMemberComputed,
    /// `delete super.x` / `delete super[x]`: a ReferenceError before the key
    /// is evaluated (spec 13.5.1.2 step 4.b).
    DeleteSuper,
    TypeofTop,
    /// `typeof <identifier>`: an unresolvable reference yields "undefined"
    /// instead of throwing (spec 13.5.3.2 step 1).
    TypeofIdent {
        name: crux::AtomId,
    },
    PrivateIn {
        atom: crux::AtomId,
    },
    /// Call with `[this, callee]` on the stack and the arguments in the
    /// VM's argument slot.
    Call {
        direct_eval: bool,
    },
    /// Call with `[this, callee, arg1..argN]` on the stack (0-2 plain
    /// arguments, no spreads): the VM reads the arguments in place and skips
    /// the argument-vector build (V8 `CallProperty0/1/2` +
    /// `CallUndefinedReceiver0/1/2`).
    CallFast {
        argc: u8,
        direct_eval: bool,
    },
    /// Call-site recognition of `Function.prototype.apply`/`call` (perf.md
    /// "remaining apply floor"): a member call `f.apply(x, arr)` /
    /// `f.call(x, ...)` compiles to the normal member read — a shadowed
    /// `apply`/`call` resolves onto the stack and is called normally — plus
    /// this step. The handler checks the resolved function against the realm's
    /// intrinsic; on a match it calls `f` directly with the `this` argument
    /// and the `CreateListFromArrayLike` element reads, all on this Vm
    /// (skipping the builtin dispatch, the per-call argument-list `Vec`, and
    /// the pooled-Vm take/return), and falls back to the general call of the
    /// resolved function otherwise. Stack: `[..., f, apply/call, thisArg,
    /// arg1..argN]` — the `CallFast` layout, `argc` = N+1.
    CallApply {
        argc: u8,
        kind: ApplyKind,
    },
    /// Cut 35 slice 2: a plain global-named callee called with an undefined
    /// receiver (`f(x)` with `f` a declared script global, no `with`): the
    /// receiver push and the callee load fuse into the call step — the
    /// arguments are the top `argc` stack values, the callee is loaded from
    /// the global cell inside the handler, and `this` is `undefined` (spec
    /// 13.4.3). Two fewer dispatches per call in a hot loop.
    CallFastGlobal {
        name: crux::AtomId,
        argc: u8,
        direct_eval: bool,
    },
    /// Cut 35 slice 4: like `CallFastGlobal` but the callee comes from a
    /// frame slot (a certified-value var holding a certified closure): the
    /// receiver push and the slot load fuse into the call step. A slot read
    /// is side-effect-free, so the only ordering hazard vs spec 13.4.3 is an
    /// argument that WRITES the callee's slot — the compiler fuses only when
    /// no argument expression assigns the name (a certified script's args
    /// can write a declared var only directly).
    CallFastSlot {
        slot: usize,
        argc: u8,
    },
    /// Cut 35 slice 17: the fused `x = f(args)` for a slot callee with
    /// plain slot args — the arg loads, the slot-callee call, and the
    /// store in one step (the `n = f(n)` bench body drops from three
    /// dispatches to one). The arg slots are read in order with their
    /// `LoadLocal` TDZ checks, the callee comes from its slot, and the
    /// result stores to the target with the `FusedStoreLocal` TDZ check.
    CallFastSlotStore {
        callee_slot: usize,
        arg_slots: Vec<usize>,
        store_slot: usize,
    },
    /// Cut 35 slice 20: the fused `x = f(args)` for a global callee with
    /// plain slot args — the arg loads, the global-callee call (the
    /// slice-2 fused call + the slice-12 global leaf cache), and the store
    /// in one step, mirroring `CallFastSlotStore`. The direct-eval flag is
    /// always false (the global-call fuse excludes the `eval` identifier).
    CallFastGlobalStore {
        name: crux::AtomId,
        arg_slots: Vec<usize>,
        store_slot: usize,
    },
    /// Proper tail call (spec 14.2.2): a strict-mode `return f(x)` outside
    /// any try/with. The callee/args are on the stack exactly as for
    /// `CallFast`, but the handler runs the return's cleanup (iterator
    /// close, env unwind) and replaces the current frame with the callee's
    /// instead of recursing — `run_inner`'s driver loops on the new body.
    TailCallFast {
        argc: u8,
        direct_eval: bool,
    },
    /// The vector-argument form of `TailCallFast` (≥3 args or a spread).
    TailCall {
        direct_eval: bool,
    },
    /// Tail form of `CallFastGlobal` (a plain declared-global callee).
    TailCallFastGlobal {
        name: crux::AtomId,
        argc: u8,
    },
    /// Tail form of `CallFastSlot` (a frame-slot callee).
    TailCallFastSlot {
        slot: usize,
        argc: u8,
    },
    /// Cut 46: a proper tail call whose callee is the enclosing named
    /// function expression's own self-binding — statically the running body
    /// itself (the self-binding is immutable, and the compiler emits this
    /// only for a certified capture-free, arguments-free body whose own
    /// name resolves to the `Env` walk). The arguments sit alone on the
    /// stack (`[a1..aN]` — no `this`/callee pushes); the handler rebinds the
    /// frame in place and re-enters the body's entry instead of looking up
    /// the callee, swapping contexts, and re-running the call machinery —
    /// the whole self-recursive tail chain runs with no runtime round-trip.
    TailCallSelf {
        argc: u8,
    },
    /// Cut 47: a tail call to the enclosing function's own NAME in a body
    /// that is NOT a named expression — a top-level or enclosing function
    /// declaration (`function f(n) { return f(n - 1); }`), where the name
    /// resolves through the global/outer env and could have been reassigned.
    /// The callee/args sit on the stack exactly as for `TailCallFast`
    /// (`[this, callee, a1..aN]`); the JIT compares the resolved callee
    /// against the running closure (`JitCallContext::current_function`)
    /// and jumps to the body's re-entry on a match (the self-recursive
    /// chain runs in one machine-code invocation), else runs the general
    /// `tail_call` helper. The interpreter routes it through the shared
    /// `tail_call_shared` machinery, which handles both cases.
    TailCallSelfCheck {
        argc: u8,
    },
    /// Cut 51: the vector-argument form of `TailCallSelf` (a spread, or
    /// more plain arguments than `FAST_CALL_MAX_ARGS`): the named-expression
    /// self-binding is statically the running body — the arguments sit in the
    /// Vm's vector (`ArgsBase`/`ArgsPush`/`ArgsSpread`), no receiver/callee
    /// pushes; the handler rebinds the frame and re-enters the body's entry
    /// with no runtime round-trip.
    TailCallSelfVector,
    /// Cut 51: the vector-argument form of `TailCallSelfCheck`: the
    /// receiver/callee sit on the stack as for the vector `TailCall`
    /// (`[this, callee]`), the arguments in the Vm's vector; the JIT compares
    /// the resolved callee against the running closure and jumps on a match,
    /// else runs the general vector tail-call helper.
    TailCallSelfCheckVector,
    /// Tail form of `TaggedTemplate` (`return tag\`...\``).
    TailTaggedTemplate(syntax::ast::TemplateLiteral),
    SuperCall,
    Construct,
    TaggedTemplate(syntax::ast::TemplateLiteral),
    /// Create a function expression's closure against the current lexical
    /// environment (spec 15.2.5). `strict` is the enclosing code's
    /// strictness, inherited when the body has no directive of its own.
    /// `outer_chain` (Cut 3 continuation, nested context chains) is the
    /// capture-context layout of each enclosing certified body, innermost
    /// first (each entry = the body's captured names; per-iteration head
    /// names open at this creation site are excluded): the closure's
    /// references to those bindings compile to static context-chain reads.
    CreateFunction {
        function: Box<syntax::ast::Function>,
        strict: bool,
        outer_chain: Vec<Vec<crux::AtomId>>,
        /// Cut 28: the per-iteration head layouts of the certified loops
        /// open at this creation site (see
        /// [`crate::function::EcmaFunction::per_iteration_chain`]).
        per_iteration_chain: Vec<(Vec<crux::AtomId>, usize)>,
    },
    /// Create an arrow function's closure: `[[ThisMode]]` is lexical and
    /// there is no `prototype` (spec 15.3.2). `outer_chain` is as in
    /// `CreateFunction`.
    CreateArrow {
        is_async: bool,
        params: Vec<syntax::ast::BindingElement>,
        body: syntax::ast::ArrowBody,
        strict: bool,
        outer_chain: Vec<Vec<crux::AtomId>>,
        /// Cut 28: see [`Step::CreateFunction`].
        per_iteration_chain: Vec<(Vec<crux::AtomId>, usize)>,
    },
    /// `new.target` (spec 13.3.5.3): the active constructor, or *undefined*
    /// at the script level.
    NewTarget,
    /// A `RegExp` literal: construct a fresh RegExp object at runtime — a
    /// literal creates a new object per evaluation (spec 13.2.4.4).
    RegExpLiteral {
        pattern: JsString,
        flags: JsString,
    },
    // ----- literals -----
    ArrayBegin,
    ArrayElement,
    ArraySpread,
    ArrayHole,
    /// Finish the array literal: set its length to the element count (spec
    /// 13.2.4.1 step 6).
    ArrayEnd,
    // ----- class definitions with suspending heritage/computed names -----
    ClassBegin {
        class: Box<Class>,
        binding: Option<crux::string::AtomId>,
        key_count: usize,
    },
    ClassHeritage,
    ClassKeyToPropertyKey,
    ClassFinish {
        class: Box<Class>,
        binding: Option<crux::string::AtomId>,
        key_count: usize,
    },
    ObjectBegin,
    ObjectInitName {
        name: crux::AtomId,
        set_name: bool,
        /// A shorthand property (`{ x }`): never the `__proto__` setter
        /// (Annex B.3.1).
        shorthand: bool,
    },
    ObjectInitComputed {
        set_name: bool,
    },
    /// Convert the computed key on top of the stack to a property key
    /// immediately after it evaluates — before the property's value evaluates
    /// (spec 13.2.5.5 step 1 vs 6.a: the key's coercion runs first, so a
    /// key whose `toString` mutates the value expression's inputs is
    /// observed).
    ObjectKeyToPropertyKey,
    ObjectMethodName {
        name: crux::AtomId,
        function: Function,
    },
    ObjectMethodComputed {
        function: Function,
    },
    ObjectAccessorName {
        name: crux::AtomId,
        get: bool,
        param: Option<BindingElement>,
        body: syntax::ast::Block,
    },
    ObjectAccessorComputed {
        get: bool,
        param: Option<BindingElement>,
        body: syntax::ast::Block,
    },
    ObjectSpread,
    PushStr(JsString),
    ConcatStr,
    ConcatStrConst(JsString),
    // ----- arguments -----
    /// Record the current argument-vector length: a call's arguments are
    /// appended after it and the call takes exactly the appended slice, so
    /// nested calls (an argument that is itself a call) keep their vectors
    /// separate.
    ArgsBase,
    ArgsPush,
    ArgsSpread,
    // ----- statements -----
    /// Create the block environment and instantiate its declarations.
    EnterBlock {
        decls: Vec<Stmt>,
    },
    /// Evaluate a function declaration: instantiate the closure and bind the
    /// hoisted name (spec 15.2.6, incl. the Annex B statement-position form).
    FunctionDecl {
        stmt: Box<Stmt>,
    },
    /// Initialize a top-level function declaration's certified binding at
    /// body entry (the declaration is hoisted — spec 10.2.11): instantiate
    /// the closure against the capture context and store it into the frame
    /// slot or capture-context slot the binding was allocated to. The
    /// declaration statement itself is then empty (15.2.6). `outer_chain` is
    /// the closure's enclosing certified context chain (see
    /// `CreateFunction`).
    FunctionDeclInit {
        name: crux::AtomId,
        function: Box<syntax::ast::Function>,
        frame_slot: Option<usize>,
        context_slot: Option<usize>,
        outer_chain: Vec<Vec<crux::AtomId>>,
        /// Cut 28: the inherited per-iteration chain (see
        /// [`Step::CreateFunction`]); the declaration instantiates at body
        /// entry, before this body's own loops start.
        per_iteration_chain: Vec<(Vec<crux::AtomId>, usize)>,
    },
    /// Reset the statement-completion register to an empty completion (spec
    /// 6.2.2.3): the current statement's completion starts empty.
    ResetCompletion,
    /// UpdateEmpty with *undefined* (spec 6.2.2.4): the statement always
    /// completes normally, so an empty register becomes *undefined*.
    NormalizeCompletion,
    /// Enter a statement list (spec 14.2.1): save the enclosing list's
    /// completion state and start the new list empty.
    ListBegin,
    /// Leave a statement list: an empty list restores the enclosing list's
    /// state (UpdateEmpty of the statement list), a valued list keeps its
    /// value as the new accumulation.
    ListEnd,
    /// Save the statement-completion register before a `finally` block runs:
    /// the finally's statements must not clobber the completion of the
    /// statement whose control passes through it (spec 14.15.5).
    SaveCompletion,
    /// Restore the statement-completion register after a `finally` block
    /// completed normally (an abrupt finally replaces the completion anyway).
    RestoreCompletion,
    LeaveBlock,
    EnterTry {
        handler: usize,
    },
    Exit {
        after: usize,
    },
    CatchBind {
        param: Option<BindingPattern>,
        decls: Vec<Stmt>,
    },
    FinallyEnd,
    EnterWith,
    PerIteration {
        names: Vec<JsString>,
    },
    EnterLoopEnv {
        kind: VarDeclKind,
        decls: Vec<VarDeclarator>,
    },
    /// A for-in/for-of lexical head's temporary environment: the head names
    /// are uninitialized (in TDZ) while the RHS evaluates (spec 14.7.5.4 /
    /// 14.7.6.1).
    EnterIterTdzEnv {
        names: Vec<JsString>,
    },
    LeaveIterTdzEnv,
    ForInBegin,
    /// Cut 35 slice 18: `back` is where a successful fetch continues — the
    /// do-while loop shape's body start (the certified paths) or the next
    /// step (the generic paths, matching the old fall-through).
    ForInNext {
        done: usize,
        back: usize,
    },
    ForInBind {
        left: ForBinding,
    },
    ForInRestore,
    ForOfBegin {
        top: usize,
        end: usize,
    },
    ForOfNext {
        done: usize,
        back: usize,
    },
    /// The fused for-of protocol step + slot head bind (Cut 21): the
    /// element writes the frame slot directly — one less dispatch and no
    /// value-stack round-trip per element. The generic iterator path
    /// writes the slot the same way. `back` is the do-while body start
    /// (Cut 35 slice 18).
    ForOfNextBindLocal {
        slot: usize,
        done: usize,
        back: usize,
    },
    ForOfBind {
        left: ForBinding,
    },
    /// The fast `for-of` head bind for a simple `var` ident whose binding
    /// resolved to a frame slot (Cut 3) — the element is stored directly.
    ForOfBindLocal {
        slot: usize,
    },
    /// The fast `for-of` head bind for a simple `var` ident whose binding
    /// resolved to the global object — the element is stored via the global
    /// cell (mirroring `StoreGlobal`).
    ForOfBindGlobal {
        name: crux::AtomId,
    },
    ForOfRestore,
    ForOfClose,
    AsyncForOfBegin {
        top: usize,
        end: usize,
    },
    AsyncForOfNext,
    AsyncForOfTest {
        done: usize,
    },
    AsyncForOfBind {
        left: ForBinding,
    },
    AsyncForOfRestore,
    AsyncForOfClose,
    SwitchDisc,
    SwitchTest {
        case: usize,
    },
    SetCompletion,
    // ----- control flow -----
    Jump(usize),
    JumpIfFalse(usize),
    JumpIfTrue(usize),
    JumpIfFalseKeep(usize),
    JumpIfTrueKeep(usize),
    JumpIfNullishKeep(usize),
    JumpIfNotNullishKeep(usize),
    /// Fused loop test `slot <op> imm` (Cut 4): read the slot, abstract-compare
    /// against the constant, jump to `target` when the test is false — the
    /// arithmetic loop's `i < 1_000_000` (LoadLocal + BinaryImm + JumpIfFalse)
    /// becomes one step. The relational semantics are `apply_binary`'s, so the
    /// comparison is exactly what the general path computes.
    JumpIfLtImm {
        slot: usize,
        imm: f64,
        target: usize,
    },
    JumpIfLeImm {
        slot: usize,
        imm: f64,
        target: usize,
    },
    JumpIfGtImm {
        slot: usize,
        imm: f64,
        target: usize,
    },
    JumpIfGeImm {
        slot: usize,
        imm: f64,
        target: usize,
    },
    /// Fused strict-equality branch `slot === imm` (an `if (x === N)` /
    /// `while (x === N)` condition as ONE step instead of LoadLocal +
    /// BinaryImm + JumpIfFalse): read the slot, test it against the numeric
    /// literal with STRICT equality — a non-Number value is never strictly
    /// equal to a Number, so the test needs no coercion and no general
    /// evaluator — and jump to `target` when the test is FALSE (the family
    /// convention: `JumpIfLtImm` likewise jumps when `slot < imm` is
    /// false). Emitted only for a tdz-free frame-slot `var`.
    JumpIfEqImm {
        slot: usize,
        imm: f64,
        target: usize,
    },
    /// The `slot !== imm` sibling of [`Step::JumpIfEqImm`]: jump to
    /// `target` when `slot !== imm` is false (i.e. when the slot holds the
    /// Number `imm`).
    JumpIfNeqImm {
        slot: usize,
        imm: f64,
        target: usize,
    },
    /// The fused relational loop test with a fast-binding limit (`i < n`
    /// where `n` is a frame slot or declared global — the general path
    /// evaluates the limit every iteration, so the fused head re-reads it):
    /// read the counter slot and the limit binding, apply the abstract
    /// comparison, and jump to `target` when the test is false — exactly
    /// what `LoadLocal; LoadLocal/LoadGlobal; Binary; JumpIfFalse`
    /// computes. The literal-limit shapes use the `JumpIf*Imm` steps above;
    /// this step covers the non-literal limit (emitted only for a
    /// frame-slot counter, so the loop can never bail a new shape out of
    /// the JIT).
    JumpIfRelLimit {
        op: BinaryOp,
        slot: usize,
        limit: RelLimit,
        target: usize,
    },
    /// Gap-close M6 slice 2: the hoisted-loop guard. Pops the receiver (a
    /// TypedArray-length candidate the compiler pushed); when it is an
    /// IntegerIndexed object with no own `length` — the exact typed-array
    /// probe — pushes `Number(effective_length)` and falls through (the
    /// compiler stores it in a hidden frame slot and runs the loop against
    /// that hoisted limit: a call-free body cannot detach/resize/redefine
    /// the view, so the length is loop-invariant); otherwise jumps to
    /// `target`, the compiler's general per-iteration loop (unchanged
    /// semantics). Mirror of the runtime `typed_array_length` FFI probe.
    TypedArrayLengthHoist {
        target: usize,
    },
    // ----- top-level fast path (script-level bindings) -----
    /// Read a declared top-level `var`/function directly off the global
    /// object — the binding is guaranteed to exist (script instantiation
    /// created the property), so the env-chain resolve walk disappears.
    LoadGlobal {
        name: crux::AtomId,
    },
    /// Pop into a declared top-level `var` (a `var x = v` initializer or an
    /// assignment to `x`).
    StoreGlobal {
        name: crux::AtomId,
    },
    /// Apply `++`/`--` to a top-level `var`, pushing the result (old for
    /// postfix, new for prefix).
    UpdateGlobal {
        name: crux::AtomId,
        op: UpdateOp,
        prefix: bool,
    },
    /// Fused top-level `i++` in a value-discarding position (the `for`
    /// update): read, add 1, store, push nothing.
    IncGlobal {
        name: crux::AtomId,
    },
    /// Fused top-level `i--` in a value-discarding position.
    DecGlobal {
        name: crux::AtomId,
    },
    /// Fused top-level loop test `x <op> imm` (see `JumpIfLtImm`): the
    /// slot is a declared global var.
    JumpIfLtGlobalImm {
        name: crux::AtomId,
        imm: f64,
        target: usize,
    },
    JumpIfLeGlobalImm {
        name: crux::AtomId,
        imm: f64,
        target: usize,
    },
    JumpIfGtGlobalImm {
        name: crux::AtomId,
        imm: f64,
        target: usize,
    },
    JumpIfGeGlobalImm {
        name: crux::AtomId,
        imm: f64,
        target: usize,
    },
    /// The fused canonical loop's per-iteration head (Cut 15): `for (var i
    /// = INIT; i <op> LIMIT; i++/i--)` on a fast binding — the increment,
    /// the next test, and the back-jump run in one step (the body dispatches
    /// inline), replacing the `IncGlobal`+`JumpIfLtGlobalImm`+`Jump`
    /// sequence with a single dispatch. The loop's first test is the
    /// existing `JumpIfLtGlobalImm` before the body.
    FastLoopHead {
        var: FastLoopVar,
        op: BinaryOp,
        limit: RelLimit,
        inc: UpdateOp,
        /// Back to the body start when the test passes.
        body_start: usize,
        /// Continue at when the test fails.
        after: usize,
    },
    /// The fused canonical loop's counter prologue (Cut 17): load the
    /// binding's current value into the `Vm::loop_counter` field
    /// (`FastLoopVar::Counter` heads then work on it). Emitted once, after
    /// the loop init.
    FastLoopBind {
        var: FastLoopVar,
    },
    /// The fused canonical loop's counter epilogue (Cut 17): write the
    /// accumulator back to the binding. Emitted once at the loop exit — on
    /// the `end_label` path, so a `break` lands on it too (a mid-loop
    /// `continue` skips it; a `return`/uncaught throw leaves the frame
    /// dead, so the stale binding is unobservable).
    FastLoopStore {
        var: FastLoopVar,
    },
    /// Run a register-lowered loop body (Cut 35 slice 9): the ops address
    /// the current frame — the script's inline frame here (the leaf path
    /// uses the stack segment via `leaf_frame_base`) — with the
    /// accumulator as scratch. Since Cut 35 slice 21 the loop counter
    /// lives in the dedicated `Vm::loop_counter` field, so the body needs
    /// no save/restore or entry push. The body's transient stack use (a
    /// member store's pushed result) is truncated to the entry length; the
    /// completion is left untouched (the loop machinery owns the loop's
    /// completion).
    RunRegBody {
        ops: Box<[LeafOp]>,
    },
    /// Push the fused loop counter (the dedicated `Vm::loop_counter` field)
    /// onto the value stack: the body's redirected reads of the counter.
    PushAcc,
    /// Pop the value stack into the fused loop counter: the body's
    /// redirected `counter = expr` assignments.
    PopAcc,
    /// Increment the fused loop counter in place (no stack effect): the
    /// body's redirected statement-position `counter++` (the statement's
    /// `SetCompletion` discards the pushed old value, so `Update`
    /// compiles to `PushAcc; IncAcc`).
    IncAcc,
    /// Decrement the fused loop counter in place (see `IncAcc`).
    DecAcc,
    /// The certified body's capture context (Cut 3 continuation): push the
    /// value of the captured binding at `index` (the per-call declarative
    /// environment holds the bindings; a `None` value is the TDZ marker).
    /// `depth` is the static context-chain depth (0 = the body's own
    /// capture context; nested closure bodies resolve enclosing bodies'
    /// contexts through it), skipping per-iteration envs.
    LoadContextSlot {
        depth: usize,
        index: usize,
    },
    /// Pop into the captured binding at `depth`/`index` (an assignment: the
    /// current value must not be the TDZ marker, and an outer immutable
    /// binding throws).
    StoreContextSlot {
        depth: usize,
        index: usize,
    },
    /// Pop into the captured binding at `index` (the first write: no
    /// check).
    InitContextSlot {
        index: usize,
    },
    /// Read the captured binding at `depth`/`index`, apply `++`/`--`, store,
    /// and push the old (postfix) or new (prefix) value.
    UpdateContextSlot {
        depth: usize,
        index: usize,
        op: UpdateOp,
        prefix: bool,
    },
    /// Create the first per-iteration environment of a certified lexical
    /// for-head whose bindings a body closure captures (Cut 3
    /// continuation): fresh bindings initialized from the capture context's
    /// head slots, pushed on the env stack so the loop's exit/break
    /// `LeaveBlock` pops it. Later iterations re-use the env-path
    /// `PerIteration` step (floating envs; the stack top stays the first
    /// one).
    EnterPerIteration {
        names: Vec<JsString>,
    },
    /// Push the per-iteration binding at `depth` outers from the current
    /// per-iteration env (0 = this loop's env), slot `index` in that env's
    /// head-name layout.
    LoadPerIteration {
        depth: usize,
        index: usize,
    },
    /// Pop into the per-iteration binding at `depth`/`index` (see
    /// `LoadPerIteration`; the per-iteration bindings are always
    /// initialized by the fresh-copy machinery, so no TDZ check).
    StorePerIteration {
        depth: usize,
        index: usize,
    },
    /// Read the per-iteration binding at `depth`/`index`, apply `++`/`--`,
    /// store, and push the old (postfix) or new (prefix) value.
    UpdatePerIteration {
        depth: usize,
        index: usize,
        op: UpdateOp,
        prefix: bool,
    },
    /// Fill the body's `arguments` slot (Cut 3 continuation): build the
    /// arguments object from the call's arguments and store it into the
    /// frame slot. Emitted once at body entry. `mapped` is `Some(formals)`
    /// for a sloppy simple-param body — the mapped object aliases the
    /// formal parameters through the capture context — and `None` for the
    /// strict unmapped object.
    CreateArguments {
        slot: usize,
        mapped: Option<Vec<crux::AtomId>>,
    },
    /// A `break` statement: route through any pending finallys, then jump to
    /// `target` (spec 14.14.4).
    Break {
        target: usize,
    },
    /// A `continue` statement, routed through pending finallys.
    Continue {
        target: usize,
    },
    /// A function-call assignment target in sloppy code: the operands are
    /// evaluated, then PutValue on the call's value reference throws a
    /// ReferenceError (Annex B web-compat, spec 13.15.3 / 6.2.5.6).
    InvalidAssignmentTarget,
    Return,
    Throw,
    // ----- suspension -----
    Yield {
        delegate: bool,
    },
    Await,
    YieldStarBegin,
    YieldStarNext {
        done: usize,
    },
    YieldStarResume {
        loop_top: usize,
        done: usize,
        yield_at: usize,
    },
    // ----- async-generator `yield*` (the inner iterator's results are
    // promises; each step awaits them through the driver) -----
    AsyncYieldStarBegin,
    AsyncYieldStarNext {
        done: usize,
    },
    AsyncYieldStarInspect {
        done: usize,
    },
    AsyncYieldStarResume {
        loop_top: usize,
        done: usize,
        inspect: usize,
    },
    // ----- modules -----
    ImportCall {
        has_options: bool,
        phase: syntax::ast::ImportPhase,
    },
    ImportMeta,
}

impl Trace for Step {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        match self {
            Step::Push(value) => value.trace(visit),
            Step::RegExpLiteral { pattern, flags } => {
                pattern.trace(visit);
                flags.trace(visit);
            }
            Step::PushStr(text) => text.trace(visit),
            Step::ConcatStrConst(text) => text.trace(visit),
            Step::PerIteration { names }
            | Step::EnterIterTdzEnv { names }
            | Step::EnterPerIteration { names } => names.trace(visit),
            Step::DestructureObjKey {
                key: crux::property::PropertyKey::Symbol(symbol),
            } => symbol.trace(visit),
            Step::DestructureObjRest { excluded } => {
                for key in excluded {
                    if let crux::property::PropertyKey::Symbol(symbol) = key {
                        symbol.trace(visit);
                    }
                }
            }
            // The register ops carry literal values (a `LoadConst`/`BinConst`
            // constant, a member store/read's `Const` key or value) that the
            // body must root — an unrooted box is collected under --gc-stress
            // mid-run (the `b['x'] = i` shape's key string read back as
            // garbage).
            Step::RunRegBody { ops } => {
                for op in ops.iter() {
                    trace_leaf_op_heaps(op, visit);
                }
            }
            _ => {}
        }
    }
}

/// Trace a register op's literal heap values (the bodies' `RegOperand::Const`
/// and `LoadConst`/`BinConst` constants — see [`Step::trace`]'s `RunRegBody`
/// arm).
fn trace_leaf_op_heaps(op: &LeafOp, visit: &mut dyn FnMut(GcAny)) {
    let operand = |operand: &RegOperand, visit: &mut dyn FnMut(GcAny)| {
        if let RegOperand::Const(value) = operand {
            value.trace(visit);
        }
    };
    match op {
        LeafOp::LoadConst(value) | LeafOp::BinConst { value, .. } => value.trace(visit),
        LeafOp::StoreMemberName { value, .. } => operand(value, visit),
        LeafOp::StoreMemberComputed { key, value } => {
            operand(key, visit);
            operand(value, visit);
        }
        LeafOp::StoreMemberComputedLocal { key, .. } => operand(key, visit),
        LeafOp::CompoundMemberComputedLocal { key, rhs, .. } => {
            operand(key, visit);
            operand(rhs, visit);
        }
        LeafOp::UpdateMemberComputedLocal { key, .. } => operand(key, visit),
        LeafOp::GetMemberComputed { key, .. } | LeafOp::GetMemberComputedLocal { key, .. } => {
            operand(key, visit);
        }
        _ => {}
    }
}

/// A register instruction for a *leaf* body (Cut 35 slice 1). The step path
/// round-trips the value stack for every expression; these ops target a
/// single accumulator (`Vm.acc`) plus the leaf's frame segment, capture
/// context, and (for per-iteration reads) lexical env directly, with no
/// stack traffic. A register body touches only those four state pieces, so
/// its inline run (`run_leaf_regs`) saves and restores a fraction of the
/// step path's fields. `lower_leaf_ops` emits these only for the
/// left-leaning straight-line shapes the hot leaf bodies produce — anything
/// else stays on the step path.
#[derive(Debug, Clone)]
pub enum LeafOp {
    /// acc = frame[slot]; the `tdz` bit mirrors `Step::LoadLocal`'s
    /// uninitialized-binding check (a `let`/`const` slot before its
    /// initializer).
    LoadReg { slot: usize, tdz: bool },
    /// acc = the leaf's capture-context slot (depth-0 `LoadContextSlot`).
    LoadContext { index: usize },
    /// acc = the leaf's per-iteration slot (depth-0 `LoadPerIteration`).
    LoadPerIter { index: usize },
    /// acc = the accumulator-loop counter (Cut 35 slice 16/21: a body's
    /// `Step::PushAcc` read lowers to a direct read of the dedicated
    /// `Vm::loop_counter` field — no entry push since slice 21).
    LoadCounter,
    /// acc = value.
    LoadConst(Value),
    /// acc = acc op frame[slot], with the number-number inline
    /// `Step::BinaryImm` mirrors.
    BinReg {
        op: BinaryOp,
        slot: usize,
        tdz: bool,
    },
    /// acc = acc op context[slot].
    BinContext { op: BinaryOp, index: usize },
    /// acc = acc op per-iteration[slot].
    BinPerIter { op: BinaryOp, index: usize },
    /// acc = acc op imm (the `Step::BinaryImm` number-number inline).
    BinImm { op: BinaryOp, imm: f64 },
    /// acc = acc op value.
    BinConst { op: BinaryOp, value: Value },
    /// acc = frame[slot] op imm (Cut 35 slice 14: the fused `LoadReg` +
    /// `BinImm` for a frame-slot left operand — one dispatch, skipping the
    /// intermediate accumulator write). The `tdz` bit mirrors `LoadReg`'s
    /// uninitialized-binding check before the read.
    BinImmLocal {
        op: BinaryOp,
        slot: usize,
        tdz: bool,
        imm: f64,
    },
    /// acc = context[index] op frame[slot] (Cut 35 slice 14: the fused
    /// `LoadContext` + `BinReg` for a captured left and a frame-slot right
    /// — one dispatch). Runs the context-transparent env walk like
    /// `LoadContext` and the `tdz` check like `BinReg`.
    BinCtxReg {
        op: BinaryOp,
        index: usize,
        slot: usize,
        tdz: bool,
    },
    /// frame[slot] = acc; the `tdz` bit mirrors `Step::StoreLocal`'s
    /// assignment-to-uninitialized check.
    StoreReg { slot: usize, tdz: bool },
    /// Write `value` onto the object in the accumulator under `name` (the
    /// plain-assign member store, `Step::AssignMemberName` with a plain
    /// `=`): runs `assign_member`, which can trigger a setter — the same
    /// agent-side machinery the step path invokes (the pushed result is
    /// discarded by the frame truncate).
    StoreMemberName {
        name: crux::AtomId,
        value: RegOperand,
    },
    /// Write the accumulator onto the `name` property of the object in
    /// frame `object_slot` (the plain member store of a computed value to
    /// a frame-slot object, and the store half of the register-lowered
    /// binary compound member assign): runs `assign_member` like
    /// `StoreMemberName`, but the object is read from the slot at store
    /// time so the value can stay in the accumulator — the object load
    /// never clobbers it. The lowering emits it only for `tdz=false`
    /// slots, the late-read contract (`BinLeftReg`): nothing in the
    /// straight-line run writes the slot between its original evaluation
    /// and the store.
    StoreMemberNameLocal {
        object_slot: usize,
        name: crux::AtomId,
    },
    /// Write `value` onto the object in the accumulator under the computed
    /// `key` (the plain-assign computed member store, `Step::AssignMemberComputed`
    /// with a plain `=`): the shared `assign_computed_plain` fast-array and
    /// property-key machinery. Neither operand may be `Acc` — the object
    /// load would clobber it.
    StoreMemberComputed { key: RegOperand, value: RegOperand },
    /// Write the accumulator onto the computed `key` property of the object
    /// in frame `object_slot`, resolving the key operand at store time (the
    /// computed counterpart of `StoreMemberNameLocal`: the store of a
    /// computed value with the object in a frame slot — e.g.
    /// `o[k] = o[k] + 1`, where the value was computed after the
    /// reference). The engine's plain computed store defers the target
    /// key's ToPropertyKey to the store, so this re-derivation matches the
    /// step path exactly. The lowering emits it only for a `tdz=false`
    /// frame-slot object and a `Reg`/`Const` key (the late-read contract).
    StoreMemberComputedLocal { object_slot: usize, key: RegOperand },
    /// The register form of a statement-position computed member compound
    /// (`o[k] op= v`): the object is a frame slot and the key a
    /// `Reg`/`Const` operand. Converts the key ONCE inside the op and
    /// shares it between the read and the write (spec 13.15.3 — the step
    /// path's `GetMemberComputedKeep` converts before the read and hands
    /// the converted key to the write; a separate store op re-deriving an
    /// object key would re-run its ToPropertyKey). Reads the old value
    /// (member-cell probed), applies the compound to the RHS value (a
    /// caller-resolved pure operand, stable across the read), and stores
    /// through the same key.
    CompoundMemberComputedLocal {
        object_slot: usize,
        key: RegOperand,
        op: AssignOp,
        rhs: RegOperand,
    },
    /// The register form of a statement-position computed member update
    /// (`o[k]++` / `o[k]--`): the same once-converted-key contract;
    /// applies the ToNumeric update to the read value and stores.
    UpdateMemberComputedLocal {
        object_slot: usize,
        key: RegOperand,
        op: syntax::ast::UpdateOp,
    },
    /// The register form of a statement-position LOCAL update (`l++` /
    /// `++l` / `l--` as a statement — the result is discarded by the
    /// trailing `SetCompletion`): reads the frame slot, applies the
    /// ToNumeric update (`update_value` — number case inline f64 ±1), and
    /// stores the new value, pushing nothing. The `tdz` bit mirrors
    /// `StoreReg`'s assignment-time uninitialized check.
    UpdateReg {
        slot: usize,
        tdz: bool,
        op: syntax::ast::UpdateOp,
    },
    /// acc = the accumulator object's `name` property (the named member
    /// read, `Step::GetMemberName`): the shared `get_member_name` nullish
    /// check + member-cell cache machinery.
    GetMemberName { name: crux::AtomId },
    /// acc = the accumulator object's `key` property (the computed member
    /// read, `Step::GetMemberComputed`): the shared `get_member_computed`
    /// fast-array and property-key machinery. The key may not be `Acc` —
    /// the object load would clobber it.
    GetMemberComputed { key: RegOperand },
    /// acc = the frame slot's `name` property (Cut 35 slice 10: the fused
    /// `LoadLocal` + `GetMemberName` for a frame-slot object — one dispatch
    /// against the slot, skipping the separate load). The `tdz` bit mirrors
    /// `LoadReg`'s uninitialized-binding check before the read.
    GetMemberNameLocal {
        object_slot: usize,
        tdz: bool,
        name: crux::AtomId,
    },
    /// acc = the frame slot's `key` property (the fused `LoadLocal` +
    /// `GetMemberComputed` for a frame-slot object). The key is a direct
    /// operand (`Reg`/`Ctx`/`PerIter`/`Const`) — a computed or spilled key
    /// is rejected by the lowering.
    GetMemberComputedLocal {
        object_slot: usize,
        tdz: bool,
        key: RegOperand,
    },
    /// Push the accumulator onto the value stack (Cut 35 slice 10): a body
    /// with more live values than the single accumulator can hold spills the
    /// accumulator's value, reuses the accumulator, and pops the spilled
    /// value back via `BinAccPop`. The push/pop pairs balance inside the
    /// body; every caller truncates the stack on completion or error.
    PushAcc,
    /// acc = pop() op acc — the spilled left operand combined with the
    /// accumulator right operand (a body that spilled the first operand of
    /// a binary while computing the second).
    BinAccPop { op: BinaryOp },
    /// acc = the accumulator's `++`/`--` update value (the statement-position
    /// member update, `o.x++`): applies `update_value` semantics —
    /// ToNumeric, then ±1 — NOT the binary `+`/`-` (a non-numeric string
    /// would concatenate, not increment). The number case is the inline
    /// f64 ±1; anything else falls to the general `update_value`.
    UpdateAcc { op: syntax::ast::UpdateOp },
    /// acc = frame[slot] op acc — a frame-slot left operand combined with
    /// the accumulator right operand. The slot is read at the combine,
    /// after the accumulator value was computed; that is safe only for
    /// `tdz=false` slots, because a member read's getters cannot reach the
    /// body's own frame slots and the accepted shapes write no slot between
    /// the load and the combine (the lowering rejects `tdz=true` slots).
    BinLeftReg { op: BinaryOp, slot: usize },
    /// acc = frame[slot] op acc; frame[slot] = acc — the fused tail of a
    /// statement-position local compound (`s op= <rhs>` / `s = s op <rhs>`
    /// whose RHS resolved into the accumulator): the `[BinLeftReg,
    /// StoreReg]` pair in one dispatch. The slot value is copied before the
    /// combine (the same late-read discipline as `BinLeftReg` — a coercion
    /// side effect that writes the slot cannot change the left operand),
    /// and the write-back skips the `tdz` check (the lowering only fuses
    /// the `tdz=false` slot shape, where the pair's `StoreReg` had none).
    BinStoreReg { op: BinaryOp, slot: usize },
    /// Complete with `Completion::Return(acc)`.
    ReturnAcc,
}

/// A `try` region's handler: the covered ranges and the catch/finally
/// targets (step indices).
#[derive(Debug, Clone, Copy)]
pub struct Handler {
    pub start: usize,
    pub try_end: usize,
    pub catch: Option<CatchHandler>,
    pub finally: Option<usize>,
}

#[derive(Debug, Clone, Copy)]
pub struct CatchHandler {
    pub start: usize,
    pub end: usize,
}

/// The compile-time binding layout of a fast-path function body (Cut 3):
/// params and `var` bindings get fixed frame slots, so identifier ops emit
/// `LoadLocal`/`StoreLocal` instead of a runtime environment-chain walk. The
/// body compiles with `scope = Some` only when the scope analysis certified
/// it (simple params, no closures/eval/with/`this`/`arguments`/`new.target`/
/// `super`, no lexical block declarations) — otherwise `CompiledBody.scope`
/// is `None` and the body uses the environment machinery unchanged.
#[derive(Debug, Clone)]
pub struct ScopeInfo {
    /// Total frame slots for named bindings. Params occupy slots `0..arity`
    /// (in source order), `var` bindings follow in first-declaration order.
    pub frame_size: usize,
    /// The parameter count: `setup_frame` copies only this many arguments
    /// (extra call arguments are ignored per spec 10.2.11 — copying by
    /// `frame_size` would let them land in `var` slots).
    pub arity: usize,
    /// Binding name → frame slot.
    pub slots: HashMap<crux::AtomId, usize>,
    /// Per-slot: `StoreLocal` must TDZ-check the current value (a `let`/
    /// `const` binding — the slice's params/`var`s are all false).
    pub tdz_store: Vec<bool>,
    /// Cut 3 continuation (closure capture): the body's captured bindings
    /// — read/written by closures the body creates — live in a per-call
    /// declarative environment (the capture context) instead of the frame,
    /// so the closures can reach them after the call returns. The
    /// following four are in lockstep, in context-slot order:
    pub context_names: Vec<crux::AtomId>,
    /// `true` when the context binding starts in the TDZ (a captured
    /// `let`/`const`; a captured `var` starts `undefined`).
    pub context_tdz: Vec<bool>,
    /// `true` for a captured `const` (the context binding is immutable).
    pub context_const: Vec<bool>,
    /// The parameter position a captured param's value comes from (the
    /// context binding is initialized with the call argument), or `None`
    /// for a declared binding.
    pub context_param: Vec<Option<usize>>,
    /// Binding name → context slot (mirrors `context_names`).
    pub context_slots: HashMap<crux::AtomId, usize>,
    /// The frame slot holding the body's `arguments` object (Cut 3
    /// continuation): `Some` when the body references `arguments` — the
    /// certified call fills it at entry. Arrow bodies (lexical `arguments`)
    /// stay on the env path.
    pub arguments_slot: Option<usize>,
    /// Cut 3 continuation (mapped arguments slice): the formal parameter
    /// names of a sloppy simple-param body observing `arguments` — `Some`
    /// when the body gets the mapped arguments object (every param is
    /// captured, so the object's accessors and the body's
    /// `LoadContextSlot`s share the capture-context bindings). `None` for
    /// strict unmapped and non-arguments bodies.
    pub arguments_formals: Option<Vec<crux::AtomId>>,
    /// The frame slot holding the body's `this` value (Cut 3 continuation):
    /// `Some` when a non-arrow body references `this` — the certified call
    /// fills it with the OrdinaryCallBindThis result. Arrow bodies (lexical
    /// `this`) stay on the env path.
    pub this_slot: Option<usize>,
    /// Tasklist 2.3: the capture-context slot holding this body's `this`
    /// value when an arrow created here references `this` — `Some` for a
    /// non-arrow body whose arrows capture its lexical `this` (the certified
    /// entry stores the this slot into the context; the arrows read it
    /// through the context chain). The slot carries the reserved
    /// [`captured_this_atom`] binding.
    pub captured_this: Option<usize>,
    /// Cut 35 slice 23: whether the frame is exactly the parameters, all
    /// present and never assigned — the frame holds only simple params
    /// (`frame_size == arity`, no `this`/`arguments`/`var` slots) and no
    /// statement assigns a param. A register leaf with this flag can read
    /// its args straight from the caller's frame slots at a fused call
    /// site (no argument push, no aliased stack region); `StoreReg` to a
    /// param is impossible, so the aliased region is read-only.
    pub args_alias: bool,
    /// Cut 6 first slice (Annex B): the body's block-level function
    /// declarations, in declaration order. Each binds a block-scoped
    /// binding in `block_slot` (initialized with the instantiated closure
    /// at block entry — 14.2.3, no TDZ) and, when the hoist applies, the
    /// function-scoped var binding in `var_slot` (reset to `undefined` at
    /// block entry; the declaration statement copies the block binding's
    /// current value into it — B.3.3.3). `var_slot` is `None` for a
    /// declaration with no hoist (a strict body, an async/generator
    /// declaration, or a top-level-lexical/parameter/enclosing-lexical
    /// conflict — B.3.3.4): it is block-scoped only. `span` pairs each
    /// entry with its `FunctionDecl` statement during compilation.
    pub annex_b: Vec<AnnexBFunction>,
    /// Cut 6 continuation (Annex B): the body's statement-position function
    /// declarations (`if (x) function f() {}`), which the hoist applies to.
    /// The statement instantiates the closure into the hoisted var
    /// binding's slot — the env path's transient block environment is
    /// unobservable, so no block binding exists. A dead declaration (a
    /// parameter or lexical conflict, or an async/generator form) is not
    /// listed: it compiles to nothing. `span` pairs each entry with its
    /// `FunctionDecl` statement.
    pub statement_fns: Vec<AnnexBStatementFn>,
}

/// An Annex B block-level function declaration in a certified body (Cut 6
/// first slice): see [`ScopeInfo::annex_b`].
#[derive(Debug, Clone)]
pub struct AnnexBFunction {
    pub name: crux::AtomId,
    pub span: crux::Span,
    pub function: Box<syntax::ast::Function>,
    pub block_slot: usize,
    pub var_slot: Option<usize>,
}

/// An Annex B statement-position function declaration in a certified body
/// (Cut 6 continuation): see [`ScopeInfo::statement_fns`].
#[derive(Debug, Clone)]
pub struct AnnexBStatementFn {
    pub name: crux::AtomId,
    pub span: crux::Span,
    pub frame_slot: Option<usize>,
    pub context_slot: Option<usize>,
}

impl ScopeInfo {
    /// The frame slot of a binding, when this body's analysis covers it.
    fn slot_of(&self, name: crux::AtomId) -> Option<usize> {
        self.slots.get(&name).copied()
    }

    /// The capture-context slot of a binding (Cut 3 continuation): the
    /// per-call declarative environment's index, when a closure in the body
    /// captures it.
    fn context_of(&self, name: crux::AtomId) -> Option<usize> {
        self.context_slots.get(&name).copied()
    }

    /// The body's capture context (Cut 3 continuation): a declarative
    /// environment holding the captured bindings (order = `context_names`),
    /// outer = the function's [[Environment]]. Captured params initialize
    /// with the call arguments; captured `var`s start `undefined`; captured
    /// `let`/`const` start in the TDZ. `None` when the body captures
    /// nothing (the certified call keeps the plain closure env).
    pub fn new_body_context(
        &self,
        outer: &EnvRef,
        args: &[Value],
    ) -> Result<Option<EnvRef>, JsError> {
        if self.context_names.is_empty() {
            return Ok(None);
        }
        let env = new_declarative_environment(Some(*outer));
        for (index, name) in self.context_names.iter().enumerate() {
            let text = crux::lookup(*name);
            if self.context_const[index] {
                // Const bindings are created strict unconditionally (spec
                // 16.1.8: CreateImmutableBinding(dn, true) for const
                // declarations), so a sloppy nested closure's write to an
                // enclosing `const` still throws like the env path.
                env.create_immutable_binding(&text, true)?;
            } else {
                env.create_mutable_binding(&text, false)?;
            }
            let value = match self.context_param[index] {
                Some(position) => args.get(position).cloned().unwrap_or(Value::Undefined),
                None if !self.context_tdz[index] => Value::Undefined,
                None => continue,
            };
            env.initialize_binding(&text, value)?;
        }
        Ok(Some(env))
    }
}

/// A compiled resumable function body.
#[derive(Debug, Clone)]
pub struct CompiledBody {
    pub steps: Vec<Step>,
    pub handlers: Vec<Handler>,
    pub strict: bool,
    /// The fast-path frame layout, when the scope analysis certified the
    /// body (see [`ScopeInfo`]). `None` = the environment-machinery path.
    pub scope: Option<ScopeInfo>,
    /// Whether the body's `lexical_env` never changes during its run: a
    /// certified body's blocks contribute no env (every lexical declaration
    /// is a frame slot), its for-of/for-in heads bind direct slots/contexts
    /// (a captured lexical head opens the per-iteration env machinery, so
    /// those bodies are not env-constant), and it has no
    /// `with`/`try`/`switch`/`using`, so the dispatch loop's per-step
    /// context-env sync is a no-op and can be skipped.
    pub env_constant: bool,
    /// Cut 25: whether the certified body is a *leaf* — no calls, no
    /// closure creation, no reference/environment/iterator machinery, no
    /// sloppy mapped `arguments` — so a call to it can run in place on the
    /// CALLER's Vm (no execution-context push, no pool round-trip, no frame
    /// re-alloc): `do_call_fast` inlines it when the caller's shared stacks
    /// are empty. A leaf cannot recurse (it contains no calls), so the
    /// flat save/restore of the few fields it touches is safe. See
    /// `docs/perf.md` Cut 25.
    pub leaf: bool,
    /// Cut 28: whether the leaf reads captured per-iteration heads — its
    /// steps contain `LoadPerIteration`/`StorePerIteration`/
    /// `UpdatePerIteration`, which resolve against the leaf's own
    /// `lexical_env`. The inline run sets `lexical_env` to the leaf's env
    /// for the duration only when this is true (the common leaf never
    /// touches the caller's env).
    pub leaf_needs_env: bool,
    /// Cut 30: whether the leaf reads an environment at all — any
    /// context-slot step (`LoadContextSlot` etc. resolve `body_context`)
    /// or per-iteration step (`leaf_needs_env`). A leaf with neither never
    /// touches `body_context`/`lexical_env`, so the inline run skips the
    /// body-context creation and the save/restore of both fields.
    pub leaf_uses_env: bool,
    /// Cut 35 slice 1: the register form of this leaf body, when every step
    /// lowered to a [`LeafOp`] (`None` = run the step path). A register body
    /// touches only `acc`, the frame segment, and the env fields, so its
    /// inline run is both faster to dispatch and cheaper to save/restore.
    pub leaf_ops: Option<Box<[LeafOp]>>,
    /// The certified top-level fast path (script-level bindings): the
    /// declared `var`/function names a script reads and writes directly on
    /// the global object, skipping the env-chain walk. `None` = the
    /// environment-machinery path (modules, eval bodies, uncertified
    /// scripts). Keys are `String` (not `JsString`) so the set stays free of
    /// interior-mutability lints.
    pub script_globals: Option<HashSet<String>>,
    /// The JIT's compiled-info pointer for this body: `0` = not yet looked
    /// up, `1` = known non-compilable, otherwise a `*const
    /// crate::jit::JitCompiledInfo` owned by the installed jit cache. The
    /// cache clears it when the entry is evicted (before the compiled code
    /// is freed), so a set pointer is always valid; the JIT's call paths
    /// set it on the first lookup so a hot call skips the cache
    /// consultation entirely.
    pub jit_info: std::cell::Cell<usize>,
    /// Cut 69: the number of JIT consultations this body received while
    /// below `crate::jit::JIT_COMPILE_THRESHOLD` (saturating). A
    /// straight-line body (`has_loop` false) is run interpreted until the
    /// count reaches the threshold, then compiles on the next consult; a
    /// loop body compiles on the first consult. The count is shared across
    /// every `Rc` clone of the body (the per-site closures of one body), so
    /// the consult counts aggregate.
    pub jit_calls: std::cell::Cell<u32>,
    /// Cut 69: whether the body contains a loop (see [`body_has_loop`]).
    /// Loop bodies compile on first JIT use — they run once with many
    /// internal iterations, so a pure call-count threshold would never
    /// promote them.
    pub has_loop: bool,
    /// M10: whether the body contains a `Step::CallApply` site. The JIT's
    /// per-run context snapshots the realm's `apply`/`call` intrinsic bits
    /// only for such bodies (the snapshot costs a realm + intrinsics read
    /// per run, which every other compiled run would otherwise pay).
    pub has_call_apply: bool,
}

impl Trace for CompiledBody {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.steps.trace(visit);
    }
}

/// A runtime `try` frame.
#[derive(Debug)]
pub struct TryFrame {
    pub handler: usize,
    pub saved_env: EnvRef,
    pub env_depth: usize,
}

impl Trace for TryFrame {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.saved_env.trace(visit);
    }
}

/// A pending control transfer a `finally` finishes after it runs.
#[derive(Debug)]
pub enum PendingControl {
    Normal {
        after: usize,
        env: EnvRef,
        depth: usize,
    },
    Break {
        target: usize,
        env: EnvRef,
        depth: usize,
    },
    Continue {
        target: usize,
        env: EnvRef,
        depth: usize,
    },
    Return {
        value: Value,
        env: EnvRef,
        depth: usize,
    },
    Throw {
        value: Value,
        env: EnvRef,
        depth: usize,
    },
}

impl Trace for PendingControl {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        match self {
            PendingControl::Return { value, env, .. }
            | PendingControl::Throw { value, env, .. } => {
                value.trace(visit);
                env.trace(visit);
            }
            PendingControl::Normal { env, .. }
            | PendingControl::Break { env, .. }
            | PendingControl::Continue { env, .. } => env.trace(visit),
        }
    }
}

/// The `(env, depth)` a pending control restores to when its finally
/// completes (all variants carry the same pair).
pub fn pending_env_depth(pending: &PendingControl) -> (EnvRef, usize) {
    match pending {
        PendingControl::Normal { env, depth, .. }
        | PendingControl::Break { env, depth, .. }
        | PendingControl::Continue { env, depth, .. }
        | PendingControl::Return { env, depth, .. }
        | PendingControl::Throw { env, depth, .. } => (*env, *depth),
    }
}

/// How the VM suspended, for the driver (generator/async machinery).
#[derive(Debug, Clone)]
pub enum Suspension {
    Yield {
        value: Value,
        delegate: bool,
    },
    Await(Value),
    /// The `yield*` delegation has no `return` method: the received value is
    /// awaited and the body is resumed with a return completion of it (spec
    /// 15.5.5 return case step b.ii). The driver resumes with
    /// `Resume::Return` instead of `Resume::Normal`.
    AwaitReturn(Value),
}

/// What a resume hands to the VM.
#[derive(Debug, Clone)]
pub enum Resume {
    Normal(Value),
    Throw(Value),
    Return(Value),
}

/// An abrupt resume delivered to a `yield*` delegation.
#[derive(Debug, Clone)]
pub enum ResumeAbrupt {
    Throw(Value),
    Return(Value),
}

impl Trace for ResumeAbrupt {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        match self {
            ResumeAbrupt::Throw(value) | ResumeAbrupt::Return(value) => value.trace(visit),
        }
    }
}

/// The result of a VM run.
#[derive(Debug)]
pub enum VmOutcome {
    Completed(Completion),
    Suspended(Suspension),
    /// A proper tail call replaced the running body: the handler already set
    /// up the callee's context and frame on this Vm, and `run_inner`'s
    /// driver continues with the carried body.
    TailCall(std::rc::Rc<CompiledBody>),
}

/// The body a [`Vm::run_inner`] driver is currently executing: a proper tail
/// call replaces it, and the enum owns each replacement's `Rc` so the
/// per-iteration reborrow stays valid.
enum CurrentBody<'a> {
    Borrowed(&'a CompiledBody),
    Owned(std::rc::Rc<CompiledBody>),
}

impl<'a> CurrentBody<'a> {
    fn get(&self) -> &CompiledBody {
        match self {
            CurrentBody::Borrowed(body) => body,
            CurrentBody::Owned(rc) => rc,
        }
    }
}

/// A tail call's outcome: the current body completed (a leaf/native callee)
/// or the frame was replaced and the driver must continue with the new body.
enum TailOutcome {
    Returned(VmOutcome),
    Replaced(std::rc::Rc<CompiledBody>),
}

/// A property key for member steps.
#[derive(Debug, Clone)]
pub enum PropertyKeyName {
    Name(crux::AtomId),
    Key(PropertyKey),
}

/// The control-transfer payload for the try/finally machinery.
#[derive(Debug, Clone)]
pub enum Ctl {
    Normal { after: usize },
    Break { target: usize },
    Continue { target: usize },
    Return { value: Value },
    Throw { value: Value },
}

#[derive(Debug)]
pub enum CtlResult {
    Continue,
    Done(VmOutcome),
}

/// A for-in enumeration in progress: the base object, the
/// (prototype-level, key) pairs, and the next index.
pub(crate) type ForInState = (Handle<crux::object::JsObject>, Vec<(usize, Value)>, usize);

/// Frame slots for small layouts live in a fixed inline array so a fast
/// call allocates nothing (the bench's simple-param functions are ≤ 8
/// slots); larger layouts fall back to the heap.
const INLINE_FRAME: usize = 8;
/// The direct-mapped member-access cell count (P3): a power of two so the
/// cache index is a mask. `pub` so the jit crate's inline member-cell probe
/// indexes the same table.
pub const MEMBER_CELLS: usize = 16;

/// The write-side store-cell table size (L1a warm-store cell): a SEPARATE,
/// larger direct-mapped table than the read cells, because a store-cell
/// miss falls back to the full [[Set]] (~140ns) while a read-cell miss
/// falls back to the map live-field path (~+1ns). The 16-entry read tables
/// are fine at their working sets (probe 2026-09-04: 64 distinct same-map
/// objects read at ~4.2ns/op, +0.7ns over warm); a 16-entry write table
/// aliases across any >16-object store loop and every store pays the full
/// [[Set]] (probe: 64-object cycling stores ~140ns/store vs ~20ns warm).
/// Mirrors the GLOBAL_CELLS 32->256 bump (Cut 35 slice 5). The JIT never
/// reads the write cells, so the size is interpreter-only. Power of two so
/// the index is a mask.
pub(crate) const MEMBER_WRITE_CELLS: usize = 4096;

/// Part B, B5.4: the cached constructor boilerplate map — (function id,
/// prototype id, function-object generation) → the final shape the body's
/// `this.*` stores transition to. Re-validated against the function object's
/// generation (a `prototype` redefine/delete bumps it) and the prototype's
/// identity, so a stale entry misses and rebuilds. (The constructor's
/// `prototype` VALUE itself is served by the shared (function id,
/// "prototype") member value cell when warm — the oracle the L1c record-
/// discipline work keeps value-write-exact — not by a generation-keyed cell,
/// which a value write to `prototype` would leave stale.)
pub struct ConstructMapCell {
    pub id: u64,
    pub proto_id: u64,
    pub generation: u32,
    pub map: crux::Handle<crux::Map>,
}

impl Trace for ConstructMapCell {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.map.trace(visit);
    }
}

/// Direct-mapped slots for the constructor caches ([`ConstructMapCell`] and
/// the property-pattern pre-warm; a power of two so the index is a mask).
pub(crate) const CONSTRUCT_PROTO_CELLS: usize = 256;
/// Direct-mapped slots for the constructor property-pattern cache (Cut 35
/// slice 30): function id → the `this.*` property names its body assigns.
/// A power of two so the cache index is a mask; a collision evicts (the
/// pre-warm is an optimization — a miss just means the store path walks
/// the chain on its own).
pub(crate) const CONSTRUCT_PATTERN_CELLS: usize = 256;

/// A cached constructor property pattern: the count of property names and
/// up to four `AtomId`s (the fixed array keeps the cache entry tiny).
pub(crate) type ConstructPatternCell = (u8, [crux::AtomId; 4]);

/// The direct-mapped cache index for a function's property patterns.
pub(crate) fn construct_pattern_index(function_id: u64) -> usize {
    (function_id.wrapping_mul(0x9E37_79B9_7F4A_7C15) as usize) & (CONSTRUCT_PATTERN_CELLS - 1)
}

/// Record a function body's collected `this.*` property writes (Cut 35
/// slice 30) for `construct_this_object`'s store-cache pre-warm.
pub(crate) fn store_construct_patterns(
    agent: &mut Agent,
    function_id: u64,
    this_writes: (usize, [crux::AtomId; 4]),
) {
    let index = construct_pattern_index(function_id);
    agent.construct_property_patterns[index] = Some((this_writes.0 as u8, this_writes.1));
}
/// The read-side array-element value cache entry (Cut 35 slice 13): the
/// cached value of `array[index]` at the array's generation — a generation
/// match means no own-property change since the read (slice 11 bumps every
/// mutation, including in-place element writes), so the value is current
/// without re-borrowing the property vector.
pub(crate) struct ArrayElementValueCell {
    pub id: u64,
    pub index: u64,
    pub generation: u32,
    pub value: Value,
}

impl Trace for ArrayElementValueCell {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.value.trace(visit);
    }
}

/// The array-length cache entry (Cut 35 slice 13): the cached length of a
/// plain Array at its generation — the for-of fast path re-reads the length
/// every step, and a generation match skips the property-vector borrow and
/// the number conversion.
pub(crate) struct ArrayLengthCell {
    pub id: u64,
    pub generation: u32,
    pub length: u64,
}
/// The write-side chain-cache entry (Cut 22): (prototype id, key atom,
/// walked-chain length, per-link generations).
pub(crate) type MemberStoreCell = (u64, crux::AtomId, u32, [u32; 4]);
/// The read-side value-cache entry (Cut 35 slice 11): the cached value of
/// `object.name` at the object's generation — a generation match means no
/// own-property change since the read (every mutation path bumps,
/// including `set_key`'s in-place value update), so the value is current
/// without re-borrowing the property vector. `#[repr(C)]` with all-scalar
/// fields so the compiled `GetMemberName` probe reads them at fixed
/// offsets (`offset_of!`).
#[repr(C)]
#[derive(Clone)]
pub struct MemberValueCell {
    pub id: u64,
    pub name: crux::AtomId,
    pub generation: u32,
    pub value: Value,
}

impl MemberValueCell {
    /// An empty cell: `id` is an impossible object id, so the compiled
    /// probe's validation never matches it and the read falls to the full
    /// Get.
    pub(crate) const fn empty() -> Self {
        Self {
            id: u64::MAX,
            name: 0,
            generation: 0,
            value: Value::Undefined,
        }
    }
}

/// `MemberWriteCell::field` value when no inline-field mirror is pinned:
/// the object was dictionary-mode or its map did not describe the key when
/// the cell was recorded (a vector-only property).
pub(crate) const MEMBER_WRITE_FIELD_NONE: u8 = u8::MAX;

/// The write-side value-cache entry (L1a warm-store fast path): (id,
/// name, generation, slot) — "at this generation, `name` is an own
/// writable data property of `id` at property-vector `slot`". A member
/// write whose (id, name, generation) match stores directly at the slot
/// — no [[Set]] re-derivation. Sound because an own writable data
/// property shadows the entire chain (spec 7.3.3 step 3 — the chain is
/// consulted only when the own property is absent), so no setter
/// tracking is needed, and the slice-11 discipline (every own-property
/// mutation bumps the generation, including in-place `set_key`) makes a
/// generation match pin the recorded slot's content.
///
/// L1c: the cell also records the inline-field mirror of the property —
/// the (map id, in-object offset) assigned by the object's map (see
/// `JsObject::map_store_field`) — so the warm write mirrors the value
/// into `in_fields` at the pinned offset without re-scanning the map's
/// descriptors. The same generation gate pins the map (every structural
/// change — define, delete, accessor conversion, map transition — bumps),
/// and a map id pins its descriptor layout (maps are immutable after
/// creation). `map_id` is 0 and `field` is `MEMBER_WRITE_FIELD_NONE`
/// when no mirror is pinned.
#[derive(Clone, Copy)]
pub(crate) struct MemberWriteCell {
    pub id: u64,
    pub name: crux::AtomId,
    pub generation: u32,
    pub slot: usize,
    /// The map id whose descriptors assign `field`, when a mirror is
    /// pinned (see `field`).
    pub map_id: u64,
    /// The in-object field offset of the mirrored property, or
    /// `MEMBER_WRITE_FIELD_NONE` when no mirror is pinned.
    pub field: u8,
}

/// The prototype-chain read cache (2026-09-01): the RESOLUTION of
/// `(receiver id, name)` found on the prototype chain — re-validated by
/// the receiver's generation (an own property appearing on the receiver
/// bumps it) and each cached link's (id, generation) (a link's own
/// mutation or a proto replacement bumps a generation). Deeper links
/// than the found one cannot shadow its own data property, so the probe
/// never walks past the cached links. `links[0]` is the receiver's
/// prototype; `link_count` is 1 when the property is on the first link,
/// 2 when on the second. The VALUE is deliberately NOT cached: a chain
/// hit re-reads the found property live (through the found link's member
/// value cell when warm, else the recorded vector `slot`), so a value
/// write to the found link's own property — a warm store that must not
/// bump the link's generation under the L1c record discipline — is always
/// observed (the slot is stable while the link's generation is unchanged,
/// which the walk validates). All-scalar; no trace edges.
#[derive(Clone)]
pub struct MemberChainCell {
    pub id: u64,
    pub name: crux::AtomId,
    pub generation: u32,
    pub slot: usize,
    pub link_count: u8,
    pub links: [(u64, u32); 2],
}

/// Part B, B5.2: map-keyed member cache entry — maps (map_id, name) to a
/// field offset for the in_fields fast path. The map's shape is immutable,
/// so a map_id + name match pins the descriptor (and its offset) exactly.
#[derive(Clone, Copy)]
pub(crate) struct MemberMapCell {
    pub map_id: u64,
    pub name: crux::AtomId,
    pub slot: usize,
}

impl Trace for MemberValueCell {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.value.trace(visit);
    }
}

/// The direct-mapped global-var cell count: a power of two so the cache
/// index is a mask. Bigger than the member cells because a script's
/// top-level names (`n`, `i`, `s`, ...) all probe this table; a collision
/// evicts and the reference path re-resolves. `pub` so the jit crate's
/// inline global fast path can index the same table.
pub const GLOBAL_CELLS: usize = 256;

/// The direct-mapped leaf-inline cache (Cut 34): the per-function data
/// `do_call_fast` needs to run a leaf inline — the compiled ir, strictness,
/// and (for a leaf that reads an environment) the closure env — keyed by
/// function id. Function ids are never reused, so a hit needs no generation
/// check. Boxed so the Agent's hot-field cache footprint stays small (the
/// Cut 27 lesson: an inline copy regressed the leaf path).
pub(crate) const LEAF_CACHE: usize = 16;

/// A cached leaf-inline record: everything the inline call path reads off
/// the `ecma_functions` record, captured so the per-call HashMap lookup is
/// skipped on a hit.
#[derive(Clone)]
pub(crate) struct LeafEntry {
    pub ir: std::rc::Rc<CompiledBody>,
    pub strict: bool,
    /// The function's [[Environment]], kept only when the leaf reads an
    /// environment (`CompiledBody::leaf_uses_env`).
    pub environment: Option<EnvRef>,
    /// The certified base-constructor leaf verdict (Cut 35 slice 15): the
    /// `Construct` step shares the leaf cache, so a construct-inlineable
    /// callee skips the `ecma_functions` HashMap lookup it paid per
    /// construct.
    pub construct_inline: bool,
}

impl Trace for LeafEntry {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        // `ir` is native `Rc` data — `Step`'s constants (flat strings,
        // bigints, primitives) hold no GC edges — so only the env is traced.
        self.environment.trace(visit);
    }
}

/// The global call-site leaf cache entry (Cut 35 slice 12): a resolved
/// [`LeafEntry`] for a stable global callee, valid while the global object
/// keeps its identity and generation (every global-object mutation bumps,
/// slice 11). The compiler's never-assigned + no-call-like-args guard makes
/// the callee stable for the script's duration, so the per-call
/// cell-load/kind/realms/lookup validation chain is skipped on a hit.
pub(crate) struct GlobalLeafCell {
    pub name: crux::AtomId,
    pub global_id: u64,
    pub global_generation: u32,
    pub entry: LeafEntry,
}

impl Trace for GlobalLeafCell {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.entry.trace(visit);
    }
}

/// The slot-callee leaf cache entry (Cut 35 slice 12): a resolved
/// [`LeafEntry`] for a frame-slot callee (a certified-value var holding a
/// certified closure). The slot's current value is validated by its heap
/// payload — the same closure keeps the same allocation — and the held
/// `callee` keeps that closure alive, so a payload match means the cached
/// entry (ir + closure env) is exactly the callee's. The slot index is the
/// direct-mapped key; a different body's same-index slot misses on the
/// payload.
pub(crate) struct SlotLeafCell {
    pub payload: u64,
    /// Held for its drop side effect: the strong ref keeps the callee's
    /// closure allocation alive, so its payload can never be reused while
    /// the cache entry exists (the payload compare is then exact). Never
    /// read.
    #[allow(dead_code)]
    pub callee: Value,
    pub entry: LeafEntry,
}

impl Trace for SlotLeafCell {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.callee.trace(visit);
        self.entry.trace(visit);
    }
}

/// The direct-mapped slot-callee leaf cache size (Cut 35 slice 12): a
/// power of two so the index is a mask.
pub(crate) const SLOT_LEAF_CELLS: usize = 64;

/// The leaf-inline cache site (Cut 35 slice 12): which per-call-site
/// cache, if any, the resolved leaf entry is written to on the first
/// call. `Global` (a stable global callee, validated by the global
/// object's generation), `Slot` (a frame-slot callee, validated by its
/// heap payload), or none (`CallFast`'s `[this, callee]` stack shape).
pub(crate) enum LeafCacheSite {
    Global { name: crux::AtomId },
    Slot { index: usize, callee: Value },
    None,
}

/// The fast-path frame storage: an inline buffer for small layouts, a `Vec`
/// otherwise.
#[derive(Clone, Debug)]
pub(crate) enum Frame {
    Inline([Value; INLINE_FRAME]),
    Heap(Vec<Value>),
}

impl Trace for Frame {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        match self {
            Frame::Inline(buf) => {
                for value in buf {
                    value.trace(visit);
                }
            }
            Frame::Heap(vec) => vec.trace(visit),
        }
    }
}

impl Frame {
    #[inline]
    fn get(&self, slot: usize) -> &Value {
        match self {
            Frame::Inline(buf) => &buf[slot],
            Frame::Heap(vec) => &vec[slot],
        }
    }

    #[inline]
    pub(crate) fn get_mut(&mut self, slot: usize) -> &mut Value {
        match self {
            Frame::Inline(buf) => &mut buf[slot],
            Frame::Heap(vec) => &mut vec[slot],
        }
    }
}

/// Build a certified body's frame: params in slots `0..arity` (source
/// order), `var`s undefined, `let`/`const` slots in the TDZ. Shared by
/// `Vm::setup_frame` and the Cut 25 leaf-inline (which swaps it in for the
/// duration of the leaf's run).
fn leaf_frame(scope: &ScopeInfo, args: &[Value]) -> Frame {
    if scope.frame_size <= INLINE_FRAME {
        let mut buf = std::array::from_fn(|index| {
            // A `let`/`const` slot starts in the TDZ (`LoadLocal`/`StoreLocal`
            // check the marker); params and `var`s start `undefined`.
            if scope.tdz_store.get(index).copied().unwrap_or(false) {
                Value::uninitialized()
            } else {
                Value::Undefined
            }
        });
        for (index, arg) in args.iter().take(scope.arity).enumerate() {
            buf[index] = *arg;
        }
        Frame::Inline(buf)
    } else {
        let mut slots: Vec<Value> = (0..scope.frame_size)
            .map(|index| {
                if scope.tdz_store[index] {
                    Value::uninitialized()
                } else {
                    Value::Undefined
                }
            })
            .collect();
        for (index, arg) in args.iter().take(scope.arity).enumerate() {
            slots[index] = *arg;
        }
        Frame::Heap(slots)
    }
}

/// An active for-of loop's iterator state: the generic iterator protocol,
/// or the fast index path over a plain Array with the stock `@@iterator`
/// (see [`crate::expr::for_of_begin`]). The fast path re-reads the array's
/// `length` and each element on every step — the stock Array iterator's
/// observable behavior (spec %ArrayIteratorPrototype%.next steps 5-7) —
/// without the iterator object, the per-element `next()` call, or the
/// result-object allocation.
#[derive(Debug)]
pub enum ForOfEntry {
    Generic(crate::expr::IteratorRecord),
    Fast { array: Value, index: usize },
}

/// Where the for-of protocol step's element lands (Cut 21): the value
/// stack (the general shape, followed by a separate bind step) or a frame
/// slot directly (the fused bind).
pub(crate) enum ForOfNextTarget {
    Stack,
    Slot(usize),
}

/// The outcome of advancing an active for-of entry: the next element, or
/// exhaustion (the entry and its boundary were popped).
pub(crate) enum ForOfAdvance {
    Element(Value),
    Done,
}

/// The scope-environment stack: a small inline buffer for the common
/// shallow nesting (a body env plus a couple of block/try envs), falling
/// back to a heap `Vec` for deeply nested scopes. The per-call `Vm`
/// previously allocated a one-element `Vec` here — a heap round-trip on
/// every call — so the base env now lands in the inline buffer instead.
#[derive(Debug)]
pub(crate) struct EnvStack {
    inline: [Option<EnvRef>; ENV_INLINE],
    heap: Vec<EnvRef>,
    /// Cut 68: `pub(crate)` so the JIT's eligibility-state offsets can read it.
    pub(crate) len: usize,
}

impl Trace for EnvStack {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        for env in &self.inline {
            env.trace(visit);
        }
        self.heap.trace(visit);
    }
}

/// The inline capacity of [`EnvStack`] (the Vm is re-created per call, so
/// this is a direct size/alloc tradeoff; deep scopes spill to the heap).
const ENV_INLINE: usize = 8;

impl EnvStack {
    /// A stack holding only the body environment.
    fn with_base(env: EnvRef) -> Self {
        let mut inline = std::array::from_fn(|_| None);
        inline[0] = Some(env);
        Self {
            inline,
            heap: Vec::new(),
            len: 1,
        }
    }

    /// Re-point the stack at a fresh base, dropping the previous run's
    /// entries (the Vm pool reuses the stack across calls).
    fn reset(&mut self, base: EnvRef) {
        for slot in &mut self.inline {
            *slot = None;
        }
        self.inline[0] = Some(base);
        self.heap.clear();
        self.len = 1;
    }

    #[inline]
    pub(crate) fn push(&mut self, env: EnvRef) {
        if self.len < ENV_INLINE {
            self.inline[self.len] = Some(env);
        } else {
            self.heap.push(env);
        }
        self.len += 1;
    }

    #[inline]
    pub(crate) fn pop(&mut self) -> Option<EnvRef> {
        if self.len == 0 {
            return None;
        }
        self.len -= 1;
        if self.len < ENV_INLINE {
            self.inline[self.len].take()
        } else {
            self.heap.pop()
        }
    }

    #[inline]
    pub(crate) fn len(&self) -> usize {
        self.len
    }

    /// Truncate to `depth` entries from the bottom.
    fn truncate(&mut self, depth: usize) {
        if depth >= self.len {
            return;
        }
        if depth >= ENV_INLINE {
            self.heap.truncate(depth - ENV_INLINE);
        } else {
            self.heap.clear();
            for slot in &mut self.inline[depth..ENV_INLINE] {
                *slot = None;
            }
        }
        self.len = depth;
    }

    /// The entry at `index` from the bottom.
    fn get(&self, index: usize) -> Option<&EnvRef> {
        if index < ENV_INLINE {
            self.inline[index].as_ref()
        } else {
            self.heap.get(index - ENV_INLINE)
        }
    }

    /// Drain every env's disposable resources, innermost first, into
    /// `resources` (spec 9.4.3: an error escaping the body disposes the
    /// active scopes' `using` resources in reverse registration order).
    fn drain_disposables(&self, resources: &mut Vec<crate::env::DisposableResource>) {
        for index in (0..self.len).rev() {
            if let Some(env) = self.get(index) {
                resources.extend(env.drain_disposable_resources().into_iter().rev());
            }
        }
    }
}

/// The binding a fused canonical loop reads, tests, and increments: a frame
/// slot, a declared top-level var, or (Cut 17) the VM accumulator — the
/// counter of a canonical loop whose body only reads it or assigns it in
/// statement position lives in `Vm::acc` for the loop's duration, so the
/// head and body never round-trip the frame/global per iteration (the V8
/// register-counter model).
#[derive(Debug, Clone, Copy)]
pub enum FastLoopVar {
    Slot(usize),
    Global(crux::AtomId),
    /// The dedicated `Vm::loop_counter` field (Cut 17/35 slice 21): the
    /// accumulator-path head's counter lives here, never in the frame or
    /// the register accumulator. The field is a raw `f64` (Cut 35 slice
    /// 22), so the acc-path gates must admit only Number inits and stores.
    Counter,
}

/// The right operand of a fused relational loop test (the `LIMIT` of
/// `for (i = 0; i < LIMIT; i++)`): a literal (the original `imm` shape), a
/// frame slot, or a declared global. The general path evaluates the limit
/// every iteration, so the fused head re-reads the binding each pass.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum RelLimit {
    Imm(f64),
    Slot(usize),
    Global(crux::AtomId),
}

struct FastLoopShape {
    var: FastLoopVar,
    loc: BindingLoc,
    name: crux::AtomId,
    op: BinaryOp,
    limit: RelLimit,
    inc: UpdateOp,
}

// The stack of Vms currently running bodies (GC-2): the active Vm is
// not in the pool, and its heap-buffered value stacks are invisible to
// the conservative native-stack scan, so a mid-execution collection
// must trace them precisely. Each entry also carries the compiled body
// the Vm is running — its steps embed literal `Value`s (script bodies are
// per-evaluation `Rc<CompiledBody>` locals, not `EcmaFunction.ir`).
// Nested calls stack multiple runs.
struct ActiveRun {
    vm: *const Vm,
    body: *const CompiledBody,
    /// A JIT body's private frame/working buffer (heap values only it
    /// references), as `(ptr as usize, len)` — `None` for an interpreter
    /// run. A helper-triggered collection during the JIT body must trace it
    /// like the Vm's own stacks.
    jit_buffer: Option<(usize, usize)>,
}
thread_local! {
    static ACTIVE_RUNS: std::cell::RefCell<Vec<ActiveRun>> =
        const { std::cell::RefCell::new(Vec::new()) };
    /// A body is being compiled: the compiler's `steps` Vec is the only
    /// reference to the literal `Value`s it embeds, and it is a heap buffer
    /// the stack scan cannot see — a mid-compile stress collection would
    /// sweep them. The compiled body becomes a root once the run starts.
    static COMPILING: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    /// GC-2: a window where a local `Vec<Value>` holds unrooted handles
    /// across a collection (the tail-call argument copy — the instantiation
    /// that follows allocates). Collections are suppressed (retain
    /// everything) for the window's duration.
    static SUPPRESS_STRESS: std::cell::Cell<u32> = const { std::cell::Cell::new(0) };
}

/// Whether a body is currently being compiled (GC-2): the `--gc-stress`
/// collector skips allocations inside the compile so the constants a
/// half-built body holds are not swept.
pub(crate) fn is_compiling() -> bool {
    COMPILING.with(|compiling| compiling.get())
        || SUPPRESS_STRESS.with(|suppress| suppress.get() > 0)
}

/// RAII: suppress `--gc-stress` collections for the duration of a window
/// where unrooted handles sit in local heap buffers (the tail-call
/// argument Vec). Nests with the compile guard via the counter.
pub(crate) struct StressSuppress;
impl StressSuppress {
    pub(crate) fn new() -> Self {
        SUPPRESS_STRESS.with(|suppress| suppress.set(suppress.get() + 1));
        StressSuppress
    }
}
impl Drop for StressSuppress {
    fn drop(&mut self) {
        SUPPRESS_STRESS.with(|suppress| suppress.set(suppress.get() - 1));
    }
}

/// RAII: suppress `--gc-stress` collections for the duration of a compile.
struct CompilingGuard;
impl CompilingGuard {
    fn new() -> Self {
        COMPILING.with(|compiling| compiling.set(true));
        CompilingGuard
    }
}
impl Drop for CompilingGuard {
    fn drop(&mut self) {
        COMPILING.with(|compiling| compiling.set(false));
    }
}

/// Trace every Vm currently running a body and its compiled body (GC-2
/// root): the active Vms' heap buffers hold live values the stack scan
/// cannot see, and the compiled steps hold the body's literal `Value`s. A
/// JIT run's private working area is traced alongside (see [`with_jit_run`]).
pub(crate) fn trace_active_vms(visit: &mut dyn FnMut(crux::heap::GcAny)) {
    ACTIVE_RUNS.with(|stack| {
        for run in &*stack.borrow() {
            // SAFETY: an entry is pushed for the duration of a `run_inner`
            // or JIT call and popped before the Vm is returned to the pool
            // (the owned body is dropped with `current` at the same
            // return), so both are live and immobile while on the stack.
            unsafe {
                (&*run.vm).trace(visit);
                (&*run.body).trace(visit);
                if let Some((ptr, len)) = run.jit_buffer {
                    for value in std::slice::from_raw_parts(ptr as *const Value, len) {
                        value.trace(visit);
                    }
                }
            }
        }
    });
}

/// Root a JIT body running on `vm` (covering the vm's own state — its
/// frame, stack, and any nested leaf jit roots — plus the private working
/// area) for the duration of `f`: a helper the compiled code calls can
/// allocate and trigger a collection, and a heap value only those buffers
/// reference must survive until the JIT stores or returns it.
pub(crate) fn with_jit_run<T>(
    vm: &Vm,
    body: &CompiledBody,
    work: &[Value],
    f: impl FnOnce() -> T,
) -> T {
    ACTIVE_RUNS.with(|stack| {
        stack.borrow_mut().push(ActiveRun {
            vm: vm as *const Vm,
            body: body as *const CompiledBody,
            jit_buffer: Some((work.as_ptr() as usize, work.len())),
        });
    });
    let result = f();
    ACTIVE_RUNS.with(|stack| {
        stack.borrow_mut().pop();
    });
    result
}

/// Root a pooled Vm running a leaf body for the duration of `f` (GC-2):
/// the builtins' leaf fast path (`apply`/`call`) runs a certified leaf on
/// a Vm taken from the pool — a buffer its `stack` holds that the precise
/// tracer cannot see — so a budget collection inside the body must trace
/// it exactly like `run_inner` would. `vm`/`body` are raw pointers (the
/// caller owns both for the call; `body` is the leaf's `Rc<CompiledBody>`).
pub(crate) fn with_leaf_run<T>(vm: *mut Vm, body: *const CompiledBody, f: impl FnOnce() -> T) -> T {
    ACTIVE_RUNS.with(|stack| {
        stack.borrow_mut().push(ActiveRun {
            vm,
            body,
            jit_buffer: None,
        });
    });
    let result = f();
    ACTIVE_RUNS.with(|stack| {
        stack.borrow_mut().pop();
    });
    result
}

/// The resumable VM state. Saved across suspension by the driver.
#[derive(Debug)]
pub struct Vm {
    pub ip: usize,
    pub stack: Vec<Value>,
    /// The JIT runs' private buffers as `(ptr as usize, len)`, pushed for
    /// the duration of each leaf-path JIT call on this Vm and traced with
    /// it (the leaf path runs on the caller's Vm, which the active-run
    /// tracer already covers — no thread-local registration needed). Empty
    /// outside a JIT call.
    pub(crate) jit_roots: Vec<(usize, usize)>,
    /// The fast-path frame (Cut 3): named-binding slots for the active body,
    /// sized by `ScopeInfo::frame_size`. Empty on the environment path.
    pub(crate) frame: Frame,
    /// Cut 34: while a leaf runs inline on this Vm, its frame is a flat
    /// segment on the value stack starting at this index — the caller's
    /// `frame` stays in place (no 256-byte swap per call). `None` outside a
    /// leaf run.
    pub(crate) leaf_frame_base: Option<usize>,
    /// Cut 35 slice 23: an offset applied to `frame_get`/`frame_set` while
    /// a `LeafFrame::CallerSlots` register leaf runs — its frame IS the
    /// caller's frame at `base..` (the caller's `leaf_frame_base` stays
    /// active, and the offset addresses its slots directly). Zero for every
    /// other frame source, so the extra add is a predictable no-op. A
    /// `CallerSlots` leaf contains no call steps, so the offset is never
    /// active across a nested call.
    leaf_frame_offset: usize,
    pub args: Vec<Value>,
    pub lexical_env: EnvRef,
    pub(crate) env_stack: EnvStack,
    /// The certified body's capture context (Cut 3 continuation): the env
    /// holding the body's captured bindings, fixed for the run. The
    /// per-iteration loop machinery copies fresh head bindings from it.
    pub(crate) body_context: Option<EnvRef>,
    /// The running context's realm global object, resolved on first access
    /// and reused for the whole body run (a body's realm cannot change while
    /// its own steps run — nested calls push their own contexts). Avoids the
    /// per-access context-stack walk and handle clone.
    pub(crate) global: Option<Handle<crux::object::JsObject>>,
    pub completion: Value,
    pub try_stack: Vec<TryFrame>,
    /// Pending control transfers awaiting their finally (a stack: nested
    /// finallys push their own pending instead of overwriting an outer one).
    pub pending: Vec<PendingControl>,
    pub thrown: Option<Value>,
    pub resume_abrupt: Option<ResumeAbrupt>,
    /// Whether the innermost for-of is stepping its iterator (`ForOfNext`):
    /// a `next()` error propagates without closing the iterator (spec
    /// 14.7.6.2 uses `?`), unlike a body or head-binding error.
    pub for_of_stepping: bool,
    /// Whether the innermost for-await-of is awaiting its `next()` promise
    /// (`AsyncForOfNext`): a rejection propagates without closing the
    /// iterator — the close is only for body abrupt completions (spec
    /// 14.7.5.5), and the AsyncFromSyncIterator continuation already closed
    /// an underlying sync iterator on a rejected value.
    pub async_for_of_stepping: bool,
    /// Whether the innermost destructure is stepping its iterator
    /// (`DestructureNext`): an abrupt step leaves the iterator open.
    pub destructure_stepping: bool,
    /// In-progress for-in enumerations: the (prototype-level, key) pairs and
    /// the enumerated base object, so a key deleted during enumeration can be
    /// re-checked against its own level at visit time (spec
    /// EnumerateObjectProperties).
    pub for_in_stack: Vec<ForInState>,
    pub for_of_stack: Vec<ForOfEntry>,
    pub async_for_of_stack: Vec<crate::expr::IteratorRecord>,
    /// The `(top, end)` step span of each active for-of/for-await-of loop: a
    /// `break`/`continue` whose target lies outside the span leaves the loop,
    /// so its iterator must close (the compiled `ForOfClose` is skipped).
    pub for_of_boundaries: Vec<(usize, usize)>,
    pub async_for_of_boundaries: Vec<(usize, usize)>,
    pub destructure_stack: Vec<crate::expr::IteratorRecord>,
    /// Whether each destructure's iterator was exhausted by an element step;
    /// an exhausted iterator is not closed (spec 13.15.5.2 step 5).
    pub destructure_done: Vec<bool>,
    pub destructure_obj_stack: Vec<Value>,
    /// Stored converted keys of an object-pattern assignment (`[k]: t = ...`)
    /// whose computed keys evaluated before the target reference and are read
    /// back after it.
    pub destructure_assign_keys: Vec<Value>,
    /// Per object-pattern frame of runtime-computed keys (the `[k]: v`
    /// properties), merged into `DestructureObjRest`'s exclusion set so the
    /// rest copy skips them too.
    pub destructure_excluded: Vec<Vec<crux::property::PropertyKey>>,
    pub yield_star_stack: Vec<YieldStarState>,
    /// Cut 58: the working region of a suspended compiled body — the machine
    /// code's private buffer contents at the suspension point, saved so the
    /// resume can restore them (the buffer itself is a per-run local).
    /// Empty outside a suspended JIT run.
    pub jit_work: Vec<Value>,
    /// Pending class definitions whose heritage/computed names suspend.
    pub class_stack: Vec<ClassEvalState>,
    pub switch_disc: Option<Value>,
    /// An upstream `?.` short-circuited: the rest of the chain (keys, args,
    /// further links) must not evaluate, and the chain is `undefined` (spec
    /// 13.4.3). Cleared when the outermost chain node finishes.
    pub chain_short: bool,
    /// Cut 36 mirror: whether the running context's env chain is exactly the
    /// global env (no intermediate envs), computed at run entry and valid
    /// only while the body adds no envs mid-run (`CompiledBody::env_constant`
    /// gates the `LoadIdent` fast path on it). Mirrors the JIT's
    /// `JitCallContext::clean_chain`.
    pub(crate) clean_chain: bool,
    /// The in-flight disposal of a scope's `using` resources at an
    /// async-disposal suspension: the VM suspends with `Suspension::Await`
    /// per async dispose, and `run_abrupt` resumes the driver.
    pub pending_disposal: Option<PendingDisposal>,
    /// A caught throw that discarded the try block's envs: `CatchBind`
    /// disposes them (folding into the thrown value, spec 9.4.3) before
    /// binding the parameter. `(saved_env, env_depth)` of the try frame.
    pub pending_catch_disposal: Option<(EnvRef, usize)>,
    /// Cut 45: the next body of a JIT tail-call chain — a compiled body's
    /// `tail_call` helper replaced the frame (via `tail_prepare_ordinary`)
    /// and stashed the callee's body here; `run_compiled_body` loops on it
    /// with the same Vm, so a deep TCO chain never grows the native stack.
    /// The Rc is also in `ecma_functions` (the callee is registered), so its
    /// literal `Value`s are already rooted and this field needs no tracing.
    pub(crate) tail_replaced: Option<std::rc::Rc<crate::ir::CompiledBody>>,
    /// Cut 47: the closure whose body is running on this Vm, when it is an
    /// ordinary ECMAScript function entered through `run_compiled_body`
    /// (set at entry, and by `tail_prepare_ordinary` on a frame
    /// replacement). The JIT's `TailCallSelfCheck` machine code compares the
    /// resolved callee against this value to recognize a global-name
    /// self-tail-call at runtime (the name could have been reassigned).
    pub(crate) current_function: Option<Value>,
    /// Cut 62: the `new.target` of the current certified run (the frame-slot
    /// model creates no FunctionEnv to carry it). Set by the certified
    /// construct path; `None` (a normal call or a fresh Vm) reads as
    /// `undefined`.
    pub(crate) current_new_target: Option<Value>,
    pub strict: bool,
    /// Whether the statement-completion register holds an empty completion
    /// (spec 6.2.2.3): no value-producing statement has run since the last
    /// reset. Only the top-level script path observes it.
    pub completion_is_empty: bool,
    /// The register executor's accumulator: the implicit result register of
    /// the leaf ops and the register-loop bodies (`RunRegBody` clobbers it
    /// freely — it is NOT the loop counter since Cut 35 slice 21). Callers
    /// that need a value across a register run save it.
    acc: Value,
    /// The fused canonical loop's counter (Cut 17; dedicated field, Cut 35
    /// slice 21; raw `f64` since Cut 35 slice 22): the loop head and the
    /// body's redirected reads/writes touch only this field, so the counter
    /// never round-trips the frame/global — or the accumulator — per
    /// iteration. Only the `FastLoop*`/`PushAcc`/`PopAcc`/`IncAcc`/`DecAcc`
    /// steps and the `LoadCounter` op read or write it; every other step
    /// uses the value stack or the accumulator, so the counter survives
    /// arbitrary body code between head dispatches without a save/restore.
    /// The raw f64 is sound because the acc-path compile gates admit only
    /// Number values — the loop init (`for_init_counter_number`) and the
    /// body's statement-position `counter = expr` (`expr_is_number`) must
    /// be provably Number — so the head's test and increment are plain
    /// float ops, never the Value round-trip.
    loop_counter: f64,
    /// Completion-register saves for the `finally` blocks currently running
    /// (nested finallys push in order).
    completion_stack: Vec<(Value, bool)>,
    /// Completion-state saves for the statement lists currently running
    /// (nested blocks/try bodies push in order).
    list_stack: Vec<(Value, bool)>,
    /// Pre-resolved `var` declaration references awaiting their initializer's
    /// value (spec 14.3.2 step 2).
    pub(crate) var_ref_stack: Vec<crate::context::Reference>,
    /// The next element index of each in-progress array literal (nested
    /// literals push in order); the length is set once at `ArrayEnd`.
    pub(crate) array_index_stack: Vec<usize>,
    /// The argument-vector boundary of each in-progress call (nested calls
    /// push in order); the call step pops it and takes the appended slice.
    pub(crate) args_base_stack: Vec<usize>,
    /// The call's arguments for the active body (Cut 3 continuation,
    /// unmapped arguments slice): set by the certified call when the body
    /// has an `arguments` slot, read by `Step::CreateArguments`. Distinct
    /// from `args` — the in-flight argument-construction stack.
    pub(crate) call_args: Vec<Value>,
}

impl Trace for Vm {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.stack.trace(visit);
        self.frame.trace(visit);
        self.args.trace(visit);
        self.lexical_env.trace(visit);
        self.env_stack.trace(visit);
        self.body_context.trace(visit);
        self.global.trace(visit);
        self.completion.trace(visit);
        self.try_stack.trace(visit);
        self.pending.trace(visit);
        self.thrown.trace(visit);
        self.resume_abrupt.trace(visit);
        // The suspended-loop/iteration stacks hold live values and iterator
        // records across a suspension (a pooled Vm is reset before reuse, so
        // tracing an idle Vm's empty stacks is a no-op).
        for (object, keys, _) in &self.for_in_stack {
            object.trace(visit);
            for (_, key) in keys {
                key.trace(visit);
            }
        }
        self.for_of_stack.trace(visit);
        self.async_for_of_stack.trace(visit);
        self.destructure_stack.trace(visit);
        self.destructure_obj_stack.trace(visit);
        self.destructure_assign_keys.trace(visit);
        self.yield_star_stack.trace(visit);
        self.class_stack.trace(visit);
        self.jit_work.trace(visit);
        self.switch_disc.trace(visit);
        self.pending_disposal.trace(visit);
        if let Some((env, _)) = &self.pending_catch_disposal {
            env.trace(visit);
        }
        self.acc.trace(visit);
        for (value, _) in &self.completion_stack {
            value.trace(visit);
        }
        for (value, _) in &self.list_stack {
            value.trace(visit);
        }
        self.var_ref_stack.trace(visit);
        self.call_args.trace(visit);
        self.current_function.trace(visit);
        self.current_new_target.trace(visit);
        // The leaf-path JIT runs' private buffers (pushed by `run_jit_leaf`
        // for the call's duration; empty otherwise).
        // SAFETY: each entry is a buffer `run_jit_leaf` holds alive for its
        // call, and the call outlives any collection it triggers.
        for (ptr, len) in &self.jit_roots {
            for value in unsafe { std::slice::from_raw_parts(*ptr as *const Value, *len) } {
                value.trace(visit);
            }
        }
    }
}

impl Trace for ForOfEntry {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        match self {
            ForOfEntry::Generic(iterator) => iterator.trace(visit),
            ForOfEntry::Fast { array, .. } => array.trace(visit),
        }
    }
}

impl Trace for YieldStarState {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.iterator.trace(visit);
        self.received.trace(visit);
    }
}

impl Trace for ClassEvalState {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.class_env.trace(visit);
        self.class_private_env.trace(visit);
        self.outer_private_env.trace(visit);
        self.outer_env.trace(visit);
        self.heritage.trace(visit);
    }
}

impl Trace for DisposalResume {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        if let DisposalResume::DeliverCatch { saved_env, .. } = self {
            saved_env.trace(visit);
        }
    }
}

impl Trace for PendingDisposal {
    fn trace(&self, visit: &mut dyn FnMut(GcAny)) {
        self.resources.trace(visit);
        self.completion.trace(visit);
        self.resume.trace(visit);
    }
}

/// The per-class-definition state while the resumable VM evaluates a
/// suspending heritage or computed element names.
#[derive(Debug)]
pub struct ClassEvalState {
    pub class_env: EnvRef,
    pub class_private_env: crux::handle::Handle<crate::context::PrivateEnvironment>,
    pub outer_private_env: Option<crux::handle::Handle<crate::context::PrivateEnvironment>>,
    pub outer_env: EnvRef,
    pub heritage: Option<Value>,
}

/// The per-`yield*` delegation state.
#[derive(Debug)]
pub struct YieldStarState {
    pub iterator: crate::expr::IteratorRecord,
    pub received: Value,
    /// Whether the current delegation pass was resumed with a return
    /// completion: a done result then completes the body with a return
    /// completion of its value instead of continuing (spec 15.5.5 return
    /// case step viii).
    pub resumed_return: bool,
}

/// An in-flight scope disposal (spec 9.4.3 DisposeResources): the remaining
/// resources in disposal order, the completion being folded, and how to
/// resume once the stack drains.
#[derive(Debug)]
pub struct PendingDisposal {
    pub resources: Vec<crate::env::DisposableResource>,
    pub index: usize,
    pub completion: Completion,
    pub resume: DisposalResume,
}

/// How a finished scope disposal delivers its folded completion.
#[derive(Debug)]
pub enum DisposalResume {
    /// Scope-exit style: a normal completion continues at the current ip; a
    /// throw propagates through the handler table.
    ApplyCompletion,
    /// The try-catch path: the folded value is delivered to the catch (the
    /// `CatchBind` step re-runs with `self.thrown` set and the env stack
    /// restored).
    DeliverCatch { saved_env: EnvRef, env_depth: usize },
}

impl Vm {
    pub fn new(lexical_env: EnvRef, strict: bool) -> Self {
        Self {
            ip: 0,
            stack: Vec::new(),
            jit_roots: Vec::new(),
            frame: Frame::Inline(std::array::from_fn(|_| Value::Undefined)),
            leaf_frame_base: None,
            leaf_frame_offset: 0,
            args: Vec::new(),
            lexical_env,
            env_stack: EnvStack::with_base(lexical_env),
            body_context: None,
            global: None,
            clean_chain: false,
            completion: Value::Undefined,
            try_stack: Vec::new(),
            pending: Vec::new(),
            thrown: None,
            resume_abrupt: None,
            for_of_stepping: false,
            async_for_of_stepping: false,
            destructure_stepping: false,
            for_in_stack: Vec::new(),
            for_of_stack: Vec::new(),
            async_for_of_stack: Vec::new(),
            for_of_boundaries: Vec::new(),
            async_for_of_boundaries: Vec::new(),
            destructure_stack: Vec::new(),
            destructure_done: Vec::new(),
            destructure_obj_stack: Vec::new(),
            destructure_assign_keys: Vec::new(),
            destructure_excluded: Vec::new(),
            yield_star_stack: Vec::new(),
            jit_work: Vec::new(),
            class_stack: Vec::new(),
            switch_disc: None,
            chain_short: false,
            pending_disposal: None,
            pending_catch_disposal: None,
            strict,
            completion_is_empty: true,
            acc: Value::Undefined,
            loop_counter: 0.0,
            completion_stack: Vec::new(),
            list_stack: Vec::new(),
            var_ref_stack: Vec::new(),
            array_index_stack: Vec::new(),
            args_base_stack: Vec::new(),
            call_args: Vec::new(),
            tail_replaced: None,
            current_function: None,
            current_new_target: None,
        }
    }

    /// Reset a pooled Vm for a new run (the per-call reuse): the Vec
    /// stacks keep their capacity, the inline env stack is re-pointed, and
    /// the frame is left stale — `setup_frame` overwrites every slot below
    /// `frame_size` on the next run, and a `frame_size`-0 body never reads
    /// it (the pool hands a Vm out only after its previous run finished).
    pub fn reset(&mut self, lexical_env: EnvRef, strict: bool) {
        // GC-4: drop the frame's slot values so the pooled Vm (and a tail
        // call's fresh run, which reuses this Vm) does not trace stale
        // frame locals as roots.
        self.clear_frame();
        self.ip = 0;
        self.stack.clear();
        self.jit_roots.clear();
        self.leaf_frame_base = None;
        self.leaf_frame_offset = 0;
        self.args.clear();
        self.lexical_env = lexical_env;
        self.env_stack.reset(lexical_env);
        self.body_context = None;
        self.global = None;
        self.clean_chain = false;
        self.completion = Value::Undefined;
        self.try_stack.clear();
        self.pending.clear();
        self.thrown = None;
        self.resume_abrupt = None;
        self.for_of_stepping = false;
        self.async_for_of_stepping = false;
        self.destructure_stepping = false;
        self.for_in_stack.clear();
        self.for_of_stack.clear();
        self.async_for_of_stack.clear();
        self.for_of_boundaries.clear();
        self.async_for_of_boundaries.clear();
        self.destructure_stack.clear();
        self.destructure_done.clear();
        self.destructure_obj_stack.clear();
        self.destructure_assign_keys.clear();
        self.destructure_excluded.clear();
        self.yield_star_stack.clear();
        self.jit_work.clear();
        self.class_stack.clear();
        self.switch_disc = None;
        self.chain_short = false;
        self.pending_disposal = None;
        self.pending_catch_disposal = None;
        self.strict = strict;
        self.completion_is_empty = true;
        self.acc = Value::Undefined;
        self.loop_counter = 0.0;
        self.completion_stack.clear();
        self.list_stack.clear();
        self.var_ref_stack.clear();
        self.array_index_stack.clear();
        self.args_base_stack.clear();
        self.call_args.clear();
        self.current_function = None;
        self.current_new_target = None;
    }

    /// GC-4: clear every frame slot so a Vm's stale values are never traced
    /// as roots (a WeakRef or FinalizationRegistry target that lived in a
    /// frame slot must die when the script/function that held it returns).
    pub(crate) fn clear_frame(&mut self) {
        match &mut self.frame {
            Frame::Inline(buf) => buf.fill(Value::Undefined),
            Frame::Heap(vec) => vec.clear(),
        }
    }

    fn pop(&mut self) -> Value {
        self.stack.pop().unwrap_or(Value::Undefined)
    }

    /// Allocate the fast-path frame and bind the arguments into their slots
    /// (Cut 3). Params are slots `0..arity` in source order; extra arguments
    /// are ignored (spec 10.2.11, ordinary call), missing ones stay
    /// `undefined`, `var` bindings initialize to `undefined`, and
    /// `let`/`const` slots start in the TDZ — matching
    /// `function_declaration_instantiation` for a body whose references the
    /// scope analysis certified.
    pub fn setup_frame(&mut self, scope: &ScopeInfo, args: &[Value]) {
        self.frame = leaf_frame(scope, args);
    }

    /// Cut 58: fill a certified resumable body's frame — params from `args`,
    /// the `this` slot, and the arguments-object inputs — the async/generator
    /// drivers share `run_compiled_body`'s certified setup.
    pub(crate) fn setup_certified_frame(
        &mut self,
        scope: &ScopeInfo,
        args: &[Value],
        this_value: Option<Value>,
    ) {
        if scope.frame_size > 0 {
            self.setup_frame(scope, args);
        }
        if scope.arguments_slot.is_some() {
            self.call_args = args.to_vec();
        }
        if let (Some(slot), Some(this_value)) = (scope.this_slot, this_value) {
            *self.frame.get_mut(slot) = this_value;
        }
    }

    /// Cut 34: the active frame slot — the leaf's flat stack segment when a
    /// leaf runs inline (`leaf_frame_base`), else the caller's `frame`. The
    /// branch is fully predictable on both paths (the base is `None` for
    /// every non-leaf body).
    #[inline]
    fn frame_get(&self, slot: usize) -> &Value {
        let slot = slot + self.leaf_frame_offset;
        match self.leaf_frame_base {
            Some(base) => &self.stack[base + slot],
            None => Frame::get(&self.frame, slot),
        }
    }

    #[inline]
    pub(crate) fn frame_get_mut(&mut self, slot: usize) -> &mut Value {
        let slot = slot + self.leaf_frame_offset;
        match self.leaf_frame_base {
            Some(base) => &mut self.stack[base + slot],
            None => Frame::get_mut(&mut self.frame, slot),
        }
    }

    /// The fused strict-equality branch (`JumpIfEqImm`/`JumpIfNeqImm`): read
    /// the slot (TDZ-checked like `LoadLocal`), test it against the numeric
    /// literal with STRICT equality — a non-Number value is never strictly
    /// equal to a Number, so no coercion and no general evaluator — and jump
    /// to `target` when `equal == jump_when_equal` (the step's convention:
    /// `JumpIfEqImm` jumps when the `===` test is FALSE, `JumpIfNeqImm`
    /// when the `!==` test is FALSE).
    fn jump_if_strict_eq_imm(
        &mut self,
        slot: usize,
        imm: f64,
        jump_when_equal: bool,
        target: usize,
    ) -> Result<(), JsError> {
        let left = *self.frame_get(slot);
        if left.is_uninitialized() {
            return Err(JsError::new(
                ErrorKind::ReferenceError,
                "Cannot access a binding before initialization".into(),
            ));
        }
        let equal = match left.as_number() {
            // Strict equality of two Numbers: NaN compares false, -0 == 0,
            // matching Rust's f64 `==` (the engine has no boxed Numbers).
            Some(num) => num == imm,
            None => false,
        };
        if equal == jump_when_equal {
            self.ip = target;
        }
        Ok(())
    }

    /// The fused relational-imm loop test (Cut 4): read the slot (TDZ-checked
    /// like `LoadLocal`), abstract-compare against the constant with the
    /// general binary evaluator, and jump to `target` when the test is false
    /// — exactly what `LoadLocal; BinaryImm; JumpIfFalse` computes.
    fn jump_if_rel_imm(
        &mut self,
        agent: &mut Agent,
        op: BinaryOp,
        slot: usize,
        imm: f64,
        target: usize,
    ) -> Result<(), JsError> {
        let left = *self.frame_get(slot);
        if left.is_uninitialized() {
            return Err(JsError::new(
                ErrorKind::ReferenceError,
                "Cannot access a binding before initialization".into(),
            ));
        }
        if let Some(num) = left.as_number() {
            // JS relational semantics for two numbers: NaN comparisons are
            // false, matching Rust's f64 comparisons.
            let pass = match op {
                BinaryOp::LessThan => num < imm,
                BinaryOp::LessEqual => num <= imm,
                BinaryOp::GreaterThan => num > imm,
                BinaryOp::GreaterEqual => num >= imm,
                _ => unreachable!("JumpIfRelImm with a non-relational op"),
            };
            if !pass {
                self.ip = target;
            }
            return Ok(());
        }
        let right = Value::Number(imm);
        let value = crate::expr::apply_binary(agent, op, &left, &right)?;
        if !crux::convert::to_boolean(&value) {
            self.ip = target;
        }
        Ok(())
    }

    /// The fused relational loop test with a fast-binding limit (Cut 15
    /// extension): read the counter slot (TDZ-checked like `LoadLocal`),
    /// read the limit binding, abstract-compare with the general binary
    /// evaluator, and jump to `target` when the test is false — exactly
    /// what `LoadLocal; LoadLocal/LoadGlobal; Binary; JumpIfFalse`
    /// computes.
    fn jump_if_rel_limit(
        &mut self,
        agent: &mut Agent,
        op: BinaryOp,
        slot: usize,
        limit: RelLimit,
        target: usize,
    ) -> Result<(), JsError> {
        let left = *self.frame_get(slot);
        if left.is_uninitialized() {
            return Err(JsError::new(
                ErrorKind::ReferenceError,
                "Cannot access a binding before initialization".into(),
            ));
        }
        let right = match limit {
            RelLimit::Imm(imm) => Value::Number(imm),
            RelLimit::Slot(limit_slot) => {
                let right = *self.frame_get(limit_slot);
                if right.is_uninitialized() {
                    return Err(JsError::new(
                        ErrorKind::ReferenceError,
                        "Cannot access a binding before initialization".into(),
                    ));
                }
                right
            }
            RelLimit::Global(name) => self.load_global_value(agent, name)?,
        };
        if let (Some(num), Some(limit_num)) = (left.as_number(), right.as_number()) {
            // JS relational semantics for two numbers: NaN comparisons are
            // false, matching Rust's f64 comparisons.
            let pass = match op {
                BinaryOp::LessThan => num < limit_num,
                BinaryOp::LessEqual => num <= limit_num,
                BinaryOp::GreaterThan => num > limit_num,
                BinaryOp::GreaterEqual => num >= limit_num,
                _ => unreachable!("JumpIfRelLimit with a non-relational op"),
            };
            if !pass {
                self.ip = target;
            }
            return Ok(());
        }
        let value = crate::expr::apply_binary(agent, op, &left, &right)?;
        if !crux::convert::to_boolean(&value) {
            self.ip = target;
        }
        Ok(())
    }

    /// The running context's realm global object, cached on first access
    /// (see the `Vm::global` field): the top-level fast path's reference
    /// target and the global-cell validation base.
    pub(crate) fn global_object(
        &mut self,
        agent: &mut Agent,
    ) -> Result<Handle<crux::object::JsObject>, JsError> {
        if let Some(global) = &self.global {
            return Ok(*global);
        }
        let global = agent.running_context()?.realm.global_object;
        self.global = Some(global);
        Ok(global)
    }

    /// Whether the current realm's global object matches `(id, generation)`
    /// (the global-leaf-cache validation, Cut 35 slice 25): the cached
    /// handle on this Vm is read in place (no clone — `global_object`
    /// clones its return every call); the first call resolves and caches
    /// it.
    fn global_matches(
        &mut self,
        agent: &mut Agent,
        id: u64,
        generation: u32,
    ) -> Result<bool, JsError> {
        if let Some(global) = &self.global {
            return Ok(global.id() == id && global.generation() == generation);
        }
        let global = agent.running_context()?.realm.global_object;
        let matches = global.id() == id && global.generation() == generation;
        self.global = Some(global);
        Ok(matches)
    }

    /// The top-level fast path's reference for a declared global var: a
    /// value reference against the realm's global object (the global
    /// environment's binding object), so `get_value`/`put_value` run the
    /// exact property machinery the env path uses after its resolve walk.
    fn global_reference(
        &mut self,
        agent: &mut Agent,
        name: crux::AtomId,
    ) -> Result<crate::context::Reference, JsError> {
        let global = self.global_object(agent)?;
        let global_value = Value::Object(global);
        Ok(crate::context::Reference {
            base: crate::context::ReferenceBase::Value(global_value),
            name: PropertyKey::from_js_string(&crux::lookup(name)),
            strict: self.strict,
            this_value: Some(global_value),
            private_name: None,
        })
    }

    /// The direct-mapped cache index for a global-var name atom.
    fn global_cell_index(name: crux::AtomId) -> usize {
        name as usize & (GLOBAL_CELLS - 1)
    }

    /// Resolve and cache the global-object slot for a declared top-level
    /// name (own data property only; the reference path handles the rest).
    fn resolve_global_cell(agent: &mut Agent, name: crux::AtomId) {
        let key = PropertyKey::String(name);
        let Some(global) = agent
            .running_context()
            .ok()
            .map(|context| context.realm.global_object)
        else {
            return;
        };
        let props = global.properties.borrow();
        if let Some(slot) = props.iter().position(|(stored, property)| {
            *stored == key && matches!(property.kind, crux::object::PropertyKind::Data { .. })
        }) {
            agent.global_cells[Self::global_cell_index(name)] = Some((name, slot));
        }
    }

    /// Record the JIT's global-value cell for `name` under the version read
    /// NOW (call after the value is read, so a getter that mutated the
    /// global during the read records a version that will not match it).
    /// `slot` is the binding's property-vector slot when known — the
    /// compiled `StoreGlobal` fast path needs it (a load-only cell with
    /// `None` still validates for reads).
    fn record_global_cell(
        agent: &mut Agent,
        name: crux::AtomId,
        value: Value,
        global: &Handle<crux::object::JsObject>,
        slot: Option<usize>,
    ) {
        agent.global_value_cells[Self::global_cell_index(name)] = crate::jit::GlobalValueCell {
            name,
            global_id: global.id(),
            generation: global.generation(),
            slot: slot.map(|s| s as u32).unwrap_or(u32::MAX),
            value,
        };
    }

    /// Best-effort warm of the JIT's global-value cell after an identifier
    /// resolve landed on the global object record (the compiled `LoadIdent`
    /// probe's miss path). Records only when the name is an own data
    /// property of the global object — the probe's fast path is exactly the
    /// declared-var read shape; an accessor or absent name stays on the
    /// resolve path (an accessor can run code and an inherited property can
    /// change without the global's generation bumping, so caching either
    /// would go stale). The read already succeeded, so errors are swallowed
    /// (the cell is an optimization).
    pub(crate) fn warm_global_cell(&mut self, agent: &mut Agent, name: crux::AtomId, value: Value) {
        let Ok(global) = self.global_object(agent) else {
            return;
        };
        Self::resolve_global_cell(agent, name);
        let Some((_, slot)) = agent.global_cells[Self::global_cell_index(name)] else {
            return;
        };
        Self::record_global_cell(agent, name, value, &global, Some(slot));
    }

    /// The Cut 36 `LoadIdent` fast path: read the warmed global-value cell
    /// when its captured name and the live global's identity + generation
    /// still match (the same probe the compiled `LoadIdent` runs). The cell
    /// is only ever written by a resolve that landed on a global-object
    /// binding, so a hit is exactly the value the env walk would produce;
    /// `None` falls back to the full resolve.
    fn try_global_cell_read(&mut self, agent: &mut Agent, name: crux::AtomId) -> Option<Value> {
        let cell = agent.global_value_cells[Self::global_cell_index(name)];
        if cell.name != name {
            return None;
        }
        let global = self.global_object(agent).ok()?;
        if cell.global_id != global.id() || cell.generation != global.generation() {
            return None;
        }
        Some(cell.value)
    }

    /// Read a declared top-level `var` directly off the global object: the
    /// cached slot when still valid (a direct-mapped probe + key match),
    /// else the reference path (which re-resolves the cache). Every
    /// successful read also records the JIT's global-value cell (Cut 36),
    /// so the compiled `LoadGlobal` fast path warms from the first
    /// interpreter or slow-path read.
    pub(crate) fn load_global_value(
        &mut self,
        agent: &mut Agent,
        name: crux::AtomId,
    ) -> Result<Value, JsError> {
        if let Some((cached_name, slot)) = agent.global_cells[Self::global_cell_index(name)]
            && cached_name == name
        {
            let global = self.global_object(agent)?;
            let props = global.properties.borrow();
            if let Some((key, property)) = props.get(slot)
                && *key == PropertyKey::String(name)
                && let crux::object::PropertyKind::Data { value, .. } = &property.kind
            {
                let value = *value;
                Self::record_global_cell(agent, name, value, &global, Some(slot));
                return Ok(value);
            }
        }
        let reference = self.global_reference(agent, name)?;
        let value = crate::context::get_value(agent, &reference)?;
        Self::resolve_global_cell(agent, name);
        // The version read AFTER the value: a getter that mutated the global
        // during `get_value` bumps the generation, so the recorded cell is
        // either current or never matched by the JIT's live check. Record
        // only an own data property (an accessor or inherited binding could
        // change without the global's generation bumping — see
        // `warm_global_cell`).
        if let Some((_, slot)) = agent.global_cells[Self::global_cell_index(name)] {
            let global = self.global_object(agent)?;
            Self::record_global_cell(agent, name, value, &global, Some(slot));
        }
        Ok(value)
    }

    /// Write a declared top-level `var`: the cached slot's data property
    /// when still valid and writable, else the reference path (which
    /// enforces the strict-mode non-writable error and re-resolves the
    /// cache).
    pub(crate) fn store_global_value(
        &mut self,
        agent: &mut Agent,
        name: crux::AtomId,
        value: Value,
    ) -> Result<(), JsError> {
        if let Some((cached_name, slot)) = agent.global_cells[Self::global_cell_index(name)]
            && cached_name == name
        {
            let global = self.global_object(agent)?;
            let mut props = global.properties.borrow_mut();
            if let Some((key, property)) = props.get_mut(slot)
                && *key == PropertyKey::String(name)
                && let crux::object::PropertyKind::Data {
                    writable: true,
                    value: cell,
                } = &mut property.kind
            {
                *cell = value;
                // Mirror the JIT's global-value cell (Cut 36): a plain
                // cached write does not bump the generation, so without the
                // mirror the cell would keep serving the pre-store value to
                // the compiled `LoadGlobal` fast path.
                Self::record_global_cell(agent, name, value, &global, Some(slot));
                return Ok(());
            }
        }
        let reference = self.global_reference(agent, name)?;
        crate::context::put_value(agent, &reference, value)?;
        Self::resolve_global_cell(agent, name);
        Ok(())
    }

    /// The `++`/`--` fast path on a declared top-level `var`: read, update,
    /// and write through one direct-mapped probe and one property-vector
    /// borrow — the composed load/store takes two of each. Returns the
    /// prefix result (the new value) or the postfix result (the ToNumeric
    /// old value). Falls back to the composed path on a stale cell or a
    /// non-writable property (whose strict-mode error the reference path
    /// enforces).
    fn update_global(
        &mut self,
        agent: &mut Agent,
        name: crux::AtomId,
        op: UpdateOp,
        prefix: bool,
    ) -> Result<Value, JsError> {
        if let Some((cached_name, slot)) = agent.global_cells[Self::global_cell_index(name)]
            && cached_name == name
        {
            let global = self.global_object(agent)?;
            let mut props = global.properties.borrow_mut();
            if let Some((key, property)) = props.get_mut(slot)
                && *key == PropertyKey::String(name)
                && let crux::object::PropertyKind::Data {
                    writable: true,
                    value: cell,
                } = &mut property.kind
            {
                let old = *cell;
                // A Number counter avoids the `to_numeric` call entirely
                // (its result for a Number is the value itself, so the
                // postfix result is `old` unchanged).
                let (new, result) = if let Some(num) = old.as_number() {
                    let delta = if matches!(op, UpdateOp::Increment) {
                        1.0
                    } else {
                        -1.0
                    };
                    (Value::Number(num + delta), old)
                } else {
                    let old_numeric = crux::convert::to_numeric(&old)?;
                    let new = match old_numeric.kind() {
                        ValueKind::Number(n) => {
                            let delta = if matches!(op, UpdateOp::Increment) {
                                1.0
                            } else {
                                -1.0
                            };
                            Value::Number(n + delta)
                        }
                        ValueKind::BigInt(b) => {
                            let one = crux::BigInt::from(1i64);
                            let delta = if matches!(op, UpdateOp::Increment) {
                                one
                            } else {
                                crux::bigint::unary_minus(&one)
                            };
                            Value::BigInt(Handle::new(crux::bigint::add(&b, &delta)))
                        }
                        _ => unreachable!(),
                    };
                    (new, old_numeric)
                };
                *cell = new;
                Self::record_global_cell(agent, name, new, &global, Some(slot));
                return Ok(if prefix { new } else { result });
            }
        }
        let old = self.load_global_value(agent, name)?;
        let (old_numeric, new) = update_value(agent, &op, &old)?;
        self.store_global_value(agent, name, new)?;
        Ok(if prefix { new } else { old_numeric })
    }

    /// The direct-mapped cache index for (object id, name atom).
    fn member_cell_index(object_id: u64, name: crux::AtomId) -> usize {
        (object_id as usize ^ name as usize) & (MEMBER_CELLS - 1)
    }

    /// The direct-mapped cache index for the L1a store cells (a larger
    /// table than the read cells — see [`MEMBER_WRITE_CELLS`]).
    fn member_write_cell_index(object_id: u64, name: crux::AtomId) -> usize {
        (object_id as usize ^ name as usize) & (MEMBER_WRITE_CELLS - 1)
    }

    /// The direct-mapped cache index for (map id, name atom). Part B, B5.2.
    fn member_map_cell_index(map_id: u64, name: crux::AtomId) -> usize {
        (map_id as usize ^ name as usize) & (MEMBER_CELLS - 1)
    }

    /// The object part of a value whose own properties the member cells can
    /// serve: plain/array objects and functions (a function's own data
    /// properties — `length`/`name`/`prototype` — live in the ordinary
    /// object's property vector, so `C.prototype` caches like any own data
    /// read). Every other kind (typed arrays, proxies, boxed primitives)
    /// stays on the full Get path.
    fn cell_object(value: &Value) -> Option<Handle<crux::object::JsObject>> {
        match value.kind() {
            ValueKind::Object(object)
                if matches!(
                    object.kind,
                    crux::object::ObjectKind::Ordinary | crux::object::ObjectKind::Array(_)
                ) =>
            {
                // `kind()` already reconstructed the handle; move it out
                // rather than cloning again (the hot member-read path pays
                // this per read).
                Some(object)
            }
            ValueKind::Function(function) => {
                let object = &function.object;
                if matches!(
                    object.kind,
                    crux::object::ObjectKind::Ordinary | crux::object::ObjectKind::Array(_)
                ) {
                    Some(*object)
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    /// Part B, B5.2: map-based read fast path. Check the object's map for
    /// a descriptor of `name`, then read from `in_fields` at the assigned
    /// offset. Returns `None` if not in the map (falls through to
    /// `member_cell_get`'s existing path).
    fn member_cell_get_map(
        agent: &mut Agent,
        object: &Handle<crux::object::JsObject>,
        name: crux::AtomId,
    ) -> Option<Value> {
        let map = object.map.get()?;
        let map_id = map.id();
        // The direct-mapped cache probe: (map_id, name) → field offset. The
        // map's shape is immutable, so a match pins the descriptor; the
        // offset addresses the object's own `in_fields` (shared map,
        // per-object storage).
        let index = Self::member_map_cell_index(map_id, name);
        if let Some(cell) = &agent.member_map_cells[index]
            && cell.map_id == map_id
            && cell.name == name
            && let Some(value) = object.map_field(cell.slot)
        {
            // Warm the JIT's member-value probe too: a map-served read is an
            // own data property like the slot path's, so the compiled
            // `GetMemberName` probe (id + name + generation validation)
            // serves the next read as a native load.
            agent.member_value_cells[Self::member_cell_index(object.id(), name)] =
                MemberValueCell {
                    id: object.id(),
                    name,
                    generation: object.generation(),
                    value,
                };
            return Some(value);
        }
        // Cache miss (a cold shape or an evicted entry): resolve through the
        // descriptor scan and re-cache the offset.
        let key = PropertyKey::String(name);
        let slot = map.field_offset(&key)?;
        let value = object.map_field(slot)?;
        agent.member_map_cells[index] = Some(MemberMapCell { map_id, name, slot });
        agent.member_value_cells[Self::member_cell_index(object.id(), name)] = MemberValueCell {
            id: object.id(),
            name,
            generation: object.generation(),
            value,
        };
        Some(value)
    }

    /// The warm member-read probes shared by `member_cell_get` and the
    /// register executor's member-read arms: the generation-validated value
    /// cell first (a pure (id, name, generation) compare — no map read, no
    /// in-fields access, no per-read cache write), then the map live-field
    /// read, which warms the value cell on its hit so the next read — and
    /// the JIT's inline probe, which sees only the value cell — is served
    /// by the pure compare. `#[inline(always)]` so a warm register read
    /// folds into the executor arm with no out-of-line call; `None` means
    /// both probes missed and the caller falls back to the full resolution
    /// (which re-runs these probes, then the slot/vector and chain paths).
    #[inline(always)]
    fn member_cell_warm_probe(
        agent: &mut Agent,
        object: &Handle<crux::object::JsObject>,
        name: crux::AtomId,
    ) -> Option<Value> {
        let index = Self::member_cell_index(object.id(), name);
        let cell = &agent.member_value_cells[index];
        if cell.id == object.id() && cell.name == name && cell.generation == object.generation() {
            return Some(cell.value);
        }
        Self::member_cell_get_map(agent, object, name)
    }

    /// The cached read of `object.name` — an own data property on a plain
    /// object at the direct-mapped slot, re-validated against the stored key
    /// and property kind. `None` falls back to the full Get (which then
    /// re-resolves the cache). The fronting value cache (Cut 35 slice 11)
    /// returns the value with no property-vector borrow when the object's
    /// generation matches the cached read (every own-property mutation path
    /// bumps the generation, including `set_key`'s in-place value update).
    fn member_cell_get(agent: &mut Agent, object: &Value, name: crux::AtomId) -> Option<Value> {
        let object = Self::cell_object(object)?;
        if let Some(value) = Self::member_cell_warm_probe(agent, &object, name) {
            return Some(value);
        }
        let index = Self::member_cell_index(object.id(), name);
        let slot = match agent.member_cells[index] {
            Some((cached_id, cached_name, slot))
                if cached_id == object.id() && cached_name == name =>
            {
                slot
            }
            _ => {
                // Cut 23 (proto-keyed fallback): fresh objects (a
                // constructor's new `this`) share their prototype's shape,
                // so the slot cached for the prototype is validated against
                // this object's own vector below — a divergent layout
                // misses and re-resolves.
                let proto_handle = object.get_prototype_of().ok()?;
                let proto = proto_handle.as_ref()?;
                if !matches!(
                    proto.kind,
                    crux::object::ObjectKind::Ordinary | crux::object::ObjectKind::Array(_)
                ) {
                    return None;
                }
                let proto_index = Self::member_cell_index(proto.id(), name);
                let (cached_proto, cached_name, slot) = agent.member_proto_cells[proto_index]?;
                if cached_proto != proto.id() || cached_name != name {
                    return None;
                }
                slot
            }
        };
        let props = object.properties.borrow();
        let (key, property) = props.get(slot)?;
        if *key != PropertyKey::String(name) {
            return None;
        }
        match &property.kind {
            crux::object::PropertyKind::Data { value, .. } => {
                let value = *value;
                agent.member_value_cells[index] = MemberValueCell {
                    id: object.id(),
                    name,
                    generation: object.generation(),
                    value,
                };
                Some(value)
            }
            _ => None,
        }
    }

    /// The direct-mapped cache index for (object id, name) chain reads.
    fn member_chain_index(object_id: u64, name: crux::AtomId) -> usize {
        (object_id as usize ^ name as usize) & (MEMBER_CELLS - 1)
    }

    /// The cached prototype-chain member read: returns the value when the
    /// receiver's id/name/generation and every cached link's (id,
    /// generation) still match — an own property appearing on the receiver,
    /// a link's own structural mutation (a define, a delete, a proto
    /// replacement) bumps a generation and misses. Links below the found
    /// one cannot shadow its own data property, so the probe never walks
    /// past the cached links. The resolved value is re-read LIVE from the
    /// found link (its member value cell when warm, else the recorded
    /// vector slot): the chain cell caches the resolution, not the value,
    /// so a VALUE write to the found link's own property — a warm store
    /// that must not bump the link's generation under the L1c record
    /// discipline — is always observed. `None` falls back to the full Get
    /// (which then re-resolves).
    fn member_chain_get(agent: &mut Agent, object: &Value, name: crux::AtomId) -> Option<Value> {
        let object = Self::cell_object(object)?;
        let index = Self::member_chain_index(object.id(), name);
        let cell = agent.member_chain_cells[index].as_ref()?;
        if cell.id != object.id() || cell.name != name || cell.generation != object.generation() {
            return None;
        }
        let mut link = object.get_prototype_of().ok().flatten();
        let mut found: Option<Handle<crux::object::JsObject>> = None;
        for (expected_id, expected_gen) in cell.links.iter().take(cell.link_count as usize) {
            let current = link?;
            if current.id() != *expected_id || current.generation() != *expected_gen {
                return None;
            }
            found = Some(current);
            link = current.get_prototype_of().ok().flatten();
        }
        let found_link = found?;
        // The live re-read: the found link's member value cell, when warm,
        // IS the current value (every warm L1a store fronts it, every
        // structural change bumps past it). Otherwise read the recorded
        // vector slot directly — the slot is stable while the link's
        // generation is unchanged, which the walk just validated.
        let vindex = Self::member_cell_index(found_link.id(), name);
        let vcell = &agent.member_value_cells[vindex];
        if vcell.id == found_link.id()
            && vcell.name == name
            && vcell.generation == found_link.generation()
        {
            return Some(vcell.value);
        }
        let key = PropertyKey::String(name);
        let props = found_link.properties.borrow();
        let (stored, property) = props.get(cell.slot)?;
        if *stored != key {
            return None;
        }
        match &property.kind {
            crux::object::PropertyKind::Data { value, .. } => Some(*value),
            // The found property converted to an accessor: the structural
            // change bumped the link's generation, so the walk above would
            // have missed; this is the exact fallback for a missed bump.
            _ => None,
        }
    }

    /// Record a prototype-chain read for `(object, name)` resolved by the
    /// full Get: walk up to two plain prototype links, cache (receiver
    /// generation, the links' (id, generation) up to the link holding the
    /// own DATA property, its vector slot) so a later read re-validates
    /// instead of re-walking, and warm the found link's member value cell
    /// (the oracle chain hits re-read through). An own property on the
    /// RECEIVER (a data own prop would have hit `member_cell_get`; an
    /// accessor must not cache the getter's value), an accessor on a link
    /// (the [[Get]] stops there), a non-plain link, a property deeper than
    /// two links, or a miss records nothing.
    fn resolve_chain_cell(agent: &mut Agent, object: &Value, name: crux::AtomId) {
        let Some(object) = Self::cell_object(object) else {
            return;
        };
        if object.has_own_property_atom(name) {
            return;
        }
        let key = PropertyKey::String(name);
        let mut links = [(0u64, 0u32); 2];
        let mut count = 0usize;
        let mut link = object.get_prototype_of().ok().flatten();
        while count < 2 {
            let Some(current) = link else {
                return;
            };
            if !matches!(
                current.kind,
                crux::object::ObjectKind::Ordinary | crux::object::ObjectKind::Array(_)
            ) {
                return;
            }
            links[count] = (current.id(), current.generation());
            count += 1;
            if let Some(slot) = current.property_slot(&key) {
                let props = current.properties.borrow();
                match props
                    .get(slot)
                    .map(|(stored, property)| (stored, &property.kind))
                {
                    // The property found on this link: a data prop caches,
                    // an accessor does not (the read runs the getter).
                    Some((stored, crux::object::PropertyKind::Data { value, .. }))
                        if *stored == key =>
                    {
                        let value = *value;
                        let index = Self::member_chain_index(object.id(), name);
                        agent.member_chain_cells[index] = Some(MemberChainCell {
                            id: object.id(),
                            name,
                            generation: object.generation(),
                            slot,
                            link_count: count as u8,
                            links,
                        });
                        // Warm the found link's (link, name) member value
                        // cell: a chain hit re-reads the found property
                        // through that oracle (see `member_chain_get`), so
                        // it must be warm for the next hit to skip the
                        // vector read.
                        let vindex = Self::member_cell_index(current.id(), name);
                        agent.member_value_cells[vindex] = MemberValueCell {
                            id: current.id(),
                            name,
                            generation: current.generation(),
                            value,
                        };
                        return;
                    }
                    Some(_) => return,
                    None => {}
                }
            }
            link = current.get_prototype_of().ok().flatten();
        }
    }

    /// The direct-mapped cache index for the write-side chain cache.
    pub(crate) fn member_store_cell_index(proto_id: u64, atom: crux::AtomId) -> usize {
        (proto_id as usize ^ atom as usize) & (MEMBER_CELLS - 1)
    }

    /// The write-side chain-cache probe (Cut 22): re-validates a cached
    /// "the chain from this prototype holds no accessor/non-writable for
    /// this key" verdict by walking the chain links and comparing their
    /// generations — a mutation anywhere bumps a generation and misses.
    fn member_store_cell_probe(
        agent: &mut Agent,
        proto: &Handle<crux::object::JsObject>,
        atom: crux::AtomId,
    ) -> bool {
        let index = Self::member_store_cell_index(proto.id(), atom);
        let Some((cached_proto, cached_atom, len, gens)) = agent.member_store_cells[index] else {
            return false;
        };
        if cached_proto != proto.id() || cached_atom != atom {
            return false;
        }
        // The walk starts at the prototype itself (the first recorded link)
        // and compares every link's generation — a mutation anywhere in the
        // chain bumps one and misses.
        let mut link = Some(*proto);
        for &expected in gens.iter().take(len as usize) {
            let Some(current) = link else { return false };
            if current.generation() != expected {
                return false;
            }
            link = current.get_prototype_of().ok().flatten();
        }
        true
    }

    /// Resolve and cache the "chain is safe" verdict for (receiver, key):
    /// walk the chain from the receiver's prototype, recording each
    /// Ordinary/Array link's generation. Safe means every link either lacks
    /// the key or holds a writable data property — where [[Set]] stops and
    /// defines on the receiver (spec 10.1.9.4). `false` = not cacheable (an
    /// exotic link, an accessor, or a non-writable data property) — the
    /// caller falls back to the full [[Set]].
    fn member_store_cell_resolve(
        agent: &mut Agent,
        receiver: &crux::object::JsObject,
        key: &PropertyKey,
        atom: crux::AtomId,
    ) -> bool {
        let Some(proto) = receiver.get_prototype_of().ok().flatten() else {
            // No chain: [[Set]] always defines on the receiver (handled
            // directly by the caller, no cache needed).
            return true;
        };
        if !matches!(
            proto.kind,
            crux::object::ObjectKind::Ordinary | crux::object::ObjectKind::Array(_)
        ) {
            return false;
        }
        let mut gens = [0u32; 4];
        let mut len = 0usize;
        let mut link = Some(proto);
        while let Some(current) = link {
            if len >= 4 {
                return false;
            }
            if !matches!(
                current.kind,
                crux::object::ObjectKind::Ordinary | crux::object::ObjectKind::Array(_)
            ) {
                return false;
            }
            match current.get_own_property_key(key).ok().flatten() {
                Some(prop) => match &prop.kind {
                    crux::object::PropertyKind::Data { writable, .. } if *writable => {
                        // The writable-data stop: [[Set]] defines on the
                        // receiver; the stop link's generation is recorded
                        // so a later accessor conversion invalidates.
                        gens[len] = current.generation();
                        len += 1;
                        break;
                    }
                    _ => return false, // an accessor or non-writable data
                },
                None => {
                    gens[len] = current.generation();
                    len += 1;
                    link = current.get_prototype_of().ok().flatten();
                }
            }
        }
        let index = Self::member_store_cell_index(proto.id(), atom);
        agent.member_store_cells[index] = Some((proto.id(), atom, len as u32, gens));
        true
    }

    /// Resolve the store verdict for a given prototype (no receiver),
    /// returning the cache entry `(proto_id, atom, len, gens)` so the
    /// caller can directly set it (used by construct cache pre-warm).
    pub(crate) fn member_store_cell_resolve_raw(
        _agent: &mut Agent,
        proto: crux::handle::Handle<crux::object::JsObject>,
        atom: crux::AtomId,
    ) -> Option<(u64, crux::AtomId, u32, [u32; 4])> {
        let mut gens = [0u32; 4];
        let mut len = 0usize;
        let mut link: Option<crux::handle::Handle<crux::object::JsObject>> = Some(proto);
        while let Some(current) = link {
            if len >= 4 {
                return None;
            }
            if !matches!(
                current.kind,
                crux::object::ObjectKind::Ordinary | crux::object::ObjectKind::Array(_)
            ) {
                return None;
            }
            let key = PropertyKey::String(atom);
            match current.get_own_property_key(&key).ok().flatten() {
                Some(prop) => match &prop.kind {
                    crux::object::PropertyKind::Data { writable, .. } if *writable => {
                        gens[len] = current.generation();
                        len += 1;
                        break;
                    }
                    _ => return None,
                },
                None => {
                    gens[len] = current.generation();
                    len += 1;
                    link = current.get_prototype_of().ok().flatten();
                }
            }
        }
        Some((proto.id(), atom, len as u32, gens))
    }

    /// The fresh-property write fast path (Cut 22): a plain ordinary
    /// receiver with the key absent and a cache-verified accessor-free
    /// chain defines the new property directly — no [[Set]] chain walk, no
    /// descriptor/validate machinery. Returns false to fall back to the
    /// full [[Set]].
    fn fast_fresh_store(
        &mut self,
        agent: &mut Agent,
        object: &Value,
        key: &PropertyKeyName,
        value: &Value,
    ) -> Result<bool, JsError> {
        let PropertyKeyName::Name(atom) = key else {
            return Ok(false);
        };
        let receiver = match object.kind() {
            ValueKind::Object(obj) => obj,
            ValueKind::Function(f) => f.object,
            _ => return Ok(false),
        };
        if !matches!(receiver.kind, crux::object::ObjectKind::Ordinary) {
            return Ok(false);
        }
        let property_key = PropertyKey::String(*atom);
        // An existing property: the in-place update path handles it. For a
        // map-shaped object (the map describes the key) the field state is
        // the authoritative own-property signal — the field is written iff
        // the property vector holds the key (every mapped write mirrors
        // both, and a delete drops the object to dictionary mode), so the
        // property-vector scan is skipped.
        let existing = if let Some(map) = receiver.map.get()
            && let Some(offset) = map.field_offset(&property_key)
        {
            receiver.map_field(offset).is_some()
        } else {
            receiver.get_own_property_key(&property_key)?.is_some()
        };
        if existing {
            return Ok(false);
        }
        let ok = if let Some(proto) = receiver.get_prototype_of()? {
            if !Self::member_store_cell_probe(agent, &proto, *atom)
                && !Self::member_store_cell_resolve(agent, &receiver, &property_key, *atom)
            {
                return Ok(false);
            }
            receiver.fresh_data_define(&property_key, *value)
        } else {
            // No chain: [[Set]] always defines on the receiver.
            receiver.fresh_data_define(&property_key, *value)
        };
        // Part B, B5.2/B5.4: `fresh_data_define` wrote the value into the
        // field the map assigned (a fresh transition or a boilerplate
        // pre-sized field) — cache the (map_id, name) → offset entry for the
        // read path. A dictionary-mode define (map full) has no field.
        if ok
            && let Some(map) = receiver.map.get()
            && let Some(slot) = map.field_offset(&property_key)
        {
            let map_id = map.id();
            let index = Self::member_map_cell_index(map_id, *atom);
            agent.member_map_cells[index] = Some(crate::ir::MemberMapCell {
                map_id,
                name: *atom,
                slot,
            });
        }
        if ok {
            // Cut 35 slice 32: the store-then-read pattern (a constructor
            // writing `this.x` and the caller reading `o.x` right after) —
            // front the just-defined property in the read-side value cache
            // so the next `member_cell_get` returns it with no
            // property-vector borrow or proto-keyed fallback.
            let index = Self::member_cell_index(receiver.id(), *atom);
            agent.member_value_cells[index] = MemberValueCell {
                id: receiver.id(),
                name: *atom,
                generation: receiver.generation(),
                value: *value,
            };
        }
        Ok(ok)
    }

    /// Resolve and cache the slot of `object`'s own data property for
    /// `name` (only plain ordinary/array objects use the linear store).
    fn resolve_member_cell(agent: &mut Agent, object: &Value, name: crux::AtomId) {
        let Some(object) = Self::cell_object(object) else {
            return;
        };
        let key = PropertyKey::String(name);
        if let Some(slot) = object.property_slot(&key) {
            let props = object.properties.borrow();
            if let Some((stored, property)) = props.get(slot)
                && *stored == key
                && let crux::object::PropertyKind::Data { value, .. } = &property.kind
            {
                let index = Self::member_cell_index(object.id(), name);
                agent.member_cells[index] = Some((object.id(), name, slot));
                agent.member_value_cells[index] = MemberValueCell {
                    id: object.id(),
                    name,
                    generation: object.generation(),
                    value: *value,
                };
                // Cut 23: cache the slot for the prototype too — fresh
                // instances of the same shape hit the proto-keyed fallback
                // in `member_cell_get` (validated per access).
                if let Ok(Some(proto)) = object.get_prototype_of()
                    && matches!(
                        proto.kind,
                        crux::object::ObjectKind::Ordinary | crux::object::ObjectKind::Array(_)
                    )
                {
                    let proto_index = Self::member_cell_index(proto.id(), name);
                    agent.member_proto_cells[proto_index] = Some((proto.id(), name, slot));
                }
            }
        }
    }

    /// The direct-mapped cache index for (object id, array index).
    fn array_element_index(object_id: u64, index: u64) -> usize {
        (object_id as usize ^ index as usize) & (MEMBER_CELLS - 1)
    }

    /// The object side of a value whose own properties the L1a store cell
    /// can serve: Ordinary objects and functions with an Ordinary object
    /// part. Arrays are excluded — their `length`/canonical-index writes
    /// are exotic intercepts (ArraySetLength, element defines) the store
    /// cell must never bypass. Every other kind stays on the full [[Set]].
    fn store_cell_object(value: &Value) -> Option<Handle<crux::object::JsObject>> {
        match value.kind() {
            ValueKind::Object(object)
                if matches!(object.kind, crux::object::ObjectKind::Ordinary) =>
            {
                Some(object)
            }
            ValueKind::Function(function) => {
                let object = &function.object;
                if matches!(object.kind, crux::object::ObjectKind::Ordinary) {
                    Some(*object)
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    /// The L1a warm-store fast path (a store-side cell mirroring the read
    /// cells, put_value's hot member-write path): a write to `base.name`
    /// whose cached (id, name, generation) matches stores directly into the
    /// recorded property-vector slot — no namespace/receiver probes, no
    /// primitive boxing, no `find_ecma_accessor` own-property lookup, no
    /// descriptor machinery. Sound because an own writable data property
    /// shadows the whole chain (spec 7.3.3 step 3 consults the chain only
    /// when the own property is absent), so no setter tracking is needed;
    /// a structural change (a redefine, a delete, an accessor conversion)
    /// bumps the generation and misses the cell. VALUE writes take the L1c
    /// no-bump discipline (see `write_data_property_slot`): the read-side
    /// value cell is refreshed here, so the value caches stay exact without
    /// invalidating every other (id, generation)-keyed entry on a value
    /// write. The caller (put_value) has already gated receiver == base on
    /// an Object/Function with a string key. Returns true when the store
    /// happened; false falls back to the full [[Set]].
    pub(crate) fn warm_store_put(
        agent: &mut Agent,
        base: &Value,
        name: crux::AtomId,
        value: Value,
    ) -> bool {
        let Some(object) = Self::store_cell_object(base) else {
            return false;
        };
        let index = Self::member_write_cell_index(object.id(), name);
        let Some(cell) = agent.member_write_cells[index] else {
            return false;
        };
        if cell.id != object.id() || cell.name != name || cell.generation != object.generation() {
            return false;
        }
        // The cell pinned the inline-field mirror (map id + offset) when it
        // was recorded under the same generation gate that pins the slot; a
        // map id pins the descriptor layout, so the mirror writes at the
        // offset with no descriptor re-scan. An unpinned cell (dictionary
        // mode / unmapped property) falls back to the scan.
        let pinned_field =
            (cell.field != MEMBER_WRITE_FIELD_NONE).then_some((cell.map_id, cell.field as usize));
        if !object.write_data_property_slot(
            &PropertyKey::String(name),
            cell.slot,
            value,
            pinned_field,
        ) {
            return false;
        }
        // The L1c record discipline: an in-place VALUE write does not bump
        // the generation (`write_data_property_slot` mirrors the field and
        // writes the vector slot in place) — an own writable data property
        // shadows the whole chain (spec 7.3.3), so no setter/chain
        // tracking is needed, and the store cell stays valid at the
        // UNCHANGED generation (no structural change happened, so its
        // recorded slot/map/field still hold). Only the read-side value
        // cell needs the refresh: front the fresh value at the current
        // generation so the next read — and the compiled `GetMemberName`
        // probe — hits without a property-vector access. Structural
        // changes (define/delete/accessor conversion/map transition) still
        // bump through their own paths.
        let generation = object.generation();
        // The read-side value cell keeps the SMALL table's index (the JIT's
        // compiled probe and every read path mask by MEMBER_CELLS - 1); only
        // the store-cell probe/record use the larger write table.
        let read_index = Self::member_cell_index(object.id(), name);
        agent.member_value_cells[read_index] = MemberValueCell {
            id: object.id(),
            name,
            generation,
            value,
        };
        true
    }

    /// Record the L1a store cell after a full-[[Set]] write completed on
    /// `base.name` (the store cell missed or was cold): when the write left
    /// `name` an own writable data property — an in-place update or a fresh
    /// define, not a setter-invoked accessor — resolve its vector slot and
    /// cache (id, name, generation, slot) so the next write takes
    /// `warm_store_put`. Also fronts the read-side value cell with the
    /// stored value: the full path bumped the generation, so the next read
    /// would otherwise re-resolve. No-op for every other outcome.
    pub(crate) fn warm_store_record(agent: &mut Agent, base: &Value, name: crux::AtomId) {
        let Some(object) = Self::store_cell_object(base) else {
            return;
        };
        let key = PropertyKey::String(name);
        let Some(slot) = object.property_slot(&key) else {
            return;
        };
        let props = object.properties.borrow();
        let Some((stored, property)) = props.get(slot) else {
            return;
        };
        if *stored != key {
            return;
        }
        let crux::object::PropertyKind::Data { value, writable } = &property.kind else {
            return;
        };
        if !*writable {
            return;
        }
        let value = *value;
        // Pin the inline-field mirror (map id + offset) when the object's
        // map describes the key: the next warm write mirrors the field at
        // the pinned offset without the descriptor scan. Dictionary-mode
        // and vector-only properties record no mirror.
        let (map_id, field) = match object.map_store_field(&key) {
            Some((map_id, field)) => (map_id, field as u8),
            None => (0, MEMBER_WRITE_FIELD_NONE),
        };
        let generation = object.generation();
        let write_index = Self::member_write_cell_index(object.id(), name);
        agent.member_write_cells[write_index] = Some(MemberWriteCell {
            id: object.id(),
            name,
            generation,
            slot,
            map_id,
            field,
        });
        // The read-side value cell keeps the SMALL table's index.
        let read_index = Self::member_cell_index(object.id(), name);
        agent.member_value_cells[read_index] = MemberValueCell {
            id: object.id(),
            name,
            generation,
            value,
        };
    }

    /// The cached read of `object[index]` — an own data element of a plain
    /// Array at the direct-mapped slot, re-validated against the stored key
    /// atom. `None` falls back to the full Get (which then re-resolves).
    /// The fronting value cache (Cut 35 slice 13) returns the element with
    /// no property-vector borrow when the array's generation matches.
    pub(crate) fn array_element_get(
        agent: &mut Agent,
        object: &Value,
        index: u64,
    ) -> Option<Value> {
        let ValueKind::Object(object) = object.kind() else {
            return None;
        };
        if !matches!(object.kind, crux::object::ObjectKind::Array(_)) {
            return None;
        }
        // Dense fast path: the buffer is authoritative — the element is the
        // slot (a hole reads absent, so the caller's full Get sees the
        // chain). The value cell below stays valid because buffer writes
        // bump the generation.
        if let crux::object::ObjectKind::Array(slots) = &object.kind
            && slots.dense.get()
        {
            let value = slots.elements.borrow().get(index as usize).and_then(|e| *e);
            if let Some(value) = value {
                let cache_index = Self::array_element_index(object.id(), index);
                agent.array_element_value_cells[cache_index] = Some(ArrayElementValueCell {
                    id: object.id(),
                    index,
                    generation: object.generation(),
                    value,
                });
            }
            return value;
        }
        let cache_index = Self::array_element_index(object.id(), index);
        if let Some(cell) = agent.array_element_value_cells[cache_index].as_ref()
            && cell.id == object.id()
            && cell.index == index
            && cell.generation == object.generation()
        {
            return Some(cell.value);
        }
        let (cached_id, cached_index, atom, slot) = agent.array_element_cells[cache_index]?;
        if cached_id != object.id() || cached_index != index {
            return None;
        }
        let props = object.properties.borrow();
        let (key, property) = props.get(slot)?;
        if *key != PropertyKey::String(atom) {
            return None;
        }
        match &property.kind {
            crux::object::PropertyKind::Data { value, .. } => {
                let value = *value;
                agent.array_element_value_cells[cache_index] = Some(ArrayElementValueCell {
                    id: object.id(),
                    index,
                    generation: object.generation(),
                    value,
                });
                Some(value)
            }
            _ => None,
        }
    }

    /// Resolve and cache the slot of `object`'s own data element at `index`.
    fn resolve_array_element(agent: &mut Agent, object: &Value, index: u64) {
        let ValueKind::Object(object) = object.kind() else {
            return;
        };
        if !matches!(object.kind, crux::object::ObjectKind::Array(_)) {
            return;
        }
        // Dense: the value cell is the buffer slot directly (the generation
        // catches a later write or spill); a hole caches nothing.
        if let crux::object::ObjectKind::Array(slots) = &object.kind
            && slots.dense.get()
        {
            let value = slots.elements.borrow().get(index as usize).and_then(|e| *e);
            if let Some(value) = value {
                let cache_index = Self::array_element_index(object.id(), index);
                agent.array_element_value_cells[cache_index] = Some(ArrayElementValueCell {
                    id: object.id(),
                    index,
                    generation: object.generation(),
                    value,
                });
            }
            return;
        }
        // Array element keys are the canonical interned index strings, so
        // the lazy property index finds the slot in O(1) (a linear scan of
        // the whole vector would make sequential element fills quadratic).
        let atom = PropertyKey::from_utf8(&index.to_string());
        let PropertyKey::String(atom) = atom else {
            return;
        };
        if let Some(slot) = object.property_slot(&PropertyKey::String(atom)) {
            let props = object.properties.borrow();
            if let Some((stored, property)) = props.get(slot)
                && *stored == PropertyKey::String(atom)
                && let crux::object::PropertyKind::Data { value, .. } = &property.kind
            {
                let cache_index = Self::array_element_index(object.id(), index);
                agent.array_element_cells[cache_index] = Some((object.id(), index, atom, slot));
                agent.array_element_value_cells[cache_index] = Some(ArrayElementValueCell {
                    id: object.id(),
                    index,
                    generation: object.generation(),
                    value: *value,
                });
            }
        }
    }

    /// The direct-mapped cache index for an array's length.
    fn array_length_index(object_id: u64) -> usize {
        object_id as usize & (MEMBER_CELLS - 1)
    }

    /// The length of a plain Array — always the first property-vector entry
    /// (the stock Array iterator re-reads it every step, so this matches).
    /// The fronting length cache (Cut 35 slice 13) skips the borrow and
    /// number conversion when the array's generation matches. Defensively
    /// falls back to the generic read.
    pub(crate) fn array_length(agent: &mut Agent, array: &Value) -> Result<u64, JsError> {
        let ValueKind::Object(obj) = array.kind() else {
            return Err(JsError::new(
                ErrorKind::TypeError,
                "Array length of a non-object".into(),
            ));
        };
        let cache_index = Self::array_length_index(obj.id());
        if let Some(cell) = agent.array_length_cells[cache_index].as_ref()
            && cell.id == obj.id()
            && cell.generation == obj.generation()
        {
            return Ok(cell.length);
        }
        // Dense: the cell is authoritative (the mirror is kept in sync, but
        // the cell skips the borrow and number conversion).
        if let crux::object::ObjectKind::Array(slots) = &obj.kind
            && slots.dense.get()
        {
            let length = crux::convert::to_length(slots.length.get());
            agent.array_length_cells[cache_index] = Some(ArrayLengthCell {
                id: obj.id(),
                generation: obj.generation(),
                length,
            });
            return Ok(length);
        }
        let props = obj.properties.borrow();
        if let Some((_, property)) = props.first()
            && let crux::object::PropertyKind::Data { value, .. } = &property.kind
        {
            let number = crate::context::to_number(agent, value)?;
            let length = crux::convert::to_length(number);
            agent.array_length_cells[cache_index] = Some(ArrayLengthCell {
                id: obj.id(),
                generation: obj.generation(),
                length,
            });
            return Ok(length);
        }
        let length_value =
            crate::context::get_property(agent, array, &JsString::from_utf8("length"), *array)?;
        Ok(crux::convert::to_length(crate::context::to_number(
            agent,
            &length_value,
        )?))
    }

    /// The fused relational-imm loop test on a declared top-level var: read
    /// the global binding, abstract-compare against the constant, jump to
    /// `target` when the test is false — exactly what
    /// `LoadGlobal; BinaryImm; JumpIfFalse` computes. The common shape (a
    /// Number counter vs a numeric limit) compares directly off the cell
    /// with no `apply_binary` round-trip.
    fn jump_if_rel_global(
        &mut self,
        agent: &mut Agent,
        op: BinaryOp,
        name: crux::AtomId,
        imm: f64,
        target: usize,
    ) -> Result<(), JsError> {
        if let Some((cached_name, slot)) = agent.global_cells[Self::global_cell_index(name)]
            && cached_name == name
        {
            let global = self.global_object(agent)?;
            let props = global.properties.borrow();
            if let Some((key, property)) = props.get(slot)
                && *key == PropertyKey::String(name)
                && let crux::object::PropertyKind::Data { value, .. } = &property.kind
                && let Some(num) = value.as_number()
            {
                // JS relational semantics for two numbers: NaN comparisons
                // are false, matching Rust's f64 comparisons.
                let pass = match op {
                    BinaryOp::LessThan => num < imm,
                    BinaryOp::LessEqual => num <= imm,
                    BinaryOp::GreaterThan => num > imm,
                    BinaryOp::GreaterEqual => num >= imm,
                    _ => unreachable!("JumpIfRelGlobalImm with a non-relational op"),
                };
                if !pass {
                    self.ip = target;
                }
                return Ok(());
            }
        }
        let left = self.load_global_value(agent, name)?;
        let right = Value::Number(imm);
        let value = crate::expr::apply_binary(agent, op, &left, &right)?;
        if !crux::convert::to_boolean(&value) {
            self.ip = target;
        }
        Ok(())
    }

    /// The fused canonical loop's test `var <op> LIMIT` (see `Step::FastLoop`):
    /// a Number counter vs a Number limit compares directly (JS relational
    /// semantics for two numbers — NaN is false, matching Rust's f64
    /// comparisons); a non-number falls back to the general `apply_binary`
    /// boolean. The limit is a literal, a frame slot, or a declared global —
    /// the binding forms re-read the limit every iteration, matching the
    /// general path's per-iteration evaluation.
    fn fast_loop_test(
        &mut self,
        agent: &mut Agent,
        var: FastLoopVar,
        op: BinaryOp,
        limit: RelLimit,
    ) -> Result<bool, JsError> {
        // The dedicated field holds the loop's Number counter (the acc-path
        // gates admit only Number inits/stores) — compare the raw f64
        // directly against an immediate limit (JS relational semantics for
        // two numbers: NaN compares false, matching Rust's f64
        // comparisons); a binding limit goes through the shared value
        // comparison below.
        if matches!(var, FastLoopVar::Counter)
            && let RelLimit::Imm(imm) = limit
        {
            return Ok(match op {
                BinaryOp::LessThan => self.loop_counter < imm,
                BinaryOp::LessEqual => self.loop_counter <= imm,
                BinaryOp::GreaterThan => self.loop_counter > imm,
                BinaryOp::GreaterEqual => self.loop_counter >= imm,
                _ => unreachable!("FastLoop with a non-relational op"),
            });
        }
        let value = match var {
            FastLoopVar::Slot(slot) => {
                let value = *self.frame_get(slot);
                if value.is_uninitialized() {
                    return Err(JsError::new(
                        ErrorKind::ReferenceError,
                        "Cannot access a binding before initialization".into(),
                    ));
                }
                value
            }
            FastLoopVar::Global(name) => self.load_global_value(agent, name)?,
            FastLoopVar::Counter => Value::Number(self.loop_counter),
        };
        let right = match limit {
            RelLimit::Imm(imm) => Value::Number(imm),
            RelLimit::Slot(slot) => {
                let right = *self.frame_get(slot);
                if right.is_uninitialized() {
                    return Err(JsError::new(
                        ErrorKind::ReferenceError,
                        "Cannot access a binding before initialization".into(),
                    ));
                }
                right
            }
            // The warmed value cell first (the Cut 36 probe — a script
            // global's own data value, re-validated by name + generation;
            // `store_global_value` mirrors it, so a body that writes the
            // limit is observed), else the full resolve.
            RelLimit::Global(name) => match self.try_global_cell_read(agent, name) {
                Some(value) => value,
                None => self.load_global_value(agent, name)?,
            },
        };
        if let (Some(num), Some(limit_num)) = (value.as_number(), right.as_number()) {
            return Ok(match op {
                BinaryOp::LessThan => num < limit_num,
                BinaryOp::LessEqual => num <= limit_num,
                BinaryOp::GreaterThan => num > limit_num,
                BinaryOp::GreaterEqual => num >= limit_num,
                _ => unreachable!("FastLoop with a non-relational op"),
            });
        }
        Ok(crux::convert::to_boolean(&crate::expr::apply_binary(
            agent, op, &value, &right,
        )?))
    }

    /// The fused canonical loop's increment `var++`/`var--` (see
    /// `Step::FastLoop`): a Number counter updates in place; other values go
    /// through the general `++`/`--` machinery.
    fn fast_loop_inc(
        &mut self,
        agent: &mut Agent,
        var: FastLoopVar,
        inc: UpdateOp,
    ) -> Result<(), JsError> {
        match var {
            FastLoopVar::Slot(slot) => {
                let old = *self.frame_get(slot);
                if old.is_uninitialized() {
                    return Err(JsError::new(
                        ErrorKind::ReferenceError,
                        "Cannot access a binding before initialization".into(),
                    ));
                }
                let new = if let Some(num) = old.as_number() {
                    let delta = if matches!(inc, UpdateOp::Increment) {
                        1.0
                    } else {
                        -1.0
                    };
                    Value::Number(num + delta)
                } else {
                    update_value(agent, &inc, &old)?.1
                };
                *self.frame_get_mut(slot) = new;
            }
            FastLoopVar::Global(name) => {
                self.update_global(agent, name, inc, true)?;
            }
            // Cut 17: the counter lives in the dedicated `loop_counter`
            // field — a raw f64 (Cut 35 slice 22) that only ever holds
            // Numbers, so the increment is a plain float op.
            FastLoopVar::Counter => {
                let delta = if matches!(inc, UpdateOp::Increment) {
                    1.0
                } else {
                    -1.0
                };
                self.loop_counter += delta;
            }
        }
        Ok(())
    }

    /// The fused canonical loop's counter prologue (Cut 17): load the
    /// binding's current value into the `loop_counter` field
    /// (`Step::FastLoopBind`). The acc-path gate requires the init to be a
    /// Number, so the field takes the value's numeric form.
    fn fast_loop_bind(&mut self, agent: &mut Agent, var: FastLoopVar) -> Result<(), JsError> {
        let value = match var {
            FastLoopVar::Slot(slot) => *self.frame_get(slot),
            FastLoopVar::Global(name) => self.load_global_value(agent, name)?,
            FastLoopVar::Counter => unreachable!("FastLoopBind on the counter field itself"),
        };
        debug_assert!(
            value.is_number(),
            "the acc-path loop init is gated to a Number"
        );
        self.loop_counter = value.as_number().unwrap_or(0.0);
        Ok(())
    }

    /// The fused canonical loop's counter epilogue (Cut 17): write the
    /// `loop_counter` field back to the binding (`Step::FastLoopStore`).
    fn fast_loop_store(&mut self, agent: &mut Agent, var: FastLoopVar) -> Result<(), JsError> {
        let value = Value::Number(self.loop_counter);
        match var {
            FastLoopVar::Slot(slot) => *self.frame_get_mut(slot) = value,
            FastLoopVar::Global(name) => self.store_global_value(agent, name, value)?,
            FastLoopVar::Counter => unreachable!("FastLoopStore on the counter field itself"),
        }
        Ok(())
    }

    fn array_index(&mut self) -> Result<&mut usize, JsError> {
        self.array_index_stack.last_mut().ok_or_else(|| {
            JsError::new(
                ErrorKind::SyntaxError,
                "Array step without an array literal".into(),
            )
        })
    }

    pub(crate) fn restore_env(&mut self, env: EnvRef, depth: usize) {
        // A control transfer's leave_scopes may have pre-popped envs a
        // finally's frame restore must re-establish: the finally body runs
        // with the try-entry environment stack intact so its own abrupt
        // control (a `break`/`continue` inside the finally) unwinds against
        // the same levels.
        while self.env_stack.len() < depth {
            self.env_stack.push(env);
        }
        self.env_stack.truncate(depth);
        self.lexical_env = env;
    }

    /// Run until suspension or completion. `resume` delivers the value of the
    /// last suspension: a normal value for `yield`/`await` continuations, or
    /// an abrupt completion that the driver has decided reaches this VM (the
    /// `yield*` delegate case; plain `yield`/`await` abrupts are handled by
    /// the driver).
    pub fn run(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        resume: Resume,
    ) -> Result<VmOutcome, JsError> {
        match resume {
            Resume::Normal(value) => self.stack.push(value),
            Resume::Throw(value) => {
                self.resume_abrupt = Some(ResumeAbrupt::Throw(value));
                self.stack.push(value);
            }
            Resume::Return(value) => {
                self.resume_abrupt = Some(ResumeAbrupt::Return(value));
                self.stack.push(value);
            }
        }
        self.run_inner(agent, body)
    }

    /// Run from the start of the body (no resume value).
    pub fn start(&mut self, agent: &mut Agent, body: &CompiledBody) -> Result<VmOutcome, JsError> {
        self.run_inner(agent, body)
    }

    /// The throw machinery entry used by await-rejection resumes: run the
    /// throw through the handler table. The abrupt-completion handling
    /// (closing a suspended destructure's iterators, `throw_machinery`)
    /// allocates before `run_inner` registers this Vm, so the Vm is rooted
    /// for the whole call (GC-2: its heap-buffered stacks would otherwise be
    /// unrooted while those closes fire stress collections).
    pub fn run_abrupt(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        resume: Resume,
    ) -> Result<VmOutcome, JsError> {
        ACTIVE_RUNS.with(|stack| {
            stack.borrow_mut().push(ActiveRun {
                vm: self as *const Vm,
                body: body as *const CompiledBody,
                jit_buffer: None,
            });
        });
        let result = self.run_abrupt_inner(agent, body, resume);
        ACTIVE_RUNS.with(|stack| {
            stack.borrow_mut().pop();
        });
        result
    }

    fn run_abrupt_inner(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        resume: Resume,
    ) -> Result<VmOutcome, JsError> {
        match resume {
            Resume::Normal(value) => {
                if self.pending_disposal.is_some() {
                    // The awaited async-dispose settled: keep driving the
                    // scope disposal.
                    return self.resume_pending_disposal(agent, body, Ok(value));
                }
                self.stack.push(value);
                self.run_inner(agent, body)
            }
            Resume::Throw(value) => {
                if self.pending_disposal.is_some() {
                    // A rejected async-dispose is a throwing disposal, folded
                    // into the disposal completion — never routed through the
                    // body's handler table.
                    return self.resume_pending_disposal(agent, body, Err(value));
                }
                // A rejected for-await-of `next()` promise leaves the iterator
                // open (spec 14.7.5.5 — only body abrupt completions close):
                // drop the record without closing it.
                if self.async_for_of_stepping {
                    self.async_for_of_stack.pop();
                    self.async_for_of_boundaries.pop();
                    self.async_for_of_stepping = false;
                }
                // A resumed `yield`/`await` inside a destructure propagates
                // the abrupt completion through the pattern, closing its
                // iterators (spec 13.15.5.2 step 5 + 7.4.11).
                self.close_destructures_abrupt(agent, false)?;
                match self.throw_machinery(agent, body, value)? {
                    CtlResult::Continue => self.run_inner(agent, body),
                    CtlResult::Done(outcome) => Ok(outcome),
                }
            }
            Resume::Return(value) => {
                match self.close_destructures_abrupt(agent, true) {
                    Ok(()) => match self.control_transfer(agent, body, Ctl::Return { value })? {
                        CtlResult::Continue => self.run_inner(agent, body),
                        CtlResult::Done(outcome) => Ok(outcome),
                    },
                    // A throwing or non-object `return` replaces the return
                    // completion with that error (spec 7.4.11 steps 6-8).
                    Err(error) => self.throw_error(agent, body, error),
                }
            }
        }
    }

    /// Close every active destructure iterator when a suspended `yield`/
    /// `await` inside a pattern is aborted (spec 13.15.5.2/13.15.5.5: an
    /// abrupt element or rest evaluation closes the not-done iterator with
    /// the abrupt completion). With a return completion the innermost close
    /// runs first and a throwing or non-object `return` becomes the new
    /// completion, so the remaining iterators close with the throw flavor
    /// (spec 7.4.11 steps 4-8); with a throw completion all closes swallow.
    pub(crate) fn close_destructures_abrupt(
        &mut self,
        agent: &mut Agent,
        completion_is_return: bool,
    ) -> Result<(), JsError> {
        let mut first_error: Option<JsError> = None;
        while let Some(index) = self.destructure_stack.len().checked_sub(1) {
            let iterator = self.destructure_stack[index].clone();
            let done = self.destructure_done.get(index).copied().unwrap_or(false);
            if !done {
                if completion_is_return && first_error.is_none() {
                    if let Err(error) = iterator_close(agent, &iterator) {
                        first_error = Some(error);
                    }
                } else {
                    crate::expr::iterator_close_throw(agent, &iterator)?;
                }
            }
            self.destructure_stack.pop();
            self.destructure_done.pop();
        }
        self.destructure_obj_stack.clear();
        self.destructure_assign_keys.clear();
        self.destructure_excluded.clear();
        match first_error {
            Some(error) => Err(error),
            None => Ok(()),
        }
    }

    /// Close every active destructure iterator when a step error escapes a
    /// destructuring pattern (spec 13.15.5.2 step 5): the first throwing
    /// `return` replaces the error (spec 7.4.11). The caller gates on
    /// `!destructure_stepping` (a `next()` error leaves the iterator open).
    /// Shared by `run_inner`'s Err arm and the JIT's error path (Cut 59);
    /// also clears the object-pattern stacks.
    pub(crate) fn close_destructures_throw(&mut self, agent: &mut Agent) -> Result<(), JsError> {
        let mut close_error: Option<JsError> = None;
        while let Some(index) = self.destructure_stack.len().checked_sub(1) {
            let iterator = self.destructure_stack[index].clone();
            let done = self.destructure_done.get(index).copied().unwrap_or(false);
            if !done
                && let Err(e) = crate::expr::iterator_close_throw(agent, &iterator)
                && close_error.is_none()
            {
                close_error = Some(e);
            }
            self.destructure_stack.pop();
            self.destructure_done.pop();
        }
        self.destructure_obj_stack.clear();
        self.destructure_assign_keys.clear();
        self.destructure_excluded.clear();
        match close_error {
            Some(error) => Err(error),
            None => Ok(()),
        }
    }

    /// Close the active for-of iterators with a throw completion: the
    /// original error wins, a throwing `return` (or `return` lookup) is
    /// swallowed (spec 7.4.11 steps 6-7, mirroring the tree-walker's
    /// eval_for_of error paths).
    pub(crate) fn close_for_of_throw(&mut self, agent: &mut Agent) {
        while let Some(entry) = self.for_of_stack.pop() {
            if let ForOfEntry::Generic(iterator) = entry {
                let _ = crate::expr::iterator_close_throw(agent, &iterator);
            }
        }
        self.for_of_boundaries.clear();
        while let Some(iterator) = self.async_for_of_stack.pop() {
            let _ = crate::expr::iterator_close_throw(agent, &iterator);
        }
        self.async_for_of_boundaries.clear();
    }

    /// Close the active for-of iterators with a return completion: a throwing
    /// `return` replaces the return (spec 7.4.6), later closes swallow.
    fn close_for_of_return(&mut self, agent: &mut Agent) -> Result<(), JsError> {
        let mut first_error: Option<JsError> = None;
        while let Some(entry) = self.for_of_stack.pop() {
            if let ForOfEntry::Generic(iterator) = entry {
                if first_error.is_none() {
                    if let Err(e) = crate::expr::iterator_close(agent, &iterator) {
                        first_error = Some(e);
                    }
                } else {
                    let _ = crate::expr::iterator_close_throw(agent, &iterator);
                }
            }
        }
        let close = |agent: &mut Agent,
                     stack: &mut Vec<crate::expr::IteratorRecord>,
                     first_error: &mut Option<JsError>|
         -> Result<(), JsError> {
            while let Some(iterator) = stack.pop() {
                if first_error.is_none() {
                    if let Err(e) = crate::expr::iterator_close(agent, &iterator) {
                        *first_error = Some(e);
                    }
                } else {
                    let _ = crate::expr::iterator_close_throw(agent, &iterator);
                }
            }
            Ok(())
        };
        close(agent, &mut self.async_for_of_stack, &mut first_error)?;
        self.for_of_boundaries.clear();
        self.async_for_of_boundaries.clear();
        match first_error {
            Some(e) => Err(e),
            None => Ok(()),
        }
    }

    /// Close the iterators of for-of loops a `break`/`continue` exits (the
    /// compiled `ForOfClose` at each loop's end was skipped): a loop whose
    /// `(top, end)` span does not contain the transfer target.
    fn close_for_of_upto(&mut self, agent: &mut Agent, target: usize) -> Result<(), JsError> {
        while let Some(&(top, end)) = self.for_of_boundaries.last()
            && (target < top || target > end)
        {
            self.for_of_boundaries.pop();
            if let Some(ForOfEntry::Generic(iterator)) = self.for_of_stack.pop() {
                iterator_close(agent, &iterator)?;
            }
        }
        while let Some(&(top, end)) = self.async_for_of_boundaries.last()
            && (target < top || target > end)
        {
            self.async_for_of_boundaries.pop();
            if let Some(iterator) = self.async_for_of_stack.pop() {
                iterator_close(agent, &iterator)?;
            }
        }
        Ok(())
    }

    fn run_inner(&mut self, agent: &mut Agent, body: &CompiledBody) -> Result<VmOutcome, JsError> {
        // Cut 36 mirror: whether the running context's env chain is exactly
        // the global env — a certified body's `LoadIdent` then resolves at
        // the global env, so the read can serve the warmed global-value cell
        // instead of walking the env chain per step (the `clean_chain` gate
        // the JIT bakes into `JitCallContext`). Computed at run entry: only
        // an `env_constant` body skips the per-step context sync, so the
        // flag stays valid for the whole run there (the `LoadIdent` fast
        // path gates on `body.env_constant`).
        self.clean_chain = agent
            .running_context()
            .map(|context| {
                let env = context.lexical_environment;
                matches!(&*env, EnvRecord::Global(_)) && env.outer().is_none()
            })
            .unwrap_or(false);
        // GC-2: root this Vm and its compiled body for the run's duration —
        // a mid-execution stress collection must trace the active Vm
        // precisely (its heap-buffered stacks and the body's literal steps).
        ACTIVE_RUNS.with(|stack| {
            stack.borrow_mut().push(ActiveRun {
                vm: self as *const Vm,
                body: body as *const CompiledBody,
                jit_buffer: None,
            });
        });
        let result = self.run_inner_impl(agent, body);
        ACTIVE_RUNS.with(|stack| {
            stack.borrow_mut().pop();
        });
        result
    }

    fn run_inner_impl(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
    ) -> Result<VmOutcome, JsError> {
        // A proper tail call replaces the running body instead of recursing:
        // the handler swaps in the callee's body and the driver loops.
        let mut current = CurrentBody::Borrowed(body);
        // Record the agent for the duration so crux-side ECMAScript calls
        // (proxy traps reached through property access) can find the runtime.
        crux::function::with_agent(agent as *mut Agent as *mut (), || {
            loop {
                let body = current.get();
                match self.run_inner_inner(agent, body) {
                    Ok(VmOutcome::TailCall(next)) => {
                        current = CurrentBody::Owned(next);
                        // The tracked body must follow the tail call (the
                        // owned callee body outlives the borrowed one).
                        ACTIVE_RUNS.with(|stack| {
                            if let Some(last) = stack.borrow_mut().last_mut() {
                                last.body = current.get() as *const CompiledBody;
                            }
                        });
                    }
                    Ok(outcome) => return Ok(outcome),
                    // A step's engine error (a TypeError from a property access, a
                    // ReferenceError from an unresolved identifier, ...) inside a
                    // `try` is a thrown completion: route it through the handler
                    // table so `catch` sees it, like the interpreter path. Without
                    // a covering handler the original error propagates untouched.
                    Err(error) => {
                        // An error escaping a step while a destructuring pattern is
                        // in progress closes the not-done iterators (spec
                        // 13.15.5.2 step 5): the first throwing `return` replaces
                        // the error (spec 7.4.11). The tree-walker's
                        // array_assignment does the same on its error path. The
                        // JIT's error path shares the close (Cut 59).
                        let mut error = error;
                        if !self.destructure_stack.is_empty()
                            && !self.destructure_stepping
                            && let Err(e) = self.close_destructures_throw(agent)
                        {
                            error = e;
                        }
                        // An error escaping a for-of body or head closes the
                        // active iterators (spec 14.7.6.2: a head-binding error or
                        // abrupt body completion returns IteratorClose). A `next()`
                        // error is exempt: it propagates with the iterator open.
                        // An error covered by a handler whose catch resumes inside
                        // the loop body must leave the iterators intact — the loop
                        // continues (mirrors the `throw`-statement path, which only
                        // closes when the throw escapes).
                        let covered = self.try_stack.iter().any(|frame| {
                            body.handlers.get(frame.handler).is_some_and(|handler| {
                                self.ip >= handler.start && self.ip < handler.try_end
                            })
                        });
                        if !covered && !self.for_of_stepping {
                            self.close_for_of_throw(agent);
                        }
                        if covered {
                            // Route the engine error through the handler table
                            // like a thrown value, then CONTINUE the same loop —
                            // re-entering run_inner (throw_error) would recurse
                            // once per caught error and overflow the stack on a
                            // hot catch loop.
                            let value = match crate::builtins::error::to_throwable(agent, &error) {
                                Ok(value) => value,
                                Err(_) => error_message_value(&error),
                            };
                            match self.throw_machinery(agent, body, value)? {
                                CtlResult::Continue => continue,
                                CtlResult::Done(outcome) => return Ok(outcome),
                            }
                        } else {
                            // spec 9.4.3: an error escaping the body disposes the
                            // active scopes' `using` resources (innermost first),
                            // folding a throwing disposal into the error (the
                            // tree-walker's statement lists do the same).
                            let mut resources = Vec::new();
                            self.env_stack.drain_disposables(&mut resources);
                            if !resources.is_empty() {
                                let thrown = crate::promise::error_value(agent, &error);
                                if let Some(outcome) = self.start_scope_disposal(
                                    agent,
                                    body,
                                    resources,
                                    Completion::Throw(thrown),
                                    DisposalResume::ApplyCompletion,
                                )? {
                                    return Ok(outcome);
                                }
                            }
                            return Err(error);
                        }
                    }
                }
            }
        })
    }

    fn run_inner_inner(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
    ) -> Result<VmOutcome, JsError> {
        loop {
            let steps = &body.steps;
            let step = match steps.get(self.ip) {
                Some(step) => step,
                None => {
                    // Fell off the end: the body completes with the
                    // statement-list completion — empty when the last
                    // statement produced no value.
                    return Ok(VmOutcome::Completed(if self.completion_is_empty {
                        Completion::Empty
                    } else {
                        Completion::Normal(self.completion)
                    }));
                }
            };
            self.ip += 1;
            // Steps that read the running context (resolve_binding, member
            // helpers, closure creation) see the VM's lexical environment
            // through the context; the sync is skipped when it has not
            // changed since the last step (an `Rc` pointer comparison). A
            // certified body's env is constant (every binding is a frame
            // slot, no `with`/`try`/`switch`/`for-in`/`for-of`/`using`), so
            // the whole sync is skipped for it.
            if !body.env_constant
                && let Ok(context) = agent.running_context_mut()
                && !Handle::ptr_eq(context.lexical_environment, self.lexical_env)
            {
                context.lexical_environment = self.lexical_env
            }
            match step {
                Step::LoadIdent { name } => {
                    // Cut 36 mirror: with a clean chain (the context env IS
                    // the global env, and this env-constant body adds no envs
                    // mid-run) the name resolves at the global env — serve the
                    // warmed global-value cell directly, else fall back to the
                    // full resolve (which warms the cell when the binding is a
                    // global-object data property, so a hot loop's second read
                    // hits the native load).
                    if body.env_constant
                        && self.clean_chain
                        && let Some(value) = self.try_global_cell_read(agent, *name)
                    {
                        self.stack.push(value);
                        continue;
                    }
                    let reference =
                        crate::context::resolve_binding(agent, &crux::lookup(*name), self.strict)?;
                    let value = crate::context::get_value(agent, &reference)?;
                    if body.env_constant
                        && self.clean_chain
                        && let crate::context::ReferenceBase::Environment(env) = &reference.base
                        && let EnvRecord::Global(_) = &**env
                        && !env.has_lexical_declaration(&crux::lookup(*name))
                    {
                        // The JIT's `load_ident` warm gate: a global-object
                        // binding (var/function/undeclared), never a top-level
                        // `let`/`const`/`class` (a declarative shadow would
                        // not bump the global object's generation).
                        self.warm_global_cell(agent, *name, value);
                    }
                    self.stack.push(value);
                }
                Step::LoadLocal { slot } => {
                    let value = *self.frame_get(*slot);
                    if value.is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    self.stack.push(value);
                }
                Step::StoreLocal { slot } => {
                    let value = self.pop();
                    if self.frame_get(*slot).is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    *self.frame_get_mut(*slot) = value;
                }
                Step::FusedStoreLocal { slot } => {
                    let value = self.pop();
                    if self.frame_get(*slot).is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    *self.frame_get_mut(*slot) = value;
                    self.completion = value;
                    self.completion_is_empty = false;
                }
                Step::FusedStoreGlobal { name } => {
                    let value = self.pop();
                    self.store_global_value(agent, *name, value)?;
                    self.completion = value;
                    self.completion_is_empty = false;
                }
                Step::LoadGlobal { name } => {
                    let value = self.load_global_value(agent, *name)?;
                    self.stack.push(value);
                }
                Step::StoreGlobal { name } => {
                    let value = self.pop();
                    self.store_global_value(agent, *name, value)?;
                }
                Step::InitLocal { slot } => {
                    let value = self.pop();
                    *self.frame_get_mut(*slot) = value;
                }
                Step::UpdateLocal { slot, op, prefix } => {
                    let old = *self.frame_get(*slot);
                    if old.is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    *self.frame_get_mut(*slot) = new;
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::Inc { slot } => {
                    let old = *self.frame_get(*slot);
                    if old.is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    *self.frame_get_mut(*slot) = update_value(agent, &UpdateOp::Increment, &old)?.1;
                }
                Step::Dec { slot } => {
                    let old = *self.frame_get(*slot);
                    if old.is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    *self.frame_get_mut(*slot) = update_value(agent, &UpdateOp::Decrement, &old)?.1;
                }
                Step::UpdateGlobal { name, op, prefix } => {
                    let value = self.update_global(agent, *name, *op, *prefix)?;
                    self.stack.push(value);
                }
                Step::IncGlobal { name } => {
                    self.update_global(agent, *name, UpdateOp::Increment, true)?;
                }
                Step::DecGlobal { name } => {
                    self.update_global(agent, *name, UpdateOp::Decrement, true)?;
                }
                Step::CreateFunction {
                    function,
                    strict,
                    outer_chain,
                    per_iteration_chain,
                } => {
                    let env = agent.running_context()?.lexical_environment;
                    let value = crate::function::instantiate_function_expression(
                        agent,
                        function,
                        env,
                        *strict,
                        outer_chain.clone(),
                        per_iteration_chain.clone(),
                    )?;
                    self.stack.push(value);
                }
                Step::CreateArrow {
                    is_async,
                    params,
                    body,
                    strict,
                    outer_chain,
                    per_iteration_chain,
                } => {
                    let env = agent.running_context()?.lexical_environment;
                    let value = crate::function::instantiate_arrow(
                        agent,
                        *is_async,
                        params.as_slice(),
                        body,
                        env,
                        *strict,
                        outer_chain.clone(),
                        per_iteration_chain.clone(),
                    )?;
                    self.stack.push(value);
                }
                Step::NewTarget => {
                    // Cut 62: the certified path's `new.target` is the
                    // per-run `current_new_target` (the frame-slot model
                    // creates no FunctionEnv to carry it); the env path
                    // reads the running this-environment's binding.
                    let value = if self.body_context.is_some() {
                        self.current_new_target.unwrap_or(Value::Undefined)
                    } else {
                        get_new_target(agent)?
                    };
                    self.stack.push(value);
                }
                Step::RegExpLiteral { pattern, flags } => {
                    let value = crate::expr::eval_regexp_literal(agent, pattern, flags)?;
                    self.stack.push(value);
                }
                Step::FunctionDecl { stmt } => {
                    let StmtKind::FunctionDecl(function) = &stmt.kind else {
                        unreachable!("FunctionDecl step carries a function declaration");
                    };
                    if function.statement_position && !self.strict {
                        crate::eval::eval_statement_position_function(
                            agent,
                            function,
                            stmt,
                            self.strict,
                        )?;
                    } else {
                        crate::eval::eval_function_declaration(agent, function, self.strict)?;
                    }
                }
                Step::FunctionDeclInit {
                    function,
                    frame_slot,
                    context_slot,
                    outer_chain,
                    per_iteration_chain,
                    ..
                } => {
                    // A certified body's hoisted top-level function
                    // declaration: instantiate the closure against the
                    // capture context (the binding was created by the
                    // certified layout) and store it. The declaration runs
                    // at body entry, so it sees only the INHERITED
                    // per-iteration chain (the loops inside this body have
                    // not started).
                    let env = agent.running_context()?.lexical_environment;
                    let value = crate::function::instantiate_function(
                        agent,
                        function,
                        env,
                        self.strict,
                        outer_chain.clone(),
                        per_iteration_chain.clone(),
                        false,
                    )?;
                    if let Some(slot) = frame_slot {
                        *self.frame_get_mut(*slot) = value;
                    } else if let Some(index) = context_slot {
                        let env = self.context_chain_env(0)?;
                        context_env(&env).set_slot(*index, value);
                    } else {
                        unreachable!(
                            "FunctionDeclInit without a binding slot (the scan allocated one)"
                        );
                    }
                }
                Step::Push(value) => self.stack.push(*value),
                Step::Pop => {
                    self.pop();
                }
                Step::Dup => {
                    let top = self.pop();
                    self.stack.push(top);
                    self.stack.push(top);
                }
                Step::Dup2 => {
                    let b = self.pop();
                    let a = self.pop();
                    self.stack.push(a);
                    self.stack.push(b);
                    self.stack.push(a);
                    self.stack.push(b);
                }
                Step::Unary(op) => {
                    let operand = self.pop();
                    let value = crate::expr::eval_unary_value(agent, op, operand)?;
                    self.stack.push(value);
                }
                Step::Binary(op) => {
                    let right = self.pop();
                    let left = self.pop();
                    let value = crate::expr::apply_binary(agent, *op, &left, &right)?;
                    self.stack.push(value);
                }
                Step::BinaryImm { op, imm } => {
                    let left = self.pop();
                    // The number-number arithmetic shape inlines `apply_binary`
                    // (two tag checks + a direct op) — the general evaluator
                    // adds a call and the RHS tag check for no semantic gain.
                    let value = if let Some(num) = left.as_number() {
                        match op {
                            BinaryOp::Add => Value::Number(num + *imm),
                            BinaryOp::Sub => Value::Number(num - *imm),
                            BinaryOp::Mul => Value::Number(num * *imm),
                            BinaryOp::Div => Value::Number(num / *imm),
                            BinaryOp::Rem => Value::Number(num % *imm),
                            BinaryOp::Exp => Value::Number(num.powf(*imm)),
                            _ => {
                                crate::expr::apply_binary(agent, *op, &left, &Value::Number(*imm))?
                            }
                        }
                    } else {
                        crate::expr::apply_binary(agent, *op, &left, &Value::Number(*imm))?
                    };
                    self.stack.push(value);
                }
                Step::GetMemberName { name } => {
                    let object = self.pop();
                    let value = self.get_member_name(agent, object, *name)?;
                    self.stack.push(value);
                }
                Step::GetMemberComputed => {
                    let key = self.pop();
                    let object = self.pop();
                    let value = self.get_member_computed(agent, object, key)?;
                    self.stack.push(value);
                }
                Step::GetMemberComputedKeep => {
                    // Compound/update paths: the (object, key) pair was
                    // duplicated; convert the key once (after the nullish
                    // check, spec 13.3.3 step 3 before step 6) and leave the
                    // converted key on the stack for the write, so the key's
                    // ToPropertyKey runs exactly once (spec 13.15.4).
                    let key = self.pop();
                    let object = self.pop();
                    if is_nullish(&object) {
                        return Err(nullish_error("Cannot read properties of null"));
                    }
                    let key = crate::context::to_property_key(agent, &key)?;
                    let value = crate::context::get_property_key(agent, &object, &key, object)?;
                    self.pop(); // the write copy of the raw key
                    let key = match key {
                        PropertyKey::String(id) => Value::String(Handle::new(crux::lookup(id))),
                        PropertyKey::Symbol(symbol) => Value::Symbol(symbol),
                    };
                    self.stack.push(key);
                    self.stack.push(value);
                }
                Step::GetSuperComputedKeep => {
                    // Mirror of GetMemberComputedKeep for super: the key is
                    // converted once and the converted value left for the
                    // write; the base captured by GetSuperBase is used, not
                    // recomputed (a key whose toString mutates the prototype
                    // must still see the original base, spec 13.3.7.1).
                    let key = self.pop();
                    let base = self.pop();
                    let key = crate::context::to_property_key(agent, &key)?;
                    let this = self.vm_this_binding(agent)?;
                    let value = crate::context::get_property_key(agent, &base, &key, this)?;
                    self.pop(); // the write copy of the raw key
                    let key = match key {
                        PropertyKey::String(id) => Value::String(Handle::new(crux::lookup(id))),
                        PropertyKey::Symbol(symbol) => Value::Symbol(symbol),
                    };
                    self.stack.push(key);
                    self.stack.push(value);
                }
                Step::GetSuperName { name } => {
                    let base = self.pop();
                    let this = self.vm_this_binding(agent)?;
                    let value =
                        crate::context::get_property(agent, &base, &crux::lookup(*name), this)?;
                    self.stack.push(value);
                }
                Step::GetSuperComputed => {
                    let key = self.pop();
                    let base = self.pop();
                    let key = crate::context::to_property_key(agent, &key)?;
                    let this = self.vm_this_binding(agent)?;
                    let value = crate::context::get_property_key(agent, &base, &key, this)?;
                    self.stack.push(value);
                }
                Step::GetPrivate { atom } => {
                    let object = self.pop();
                    let name_id = crate::context::resolve_private_name(agent, *atom)?.id;
                    let value = crate::context::private_get(agent, &object, name_id)?;
                    self.stack.push(value);
                }
                Step::ThisValue => {
                    let this = self.vm_this_binding(agent)?;
                    self.stack.push(this);
                }
                Step::GetSuperBase => {
                    // SuperProperty evaluation checks GetThisBinding first
                    // (spec 13.3.7.1): an uninitialized `this` in a derived
                    // constructor throws before the base is read or the key
                    // evaluates.
                    self.vm_this_binding(agent)?;
                    let base = self.vm_super_base(agent)?;
                    self.stack.push(base);
                }
                Step::AssignIdent { name, op, set_name } => {
                    self.assign_ident(agent, *name, *op, *set_name)?;
                }
                Step::AssignMemberName { name, op } => {
                    let value = self.pop();
                    let old = if is_compound_assign(op) {
                        Some(self.pop())
                    } else {
                        None
                    };
                    let object = self.pop();
                    if is_nullish(&object) {
                        return Err(nullish_error("Cannot set properties of null"));
                    }
                    self.assign_member(
                        agent,
                        object,
                        PropertyKeyName::Name(*name),
                        old,
                        value,
                        *op,
                    )?;
                }
                Step::AssignMemberComputed { op } => {
                    let value = self.pop();
                    let old = if is_compound_assign(op) {
                        Some(self.pop())
                    } else {
                        None
                    };
                    let key = self.pop();
                    let object = self.pop();
                    if let Some(old) = old {
                        if is_nullish(&object) {
                            return Err(nullish_error("Cannot set properties of null"));
                        }
                        let key = crate::context::to_property_key(agent, &key)?;
                        self.assign_member(
                            agent,
                            object,
                            PropertyKeyName::Key(key),
                            Some(old),
                            value,
                            *op,
                        )?;
                    } else {
                        self.assign_computed_plain(agent, object, key, value)?;
                    }
                }
                Step::AssignSuperName { name, op } => {
                    let value = self.pop();
                    let old = if is_compound_assign(op) {
                        Some(self.pop())
                    } else {
                        None
                    };
                    let base = self.pop();
                    self.assign_super(agent, base, PropertyKeyName::Name(*name), old, value, *op)?;
                }
                Step::AssignSuperComputed { op } => {
                    let value = self.pop();
                    let old = if is_compound_assign(op) {
                        Some(self.pop())
                    } else {
                        None
                    };
                    let key = self.pop();
                    let base = self.pop();
                    let key = crate::context::to_property_key(agent, &key)?;
                    self.assign_super(agent, base, PropertyKeyName::Key(key), old, value, *op)?;
                }
                Step::AssignPrivate { atom, op } => {
                    let value = self.pop();
                    let object = self.pop();
                    let name_id = crate::context::resolve_private_name(agent, *atom)?.id;
                    // Only a compound assignment reads the old value; a plain
                    // `=` must not invoke the getter (PrivateSet on an
                    // accessor runs the setter, spec 10.2.12.2).
                    let new = match *op {
                        AssignOp::Assign
                        | AssignOp::AndAssign
                        | AssignOp::OrAssign
                        | AssignOp::NullishAssign => value,
                        _ => {
                            let old = crate::context::private_get(agent, &object, name_id)?;
                            crate::expr::apply_compound(agent, *op, &old, &value)?
                        }
                    };
                    crate::context::private_set(agent, &object, name_id, new)?;
                    self.stack.push(new);
                }
                Step::Destructure { pattern } => {
                    let value = self.pop();
                    crate::binding::binding_initialization(
                        agent,
                        pattern,
                        value,
                        None,
                        self.strict,
                    )?;
                    self.stack.push(value);
                }
                Step::DestructureBegin => {
                    let value = self.pop();
                    let iterator = get_iterator(agent, &value)?;
                    self.destructure_stack.push(iterator);
                    self.destructure_done.push(false);
                }
                Step::DestructureNext => {
                    let index = self.destructure_stack.len().checked_sub(1).ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "DestructureNext without a destructure".into(),
                        )
                    })?;
                    let iterator = self.destructure_stack[index].clone();
                    // An abrupt iterator step does not close the iterator
                    // (the error path in `run_inner` skips the close while the
                    // flag is set; it stays set on the error path).
                    self.destructure_stepping = true;
                    match iterator_step(agent, &iterator) {
                        Ok(Some(value)) => {
                            self.destructure_stepping = false;
                            self.stack.push(value);
                        }
                        Ok(None) => {
                            self.destructure_stepping = false;
                            // The iterator is exhausted but the element still
                            // receives *undefined*: a default initializer must
                            // run (and may suspend) even after exhaustion.
                            self.destructure_done[index] = true;
                            self.stack.push(Value::Undefined);
                        }
                        Err(error) => return Err(error),
                    }
                }
                Step::DestructureUndef { use_default } => {
                    let value = self.pop();
                    if matches!(value.kind(), ValueKind::Undefined) {
                        self.ip = *use_default;
                    } else {
                        self.stack.push(value);
                    }
                }
                Step::DestructureRest => {
                    let index = self.destructure_stack.len().checked_sub(1).ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "DestructureRest without a destructure".into(),
                        )
                    })?;
                    let iterator = self.destructure_stack[index].clone();
                    // An abrupt step during the rest collection leaves the
                    // iterator open (mirroring DestructureNext); the flag stays
                    // set on the error path.
                    self.destructure_stepping = true;
                    let mut collected = Vec::new();
                    let stepped = loop {
                        match iterator_step(agent, &iterator) {
                            Ok(Some(value)) => collected.push(value),
                            Ok(None) => break Ok(()),
                            Err(error) => break Err(error),
                        }
                    };
                    match stepped {
                        Ok(()) => {
                            self.destructure_stepping = false;
                        }
                        Err(error) => return Err(error),
                    }
                    self.destructure_stack.pop();
                    self.destructure_done.pop();
                    let array = crate::builtins::array::array_from_values(agent, &collected)?;
                    self.stack.push(array);
                }
                Step::DestructureObjCoercible => {
                    let value = self.pop();
                    if matches!(value.kind(), ValueKind::Undefined | ValueKind::Null) {
                        return Err(JsError::new(
                            ErrorKind::TypeError,
                            "Cannot destructure null or undefined".into(),
                        ));
                    }
                    self.destructure_obj_stack.push(value);
                    self.destructure_excluded.push(Vec::new());
                }
                Step::DestructureObjKey { key } => {
                    let object = self.destructure_obj_stack.last().cloned().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "DestructureObjKey without an object".into(),
                        )
                    })?;
                    let value = crate::context::get_property_key(agent, &object, key, object)?;
                    self.stack.push(value);
                }
                Step::DestructureObjKeyComputed => {
                    let key = self.pop();
                    let object = self.destructure_obj_stack.last().cloned().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "DestructureObjKeyComputed without an object".into(),
                        )
                    })?;
                    let key = crate::context::to_property_key(agent, &key)?;
                    if let Some(frame) = self.destructure_excluded.last_mut() {
                        frame.push(key.clone());
                    }
                    let value = crate::context::get_property_key(agent, &object, &key, object)?;
                    self.stack.push(value);
                }
                Step::DestructureObjKeyStore => {
                    let key = self.pop();
                    self.destructure_assign_keys.push(key);
                }
                Step::DestructureObjKeyGet => {
                    let key = self.destructure_assign_keys.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "DestructureObjKeyGet without a stored key".into(),
                        )
                    })?;
                    let object = self.destructure_obj_stack.last().cloned().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "DestructureObjKeyGet without an object".into(),
                        )
                    })?;
                    let key = crate::context::to_property_key(agent, &key)?;
                    if let Some(frame) = self.destructure_excluded.last_mut() {
                        frame.push(key.clone());
                    }
                    let value = crate::context::get_property_key(agent, &object, &key, object)?;
                    self.stack.push(value);
                }
                Step::DestructureObjRest { excluded } => {
                    let object = self.destructure_obj_stack.last().cloned().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "DestructureObjRest without an object".into(),
                        )
                    })?;
                    let mut all = excluded.clone();
                    if let Some(frame) = self.destructure_excluded.last() {
                        all.extend(frame.iter().cloned());
                    }
                    let rest = crate::binding::rest_object(agent)?;
                    crate::binding::copy_data_properties_excluding(agent, &rest, &object, &all)?;
                    self.stack.push(Value::Object(rest));
                }
                Step::DestructureClose => {
                    if let Some(index) = self.destructure_stack.len().checked_sub(1) {
                        let done = self.destructure_done.get(index).copied().unwrap_or(false);
                        // Pop before closing: a throwing `return` then reaches
                        // `run_inner` with an empty destructure stack, so the
                        // error-path close does not close it a second time.
                        let iterator = self.destructure_stack.pop().unwrap();
                        self.destructure_done.pop();
                        if !done {
                            iterator_close(agent, &iterator)?;
                        }
                    }
                }
                Step::DestructureObjEnd => {
                    self.destructure_obj_stack.pop();
                    self.destructure_excluded.pop();
                }
                Step::DeclInit { pattern } => {
                    let value = self.pop();
                    crate::binding::binding_initialization(
                        agent,
                        pattern,
                        value,
                        Some(&self.lexical_env),
                        self.strict,
                    )?;
                    self.stack.push(value);
                }
                Step::ResolveVarIdent { name } => {
                    let reference =
                        crate::context::resolve_binding(agent, &crux::lookup(*name), self.strict)?;
                    self.var_ref_stack.push(reference);
                }
                Step::ResolvePrivateRef { atom } => {
                    let object = self.pop();
                    let name_id = crate::context::resolve_private_name(agent, *atom)?.id;
                    self.var_ref_stack.push(crate::context::Reference {
                        base: crate::context::ReferenceBase::Value(object),
                        name: PropertyKey::from_utf8(""),
                        strict: self.strict,
                        this_value: None,
                        private_name: Some(name_id),
                    });
                }
                Step::ResolveMemberRefName { name } => {
                    let object = self.pop();
                    let reference =
                        member_reference(&object, &PropertyKeyName::Name(*name), self.strict);
                    self.var_ref_stack.push(reference);
                }
                Step::ResolveMemberRefComputed => {
                    let key = self.pop();
                    let object = self.pop();
                    // RequireObjectCoercible before ToPropertyKey (spec 13.3.3
                    // steps 4-5): the nullish-base TypeError fires before the
                    // key's coercion — the logical-assignment lhs-before-rhs
                    // fixtures pin the key's toString must not run.
                    if is_nullish(&object) {
                        return Err(nullish_error("Cannot convert undefined or null to object"));
                    }
                    let key = crate::context::to_property_key(agent, &key)?;
                    let reference =
                        member_reference(&object, &PropertyKeyName::Key(key), self.strict);
                    self.var_ref_stack.push(reference);
                }
                Step::PutVarReference => {
                    let value = self.pop();
                    let reference = self.var_ref_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "PutVarReference without a resolution".into(),
                        )
                    })?;
                    crate::context::put_value(agent, &reference, value)?;
                    self.stack.push(value);
                }
                Step::PopVarReference => {
                    self.var_ref_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "PopVarReference without a resolution".into(),
                        )
                    })?;
                }
                Step::ResolveSuperRefName { name } => {
                    let this = self.vm_this_binding(agent)?;
                    let base = self.vm_super_base(agent)?;
                    self.var_ref_stack.push(crate::context::Reference {
                        base: crate::context::ReferenceBase::Value(base),
                        name: PropertyKey::from_js_string(&crux::lookup(*name)),
                        strict: self.strict,
                        this_value: Some(this),
                        private_name: None,
                    });
                }
                Step::ResolveSuperRefComputed => {
                    let key = self.pop();
                    let base = self.pop();
                    let key = crate::context::to_property_key(agent, &key)?;
                    let this = self.vm_this_binding(agent)?;
                    self.var_ref_stack.push(crate::context::Reference {
                        base: crate::context::ReferenceBase::Value(base),
                        name: key,
                        strict: self.strict,
                        this_value: Some(this),
                        private_name: None,
                    });
                }
                Step::GetVarReference => {
                    let reference = self.var_ref_stack.last().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "GetVarReference without a resolution".into(),
                        )
                    })?;
                    let value = crate::context::get_value(agent, reference)?;
                    self.stack.push(value);
                }
                Step::GetVarReferenceThis => {
                    let reference = self.var_ref_stack.last().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "GetVarReferenceThis without a resolution".into(),
                        )
                    })?;
                    self.stack.push(crate::context::get_this_value(reference));
                }
                Step::PutVarReferenceOp { op } => {
                    let value = self.pop();
                    let old = self.pop();
                    let reference = self.var_ref_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "PutVarReferenceOp without a resolution".into(),
                        )
                    })?;
                    let new = crate::expr::apply_compound(agent, *op, &old, &value)?;
                    crate::context::put_value(agent, &reference, new)?;
                    self.stack.push(new);
                }
                Step::UpdateVarReference { op, prefix } => {
                    let old = self.pop();
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    let reference = self.var_ref_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "UpdateVarReference without a resolution".into(),
                        )
                    })?;
                    crate::context::put_value(agent, &reference, new)?;
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::UsingInit { pattern, is_await } => {
                    let value = self.pop();
                    let kind = if *is_await {
                        crate::eval::DisposalKind::Async
                    } else {
                        crate::eval::DisposalKind::Sync
                    };
                    let resource = crate::eval::create_disposable_resource(agent, &value, kind)?;
                    self.lexical_env.add_disposable_resource(resource);
                    crate::binding::binding_initialization(
                        agent,
                        pattern,
                        value,
                        Some(&self.lexical_env),
                        self.strict,
                    )?;
                    self.stack.push(value);
                }
                Step::SetFunctionName { name } => {
                    let value = self.pop();
                    let display =
                        crate::function::default_binding_display_name(Some(crux::lookup(*name)))
                            .unwrap_or_else(|| crux::lookup(*name));
                    crate::function::set_function_name(&value, &display, None)?;
                    self.stack.push(value);
                }
                Step::SetChainShort => {
                    self.chain_short = true;
                }
                Step::ClearChainShort => {
                    self.chain_short = false;
                }
                Step::JumpIfChainShort(target) => {
                    if self.chain_short {
                        self.ip = *target;
                    }
                }
                Step::UpdateIdent { name, op, prefix } => {
                    let old = self.pop();
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    let reference =
                        crate::context::resolve_binding(agent, &crux::lookup(*name), self.strict)?;
                    crate::context::put_value(agent, &reference, new)?;
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::UpdateMemberName { name, op, prefix } => {
                    let old = self.pop();
                    let object = self.pop();
                    if is_nullish(&object) {
                        return Err(nullish_error("Cannot set properties of null"));
                    }
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    crate::context::put_value(
                        agent,
                        &member_reference(&object, &PropertyKeyName::Name(*name), self.strict),
                        new,
                    )?;
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::UpdateMemberComputed { op, prefix } => {
                    let old = self.pop();
                    let key = self.pop();
                    let object = self.pop();
                    if is_nullish(&object) {
                        return Err(nullish_error("Cannot set properties of null"));
                    }
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    let key = crate::context::to_property_key(agent, &key)?;
                    crate::context::put_value(
                        agent,
                        &member_reference(&object, &PropertyKeyName::Key(key), self.strict),
                        new,
                    )?;
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::UpdateSuperName { name, op, prefix } => {
                    let old = self.pop();
                    let base = self.pop();
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    self.put_super(agent, base, PropertyKeyName::Name(*name), new)?;
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::UpdateSuperComputed { op, prefix } => {
                    let old = self.pop();
                    let key = self.pop();
                    let base = self.pop();
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    let key = crate::context::to_property_key(agent, &key)?;
                    self.put_super(agent, base, PropertyKeyName::Key(key), new)?;
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::UpdatePrivate { atom, op, prefix } => {
                    let old = self.pop();
                    let object = self.pop();
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    let name_id = crate::context::resolve_private_name(agent, *atom)?.id;
                    crate::context::private_set(agent, &object, name_id, new)?;
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::DeleteIdent { name } => {
                    let reference =
                        crate::context::resolve_binding(agent, &crux::lookup(*name), self.strict)?;
                    let deleted = crate::context::delete_property_or_throw(agent, &reference)?;
                    self.stack.push(Value::Boolean(deleted));
                }
                Step::DeleteMemberName { name } => {
                    let object = self.pop();
                    if is_nullish(&object) {
                        return Err(nullish_error("Cannot convert undefined or null to object"));
                    }
                    let reference = crate::context::Reference {
                        base: crate::context::ReferenceBase::Value(object),
                        name: PropertyKey::from_js_string(&crux::lookup(*name)),
                        strict: self.strict,
                        this_value: None,
                        private_name: None,
                    };
                    let deleted = crate::context::delete_property_or_throw(agent, &reference)?;
                    self.stack.push(Value::Boolean(deleted));
                }
                Step::DeleteMemberComputed => {
                    let key = self.pop();
                    let object = self.pop();
                    if is_nullish(&object) {
                        return Err(nullish_error("Cannot convert undefined or null to object"));
                    }
                    let key = crate::context::to_property_key(agent, &key)?;
                    let reference = crate::context::Reference {
                        base: crate::context::ReferenceBase::Value(object),
                        name: key,
                        strict: self.strict,
                        this_value: None,
                        private_name: None,
                    };
                    let deleted = crate::context::delete_property_or_throw(agent, &reference)?;
                    self.stack.push(Value::Boolean(deleted));
                }
                Step::DeleteSuper => {
                    // `delete super.x` is a ReferenceError before the key is
                    // even evaluated (spec 13.5.1.2 step 4.b).
                    return Err(JsError::new(
                        ErrorKind::ReferenceError,
                        "Unsupported reference to 'super'".into(),
                    ));
                }
                Step::TypeofTop => {
                    let value = self.pop();
                    self.stack
                        .push(Value::String(Handle::new(JsString::from_utf8(
                            crux::value::type_of(&value),
                        ))));
                }
                Step::TypeofIdent { name } => {
                    // spec 13.5.3.2 step 1: an unresolvable reference is
                    // "undefined", not a ReferenceError.
                    let reference =
                        crate::context::resolve_binding(agent, &crux::lookup(*name), self.strict)?;
                    let value = match &reference.base {
                        crate::context::ReferenceBase::Unresolvable => Value::Undefined,
                        _ => crate::context::get_value(agent, &reference)?,
                    };
                    self.stack
                        .push(Value::String(Handle::new(JsString::from_utf8(
                            crux::value::type_of(&value),
                        ))));
                }
                Step::PrivateIn { atom } => {
                    let object = self.pop();
                    // `#x in rhs` requires an object RHS (spec 13.11.1 step
                    // 4), like the `in` operator's non-object check.
                    if !matches!(object.kind(), ValueKind::Object(_) | ValueKind::Function(_)) {
                        return Err(JsError::new(
                            ErrorKind::TypeError,
                            "Cannot use 'in' operator to search for a property in a non-object"
                                .into(),
                        ));
                    }
                    let name_id = crate::context::resolve_private_name(agent, *atom)?.id;
                    self.stack.push(Value::Boolean(crate::context::private_in(
                        &object, name_id,
                    )?));
                }
                Step::Call { direct_eval } => {
                    self.do_call(agent, *direct_eval)?;
                }
                Step::CallFast { argc, direct_eval } => {
                    self.do_call_fast(agent, *argc as usize, *direct_eval)?;
                }
                Step::CallApply { argc, kind } => {
                    self.do_call_apply(agent, *argc as usize, *kind)?;
                }
                Step::TailCallFast { argc, direct_eval } => {
                    return self.tail_call_fast(agent, *argc as usize, *direct_eval, body);
                }
                Step::TailCall { direct_eval } => {
                    return self.tail_call_vector(agent, *direct_eval, body);
                }
                Step::TailCallFastGlobal { name, argc } => {
                    return self.do_tail_call_global(agent, *name, *argc as usize, body);
                }
                Step::TailCallFastSlot { slot, argc } => {
                    return self.do_tail_call_slot(agent, *slot, *argc as usize, body);
                }
                Step::TailCallSelf { argc } => {
                    // Cut 46: the callee is statically the running body
                    // itself — rebind the frame with the new arguments and
                    // re-enter the body's entry on this Vm (no callee
                    // lookup, no context swap, no frame realloc).
                    self.tail_call_self(agent, *argc as usize, body)?;
                    continue;
                }
                Step::TailCallSelfCheck { argc } => {
                    // Cut 47: a global-name self-tail-call — the shared
                    // machinery handles the callee either way (an identity
                    // match frame-replaces, a reassigned name calls the
                    // resolved callee); the JIT adds the identity check
                    // before committing to the jump.
                    return self.tail_call_fast(agent, *argc as usize, false, body);
                }
                Step::TailCallSelfVector => {
                    // Cut 51: the vector-form self-tail-call — the arguments
                    // sit in the Vm's vector; rebind the frame in place and
                    // re-enter the body's entry on this Vm (no callee
                    // lookup, no context swap, no runtime round-trip).
                    self.tail_call_self_vector(agent, body)?;
                    continue;
                }
                Step::TailCallSelfCheckVector => {
                    // Cut 51: the vector-form checked self-tail-call — the
                    // shared vector machinery handles the callee either way
                    // (an identity match frame-replaces, a reassigned name
                    // calls the resolved callee); the JIT adds the identity
                    // check before committing to the jump.
                    return self.tail_call_vector(agent, false, body);
                }
                Step::CallFastGlobal {
                    name,
                    argc,
                    direct_eval,
                } => {
                    self.do_call_fast_global(agent, *name, None, *argc as usize, *direct_eval)?;
                }
                Step::CallFastSlot { slot, argc } => {
                    self.do_call_fast_slot(agent, *slot, None, *argc as usize)?;
                }
                Step::CallFastSlotStore {
                    callee_slot,
                    arg_slots,
                    store_slot,
                } => {
                    // Cut 35 slice 17: the fused `x = f(args)` — TDZ-check
                    // the arg slots in order (their `LoadLocal` checks),
                    // run the slot-callee call, and store the result to
                    // the target with the `FusedStoreLocal` TDZ check. The
                    // evaluation order matches the unfused steps exactly.
                    // Cut 35 slice 23: the args stay in the caller's frame
                    // — the callee may read them straight from there (no
                    // stack push); the call core materializes them on a
                    // miss or fallback.
                    let arg_base = arg_slots.first().copied();
                    for &slot in arg_slots {
                        if self.frame_get(slot).is_uninitialized() {
                            return Err(JsError::new(
                                ErrorKind::ReferenceError,
                                "Cannot access a binding before initialization".into(),
                            ));
                        }
                    }
                    self.do_call_fast_slot(agent, *callee_slot, arg_base, arg_slots.len())?;
                    let result = self.pop();
                    if self.frame_get(*store_slot).is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    *self.frame_get_mut(*store_slot) = result;
                }
                Step::CallFastGlobalStore {
                    name,
                    arg_slots,
                    store_slot,
                } => {
                    // Cut 35 slice 20: the fused `x = f(args)` for a global
                    // callee — same shape as `CallFastSlotStore` through
                    // `do_call_fast_global` (the global leaf cache). The
                    // arg slots are TDZ-checked here and passed by caller-
                    // frame base (Cut 35 slice 23) so the callee can read
                    // them without a stack push.
                    let arg_base = arg_slots.first().copied();
                    for &slot in arg_slots {
                        if self.frame_get(slot).is_uninitialized() {
                            return Err(JsError::new(
                                ErrorKind::ReferenceError,
                                "Cannot access a binding before initialization".into(),
                            ));
                        }
                    }
                    self.do_call_fast_global(agent, *name, arg_base, arg_slots.len(), false)?;
                    let result = self.pop();
                    if self.frame_get(*store_slot).is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    *self.frame_get_mut(*store_slot) = result;
                }
                Step::SuperCall => {
                    let base = self.args_base_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "SuperCall without an argument boundary".into(),
                        )
                    })?;
                    // GC-2: the argument copy below is a local `Vec<Value>`
                    // the stack scan cannot see, and the super constructor's
                    // setup allocates — suppress `--gc-stress` for the window
                    // (see the `Call` step).
                    let _stress = StressSuppress::new();
                    let args = self.args.split_off(base);
                    let new_target = get_new_target(agent)?;
                    let super_ctor = get_super_constructor(agent)?;
                    let result =
                        crate::function::construct(agent, &super_ctor, &args, &new_target)?;
                    let this_env = get_this_environment(agent)?;
                    this_env.bind_this_value(result)?;
                    if let Some(function_value) = agent.running_context()?.function {
                        crate::function::initialize_instance_elements(
                            agent,
                            &result,
                            &function_value,
                        )?;
                    }
                    self.stack.push(result);
                }
                Step::Construct => {
                    let callee = self.pop();
                    let base = self.args_base_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "Construct without an argument boundary".into(),
                        )
                    })?;
                    // GC-2: the general construct path copies its arguments
                    // into a local Vec (the leaf path's frame copies them
                    // before any collection, so it can split freely); the
                    // copy is unrooted while the construct machinery (env
                    // records, the capture context, a rest binding's
                    // `array_from_values`) allocates, so `--gc-stress` is
                    // suppressed for the window.
                    let result = if self.can_inline_leaf()
                        && let ValueKind::Function(function) = callee.kind()
                        && matches!(function.kind, crux::function::FunctionKind::EcmaScript)
                        && agent.realm_count.get() == 1
                        && let Some(entry) = agent.leaf_lookup(function.id())
                        // Cut 33: the certified base-constructor leaf verdict
                        // (leaf body, base kind, no fields/private methods) is
                        // cached at ir-compile time.
                        && entry.construct_inline
                    {
                        // The argument slice is read in place from `self.args`
                        // into a small stack buffer (≤3 args, the common
                        // shape) instead of `split_off`'s per-construct Vec
                        // allocation; a longer argument list keeps the Vec
                        // path. The buffer is a local like the Vec was, so
                        // the rooting story is unchanged.
                        let argc = self.args.len() - base;
                        let mut args_buf = [Value::Undefined; 3];
                        let args: std::borrow::Cow<'_, [Value]> = if argc <= args_buf.len() {
                            args_buf[..argc].copy_from_slice(&self.args[base..]);
                            std::borrow::Cow::Borrowed(&args_buf[..argc])
                        } else {
                            std::borrow::Cow::Owned(self.args.split_off(base))
                        };
                        self.args.truncate(base);
                        let ir = entry.ir.clone();
                        let strict = entry.strict;
                        // Cut 30: clone the callee's env only for a leaf
                        // that reads one (see `do_call_fast`).
                        let environment = if ir.leaf_uses_env {
                            entry.environment
                        } else {
                            None
                        };
                        self.run_leaf_construct(agent, &ir, environment, strict, &callee, &args)?
                    } else {
                        let _stress = StressSuppress::new();
                        let args = self.args.split_off(base);
                        crate::function::construct(agent, &callee, &args, &callee)?
                    };
                    self.stack.push(result);
                }
                Step::TaggedTemplate(template) => {
                    let tag = self.pop();
                    let this = self.pop();
                    let base = self.args_base_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "TaggedTemplate without an argument boundary".into(),
                        )
                    })?;
                    // GC-2: the substitution Vec is unrooted while the tag
                    // invocation allocates — suppress `--gc-stress` for the
                    // window (see the tail-call dispatch).
                    let _stress = StressSuppress::new();
                    let substitutions = self.args.split_off(base);
                    let value = tagged_template(agent, this, tag, template, substitutions)?;
                    self.stack.push(value);
                }
                Step::TailTaggedTemplate(template) => {
                    let tag = self.pop();
                    let this = self.pop();
                    let base = self.args_base_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "TailTaggedTemplate without an argument boundary".into(),
                        )
                    })?;
                    // GC-2: borrow the substitutions from the traced
                    // `self.args` (see the `Construct` step) — the template
                    // object creation below allocates.
                    let substitutions = &self.args[base..];
                    // The tag invocation is the tail call: build the
                    // template object + substitution arguments, lay them out
                    // as a fast-form call, and let the shared dispatcher
                    // frame-replace (or run a leaf in place) and complete the
                    // return.
                    let template_object = crate::expr::get_template_object(agent, template)?;
                    let mut args = vec![template_object];
                    args.extend_from_slice(substitutions);
                    let argc = args.len();
                    let keep = self.stack.len();
                    self.stack.push(this);
                    self.stack.push(tag);
                    self.stack.extend(args);
                    let n = self.stack.len();
                    return match self.tail_call_shared(
                        agent,
                        this,
                        tag,
                        argc,
                        n - argc,
                        keep,
                        false,
                        body,
                    )? {
                        TailOutcome::Returned(outcome) => Ok(outcome),
                        TailOutcome::Replaced(ir) => Ok(VmOutcome::TailCall(ir)),
                    };
                }
                Step::ArrayBegin => {
                    let array = crate::builtins::array::array_create(agent, 0.0)?;
                    self.array_index_stack.push(0);
                    self.stack.push(Value::Object(array));
                }
                Step::ArrayElement => {
                    let value = self.pop();
                    let array = self.pop();
                    let index = *self.array_index()?;
                    array_set(&array, &index.to_string(), value)?;
                    *self.array_index()? = index + 1;
                    self.stack.push(array);
                }
                Step::ArraySpread => {
                    let iterable = self.pop();
                    let array = self.pop();
                    let iterator = get_iterator(agent, &iterable)?;
                    while let Some(value) = iterator_step(agent, &iterator)? {
                        let index = *self.array_index()?;
                        array_set(&array, &index.to_string(), value)?;
                        *self.array_index()? = index + 1;
                    }
                    self.stack.push(array);
                }
                Step::ArrayHole => {
                    let index = *self.array_index()?;
                    *self.array_index()? = index + 1;
                }
                Step::ArrayEnd => {
                    let array = self.pop();
                    let length = self.array_index_stack.pop().ok_or_else(|| {
                        JsError::new(ErrorKind::SyntaxError, "ArrayEnd without an array".into())
                    })?;
                    let ValueKind::Object(obj) = array.kind() else {
                        return Err(JsError::new(ErrorKind::TypeError, "not an object".into()));
                    };
                    obj.set(
                        &JsString::from_utf8("length"),
                        Value::Number(length as f64),
                        true,
                    )?;
                    self.stack.push(array);
                }
                Step::ObjectBegin => {
                    let proto = agent
                        .current_realm()?
                        .intrinsics
                        .object_prototype()
                        .and_then(|value| crate::context::as_object(&value));
                    let object = crux::object::JsObject::ordinary_object_create(proto);
                    self.stack.push(Value::Object(object));
                }
                Step::ObjectInitName {
                    name,
                    set_name,
                    shorthand,
                } => {
                    let value = self.pop();
                    let object = self.pop();
                    object_init(
                        &object,
                        &PropertyName::Ident(*name),
                        value,
                        *set_name,
                        *shorthand,
                    )?;
                    self.stack.push(object);
                }
                Step::ObjectInitComputed { set_name } => {
                    let value = self.pop();
                    let key = self.pop();
                    let object = self.pop();
                    let ValueKind::Object(obj) = object.kind() else {
                        return Err(JsError::new(ErrorKind::TypeError, "not an object".into()));
                    };
                    let key = crate::context::to_property_key(agent, &key)?;
                    object_init_key(&obj, key, value, *set_name)?;
                    self.stack.push(object);
                }
                Step::ObjectKeyToPropertyKey => {
                    let key = self.pop();
                    let key = crate::context::to_property_key(agent, &key)?;
                    let key = match key {
                        PropertyKey::String(id) => Value::String(Handle::new(crux::lookup(id))),
                        PropertyKey::Symbol(symbol) => Value::Symbol(symbol),
                    };
                    self.stack.push(key);
                }
                Step::ObjectMethodName { name, function } => {
                    let object = self.pop();
                    object_method(
                        agent,
                        &object,
                        PropertyKey::String(*name),
                        function,
                        self.strict,
                    )?;
                    self.stack.push(object);
                }
                Step::ObjectMethodComputed { function } => {
                    let key = self.pop();
                    let object = self.pop();
                    let key = crate::context::to_property_key(agent, &key)?;
                    object_method(agent, &object, key, function, self.strict)?;
                    self.stack.push(object);
                }
                Step::ObjectAccessorName {
                    name,
                    get,
                    param,
                    body,
                } => {
                    let object = self.pop();
                    object_accessor(
                        agent,
                        &object,
                        PropertyKey::String(*name),
                        *get,
                        param.as_ref(),
                        body,
                        self.strict,
                    )?;
                    self.stack.push(object);
                }
                Step::ObjectAccessorComputed { get, param, body } => {
                    let key = self.pop();
                    let object = self.pop();
                    let key = crate::context::to_property_key(agent, &key)?;
                    object_accessor(agent, &object, key, *get, param.as_ref(), body, self.strict)?;
                    self.stack.push(object);
                }
                Step::ObjectSpread => {
                    let from = self.pop();
                    let object = self.pop();
                    let ValueKind::Object(obj) = object.kind() else {
                        return Err(JsError::new(ErrorKind::TypeError, "not an object".into()));
                    };
                    crate::expr::copy_data_properties(agent, &obj, &from)?;
                    self.stack.push(object);
                }
                Step::ClassBegin {
                    class,
                    binding,
                    key_count: _,
                } => {
                    // Create the class scope and PrivateEnvironment and
                    // activate them, so the heritage and computed names run
                    // with the class name in TDZ and `super`/private names
                    // visible (spec 15.7.14 steps 2-11).
                    let outer_env = self.lexical_env;
                    let class_env = new_declarative_environment(Some(outer_env));
                    if let Some(binding) = binding {
                        let name = crux::lookup(*binding);
                        class_env.create_immutable_binding(&name, true)?;
                    }
                    let outer_private_env = agent.running_context()?.private_environment;
                    let class_private_env =
                        crate::context::new_private_environment(outer_private_env);
                    {
                        let mut names = class_private_env.names.borrow_mut();
                        for element in &class.elements {
                            let Some(atom) = crate::class::private_element_name(element) else {
                                continue;
                            };
                            let description = JsString::from_utf8(&format!(
                                "#{}",
                                crux::lookup(atom).to_string_lossy()
                            ));
                            if !names.iter().any(|name| name.description == description) {
                                names.push(crate::context::new_private_name(description));
                            }
                        }
                    }
                    if let Ok(context) = agent.running_context_mut() {
                        context.lexical_environment = class_env;
                        context.private_environment = Some(class_private_env);
                    }
                    self.lexical_env = class_env;
                    self.class_stack.push(ClassEvalState {
                        class_env,
                        class_private_env,
                        outer_private_env,
                        outer_env,
                        heritage: None,
                    });
                }
                Step::ClassHeritage => {
                    let value = self.pop();
                    let Some(state) = self.class_stack.last_mut() else {
                        return Err(JsError::new(
                            ErrorKind::SyntaxError,
                            "ClassHeritage without a pending class".into(),
                        ));
                    };
                    state.heritage = Some(value);
                }
                Step::ClassKeyToPropertyKey => {
                    // ToPropertyKey runs before the next name is evaluated
                    // (user code ordering, spec 15.7.13), so convert here.
                    let value = self.pop();
                    let key = crate::context::to_property_key(agent, &value)?;
                    let key = match key {
                        PropertyKey::String(id) => Value::String(Handle::new(crux::lookup(id))),
                        PropertyKey::Symbol(symbol) => Value::Symbol(symbol),
                    };
                    self.stack.push(key);
                }
                Step::ClassFinish {
                    class,
                    binding,
                    key_count,
                } => {
                    let mut keys: Vec<Option<PropertyKey>> = Vec::with_capacity(*key_count);
                    for _ in 0..*key_count {
                        let value = self.pop();
                        let key = crate::context::to_property_key(agent, &value)?;
                        keys.push(Some(key));
                    }
                    keys.reverse();
                    let state = self.class_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "ClassFinish without a pending class".into(),
                        )
                    })?;
                    self.lexical_env = state.outer_env;
                    if let Ok(context) = agent.running_context_mut() {
                        context.lexical_environment = state.outer_env;
                        context.private_environment = state.outer_private_env;
                    }
                    let class_value = crate::class::class_definition_evaluation_with_scope(
                        agent,
                        class,
                        *binding,
                        state.class_env,
                        state.class_private_env,
                        state.outer_private_env,
                        state.outer_env,
                        state.heritage,
                        &keys,
                    )?;
                    self.stack.push(class_value);
                }
                Step::PushStr(text) => {
                    self.stack.push(Value::String(Handle::new(text.clone())));
                }
                Step::ConcatStr => {
                    let value = self.pop();
                    let acc = self.pop();
                    let text = crate::context::to_string(agent, &value)?;
                    let mut units = string_units_of(&acc);
                    units.extend_from_slice(text.as_slice());
                    self.stack
                        .push(Value::String(Handle::new(JsString::from_utf16(&units))));
                }
                Step::ConcatStrConst(text) => {
                    let acc = self.pop();
                    let mut units = string_units_of(&acc);
                    units.extend_from_slice(text.as_slice());
                    self.stack
                        .push(Value::String(Handle::new(JsString::from_utf16(&units))));
                }
                Step::ArgsBase => {
                    self.args_base_stack.push(self.args.len());
                }
                Step::ArgsPush => {
                    let value = self.pop();
                    self.args.push(value);
                }
                Step::ArgsSpread => {
                    let iterable = self.pop();
                    let iterator = get_iterator(agent, &iterable)?;
                    while let Some(value) = iterator_step(agent, &iterator)? {
                        self.args.push(value);
                    }
                }
                Step::EnterBlock { decls } => {
                    let old_env = self.lexical_env;
                    let env = new_declarative_environment(Some(old_env));
                    block_declaration_instantiation(agent, decls, &env, self.strict)?;
                    // A certified body's closures resolve captured bindings
                    // through the static context chain, not these envs (the
                    // flat slot/context layout is authoritative), so the
                    // block env is scaffolding to them — mark it
                    // context-transparent like a per-iteration env so a
                    // closure created inside the block (a `try` block, whose
                    // `EnterBlock` is always emitted) still reaches its
                    // capture context. The env path keeps it visible.
                    if body.scope.is_some()
                        && let EnvRecord::Declarative(declarative) = &*env
                    {
                        declarative.mark_context_transparent();
                    }
                    self.lexical_env = env;
                    self.env_stack.push(env);
                }
                Step::LeaveBlock => {
                    let popped = self.env_stack.pop().ok_or_else(|| {
                        JsError::new(ErrorKind::SyntaxError, "Environment stack underflow".into())
                    })?;
                    // spec 9.4.3: the scope's `using` resources are disposed
                    // when it exits, in reverse registration order;
                    // async-dispose hints suspend the VM through the job
                    // queue.
                    let mut resources = popped.drain_disposable_resources();
                    resources.reverse();
                    // Restore to the popped environment's outer, which may
                    // differ from the stack's previous entry (per-iteration
                    // environments live outside the stack).
                    self.lexical_env = popped.outer().unwrap_or(popped);
                    if !resources.is_empty() {
                        let completion = Completion::Normal(self.completion);
                        if let Some(outcome) = self.start_scope_disposal(
                            agent,
                            body,
                            resources,
                            completion,
                            DisposalResume::ApplyCompletion,
                        )? {
                            return Ok(outcome);
                        }
                    }
                }
                Step::EnterTry { handler } => {
                    self.try_stack.push(TryFrame {
                        handler: *handler,
                        saved_env: self.lexical_env,
                        env_depth: self.env_stack.len(),
                    });
                }
                Step::Exit { after } => {
                    match self.control_transfer(agent, body, Ctl::Normal { after: *after })? {
                        CtlResult::Continue => continue,
                        CtlResult::Done(outcome) => return Ok(outcome),
                    }
                }
                Step::CatchBind { param, decls } => {
                    // A caught throw discarded the try block's envs: dispose
                    // their `using` resources first, folding into the thrown
                    // value (spec 9.4.3 on the try block's abrupt
                    // completion), so the catch observes the folded error.
                    if let Some((saved_env, depth)) = self.pending_catch_disposal.take() {
                        let mut resources = Vec::new();
                        for index in (depth..self.env_stack.len()).rev() {
                            if let Some(env) = self.env_stack.get(index) {
                                resources
                                    .extend(env.drain_disposable_resources().into_iter().rev());
                            }
                        }
                        self.env_stack.truncate(depth);
                        if !resources.is_empty() {
                            let thrown = self.thrown.take().unwrap_or(Value::Undefined);
                            let completion = Completion::Throw(thrown);
                            if let Some(outcome) = self.start_scope_disposal(
                                agent,
                                body,
                                resources,
                                completion,
                                DisposalResume::DeliverCatch {
                                    saved_env,
                                    env_depth: depth,
                                },
                            )? {
                                // The disposal suspended: the ip was already
                                // advanced past this step, so re-enter the
                                // CatchBind step on resume to bind the
                                // parameter with the folded value.
                                self.ip -= 1;
                                return Ok(outcome);
                            }
                        } else {
                            self.restore_env(saved_env, depth);
                        }
                    }
                    let thrown = self.thrown.take().unwrap_or(Value::Undefined);
                    let old_env = self.lexical_env;
                    let env = new_declarative_environment(Some(old_env));
                    // The catch parameter binds in its own environment, so a
                    // default initializer's closure captures the parameter
                    // (spec 15.1.7 step 7). All the created environments go on
                    // the stack so the body's LeaveBlock(s) unwind back to
                    // `old_env` — otherwise the parameter environment would
                    // stay active after the catch, leaking its bindings.
                    // A certified body's closures resolve captures through the
                    // static context chain, so its catch envs are scaffolding
                    // to them — mark them context-transparent (like a
                    // per-iteration env) so a closure created inside the catch
                    // still reaches its capture context. The env path keeps
                    // them visible.
                    if body.scope.is_some()
                        && let EnvRecord::Declarative(declarative) = &*env
                    {
                        declarative.mark_context_transparent();
                    }
                    let body_env = match &param {
                        Some(param) => {
                            let param_env = new_declarative_environment(Some(env));
                            // Annex B.3.5: a direct eval's var-vs-lexical walk
                            // skips the catch parameter's environment.
                            param_env.mark_catch_param_env();
                            if body.scope.is_some()
                                && let EnvRecord::Declarative(declarative) = &*param_env
                            {
                                declarative.mark_context_transparent();
                            }
                            self.env_stack.push(env);
                            let mut names = Vec::new();
                            crate::script::bound_names(param, &mut names);
                            for name in &names {
                                param_env.create_mutable_binding(name, false)?;
                            }
                            // The parameter environment is the running
                            // environment while the default initializers run,
                            // so a closure captures the parameter (spec
                            // 15.1.7 step 7).
                            if let Ok(context) = agent.running_context_mut() {
                                context.lexical_environment = param_env;
                            }
                            crate::binding::binding_initialization(
                                agent,
                                param,
                                thrown,
                                Some(&param_env),
                                self.strict,
                            )?;
                            self.env_stack.push(param_env);
                            new_declarative_environment(Some(param_env))
                        }
                        None => env,
                    };
                    if body.scope.is_some()
                        && let EnvRecord::Declarative(declarative) = &*body_env
                    {
                        declarative.mark_context_transparent();
                    }
                    block_declaration_instantiation(agent, decls, &body_env, self.strict)?;
                    self.lexical_env = body_env;
                    self.env_stack.push(body_env);
                    // A certified body's catch parameter lives in a flat frame
                    // slot (the scope scan allocates it; a captured or
                    // destructuring parameter keeps the body on the env path):
                    // write the thrown value so the slot reads in the catch
                    // body see it.
                    if let Some(scope) = &body.scope
                        && let Some(param) = param
                        && let BindingPattern::Ident(name) = param
                        && let Some(slot) = scope.slots.get(name)
                    {
                        *self.frame_get_mut(*slot) = thrown;
                    }
                }
                Step::FinallyEnd => {
                    let pending = self.pending.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "FinallyEnd without a pending control".into(),
                        )
                    })?;
                    let ctl = match pending {
                        PendingControl::Normal { after, env, depth } => {
                            self.restore_env(env, depth);
                            Ctl::Normal { after }
                        }
                        PendingControl::Break { target, env, depth } => {
                            self.restore_env(env, depth);
                            Ctl::Break { target }
                        }
                        PendingControl::Continue { target, env, depth } => {
                            self.restore_env(env, depth);
                            Ctl::Continue { target }
                        }
                        PendingControl::Return { value, env, depth } => {
                            self.restore_env(env, depth);
                            Ctl::Return { value }
                        }
                        PendingControl::Throw { value, env, depth } => {
                            self.restore_env(env, depth);
                            // A pending throw applies through the throw
                            // machinery (a catch in the same body may cover
                            // it); control_transfer only routes finallys.
                            match self.throw_machinery(agent, body, value)? {
                                CtlResult::Continue => continue,
                                CtlResult::Done(outcome) => return Ok(outcome),
                            }
                        }
                    };
                    match self.control_transfer(agent, body, ctl)? {
                        CtlResult::Continue => {}
                        CtlResult::Done(outcome) => return Ok(outcome),
                    }
                }
                Step::EnterIterTdzEnv { names } => {
                    let old_env = self.lexical_env;
                    let env = new_declarative_environment(Some(old_env));
                    for name in names {
                        env.create_mutable_binding(name, false)?;
                    }
                    self.lexical_env = env;
                    self.env_stack.push(env);
                }
                Step::LeaveIterTdzEnv => {
                    let popped = self.env_stack.pop().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "LeaveIterTdzEnv without an environment".into(),
                        )
                    })?;
                    self.lexical_env = popped.outer().unwrap_or(popped);
                }
                Step::EnterWith => {
                    let object = self.pop();
                    // spec 14.15.4 step 2: primitives are boxed (ToObject).
                    let object_value = crate::context::to_object(agent, &object)?;
                    let obj = crate::context::as_object(&object_value).ok_or_else(|| {
                        JsError::new(
                            ErrorKind::TypeError,
                            "Cannot use 'with' on a non-object value".into(),
                        )
                    })?;
                    let with_env =
                        crate::env::new_object_environment(obj, true, Some(self.lexical_env));
                    self.lexical_env = with_env;
                    self.env_stack.push(with_env);
                }
                Step::PerIteration { names } => {
                    let last = self.lexical_env;
                    let outer = last.outer().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::ReferenceError,
                            "No outer environment for per-iteration bindings".into(),
                        )
                    })?;
                    let env = new_declarative_environment(Some(outer));
                    for name in names {
                        let value = last.get_binding_value(name, false)?;
                        env.create_mutable_binding(name, false)?;
                        env.initialize_binding(name, value)?;
                    }
                    // The per-iteration environment replaces the lexical
                    // environment without joining the stack; the loop's exit
                    // restores the loop environment directly.
                    if let EnvRecord::Declarative(declarative) = &*env {
                        declarative.mark_context_transparent();
                    }
                    self.lexical_env = env;
                }
                Step::EnterPerIteration { names } => {
                    // Cut 3 continuation (per-iteration loop heads): the
                    // first per-iteration env of a certified loop — fresh
                    // bindings copied from the capture context's head slots,
                    // pushed on the env stack so the loop's exit/break
                    // `LeaveBlock` pops it and restores the capture context.
                    // Later iterations re-use `PerIteration` above (the
                    // copies then come from the previous per-iteration env).
                    let source = self.body_context.unwrap_or(self.lexical_env);
                    let env = new_declarative_environment(Some(self.lexical_env));
                    for name in names {
                        let value = source.get_binding_value(name, false)?;
                        env.create_mutable_binding(name, false)?;
                        env.initialize_binding(name, value)?;
                    }
                    if let EnvRecord::Declarative(declarative) = &*env {
                        declarative.mark_context_transparent();
                    }
                    self.lexical_env = env;
                    self.env_stack.push(env);
                }
                Step::LoadPerIteration { depth, index } => {
                    let env = self.per_iteration_env(*depth)?;
                    let value = context_env(&env).slot_value(*index).ok_or_else(|| {
                        JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        )
                    })?;
                    self.stack.push(value);
                }
                Step::StorePerIteration { depth, index } => {
                    let value = self.pop();
                    let env = self.per_iteration_env(*depth)?;
                    context_env(&env).set_slot(*index, value);
                }
                Step::UpdatePerIteration {
                    depth,
                    index,
                    op,
                    prefix,
                } => {
                    let env = self.per_iteration_env(*depth)?;
                    let old = context_env(&env).slot_value(*index).ok_or_else(|| {
                        JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        )
                    })?;
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    context_env(&env).set_slot(*index, new);
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::EnterLoopEnv { kind, decls } => {
                    let old_env = self.lexical_env;
                    let env = new_declarative_environment(Some(old_env));
                    // The head initializers (evaluated through the tree-walker)
                    // run with the loop env active: a closure they create
                    // captures the loop's own bindings, not the outer scope
                    // (spec 14.7.4.2 — the loop env is the running
                    // execution context's environment while the declarations
                    // initialize).
                    self.lexical_env = env;
                    self.env_stack.push(env);
                    if let Ok(context) = agent.running_context_mut() {
                        context.lexical_environment = env;
                    }
                    let head = (|| -> Result<(), JsError> {
                        for decl in decls {
                            let mut names = Vec::new();
                            crate::script::bound_names(&decl.pattern, &mut names);
                            for name in &names {
                                if *kind == VarDeclKind::Const
                                    || matches!(*kind, VarDeclKind::Using | VarDeclKind::AwaitUsing)
                                {
                                    // `using` heads bind immutably like
                                    // `const` (spec 15.14.2).
                                    env.create_immutable_binding(name, true)?;
                                } else {
                                    env.create_mutable_binding(name, false)?;
                                }
                            }
                            let value = match &decl.init {
                                Some(init) => crate::expr::eval_expr(agent, init, self.strict)?,
                                None => Value::Undefined,
                            };
                            // A `using` head registers the disposable resource
                            // before the binding initializes (spec 14.7.4.2
                            // step 5.e, like the UsingInit step).
                            if matches!(*kind, VarDeclKind::Using | VarDeclKind::AwaitUsing) {
                                let disposal_kind = if *kind == VarDeclKind::AwaitUsing {
                                    crate::eval::DisposalKind::Async
                                } else {
                                    crate::eval::DisposalKind::Sync
                                };
                                let resource = crate::eval::create_disposable_resource(
                                    agent,
                                    &value,
                                    disposal_kind,
                                )?;
                                env.add_disposable_resource(resource);
                            }
                            crate::binding::binding_initialization(
                                agent,
                                &decl.pattern,
                                value,
                                Some(&env),
                                self.strict,
                            )?;
                        }
                        Ok(())
                    })();
                    if let Err(error) = head {
                        // spec 14.7.4.2 step 9: an abrupt head disposes the
                        // loop environment's resources before propagating,
                        // folding a throwing disposal into the error.
                        return Err(
                            match crate::eval::dispose_env_resources(agent, &env, Err(error)) {
                                Ok(Completion::Throw(value)) => JsError::new(
                                    ErrorKind::TypeError,
                                    format!("Uncaught {value:?}"),
                                )
                                .with_value(value),
                                Ok(_) => JsError::new(
                                    ErrorKind::TypeError,
                                    "Uncaught disposal error".into(),
                                ),
                                Err(error) => error,
                            },
                        );
                    }
                }
                Step::ForInBegin => {
                    let rhs = self.pop();
                    if is_nullish(&rhs) {
                        // spec ForInOfHeadEvaluation step 7.a: a nullish
                        // exprValue is a break completion — the loop is
                        // skipped, not an error (the S12.6.4 and cptn-skip
                        // fixtures). The empty-key state makes ForInNext pop
                        // straight to the done label.
                        let dummy = crux::object::JsObject::ordinary_object_create(None);
                        self.for_in_stack.push((dummy, Vec::new(), 0));
                    } else {
                        let obj = crate::context::to_object(agent, &rhs)?;
                        let obj = crate::context::as_object(&obj).ok_or_else(|| {
                            JsError::new(ErrorKind::TypeError, "for-in over a non-object".into())
                        })?;
                        let keys = crate::eval::for_in_key_levels(agent, &rhs)?;
                        self.for_in_stack.push((obj, keys, 0));
                    }
                }
                Step::ForInNext { done, back } => {
                    let Some((obj, keys, index)) = self.for_in_stack.last_mut() else {
                        return Err(JsError::new(
                            ErrorKind::SyntaxError,
                            "ForInNext without a for-in".into(),
                        ));
                    };
                    let mut pushed = false;
                    while *index < keys.len() {
                        let (level, key) = keys[*index];
                        *index += 1;
                        // A key deleted during enumeration is skipped (spec
                        // EnumerateObjectProperties step 5.a.v).
                        if crate::eval::key_enumerable_at_level(obj, level, &key)? {
                            self.stack.push(key);
                            pushed = true;
                            break;
                        }
                    }
                    if pushed {
                        // Cut 35 slice 18: continue at the do-while body
                        // start (no back-jump per iteration).
                        self.ip = *back;
                    } else {
                        self.for_in_stack.pop();
                        self.ip = *done;
                    }
                }
                Step::ForInBind { left } => {
                    let value = self.pop();
                    self.for_binding_put(agent, left, value)?;
                }
                Step::ForInRestore => {
                    self.restore_per_iteration(agent)?;
                }
                Step::ForOfBegin { top, end } => {
                    let rhs = self.pop();
                    let entry = match crate::expr::for_of_begin(agent, &rhs)? {
                        crate::expr::ForOfState::Generic(record) => ForOfEntry::Generic(record),
                        crate::expr::ForOfState::FastArray(array) => {
                            ForOfEntry::Fast { array, index: 0 }
                        }
                    };
                    self.for_of_stack.push(entry);
                    self.for_of_boundaries.push((*top, *end));
                }
                Step::ForOfNext { done, back } => {
                    self.for_of_next(agent, *done, *back, ForOfNextTarget::Stack)?;
                }
                Step::ForOfNextBindLocal { slot, done, back } => {
                    self.for_of_next(agent, *done, *back, ForOfNextTarget::Slot(*slot))?;
                }
                Step::ForOfBind { left } => {
                    let value = self.pop();
                    self.for_binding_put(agent, left, value)?;
                }
                Step::ForOfBindLocal { slot } => {
                    let value = self.pop();
                    *self.frame_get_mut(*slot) = value;
                }
                Step::ForOfBindGlobal { name } => {
                    let value = self.pop();
                    self.store_global_value(agent, *name, value)?;
                }
                Step::ForOfRestore => {
                    self.restore_per_iteration(agent)?;
                }
                Step::ForOfClose => {
                    self.for_of_boundaries.pop();
                    if let Some(ForOfEntry::Generic(iterator)) = self.for_of_stack.pop() {
                        iterator_close(agent, &iterator)?;
                    }
                }
                Step::AsyncForOfClose => {
                    // AsyncIteratorClose with a normal completion (spec
                    // 14.7.5.7 step 8.b): the `return` method is invoked when
                    // present; its errors propagate. The exhausted path pops
                    // the stack at AsyncForOfTest, so only a break (or other
                    // early exit reaching the end label) closes here.
                    self.async_for_of_boundaries.pop();
                    if let Some(iterator) = self.async_for_of_stack.pop() {
                        iterator_close(agent, &iterator)?;
                    }
                }
                Step::AsyncForOfBegin { top, end } => {
                    let rhs = self.pop();
                    let iterator = async_from_sync_or_async(agent, &rhs)?;
                    self.async_for_of_stack.push(iterator);
                    self.async_for_of_boundaries.push((*top, *end));
                }
                Step::AsyncForOfNext => {
                    let Some(iterator) = self.async_for_of_stack.last() else {
                        return Err(JsError::new(
                            ErrorKind::SyntaxError,
                            "AsyncForOfNext without a for-await-of".into(),
                        ));
                    };
                    let iterator = iterator.clone();
                    // The next() promise is in flight: a rejection must not
                    // close the iterator (spec 14.7.5.5 — the close is only
                    // for body abrupt completions). `AsyncForOfTest` clears
                    // the flag on a fulfilled resume; the rejection path
                    // discards the record instead.
                    self.async_for_of_stepping = true;
                    let next_result =
                        crate::function::call(agent, &iterator.next, iterator.iterator, &[])?;
                    return Ok(VmOutcome::Suspended(Suspension::Await(next_result)));
                }
                Step::AsyncForOfTest { done } => {
                    self.async_for_of_stepping = false;
                    // Resumed with the awaited iterator result object.
                    let result = self.pop();
                    let is_done = iterator_result_done(agent, &result)?;
                    if is_done {
                        self.async_for_of_stack.pop();
                        self.async_for_of_boundaries.pop();
                        self.ip = *done;
                    } else {
                        let value = iterator_result_value(agent, &result)?;
                        // The element value is already unwrapped upstream —
                        // AsyncFromSyncIteratorContinuation awaits a sync
                        // iterable's value and an async generator's yield
                        // awaits its own — so the loop body consumes it
                        // directly (spec 14.7.5.7 awaits only the next()
                        // result). An extra await here costs a microtask and
                        // breaks the promise interleaving.
                        self.stack.push(value);
                    }
                }
                Step::AsyncForOfBind { left } => {
                    let value = self.pop();
                    self.for_binding_put(agent, left, value)?;
                }
                Step::AsyncForOfRestore => {
                    self.restore_per_iteration(agent)?;
                }
                Step::SwitchDisc => {
                    let disc = self.pop();
                    self.switch_disc = Some(disc);
                }
                Step::SwitchTest { case } => {
                    let test = self.pop();
                    let disc = self.switch_disc.as_ref().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::SyntaxError,
                            "SwitchTest without a discriminant".into(),
                        )
                    })?;
                    if crux::ops::is_strictly_equal(disc, &test) {
                        self.ip = *case;
                    }
                }
                Step::SetCompletion => {
                    let value = self.pop();
                    self.completion = value;
                    self.completion_is_empty = false;
                }
                Step::ResetCompletion => {
                    self.completion = Value::Undefined;
                    self.completion_is_empty = true;
                }
                Step::NormalizeCompletion => {
                    if self.completion_is_empty {
                        self.completion = Value::Undefined;
                        self.completion_is_empty = false;
                    }
                }
                Step::ListBegin => {
                    self.list_stack
                        .push((self.completion, self.completion_is_empty));
                    self.completion = Value::Undefined;
                    self.completion_is_empty = true;
                }
                Step::ListEnd => {
                    if let Some((value, empty)) = self.list_stack.pop()
                        && self.completion_is_empty
                    {
                        self.completion = value;
                        self.completion_is_empty = empty;
                    }
                }
                Step::SaveCompletion => {
                    self.completion_stack
                        .push((self.completion, self.completion_is_empty));
                }
                Step::RestoreCompletion => {
                    if let Some((value, empty)) = self.completion_stack.pop() {
                        self.completion = value;
                        self.completion_is_empty = empty;
                    }
                }
                Step::Jump(target) => {
                    // GC-5 safe point: a backward jump is a loop back-edge —
                    // pace the collection trigger on the allocation budget
                    // (a live-count read is too expensive per iteration).
                    if *target < self.ip && crux::heap::allocation_budget_exceeded() {
                        agent.maybe_collect();
                    }
                    self.ip = *target
                }
                Step::JumpIfFalse(target) => {
                    let value = self.pop();
                    if !crux::convert::to_boolean(&value) {
                        self.ip = *target;
                    }
                }
                Step::JumpIfLtImm { slot, imm, target } => {
                    self.jump_if_rel_imm(agent, BinaryOp::LessThan, *slot, *imm, *target)?
                }
                Step::JumpIfEqImm { slot, imm, target } => {
                    self.jump_if_strict_eq_imm(*slot, *imm, false, *target)?
                }
                Step::JumpIfNeqImm { slot, imm, target } => {
                    self.jump_if_strict_eq_imm(*slot, *imm, true, *target)?
                }
                Step::JumpIfLeImm { slot, imm, target } => {
                    self.jump_if_rel_imm(agent, BinaryOp::LessEqual, *slot, *imm, *target)?
                }
                Step::JumpIfGtImm { slot, imm, target } => {
                    self.jump_if_rel_imm(agent, BinaryOp::GreaterThan, *slot, *imm, *target)?
                }
                Step::JumpIfGeImm { slot, imm, target } => {
                    self.jump_if_rel_imm(agent, BinaryOp::GreaterEqual, *slot, *imm, *target)?
                }
                Step::JumpIfLtGlobalImm { name, imm, target } => {
                    self.jump_if_rel_global(agent, BinaryOp::LessThan, *name, *imm, *target)?
                }
                Step::JumpIfLeGlobalImm { name, imm, target } => {
                    self.jump_if_rel_global(agent, BinaryOp::LessEqual, *name, *imm, *target)?
                }
                Step::JumpIfGtGlobalImm { name, imm, target } => {
                    self.jump_if_rel_global(agent, BinaryOp::GreaterThan, *name, *imm, *target)?
                }
                Step::JumpIfGeGlobalImm { name, imm, target } => {
                    self.jump_if_rel_global(agent, BinaryOp::GreaterEqual, *name, *imm, *target)?
                }
                Step::JumpIfRelLimit {
                    op,
                    slot,
                    limit,
                    target,
                } => self.jump_if_rel_limit(agent, *op, *slot, *limit, *target)?,
                Step::TypedArrayLengthHoist { target } => {
                    // Gap-close M6 slice 2: pop the receiver; a probe-hit
                    // typed array (IntegerIndexed, no own `length`) pushes
                    // its effective length — the value the compiler stores
                    // in the hidden hoist slot; anything else jumps to the
                    // general per-iteration loop. Mirror of the runtime
                    // `typed_array_length` FFI probe; no user code runs.
                    let Some(receiver) = self.stack.pop() else {
                        return Err(JsError::new(
                            ErrorKind::SyntaxError,
                            "Value stack underflow".into(),
                        ));
                    };
                    if let ValueKind::Object(object_ref) = receiver.kind()
                        && let crux::object::ObjectKind::IntegerIndexed(slots) = &object_ref.kind
                        && !object_ref.has_own_property_atom(Self::length_atom())
                    {
                        self.stack
                            .push(Value::Number(
                                crux::object::typed_array_effective_length(slots) as f64,
                            ));
                    } else {
                        self.ip = *target;
                    }
                }
                Step::FastLoopHead {
                    var,
                    op,
                    limit,
                    inc,
                    body_start,
                    after,
                } => {
                    // GC-5 safe point: the fused canonical loop head is the
                    // loop's back-edge (increment + re-test + jump back) —
                    // pace the collection trigger on the allocation budget.
                    if crux::heap::allocation_budget_exceeded() {
                        agent.maybe_collect();
                    }
                    // The fused canonical loop head: increment, re-test, and
                    // jump back (or out) in one dispatch — the body dispatches
                    // inline in the main loop.
                    self.fast_loop_inc(agent, *var, *inc)?;
                    if !self.fast_loop_test(agent, *var, *op, *limit)? {
                        self.ip = *after;
                    } else {
                        self.ip = *body_start;
                    }
                }
                Step::FastLoopBind { var } => {
                    self.fast_loop_bind(agent, *var)?;
                }
                Step::FastLoopStore { var } => {
                    self.fast_loop_store(agent, *var)?;
                }
                Step::RunRegBody { ops } => {
                    // The register body addresses the current frame (the
                    // script's inline frame — `leaf_frame_base` is `None`
                    // here, so `frame_get` uses the `Frame`) and truncates
                    // its transient stack use. Since Cut 35 slice 21 the
                    // loop counter lives in the dedicated `loop_counter`
                    // field (the ops clobber the accumulator freely; a
                    // counter-reading body's `LoadCounter` reads the
                    // field), so no save/restore or entry push is needed.
                    // The body's completion is discarded — the loop
                    // machinery owns the loop's completion — but a throwing
                    // op (TDZ, a setter, a coercion) propagates after the
                    // truncate, like a throwing leaf.
                    let stack_len = self.stack.len();
                    let outcome = self.run_leaf_ops(agent, ops);
                    self.stack.truncate(stack_len);
                    match outcome {
                        Ok(_) => {}
                        Err(error) => return Err(error),
                    }
                }
                Step::PushAcc => {
                    // Cut 35 slice 21: the fused loop counter lives in the
                    // dedicated `loop_counter` field, not the accumulator;
                    // slice 22 made the field an f64, so the stack value is
                    // a Number wrap.
                    self.stack.push(Value::Number(self.loop_counter));
                }
                Step::PopAcc => {
                    // Cut 35 slice 22: the acc-path `counter = expr` gate
                    // admits only provably-Number RHSes, so the popped value
                    // is a Number.
                    let value = self.pop();
                    debug_assert!(
                        value.is_number(),
                        "the acc-path counter store is gated to a Number"
                    );
                    self.loop_counter = value.as_number().unwrap_or(0.0);
                }
                Step::IncAcc => {
                    // The field is a raw f64 holding a Number (the acc-path
                    // gates admit only Number inits/stores) — plain float
                    // arithmetic, no Value round-trip.
                    self.loop_counter += 1.0;
                }
                Step::DecAcc => {
                    self.loop_counter -= 1.0;
                }
                Step::LoadContextSlot { depth, index } => {
                    // Cut 3 continuation: the certified body's capture
                    // context (its lexical environment outside a
                    // per-iteration loop, where the lexical env holds only
                    // the loop head names); `depth` resolves an enclosing
                    // certified body's context along the chain.
                    let env = self.context_chain_env(*depth)?;
                    let value = context_env(&env).slot_value(*index);
                    match value {
                        Some(value) => self.stack.push(value),
                        None => {
                            return Err(JsError::new(
                                ErrorKind::ReferenceError,
                                "Cannot access a binding before initialization".into(),
                            ));
                        }
                    }
                }
                Step::StoreContextSlot { depth, index } => {
                    let value = self.pop();
                    let env = self.context_chain_env(*depth)?;
                    let declarative = context_env(&env);
                    // An assignment to a binding still in the TDZ throws.
                    if declarative.slot_value(*index).is_none() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    // The certified body's own const writes are rejected by
                    // the scan, but a nested closure's write to an enclosing
                    // `const` is only checked here: throw like the env path.
                    if !declarative.slot_mutable(*index) {
                        return Err(JsError::new(
                            ErrorKind::TypeError,
                            "Assignment to constant variable".into(),
                        ));
                    }
                    declarative.set_slot(*index, value);
                }
                Step::InitContextSlot { index } => {
                    let value = self.pop();
                    let env = self.context_chain_env(0)?;
                    context_env(&env).set_slot(*index, value);
                }
                Step::UpdateContextSlot {
                    depth,
                    index,
                    op,
                    prefix,
                } => {
                    let env = self.context_chain_env(*depth)?;
                    let declarative = context_env(&env);
                    let old = declarative.slot_value(*index).ok_or_else(|| {
                        JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        )
                    })?;
                    // An enclosing `const` (only reachable from a nested
                    // closure) must reject the update like the env path.
                    if !declarative.slot_mutable(*index) {
                        return Err(JsError::new(
                            ErrorKind::TypeError,
                            "Assignment to constant variable".into(),
                        ));
                    }
                    let (old_numeric, new) = update_value(agent, op, &old)?;
                    declarative.set_slot(*index, new);
                    self.stack.push(if *prefix { new } else { old_numeric });
                }
                Step::CreateArguments { slot, mapped } => {
                    // Cut 3 continuation: the strict body's unmapped
                    // arguments object, built from the call's arguments; a
                    // sloppy simple-param body gets the mapped object
                    // aliasing its formals through the capture context.
                    let value = match mapped {
                        Some(formals) => {
                            let func = agent
                                .running_context()?
                                .function
                                .unwrap_or(Value::Undefined);
                            let formals: Vec<JsString> =
                                formals.iter().map(|id| crux::lookup(*id)).collect();
                            crate::function::create_mapped_arguments_object(
                                agent,
                                func,
                                &self.call_args,
                                &formals,
                                self.lexical_env,
                            )?
                        }
                        None => crate::function::create_unmapped_arguments_object(
                            agent,
                            &self.call_args,
                        )?,
                    };
                    *self.frame_get_mut(*slot) = value;
                }
                Step::JumpIfTrue(target) => {
                    let value = self.pop();
                    if crux::convert::to_boolean(&value) {
                        self.ip = *target;
                    }
                }
                Step::JumpIfFalseKeep(target) => {
                    let value = self.pop();
                    if !crux::convert::to_boolean(&value) {
                        self.stack.push(value);
                        self.ip = *target;
                    } else {
                        // The left operand is not the result: leave it for the
                        // following Pop to discard (it was already popped).
                        self.stack.push(value);
                    }
                }
                Step::JumpIfTrueKeep(target) => {
                    let value = self.pop();
                    if crux::convert::to_boolean(&value) {
                        self.stack.push(value);
                        self.ip = *target;
                    } else {
                        self.stack.push(value);
                    }
                }
                Step::JumpIfNullishKeep(target) => {
                    let value = self.pop();
                    if is_nullish(&value) {
                        self.stack.push(value);
                        self.ip = *target;
                    }
                }
                Step::JumpIfNotNullishKeep(target) => {
                    let value = self.pop();
                    if !is_nullish(&value) {
                        self.stack.push(value);
                        self.ip = *target;
                    } else {
                        self.stack.push(value);
                    }
                }
                Step::Break { target } => {
                    match self.control_transfer(agent, body, Ctl::Break { target: *target })? {
                        CtlResult::Continue => continue,
                        CtlResult::Done(outcome) => return Ok(outcome),
                    }
                }
                Step::Continue { target } => {
                    match self.control_transfer(agent, body, Ctl::Continue { target: *target })? {
                        CtlResult::Continue => continue,
                        CtlResult::Done(outcome) => return Ok(outcome),
                    }
                }
                Step::InvalidAssignmentTarget => {
                    return Err(JsError::new(
                        ErrorKind::ReferenceError,
                        "Invalid left-hand side in assignment".into(),
                    ));
                }
                Step::Return => {
                    let value = self.pop();
                    match self.control_transfer(agent, body, Ctl::Return { value })? {
                        CtlResult::Continue => continue,
                        CtlResult::Done(outcome) => return Ok(outcome),
                    }
                }
                Step::Throw => {
                    let value = self.pop();
                    match self.throw_machinery(agent, body, value)? {
                        CtlResult::Continue => continue,
                        CtlResult::Done(outcome) => return Ok(outcome),
                    }
                }
                Step::Yield { delegate } => {
                    let value = self.pop();
                    return Ok(VmOutcome::Suspended(Suspension::Yield {
                        value,
                        delegate: *delegate,
                    }));
                }
                Step::Await => {
                    let value = self.pop();
                    return Ok(VmOutcome::Suspended(Suspension::Await(value)));
                }
                Step::YieldStarBegin => {
                    let value = self.pop();
                    // GetIterator runs inside the generator body, so its
                    // TypeError is catchable by the body's try/catch (spec
                    // 15.5.5 step 4 uses `?`).
                    let iterator = match get_iterator(agent, &value) {
                        Ok(iterator) => iterator,
                        Err(error) => match self.throw_js_error(agent, body, error)? {
                            CtlResult::Continue => continue,
                            CtlResult::Done(outcome) => return Ok(outcome),
                        },
                    };
                    self.yield_star_stack.push(YieldStarState {
                        iterator,
                        received: Value::Undefined,
                        resumed_return: false,
                    });
                }
                Step::YieldStarNext { done } => {
                    let Some(state) = self.yield_star_stack.last() else {
                        return Err(JsError::new(
                            ErrorKind::SyntaxError,
                            "YieldStarNext without a delegation".into(),
                        ));
                    };
                    let received = state.received;
                    let iterator = state.iterator.clone();
                    let next = match crate::expr::iterator_next_method(agent, &iterator) {
                        Ok(next) => next,
                        Err(error) => match self.throw_js_error(agent, body, error)? {
                            CtlResult::Continue => continue,
                            CtlResult::Done(outcome) => return Ok(outcome),
                        },
                    };
                    let result =
                        match crate::function::call(agent, &next, iterator.iterator, &[received]) {
                            Ok(result) => result,
                            Err(error) => match self.throw_js_error(agent, body, error)? {
                                CtlResult::Continue => continue,
                                CtlResult::Done(outcome) => return Ok(outcome),
                            },
                        };
                    if !matches!(result.kind(), ValueKind::Object(_)) {
                        // Spec 15.5.5 normal case step a.iii.
                        let error = JsError::new(
                            ErrorKind::TypeError,
                            "yield*: iterator next() result is not an object".into(),
                        );
                        match self.throw_js_error(agent, body, error)? {
                            CtlResult::Continue => continue,
                            CtlResult::Done(outcome) => return Ok(outcome),
                        }
                    }
                    let done_flag = match iterator_result_done(agent, &result) {
                        Ok(done_flag) => done_flag,
                        Err(error) => match self.throw_js_error(agent, body, error)? {
                            CtlResult::Continue => continue,
                            CtlResult::Done(outcome) => return Ok(outcome),
                        },
                    };
                    if done_flag {
                        let value = match iterator_result_value(agent, &result) {
                            Ok(value) => value,
                            Err(error) => match self.throw_js_error(agent, body, error)? {
                                CtlResult::Continue => continue,
                                CtlResult::Done(outcome) => return Ok(outcome),
                            },
                        };
                        self.yield_star_stack.pop();
                        self.stack.push(value);
                        self.ip = *done;
                    } else {
                        // Spec 15.5.5: GeneratorYield(innerResult) yields the
                        // inner iterator result object itself, so the outer
                        // consumer reads its `value`/`done` lazily.
                        self.stack.push(result);
                    }
                }
                Step::YieldStarResume {
                    loop_top,
                    done,
                    yield_at,
                } => {
                    let received = self.pop();
                    match self.resume_abrupt.take() {
                        None => {
                            if let Some(state) = self.yield_star_stack.last_mut() {
                                state.received = received;
                            }
                            self.ip = *loop_top;
                        }
                        Some(ResumeAbrupt::Throw(value)) => {
                            let Some(state) = self.yield_star_stack.last() else {
                                return Err(JsError::new(
                                    ErrorKind::SyntaxError,
                                    "YieldStarResume without a delegation".into(),
                                ));
                            };
                            let iterator = state.iterator.clone();
                            // GetMethod(iterator, "throw"); errors propagate
                            // through the generator body's handlers (spec
                            // 15.5.5 throw case).
                            let throw_method = match crate::context::get_property(
                                agent,
                                &iterator.iterator,
                                &JsString::from_utf8("throw"),
                                iterator.iterator,
                            ) {
                                Ok(method) => method,
                                Err(error) => match self.throw_js_error(agent, body, error)? {
                                    CtlResult::Continue => continue,
                                    CtlResult::Done(outcome) => return Ok(outcome),
                                },
                            };
                            if is_callable(&throw_method) {
                                let inner = match crate::function::call(
                                    agent,
                                    &throw_method,
                                    iterator.iterator,
                                    &[value],
                                ) {
                                    Ok(inner) => inner,
                                    Err(error) => match self.throw_js_error(agent, body, error)? {
                                        CtlResult::Continue => continue,
                                        CtlResult::Done(outcome) => return Ok(outcome),
                                    },
                                };
                                if !matches!(inner.kind(), ValueKind::Object(_)) {
                                    // Spec 15.5.5 throw case step b.iii.
                                    let error = JsError::new(
                                        ErrorKind::TypeError,
                                        "yield*: iterator throw() result is not an object".into(),
                                    );
                                    match self.throw_js_error(agent, body, error)? {
                                        CtlResult::Continue => continue,
                                        CtlResult::Done(outcome) => return Ok(outcome),
                                    }
                                }
                                let done_flag = match iterator_result_done(agent, &inner) {
                                    Ok(done_flag) => done_flag,
                                    Err(error) => match self.throw_js_error(agent, body, error)? {
                                        CtlResult::Continue => continue,
                                        CtlResult::Done(outcome) => return Ok(outcome),
                                    },
                                };
                                if done_flag {
                                    let value = match iterator_result_value(agent, &inner) {
                                        Ok(value) => value,
                                        Err(error) => {
                                            match self.throw_js_error(agent, body, error)? {
                                                CtlResult::Continue => continue,
                                                CtlResult::Done(outcome) => return Ok(outcome),
                                            }
                                        }
                                    };
                                    self.yield_star_stack.pop();
                                    self.stack.push(value);
                                    self.ip = *done;
                                } else {
                                    self.stack.push(inner);
                                    self.ip = *yield_at;
                                }
                            } else {
                                // No throw method: IteratorClose with a normal
                                // completion, then a protocol-violation
                                // TypeError. Errors from the close propagate
                                // (spec 15.5.5 throw case, no-throw branch).
                                if let Err(error) = iterator_close(agent, &iterator) {
                                    match self.throw_js_error(agent, body, error)? {
                                        CtlResult::Continue => continue,
                                        CtlResult::Done(outcome) => return Ok(outcome),
                                    }
                                }
                                self.yield_star_stack.pop();
                                let violation = JsError::new(
                                    ErrorKind::TypeError,
                                    "yield* protocol violation: iterator has no throw method"
                                        .into(),
                                );
                                match self.throw_js_error(agent, body, violation)? {
                                    CtlResult::Continue => continue,
                                    CtlResult::Done(outcome) => return Ok(outcome),
                                }
                            }
                        }
                        Some(ResumeAbrupt::Return(value)) => {
                            let Some(state) = self.yield_star_stack.last() else {
                                return Err(JsError::new(
                                    ErrorKind::SyntaxError,
                                    "YieldStarResume without a delegation".into(),
                                ));
                            };
                            let iterator = state.iterator.clone();
                            // GetMethod(iterator, "return"); errors propagate
                            // through the generator body's handlers (spec
                            // 15.5.5 return case).
                            let return_method = match crate::context::get_property(
                                agent,
                                &iterator.iterator,
                                &JsString::from_utf8("return"),
                                iterator.iterator,
                            ) {
                                Ok(method) => method,
                                Err(error) => match self.throw_js_error(agent, body, error)? {
                                    CtlResult::Continue => continue,
                                    CtlResult::Done(outcome) => return Ok(outcome),
                                },
                            };
                            if is_callable(&return_method) {
                                let inner = match crate::function::call(
                                    agent,
                                    &return_method,
                                    iterator.iterator,
                                    &[value],
                                ) {
                                    Ok(inner) => inner,
                                    Err(error) => match self.throw_js_error(agent, body, error)? {
                                        CtlResult::Continue => continue,
                                        CtlResult::Done(outcome) => return Ok(outcome),
                                    },
                                };
                                if !matches!(inner.kind(), ValueKind::Object(_)) {
                                    // Spec 15.5.5 return case step c.vi.
                                    let error = JsError::new(
                                        ErrorKind::TypeError,
                                        "yield*: iterator return() result is not an object".into(),
                                    );
                                    match self.throw_js_error(agent, body, error)? {
                                        CtlResult::Continue => continue,
                                        CtlResult::Done(outcome) => return Ok(outcome),
                                    }
                                }
                                let done_flag = match iterator_result_done(agent, &inner) {
                                    Ok(done_flag) => done_flag,
                                    Err(error) => match self.throw_js_error(agent, body, error)? {
                                        CtlResult::Continue => continue,
                                        CtlResult::Done(outcome) => return Ok(outcome),
                                    },
                                };
                                if done_flag {
                                    // A done return result completes the
                                    // generator with ReturnCompletion of its
                                    // value (spec 15.5.5 return case).
                                    let value = match iterator_result_value(agent, &inner) {
                                        Ok(value) => value,
                                        Err(error) => {
                                            match self.throw_js_error(agent, body, error)? {
                                                CtlResult::Continue => continue,
                                                CtlResult::Done(outcome) => return Ok(outcome),
                                            }
                                        }
                                    };
                                    self.yield_star_stack.pop();
                                    match self.control_transfer(
                                        agent,
                                        body,
                                        Ctl::Return { value },
                                    )? {
                                        CtlResult::Continue => continue,
                                        CtlResult::Done(outcome) => return Ok(outcome),
                                    }
                                } else {
                                    self.stack.push(inner);
                                    self.ip = *yield_at;
                                }
                            } else {
                                // No return method: the delegation completes
                                // with the return completion carrying the
                                // received value (spec 15.5.5 return case).
                                self.yield_star_stack.pop();
                                match self.control_transfer(agent, body, Ctl::Return { value })? {
                                    CtlResult::Continue => continue,
                                    CtlResult::Done(outcome) => return Ok(outcome),
                                }
                            }
                        }
                    }
                }
                Step::AsyncYieldStarBegin => {
                    let value = self.pop();
                    let iterator = get_async_iterator_record(agent, &value)?;
                    self.yield_star_stack.push(YieldStarState {
                        iterator,
                        received: Value::Undefined,
                        resumed_return: false,
                    });
                }
                Step::AsyncYieldStarNext { done: _ } => {
                    let Some(state) = self.yield_star_stack.last() else {
                        return Err(JsError::new(
                            ErrorKind::SyntaxError,
                            "AsyncYieldStarNext without a delegation".into(),
                        ));
                    };
                    let received = state.received;
                    let iterator = state.iterator.clone();
                    let next = crate::expr::iterator_next_method(agent, &iterator)?;
                    let result =
                        crate::function::call(agent, &next, iterator.iterator, &[received])?;
                    // The await resume pushes the fulfilled iterator result.
                    return Ok(VmOutcome::Suspended(Suspension::Await(result)));
                }
                Step::AsyncYieldStarInspect { done } => {
                    let result = self.pop();
                    if !matches!(result.kind(), ValueKind::Object(_) | ValueKind::Function(_)) {
                        // spec 15.5.5: the awaited inner result must be an
                        // object (the check runs after the await, so a
                        // non-object value's `then` is never consulted).
                        let error = JsError::new(
                            ErrorKind::TypeError,
                            "yield*: iterator result is not an object".into(),
                        );
                        match self.throw_js_error(agent, body, error)? {
                            CtlResult::Continue => continue,
                            CtlResult::Done(outcome) => return Ok(outcome),
                        }
                    }
                    let done_flag = match iterator_result_done(agent, &result) {
                        Ok(done_flag) => done_flag,
                        Err(error) => match self.throw_js_error(agent, body, error)? {
                            CtlResult::Continue => continue,
                            CtlResult::Done(outcome) => return Ok(outcome),
                        },
                    };
                    if done_flag {
                        // Getter errors are catchable by the body (spec
                        // 15.5.5 uses `?` on IteratorValue).
                        let value = match iterator_result_value(agent, &result) {
                            Ok(value) => value,
                            Err(error) => match self.throw_js_error(agent, body, error)? {
                                CtlResult::Continue => continue,
                                CtlResult::Done(outcome) => return Ok(outcome),
                            },
                        };
                        let resumed_return = self
                            .yield_star_stack
                            .last()
                            .is_some_and(|state| state.resumed_return);
                        self.yield_star_stack.pop();
                        if resumed_return {
                            // spec 15.5.5 return case: a done return result
                            // completes the body with a return completion of
                            // its value.
                            match self.control_transfer(agent, body, Ctl::Return { value })? {
                                CtlResult::Continue => continue,
                                CtlResult::Done(outcome) => return Ok(outcome),
                            }
                        } else {
                            // The loop's done case: the yield* expression
                            // completes with the value and the body continues.
                            self.stack.push(value);
                            self.ip = *done;
                        }
                    } else {
                        let value = match iterator_result_value(agent, &result) {
                            Ok(value) => value,
                            Err(error) => match self.throw_js_error(agent, body, error)? {
                                CtlResult::Continue => continue,
                                CtlResult::Done(outcome) => return Ok(outcome),
                            },
                        };
                        self.stack.push(value);
                    }
                }
                Step::AsyncYieldStarResume {
                    loop_top,
                    done: _,
                    inspect,
                } => {
                    let received = self.pop();
                    match self.resume_abrupt.take() {
                        None => {
                            if let Some(state) = self.yield_star_stack.last_mut() {
                                state.received = received;
                                state.resumed_return = false;
                            }
                            self.ip = *loop_top;
                        }
                        Some(ResumeAbrupt::Throw(value)) => {
                            let (iterator,) = {
                                let Some(state) = self.yield_star_stack.last() else {
                                    return Err(JsError::new(
                                        ErrorKind::SyntaxError,
                                        "AsyncYieldStarResume without a delegation".into(),
                                    ));
                                };
                                (state.iterator.clone(),)
                            };
                            if let Some(state) = self.yield_star_stack.last_mut() {
                                state.resumed_return = false;
                            }
                            let throw_method = crate::context::get_property(
                                agent,
                                &iterator.iterator,
                                &JsString::from_utf8("throw"),
                                iterator.iterator,
                            )?;
                            if is_callable(&throw_method) {
                                let inner = crate::function::call(
                                    agent,
                                    &throw_method,
                                    iterator.iterator,
                                    &[value],
                                )?;
                                self.ip = *inspect;
                                return Ok(VmOutcome::Suspended(Suspension::Await(inner)));
                            }
                            iterator_close(agent, &iterator)?;
                            self.yield_star_stack.pop();
                            // spec 15.5.5 throw case, no-throw branch: after
                            // closing, the protocol violation is a TypeError.
                            let violation = JsError::new(
                                ErrorKind::TypeError,
                                "yield* protocol violation: iterator has no throw method".into(),
                            );
                            match self.throw_js_error(agent, body, violation)? {
                                CtlResult::Continue => continue,
                                CtlResult::Done(outcome) => return Ok(outcome),
                            }
                        }
                        Some(ResumeAbrupt::Return(value)) => {
                            let iterator = {
                                let Some(state) = self.yield_star_stack.last() else {
                                    return Err(JsError::new(
                                        ErrorKind::SyntaxError,
                                        "AsyncYieldStarResume without a delegation".into(),
                                    ));
                                };
                                state.iterator.clone()
                            };
                            if let Some(state) = self.yield_star_stack.last_mut() {
                                state.resumed_return = true;
                            }
                            let return_method = crate::context::get_property(
                                agent,
                                &iterator.iterator,
                                &JsString::from_utf8("return"),
                                iterator.iterator,
                            )?;
                            if is_callable(&return_method) {
                                let inner = crate::function::call(
                                    agent,
                                    &return_method,
                                    iterator.iterator,
                                    &[value],
                                )?;
                                self.ip = *inspect;
                                return Ok(VmOutcome::Suspended(Suspension::Await(inner)));
                            }
                            self.yield_star_stack.pop();
                            // spec 15.5.5 return case step b: no return
                            // method — await the received value, then return
                            // it (the driver resumes with `Resume::Return`).
                            return Ok(VmOutcome::Suspended(Suspension::AwaitReturn(value)));
                        }
                    }
                }
                Step::ImportCall { has_options, phase } => {
                    let options = if *has_options { Some(self.pop()) } else { None };
                    let specifier = self.pop();
                    let promise =
                        crate::module::dynamic_import(agent, &specifier, options.as_ref(), *phase)?;
                    self.stack.push(promise);
                }
                Step::ImportMeta => {
                    let meta = crate::module::import_meta(agent)?;
                    self.stack.push(meta);
                }
            }
        }
    }

    /// Convert an internal error into a thrown value routed through the
    /// handler table.
    fn throw_error(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        error: JsError,
    ) -> Result<VmOutcome, JsError> {
        // Engine errors throw as real Error objects (spec ch. 17), matching
        // the interpreter path (`to_throwable`); the message string is the
        // fallback until the built-ins are installed.
        let value = match crate::builtins::error::to_throwable(agent, &error) {
            Ok(value) => value,
            Err(_) => error_message_value(&error),
        };
        match self.throw_machinery(agent, body, value)? {
            CtlResult::Continue => self.run_inner(agent, body),
            CtlResult::Done(outcome) => Ok(outcome),
        }
    }

    /// Begin disposing a scope's `using` resources in reverse order, folding
    /// each result into the completion (spec 9.4.3). When an async-dispose
    /// awaits, the driver suspends with `Suspension::Await`; `run_abrupt`
    /// resumes it with the settled value. Returns `Some(outcome)` when the
    /// VM run finished (the folded completion ended the body), `None` when
    /// the run continues from the current ip.
    fn start_scope_disposal(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        resources: Vec<crate::env::DisposableResource>,
        completion: Completion,
        resume: DisposalResume,
    ) -> Result<Option<VmOutcome>, JsError> {
        self.pending_disposal = Some(PendingDisposal {
            resources,
            index: 0,
            completion,
            resume,
        });
        self.drive_pending_disposal(agent, body)
    }

    /// Drive the pending scope disposal: dispose the next resource, awaiting
    /// async-dispose results through the suspension machinery.
    fn drive_pending_disposal(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
    ) -> Result<Option<VmOutcome>, JsError> {
        loop {
            let Some(pending) = self.pending_disposal.as_ref() else {
                return Ok(None);
            };
            if pending.index >= pending.resources.len() {
                let pending = self.pending_disposal.take().unwrap();
                let completion = pending.completion;
                return Ok(match pending.resume {
                    DisposalResume::ApplyCompletion => match completion {
                        Completion::Normal(value) => {
                            self.completion = value;
                            None
                        }
                        Completion::Empty => None,
                        Completion::Throw(value) => {
                            match self.throw_machinery(agent, body, value)? {
                                CtlResult::Continue => None,
                                CtlResult::Done(outcome) => Some(outcome),
                            }
                        }
                        _ => {
                            return Err(JsError::new(
                                ErrorKind::SyntaxError,
                                "Illegal disposal completion".into(),
                            ));
                        }
                    },
                    DisposalResume::DeliverCatch {
                        saved_env,
                        env_depth,
                    } => {
                        // The disposal started from a throw, so the folded
                        // completion stays a throw; deliver it to the catch.
                        let value = match completion {
                            Completion::Throw(value) => value,
                            Completion::Normal(value) => value,
                            Completion::Empty => Value::Undefined,
                            _ => Value::Undefined,
                        };
                        self.thrown = Some(value);
                        self.restore_env(saved_env, env_depth);
                        None
                    }
                });
            }
            let resource = pending.resources[pending.index].clone();
            let method_result = if resource.method.is_undefined() {
                if resource.hint == crate::env::DisposalHint::Sync {
                    // Dispose with an undefined method and sync hint: no call
                    // and no await (spec 9.4.4 steps 1-4).
                    self.pending_disposal.as_mut().unwrap().index += 1;
                    continue;
                }
                // Async hint: Dispose returns undefined but still
                // Await(undefined) — a microtask boundary (spec 9.4.4 step
                // 3.a).
                Ok(Value::Undefined)
            } else {
                crate::function::call(agent, &resource.method, resource.value, &[])
            };
            match method_result {
                Err(error) => {
                    let value = crate::promise::error_value(agent, &error);
                    self.fold_disposal_error(agent, value)?;
                    self.pending_disposal.as_mut().unwrap().index += 1;
                }
                Ok(value) => {
                    if resource.hint == crate::env::DisposalHint::Sync {
                        self.pending_disposal.as_mut().unwrap().index += 1;
                        continue;
                    }
                    let promise_ctor = agent
                        .current_realm()?
                        .intrinsics
                        .get("%Promise%")
                        .unwrap_or(Value::Undefined);
                    let promise = crate::promise::promise_resolve(agent, &promise_ctor, value)?;
                    return Ok(Some(VmOutcome::Suspended(Suspension::Await(promise))));
                }
            }
        }
    }

    /// The await of an async dispose settled: fold the result into the
    /// pending disposal and keep driving. A rejected dispose is a throwing
    /// disposal — it never routes through the body's handler table.
    fn resume_pending_disposal(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        result: Result<Value, Value>,
    ) -> Result<VmOutcome, JsError> {
        if let Err(value) = result {
            self.fold_disposal_error(agent, value)?;
        }
        let Some(pending) = self.pending_disposal.as_mut() else {
            return self.run_inner(agent, body);
        };
        pending.index += 1;
        match self.drive_pending_disposal(agent, body)? {
            Some(outcome) => Ok(outcome),
            None => self.run_inner(agent, body),
        }
    }

    /// Fold a throwing disposal into the pending completion: a normal
    /// completion becomes the throw; a second throw nests a SuppressedError
    /// (spec 9.4.3 step 1.b).
    fn fold_disposal_error(&mut self, agent: &mut Agent, new_error: Value) -> Result<(), JsError> {
        let pending = self
            .pending_disposal
            .as_mut()
            .ok_or_else(|| JsError::new(ErrorKind::TypeError, "no disposal in flight".into()))?;
        pending.completion = match std::mem::replace(&mut pending.completion, Completion::Empty) {
            Completion::Throw(original) => Completion::Throw(
                crate::builtins::disposable::make_suppressed_error(agent, new_error, original)?,
            ),
            _ => Completion::Throw(new_error),
        };
        Ok(())
    }

    /// The Await algorithm (spec 27.6.3.1) is driven by the async-function
    /// machinery: the VM suspends with the operand, and the driver attaches
    /// promise reactions that resume it.
    fn assign_ident(
        &mut self,
        agent: &mut Agent,
        name: crux::AtomId,
        op: AssignOp,
        set_name: bool,
    ) -> Result<(), JsError> {
        let reference = crate::context::resolve_binding(agent, &crux::lookup(name), self.strict)?;
        match op {
            AssignOp::Assign => {
                let value = self.pop();
                if set_name {
                    let display =
                        crate::function::default_binding_display_name(Some(crux::lookup(name)))
                            .unwrap_or_else(|| crux::lookup(name));
                    crate::function::set_function_name(&value, &display, None)?;
                }
                crate::context::put_value(agent, &reference, value)?;
                self.stack.push(value);
            }
            AssignOp::AndAssign | AssignOp::OrAssign | AssignOp::NullishAssign => {
                let value = self.pop();
                self.pop(); // old
                crate::context::put_value(agent, &reference, value)?;
                self.stack.push(value);
            }
            _ => {
                let value = self.pop();
                let old = self.pop();
                let new = crate::expr::apply_compound(agent, op, &old, &value)?;
                crate::context::put_value(agent, &reference, new)?;
                self.stack.push(new);
            }
        }
        Ok(())
    }

    /// The plain-assign computed member store (spec 13.15.4): the shared
    /// body of the `AssignMemberComputed` step's plain `=` path and the
    /// register `StoreMemberComputed` op. The nullish check, the fast array
    /// element write (a canonical Number index on a plain Array — the
    /// number→string→intern and [[Set]] chain machinery are skipped;
    /// `array_element_write` falls back on any doubt), then the
    /// property-key conversion and `assign_member`. Pushes the assigned
    /// value (the step path's result; the register frame truncate discards
    /// it).
    pub(crate) fn assign_computed_plain(
        &mut self,
        agent: &mut Agent,
        object: Value,
        key: Value,
        value: Value,
    ) -> Result<(), JsError> {
        if is_nullish(&object) {
            return Err(nullish_error("Cannot set properties of null"));
        }
        if let ValueKind::Number(number) = key.kind()
            && number.fract() == 0.0
            && (0.0..4294967295.0).contains(&number)
            && let ValueKind::Object(object_ref) = object.kind()
        {
            let index = number as u64;
            if matches!(object_ref.kind, crux::object::ObjectKind::Array(_))
                && object_ref.array_element_write(index, value)?.is_some()
            {
                self.stack.push(value);
                return Ok(());
            }
            // A typed array writes the element by numeric index directly —
            // no number→string→parse round trip (sequential indices were
            // O(n²) in the interner memos).
            if let crux::object::ObjectKind::IntegerIndexed(slots) = &object_ref.kind
                && object_ref.typed_array_element_set(slots, index, value)?
            {
                self.stack.push(value);
                return Ok(());
            }
        }
        let key = crate::context::to_property_key(agent, &key)?;
        self.assign_member(
            agent,
            object,
            PropertyKeyName::Key(key),
            None,
            value,
            AssignOp::Assign,
        )
    }

    /// The shared named member read (the `GetMemberName` step and the
    /// register `GetMemberName` op): the nullish check, the direct-mapped
    /// member-cell cache, then the property machinery (a getter runs on
    /// this Vm — the leaf callers handle the nested state exactly like the
    /// step path). Returns the value; the step path pushes it, the register
    /// op stores it in the accumulator.
    pub(crate) fn get_member_name(
        &self,
        agent: &mut Agent,
        object: Value,
        name: crux::AtomId,
    ) -> Result<Value, JsError> {
        if is_nullish(&object) {
            return Err(nullish_error("Cannot read properties of null"));
        }
        // A primitive string's `length` is its code-unit count (spec
        // 10.4.3.4 StringGet step 1 — an own virtual property on the boxed
        // receiver, so no prototype consult). The general path would ToObject
        // the primitive into a fresh String-exotic wrapper (a 448B JsObject +
        // a 64B [[StringData]] copy) per read; hot string loops read
        // `.length` every iteration. A boxed String OBJECT is not a primitive
        // (its ordinary machinery applies; the shortcut is only for the raw
        // value).
        if name == Self::length_atom()
            && let ValueKind::String(s) = object.kind()
        {
            return Ok(Value::Number(s.len() as f64));
        }
        // A typed array's `length` is a prototype accessor; serving it from
        // the slots skips the accessor invocation, which the fixture
        // byte-copy loops read every iteration (~6.6µs per accessor call).
        // An own `length` shadows the accessor (spec OrdinaryGet — a
        // define-created own property wins), so the shortcut fires only when
        // none exists: the check is a plain (usually empty) vector scan, no
        // key-string parse.
        if name == Self::length_atom()
            && let ValueKind::Object(object_ref) = object.kind()
            && let crux::object::ObjectKind::IntegerIndexed(slots) = &object_ref.kind
            && !object_ref.has_own_property_atom(name)
        {
            return Ok(Value::Number(
                crux::object::typed_array_effective_length(slots) as f64,
            ));
        }
        match Self::member_cell_get(agent, &object, name) {
            Some(value) => Ok(value),
            None => {
                // A prototype-chain read (a method like `f.apply`/`arr.push`
                // — the property lives on a prototype, so the own-property
                // cells never serve it): the chain cache re-validates the
                // walked links instead of re-walking them.
                if let Some(value) = Self::member_chain_get(agent, &object, name) {
                    return Ok(value);
                }
                let value =
                    if !matches!(object.kind(), ValueKind::Object(_) | ValueKind::Function(_)) {
                        Self::get_primitive_member(agent, object, &PropertyKey::String(name))?
                    } else {
                        crate::context::get_property(agent, &object, &crux::lookup(name), object)?
                    };
                Self::resolve_member_cell(agent, &object, name);
                Self::resolve_chain_cell(agent, &object, name);
                Ok(value)
            }
        }
    }

    /// The interned "length" atom, cached once (the fixture byte-copy loops
    /// read `view.length` every iteration, so the fast-path probe must not
    /// re-intern per read).
    fn length_atom() -> crux::AtomId {
        use std::sync::OnceLock;
        static LENGTH: OnceLock<crux::AtomId> = OnceLock::new();
        *LENGTH.get_or_init(|| crux::string::intern_utf8("length"))
    }

    /// Serve a property read on a PRIMITIVE without building the per-read
    /// wrapper the generic [[Get]] pays on primitives (a 448B JsObject —
    /// plus a 64B [[StringData]] copy for strings). Exact for the same
    /// reason in every kind: the engine threads the PRIMITIVE as the [[Get]]
    /// receiver (spec 10.4.3.4: StringExoticObject.[[Get]] passes Receiver
    /// through to OrdinaryGet; the other primitive wrappers are ordinary
    /// objects with no own properties), so a read starting at the kind's
    /// %X.prototype% with the primitive receiver reproduces the boxed read
    /// for every key — chain data properties and accessors (which see `this`
    /// = the primitive, exactly as the boxed path's receiver threading
    /// already does), exotic/proxy links, and missing keys. The one exotic
    /// wrapper — the String box — contributes virtual own `length` and
    /// in-range canonical indices, handled here (spec 10.4.3.5
    /// StringGetOwnProperty). Object/function receivers fall through to the
    /// generic path unchanged.
    fn get_primitive_member(
        agent: &mut Agent,
        receiver: Value,
        key: &PropertyKey,
    ) -> Result<Value, JsError> {
        match receiver.kind() {
            ValueKind::String(s) => {
                if let PropertyKey::String(atom) = key {
                    if *atom == Self::length_atom() {
                        return Ok(Value::Number(s.len() as f64));
                    }
                    if let Some(index) = crux::object::array_index_of(key)
                        && index < s.len() as u64
                    {
                        let unit = s.as_slice()[index as usize];
                        return Ok(Value::String(Handle::new(JsString::from_utf16(&[unit]))));
                    }
                }
                let realm = agent.current_realm()?;
                let Some(proto) = realm.intrinsics.string_prototype() else {
                    return crate::context::get_property_key(agent, &receiver, key, receiver);
                };
                crate::context::get_property_key(agent, &proto, key, receiver)
            }
            ValueKind::Number(_)
            | ValueKind::Boolean(_)
            | ValueKind::BigInt(_)
            | ValueKind::Symbol(_) => {
                let name = match receiver.kind() {
                    ValueKind::Number(_) => "%Number.prototype%",
                    ValueKind::Boolean(_) => "%Boolean.prototype%",
                    ValueKind::BigInt(_) => "%BigInt.prototype%",
                    ValueKind::Symbol(_) => "%Symbol.prototype%",
                    _ => unreachable!("matched above"),
                };
                let realm = agent.current_realm()?;
                let Some(proto) = realm.intrinsics.primitive_prototype(name) else {
                    return crate::context::get_property_key(agent, &receiver, key, receiver);
                };
                crate::context::get_property_key(agent, &proto, key, receiver)
            }
            _ => crate::context::get_property_key(agent, &receiver, key, receiver),
        }
    }

    /// The shared computed member read (the `GetMemberComputed` step and
    /// the register `GetMemberComputed` op): nullish check, the fast array
    /// element read (a canonical Number index on a plain Array), then the
    /// property-key conversion + member-cell/property machinery.
    pub(crate) fn get_member_computed(
        &self,
        agent: &mut Agent,
        object: Value,
        key: Value,
    ) -> Result<Value, JsError> {
        if is_nullish(&object) {
            return Err(nullish_error("Cannot read properties of null"));
        }
        // A Number key converts purely (ToPropertyKey of a number runs no
        // user code), so a canonical array index reads the element directly.
        let numeric = match key.kind() {
            ValueKind::Number(number)
                if number.fract() == 0.0 && (0.0..4294967295.0).contains(&number) =>
            {
                Some(number as u64)
            }
            _ => None,
        };
        if let Some(index) = numeric
            && let Some(value) = Self::array_element_get(agent, &object, index)
        {
            return Ok(value);
        }
        // A typed array reads the element by numeric index directly — no
        // number→string→parse round trip (sequential indices were O(n²) in
        // the interner memos). An invalid index reads *undefined* (spec
        // 10.4.7.5), so the fast path covers every Number key.
        if let Some(index) = numeric
            && let ValueKind::Object(object_ref) = object.kind()
            && let crux::object::ObjectKind::IntegerIndexed(slots) = &object_ref.kind
        {
            return object_ref.typed_array_element_get(slots, index);
        }
        // A primitive string's in-range canonical index is an OWN data
        // property holding the single code unit (spec 10.4.3.5
        // StringGetOwnProperty) — the boxed wrapper's own descriptor wins
        // over the whole prototype chain, so no wrapper and no chain walk
        // (reading a string's units by index is the exact analog of the
        // array element fast path above). Out-of-range falls through: the
        // chain may hold the key (e.g. a patched `%String.prototype%`).
        if let Some(index) = numeric
            && let ValueKind::String(s) = object.kind()
            && let Some(unit) = s.as_slice().get(index as usize)
        {
            return Ok(Value::String(Handle::new(JsString::from_utf16(&[*unit]))));
        }
        let key = crate::context::to_property_key(agent, &key)?;
        let value = if !matches!(object.kind(), ValueKind::Object(_) | ValueKind::Function(_)) {
            Self::get_primitive_member(agent, object, &key)?
        } else {
            match &key {
                PropertyKey::String(atom) => match Self::member_cell_get(agent, &object, *atom) {
                    Some(value) => value,
                    None => {
                        let value = crate::context::get_property_key(agent, &object, &key, object)?;
                        Self::resolve_member_cell(agent, &object, *atom);
                        value
                    }
                },
                _ => crate::context::get_property_key(agent, &object, &key, object)?,
            }
        };
        if let Some(index) = numeric {
            Self::resolve_array_element(agent, &object, index);
        }
        Ok(value)
    }

    /// The register member-write tail for the fused computed RMW ops:
    /// `assign_member` (whose pushed result is the step path's expression
    /// value) followed by popping that push — the register path discards the
    /// result. Push-neutral, so the ops' JIT slow-helper calls need no
    /// balancing pop (the numeric fast paths return without any push).
    fn assign_member_discard(
        &mut self,
        agent: &mut Agent,
        object: Value,
        key: PropertyKeyName,
        value: Value,
    ) -> Result<(), JsError> {
        self.assign_member(agent, object, key, None, value, AssignOp::Assign)?;
        self.stack.pop();
        Ok(())
    }

    /// The register computed-member compound (`o[k] op= v`, the
    /// `CompoundMemberComputedLocal` op): the nullish check, then the key is
    /// converted ONCE and the old value read through the member cell, the
    /// compound applied to the caller-resolved RHS value, and the result
    /// stored through the SAME key. Sound because the step path's
    /// `GetMemberComputedKeep` also converts before the read and hands the
    /// write the converted key (spec 13.15.3) — re-converting an object key
    /// at a separate store op would re-run its ToPropertyKey after the
    /// read's getters. A canonical Number key on a dense Array or typed
    /// array runs no user code (ToPropertyKey of a Number is pure), so the
    /// element paths serve the read AND the write directly with no key
    /// conversion — mirroring `get_member_computed`'s numeric read and
    /// `assign_computed_plain`'s numeric write.
    pub(crate) fn compound_member_computed(
        &mut self,
        agent: &mut Agent,
        object: Value,
        key: Value,
        op: AssignOp,
        value: Value,
    ) -> Result<(), JsError> {
        if is_nullish(&object) {
            return Err(nullish_error("Cannot read properties of null"));
        }
        let numeric = match key.kind() {
            ValueKind::Number(number)
                if number.fract() == 0.0 && (0.0..4294967295.0).contains(&number) =>
            {
                Some(number as u64)
            }
            _ => None,
        };
        if let Some(index) = numeric
            && let ValueKind::Object(object_ref) = object.kind()
        {
            // Dense/spilled arrays: a present element reads fast; a hole
            // reads None and falls to the general path (the array's ordinary
            // [[Get]] sees the chain).
            if let Some(old) = Self::array_element_get(agent, &object, index) {
                let new = crate::expr::apply_compound(agent, op, &old, &value)?;
                if matches!(object_ref.kind, crux::object::ObjectKind::Array(_))
                    && object_ref.array_element_write(index, new)?.is_some()
                {
                    return Ok(());
                }
                // The element write doubted (the compound's coercion can
                // mutate the receiver): write the ALREADY-computed value
                // through the converted key — never re-read/re-apply.
                let key = crate::context::to_property_key(agent, &key)?;
                self.assign_member_discard(agent, object, PropertyKeyName::Key(key), new)?;
                return Ok(());
            }
            // Typed arrays: the element read covers every index (OOB reads
            // undefined, spec 10.4.7.5) and the setter no-ops OOB.
            if let crux::object::ObjectKind::IntegerIndexed(slots) = &object_ref.kind {
                let old = object_ref.typed_array_element_get(slots, index)?;
                let new = crate::expr::apply_compound(agent, op, &old, &value)?;
                if object_ref.typed_array_element_set(slots, index, new)? {
                    return Ok(());
                }
            }
        }
        let key = crate::context::to_property_key(agent, &key)?;
        let old = match &key {
            PropertyKey::String(atom) => match Self::member_cell_get(agent, &object, *atom) {
                Some(old) => old,
                None => {
                    let old = crate::context::get_property_key(agent, &object, &key, object)?;
                    Self::resolve_member_cell(agent, &object, *atom);
                    old
                }
            },
            _ => crate::context::get_property_key(agent, &object, &key, object)?,
        };
        let new = crate::expr::apply_compound(agent, op, &old, &value)?;
        self.assign_member_discard(agent, object, PropertyKeyName::Key(key), new)?;
        Ok(())
    }

    /// The register computed-member update (`o[k]++` / `o[k]--`, the
    /// `UpdateMemberComputedLocal` op): the once-converted-key read then the
    /// ToNumeric update (the number case is the inline f64 ±1, everything
    /// else `update_value`) stored through the same key. The canonical
    /// Number-keyed array/typed-array element paths bypass the conversion
    /// (deterministic, no user code), like `compound_member_computed`.
    pub(crate) fn update_member_computed(
        &mut self,
        agent: &mut Agent,
        object: Value,
        key: Value,
        op: syntax::ast::UpdateOp,
    ) -> Result<(), JsError> {
        if is_nullish(&object) {
            return Err(nullish_error("Cannot read properties of null"));
        }
        let numeric = match key.kind() {
            ValueKind::Number(number)
                if number.fract() == 0.0 && (0.0..4294967295.0).contains(&number) =>
            {
                Some(number as u64)
            }
            _ => None,
        };
        if let Some(index) = numeric
            && let ValueKind::Object(object_ref) = object.kind()
        {
            // The ToNumeric ±1 update (the number case inlines the f64;
            // everything else falls to `update_value`).
            let apply_update = |agent: &mut Agent, old: Value| -> Result<Value, JsError> {
                if let Some(num) = old.as_number() {
                    let delta = if matches!(op, syntax::ast::UpdateOp::Increment) {
                        1.0
                    } else {
                        -1.0
                    };
                    Ok(Value::Number(num + delta))
                } else {
                    let (_, new) = update_value(agent, &op, &old)?;
                    Ok(new)
                }
            };
            if let Some(old) = Self::array_element_get(agent, &object, index) {
                let new = apply_update(agent, old)?;
                if matches!(object_ref.kind, crux::object::ObjectKind::Array(_))
                    && object_ref.array_element_write(index, new)?.is_some()
                {
                    return Ok(());
                }
                let key = crate::context::to_property_key(agent, &key)?;
                self.assign_member_discard(agent, object, PropertyKeyName::Key(key), new)?;
                return Ok(());
            }
            if let crux::object::ObjectKind::IntegerIndexed(slots) = &object_ref.kind {
                let old = object_ref.typed_array_element_get(slots, index)?;
                let new = apply_update(agent, old)?;
                if object_ref.typed_array_element_set(slots, index, new)? {
                    return Ok(());
                }
            }
        }
        let key = crate::context::to_property_key(agent, &key)?;
        let old = match &key {
            PropertyKey::String(atom) => match Self::member_cell_get(agent, &object, *atom) {
                Some(old) => old,
                None => {
                    let old = crate::context::get_property_key(agent, &object, &key, object)?;
                    Self::resolve_member_cell(agent, &object, *atom);
                    old
                }
            },
            _ => crate::context::get_property_key(agent, &object, &key, object)?,
        };
        let new = if let Some(num) = old.as_number() {
            let delta = if matches!(op, syntax::ast::UpdateOp::Increment) {
                1.0
            } else {
                -1.0
            };
            Value::Number(num + delta)
        } else {
            let (_, new) = update_value(agent, &op, &old)?;
            new
        };
        self.assign_member_discard(agent, object, PropertyKeyName::Key(key), new)?;
        Ok(())
    }

    pub(crate) fn assign_member(
        &mut self,
        agent: &mut Agent,
        object: Value,
        key: PropertyKeyName,
        old: Option<Value>,
        value: Value,
        op: AssignOp,
    ) -> Result<(), JsError> {
        match op {
            AssignOp::Assign => {
                // L1a: probe the warm-store cell before the fresh-store and
                // full-[[Set]] paths — a hot write to an existing own
                // writable data property stores directly here, skipping the
                // `fast_fresh_store` existing-check, the `member_reference`
                // build, and the `put_value` layer (which keeps its own probe
                // for its other callers).
                if let Some(atom) = name_atom(&key)
                    && Self::warm_store_put(agent, &object, atom, value)
                {
                    self.stack.push(value);
                    return Ok(());
                }
                // Cut 22: a fresh-property write on a plain object with a
                // cache-verified accessor-free chain defines directly — no
                // [[Set]] chain walk, no descriptor/validate machinery (the
                // per-construct `this.x = x` hot path). Falls back on any
                // doubt (an existing property, an exotic receiver or chain
                // link, an accessor/non-writable in the chain).
                if self.fast_fresh_store(agent, &object, &key, &value)? {
                    self.stack.push(value);
                    return Ok(());
                }
                let reference = member_reference(&object, &key, self.strict);
                crate::context::put_value(agent, &reference, value)?;
                self.stack.push(value);
            }
            AssignOp::AndAssign | AssignOp::OrAssign | AssignOp::NullishAssign => {
                if let Some(atom) = name_atom(&key)
                    && Self::warm_store_put(agent, &object, atom, value)
                {
                    self.stack.push(value);
                    return Ok(());
                }
                let reference = member_reference(&object, &key, self.strict);
                crate::context::put_value(agent, &reference, value)?;
                self.stack.push(value);
            }
            _ => {
                let Some(old) = old else {
                    return Err(JsError::new(
                        ErrorKind::SyntaxError,
                        "compound assignment without a cached old value".into(),
                    ));
                };
                let new = crate::expr::apply_compound(agent, op, &old, &value)?;
                if let Some(atom) = name_atom(&key)
                    && Self::warm_store_put(agent, &object, atom, new)
                {
                    self.stack.push(new);
                    return Ok(());
                }
                let reference = member_reference(&object, &key, self.strict);
                crate::context::put_value(agent, &reference, new)?;
                self.stack.push(new);
            }
        }
        Ok(())
    }

    fn assign_super(
        &mut self,
        agent: &mut Agent,
        base: Value,
        key: PropertyKeyName,
        old: Option<Value>,
        value: Value,
        op: AssignOp,
    ) -> Result<(), JsError> {
        let result = self.assign_super_value(agent, base, key, old, value, op)?;
        self.stack.push(result);
        Ok(())
    }

    /// The shared super-assignment core (Cut 61): `super_reference` put with
    /// the current run's this binding — the certified frame slot for a
    /// certified body, the Function env's binding otherwise. Returns the
    /// assigned value (the interpreter handler pushes it; the JIT helper
    /// returns its bits).
    pub(crate) fn assign_super_value(
        &mut self,
        agent: &mut Agent,
        base: Value,
        key: PropertyKeyName,
        old: Option<Value>,
        value: Value,
        op: AssignOp,
    ) -> Result<Value, JsError> {
        let this = self.vm_this_binding(agent)?;
        match op {
            AssignOp::Assign
            | AssignOp::AndAssign
            | AssignOp::OrAssign
            | AssignOp::NullishAssign => {
                let reference = super_reference(&base, &key, self.strict, &this);
                crate::context::put_value(agent, &reference, value)?;
                Ok(value)
            }
            _ => {
                let Some(old) = old else {
                    return Err(JsError::new(
                        ErrorKind::SyntaxError,
                        "compound assignment without a cached old value".into(),
                    ));
                };
                let new = crate::expr::apply_compound(agent, op, &old, &value)?;
                let reference = super_reference(&base, &key, self.strict, &this);
                crate::context::put_value(agent, &reference, new)?;
                Ok(new)
            }
        }
    }

    fn put_super(
        &mut self,
        agent: &mut Agent,
        base: Value,
        key: PropertyKeyName,
        value: Value,
    ) -> Result<(), JsError> {
        self.put_super_value(agent, base, key, value)
    }

    /// The shared super-put core (Cut 61): like `assign_super_value` for a
    /// plain write (no assigned-value return — the `UpdateSuper*` handlers
    /// push the prefix/postfix result themselves).
    pub(crate) fn put_super_value(
        &mut self,
        agent: &mut Agent,
        base: Value,
        key: PropertyKeyName,
        value: Value,
    ) -> Result<(), JsError> {
        let this = self.vm_this_binding(agent)?;
        let reference = super_reference(&base, &key, self.strict, &this);
        crate::context::put_value(agent, &reference, value)
    }

    /// The this binding for the current run (Cut 61): the certified frame
    /// slot for a certified body (`body_context` set — the certified layout
    /// creates no Function env), the Function env's binding otherwise. The
    /// super steps share it.
    pub(crate) fn vm_this_binding(&self, agent: &Agent) -> Result<Value, JsError> {
        if self.body_context.is_some() {
            self.certified_this(agent)
        } else {
            resolve_this_binding(agent)
        }
    }

    /// The super base for the current run (Cut 61): the home object's
    /// prototype for a certified body, the env walk otherwise.
    pub(crate) fn vm_super_base(&self, agent: &Agent) -> Result<Value, JsError> {
        if self.body_context.is_some() {
            self.certified_super_base(agent)
        } else {
            get_super_base(agent)
        }
    }

    /// The certified run's this value (Cut 61): the running function's scope
    /// this slot — the certified call filled it with the OrdinaryCallBindThis
    /// result. A certified `super` body always has the slot (the scan
    /// allocates it when `super` or `this` is observed); a method body's this
    /// is always initialized (derived constructors never certify).
    pub(crate) fn certified_this(&self, agent: &Agent) -> Result<Value, JsError> {
        let Some(function_id) = self.current_function.map(|value| match value.kind() {
            ValueKind::Function(f) => f.id(),
            _ => 0,
        }) else {
            return Err(JsError::new(
                ErrorKind::ReferenceError,
                "No this binding".into(),
            ));
        };
        let Some(scope) = agent
            .ecma_functions
            .get(&function_id)
            .and_then(|data| data.ir.as_ref())
            .and_then(|ir| ir.scope.as_ref())
        else {
            return Err(JsError::new(
                ErrorKind::ReferenceError,
                "No this binding".into(),
            ));
        };
        let Some(slot) = scope.this_slot else {
            return Err(JsError::new(
                ErrorKind::ReferenceError,
                "No this binding".into(),
            ));
        };
        Ok(*self.frame_get(slot))
    }

    /// The certified super base (Cut 61): the running function's home
    /// object's [[Prototype]] — the frame-slot model's equivalent of
    /// `context::get_super_base` (the certified layout's env chain has no
    /// Function env). The `has_super_binding` check becomes "the function
    /// has a home object".
    pub(crate) fn certified_super_base(&self, agent: &Agent) -> Result<Value, JsError> {
        let Some(function_id) = self.current_function.map(|value| match value.kind() {
            ValueKind::Function(f) => f.id(),
            _ => 0,
        }) else {
            return Err(JsError::new(
                ErrorKind::ReferenceError,
                "super is only valid inside methods".into(),
            ));
        };
        let Some(home) = agent
            .ecma_functions
            .get(&function_id)
            .and_then(|data| data.home_object)
        else {
            return Err(JsError::new(
                ErrorKind::ReferenceError,
                "super is only valid inside methods".into(),
            ));
        };
        let home_object = match home.kind() {
            ValueKind::Object(obj) => obj,
            ValueKind::Function(f) => f.object,
            _ => return Ok(Value::Undefined),
        };
        Ok(home_object
            .get_prototype_of()?
            .map(|proto| proto.function_value().unwrap_or(Value::Object(proto)))
            .unwrap_or(Value::Undefined))
    }

    /// The `Step::Call` (vector-form) handler: the callee and receiver are on
    /// the stack, the arguments in the Vm's vector (`ArgsBase`/`ArgsPush`/
    /// `ArgsSpread` built them).
    fn do_call(&mut self, agent: &mut Agent, direct_eval: bool) -> Result<(), JsError> {
        let callee = self.pop();
        let this = self.pop();
        let base = self.args_base_stack.pop().ok_or_else(|| {
            JsError::new(
                ErrorKind::SyntaxError,
                "Call without an argument boundary".into(),
            )
        })?;
        // GC-2: the argument copy below is a local `Vec<Value>` the stack
        // scan cannot see, and the callee setup that follows (declaration
        // instantiation, a rest binding's `array_from_values`) allocates —
        // suppress `--gc-stress` collections for the window so the copy
        // cannot be swept out from under the callee.
        let _stress = StressSuppress::new();
        let args = self.args.split_off(base);
        let argc = args.len();
        // Rebuild the fast-form layout and route through the shared core
        // (mirroring the JIT's `call_vector` helper): a certified-leaf
        // callee runs inline on this Vm — no execution-context push, no
        // fresh-Vm round trip. `do_call_fast` handles direct eval, the
        // callable check, and the general call, replacing the call site
        // with the result.
        self.stack.push(this);
        self.stack.push(callee);
        self.stack.extend(args);
        self.do_call_fast(agent, argc, direct_eval)?;
        Ok(())
    }

    /// Cut 25: whether the call-site state lets a leaf run in place on this
    /// Vm. The shared stacks the abrupt-completion machinery
    /// (`control_transfer`/`throw_machinery`) walks must be empty, so a
    /// leaf's own `return`/`throw`/`break`/`continue` resolves against
    /// nothing but its own steps — it cannot touch the caller's iterators,
    /// pending finallys, try frames, or env stack. The per-iteration and
    /// destructure flags are false at any call step by construction (they
    /// are only set around the iterator steps that run on nested Vms).
    #[inline]
    pub(crate) fn can_inline_leaf(&self) -> bool {
        self.try_stack.is_empty()
            && self.pending.is_empty()
            && self.for_of_stack.is_empty()
            && self.for_of_boundaries.is_empty()
            && self.for_in_stack.is_empty()
            && self.async_for_of_stack.is_empty()
            && self.destructure_stack.is_empty()
            && self.env_stack.len() == 1
    }

    /// The shared leaf-run core (Cut 25): swap the caller's run state for
    /// the leaf's and dispatch its steps on this Vm — no execution-context
    /// push, no pool round-trip, no frame re-alloc. Every field the leaf can
    /// touch is saved and restored on both the normal and the error path, so
    /// a throwing leaf unwinds exactly like a nested call (the caller's
    /// `run_inner` sees the error with the caller's `ip` restored).
    fn run_leaf_body(
        &mut self,
        agent: &mut Agent,
        ir: &std::rc::Rc<CompiledBody>,
        environment: Option<EnvRef>,
        strict: bool,
        this_value: Value,
        args: &[Value],
    ) -> Result<Completion, JsError> {
        let scope = ir.scope.as_ref().expect("a leaf is certified");
        // Cut 35 slice 1: a body lowered to register ops runs on the
        // dedicated executor, which touches far fewer fields (no `ip`, no
        // completion, no `strict`, no `chain_short`/array-index/arguments
        // state — its ops only address the accumulator, the frame segment,
        // and the env fields).
        if let Some(ops) = ir.leaf_ops.as_deref() {
            return self.run_leaf_regs(
                agent,
                ops,
                ir,
                environment,
                this_value,
                LeafFrame::Pushed(args),
            );
        }
        // Cut 34: the leaf's frame is a flat segment on the value stack, so
        // the caller's `frame` is never swapped — no 256-byte copy per call.
        // Slots `0..frame_size` are pushed in order (this slot, params,
        // `var`s as undefined, `let`/`const` in the TDZ) and addressed via
        // `leaf_frame_base`; the leaf's own stack use grows above them and
        // the post-run truncate unwinds everything.
        let frame_base = self.stack.len();
        let frame_size = scope.frame_size;
        for slot in 0..frame_size {
            let value = if Some(slot) == scope.this_slot {
                this_value
            } else if slot < scope.arity {
                // Missing arguments stay `undefined` (spec 10.2.11).
                args.get(slot).cloned().unwrap_or(Value::Undefined)
            } else if scope.tdz_store.get(slot).copied().unwrap_or(false) {
                Value::uninitialized()
            } else {
                Value::Undefined
            };
            self.stack.push(value);
        }
        let caller_ip = self.ip;
        let caller_leaf_frame_base = self.leaf_frame_base;
        self.leaf_frame_base = Some(frame_base);
        let caller_completion = std::mem::replace(&mut self.completion, Value::Undefined);
        let caller_completion_is_empty = self.completion_is_empty;
        self.completion_is_empty = true;
        // Cut 35 slice 25: no accumulator save/restore — `acc` is read only
        // by the register executor, and every leaf-inline call site sits in
        // a step-path body where the caller's `acc` is dead (the step path
        // never reads it); a step-path leaf's own loops (`RunRegBody`)
        // clobber it freely.
        // Cut 35 slice 21: a leaf's own fast loop uses the shared
        // `loop_counter` field — save the caller's counter across the run
        // (the leaf's `FastLoopBind` overwrites it, `FastLoopStore` writes
        // it back to the leaf's own binding, and the restore below brings
        // the caller's counter back). Since slice 22 the field is a raw
        // f64, so the save/restore is a plain copy.
        let caller_loop_counter = self.loop_counter;
        self.loop_counter = 0.0;
        let caller_strict = self.strict;
        self.strict = strict;
        // Cut 28/30: a leaf that reads captured per-iteration heads
        // (`LoadPerIteration` etc.) resolves them against its own env; a
        // leaf with context-slot steps resolves them against its own
        // `body_context`. A leaf with neither never touches an env, so the
        // body-context creation and both swaps are skipped. Clone the env
        // only when both `body_context` and `lexical_env` need it — the
        // unconditional clone cost every leaf call two `Rc` atomics (Cut 29).
        let (caller_body_context, caller_lexical_env) = if let Some(environment) = environment {
            let body_env = match scope.new_body_context(&environment, args)? {
                Some(context) => context,
                None => environment,
            };
            if ir.leaf_needs_env {
                (
                    self.body_context.replace(body_env),
                    Some(std::mem::replace(&mut self.lexical_env, body_env)),
                )
            } else {
                (self.body_context.replace(body_env), None)
            }
        } else {
            debug_assert!(!ir.leaf_uses_env);
            (None, None)
        };
        let caller_chain_short = self.chain_short;
        self.chain_short = false;
        // The value stack is unwound to `frame_base` after the run. The
        // list/completion/var-ref stacks need no save/restore: a leaf's
        // steps never touch them (the statement-list, finally, and
        // reference machinery is excluded from leaves). The array-index
        // stack CAN grow (`ArrayBegin` is leaf-eligible — a leaf may build
        // an array literal), so its length is preserved.
        let array_index_stack_len = self.array_index_stack.len();
        // The body's `Step::CreateArguments` reads the call's argument slice
        // (strict unmapped only — the sloppy mapped form disqualifies a
        // leaf); a body without an `arguments` slot leaves the caller's
        // slice untouched.
        let caller_call_args = if scope.arguments_slot.is_some() {
            Some(std::mem::replace(&mut self.call_args, args.to_vec()))
        } else {
            None
        };
        self.ip = 0;
        // `run_inner_inner`, not `run_inner`: a leaf error must propagate
        // raw to the caller's `run_inner`, which applies the caller's
        // handler coverage, iterator close, and disposal with the caller's
        // body and the restored `ip`. `run_inner`'s own error machinery
        // would run those against the leaf's empty stacks/tables.
        let outcome = self.run_inner_inner(agent, ir);
        self.ip = caller_ip;
        self.leaf_frame_base = caller_leaf_frame_base;
        self.stack.truncate(frame_base);
        self.completion = caller_completion;
        self.completion_is_empty = caller_completion_is_empty;
        self.loop_counter = caller_loop_counter;
        self.strict = caller_strict;
        if let Some(saved_env) = caller_body_context {
            self.body_context = Some(saved_env);
        }
        if let Some(saved_env) = caller_lexical_env {
            self.lexical_env = saved_env;
        }
        self.chain_short = caller_chain_short;
        self.array_index_stack.truncate(array_index_stack_len);
        if let Some(call_args) = caller_call_args {
            self.call_args = call_args;
        }
        match outcome {
            Ok(VmOutcome::Completed(completion)) => Ok(completion),
            Ok(VmOutcome::Suspended(_)) => Err(JsError::new(
                ErrorKind::TypeError,
                "ordinary function suspended unexpectedly".into(),
            )),
            // A leaf body contains no calls, so a tail call cannot escape it.
            Ok(VmOutcome::TailCall(_)) => Err(JsError::new(
                ErrorKind::TypeError,
                "tail call escaped a leaf body".into(),
            )),
            Err(error) => Err(error),
        }
    }

    /// The register-leaf run core (Cut 35 slice 1): like `run_leaf_body`,
    /// but for a body lowered to [`LeafOp`]s. A register body touches only
    /// the accumulator, its frame segment on the value stack, and (for
    /// captured reads) `body_context`/`lexical_env` — never the `ip`, the
    /// completion, `strict`, `chain_short`, the array-index stack, or the
    /// arguments slice — so the save/restore shrinks to those fields and
    /// the dispatch is the small dedicated `run_leaf_ops` match. The frame
    /// segment layout and the env swap mirror the step path; errors
    /// propagate raw to the caller's `run_inner` exactly like a throwing
    /// step-path leaf.
    #[inline(always)]
    fn run_leaf_regs(
        &mut self,
        agent: &mut Agent,
        ops: &[LeafOp],
        ir: &CompiledBody,
        environment: Option<EnvRef>,
        this_value: Value,
        // The frame source (Cut 35 slice 1): `Alias(base)` overlays the
        // frame on the caller's argument region at `stack[base..]` — every
        // frame slot is a present parameter, so no copy and no push;
        // `Pushed(args)` builds the frame from the copied arguments at the
        // stack top (missing arguments stay `undefined`, spec 10.2.11).
        frame: LeafFrame<'_>,
    ) -> Result<Completion, JsError> {
        let scope = ir.scope.as_ref().expect("a register body is certified");
        // Cut 35 slice 23: capture the caller's offset BEFORE the frame
        // match may set it (`CallerSlots` writes the base into the field).
        let caller_leaf_frame_offset = self.leaf_frame_offset;
        let (frame_base, args, aliased) = match frame {
            LeafFrame::Alias(base) => (base, &[][..], true),
            LeafFrame::CallerSlots { base } => {
                // Cut 35 slice 23: the frame IS the caller's frame at
                // `base..` — keep the caller's `leaf_frame_base` active and
                // offset into it; nothing is pushed, so nothing is unwound
                // on exit.
                self.leaf_frame_offset = base;
                (0, &[][..], true)
            }
            LeafFrame::Pushed(args) => (self.stack.len(), args, false),
        };
        if !aliased {
            for slot in 0..scope.frame_size {
                let value = if Some(slot) == scope.this_slot {
                    this_value
                } else if slot < scope.arity {
                    // Missing arguments stay `undefined` (spec 10.2.11).
                    args.get(slot).cloned().unwrap_or(Value::Undefined)
                } else if scope.tdz_store.get(slot).copied().unwrap_or(false) {
                    Value::uninitialized()
                } else {
                    Value::Undefined
                };
                self.stack.push(value);
            }
        }
        let caller_leaf_frame_base = self.leaf_frame_base;
        // Cut 35 slice 23: `CallerSlots` keeps the caller's base (the
        // offset addresses its slots); the other variants overlay a stack
        // segment of their own.
        if !matches!(frame, LeafFrame::CallerSlots { .. }) {
            self.leaf_frame_base = Some(frame_base);
        }
        // Cut 35 slice 25: no accumulator save/restore — `acc` is read only
        // by the register executor, and every leaf-inline call site sits in
        // a step-path body where the caller's `acc` is dead (the step path
        // never reads it); the leaf's first op loads the accumulator from
        // scratch.
        // Cut 28/30 mirror: a per-iteration-reading leaf resolves its
        // `lexical_env` against its own env; a context-reading leaf resolves
        // `body_context`. A register body with neither never touches either
        // field, so both swaps are skipped. (A leaf's own capture context is
        // always empty — leaves create no closures — so `new_body_context`
        // returns `None` and `args` is unused for the env setup.)
        let (caller_body_context, caller_lexical_env) = if let Some(environment) = environment {
            let body_env = match scope.new_body_context(&environment, args)? {
                Some(context) => context,
                None => environment,
            };
            if ir.leaf_needs_env {
                (
                    self.body_context.replace(body_env),
                    Some(std::mem::replace(&mut self.lexical_env, body_env)),
                )
            } else {
                (self.body_context.replace(body_env), None)
            }
        } else {
            debug_assert!(!ir.leaf_uses_env);
            (None, None)
        };
        let outcome = self.run_leaf_ops(agent, ops);
        self.leaf_frame_base = caller_leaf_frame_base;
        self.leaf_frame_offset = caller_leaf_frame_offset;
        // An aliased frame lives in the caller's argument region, which the
        // caller truncates; only a pushed frame is unwound here.
        if !aliased {
            self.stack.truncate(frame_base);
        }
        if let Some(saved_env) = caller_body_context {
            self.body_context = Some(saved_env);
        }
        if let Some(saved_env) = caller_lexical_env {
            self.lexical_env = saved_env;
        }
        outcome
    }

    /// The register dispatch loop. The frame segment starts at
    /// `stack[frame_base]` (slot `slot` lives at `frame_base + slot`); `acc`
    /// is the implicit result register, read and written by every op. Every
    /// op mirrors the equivalent step's semantics exactly (including the
    /// `Step::BinaryImm` number-number inline). A lowering always ends in
    /// `ReturnAcc`; the fall-off default completes `Empty` like the step
    /// path's end-of-steps completion.
    #[inline(always)]
    fn run_leaf_ops(&mut self, agent: &mut Agent, ops: &[LeafOp]) -> Result<Completion, JsError> {
        for op in ops {
            match op {
                LeafOp::LoadReg { slot, tdz } => {
                    let value = *self.frame_get(*slot);
                    if *tdz && value.is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    self.acc = value;
                }
                LeafOp::LoadContext { index } => {
                    // `context_chain_env(0)` mirror: skip the
                    // context-transparent envs (a named function expression's
                    // self-binding scope, a per-iteration copy) that hold
                    // only scaffolding, so the read lands on the capture
                    // context holding the binding.
                    let mut env = self.body_context_env();
                    while is_context_transparent(&env) {
                        env = env.outer().ok_or_else(|| {
                            JsError::new(
                                ErrorKind::ReferenceError,
                                "No outer environment for a capture-context binding".into(),
                            )
                        })?;
                    }
                    let value = context_env(&env).slot_value(*index).ok_or_else(|| {
                        JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        )
                    })?;
                    self.acc = value;
                }
                LeafOp::LoadPerIter { index } => {
                    // Depth 0: the leaf's own `lexical_env` (the inline run
                    // swapped it to the leaf's per-iteration env).
                    let value = context_env(&self.lexical_env)
                        .slot_value(*index)
                        .ok_or_else(|| {
                            JsError::new(
                                ErrorKind::ReferenceError,
                                "Cannot access a binding before initialization".into(),
                            )
                        })?;
                    self.acc = value;
                }
                LeafOp::LoadCounter => {
                    // Cut 35 slice 16/21: the accumulator-loop counter now
                    // lives in the dedicated `loop_counter` field — read it
                    // directly (no entry push/pop since slice 21); the field
                    // is an f64 since slice 22, so the accumulator takes the
                    // Number wrap.
                    self.acc = Value::Number(self.loop_counter);
                }
                LeafOp::LoadConst(value) => self.acc = *value,
                LeafOp::BinReg { op, slot, tdz } => {
                    if *tdz && self.frame_get(*slot).is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    let right = *self.frame_get(*slot);
                    self.acc = Self::binary_inline(agent, *op, &self.acc, &right)?;
                }
                LeafOp::BinContext { op, index } => {
                    // The `context_chain_env(0)` transparent-env walk (see
                    // `LoadContext`).
                    let mut env = self.body_context_env();
                    while is_context_transparent(&env) {
                        env = env.outer().ok_or_else(|| {
                            JsError::new(
                                ErrorKind::ReferenceError,
                                "No outer environment for a capture-context binding".into(),
                            )
                        })?;
                    }
                    let right = context_env(&env).slot_value(*index).ok_or_else(|| {
                        JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        )
                    })?;
                    self.acc = Self::binary_inline(agent, *op, &self.acc, &right)?;
                }
                LeafOp::BinPerIter { op, index } => {
                    let right = context_env(&self.lexical_env)
                        .slot_value(*index)
                        .ok_or_else(|| {
                            JsError::new(
                                ErrorKind::ReferenceError,
                                "Cannot access a binding before initialization".into(),
                            )
                        })?;
                    self.acc = Self::binary_inline(agent, *op, &self.acc, &right)?;
                }
                LeafOp::BinImm { op, imm } => {
                    // The number-number arithmetic shape inlines
                    // `apply_binary` (two tag checks + a direct op) — the
                    // general evaluator adds a call and the RHS tag check
                    // for no semantic gain (mirrors `Step::BinaryImm`).
                    let value = if let Some(num) = self.acc.as_number() {
                        match op {
                            BinaryOp::Add => Value::Number(num + imm),
                            BinaryOp::Sub => Value::Number(num - imm),
                            BinaryOp::Mul => Value::Number(num * imm),
                            BinaryOp::Div => Value::Number(num / imm),
                            BinaryOp::Rem => Value::Number(num % imm),
                            BinaryOp::Exp => Value::Number(num.powf(*imm)),
                            _ => crate::expr::apply_binary(
                                agent,
                                *op,
                                &self.acc,
                                &Value::Number(*imm),
                            )?,
                        }
                    } else {
                        crate::expr::apply_binary(agent, *op, &self.acc, &Value::Number(*imm))?
                    };
                    self.acc = value;
                }
                LeafOp::BinConst { op, value } => {
                    // `x + (1)` compiles to Push(1)/Binary, not BinaryImm;
                    // a const Number right operand inlines the same shape, and
                    // a const String right operand takes the string-string
                    // concat inline (Cut 35 slice 29).
                    self.acc = Self::binary_inline(agent, *op, &self.acc, value)?;
                }
                LeafOp::BinImmLocal { op, slot, tdz, imm } => {
                    // The fused `LoadReg` + `BinImm` (Cut 35 slice 14): the
                    // frame-slot read (with its `tdz` check) then the
                    // number-number inline.
                    if *tdz && self.frame_get(*slot).is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    let left = *self.frame_get(*slot);
                    self.acc = Self::binary_inline(agent, *op, &left, &Value::Number(*imm))?;
                }
                LeafOp::BinCtxReg {
                    op,
                    index,
                    slot,
                    tdz,
                } => {
                    // The `context_chain_env(0)` transparent-env walk (see
                    // `LoadContext`), then the frame-slot read with its
                    // `tdz` check — the step path's evaluation order
                    // (captured left first, frame right second).
                    let mut env = self.body_context_env();
                    while is_context_transparent(&env) {
                        env = env.outer().ok_or_else(|| {
                            JsError::new(
                                ErrorKind::ReferenceError,
                                "No outer environment for a capture-context binding".into(),
                            )
                        })?;
                    }
                    let left = context_env(&env).slot_value(*index).ok_or_else(|| {
                        JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        )
                    })?;
                    if *tdz && self.frame_get(*slot).is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    let right = *self.frame_get(*slot);
                    self.acc = Self::binary_inline(agent, *op, &left, &right)?;
                }
                LeafOp::StoreReg { slot, tdz } => {
                    if *tdz && self.frame_get(*slot).is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    *self.frame_get_mut(*slot) = self.acc;
                }
                LeafOp::UpdateReg { slot, tdz, op } => {
                    // A statement-position local update (`l++;` as a
                    // statement — the value is discarded): ToNumeric, then
                    // ±1, stored in place (no push). A number in the slot
                    // takes the inline f64 path; anything else (a numeric
                    // string, a BigInt) runs the general updater. The `tdz`
                    // check mirrors `StoreReg`'s.
                    let old = *self.frame_get(*slot);
                    if *tdz && old.is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    let new = if let Some(num) = old.as_number() {
                        let delta = if matches!(op, syntax::ast::UpdateOp::Increment) {
                            1.0
                        } else {
                            -1.0
                        };
                        Value::Number(num + delta)
                    } else {
                        let (_, new) = update_value(agent, op, &old)?;
                        new
                    };
                    *self.frame_get_mut(*slot) = new;
                }
                LeafOp::StoreMemberName { name, value } => {
                    // The object is the accumulator; the value comes from the
                    // operand. Mirrors `Step::AssignMemberName` with a plain
                    // `=`: the nullish check, then the L1a warm-store probe
                    // directly (a warm write skips `assign_member`'s call +
                    // op match), then `assign_member` for the fallbacks
                    // (whose pushed result the frame truncate discards).
                    let object = self.acc;
                    if is_nullish(&object) {
                        return Err(nullish_error("Cannot set properties of null"));
                    }
                    let value = self.leaf_operand_value(agent, value)?;
                    if !Self::warm_store_put(agent, &object, *name, value) {
                        self.assign_member(
                            agent,
                            object,
                            PropertyKeyName::Name(*name),
                            None,
                            value,
                            AssignOp::Assign,
                        )?;
                    }
                }
                LeafOp::StoreMemberNameLocal { object_slot, name } => {
                    // The object is the frame slot (read at store time — the
                    // late-read contract, `tdz=false` only), the value is the
                    // accumulator. Mirrors `Step::AssignMemberName` with a
                    // plain `=`: the nullish check, then the L1a warm-store
                    // probe directly, then `assign_member` for the fallbacks.
                    let object = *self.frame_get(*object_slot);
                    if is_nullish(&object) {
                        return Err(nullish_error("Cannot set properties of null"));
                    }
                    let value = self.acc;
                    if !Self::warm_store_put(agent, &object, *name, value) {
                        self.assign_member(
                            agent,
                            object,
                            PropertyKeyName::Name(*name),
                            None,
                            value,
                            AssignOp::Assign,
                        )?;
                    }
                }
                LeafOp::StoreMemberComputed { key, value } => {
                    // The object is the accumulator; the key and value come
                    // from the operands (neither may be `Acc` — the object
                    // load would have clobbered it). Shares the fast-array
                    // and property-key machinery with the step path.
                    let object = self.acc;
                    let key = self.leaf_operand_value(agent, key)?;
                    let value = self.leaf_operand_value(agent, value)?;
                    self.assign_computed_plain(agent, object, key, value)?;
                }
                LeafOp::StoreMemberComputedLocal { object_slot, key } => {
                    // The object is the frame slot (read at store time — the
                    // late-read contract), the key a `Reg`/`Const` operand,
                    // the value the accumulator. Mirrors `StoreMemberComputed`:
                    // the object load never clobbers the value because it
                    // comes from the slot, so the value can stay in the
                    // accumulator. The pushed result is discarded by the run
                    // truncate.
                    let object = *self.frame_get(*object_slot);
                    let key = self.leaf_operand_value(agent, key)?;
                    self.assign_computed_plain(agent, object, key, self.acc)?;
                }
                LeafOp::CompoundMemberComputedLocal {
                    object_slot,
                    key,
                    op,
                    rhs,
                } => {
                    // The key and the RHS are resolved before the member
                    // read: they are pure operands (a `tdz=false` frame
                    // slot, a constant, or the loop counter for the RHS)
                    // whose loads are stable across the read, so the
                    // engine's evaluation order is preserved.
                    let object = *self.frame_get(*object_slot);
                    let key = self.leaf_operand_value(agent, key)?;
                    let value = self.leaf_operand_value(agent, rhs)?;
                    self.compound_member_computed(agent, object, key, *op, value)?;
                }
                LeafOp::UpdateMemberComputedLocal {
                    object_slot,
                    key,
                    op,
                } => {
                    let object = *self.frame_get(*object_slot);
                    let key = self.leaf_operand_value(agent, key)?;
                    self.update_member_computed(agent, object, key, *op)?;
                }
                LeafOp::GetMemberName { name } => {
                    let object = self.acc;
                    // The same inline warm probe as `GetMemberNameLocal`:
                    // a cell-kind object in the accumulator (a captured or
                    // computed receiver) serves the warm read without the
                    // `get_member_name` out-of-line call; only a miss (or a
                    // non-cell receiver — nullish, a proxy, a typed array)
                    // falls back to it.
                    self.acc = match Self::cell_object(&object) {
                        Some(cell) => match Self::member_cell_warm_probe(agent, &cell, *name) {
                            Some(value) => value,
                            None => self.get_member_name(agent, object, *name)?,
                        },
                        None => self.get_member_name(agent, object, *name)?,
                    };
                }
                LeafOp::GetMemberComputed { key } => {
                    let object = self.acc;
                    let key = self.leaf_operand_value(agent, key)?;
                    self.acc = self.get_member_computed(agent, object, key)?;
                }
                LeafOp::GetMemberNameLocal {
                    object_slot,
                    tdz,
                    name,
                } => {
                    // The hot path reads the frame slot by reference (no
                    // value clone), derives the object part once, and folds
                    // the warm member-cell probe (the value cell, then the
                    // map live-field read) inline — a warm read pays no
                    // out-of-line `member_cell_get` call. Only a miss falls
                    // back to the full `get_member_name`.
                    let object = self.frame_get(*object_slot);
                    if *tdz && object.is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    self.acc = match Self::cell_object(object) {
                        Some(cell) => match Self::member_cell_warm_probe(agent, &cell, *name) {
                            Some(value) => value,
                            None => self.get_member_name(agent, *object, *name)?,
                        },
                        None => self.get_member_name(agent, *object, *name)?,
                    };
                }
                LeafOp::GetMemberComputedLocal {
                    object_slot,
                    tdz,
                    key,
                } => {
                    let object = *self.frame_get(*object_slot);
                    if *tdz && object.is_uninitialized() {
                        return Err(JsError::new(
                            ErrorKind::ReferenceError,
                            "Cannot access a binding before initialization".into(),
                        ));
                    }
                    let key = self.leaf_operand_value(agent, key)?;
                    self.acc = self.get_member_computed(agent, object, key)?;
                }
                LeafOp::PushAcc => self.stack.push(self.acc),
                LeafOp::BinAccPop { op } => {
                    let left = self.pop();
                    self.acc = Self::binary_inline(agent, *op, &left, &self.acc)?;
                }
                LeafOp::UpdateAcc { op } => {
                    // The statement-position member update: ToNumeric, then
                    // ±1 (update_value). A number in the accumulator takes
                    // the inline f64 path; anything else (a numeric string,
                    // a BigInt) runs the general updater.
                    if let Some(num) = self.acc.as_number() {
                        let delta = if matches!(op, syntax::ast::UpdateOp::Increment) {
                            1.0
                        } else {
                            -1.0
                        };
                        self.acc = Value::Number(num + delta);
                    } else {
                        let (_, new) = update_value(agent, op, &self.acc)?;
                        self.acc = new;
                    }
                }
                LeafOp::BinLeftReg { op, slot } => {
                    let left = *self.frame_get(*slot);
                    self.acc = Self::binary_inline(agent, *op, &left, &self.acc)?;
                }
                LeafOp::BinStoreReg { op, slot } => {
                    // The fused tail of a slot-left binary stored back into
                    // the SAME slot (a statement-position `s op= <rhs>`
                    // whose RHS is in the accumulator): copy the slot,
                    // combine with the accumulator, write the result back —
                    // the `[BinLeftReg, StoreReg]` pair in one dispatch.
                    let left = *self.frame_get(*slot);
                    let result = Self::binary_inline(agent, *op, &left, &self.acc)?;
                    self.acc = result;
                    *self.frame_get_mut(*slot) = result;
                }
                LeafOp::ReturnAcc => {
                    return Ok(Completion::Return(self.acc));
                }
            }
        }
        Ok(Completion::Empty)
    }

    /// The number-number arithmetic inline shared by the register binary ops
    /// (Cut 35 slice 10): two tag checks + a direct op for the arithmetic
    /// shapes, falling back to the general `apply_binary` for anything else
    /// (mirrors `Step::BinaryImm`'s inline). The Add case is `apply_binary`'s
    /// own number-number fast path, inlined to skip the call; the
    /// string-string Add case (Cut 35 slice 29) routes the rope concat through
    /// a cold helper — inlining the concat body at every register-op call
    /// site bloats the number loops' icache (measured ~3-6ns/call on the
    /// closure and call rows, Cut 35 slice 30).
    #[inline]
    fn binary_inline(
        agent: &mut Agent,
        op: BinaryOp,
        left: &Value,
        right: &Value,
    ) -> Result<Value, JsError> {
        if let (Some(left), Some(right)) = (left.as_number(), right.as_number()) {
            match op {
                BinaryOp::Add => return Ok(Value::Number(left + right)),
                BinaryOp::Sub => return Ok(Value::Number(left - right)),
                BinaryOp::Mul => return Ok(Value::Number(left * right)),
                BinaryOp::Div => return Ok(Value::Number(left / right)),
                BinaryOp::Rem => return Ok(Value::Number(left % right)),
                BinaryOp::Exp => return Ok(Value::Number(left.powf(right))),
                _ => {}
            }
        }
        if op == BinaryOp::Add
            && let Some(value) = Self::concat_strings(left, right)
        {
            return Ok(value);
        }
        crate::expr::apply_binary(agent, op, left, right)
    }

    /// The string-string `Add` fast path: the rope concat, kept out of the
    /// inline (a cold call — strings are not the register ops' hot shape).
    #[inline(never)]
    fn concat_strings(left: &Value, right: &Value) -> Option<Value> {
        if let (Some(left), Some(right)) = (left.as_string(), right.as_string()) {
            Some(Value::String(JsString::concat(&left, &right)))
        } else {
            None
        }
    }

    /// Load a register operand to a value for a store op, mirroring the
    /// `LoadReg`/`LoadContext`/`LoadPerIter`/`LoadConst` ops' semantics
    /// (including the TDZ and context-transparent-env walks).
    fn leaf_operand_value(
        &mut self,
        agent: &mut Agent,
        operand: &RegOperand,
    ) -> Result<Value, JsError> {
        match operand {
            RegOperand::Acc => Ok(self.acc),
            RegOperand::Reg { slot, tdz } => {
                let value = *self.frame_get(*slot);
                if *tdz && value.is_uninitialized() {
                    return Err(JsError::new(
                        ErrorKind::ReferenceError,
                        "Cannot access a binding before initialization".into(),
                    ));
                }
                Ok(value)
            }
            RegOperand::PostInc { slot, tdz, op } => {
                // A post-increment key: read the slot, write the update back,
                // yield the OLD value — exactly what the `UpdateLocal` step
                // (postfix) computes, with the same TDZ check. The write-back
                // runs before the store machinery's nullish check, matching
                // JS evaluation order (`l++` fully evaluates before the
                // [[Set]] throws on a nullish receiver).
                let old = *self.frame_get(*slot);
                if *tdz && old.is_uninitialized() {
                    return Err(JsError::new(
                        ErrorKind::ReferenceError,
                        "Cannot access a binding before initialization".into(),
                    ));
                }
                // A slot that already holds a Number updates on the raw f64:
                // the postfix key (`a[l++] = v` on the buildString rows) skips
                // the ToNumeric/ToPrimitive dispatch in `update_value`, which
                // re-boxes and re-coerces a value that is provably a Number.
                // Number is closed under `++`/`--` (NaN and the infinities
                // included), and the old value is the yielded key unchanged, so
                // the fast path is exactly `update_value`'s Number branch.
                if let ValueKind::Number(number) = old.kind() {
                    let delta = if matches!(op, UpdateOp::Increment) {
                        1.0
                    } else {
                        -1.0
                    };
                    *self.frame_get_mut(*slot) = Value::Number(number + delta);
                    return Ok(old);
                }
                let (old_numeric, new) = update_value(agent, op, &old)?;
                *self.frame_get_mut(*slot) = new;
                Ok(old_numeric)
            }
            RegOperand::Ctx { index } => {
                let mut env = self.body_context_env();
                while is_context_transparent(&env) {
                    env = env.outer().ok_or_else(|| {
                        JsError::new(
                            ErrorKind::ReferenceError,
                            "No outer environment for a capture-context binding".into(),
                        )
                    })?;
                }
                context_env(&env).slot_value(*index).ok_or_else(|| {
                    JsError::new(
                        ErrorKind::ReferenceError,
                        "Cannot access a binding before initialization".into(),
                    )
                })
            }
            RegOperand::PerIter { index } => context_env(&self.lexical_env)
                .slot_value(*index)
                .ok_or_else(|| {
                    JsError::new(
                        ErrorKind::ReferenceError,
                        "Cannot access a binding before initialization".into(),
                    )
                }),
            RegOperand::Const(value) => Ok(*value),
            // The lowering rejects spilled keys/values; a reaching spill
            // would be a compiler bug.
            RegOperand::Spilled => Err(JsError::new(
                ErrorKind::SyntaxError,
                "spilled register operand cannot be re-loaded".into(),
            )),
            // The loop counter lives in the dedicated `loop_counter` field
            // (Cut 35 slice 21: no entry push — the field IS the storage, so
            // the operand reads it directly, mirroring `LeafOp::LoadCounter`
            // and the JIT's `counter_bits`). The read-count guard keeps the
            // shadow stack at most two `Counter` entries.
            RegOperand::Counter => Ok(Value::Number(self.loop_counter)),
        }
    }

    /// OrdinaryCallBindThis for a certified body (Cut 3 continuation): a
    /// non-arrow body's `this` slot gets the call's `this` — strict keeps it
    /// as-is; sloppy coerces undefined/null to the global object and boxes
    /// primitives. An arrow (lexical `this`) has no slot; the value is
    /// unused.
    fn bind_this_value(
        &mut self,
        agent: &mut Agent,
        scope: &ScopeInfo,
        strict: bool,
        this: Value,
    ) -> Result<Value, JsError> {
        if scope.this_slot.is_none() {
            return Ok(Value::Undefined);
        }
        if strict {
            return Ok(this);
        }
        match this.kind() {
            ValueKind::Undefined | ValueKind::Null => {
                // Same-realm guard: the caller's global is the leaf's.
                let global = self.global_object(agent)?;
                Ok(Value::Object(global))
            }
            ValueKind::Object(_) | ValueKind::Function(_) => Ok(this),
            _ => crate::context::to_object(agent, &this),
        }
    }

    /// The leaf-call completion to a value (the `do_call_fast` inline path):
    /// a `return` wins, a fall-off yields `undefined`, a thrown value
    /// surfaces as the engine error the outer `run_inner` would have
    /// produced, and an escaped break/continue is illegal.
    fn leaf_completion_result(completion: Completion) -> Result<Value, JsError> {
        match completion {
            Completion::Return(value) => Ok(value),
            Completion::Normal(_) | Completion::Empty => Ok(Value::Undefined),
            Completion::Throw(value) => Err(JsError::new(
                ErrorKind::TypeError,
                format!("Uncaught {value:?}"),
            )
            .with_value(value)),
            Completion::Break { .. } | Completion::Continue { .. } => Err(JsError::new(
                ErrorKind::SyntaxError,
                "Illegal break/continue statement".into(),
            )),
        }
    }

    /// The leaf-inline construct path (Cut 25): OrdinaryCreateFromConstructor
    /// plus the base-constructor return rule — an object `return` wins,
    /// anything else yields `this` — mirroring `ordinary_construct`'s
    /// certified fast path without the context push.
    fn run_leaf_construct(
        &mut self,
        agent: &mut Agent,
        ir: &std::rc::Rc<CompiledBody>,
        environment: Option<EnvRef>,
        strict: bool,
        new_target: &Value,
        args: &[Value],
    ) -> Result<Value, JsError> {
        let this = crate::function::construct_this_object(agent, new_target)?;
        // The JIT path: the machine code reads its arguments off the value
        // stack (its frame is a private buffer), so the construct args are
        // materialized first — the same layout the leaf-inline run uses —
        // and the base-constructor result rule applies to the returned
        // value (an object/function return wins, else `this`).
        if agent.jit_hook.is_some() {
            let pre_call = self.stack.len();
            self.stack.extend_from_slice(args);
            if self.run_jit_leaf(agent, args.len(), this, ir, strict, 0, environment)? {
                let value = self.pop();
                return match value.kind() {
                    ValueKind::Object(_) | ValueKind::Function(_) => Ok(value),
                    _ => Ok(this),
                };
            }
            self.stack.truncate(pre_call);
        }
        let completion = self.run_leaf_body(agent, ir, environment, strict, this, args)?;
        // spec 10.2.1 [[Construct]] steps 15-21 (base): an object return
        // wins; anything else falls back to `this`.
        match completion {
            Completion::Return(value) => match value.kind() {
                ValueKind::Object(_) | ValueKind::Function(_) => Ok(value),
                _ => Ok(this),
            },
            Completion::Normal(_) | Completion::Empty => Ok(this),
            Completion::Throw(value) => Err(JsError::new(
                ErrorKind::TypeError,
                format!("Uncaught {value:?}"),
            )
            .with_value(value)),
            Completion::Break { .. } | Completion::Continue { .. } => Err(JsError::new(
                ErrorKind::SyntaxError,
                "Illegal break/continue statement".into(),
            )),
        }
    }

    /// The fast-call path (`CallFast`): the 0-2 arguments are already on the
    /// value stack above `[this, callee]`. The arguments slice is read in
    /// place — no argument-vector build, no per-call `Vec` allocation — and
    /// the result replaces the call site — the frame is popped after the
    /// call. Stack: `[..., this, callee, arg1..argN]`.
    pub(crate) fn do_call_fast(
        &mut self,
        agent: &mut Agent,
        argc: usize,
        direct_eval: bool,
    ) -> Result<(), JsError> {
        let n = self.stack.len();
        let arg_start = n - argc;
        let callee = self.stack[arg_start - 1];
        let this = self.stack[arg_start - 2];
        // The shared core: `below` values under the argument region (2 for
        // `CallFast`'s `[this, callee]`) are removed with the arguments when
        // the result replaces the call site.
        self.fast_call_core(
            agent,
            argc,
            direct_eval,
            callee,
            this,
            2,
            LeafCacheSite::None,
        )
    }

    /// The `Step::CallApply` handler: the member read already resolved the
    /// `apply`/`call` function (a shadowed one is called with the original
    /// argument list — the fallback is exactly `CallFast`); when it IS the
    /// realm's intrinsic, the call runs on this Vm: the `this` argument and
    /// the `CreateListFromArrayLike` element reads replace the argument
    /// region, and `do_call_fast` leaf-inlines a certified callee with no
    /// builtin dispatch and no pooled-Vm round trip. Stack:
    /// `[..., f, apply/call, thisArg, arg1..argN]` (the `CallFast` layout,
    /// `argc` = N+1).
    pub(crate) fn do_call_apply(
        &mut self,
        agent: &mut Agent,
        argc: usize,
        kind: ApplyKind,
    ) -> Result<(), JsError> {
        let n = self.stack.len();
        let arg_start = n - argc;
        let resolved = self.stack[arg_start - 1];
        let callee = self.stack[arg_start - 2];
        let realm = agent.current_realm()?;
        let intrinsic = match kind {
            ApplyKind::Apply => realm.intrinsics.apply_builtin(),
            ApplyKind::Call => realm.intrinsics.call_builtin(),
        };
        if Some(resolved) != intrinsic {
            // A shadowed apply/call: run the resolved function with the
            // original argument list, exactly as `CallFast` would.
            return self.do_call_fast(agent, argc, false);
        }
        // The intrinsic's own step-1 IsCallable check runs before any
        // argument-list user code (spec 20.2.3.2 / 20.2.3.4 step 1).
        if !is_callable(&callee) {
            let what = match kind {
                ApplyKind::Apply => "Apply",
                ApplyKind::Call => "Call",
            };
            return Err(JsError::new(
                ErrorKind::TypeError,
                format!("{what} must be called on a function"),
            ));
        }
        // The argument region is copied out before the region is rebuilt (a
        // truncate would otherwise alias the borrow); `FAST_CALL_MAX_ARGS`
        // caps the fast form, so the small buffer always fits.
        let mut args = [Value::Undefined; FAST_CALL_MAX_ARGS];
        args[..argc].copy_from_slice(&self.stack[arg_start..n]);
        match kind {
            ApplyKind::Call => {
                // `f.call(thisArg, a, b, ...)`: `this` is args[0], the
                // direct call's arguments are the rest (spec 20.2.3.4
                // steps 5-6).
                let rest = if argc > 1 { &args[1..argc] } else { &args[..0] };
                self.stack.truncate(arg_start - 2);
                self.stack.push(args[0]);
                self.stack.push(callee);
                self.stack.extend_from_slice(rest);
                self.do_call_fast(agent, argc.saturating_sub(1), false)
            }
            ApplyKind::Apply => {
                let arg_array = if argc >= 2 { args[1] } else { Value::Undefined };
                if matches!(arg_array.kind(), ValueKind::Undefined | ValueKind::Null) {
                    // spec 20.2.3.2 step 2: a nullish argArray calls with
                    // no arguments.
                    self.stack.truncate(arg_start - 2);
                    self.stack.push(args[0]);
                    self.stack.push(callee);
                    return self.do_call_fast(agent, 0, false);
                }
                // The dense-array fast path: a dense Array's elements are
                // own data properties at the buffer positions, so the
                // argument list pushes straight onto the stack — no per-call
                // Vec, no `length`/`[[Get]]` round trip. A hole, a length
                // past the buffer end, or a non-uint32 length falls back to
                // `create_list_from_array_like` (whose own fast paths and
                // the spec [[Get]] loop keep those shapes exact). The borrow
                // never spans the call: the truncate/push/extend run no user
                // code, and the elements are copied out before
                // `do_call_fast` (a re-entrant callee may mutate the array).
                if let ValueKind::Object(obj) = arg_array.kind()
                    && let crux::object::ObjectKind::Array(slots) = &obj.kind
                    && slots.dense.get()
                {
                    let length = slots.length.get() as usize;
                    let fit = {
                        let elements = slots.elements.borrow();
                        elements.len() >= length && elements[..length].iter().all(Option::is_some)
                    };
                    if fit {
                        self.stack.truncate(arg_start - 2);
                        self.stack.push(args[0]);
                        self.stack.push(callee);
                        {
                            let elements = slots.elements.borrow();
                            for element in elements[..length].iter() {
                                self.stack.push(element.unwrap());
                            }
                        }
                        return self.do_call_fast(agent, length, false);
                    }
                }
                // The list lives in a local the stack scan cannot see only
                // until the extend below roots the values on the scanned
                // stack; `create_list_from_array_like` suppresses stress for
                // the build itself (mirroring the apply builtin).
                let arg_list =
                    crate::builtins::function::create_list_from_array_like(agent, &arg_array)?;
                self.stack.truncate(arg_start - 2);
                self.stack.push(args[0]);
                self.stack.push(callee);
                self.stack.extend_from_slice(&arg_list);
                self.do_call_fast(agent, arg_list.len(), false)
            }
        }
    }

    /// The `TailCallFast` handler (proper tail calls): the callee/args are on
    /// the stack as for a normal call, but the current body's return cleanup
    /// runs and the frame is replaced instead of recursing.
    fn tail_call_fast(
        &mut self,
        agent: &mut Agent,
        argc: usize,
        direct_eval: bool,
        body: &CompiledBody,
    ) -> Result<VmOutcome, JsError> {
        let n = self.stack.len();
        let arg_start = n - argc;
        let callee = self.stack[arg_start - 1];
        let this = self.stack[arg_start - 2];
        match self.tail_call_shared(
            agent,
            this,
            callee,
            argc,
            arg_start,
            arg_start - 2,
            direct_eval,
            body,
        )? {
            TailOutcome::Returned(outcome) => Ok(outcome),
            TailOutcome::Replaced(ir) => Ok(VmOutcome::TailCall(ir)),
        }
    }

    /// The `TailCall` (vector-form) handler: the arguments came through the
    /// `ArgsBase`/`ArgsPush` machinery; rebuild the fast-form layout so the
    /// shared dispatcher reads them in place (the vector form is rare — ≥3
    /// args or a spread).
    fn tail_call_vector(
        &mut self,
        agent: &mut Agent,
        direct_eval: bool,
        body: &CompiledBody,
    ) -> Result<VmOutcome, JsError> {
        let callee = self.pop();
        let this = self.pop();
        let base = self.args_base_stack.pop().ok_or_else(|| {
            JsError::new(
                ErrorKind::SyntaxError,
                "TailCall without an argument boundary".into(),
            )
        })?;
        let args = self.args.split_off(base);
        let argc = args.len();
        let keep = self.stack.len();
        self.stack.push(this);
        self.stack.push(callee);
        self.stack.extend(args);
        let n = self.stack.len();
        match self.tail_call_shared(agent, this, callee, argc, n - argc, keep, direct_eval, body)? {
            TailOutcome::Returned(outcome) => Ok(outcome),
            TailOutcome::Replaced(ir) => Ok(VmOutcome::TailCall(ir)),
        }
    }

    /// The `TailCallFastGlobal` handler: the callee comes from the global
    /// cell with an `undefined` receiver (the compiler emitted no receiver
    /// push or callee load).
    fn do_tail_call_global(
        &mut self,
        agent: &mut Agent,
        name: crux::AtomId,
        argc: usize,
        body: &CompiledBody,
    ) -> Result<VmOutcome, JsError> {
        let n = self.stack.len();
        let callee = self.load_global_value(agent, name)?;
        let keep = n - argc;
        match self.tail_call_shared(
            agent,
            Value::Undefined,
            callee,
            argc,
            n - argc,
            keep,
            false,
            body,
        )? {
            TailOutcome::Returned(outcome) => Ok(outcome),
            TailOutcome::Replaced(ir) => Ok(VmOutcome::TailCall(ir)),
        }
    }

    /// The `TailCallFastSlot` handler: the callee comes from a frame slot
    /// with an `undefined` receiver.
    fn do_tail_call_slot(
        &mut self,
        agent: &mut Agent,
        slot: usize,
        argc: usize,
        body: &CompiledBody,
    ) -> Result<VmOutcome, JsError> {
        let n = self.stack.len();
        let callee = *self.frame_get(slot);
        let keep = n - argc;
        match self.tail_call_shared(
            agent,
            Value::Undefined,
            callee,
            argc,
            n - argc,
            keep,
            false,
            body,
        )? {
            TailOutcome::Returned(outcome) => Ok(outcome),
            TailOutcome::Replaced(ir) => Ok(VmOutcome::TailCall(ir)),
        }
    }

    /// The shared tail-call dispatch: `args_base` is the stack index where
    /// the arguments start, `keep` the stack length to restore on the normal
    /// path. The callee/args are on the stack as for a normal call.
    #[allow(clippy::too_many_arguments)]
    fn tail_call_shared(
        &mut self,
        agent: &mut Agent,
        this: Value,
        callee: Value,
        argc: usize,
        args_base: usize,
        keep: usize,
        direct_eval: bool,
        body: &CompiledBody,
    ) -> Result<TailOutcome, JsError> {
        // A direct eval in tail position (`return eval(x)`) is a host
        // operation that must run with the caller's environment intact: the
        // eval'd script inherits the caller's lexical/private environment and
        // function position, so the frame replacement never applies. The
        // `direct_eval` flag is name-based (`eval` as the callee identifier —
        // a shadowed `eval` function is still tail-called), so the resolved
        // callee is checked here before routing.
        if direct_eval && is_eval_function(agent, &callee)? {
            let source = self
                .stack
                .get(args_base)
                .cloned()
                .unwrap_or(Value::Undefined);
            // spec 19.2.1.1 step 2: a non-string argument is returned as-is.
            if !matches!(source.kind(), ValueKind::String(_)) {
                self.stack.truncate(keep);
                return Ok(TailOutcome::Returned(
                    self.return_completion(agent, body, source)?,
                ));
            }
            let source = crux::convert::to_string(&source)?;
            let result = crate::script::perform_eval(agent, &source, self.strict, true)?;
            self.stack.truncate(keep);
            return Ok(TailOutcome::Returned(
                self.return_completion(agent, body, result)?,
            ));
        }
        // A tail call's value is this body's return: close the iterators and
        // unwind the environment exactly as the return completion would (the
        // frame is gone once the callee runs).
        if !self.for_of_stack.is_empty() {
            self.close_for_of_return(agent)?;
        }
        self.env_stack.truncate(1);
        if let Some(base) = self.env_stack.get(0) {
            self.lexical_env = *base
        }
        // A certified leaf runs in place on this Vm (it never grew the
        // stack); its result completes this body's return.
        if self.can_inline_leaf()
            && let ValueKind::Function(function) = callee.kind()
            && matches!(function.kind, crux::function::FunctionKind::EcmaScript)
            && agent.realm_count.get() == 1
            && let Some(entry) = agent.leaf_lookup(function.id())
        {
            let entry = LeafEntry {
                ir: entry.ir.clone(),
                strict: entry.strict,
                environment: entry.environment,
                construct_inline: entry.construct_inline,
            };
            let below = self.stack.len() - argc - keep;
            // The JIT path first: `run_jit_leaf` pushes the result exactly
            // like the interpreter's leaf-inline run (the truncate + push
            // tail), so the same pop-and-complete-return follows.
            if agent.jit_hook.is_some()
                && self.run_jit_leaf(
                    agent,
                    argc,
                    this,
                    &entry.ir,
                    entry.strict,
                    below,
                    entry.environment,
                )?
            {
                let value = self.pop();
                return Ok(TailOutcome::Returned(
                    self.return_completion(agent, body, value)?,
                ));
            }
            self.run_inline_leaf(agent, argc, this, entry, below, None)?;
            let value = self.pop();
            return Ok(TailOutcome::Returned(
                self.return_completion(agent, body, value)?,
            ));
        }
        // Frame replacement applies only to an ordinary-callable ECMAScript
        // function in a single realm; everything else (builtin, bound,
        // async, generator, class constructor, proxy, cross-realm) takes the
        // normal call path — which does not recurse into `run_inner` for the
        // tail call itself — and completes the return.
        // GC-2: the argument copy below is a local `Vec<Value>` the stack
        // scan cannot see, and the callee setup that follows (declaration
        // instantiation, the rest binding's `array_from_values`) allocates —
        // suppress `--gc-stress` collections for the window so the copy
        // cannot be swept out from under the callee.
        let _stress = StressSuppress::new();
        let args: Vec<Value> = self.stack[args_base..self.stack.len()].to_vec();
        if let ValueKind::Function(function) = callee.kind()
            && matches!(function.kind, crux::function::FunctionKind::EcmaScript)
            && agent.realm_count.get() == 1
            && let Some(ir) = self.tail_prepare_ordinary(agent, &function, this, &args)?
        {
            return Ok(TailOutcome::Replaced(ir));
        }
        let result = crate::function::call_inner(agent, &callee, this, &args)?;
        self.stack.truncate(keep);
        Ok(TailOutcome::Returned(
            self.return_completion(agent, body, result)?,
        ))
    }

    /// Complete the current body with a return of `value` — the `Step::Return`
    /// behavior, factored for the tail-call paths (the compiler skipped the
    /// `Return` step).
    fn return_completion(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        value: Value,
    ) -> Result<VmOutcome, JsError> {
        match self.control_transfer(agent, body, Ctl::Return { value })? {
            // A finally can never defer a compiled tail call (the compiler
            // gates on try_depth == 0), so Continue is unreachable; complete
            // the return anyway.
            CtlResult::Continue => Ok(VmOutcome::Completed(Completion::Return(value))),
            CtlResult::Done(outcome) => Ok(outcome),
        }
    }

    /// Set up an ordinary-callable ECMAScript callee's context and frame on
    /// THIS Vm (PrepareForTailCall + PrepareForOrdinaryCall): the current
    /// context is popped, the callee's is pushed, the Vm is reset to the
    /// fresh-call state, and the frame/args/this are bound. `None` when the
    /// callee needs a path the tail dispatch does not handle (class
    /// constructor, async, generator, an AST-only body) — the caller falls
    /// back to the normal call.
    pub(crate) fn tail_prepare_ordinary(
        &mut self,
        agent: &mut Agent,
        function: &Handle<crux::function::Function>,
        this: Value,
        args: &[Value],
    ) -> Result<Option<std::rc::Rc<CompiledBody>>, JsError> {
        let (ir, old_env, realm, strict, is_marked) = {
            let record = agent.ecma_functions.get(&function.id()).ok_or_else(|| {
                JsError::new(
                    ErrorKind::TypeError,
                    "Function body is not registered".into(),
                )
            })?;
            if record.is_class_constructor || record.is_async || record.is_generator {
                return Ok(None);
            }
            (
                record.ir.clone(),
                record.environment,
                record.realm,
                record.strict,
                record.class_field_initializer,
            )
        };
        let Some(ir) = ir else {
            return Ok(None); // an AST-only body keeps the normal path
        };
        let saved_depth = agent.field_initializer_depth;
        agent.field_initializer_depth = if is_marked { saved_depth + 1 } else { 0 };
        if let Some(scope) = &ir.scope {
            // Certified: the frame-slot path — no function environment, no
            // declaration instantiation (the scope analysis certified the
            // body references none of it). Mirrors `ordinary_call`'s fast
            // branch + `run_compiled_body`'s setup.
            let body_env = match scope.new_body_context(&old_env, args)? {
                Some(context) => context,
                None => old_env,
            };
            let context_function =
                (scope.arguments_slot.is_some() && !strict).then(|| Value::Function(*function));
            agent.execution_context_stack.pop();
            agent
                .execution_context_stack
                .push(crate::context::ExecutionContext {
                    function: context_function,
                    realm,
                    script_or_module: None,
                    lexical_environment: body_env,
                    variable_environment: body_env,
                    private_environment: None,
                    source: None,
                    annex_b_hoistable: Default::default(),
                });
            let this_value = if scope.this_slot.is_some() {
                Some(if strict {
                    this
                } else {
                    match this.kind() {
                        ValueKind::Undefined | ValueKind::Null => {
                            let global = agent.running_context()?.realm.global_object;
                            Value::Object(global)
                        }
                        ValueKind::Object(_) | ValueKind::Function(_) => this,
                        _ => crate::context::to_object(agent, &this)?,
                    }
                })
            } else {
                None
            };
            // Reuse this Vm as the callee's fresh Vm (a normal call would
            // grab a pooled Vm), then bind the frame/args/this exactly like
            // `run_compiled_body`.
            self.reset(body_env, strict);
            self.body_context = Some(body_env);
            self.current_function = Some(Value::Function(*function));
            if scope.frame_size > 0 {
                self.setup_frame(scope, args);
            }
            if scope.arguments_slot.is_some() {
                self.call_args = args.to_vec();
            }
            if let (Some(slot), Some(tv)) = (scope.this_slot, this_value) {
                *self.frame.get_mut(slot) = tv;
            }
            self.ip = 0;
            return Ok(Some(ir));
        }
        // Slow path (uncertified): a function environment + declaration
        // instantiation, mirroring `ordinary_call`'s slow branch.
        let (this_mode, params, body, declaring_module, private_environment) = {
            let record = agent.ecma_functions.get(&function.id()).ok_or_else(|| {
                JsError::new(
                    ErrorKind::TypeError,
                    "Function body is not registered".into(),
                )
            })?;
            (
                record.this_mode,
                record.params.clone(),
                record.body.clone(),
                record.declaring_module,
                record.private_environment,
            )
        };
        let function_value = function.self_value();
        let function_env = crate::env::new_function_environment(
            Some(old_env),
            function_value,
            Value::Undefined,
            this_mode == crate::function::ThisMode::Lexical,
        );
        let caller_script_or_module = agent
            .running_context()
            .ok()
            .and_then(|context| context.script_or_module.clone());
        let script_or_module = declaring_module
            .map(crate::context::ScriptOrModule::Module)
            .or(caller_script_or_module);
        agent.execution_context_stack.pop();
        agent
            .execution_context_stack
            .push(crate::context::ExecutionContext {
                function: Some(function_value),
                realm,
                script_or_module,
                lexical_environment: function_env,
                variable_environment: function_env,
                private_environment,
                source: agent
                    .running_context()
                    .ok()
                    .and_then(|context| context.source.clone()),
                annex_b_hoistable: Default::default(),
            });
        if this_mode != crate::function::ThisMode::Lexical {
            let this = if this_mode == crate::function::ThisMode::Sloppy {
                match this.kind() {
                    ValueKind::Undefined | ValueKind::Null => {
                        let global = agent.running_context()?.realm.global_object;
                        Value::Object(global)
                    }
                    ValueKind::Object(_) | ValueKind::Function(_) => this,
                    _ => crate::context::to_object(agent, &this)?,
                }
            } else {
                this
            };
            function_env.bind_this_value(this)?;
        }
        crate::function::function_declaration_instantiation(
            agent,
            &function_value,
            &params,
            &body,
            this_mode,
            strict,
            args,
            &function_env,
        )?;
        // The body runs against the lexical env declaration instantiation
        // installed on the running context (a sloppy body's `let` bindings
        // live in a fresh wrapper over the function env), not the function
        // env itself — mirror `run_compiled_body`, which resets the pooled
        // Vm with the context's lexical env after instantiation.
        let body_env = agent.running_context()?.lexical_environment;
        self.reset(body_env, strict);
        self.current_function = Some(Value::Function(*function));
        self.ip = 0;
        Ok(Some(ir))
    }

    /// Cut 46: the `TailCallSelf` handler — a tail call whose callee is the
    /// named-function-expression self-binding, statically the running body
    /// itself. The new arguments sit on the stack (`[a1..aN]` — the compiler
    /// emitted no receiver/callee pushes); rebind the frame in place and
    /// reset the per-run state exactly like `tail_prepare_ordinary`'s
    /// certified branch, minus the callee lookup and the execution-context
    /// swap (a capture-free self-call's context is identical to the running
    /// one). The caller's dispatch loop re-enters the body's entry with
    /// `ip == 0` — the whole self-recursive chain runs on this Vm with no
    /// runtime round-trip.
    fn tail_call_self(
        &mut self,
        agent: &mut Agent,
        argc: usize,
        body: &CompiledBody,
    ) -> Result<(), JsError> {
        let n = self.stack.len();
        let args: Vec<Value> = self.stack[n - argc..].to_vec();
        self.tail_call_self_rebind(agent, body, &args)
    }

    /// Cut 51: the `TailCallSelfVector` handler — the same in-place rebind,
    /// with the arguments read from the Vm's argument vector (the
    /// `ArgsBase`/`ArgsPush`/`ArgsSpread` build) instead of the stack.
    fn tail_call_self_vector(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
    ) -> Result<(), JsError> {
        let base = self.args_base_stack.pop().ok_or_else(|| {
            JsError::new(
                ErrorKind::SyntaxError,
                "TailCallSelfVector without an argument boundary".into(),
            )
        })?;
        let args = self.args.split_off(base);
        self.tail_call_self_rebind(agent, body, &args)
    }

    /// The shared self-tail-call rebind: reset the per-run state and set up
    /// the body's frame from the new arguments, then re-enter the body's
    /// entry (`ip == 0`) — exactly `tail_prepare_ordinary`'s certified
    /// branch minus the callee lookup and the execution-context swap (a
    /// capture-free self-call's context is identical to the running one).
    fn tail_call_self_rebind(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        args: &[Value],
    ) -> Result<(), JsError> {
        let scope = body
            .scope
            .as_ref()
            .expect("the compiler emits the self-tail-call steps only for certified bodies");
        let env = agent.running_context()?.lexical_environment;
        // GC-2: the argument copy is a local the stack scan cannot see, and
        // `setup_frame` may allocate the heap frame — mirror
        // `tail_call_shared`'s suppression window.
        let _stress = StressSuppress::new();
        self.reset(env, body.strict);
        self.body_context = Some(env);
        if scope.frame_size > 0 {
            self.setup_frame(scope, args);
        }
        self.ip = 0;
        Ok(())
    }

    /// The `CallFastGlobal` handler (Cut 35 slice 2): the callee comes from
    /// the global cell and `this` is `undefined` — the compiler emitted no
    /// receiver push or callee load, so the argument region is the top
    /// `argc` values with nothing below it. `caller_arg_base` (Cut 35
    /// slice 23): a fused call-store site passes the arguments' base in the
    /// caller's frame instead of on the stack — the callee may read them
    /// straight from the caller's slots; `None` for the stack-argument
    /// steps.
    fn do_call_fast_global(
        &mut self,
        agent: &mut Agent,
        name: crux::AtomId,
        caller_arg_base: Option<usize>,
        argc: usize,
        direct_eval: bool,
    ) -> Result<(), JsError> {
        // Cut 35 slice 12: the call-site leaf cache hit — a stable global
        // callee (the compiler's never-assigned + no-call-like-args guard)
        // keeps its resolved leaf entry across calls while the global
        // object's identity and generation are unchanged, skipping the
        // cell load, kind check, realm check, and leaf lookup every
        // iteration.
        let index = Self::global_cell_index(name);
        // Cut 35 slice 12: the call-site leaf cache hit — a stable global
        // callee (the compiler's never-assigned + no-call-like-args guard)
        // keeps its resolved leaf entry across calls while the global
        // object's identity and generation are unchanged, skipping the
        // cell load, kind check, realm check, and leaf lookup every
        // iteration. Cut 35 slice 25: the cell's fields are checked in
        // place (no tuple) and the entry is cloned only once the global/
        // caller checks pass; the global comparison reads the cached
        // handle without cloning it.
        if let Some(cell) = agent.global_leaf_cells[index].as_ref()
            && cell.name == name
        {
            // Clone the entry while the cell borrow is live (the immutable
            // `agent` borrow must end before the `&mut agent` checks/run);
            // the clone is a single Rc bump for the common no-env leaf.
            let entry = cell.entry.clone();
            let (global_id, global_generation) = (cell.global_id, cell.global_generation);
            if self.global_matches(agent, global_id, global_generation)?
                && self.can_inline_leaf()
                && agent.realm_count.get() == 1
            {
                if agent.jit_hook.is_some() {
                    if self.try_jit_leaf(
                        agent,
                        argc,
                        Value::Undefined,
                        &entry.ir,
                        entry.strict,
                        0,
                        entry.environment,
                        caller_arg_base,
                    )? {
                        return Ok(());
                    }
                    // The fused args (if any) were materialized by the JIT
                    // attempt; the interpreter fallback reads them from the
                    // stack (no caller-frame base).
                    return self.run_inline_leaf(agent, argc, Value::Undefined, entry, 0, None);
                }
                return self.run_inline_leaf(
                    agent,
                    argc,
                    Value::Undefined,
                    entry,
                    0,
                    caller_arg_base,
                );
            }
        }
        // The cache missed: materialize the caller-frame arguments (the
        // fused step no longer pushed them), then the general core.
        if let Some(base) = caller_arg_base {
            for i in 0..argc {
                self.stack.push(*self.frame_get(base + i));
            }
        }
        let callee = self.load_global_value(agent, name)?;
        self.fast_call_core(
            agent,
            argc,
            direct_eval,
            callee,
            Value::Undefined,
            0,
            LeafCacheSite::Global { name },
        )
    }

    /// The `CallFastSlot` handler (Cut 35 slice 4): like
    /// `do_call_fast_global`, but the callee comes from a frame slot — a
    /// certified-value var holding a certified closure. The slot read is a
    /// plain frame access (side-effect-free), and the compiler fused only
    /// when no argument can write the slot, so the callee-after-args order
    /// is unobservable. `caller_arg_base` is the Cut 35 slice 23 caller-
    /// frame argument base (see `do_call_fast_global`).
    fn do_call_fast_slot(
        &mut self,
        agent: &mut Agent,
        slot: usize,
        caller_arg_base: Option<usize>,
        argc: usize,
    ) -> Result<(), JsError> {
        let callee = self.frame_get(slot);
        // Cut 35 slice 12: the slot-callee leaf cache hit — the frame slot
        // holds the same closure (its heap payload matches the cached one,
        // which the held `callee` keeps alive), so the resolved entry is
        // reused without the kind check, realm check, or leaf lookup.
        if let Some(payload) = callee.heap_payload()
            && let Some(cell) = agent.slot_leaf_cells[slot & (SLOT_LEAF_CELLS - 1)].as_ref()
            && cell.payload == payload
            && self.can_inline_leaf()
            && agent.realm_count.get() == 1
        {
            let entry = cell.entry.clone();
            if agent.jit_hook.is_some() {
                if self.try_jit_leaf(
                    agent,
                    argc,
                    Value::Undefined,
                    &entry.ir,
                    entry.strict,
                    0,
                    entry.environment,
                    caller_arg_base,
                )? {
                    return Ok(());
                }
                // The fused args (if any) were materialized by the JIT
                // attempt; the interpreter fallback reads them from the
                // stack.
                return self.run_inline_leaf(agent, argc, Value::Undefined, entry, 0, None);
            }
            return self.run_inline_leaf(agent, argc, Value::Undefined, entry, 0, caller_arg_base);
        }
        let callee = *callee;
        if let Some(base) = caller_arg_base {
            for i in 0..argc {
                self.stack.push(*self.frame_get(base + i));
            }
        }
        self.fast_call_core(
            agent,
            argc,
            false,
            callee,
            Value::Undefined,
            0,
            LeafCacheSite::Slot {
                index: slot & (SLOT_LEAF_CELLS - 1),
                callee,
            },
        )
    }

    /// The shared leaf-inline run (Cut 25/34/35): bind `this`, run the
    /// leaf's register or step-path body against the argument region on the
    /// stack top, and replace the call site (`below` values under the
    /// arguments are truncated with them) with the result. Shared by
    /// `fast_call_core` and the global call-site leaf cache (Cut 35
    /// slice 12). Takes the entry by value so a cached entry needs no
    /// further clone.
    ///
    /// Cut 35 slice 23: `caller_arg_base` marks a fused call-store site
    /// whose arguments live in the CALLER's frame slots (the fused steps no
    /// longer push them) — a read-only-param register leaf reads them
    /// straight from the caller's frame (`LeafFrame::CallerSlots`, no stack
    /// traffic); anything else materializes them on the stack first and
    /// runs the normal frame path.
    #[inline(always)]
    fn run_inline_leaf(
        &mut self,
        agent: &mut Agent,
        argc: usize,
        this_value: Value,
        entry: LeafEntry,
        below: usize,
        caller_arg_base: Option<usize>,
    ) -> Result<(), JsError> {
        let ir = entry.ir;
        let strict = entry.strict;
        let environment = entry.environment;
        // Cut 35 slice 1: a register leaf runs on the small dedicated
        // executor with no `run_leaf_call`/`run_leaf_body` indirection
        // and no completion round-trip (a register body always completes
        // with `Return`); a step-path leaf runs through `run_leaf_body`
        // as before. Both paths converge on one result-placement tail.
        let scope = ir.scope.as_ref().expect("a leaf is certified");
        // Cut 35 slice 25: the common leaf has no `this` slot — skip the
        // `bind_this_value` call entirely (its first check would return
        // `undefined` anyway).
        let this_value = if scope.this_slot.is_none() {
            Value::Undefined
        } else {
            self.bind_this_value(agent, scope, strict, this_value)?
        };
        // The call site: where the result replaces the call. A fused
        // call-store site (Cut 35 slice 23) passes `caller_arg_base` and
        // pushes nothing (its args live in the caller's frame); the other
        // callers' args are already on the stack.
        let pre_call = if caller_arg_base.is_some() {
            self.stack.len()
        } else {
            self.stack.len() - argc
        };
        // Cut 50: the leaf-inline argument copy. The fast `CallFast` form
        // caps at `FAST_CALL_MAX_ARGS`, and the JIT's vector-form `call_vector`
        // routes any count through `do_call_fast` too — so a count beyond the
        // small stack buffer falls back to a function-scoped Vec (mirrors the
        // construct path's Cow, minus the borrow-lifetime dance: the leaf run
        // below borrows the chosen buffer, so both must outlive it).
        let mut args_buf = [Value::Undefined; FAST_CALL_MAX_ARGS];
        let args_owned: Vec<Value>;
        let completion = if let Some(ops) = ir.leaf_ops.as_deref() {
            // Cut 35 slice 23: at a fused call-store site, a register leaf
            // whose params are exactly the frame, all present, and never
            // assigned reads them straight from the caller's frame slots
            // (`LeafFrame::CallerSlots` — no push, no aliased stack
            // region; the fused step already TDZ-checked the slots).
            // Everything else materializes the args and runs the normal
            // frame path (Alias or Pushed) below.
            let frame = if let Some(base) = caller_arg_base
                && scope.args_alias
                && argc == scope.frame_size
            {
                LeafFrame::CallerSlots { base }
            } else {
                if let Some(base) = caller_arg_base {
                    for i in 0..argc {
                        self.stack.push(*self.frame_get(base + i));
                    }
                }
                let n = self.stack.len();
                let arg_start = n - argc;
                // Alias the frame onto the caller's argument region when
                // every frame slot is a present parameter (no `this` slot,
                // no var/TDZ slots): `f(x)`, `f(x, y)` with all args
                // supplied — no argument copy, no frame push. Otherwise
                // push the frame from the copied arguments.
                let arg_base = (scope.this_slot.is_none()
                    && scope.frame_size == scope.arity
                    && argc >= scope.frame_size)
                    .then_some(arg_start);
                if let Some(base) = arg_base {
                    LeafFrame::Alias(base)
                } else {
                    let args: &[Value] = if argc <= args_buf.len() {
                        args_buf[..argc].clone_from_slice(&self.stack[arg_start..n]);
                        &args_buf[..argc]
                    } else {
                        args_owned = self.stack[arg_start..n].to_vec();
                        &args_owned[..]
                    };
                    LeafFrame::Pushed(args)
                }
            };
            self.run_leaf_regs(agent, ops, &ir, environment, this_value, frame)?
        } else {
            // Step-path leaf: materialize the fused site's args (if any),
            // then the step body on the copied arguments.
            if let Some(base) = caller_arg_base {
                for i in 0..argc {
                    self.stack.push(*self.frame_get(base + i));
                }
            }
            let n = self.stack.len();
            let arg_start = n - argc;
            let args: &[Value] = if argc <= args_buf.len() {
                args_buf[..argc].clone_from_slice(&self.stack[arg_start..n]);
                &args_buf[..argc]
            } else {
                args_owned = self.stack[arg_start..n].to_vec();
                &args_owned[..]
            };
            self.run_leaf_body(agent, &ir, environment, strict, this_value, args)?
        };
        let result = Self::leaf_completion_result(completion)?;
        self.stack.truncate(pre_call - below);
        self.stack.push(result);
        Ok(())
    }

    /// Try the JIT leaf path at this call site, shared by every leaf entry
    /// point. `caller_arg_base` marks a fused call-store site whose
    /// arguments live in the caller's frame slots (Cut 35 slice 23) —
    /// materialize them first so `run_jit_leaf` reads them from the stack; a
    /// `None` base means the arguments are already on the stack (a normal
    /// call site, TCO, or a construct site the caller materialized). Returns
    /// `Ok(true)` when the compiled body ran (its result replaced the call
    /// site), `Ok(false)` when the hook is absent or the body has no
    /// compiled code — the caller falls back to the interpreter, and any
    /// materialized arguments remain on the stack for the stack-argument
    /// fallback.
    #[allow(clippy::too_many_arguments)]
    fn try_jit_leaf(
        &mut self,
        agent: &mut Agent,
        argc: usize,
        this: Value,
        ir: &std::rc::Rc<CompiledBody>,
        strict: bool,
        below: usize,
        environment: Option<EnvRef>,
        caller_arg_base: Option<usize>,
    ) -> Result<bool, JsError> {
        if agent.jit_hook.is_none() {
            return Ok(false);
        }
        if let Some(base) = caller_arg_base {
            for i in 0..argc {
                self.stack.push(*self.frame_get(base + i));
            }
        }
        self.run_jit_leaf(agent, argc, this, ir, strict, below, environment)
    }

    /// The JIT leaf path (see `crate::jit`): run `ir`'s compiled machine
    /// code against a private frame/working-area buffer, mirroring
    /// `run_inline_leaf`'s stack discipline — the call site's arguments are
    /// the top `argc` stack values and the result replaces them. Returns
    /// `Ok(true)` when the compiled body ran, `Ok(false)` when the body has
    /// no compiled code (the caller falls back to the interpreter), and
    /// `Err` on a thrown error.
    ///
    /// The frame and the JIT's working area live in a local buffer, not on
    /// `self.stack`: the slow-path helpers receive `&mut Vm` and may push
    /// arbitrary values (a member helper can invoke a setter, which runs JS
    /// on this stack and reallocates the `Vec` under the JIT's raw
    /// pointers). The helpers never see the leaf's frame, so the private
    /// buffer is unobservable.
    #[allow(clippy::too_many_arguments)]
    fn run_jit_leaf(
        &mut self,
        agent: &mut Agent,
        argc: usize,
        this_value: Value,
        ir: &std::rc::Rc<CompiledBody>,
        strict: bool,
        below: usize,
        environment: Option<EnvRef>,
    ) -> Result<bool, JsError> {
        let Some(hook) = agent.jit_hook else {
            return Ok(false);
        };
        // The recursion guard: a nested JIT frame runs with its own private
        // frame/working buffer on the native stack, so unbounded JIT nesting
        // could exhaust it — beyond the cap, fall back to the interpreter
        // (which is what `Ok(false)` routes to).
        if agent.jit_depth >= crate::jit::MAX_JIT_DEPTH {
            return Ok(false);
        }
        let scope = ir.scope.as_ref().expect("a leaf is certified");
        // The per-body fast pointer (set on the first successful lookup —
        // the cache clears it when the entry is evicted, so a set pointer
        // is always valid): a hot call skips the hook entirely. Null = not
        // JIT-compilable, run the interpreter. The in-flight flag is the
        // enclosing JIT depth: a nested lookup (a helper re-entering the
        // interpreter mid-run) must not let the cache evict a running
        // frame's code.
        let info_ptr = crate::jit::lookup_info(hook, ir, agent.jit_depth > 0);
        if info_ptr.is_null() {
            return Ok(false);
        }
        // SAFETY: the cache clears the per-body fast pointer on eviction, so
        // a pointer the caller just obtained (with no frame in flight to
        // evict) is into the cache's own live entry.
        let info = unsafe { &*info_ptr };
        // SAFETY: `info.entry` is a code pointer the cache owns; a fn
        // pointer is pointer-sized, so the integer cast is exact.
        let entry: crate::jit::JitEntry = unsafe { std::mem::transmute(info.entry) };
        // The common leaf has no `this` slot — skip `bind_this_value` (its
        // first check would return `undefined` anyway), mirroring
        // `run_inline_leaf`.
        let this_value = if scope.this_slot.is_none() {
            Value::Undefined
        } else {
            self.bind_this_value(agent, scope, strict, this_value)?
        };
        let pre_call = self.stack.len() - argc;
        // Cut 28/30 mirror: a leaf that reads captured bindings resolves
        // them against its own per-call capture context (`body_context`)
        // built from the closure's environment — clone it and swap both
        // env fields like `run_leaf_body`, restoring them after the run. A
        // leaf with neither context nor per-iteration reads never touches an
        // env, so both swaps are skipped.
        let (caller_body_context, caller_lexical_env) = if let Some(environment) = environment {
            let body_env = match scope
                .new_body_context(&environment, &self.stack[pre_call..pre_call + argc])?
            {
                Some(context) => context,
                None => environment,
            };
            if ir.leaf_needs_env {
                (
                    self.body_context.replace(body_env),
                    Some(std::mem::replace(&mut self.lexical_env, body_env)),
                )
            } else {
                (self.body_context.replace(body_env), None)
            }
        } else {
            debug_assert!(!ir.leaf_uses_env);
            (None, None)
        };
        // The frame (this slot, params, `var`s as undefined, `let`/`const`
        // in the TDZ — `run_leaf_body`'s layout) plus the JIT's working area
        // and the helper slack, in a private buffer — helpers receive
        // `&mut Vm` and may reallocate `self.stack`, so the JIT's raw
        // pointers must never alias it. A small body fits a stack array (no
        // per-call heap allocation); larger bodies spill to a Vec.
        let buf_len = scope.frame_size + info.stack_usage + crate::jit::JIT_STACK_SLACK;
        let (mut inline_buf, mut heap_buf) = (
            [Value::Undefined; crate::jit::INLINE_JIT_BUF],
            Vec::<Value>::new(),
        );
        let buf: &mut [Value] = if buf_len <= crate::jit::INLINE_JIT_BUF {
            &mut inline_buf[..buf_len]
        } else {
            heap_buf.resize(buf_len, Value::Undefined);
            &mut heap_buf[..]
        };
        for (slot, cell) in buf.iter_mut().enumerate().take(scope.frame_size) {
            *cell = if Some(slot) == scope.this_slot {
                this_value
            } else if slot < scope.arity {
                // Missing arguments stay `undefined` (spec 10.2.11).
                self.stack
                    .get(pre_call + slot)
                    .copied()
                    .unwrap_or(Value::Undefined)
            } else if scope.tdz_store.get(slot).copied().unwrap_or(false) {
                Value::uninitialized()
            } else {
                Value::Undefined
            };
        }
        // The live global for the compiled `LoadGlobal` fast path: resolved
        // and cached on this Vm (the machine code re-reads its id/generation
        // in place, so a mid-run mutation invalidates the value cells).
        let global = self.global_object(agent)?;
        // The compiled `LoadIdent` probe's env-chain gate (see
        // `crate::jit::run_jit_body`): the probe is sound only when the
        // body's env chain is exactly the global env — any intermediate env
        // could shadow a name the global fast cell records. Leaf bodies
        // never contain `LoadIdent` (`steps_are_leaf` excludes the
        // reference machinery), so this is computed for uniformity only.
        let clean_chain = {
            let current = agent.running_context()?.lexical_environment;
            matches!(&*current, EnvRecord::Global(_)) && current.outer().is_none()
        };
        // M10: a leaf body can contain a `CallApply` site (the step is not
        // call-excluded), so the compiled site needs the realm's intrinsic
        // bits when the leaf has one; a leaf without one skips the read.
        let (apply_builtin_bits, call_builtin_bits) = if ir.has_call_apply {
            crate::jit::call_apply_intrinsic_bits(agent)
        } else {
            (0, 0)
        };
        let mut ctx = crate::jit::JitCallContext {
            pending: false,
            error: None,
            agent: agent as *mut Agent,
            vm: self as *mut Vm,
            global_object: global.as_ptr() as *mut std::os::raw::c_void,
            global_value_cells: agent.global_value_cells.as_ptr() as *mut std::os::raw::c_void,
            member_value_cells: agent.member_value_cells.as_ptr() as *mut std::os::raw::c_void,
            clean_chain,
            buf_end: (buf.as_ptr() as usize + std::mem::size_of_val(buf))
                as *mut std::os::raw::c_void,
            leaf_epoch: 0,
            leaf_call_cache: [crate::jit::LeafCallSiteCache::empty();
                crate::jit::LEAF_CALL_CACHE_ENTRIES],
            body: std::rc::Rc::as_ptr(ir),
            tail: false,
            current_function: 0,
            apply_builtin_bits,
            call_builtin_bits,
            dispatch_value: 0,
            suspension: None,
            suspend_sp: 0,
            resume_kind: 0,
            resume_ip: 0,
            resume_sp: 0,
            resume_value: 0,
            gc_ticks: crate::jit::JIT_GC_PROBE_INTERVAL,
        };
        let frame_ptr = buf.as_mut_ptr() as *mut std::os::raw::c_void;
        // SAFETY: `buf` has `frame_size + stack_usage + slack` slots.
        let stack_ptr =
            unsafe { buf.as_mut_ptr().add(scope.frame_size) } as *mut std::os::raw::c_void;
        // Root the buffer for the call's duration via the Vm's jit-root list
        // (this Vm is already registered with the active-run tracer, so no
        // thread-local registration is needed): a helper it invokes can
        // allocate and trigger a collection, and a heap value only the
        // buffer references must survive until the JIT stores or returns it.
        self.jit_roots.push((buf.as_ptr() as usize, buf.len()));
        // Cut 51: an array literal (`ArrayBegin` is leaf-eligible — a leaf
        // may build an array) grows `array_index_stack` on the CALLER's Vm;
        // the leaf's steps keep it balanced on the normal path, but a throw
        // mid-literal must not leak the entry into the caller's next
        // literal — mirror `run_leaf_body`'s length save/truncate.
        let array_index_stack_len = self.array_index_stack.len();
        agent.jit_depth += 1;
        let result = unsafe {
            (entry)(
                frame_ptr,
                stack_ptr,
                (&mut ctx as *mut crate::jit::JitCallContext) as *mut std::os::raw::c_void,
            )
        };
        agent.jit_depth -= 1;
        self.jit_roots.pop();
        // Unwind the argument region (the frame/working area were local),
        // then surface a pending error or land the result —
        // `run_inline_leaf`'s tail. The compiled body stops executing after
        // a throwing slow path, so the pending error, when set, is the
        // call's only error.
        self.stack.truncate(pre_call - below);
        self.array_index_stack.truncate(array_index_stack_len);
        if let Some(saved_env) = caller_body_context {
            self.body_context = Some(saved_env);
        }
        if let Some(saved_env) = caller_lexical_env {
            self.lexical_env = saved_env;
        }
        if ctx.pending {
            return Err(ctx.error.take().expect("a pending JIT error is present"));
        }
        self.stack.push(Value::from_bits(result));
        Ok(true)
    }

    /// The shared fast-call core: `callee`/`this` as values, the arguments
    /// as the top `argc` stack values, `below` values under them to truncate
    /// with the arguments on completion. Covers the leaf-inline path (Cut
    /// 25/34/35), direct eval, and the general call.
    #[allow(clippy::too_many_arguments)]
    fn fast_call_core(
        &mut self,
        agent: &mut Agent,
        argc: usize,
        direct_eval: bool,
        callee: Value,
        this: Value,
        below: usize,
        leaf_cache: LeafCacheSite,
    ) -> Result<(), JsError> {
        let n = self.stack.len();
        let arg_start = n - argc;
        // Cut 25: inline a certified leaf call onto this Vm. The eligibility
        // checks are the cheap ones first; the record lookup is what the
        // general path pays anyway. A leaf is never eval (a builtin) and
        // always callable, so the eval/type checks below are skipped.
        if self.can_inline_leaf()
            && let ValueKind::Function(function) = callee.kind()
            && matches!(function.kind, crux::function::FunctionKind::EcmaScript)
            // The leaf runs with the caller's realm current: cross-realm
            // calls dispatch with the callee's realm, which the inline path
            // cannot.
            && agent.realm_count.get() == 1
            // Cut 33/34: the record-derived eligibility and the per-call
            // data (ir, strictness, closure env) come from a direct-mapped
            // cache, skipping the `ecma_functions` HashMap lookup on a hit.
            && let Some(entry) = agent.leaf_lookup(function.id())
        {
            // Clone the entry fields up front so the `leaf_lookup` borrow
            // of the agent ends before the cache write or the run.
            let entry = LeafEntry {
                ir: entry.ir.clone(),
                strict: entry.strict,
                environment: entry.environment,
                construct_inline: entry.construct_inline,
            };
            match leaf_cache {
                LeafCacheSite::Global { name } => {
                    // Cache the resolved entry for the next call (the
                    // callee is stable under the compiler's guard; the
                    // generation re-validates any global mutation).
                    let index = Self::global_cell_index(name);
                    let cached = entry.clone();
                    let global = self.global_object(agent)?;
                    agent.global_leaf_cells[index] = Some(GlobalLeafCell {
                        name,
                        global_id: global.id(),
                        global_generation: global.generation(),
                        entry: cached,
                    });
                }
                LeafCacheSite::Slot { index, callee } => {
                    // The held `callee` keeps the closure alive, so its
                    // payload can never be reused while the entry exists.
                    let cached = entry.clone();
                    agent.slot_leaf_cells[index] = Some(SlotLeafCell {
                        payload: callee
                            .heap_payload()
                            .expect("a leaf callee is a heap function value"),
                        callee,
                        entry: cached,
                    });
                }
                LeafCacheSite::None => {}
            }
            // The JIT path (when installed) runs the certified body's
            // machine code; a body without compiled code falls through to
            // the interpreter's leaf-inline run.
            if self.try_jit_leaf(
                agent,
                argc,
                this,
                &entry.ir,
                entry.strict,
                below,
                entry.environment,
                None,
            )? {
                return Ok(());
            }
            return self.run_inline_leaf(agent, argc, this, entry, below, None);
        }
        let args = &self.stack[arg_start..n];
        if is_eval_function(agent, &callee)? {
            let source = args.first().cloned().unwrap_or(Value::Undefined);
            // The `eval` builtin (spec 18.2.1 step 1): a non-string argument
            // is returned unchanged — only a primitive string is parsed.
            if !matches!(source.kind(), ValueKind::String(_)) {
                self.stack.truncate(arg_start - below);
                self.stack.push(source);
                return Ok(());
            }
            let source = crux::convert::to_string(&source)?;
            let result = crate::script::perform_eval(agent, &source, self.strict, direct_eval)?;
            self.stack.truncate(arg_start - below);
            self.stack.push(result);
            return Ok(());
        }
        if !is_callable(&callee) {
            return Err(JsError::new(
                ErrorKind::TypeError,
                format!("{} is not a function", crux::value::type_of(&callee)),
            ));
        }
        let result = crate::function::call_inner(agent, &callee, this, args)?;
        self.stack.truncate(arg_start - below);
        self.stack.push(result);
        Ok(())
    }

    /// The for-of iteration step (spec 14.7.6.2, `%ArrayIteratorPrototype%.next`
    /// for the fast path): advance the innermost for-of entry and land the
    /// element on the value stack (the general shape) or in a frame slot
    /// directly (the fused bind, Cut 21). On a successful fetch, `back` is
    /// where the loop continues (the do-while body start, Cut 35 slice 18 —
    /// no per-element back-jump); on exhaustion, `done`.
    pub(crate) fn for_of_next(
        &mut self,
        agent: &mut Agent,
        done: usize,
        back: usize,
        target: ForOfNextTarget,
    ) -> Result<(), JsError> {
        match self.for_of_advance(agent)? {
            ForOfAdvance::Element(value) => {
                match target {
                    ForOfNextTarget::Stack => self.stack.push(value),
                    ForOfNextTarget::Slot(slot) => *self.frame_get_mut(slot) = value,
                }
                self.ip = back;
            }
            ForOfAdvance::Done => self.ip = done,
        }
        Ok(())
    }

    /// Advance the innermost for-of entry (spec 14.7.6.2,
    /// `%ArrayIteratorPrototype%.next` for the fast path). The dense fast
    /// path re-reads the length and the element every step so a body that
    /// mutates the array is observed exactly as the stock iterator would. A
    /// generic `next()` error propagates with `for_of_stepping` left set so
    /// the close machinery skips the iterator (spec 14.7.6.2 uses `?` on the
    /// next call — only a normal completion or an abrupt body/head
    /// completion closes).
    pub(crate) fn for_of_advance(&mut self, agent: &mut Agent) -> Result<ForOfAdvance, JsError> {
        // The innermost state is cloned out so the arm can mutate the stacks
        // while agent-side calls run.
        let fast = match self.for_of_stack.last() {
            Some(ForOfEntry::Fast { array, index }) => Some((*array, *index)),
            _ => None,
        };
        if let Some((array, index)) = fast {
            let length = Self::array_length(agent, &array)?;
            if index as u64 >= length {
                self.for_of_stack.pop();
                self.for_of_boundaries.pop();
                return Ok(ForOfAdvance::Done);
            }
            // The element read goes through the numeric direct-mapped cache
            // (no per-element number→string→intern round-trip); a hole or
            // structural change falls back to the full Get.
            let value = match Self::array_element_get(agent, &array, index as u64) {
                Some(value) => value,
                None => {
                    let value = crate::context::get_property_key(
                        agent,
                        &array,
                        &PropertyKey::from_utf8(&index.to_string()),
                        array,
                    )?;
                    Self::resolve_array_element(agent, &array, index as u64);
                    value
                }
            };
            if let Some(ForOfEntry::Fast { index: slot, .. }) = self.for_of_stack.last_mut() {
                *slot = index + 1;
            }
            return Ok(ForOfAdvance::Element(value));
        }
        let Some(iterator) = self.for_of_stack.last() else {
            return Err(JsError::new(
                ErrorKind::SyntaxError,
                "ForOfNext without a for-of".into(),
            ));
        };
        let ForOfEntry::Generic(iterator) = iterator else {
            unreachable!("fast entries are handled above")
        };
        let iterator = iterator.clone();
        // A `next()` error propagates without closing the iterator (spec
        // 14.7.6.2 uses `?`): the flag stays set on the error path so the
        // close machinery skips it.
        self.for_of_stepping = true;
        match iterator_step(agent, &iterator) {
            Ok(Some(value)) => {
                self.for_of_stepping = false;
                Ok(ForOfAdvance::Element(value))
            }
            Ok(None) => {
                self.for_of_stepping = false;
                self.for_of_stack.pop();
                self.for_of_boundaries.pop();
                Ok(ForOfAdvance::Done)
            }
            Err(error) => Err(error),
        }
    }

    fn for_binding_put(
        &mut self,
        agent: &mut Agent,
        left: &ForBinding,
        value: Value,
    ) -> Result<(), JsError> {
        match left {
            ForBinding::Expr(expr) => {
                let reference = crate::expr::eval_reference(agent, expr, self.strict)?;
                crate::context::put_value(agent, &reference, value)?;
            }
            ForBinding::VarDecl { kind, pattern, .. } => {
                if *kind == VarDeclKind::Var {
                    crate::binding::binding_initialization(
                        agent,
                        pattern,
                        value,
                        None,
                        self.strict,
                    )?;
                } else {
                    let outer = self.lexical_env;
                    let env = new_declarative_environment(Some(outer));
                    let mut names = Vec::new();
                    crate::script::bound_names(pattern, &mut names);
                    for name in &names {
                        if *kind == VarDeclKind::Const
                            || matches!(*kind, VarDeclKind::Using | VarDeclKind::AwaitUsing)
                        {
                            // `using` bindings are immutable like `const`
                            // (spec 15.14.2).
                            env.create_immutable_binding(name, true)?;
                        } else {
                            env.create_mutable_binding(name, false)?;
                        }
                    }
                    // spec 14.7.5.6 step 5.e: AddDisposableResource runs
                    // before InitializeReferencedBinding.
                    if matches!(*kind, VarDeclKind::Using | VarDeclKind::AwaitUsing) {
                        let kind = if *kind == VarDeclKind::AwaitUsing {
                            crate::eval::DisposalKind::Async
                        } else {
                            crate::eval::DisposalKind::Sync
                        };
                        let resource =
                            crate::eval::create_disposable_resource(agent, &value, kind)?;
                        env.add_disposable_resource(resource);
                    }
                    // The defaults in the pattern resolve against the
                    // per-iteration environment (a default like `b = a` sees
                    // the already-bound sibling `a`). Sync the context now so
                    // the mid-step destructure sees the new environment.
                    self.lexical_env = env;
                    self.env_stack.push(env);
                    if let Ok(context) = agent.running_context_mut() {
                        context.lexical_environment = env;
                    }
                    crate::binding::binding_initialization(
                        agent,
                        pattern,
                        value,
                        Some(&env),
                        self.strict,
                    )?;
                    // The per-iteration environment joins the environment
                    // stack (the compiler counts it as one scope), so every
                    // loop exit — fall-through, continue, break, labeled
                    // break — unwinds it with the same machinery.
                    self.lexical_env = env;
                }
            }
        }
        Ok(())
    }

    /// Pop a per-iteration environment created by a for-in/for-of bind,
    /// disposing its `using` resources (spec 14.7.5.6 / 14.7.6.2: the
    /// iteration environment is disposed at iteration end).
    fn restore_per_iteration(&mut self, agent: &mut Agent) -> Result<(), JsError> {
        // The per-iteration environment lives on the environment stack (the
        // compiler counts it as one scope), so the restore pops it and
        // unwinds back to the pre-iteration environment; each iteration's
        // bind step creates a fresh copy whose outer is the loop base, so
        // closures never chain through previous iterations.
        let env = self.env_stack.pop().ok_or_else(|| {
            JsError::new(
                ErrorKind::SyntaxError,
                "Per-iteration restore without an environment".into(),
            )
        })?;
        let resources = env.drain_disposable_resources();
        for resource in resources.iter().rev() {
            if !resource.method.is_undefined() {
                crate::function::call(agent, &resource.method, resource.value, &[])?;
            }
        }
        self.lexical_env = env.outer().unwrap_or(env);
        Ok(())
    }

    /// The declarative per-iteration env `depth` outers from the current
    /// env (0 = the loop's own): the compiler emits `depth` as the number
    /// of enclosing per-iteration envs, so the walk stays inside the env
    /// chain of declarative per-iteration envs (each fresh per iteration).
    pub(crate) fn per_iteration_env(&self, depth: usize) -> Result<EnvRef, JsError> {
        let mut env = self.lexical_env;
        for _ in 0..depth {
            env = env.outer().ok_or_else(|| {
                JsError::new(
                    ErrorKind::ReferenceError,
                    "No outer environment for a per-iteration binding".into(),
                )
            })?;
        }
        Ok(env)
    }

    /// The certified body's capture context (Cut 3 continuation): the env
    /// holding the captured bindings. The context-slot steps target it
    /// directly — inside a per-iteration loop the lexical env is the loop's
    /// fresh per-iteration env, which holds only the head names.
    fn body_context_env(&self) -> EnvRef {
        self.body_context.unwrap_or(self.lexical_env)
    }

    /// The capture context at static context-chain `depth` (Cut 3
    /// continuation, nested context chains): depth 0 = the body's own
    /// capture context; depth ≥ 1 walks out through the enclosing certified
    /// bodies' contexts. Per-iteration environments are skipped — they hold
    /// only the loop-head names, so a capture-free closure created inside a
    /// loop still reaches its enclosing body's context.
    pub(crate) fn context_chain_env(&self, depth: usize) -> Result<EnvRef, JsError> {
        let mut env = self.body_context_env();
        loop {
            if !is_context_transparent(&env) {
                break;
            }
            env = env.outer().ok_or_else(|| {
                JsError::new(
                    ErrorKind::ReferenceError,
                    "No outer environment for a capture-context binding".into(),
                )
            })?;
        }
        for _ in 0..depth {
            loop {
                env = env.outer().ok_or_else(|| {
                    JsError::new(
                        ErrorKind::ReferenceError,
                        "No outer environment for a capture-context binding".into(),
                    )
                })?;
                if !is_context_transparent(&env) {
                    break;
                }
            }
        }
        Ok(env)
    }

    /// The control-transfer machinery: route through pending finallys, then
    /// apply the control.
    pub(crate) fn control_transfer(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        ctl: Ctl,
    ) -> Result<CtlResult, JsError> {
        // An abrupt control transfer while a finally is running replaces the
        // pending control the finally was processing (spec 14.15.4 step 8: a
        // `break`/`continue`/`return`/`throw` inside a finally overrides it)
        // — the pending's environment is the restore target (it unwinds the
        // finally's own block envs), and the finally that held it already
        // consumed its frame, so the new control applies directly. A NORMAL
        // completion (an inner try's Exit inside the finally) leaves the
        // pending for FinallyEnd.
        if let Some(pending) = (matches!(
            ctl,
            Ctl::Break { .. } | Ctl::Continue { .. } | Ctl::Return { .. } | Ctl::Throw { .. }
        ))
        .then(|| self.pending.pop())
        .flatten()
        {
            let (env, depth) = pending_env_depth(&pending);
            self.restore_env(env, depth);
            if let Ctl::Return { .. } = ctl {
                self.close_for_of_return(agent)?;
            } else if let Ctl::Throw { .. } = ctl {
                self.close_for_of_throw(agent);
            } else if let Ctl::Break { target } | Ctl::Continue { target } = ctl {
                self.close_for_of_upto(agent, target)?;
            }
            return Ok(match ctl {
                Ctl::Normal { after } => {
                    self.ip = after;
                    CtlResult::Continue
                }
                Ctl::Break { target } => {
                    self.ip = target;
                    CtlResult::Continue
                }
                Ctl::Continue { target } => {
                    self.ip = target;
                    CtlResult::Continue
                }
                Ctl::Return { value } => {
                    CtlResult::Done(VmOutcome::Completed(Completion::Return(value)))
                }
                Ctl::Throw { value } => {
                    CtlResult::Done(VmOutcome::Completed(Completion::Throw(value)))
                }
            });
        }
        loop {
            let decision = self.find_finally_frame(body, &ctl);
            match decision {
                Some((index, Some(finally))) => {
                    let frame = self.try_stack.remove(index);
                    // The pending re-applies the deferred control at the
                    // depth the transfer has already unwound to: the
                    // compiled `leave_scopes` pops run before the
                    // control-transfer step, so envs below the try (a loop
                    // body block the `continue` exits) are gone. The finally
                    // body itself runs at the try-entry environment (restored
                    // below), and a fresh throw (no leave_scopes) keeps the
                    // try-entry depth — `min` picks the right one.
                    let depth = self.env_stack.len().min(frame.env_depth);
                    let env = self
                        .env_stack
                        .get(depth.saturating_sub(1))
                        .cloned()
                        .unwrap_or(self.lexical_env);
                    self.pending.push(match &ctl {
                        Ctl::Normal { after } => PendingControl::Normal {
                            after: *after,
                            env,
                            depth,
                        },
                        Ctl::Break { target } => PendingControl::Break {
                            target: *target,
                            env,
                            depth,
                        },
                        Ctl::Continue { target } => PendingControl::Continue {
                            target: *target,
                            env,
                            depth,
                        },
                        Ctl::Return { value } => PendingControl::Return {
                            value: *value,
                            env,
                            depth,
                        },
                        Ctl::Throw { value } => PendingControl::Throw {
                            value: *value,
                            env,
                            depth,
                        },
                    });
                    self.restore_env(frame.saved_env, frame.env_depth);
                    self.ip = finally;
                    return Ok(CtlResult::Continue);
                }
                Some((index, None)) => {
                    self.try_stack.remove(index);
                }
                None => {
                    // A return (or throw re-applied after a finally) leaving
                    // the body closes the active for-of iterators, inner
                    // first; a throwing `return` replaces the completion
                    // (spec 7.4.6).
                    if let Ctl::Return { .. } = ctl {
                        self.close_for_of_return(agent)?;
                    } else if let Ctl::Throw { .. } = ctl {
                        self.close_for_of_throw(agent);
                    } else if let Ctl::Break { target } | Ctl::Continue { target } = ctl {
                        // A break/continue whose target lies before a
                        // for-of loop's end exits it — close the iterator
                        // (the compiled ForOfClose was skipped).
                        self.close_for_of_upto(agent, target)?;
                    }
                    return Ok(match ctl {
                        Ctl::Normal { after } => {
                            self.ip = after;
                            CtlResult::Continue
                        }
                        Ctl::Break { target } => {
                            self.ip = target;
                            CtlResult::Continue
                        }
                        Ctl::Continue { target } => {
                            self.ip = target;
                            CtlResult::Continue
                        }
                        Ctl::Return { value } => {
                            CtlResult::Done(VmOutcome::Completed(Completion::Return(value)))
                        }
                        Ctl::Throw { value } => {
                            CtlResult::Done(VmOutcome::Completed(Completion::Throw(value)))
                        }
                    });
                }
            }
        }
    }

    /// The innermost try frame the control leaves, with its finally target
    /// (or `None` when the frame has no finally).
    pub(crate) fn find_finally_frame(
        &self,
        body: &CompiledBody,
        ctl: &Ctl,
    ) -> Option<(usize, Option<usize>)> {
        for (i, frame) in self.try_stack.iter().enumerate().rev() {
            let handler = body.handlers.get(frame.handler)?;
            let covered_end = handler.catch.map(|c| c.end).unwrap_or(handler.try_end);
            // The ip is the *next* step to run (advanced at loop top), so a
            // try region's own `Exit` step runs with ip == try_end + 1; that
            // frame must still be found so its finally runs on the normal
            // path (GeneratorPrototype/throw/try-finally*).
            if self.ip < handler.start || self.ip > covered_end + 1 {
                continue;
            }
            let leaves = match ctl {
                Ctl::Normal { after } => !(handler.start <= *after && *after < covered_end),
                Ctl::Break { target } | Ctl::Continue { target } => {
                    !(handler.start <= *target && *target < covered_end)
                }
                Ctl::Return { .. } | Ctl::Throw { .. } => true,
            };
            if !leaves {
                continue;
            }
            return Some((i, handler.finally));
        }
        None
    }

    /// The throw machinery: dispatch to a catch or route through finallys.
    pub(crate) fn throw_machinery(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        value: Value,
    ) -> Result<CtlResult, JsError> {
        loop {
            let decision = {
                let mut found: Option<(usize, ThrowAction)> = None;
                for (i, frame) in self.try_stack.iter().enumerate().rev() {
                    let Some(handler) = body.handlers.get(frame.handler) else {
                        continue;
                    };
                    // The frame covers the try region and its catch body (a
                    // throw from the catch must still run the finally); only a
                    // throw inside the try region itself dispatches to the
                    // catch. The `+1` mirrors find_finally_frame: the Exit
                    // step's ip is covered_end + 1.
                    let covered_end = handler.catch.map(|c| c.end).unwrap_or(handler.try_end);
                    if self.ip < handler.start || self.ip > covered_end + 1 {
                        continue;
                    }
                    let in_try = self.ip < handler.try_end;
                    found = Some((
                        i,
                        if in_try && handler.catch.is_some() {
                            ThrowAction::Catch
                        } else if handler.finally.is_some() {
                            ThrowAction::Finally
                        } else {
                            ThrowAction::Pop
                        },
                    ));
                    break;
                }
                found
            };
            match decision {
                Some((index, ThrowAction::Catch)) => {
                    // A throw whose catch lies outside the finally holding a
                    // pending control escapes that finally: the throw
                    // replaces the pending (spec 14.15.4 step 8), restoring
                    // to the try-entry environment. A catch INSIDE the
                    // finally (its frame was entered above the finally's
                    // restore depth) leaves the pending for FinallyEnd.
                    if let Some(pending) = self.pending.pop() {
                        let (_, pending_depth) = pending_env_depth(&pending);
                        if self.try_stack[index].env_depth <= pending_depth {
                            let (env, depth) = pending_env_depth(&pending);
                            self.restore_env(env, depth);
                        } else {
                            self.pending.push(pending);
                        }
                    }
                    let handler_index = self.try_stack[index].handler;
                    let has_finally = body
                        .handlers
                        .get(handler_index)
                        .is_some_and(|h| h.finally.is_some());
                    let saved_env = self.try_stack[index].saved_env;
                    let env_depth = self.try_stack[index].env_depth;
                    if !has_finally {
                        // Keep the frame when a finally is pending: the catch's
                        // `Exit` routes through it (spec 14.15.4 step 5: the
                        // finally runs even after a caught error).
                        self.try_stack.remove(index);
                    }
                    // Leave the try block's envs on the stack: `CatchBind`
                    // disposes their `using` resources (folding into the
                    // thrown value) before restoring the saved environment.
                    self.pending_catch_disposal = Some((saved_env, env_depth));
                    self.thrown = Some(value);
                    let catch_start = body
                        .handlers
                        .get(handler_index)
                        .and_then(|h| h.catch)
                        .map(|c| c.start)
                        .unwrap_or(self.ip);
                    // A throw whose catch resumes outside a for-of loop exits
                    // it: close the iterator (spec 14.7.5.6 — the throw
                    // propagates through IteratorClose before the catch runs).
                    self.close_for_of_upto(agent, catch_start)?;
                    self.ip = catch_start;
                    return Ok(CtlResult::Continue);
                }
                Some((index, ThrowAction::Finally)) => {
                    let frame = self.try_stack.remove(index);
                    // Restore to the try-entry environment (the state when
                    // the finally started) so the finally's block envs unwind
                    // with the pending throw.
                    let env = frame.saved_env;
                    let depth = frame.env_depth;
                    self.pending
                        .push(PendingControl::Throw { value, env, depth });
                    self.restore_env(frame.saved_env, frame.env_depth);
                    let finally = body
                        .handlers
                        .get(frame.handler)
                        .and_then(|h| h.finally)
                        .unwrap_or(self.ip);
                    self.ip = finally;
                    return Ok(CtlResult::Continue);
                }
                Some((index, ThrowAction::Pop)) => {
                    self.try_stack.remove(index);
                }
                None => {
                    // A throw escaping a finally discards its pending control
                    // (the finally never reaches FinallyEnd).
                    if let Some(pending) = self.pending.pop() {
                        let (env, depth) = pending_env_depth(&pending);
                        self.restore_env(env, depth);
                    }
                    // A generic `next()` error escapes with the iterator open
                    // (spec 14.7.6.2 uses `?` on the next call — the
                    // interpreter's run_inner Err arm skips the close the
                    // same way; the JIT's pending-error dispatch routes such
                    // errors through here).
                    if !self.for_of_stepping {
                        self.close_for_of_throw(agent);
                    }
                    return Ok(CtlResult::Done(VmOutcome::Completed(Completion::Throw(
                        value,
                    ))));
                }
            }
        }
    }

    /// Convert an engine error into a thrown value and route it through the
    /// body's handler table. `yield*` protocol errors (GetIterator, inner
    /// `next`/`throw`/`return` errors) are catchable by the generator body
    /// (spec 15.5.5 uses `?` on every step).
    fn throw_js_error(
        &mut self,
        agent: &mut Agent,
        body: &CompiledBody,
        error: JsError,
    ) -> Result<CtlResult, JsError> {
        let thrown = crate::promise::error_value(agent, &error);
        self.throw_machinery(agent, body, thrown)
    }
}

#[derive(Debug, Clone, Copy)]
enum ThrowAction {
    Catch,
    Finally,
    Pop,
}

// ---------------------------------------------------------------------------
// Free helpers
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Free helpers
// ---------------------------------------------------------------------------

pub(crate) fn is_nullish(value: &Value) -> bool {
    matches!(value.kind(), ValueKind::Undefined | ValueKind::Null)
}

/// Split an array/object element into its target and optional default
/// initializer (`[x = init]` / `{x = init}` become an `Assign` node).
fn unwrap_default(expr: &Expr) -> (&Expr, Option<&Expr>) {
    match &expr.kind {
        ExprKind::Assign {
            op: AssignOp::Assign,
            target,
            value: initializer,
        } => (target.as_ref(), Some(initializer.as_ref())),
        _ => (expr, None),
    }
}

/// Whether a binding pattern or a declaration initializer contains a
/// suspension point: a default initializer, computed key, or nested pattern
/// with `yield`/`await`. Such declarations must be compiled to steps (the
/// runtime `binding_initialization` evaluates defaults through the
/// synchronous tree-walker, which cannot suspend).
fn binding_pattern_contains_suspension_any(pattern: &BindingPattern, init: Option<&Expr>) -> bool {
    init.is_some_and(expr_contains_suspension)
        || match pattern {
            BindingPattern::Ident(_) => false,
            BindingPattern::Object(props) => props.iter().any(|prop| match prop {
                syntax::ast::ObjectBindingProperty::Property { key, element, .. } => {
                    pattern_element_contains_suspension(element)
                        || matches!(key, PropertyName::Computed(e) if expr_contains_suspension(e))
                }
                syntax::ast::ObjectBindingProperty::Rest(element) => {
                    pattern_element_contains_suspension(element)
                }
            }),
            BindingPattern::Array(elements) => elements.iter().any(|element| match element {
                ArrayBindingElement::Hole => false,
                ArrayBindingElement::Element(e) | ArrayBindingElement::Rest(e) => {
                    pattern_element_contains_suspension(e)
                }
            }),
        }
}

/// Whether a binding element (pattern + optional default) contains a
/// suspension point, either in the default initializer or in a nested
/// pattern's defaults/computed keys.
fn pattern_element_contains_suspension(element: &BindingElement) -> bool {
    binding_pattern_contains_suspension_any(&element.pattern, element.init.as_ref())
}

pub(crate) fn nullish_error(what: &str) -> JsError {
    JsError::new(ErrorKind::TypeError, what.into())
}

/// The UTF-16 units of a value converted to a string; used by the string
/// concatenation steps, which must preserve lone surrogates (a lossy UTF-8
/// round-trip would replace them with U+FFFD).
pub(crate) fn string_units_of(value: &Value) -> Vec<u16> {
    match value.kind() {
        ValueKind::String(s) => s.as_slice().to_vec(),
        _ => crux::convert::to_string(value)
            .map(|s| s.as_slice().to_vec())
            .unwrap_or_else(|_| vec![]),
    }
}

pub(crate) fn error_message_value(error: &JsError) -> Value {
    Value::String(Handle::new(JsString::from_utf8(&error.message)))
}

/// The `++`/`--` result pair: (numeric old, new) — the postfix update
/// returns the ToNumeric-converted old value (spec 13.4.4 step 5), the
/// prefix the new value.
pub(crate) fn update_value(
    _agent: &mut Agent,
    op: &UpdateOp,
    old: &Value,
) -> Result<(Value, Value), JsError> {
    let old_numeric = crux::convert::to_numeric(old)?;
    let new = match old_numeric.kind() {
        ValueKind::Number(n) => {
            let delta = if matches!(op, UpdateOp::Increment) {
                1.0
            } else {
                -1.0
            };
            Value::Number(n + delta)
        }
        ValueKind::BigInt(b) => {
            let one = crux::BigInt::from(1i64);
            let delta = if matches!(op, UpdateOp::Increment) {
                one
            } else {
                crux::bigint::unary_minus(&one)
            };
            Value::BigInt(Handle::new(crux::bigint::add(&b, &delta)))
        }
        _ => unreachable!(),
    };
    Ok((old_numeric, new))
}

/// The string atom of a member-store key when the L1a store cell can serve
/// it: a named property or a computed key already converted to a string atom
/// (symbol keys have no atom and never take the warm store).
pub(crate) fn name_atom(key: &PropertyKeyName) -> Option<crux::AtomId> {
    match key {
        PropertyKeyName::Name(id) => Some(*id),
        PropertyKeyName::Key(PropertyKey::String(id)) => Some(*id),
        PropertyKeyName::Key(_) => None,
    }
}

pub(crate) fn member_reference(
    object: &Value,
    key: &PropertyKeyName,
    strict: bool,
) -> crate::context::Reference {
    let name = match key {
        // `Name` already holds the interned atom: the canonical
        // `PropertyKey::String(id)` form. Round-tripping through
        // `crux::lookup` + re-intern would clone the string and re-hash it
        // on every member write for no change (interning is injective).
        PropertyKeyName::Name(id) => PropertyKey::String(*id),
        PropertyKeyName::Key(key) => key.clone(),
    };
    crate::context::Reference {
        base: crate::context::ReferenceBase::Value(*object),
        name,
        strict,
        this_value: None,
        private_name: None,
    }
}

fn super_reference(
    base: &Value,
    key: &PropertyKeyName,
    strict: bool,
    this: &Value,
) -> crate::context::Reference {
    let name = match key {
        PropertyKeyName::Name(id) => PropertyKey::String(*id),
        PropertyKeyName::Key(key) => key.clone(),
    };
    crate::context::Reference {
        base: crate::context::ReferenceBase::Value(*base),
        name,
        strict,
        this_value: Some(*this),
        private_name: None,
    }
}

pub(crate) fn is_eval_function(agent: &Agent, value: &Value) -> Result<bool, JsError> {
    // `%eval%` is a builtin function; a non-function value or a compiled
    // EcmaScript callee can never be it, so the intrinsics lookup (a HashMap
    // hit per call) is skipped for the hot path. Only agent-dependent
    // builtins reach the lookup.
    match value.kind() {
        ValueKind::Function(function)
            if matches!(function.kind, crux::function::FunctionKind::EcmaScript) =>
        {
            return Ok(false);
        }
        ValueKind::Function(_) => {}
        _ => return Ok(false),
    }
    let realm = agent.current_realm()?;
    Ok(realm.intrinsics.get("%eval%").as_ref() == Some(value))
}

pub(crate) fn array_set(array: &Value, key: &str, value: Value) -> Result<(), JsError> {
    let ValueKind::Object(obj) = array.kind() else {
        return Err(JsError::new(ErrorKind::TypeError, "not an object".into()));
    };
    obj.create_data_property(&JsString::from_utf8(key), value)?;
    Ok(())
}

/// Object literal `Init` property definition (spec 13.2.5.5 step 4): the
/// `__proto__` prototype-setter special case plus name inference.
pub(crate) fn object_init(
    object: &Value,
    key: &PropertyName,
    value: Value,
    set_name: bool,
    shorthand: bool,
) -> Result<(), JsError> {
    let ValueKind::Object(obj) = object.kind() else {
        return Err(JsError::new(ErrorKind::TypeError, "not an object".into()));
    };
    let name = match key {
        PropertyName::Ident(id) => {
            // Fast path: a plain data property (not the `__proto__`
            // prototype setter, no anonymous-function name) defines directly
            // through the already-interned atom — the slow path materializes
            // a JsString, a Rust String (for the `__proto__` check), and a
            // re-intern of the same text per property.
            if !shorthand && !set_name && *id != crux::proto_atom() {
                return obj
                    .create_data_property_key(&PropertyKey::String(*id), value)
                    .map(|_| ());
            }
            crux::lookup(*id)
        }
        PropertyName::Str(text) => text.clone(),
        PropertyName::Number(n) => crux::convert::to_string(&Value::Number(*n))?,
        PropertyName::Computed(_) => {
            unreachable!("computed keys use the ObjectInitComputed step")
        }
    };
    if set_name {
        crate::function::set_function_name(&value, &name, None)?;
    }
    let name_text = name.to_string_lossy();
    if !shorthand && name_text == "__proto__" {
        match value.kind() {
            ValueKind::Object(proto) => {
                if !obj.set_prototype_of(Some(proto))? {
                    return Err(JsError::new(
                        ErrorKind::TypeError,
                        "Cannot set prototype of non-extensible object".into(),
                    ));
                }
            }
            ValueKind::Null if !obj.set_prototype_of(None)? => {
                return Err(JsError::new(
                    ErrorKind::TypeError,
                    "Cannot set prototype of non-extensible object".into(),
                ));
            }
            // B.3.1 step 6: a non-object, non-null value sets neither the
            // prototype nor an own property — the definition is a no-op.
            _ => {}
        }
    } else {
        obj.create_data_property(&name, value)?;
    }
    Ok(())
}

/// A computed-key `Init` property definition (spec 13.2.5.5 step 4): a
/// computed key is never the `__proto__` prototype setter, and SetFunctionName
/// uses the key's display form (a symbol's bracketed description).
pub(crate) fn object_init_key(
    obj: &crux::object::JsObject,
    key: PropertyKey,
    value: Value,
    set_name: bool,
) -> Result<(), JsError> {
    if set_name {
        crate::function::set_function_name(&value, &crate::expr::property_key_display(&key), None)?;
    }
    obj.create_data_property_key(&key, value)?;
    Ok(())
}

/// MethodDefinition evaluation (spec 15.4.3) for the IR object literal steps.
pub(crate) fn object_method(
    agent: &mut Agent,
    object: &Value,
    key: PropertyKey,
    function: &Function,
    strict: bool,
) -> Result<(), JsError> {
    let ValueKind::Object(obj) = object.kind() else {
        return Err(JsError::new(ErrorKind::TypeError, "not an object".into()));
    };
    let env = agent.running_context()?.lexical_environment;
    let closure = crate::function::instantiate_method(agent, function, env, strict)?;
    crate::function::make_method(agent, &closure, Value::Object(obj))?;
    crate::function::set_function_name(&closure, &crate::expr::property_key_display(&key), None)?;
    obj.create_data_property_key(&key, closure)?;
    Ok(())
}

/// Accessor definition (get/set PropertyDefinition) for the IR steps.
#[allow(clippy::too_many_arguments)]
pub(crate) fn object_accessor(
    agent: &mut Agent,
    object: &Value,
    key: PropertyKey,
    get: bool,
    param: Option<&BindingElement>,
    body: &syntax::ast::Block,
    strict: bool,
) -> Result<(), JsError> {
    let ValueKind::Object(obj) = object.kind() else {
        return Err(JsError::new(ErrorKind::TypeError, "not an object".into()));
    };
    let env = agent.running_context()?.lexical_environment;
    let params = if let Some(param) = param {
        vec![param.clone()]
    } else {
        Vec::new()
    };
    let closure = crate::function::instantiate_accessor(agent, params, body, env, strict)?;
    crate::function::make_method(agent, &closure, Value::Object(obj))?;
    let prefix = if get { Some("get") } else { Some("set") };
    crate::function::set_function_name(&closure, &crate::expr::property_key_display(&key), prefix)?;
    let descriptor = crux::property::PropertyDescriptor {
        value: None,
        writable: None,
        get: if get { Some(closure) } else { None },
        set: if get { None } else { Some(closure) },
        enumerable: Some(true),
        configurable: Some(true),
    };
    obj.define_property_key(&key, &descriptor)?;
    Ok(())
}

/// TaggedTemplate evaluation (spec 13.3.6.2) for the IR step.
fn tagged_template(
    agent: &mut Agent,
    this: Value,
    tag: Value,
    template: &syntax::ast::TemplateLiteral,
    substitutions: Vec<Value>,
) -> Result<Value, JsError> {
    if !is_callable(&tag) {
        return Err(JsError::new(
            ErrorKind::TypeError,
            format!("{} is not a function", crux::value::type_of(&tag)),
        ));
    }
    // GetTemplateObject (spec 12.2.9.3): the same parse node yields the same
    // frozen array across calls, via the shared realm/parse-generation cache.
    let template_object = crate::expr::get_template_object(agent, template)?;
    let mut args = vec![template_object];
    args.extend(substitutions);
    crate::function::call(agent, &tag, this, &args)
}

fn iterator_result_done(agent: &mut Agent, result: &Value) -> Result<bool, JsError> {
    let done = crate::context::get_property(agent, result, &JsString::from_utf8("done"), *result)?;
    Ok(crux::convert::to_boolean(&done))
}

fn iterator_result_value(agent: &mut Agent, result: &Value) -> Result<Value, JsError> {
    crate::context::get_property(agent, result, &JsString::from_utf8("value"), *result)
}

/// GetIterator with the ~async~ hint for an async-generator `yield*` (spec
/// 14.5.5 step 1): `@@asyncIterator` when present, else the sync iterator
/// wrapped as an async-from-sync iterator.
fn get_async_iterator_record(
    agent: &mut Agent,
    value: &Value,
) -> Result<crate::expr::IteratorRecord, JsError> {
    let method = crate::expr::get_method(agent, value, "@@asyncIterator")?;
    if let Some(method) = method {
        let iterator = crate::function::call(agent, &method, *value, &[])?;
        if !matches!(iterator.kind(), ValueKind::Object(_)) {
            return Err(JsError::new(
                ErrorKind::TypeError,
                "async iterator must be an object".into(),
            ));
        }
        let next =
            crate::context::get_property(agent, &iterator, &JsString::from_utf8("next"), iterator)?;
        if !crux::value::is_callable(&next) {
            return Err(JsError::new(
                ErrorKind::TypeError,
                "async iterator has no callable next".into(),
            ));
        }
        return Ok(crate::expr::IteratorRecord { iterator, next });
    }
    let sync = crate::expr::get_iterator(agent, value)?;
    let object = crate::async_await::async_from_sync_iterator(agent, &sync)?;
    let iterator = Value::Object(object);
    let next =
        crate::context::get_property(agent, &iterator, &JsString::from_utf8("next"), iterator)?;
    Ok(crate::expr::IteratorRecord { iterator, next })
}

/// GetAsyncIterator (spec 27.1.1.2): the async iterator, wrapping sync
/// iterators in an AsyncFromSyncIterator.
fn async_from_sync_or_async(
    agent: &mut Agent,
    value: &Value,
) -> Result<crate::expr::IteratorRecord, JsError> {
    let async_method = crate::expr::get_method(agent, value, "@@asyncIterator")?;
    if let Some(method) = async_method {
        let iterator = crate::function::call(agent, &method, *value, &[])?;
        let next =
            crate::context::get_property(agent, &iterator, &JsString::from_utf8("next"), iterator)?;
        if !is_callable(&next) {
            return Err(JsError::new(
                ErrorKind::TypeError,
                "Async iterator's next method is not callable".into(),
            ));
        }
        return Ok(crate::expr::IteratorRecord { iterator, next });
    }
    // Wrap the sync iterator.
    let sync = get_iterator(agent, value)?;
    let wrapped = crate::async_await::async_from_sync_iterator(agent, &sync)?;
    let next = crate::context::get_property(
        agent,
        &Value::Object(wrapped),
        &JsString::from_utf8("next"),
        Value::Object(wrapped),
    )?;
    Ok(crate::expr::IteratorRecord {
        iterator: Value::Object(wrapped),
        next,
    })
}

/// Rebuild a binding pattern from a destructuring assignment target.
fn pattern_of_target(target: &Expr) -> Result<BindingPattern, JsError> {
    match &target.kind {
        ExprKind::Object(literal) => {
            let mut properties = Vec::new();
            for prop in &literal.props {
                match prop {
                    ObjectProperty::Init { key, value, .. } => {
                        let element = binding_element_of_target(value)?;
                        properties.push(syntax::ast::ObjectBindingProperty::Property {
                            key: key.clone(),
                            element,
                            span: target.span,
                        });
                    }
                    ObjectProperty::Spread(expr) => {
                        let element = pattern_of_target(expr)?;
                        properties.push(syntax::ast::ObjectBindingProperty::Rest(BindingElement {
                            pattern: element,
                            init: None,
                            rest: true,
                            span: target.span,
                        }));
                    }
                    _ => {
                        return Err(JsError::new(
                            ErrorKind::SyntaxError,
                            "Invalid destructuring assignment target".into(),
                        ));
                    }
                }
            }
            Ok(BindingPattern::Object(properties))
        }
        ExprKind::Array(literal) => {
            let mut elements = Vec::new();
            for element in &literal.elements {
                match element {
                    ArrayElement::Hole => elements.push(syntax::ast::ArrayBindingElement::Hole),
                    ArrayElement::Expr(expr) => {
                        elements.push(syntax::ast::ArrayBindingElement::Element(
                            binding_element_of_target(expr)?,
                        ));
                    }
                    ArrayElement::Spread(expr) => {
                        let pattern = pattern_of_target(expr)?;
                        elements.push(syntax::ast::ArrayBindingElement::Rest(BindingElement {
                            pattern,
                            init: None,
                            rest: true,
                            span: target.span,
                        }));
                    }
                }
            }
            Ok(BindingPattern::Array(elements))
        }
        ExprKind::Ident(id) => {
            let name = crux::lookup(*id);
            let atom = crux::intern(name.as_slice());
            Ok(BindingPattern::Ident(atom))
        }
        ExprKind::Paren(inner) => pattern_of_target(inner),
        ExprKind::Member(member) => {
            // Member expressions are valid assignment targets too, but
            // destructuring a member target needs the reference machinery;
            // the tree-walker's binding_initialization with `None` handles
            // them via PutValue. Represent as an identifier-less pattern is
            // not possible; fall back to evaluating the pattern directly.
            let _ = member;
            Err(JsError::new(
                ErrorKind::SyntaxError,
                "Member destructuring assignment targets are not supported in resumable bodies"
                    .into(),
            ))
        }
        _ => Err(JsError::new(
            ErrorKind::SyntaxError,
            "Invalid destructuring assignment target".into(),
        )),
    }
}

/// A destructuring assignment element: an assignment expression `x = 1` is a
/// default initializer (spec 13.15.5: BindingInitialization of `x` with
/// default `1`), anything else is the plain target pattern.
fn binding_element_of_target(expr: &Expr) -> Result<BindingElement, JsError> {
    if let ExprKind::Assign {
        target,
        value,
        op: AssignOp::Assign,
    } = &expr.kind
    {
        Ok(BindingElement {
            pattern: pattern_of_target(target)?,
            init: Some((**value).clone()),
            rest: false,
            span: expr.span,
        })
    } else {
        Ok(BindingElement {
            pattern: pattern_of_target(expr)?,
            init: None,
            rest: false,
            span: expr.span,
        })
    }
}

// ---------------------------------------------------------------------------
// Suspension detection
// ---------------------------------------------------------------------------

/// Whether an expression contains a suspension point (`yield`/`await`) or a
/// construct the VM must linearize. Nested function/class bodies are separate
/// resumable units and never count.
pub fn expr_contains_suspension(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::Yield { .. } | ExprKind::Await(_) => true,
        ExprKind::Function(_) | ExprKind::Arrow { .. } => false,
        ExprKind::Class(class) => class_contains_suspension(class),
        ExprKind::Unary { operand, .. } => expr_contains_suspension(operand),
        ExprKind::Update { target, .. } => expr_contains_suspension(target),
        ExprKind::Binary { left, right, .. } => {
            expr_contains_suspension(left) || expr_contains_suspension(right)
        }
        ExprKind::Logical { left, right, .. } => {
            expr_contains_suspension(left) || expr_contains_suspension(right)
        }
        ExprKind::Assign { target, value, .. } => {
            expr_contains_suspension(target) || expr_contains_suspension(value)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            expr_contains_suspension(test)
                || expr_contains_suspension(consequent)
                || expr_contains_suspension(alternate)
        }
        ExprKind::PrivateIn { object, .. } => expr_contains_suspension(object),
        ExprKind::Call(call) => {
            expr_contains_suspension(&call.callee)
                || call.args.iter().any(|a| match a {
                    Argument::Expr(e) => expr_contains_suspension(e),
                    Argument::Spread(e) => expr_contains_suspension(e),
                })
        }
        ExprKind::New(new) => {
            expr_contains_suspension(&new.callee)
                || new.args.iter().any(|a| match a {
                    Argument::Expr(e) => expr_contains_suspension(e),
                    Argument::Spread(e) => expr_contains_suspension(e),
                })
        }
        ExprKind::Member(member) => {
            expr_contains_suspension(&member.object)
                || matches!(&member.property, MemberProperty::Computed(e) if expr_contains_suspension(e))
        }
        ExprKind::TaggedTemplate { tag, quasi } => {
            expr_contains_suspension(tag) || quasi.exprs.iter().any(expr_contains_suspension)
        }
        ExprKind::Template(template) => template.exprs.iter().any(expr_contains_suspension),
        ExprKind::Paren(inner) => expr_contains_suspension(inner),
        ExprKind::Sequence(exprs) => exprs.iter().any(expr_contains_suspension),
        ExprKind::Array(literal) => literal.elements.iter().any(|e| match e {
            ArrayElement::Expr(expr) => expr_contains_suspension(expr),
            ArrayElement::Spread(expr) => expr_contains_suspension(expr),
            ArrayElement::Hole => false,
        }),
        ExprKind::Object(literal) => literal.props.iter().any(object_prop_contains_suspension),
        ExprKind::ImportCall { .. } => true,
        ExprKind::MetaProperty { .. } => true,
        _ => false,
    }
}

/// Whether a class definition's heritage or a computed element name contains a
/// suspension point. Field initializer values run at construction (not class
/// definition) and do not count; element bodies are separate resumable units.
fn class_contains_suspension(class: &Class) -> bool {
    class
        .heritage
        .as_ref()
        .is_some_and(expr_contains_suspension)
        || class
            .elements
            .iter()
            .any(class_element_name_contains_suspension)
}

fn class_element_name_contains_suspension(element: &ClassElement) -> bool {
    let name = match element {
        ClassElement::Method { name, .. }
        | ClassElement::Get { name, .. }
        | ClassElement::Set { name, .. }
        | ClassElement::Field { name, .. } => name,
        ClassElement::StaticBlock(_) => return false,
    };
    matches!(
        name,
        ClassElementName::Property(PropertyName::Computed(expr)) if expr_contains_suspension(expr)
    )
}

/// The computed public name expression of a class element, if any.
fn computed_public_name(element: &ClassElement) -> Option<&Expr> {
    let name = match element {
        ClassElement::Method { name, .. }
        | ClassElement::Get { name, .. }
        | ClassElement::Set { name, .. }
        | ClassElement::Field { name, .. } => name,
        ClassElement::StaticBlock(_) => return None,
    };
    match name {
        ClassElementName::Property(PropertyName::Computed(expr)) => Some(expr),
        _ => None,
    }
}

pub(crate) fn has_computed_public_name(element: &ClassElement) -> bool {
    computed_public_name(element).is_some()
}

fn object_prop_contains_suspension(prop: &ObjectProperty) -> bool {
    match prop {
        ObjectProperty::Init { key, value, .. } => {
            property_name_contains_suspension(key) || expr_contains_suspension(value)
        }
        ObjectProperty::Method { key, .. } => property_name_contains_suspension(key),
        ObjectProperty::Get { key, body } | ObjectProperty::Set { key, body, .. } => {
            property_name_contains_suspension(key)
                || body.stmts.iter().any(stmt_contains_suspension)
        }
        ObjectProperty::Spread(expr) => expr_contains_suspension(expr),
    }
}

fn property_name_contains_suspension(key: &PropertyName) -> bool {
    match key {
        PropertyName::Computed(expr) => expr_contains_suspension(expr),
        _ => false,
    }
}

/// Whether a statement contains a suspension point anywhere in its subtree.
pub fn stmt_contains_suspension(stmt: &Stmt) -> bool {
    match &stmt.kind {
        StmtKind::Block(block) => block.stmts.iter().any(stmt_contains_suspension),
        StmtKind::Expr(expr) | StmtKind::Throw(expr) => expr_contains_suspension(expr),
        StmtKind::Return(Some(expr)) => expr_contains_suspension(expr),
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            expr_contains_suspension(test)
                || stmt_contains_suspension(consequent)
                || alternate.as_deref().is_some_and(stmt_contains_suspension)
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            expr_contains_suspension(test) || stmt_contains_suspension(body)
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            init.as_ref().is_some_and(for_init_contains_suspension)
                || test.as_ref().is_some_and(expr_contains_suspension)
                || update.as_ref().is_some_and(expr_contains_suspension)
                || stmt_contains_suspension(body)
        }
        StmtKind::ForIn { left, right, body } => {
            for_binding_contains_suspension(left)
                || expr_contains_suspension(right)
                || stmt_contains_suspension(body)
        }
        StmtKind::ForOf {
            left,
            right,
            body,
            is_await,
        } => {
            *is_await
                || for_binding_contains_suspension(left)
                || expr_contains_suspension(right)
                || stmt_contains_suspension(body)
        }
        StmtKind::Labeled { body, .. } => stmt_contains_suspension(body),
        StmtKind::Switch {
            discriminant,
            cases,
        } => {
            expr_contains_suspension(discriminant)
                || cases.iter().any(|c| {
                    c.test.as_ref().is_some_and(expr_contains_suspension)
                        || c.consequent.iter().any(stmt_contains_suspension)
                })
        }
        StmtKind::Try {
            block,
            handler,
            finalizer,
        } => {
            block.stmts.iter().any(stmt_contains_suspension)
                || handler
                    .as_ref()
                    .is_some_and(|h| h.body.stmts.iter().any(stmt_contains_suspension))
                || finalizer
                    .as_ref()
                    .is_some_and(|f| f.stmts.iter().any(stmt_contains_suspension))
        }
        StmtKind::ClassDecl(class) => class_contains_suspension(class),
        StmtKind::VarDecl { decls, .. } => decls
            .iter()
            .any(|d| binding_pattern_contains_suspension_any(&d.pattern, d.init.as_ref())),
        // An `await using` statement always implies an await (even with a
        // null initializer, spec 9.4.4), and its scope's async disposal must
        // suspend: compile it (and any enclosing scope) instead of batching
        // it to the tree walker.
        StmtKind::UsingDecl { is_await: true, .. } => true,
        StmtKind::UsingDecl { decls, .. } => decls
            .iter()
            .any(|d| binding_pattern_contains_suspension_any(&d.pattern, d.init.as_ref())),
        StmtKind::With { object, body } => {
            expr_contains_suspension(object) || stmt_contains_suspension(body)
        }
        _ => false,
    }
}

/// A statement whose control flow never leaves its enclosing statement
/// list (no `break`/`continue`/`return`/`throw`; suspension is checked by
/// the caller). Nested loops/labels/switches keep their transfers inside
/// themselves, and nested function/class declarations are separate
/// execution contexts, so only statements whose bodies can exit the list
/// stop the walk.
fn stmt_has_no_outgoing_transfer(stmt: &Stmt) -> bool {
    match &stmt.kind {
        StmtKind::Break(_) | StmtKind::Continue(_) | StmtKind::Return(_) | StmtKind::Throw(_) => {
            false
        }
        StmtKind::Block(block) => block.stmts.iter().all(stmt_has_no_outgoing_transfer),
        StmtKind::If {
            consequent,
            alternate,
            ..
        } => {
            stmt_has_no_outgoing_transfer(consequent)
                && alternate
                    .as_deref()
                    .is_none_or(stmt_has_no_outgoing_transfer)
        }
        StmtKind::Labeled { body, .. } => stmt_has_no_outgoing_transfer(body),
        StmtKind::While { body, .. } | StmtKind::DoWhile { body, .. } => {
            stmt_has_no_outgoing_transfer(body)
        }
        StmtKind::For { body, .. }
        | StmtKind::ForIn { body, .. }
        | StmtKind::ForOf { body, .. } => stmt_has_no_outgoing_transfer(body),
        StmtKind::Switch { cases, .. } => cases
            .iter()
            .all(|case| case.consequent.iter().all(stmt_has_no_outgoing_transfer)),
        // A try/catch/finally redirects transfers through its own machinery
        // and `with` hosts arbitrary nested scopes — neither is a hot
        // straight-line loop body, so keep the wrapper.
        StmtKind::Try { .. } | StmtKind::With { .. } => false,
        // Empty/expression/declaration statements and nested function/class
        // declarations cannot transfer out of the list.
        _ => true,
    }
}

fn for_init_contains_suspension(init: &ForInit) -> bool {
    match init {
        ForInit::Expr(expr) => expr_contains_suspension(expr),
        ForInit::VarDecl { decls, .. } => decls
            .iter()
            .any(|d| d.init.as_ref().is_some_and(expr_contains_suspension)),
    }
}

/// Whether an expression contains a `?.` link anywhere: a short-circuit then
/// propagates through the whole chain, so compiled member/call steps after
/// the link must be guarded (spec 13.4.3).
fn expr_may_short_circuit(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::Member(member) => member.optional || expr_may_short_circuit(&member.object),
        ExprKind::Call(call) => call.optional || expr_may_short_circuit(&call.callee),
        // Parentheses terminate an optional chain (spec 13.4.3): a member
        // access or call on a parenthesized value always runs, even when the
        // chain inside the parens short-circuited — `(a?.b).c` reads `.c` of
        // the chain result (throwing on nullish), it does not short-circuit.
        ExprKind::Paren(_) => false,
        ExprKind::New(new) => expr_may_short_circuit(&new.callee),
        ExprKind::TaggedTemplate { tag, .. } => expr_may_short_circuit(tag),
        _ => false,
    }
}

fn for_binding_contains_suspension(binding: &ForBinding) -> bool {
    match binding {
        ForBinding::Expr(expr) => expr_contains_suspension(expr),
        ForBinding::VarDecl { init, .. } => init.as_ref().is_some_and(expr_contains_suspension),
    }
}

// ---------------------------------------------------------------------------
// Compiler
// ---------------------------------------------------------------------------

#[derive(Debug)]
enum Fixup {
    Jump(usize, usize),
    JumpIfFalse(usize, usize),
    JumpIfTrue(usize, usize),
    JumpIfFalseKeep(usize, usize),
    JumpIfTrueKeep(usize, usize),
    JumpIfNullishKeep(usize, usize),
    JumpIfNotNullishKeep(usize, usize),
    /// The for-of loop's `(top, end)` step span, carried on `ForOfBegin` so a
    /// `break`/`continue` whose target lies outside the loop (the transfer
    /// leaves it, skipping the compiled `ForOfClose`) closes its iterator.
    ForOfBoundary(usize, usize, usize),
    AsyncForOfBoundary(usize, usize, usize),
    /// The fused relational-imm loop test (Cut 4): the step's `target` is
    /// resolved at compile end; op/slot/imm were fixed at emission.
    JumpIfRelImm {
        index: usize,
        label: usize,
        op: BinaryOp,
        slot: usize,
        imm: f64,
    },
    /// The fused strict-equality-imm branch: the step's `target` resolves
    /// at compile end; `neq` (the source `!==` form) picks the variant.
    JumpIfStrictEqImm {
        index: usize,
        label: usize,
        neq: bool,
        slot: usize,
        imm: f64,
    },
    /// The fused relational-imm loop test on a declared top-level var (the
    /// fast-script variant of `JumpIfRelImm`).
    JumpIfRelGlobalImm {
        index: usize,
        label: usize,
        op: BinaryOp,
        name: crux::AtomId,
        imm: f64,
    },
    /// The fused relational loop test with a fast-binding limit
    /// (`Step::JumpIfRelLimit`): the step's `target` resolves at compile end;
    /// op/slot/limit were fixed at emission.
    JumpIfRelLimit {
        index: usize,
        label: usize,
    },
    /// The fused canonical loop head's jump targets (Cut 15): both labels
    /// resolve at compile end like the jump fixups.
    FastLoopHead(usize, usize, usize),
    /// The hoisted-loop guard (`Step::TypedArrayLengthHoist`): the step's
    /// `target` resolves at compile end (the general per-iteration loop's
    /// entry).
    TypedArrayLengthHoist {
        index: usize,
        label: usize,
    },
    Break(usize, usize),
    Continue(usize, usize),
    JumpIfChainShort(usize, usize),
    Exit(usize, usize),
    ForInNext(usize, usize),
    ForOfNext(usize, usize),
    ForOfNextBindLocal(usize, usize),
    DestructureUndef(usize, usize),
    AsyncForOfNext(usize, usize),
    SwitchTest(usize, usize),
    YieldStarNext(usize, usize),
    YieldStarResume(usize, usize, usize, usize),
    AsyncYieldStarNext(usize, usize),
    AsyncYieldStarInspect(usize, usize),
    AsyncYieldStarResume(usize, usize, usize, usize),
}

/// Cut 50/M2: the largest plain-argument count compiled as the fast
/// `CallFast`/`TailCallFast` form (`[this, callee, a1..aN]` on the stack,
/// no argument-vector machinery). More arguments — or any spread — take the
/// vector form (`ArgsBase`/`ArgsPush`/`ArgsSpread` + the vector
/// `Call`/`TailCall`). The `argc` field is `u8`, and the JIT's in-frame leaf
/// probe handles any count that fits the working buffer; the two `[Value;
/// FAST_CALL_MAX_ARGS]` stack buffers (`do_call_apply`, `run_inline_leaf`)
/// grow with it, so the cap is a stack-size tradeoff. 64 was measured
/// (gap-close M2, 2026-09-02): the 33-arg wide call at the fast form runs
/// ~29x faster in the JIT and ~1.9x faster interpreted than the vector form
/// (jit 1ms vs 29ms, interp 22ms vs 42ms per 200K — the vector form's
/// `ArgsBase`/`ArgsPush` per-arg protocol and the `split_off` rebuild were
/// the cost). 65+ plain args still take the vector form.
const FAST_CALL_MAX_ARGS: usize = 64;

#[derive(Debug)]
enum Scope {
    Loop {
        break_target: usize,
        break_count: usize,
        continue_target: usize,
        continue_count: usize,
    },
    Switch {
        break_target: usize,
        break_count: usize,
    },
    Label {
        name: crux::AtomId,
        break_target: usize,
        break_count: usize,
        continue_target: Option<(usize, usize)>,
    },
    Iteration {
        open: usize,
        closed: usize,
        continue_target: usize,
        break_target: usize,
    },
}

#[derive(Default)]
struct Compiler {
    steps: Vec<Step>,
    handlers: Vec<Handler>,
    labels: HashMap<usize, usize>,
    fixups: Vec<Fixup>,
    scope_stack: Vec<Scope>,
    scope_count: usize,
    next_label: usize,
    /// Whether the enclosing function is an async generator: `yield*` then
    /// delegates through the async-iterator protocol with awaited results.
    is_async_generator: bool,
    /// The nesting depth of optional chains being compiled: the outermost
    /// chain node clears the runtime short-circuit flag when it finishes.
    chain_depth: usize,
    /// The nesting depth of `with` statements being compiled: a plain
    /// identifier callee inside one must derive its call `this` from the
    /// resolved reference (the with base object), not `undefined` (spec
    /// 13.4.3 step 4.b).
    with_depth: usize,
    /// The body's strictness: function expressions/arrows created by the
    /// body inherit it as their enclosing strictness (and a class subtree
    /// forces strict — `class_depth`).
    strict: bool,
    /// The nesting depth of class definitions being compiled: every part of
    /// a class is strict mode code (spec 15.2.1), so function expressions in
    /// a heritage or computed-key expression are strict even in a sloppy
    /// script.
    class_depth: usize,
    /// The inferred name of an anonymous class expression being compiled as
    /// an assignment/declaration initializer: threaded into the class
    /// definition so static field initializers see the final name (spec
    /// 15.7.14 step 8 with NamedEvaluation). Consumed by `compile_class`.
    pending_class_name: Option<crux::AtomId>,
    /// The fast-path frame layout (Cut 3): when `Some`, the body's binding
    /// names resolve to frame slots (`LoadLocal`/`StoreLocal`) and blocks
    /// with no lexical declarations skip their environment. `None` compiles
    /// through the environment machinery.
    scope: Option<ScopeInfo>,
    /// The certified top-level fast path (script-level bindings): the
    /// declared `var`/function names read and written directly on the
    /// global object (`LoadGlobal`/`StoreGlobal`), skipping the env-chain
    /// walk. `None` (and `ScopeInfo` above) means the environment path.
    script_globals: Option<HashSet<String>>,
    /// The certified script's assigned names (Cut 35 slice 4): the
    /// `CallFastGlobal` fuse requires the callee to be never-assigned (its
    /// global binding is then stable for the whole script — reading it
    /// after the args matches reading it before). Collected with function
    /// bodies, so an uncertified function's write to a declared name counts.
    /// `None` outside the certified-script path (the fuse never fires).
    script_assigned: Option<HashSet<crux::AtomId>>,
    /// The fused canonical loop's counter name (Cut 17): while compiling the
    /// body of an accumulator loop, the name resolves to `BindingLoc::Acc`,
    /// so its reads/assignments/updates touch `Vm::acc` instead of the
    /// slot/global (the body scan guarantees only those shapes occur).
    /// `None` when no accumulator loop is open; nested canonical loops skip
    /// the accumulator (one shared `Vm::acc`).
    acc_binding: Option<crux::AtomId>,
    /// The captured for-head names of the per-iteration loops currently
    /// being compiled (Cut 3 continuation), innermost last: while a loop
    /// body compiles, its captured head bindings resolve to per-iteration
    /// env steps (`LoadPerIteration` etc.) instead of the capture-context
    /// steps — the head inits compile before the entry step, so they keep
    /// the context-slot path.
    per_iteration_heads: Vec<Vec<crux::AtomId>>,
    /// The `ScopeInfo::annex_b` indices of the Annex B block functions whose
    /// blocks are currently being compiled (Cut 6 first slice), innermost
    /// last: while compiling inside a declaring block, a reference to the
    /// name resolves to the block binding's slot instead of the var slot.
    annex_b_stack: Vec<Vec<usize>>,
    /// The enclosing certified bodies' capture-context layouts (Cut 3
    /// continuation, nested context chains), innermost first: a reference to
    /// one of their captured names resolves to a static context-chain read
    /// (`LoadContextSlot { depth ≥ 1 }`) instead of the env walk. Empty when
    /// the enclosing chain is uncertified.
    outer_chain: Vec<Vec<crux::AtomId>>,
    /// Cut 28: the inherited per-iteration head layouts — `(head names, env
    /// hop offset)` — of the certified loops open when THIS body was created
    /// (see
    /// [`crate::function::EcmaFunction::per_iteration_chain`]). A reference
    /// to one of those heads compiles to a static `LoadPerIteration` read
    /// against the body's own `lexical_env` instead of an env walk.
    per_iteration_chain: Vec<(Vec<crux::AtomId>, usize)>,
    /// Whether any emitted step switches the lexical environment (block/
    /// loop/catch/with envs): when false the body's env is constant for its
    /// whole run, so the dispatch loop skips the per-step context sync.
    env_changing: bool,
    /// Cut 34: whether the expression being compiled is a statement-position
    /// expression (its value is the statement completion). A fast-binding
    /// assignment at the top expression depth (`expr_depth == 1`) then
    /// stores AND sets the completion in one step (`FusedStore*`), skipping
    /// the result `Dup` + `SetCompletion`; `fused_completion` records that
    /// the statement's completion was already set.
    statement_expr: bool,
    fused_completion: bool,
    /// Cut 34: the `compile_expr` nesting depth, so `statement_expr` reaches
    /// only the statement's own assignment, not a nested one in an operand.
    expr_depth: usize,
    /// The nesting depth of try/catch/finally bodies being compiled: a return
    /// inside one cannot be a proper tail call (the finally must still run
    /// after the call returns).
    try_depth: usize,
    /// The `try_depth` at which the currently-compiled clause is tail-safe:
    /// the innermost try's catch (when it has no finally) or its finally.
    /// `0` outside such a clause. A return is tail-eligible only when
    /// `tail_safe_depth == try_depth <= 1` (the innermost try's own clause,
    /// with no enclosing trys — an outer catch could catch a throw from the
    /// callee, and an outer finally must run after the call).
    tail_safe_depth: usize,
    /// Whether the expression currently being compiled is in tail position —
    /// its value is directly the return statement's argument: a call compiled
    /// in tail position emits a frame-replacing tail call.
    tail: bool,
    /// Whether the body contains a `using` declaration: a tail call would
    /// skip the body env's disposal on the way out, so such bodies never
    /// compile tail calls (conservative — the corpus has no `using` + tail
    /// shape, and correctness wins).
    has_using: bool,
    /// Cut 46: the enclosing function's own name, when it has one. A tail
    /// call whose callee identifier matches it — in a NAMED FUNCTION
    /// EXPRESSION body — is the immutable self-binding (the running body
    /// itself), compiled as an in-place frame rebind + jump.
    function_name: Option<crux::AtomId>,
    /// Cut 46: whether the body belongs to a named function EXPRESSION (its
    /// name is bound by the immutable self-binding scope) rather than a
    /// function declaration or anonymous expression. See
    /// [`crate::function::EcmaFunction::named_expression`].
    named_expression: bool,
    /// Cut 35 slice 30: property names written to `this` in a certified
    /// constructor body (only tracked when the body uses lexical `this` /
    /// is a constructor — detected by `this_slot.is_some()` in scope).
    /// Populated during compilation and returned alongside the compiled
    /// body for store-cache pre-warming in `construct_this_object`.
    this_writes: (usize, [crux::AtomId; 4]),
    /// Gap-close M6 slice 2: while the fallback copy of a hoisted
    /// `for (…; K <op> RECV.length; …)` loop is being compiled, its own test
    /// (the original eligible member shape) must not re-hoist. Nested loops
    /// inside that copy are also suppressed, which is merely conservative.
    hoist_suppressed: bool,
    /// Gap-close M6 slice 3: while the FAST copy of a hoisted
    /// `for (…; K <op> RECV.length; …)` loop is being compiled — `(recv_slot,
    /// hoist_slot)` — the receiver slot the guard probed and the hidden slot
    /// holding the hoisted length. Body reads of `RECV.length` then lower to
    /// a plain `LoadLocal` of the hidden slot (the probe hit + the body
    /// purity make the length loop-invariant). `None` on the guard-miss
    /// fallback copy, whose hidden slot was never initialized.
    hoisted_length: Option<(usize, usize)>,
}

/// Where a binding lives for emission purposes: a frame slot (fast body),
/// the capture context (a binding a closure in the body captures, Cut 3
/// continuation), a declared top-level var (fast script), the fused loop
/// counter in the VM accumulator (Cut 17), or the environment machinery.
/// A `Context` carries the static context-chain depth (0 = the body's own
/// capture context; a nested closure body resolving an enclosing body's
/// captured binding has depth ≥ 1).
#[derive(Debug, Clone, Copy, PartialEq)]
enum BindingLoc {
    Slot(usize),
    Context(usize, usize),
    /// Cut 28: a captured per-iteration head of an enclosing certified
    /// loop — `(depth, index)` into the closure's own captured per-iteration
    /// env chain (see `Compiler::captured_per_iteration`). Emits the
    /// per-iteration steps against the closure's `lexical_env`.
    CapturedIteration(usize, usize),
    Global,
    Acc,
    Env,
}

impl Compiler {
    /// The frame slot of a binding under this body's fast-path analysis.
    fn slot_of(&self, name: crux::AtomId) -> Option<usize> {
        self.scope.as_ref().and_then(|scope| scope.slot_of(name))
    }

    /// Where a binding resolves: the frame (fast body), the capture context
    /// (Cut 3 continuation — own context at depth 0, an enclosing certified
    /// body's context at depth ≥ 1), a captured per-iteration head of an
    /// enclosing certified loop (Cut 28), the global object (certified fast
    /// script), the fused loop counter in the accumulator (Cut 17), or the
    /// environment machinery.
    fn binding(&self, name: crux::AtomId) -> BindingLoc {
        if self.acc_binding == Some(name) {
            BindingLoc::Acc
        } else if let Some(block_slot) = self.annex_b_block_slot(name) {
            // Cut 6 first slice: inside a declaring block, an Annex B
            // block function's name resolves to the block binding — the
            // var binding is the function-scoped fallback outside.
            BindingLoc::Slot(block_slot)
        } else if let Some(index) = self.scope.as_ref().and_then(|scope| scope.context_of(name)) {
            BindingLoc::Context(0, index)
        } else if let Some(slot) = self.slot_of(name) {
            BindingLoc::Slot(slot)
        } else if self
            .script_globals
            .as_ref()
            .is_some_and(|globals| globals.contains(&crux::lookup(name).to_string_lossy()))
        {
            BindingLoc::Global
        } else if let Some((depth, index)) = self.captured_per_iteration(name) {
            // Cut 28: a captured per-iteration head — checked before the
            // context chain (the head names are stripped from the enclosing
            // entries).
            BindingLoc::CapturedIteration(depth, index)
        } else if let Some((depth, index)) = self.outer_context(name) {
            BindingLoc::Context(depth, index)
        } else {
            BindingLoc::Env
        }
    }

    /// Cut 28: the static read/write location of a captured per-iteration
    /// head (a binding of a certified `for (let i...)` loop that was open
    /// when this body was created): `(depth, index)` — `depth` = the
    /// closure's own capture-context hop (its `body_context` wraps its
    /// [[Environment]] when it has captures) plus the chain entry's recorded
    /// env hop offset; `index` = the head's position in that loop's
    /// per-iteration env layout. `None` falls back to the env walk.
    fn captured_per_iteration(&self, name: crux::AtomId) -> Option<(usize, usize)> {
        let base = usize::from(
            self.scope
                .as_ref()
                .is_some_and(|scope| !scope.context_names.is_empty()),
        );
        for (heads, depth) in &self.per_iteration_chain {
            if let Some(index) = heads.iter().position(|head| *head == name) {
                return Some((base + depth, index));
            }
        }
        None
    }

    /// Cut 28: the per-iteration chain to record on a closure created here —
    /// this body's open per-iteration loops (innermost first, each one env
    /// hop past the closure's [[Environment]]), then the inherited chain
    /// shifted by this body's own capture-context hop (a closure created in
    /// this body captures its running env — the capture context when it has
    /// one).
    fn closure_per_iteration_chain(&self) -> Vec<(Vec<crux::AtomId>, usize)> {
        let mut chain =
            Vec::with_capacity(self.per_iteration_heads.len() + self.per_iteration_chain.len());
        for (position, heads) in self.per_iteration_heads.iter().enumerate() {
            chain.push((heads.clone(), position));
        }
        let hop = usize::from(
            self.scope
                .as_ref()
                .is_some_and(|scope| !scope.context_names.is_empty()),
        );
        for (heads, depth) in &self.per_iteration_chain {
            chain.push((heads.clone(), depth + hop));
        }
        chain
    }

    /// The block binding of an Annex B block function whose declaring block
    /// is open (Cut 6 first slice): the innermost enclosing block that
    /// declares the name wins.
    fn annex_b_block_slot(&self, name: crux::AtomId) -> Option<usize> {
        let scope = self.scope.as_ref()?;
        self.annex_b_stack
            .iter()
            .rev()
            .flat_map(|indices| indices.iter().rev().copied())
            .map(|index| &scope.annex_b[index])
            .find(|entry| entry.name == name)
            .map(|entry| entry.block_slot)
    }

    /// The `ScopeInfo::annex_b` indices of the Annex B block functions
    /// declared directly in `stmts` (Cut 6 first slice): the block-entry
    /// init steps and the compile-time reference stack use them.
    fn annex_b_block_entries(&self, stmts: &[Stmt]) -> Vec<usize> {
        let Some(scope) = self.scope.as_ref() else {
            return Vec::new();
        };
        scope
            .annex_b
            .iter()
            .enumerate()
            .filter_map(|(index, entry)| {
                stmts
                    .iter()
                    .any(|stmt| {
                        matches!(&stmt.kind, StmtKind::FunctionDecl(f) if f.span == entry.span)
                    })
                    .then_some(index)
            })
            .collect()
    }

    /// The Annex B hoist copy of the given declaration statement (Cut 6
    /// first slice): `(block_slot, var_slot)` when the statement is a live
    /// hoisted block function of the innermost open block — the statement
    /// copies the block binding into the var binding (B.3.3.3). `None` for
    /// a top-level declaration, a dead block duplicate, or a non-hoisted
    /// block declaration (all empty statements).
    fn annex_b_copy_target(&self, function: &syntax::ast::Function) -> Option<(usize, usize)> {
        let scope = self.scope.as_ref()?;
        let index = self.annex_b_stack.last()?.iter().copied().find(|&index| {
            let entry = &scope.annex_b[index];
            entry.span == function.span && entry.var_slot.is_some()
        })?;
        let entry = &scope.annex_b[index];
        Some((entry.block_slot, entry.var_slot?))
    }

    /// The hoisted Annex B statement-position declaration matching the
    /// given statement (Cut 6 continuation), when the body certified one
    /// for it.
    fn statement_fn(&self, function: &syntax::ast::Function) -> Option<&AnnexBStatementFn> {
        let scope = self.scope.as_ref()?;
        scope
            .statement_fns
            .iter()
            .find(|entry| entry.span == function.span)
    }

    /// The enclosing certified bodies' capture-context layouts (Cut 3
    /// continuation, nested context chains): entry `k` holds the captured
    /// names of the certified body `k` scopes out (0 = the immediately
    /// enclosing one), with the per-iteration head names that were open at
    /// each body's own creation site excluded. Threaded through the closure
    /// creation steps from the enclosing compilers; empty when the enclosing
    /// chain is not certified.
    fn outer_context(&self, name: crux::AtomId) -> Option<(usize, usize)> {
        let scope = self.scope.as_ref()?;
        // The walk base is the closure's own capture context (1 hop) when
        // the body has one; the per-iteration envs on the chain are skipped
        // at runtime, so each enclosing body contributes exactly one hop.
        let base = usize::from(!scope.context_names.is_empty());
        for (depth, names) in self.outer_chain.iter().enumerate() {
            if let Some(index) = names.iter().position(|n| *n == name) {
                return Some((base + depth, index));
            }
        }
        None
    }

    /// The entry this certified body contributes to a closure created here:
    /// its captured names minus the per-iteration head names whose loops are
    /// open at the creation site (those resolve through the per-iteration
    /// env, not the capture context's stale slot).
    fn own_context_entry(&self) -> Vec<crux::AtomId> {
        let Some(scope) = self.scope.as_ref() else {
            return Vec::new();
        };
        let mut names = scope.context_names.clone();
        for heads in &self.per_iteration_heads {
            for head in heads {
                names.retain(|name| *name != *head);
            }
        }
        names
    }

    /// The context chain to record on a closure created here: this body's
    /// own entry first (the innermost enclosing context), then the inherited
    /// enclosing certified bodies' entries. A body with an empty capture
    /// context contributes no runtime hop, so its entry is omitted — or
    /// empty entirely when this body is uncertified (the chain is broken,
    /// references resolve through the env walk).
    fn closure_outer_chain(&self) -> Vec<Vec<crux::AtomId>> {
        let Some(scope) = self.scope.as_ref() else {
            return Vec::new();
        };
        let mut chain = Vec::with_capacity(self.outer_chain.len() + 1);
        if !scope.context_names.is_empty() {
            chain.push(self.own_context_entry());
        }
        chain.extend(self.outer_chain.iter().cloned());
        chain
    }

    /// The per-iteration env slot of a captured for-head binding (Cut 3
    /// continuation): `(depth, index)` — walk `depth` outers from the
    /// current per-iteration env (0 = this loop's env), then read slot
    /// `index` in that env's head-name layout. `None` outside a per-iteration
    /// loop body (the head inits compile before the first env exists and
    /// keep the capture-context path).
    fn per_iteration(&self, name: crux::AtomId) -> Option<(usize, usize)> {
        let total = self.per_iteration_heads.len();
        for (position, heads) in self.per_iteration_heads.iter().enumerate().rev() {
            if let Some(index) = heads.iter().position(|head| *head == name) {
                return Some((total - 1 - position, index));
            }
        }
        None
    }

    /// Prepare to evaluate an initializer that may be an anonymous class
    /// expression: record the inferred binding name so the class definition
    /// names itself before its static field initializers run (spec 15.7.14
    /// step 8 with NamedEvaluation).
    fn begin_named_initializer(&mut self, name: crux::AtomId, init: &Expr) {
        if let ExprKind::Class(class) = &init.kind
            && class.name.is_none()
        {
            self.pending_class_name = Some(name);
        }
    }

    /// Emit the load for a fast binding: a frame slot read, a capture-
    /// context read, a direct global-object read, or the fused loop counter
    /// (all are guaranteed to resolve).
    fn emit_load(&mut self, loc: BindingLoc, name: crux::AtomId) {
        match loc {
            BindingLoc::Slot(slot) => self.emit(Step::LoadLocal { slot }),
            // Cut 3 continuation: a captured for-head binding reads the
            // current per-iteration env (a fresh copy per iteration) — a
            // closure in the body observes the per-iteration value, not the
            // capture context's. Other captured bindings (own or an
            // enclosing body's) read the static context chain.
            BindingLoc::Context(depth, index) => {
                if depth == 0
                    && let Some((depth, index)) = self.per_iteration(name)
                {
                    self.emit(Step::LoadPerIteration { depth, index });
                } else {
                    self.emit(Step::LoadContextSlot { depth, index });
                }
            }
            BindingLoc::Global => self.emit(Step::LoadGlobal { name }),
            BindingLoc::Acc => self.emit(Step::PushAcc),
            // Cut 28: a captured per-iteration head reads the closure's own
            // captured per-iteration env (its `lexical_env` at run time).
            BindingLoc::CapturedIteration(depth, index) => {
                self.emit(Step::LoadPerIteration { depth, index })
            }
            BindingLoc::Env => unreachable!("emit_load on the environment path"),
        }
    }

    /// Cut 34: the store for a statement-position assignment — a fast
    /// frame-slot/global target at the top expression depth fuses the store
    /// and the statement-completion write (`FusedStore*`), skipping the
    /// result `Dup` that `SetCompletion` would otherwise pop. Context/acc
    /// targets and nested assignments fall back to the dup-store.
    fn emit_statement_store(&mut self, loc: BindingLoc, name: crux::AtomId) {
        if self.statement_expr && self.expr_depth == 1 {
            match loc {
                BindingLoc::Slot(store_slot) => {
                    // Cut 35 slice 17: `x = f(args)` where the tail is the
                    // args' `LoadLocal`s + a `CallFastSlot` fuses the arg
                    // loads, the call, and the store into one step. The
                    // pattern only matches an actual `CallFastSlot`
                    // emission (its guards already passed) with plain slot
                    // args, so the semantics are unchanged.
                    let fused = if let Some(Step::CallFastGlobal {
                        name,
                        argc,
                        direct_eval: false,
                    }) = self.steps.last()
                        && let argc = *argc as usize
                        && self.steps.len() > argc
                        && (0..argc).all(|i| {
                            matches!(self.steps[self.steps.len() - 2 - i], Step::LoadLocal { .. })
                        }) {
                        // Cut 35 slice 20: the global-callee variant of the
                        // slot-callee fusion above (a global function
                        // declaration's call site, the calls bench shape).
                        let arg_slots = (0..argc)
                            .rev()
                            .map(|i| {
                                let Step::LoadLocal { slot } = self.steps[self.steps.len() - 2 - i]
                                else {
                                    unreachable!("checked above")
                                };
                                slot
                            })
                            .collect();
                        let name = *name;
                        self.steps.truncate(self.steps.len() - argc - 1);
                        self.emit(Step::CallFastGlobalStore {
                            name,
                            arg_slots,
                            store_slot,
                        });
                        self.fused_completion = true;
                        true
                    } else if let Some(Step::CallFastSlot { slot, argc }) = self.steps.last()
                        && let argc = *argc as usize
                        && self.steps.len() > argc
                        && (0..argc).all(|i| {
                            matches!(self.steps[self.steps.len() - 2 - i], Step::LoadLocal { .. })
                        })
                    {
                        let callee_slot = *slot;
                        // The arg slots in compile order (the last-pushed
                        // arg sits directly before the call).
                        let arg_slots = (0..argc)
                            .rev()
                            .map(|i| {
                                let Step::LoadLocal { slot } = self.steps[self.steps.len() - 2 - i]
                                else {
                                    unreachable!("checked above")
                                };
                                slot
                            })
                            .collect();
                        self.steps.truncate(self.steps.len() - argc - 1);
                        self.emit(Step::CallFastSlotStore {
                            callee_slot,
                            arg_slots,
                            store_slot,
                        });
                        self.fused_completion = true;
                        true
                    } else {
                        false
                    };
                    if !fused {
                        self.emit(Step::FusedStoreLocal { slot: store_slot });
                        self.fused_completion = true;
                    }
                }
                BindingLoc::Global => {
                    self.emit(Step::FusedStoreGlobal { name });
                    self.fused_completion = true;
                }
                _ => self.emit_dup_store(loc, name),
            }
        } else {
            self.emit_dup_store(loc, name);
        }
    }

    /// Emit `Dup; Store` for a fast binding, leaving the assigned value as
    /// the expression result (the store itself pops the duplicate).
    fn emit_dup_store(&mut self, loc: BindingLoc, name: crux::AtomId) {
        self.emit(Step::Dup);
        match loc {
            BindingLoc::Slot(slot) => self.emit(Step::StoreLocal { slot }),
            BindingLoc::Context(depth, index) => {
                if depth == 0
                    && let Some((depth, index)) = self.per_iteration(name)
                {
                    self.emit(Step::StorePerIteration { depth, index });
                } else {
                    self.emit(Step::StoreContextSlot { depth, index });
                }
            }
            BindingLoc::Global => self.emit(Step::StoreGlobal { name }),
            BindingLoc::Acc => self.emit(Step::PopAcc),
            BindingLoc::CapturedIteration(depth, index) => {
                self.emit(Step::StorePerIteration { depth, index })
            }
            BindingLoc::Env => unreachable!("emit_dup_store on the environment path"),
        }
    }

    /// The flat slot write for a certified destructuring element (Cut 59):
    /// the value on top of the stack initializes the declaration's binding
    /// (a frame slot or capture-context slot — the certified scan allocated
    /// every pattern name). The env fallback keeps the wholesale
    /// `DeclInit`/`Destructure` (correct, but it bails the body at JIT time).
    fn emit_certified_bind(&mut self, pattern: &BindingPattern, lexical: bool) {
        let BindingPattern::Ident(name) = pattern else {
            unreachable!("emit_certified_bind binds an identifier element")
        };
        match self.binding(*name) {
            BindingLoc::Slot(slot) => self.emit(Step::InitLocal { slot }),
            BindingLoc::Context(0, index) => self.emit(Step::InitContextSlot { index }),
            BindingLoc::Global => self.emit(Step::StoreGlobal { name: *name }),
            _ => {
                self.emit(if lexical {
                    Step::DeclInit {
                        pattern: pattern.clone(),
                    }
                } else {
                    Step::Destructure {
                        pattern: pattern.clone(),
                    }
                });
                self.emit(Step::Pop);
            }
        }
    }

    /// The flat store for a certified destructuring ASSIGNMENT element (Cut
    /// 59): the value on top of the stack assigns the target binding — a
    /// frame slot (`StoreLocal`), a captured binding (`StoreContextSlot`, the
    /// const/TDZ checks), or a declared global. An undeclared name resolves
    /// through the environment machinery (`AssignIdent` — it bails the body
    /// at JIT time, correct but slower).
    fn emit_certified_assign_store(&mut self, name: crux::AtomId) {
        match self.binding(name) {
            BindingLoc::Slot(slot) => self.emit(Step::StoreLocal { slot }),
            BindingLoc::Context(depth, index) => {
                if depth == 0
                    && let Some((per_depth, per_index)) = self.per_iteration(name)
                {
                    self.emit(Step::StorePerIteration {
                        depth: per_depth,
                        index: per_index,
                    });
                } else {
                    self.emit(Step::StoreContextSlot { depth, index });
                }
            }
            BindingLoc::Global => self.emit(Step::StoreGlobal { name }),
            BindingLoc::Acc => self.emit(Step::PopAcc),
            BindingLoc::CapturedIteration(depth, index) => {
                self.emit(Step::StorePerIteration { depth, index })
            }
            BindingLoc::Env => {
                self.emit(Step::AssignIdent {
                    name,
                    op: AssignOp::Assign,
                    set_name: false,
                });
                self.emit(Step::Pop);
            }
        }
    }

    /// Whether a block contributes no environment — true when the block has
    /// no lexical declarations, or (certified bodies only) when every lexical
    /// declaration binds to a frame slot or the capture context: the scope
    /// analysis guarantees the bindings are never consulted through an env
    /// (no closures/eval/with), so the per-iteration/per-block env
    /// allocation in hot loops disappears and `lexical_env` stays constant
    /// for the body.
    fn fast_block(&self, stmts: &[Stmt]) -> bool {
        if self.scope.is_some() {
            return Self::block_decls(stmts).iter().all(|decl| {
                if let StmtKind::VarDecl { decls, .. } = &decl.kind {
                    decls.iter().all(|decl| match &decl.pattern {
                        // A captured binding also contributes no env: a
                        // block env would shadow the capture context and
                        // break `LoadContextSlot` (the flat slot/context
                        // layout is what the certified model consults).
                        BindingPattern::Ident(name) => {
                            self.slot_of(*name).is_some()
                                || self
                                    .scope
                                    .as_ref()
                                    .is_some_and(|scope| scope.context_of(*name).is_some())
                        }
                        _ => false,
                    })
                } else {
                    // A block function declaration in a certified body is an
                    // Annex B declaration the scope analysis allocated (Cut 6
                    // first slice): a block slot + optional var slot, no env.
                    // Class and `using` declarations never certify (the scan
                    // bails the body).
                    matches!(decl.kind, StmtKind::FunctionDecl(_))
                }
            });
        }
        self.script_globals.is_some() && Self::block_decls(stmts).is_empty()
    }

    /// A loop test of the shape `binding <op> NumberLiteral` on the fast
    /// path (Cut 4): the fused `JumpIf*Imm` step replaces `LoadLocal;
    /// BinaryImm; JumpIfFalse` (and the `LoadGlobal` equivalent on the fast
    /// script). The comparison stays the general `apply_binary` semantics,
    /// so a non-number value coerces exactly as before. The limit may be a
    /// literal (the original `JumpIf*Imm` shape) or a fast binding (`i < n`
    /// with `n` a frame slot / declared global — the fused test re-reads it
    /// every iteration, matching the general path's per-iteration
    /// evaluation); a non-fast limit (an env/context binding) keeps the
    /// general test.
    fn fused_rel_test(
        &self,
        test: &Expr,
    ) -> Option<(BinaryOp, BindingLoc, crux::AtomId, RelLimit)> {
        if let ExprKind::Binary { op, left, right } = &test.kind
            && matches!(
                op,
                BinaryOp::LessThan
                    | BinaryOp::LessEqual
                    | BinaryOp::GreaterThan
                    | BinaryOp::GreaterEqual
            )
            && let ExprKind::Ident(name) = &left.kind
        {
            let limit = match &right.kind {
                ExprKind::Literal(syntax::ast::Literal::Number(n)) => RelLimit::Imm(*n),
                ExprKind::Ident(limit_name) => match self.binding(*limit_name) {
                    BindingLoc::Slot(limit_slot) => RelLimit::Slot(limit_slot),
                    BindingLoc::Global => RelLimit::Global(*limit_name),
                    _ => return None,
                },
                _ => return None,
            };
            match self.binding(*name) {
                // A nested loop's test over an active accumulator counter or
                // a captured binding must not fuse (there is no
                // `JumpIf*AccImm`/`JumpIf*ContextImm` step); the general
                // test reads them instead. A non-literal limit also requires
                // a frame-slot counter (the fused test reads the counter
                // slot, and a global counter + binding limit would bail a
                // new shape out of the JIT).
                BindingLoc::Env
                | BindingLoc::Acc
                | BindingLoc::Context(_, _)
                | BindingLoc::CapturedIteration(_, _) => None,
                BindingLoc::Global if !matches!(limit, RelLimit::Imm(_)) => None,
                loc => Some((*op, loc, *name, limit)),
            }
        } else {
            None
        }
    }

    /// An `if`/`while` condition that is `ident === <number>` or
    /// `ident !== <number>` over a frame-slot binding — the strict-equality
    /// sibling of [`Compiler::fused_rel_test`]. Strict equality against a
    /// numeric literal is coercion-free (only the Number `imm` itself
    /// matches), so the fused `JumpIfEqImm`/`JumpIfNeqImm` test needs no
    /// general evaluator; the slot read TDZ-checks like `LoadLocal`.
    fn fused_strict_eq_test(&self, test: &Expr) -> Option<(usize, f64, bool)> {
        if let ExprKind::Binary { op, left, right } = &test.kind {
            let neq = match op {
                BinaryOp::StrictEqual => false,
                BinaryOp::StrictNotEqual => true,
                _ => return None,
            };
            if let (ExprKind::Ident(name), ExprKind::Literal(syntax::ast::Literal::Number(n))) =
                (&left.kind, &right.kind)
                && let BindingLoc::Slot(slot) = self.binding(*name)
            {
                return Some((slot, *n, neq));
            }
        }
        None
    }

    /// Emit the fused strict-equality branch (slice B): the
    /// `JumpIfEqImm`/`JumpIfNeqImm` step with `target: 0`, patched to
    /// `target_label` at compile end.
    fn emit_fused_strict_eq_test(&mut self, neq: bool, slot: usize, imm: f64, target_label: usize) {
        let index = self.steps.len();
        self.emit(if neq {
            Step::JumpIfNeqImm {
                slot,
                imm,
                target: 0,
            }
        } else {
            Step::JumpIfEqImm {
                slot,
                imm,
                target: 0,
            }
        });
        self.fixups.push(Fixup::JumpIfStrictEqImm {
            index,
            label: target_label,
            neq,
            slot,
            imm,
        });
    }

    /// A `for` update that is a bare `i++`/`i--` on a fast binding (Cut 4):
    /// the loop protocol discards the update's value, so the fused `Inc`/
    /// `Dec` (store, no push) is exactly the update step + `Pop`. Only the
    /// `UpdateOp` shapes qualify — `i += 1` is not equivalent (string
    /// operands concatenate under `+=` but coerce numerically under `++`).
    fn fused_update(&self, update: &Expr) -> Option<(BindingLoc, crux::AtomId, UpdateOp)> {
        if let ExprKind::Update { op, target, .. } = &update.kind
            && let ExprKind::Ident(name) = &target.kind
        {
            match self.binding(*name) {
                // A nested loop's update over an active accumulator counter
                // or a captured binding must not fuse (the general `Update`
                // path reads/writes them).
                BindingLoc::Env
                | BindingLoc::Acc
                | BindingLoc::Context(_, _)
                | BindingLoc::CapturedIteration(_, _) => None,
                loc => Some((loc, *name, *op)),
            }
        } else {
            None
        }
    }

    /// Emit a fused relational loop test (Cut 4): the `JumpIf*Imm` step for a
    /// literal limit, the `JumpIfRelLimit` step for a fast-binding limit —
    /// both with `target: 0`, patched to `target_label` at compile end.
    fn emit_fused_rel_test(
        &mut self,
        op: BinaryOp,
        loc: BindingLoc,
        name: crux::AtomId,
        limit: RelLimit,
        target_label: usize,
    ) {
        let index = self.steps.len();
        match (loc, limit) {
            (BindingLoc::Slot(slot), RelLimit::Imm(imm)) => {
                self.emit(Step::JumpIfLtImm {
                    slot,
                    imm,
                    target: 0,
                });
                self.fixups.push(Fixup::JumpIfRelImm {
                    index,
                    label: target_label,
                    op,
                    slot,
                    imm,
                });
            }
            (BindingLoc::Global, RelLimit::Imm(imm)) => {
                self.emit(Step::JumpIfLtGlobalImm {
                    name,
                    imm,
                    target: 0,
                });
                self.fixups.push(Fixup::JumpIfRelGlobalImm {
                    index,
                    label: target_label,
                    op,
                    name,
                    imm,
                });
            }
            (BindingLoc::Slot(slot), limit) => {
                // A frame-slot counter against a fast-binding limit (the
                // `fused_rel_test` gate admits only this combo for a
                // non-literal limit).
                self.emit(Step::JumpIfRelLimit {
                    op,
                    slot,
                    limit,
                    target: 0,
                });
                self.fixups.push(Fixup::JumpIfRelLimit {
                    index,
                    label: target_label,
                });
            }
            (BindingLoc::Acc, _) => unreachable!("emit_fused_rel_test on the accumulator"),
            (BindingLoc::Context(_, _) | BindingLoc::CapturedIteration(_, _), _) => {
                unreachable!("emit_fused_rel_test on a captured binding")
            }
            (BindingLoc::Env, _) => unreachable!("emit_fused_rel_test on the environment path"),
            (BindingLoc::Global, _) => {
                unreachable!("a global counter fuses only a literal limit")
            }
        }
    }

    /// The fused canonical loop (Cut 15): `for (var i = INIT; i <op>
    /// LIMIT; i++/i--)` on a fast binding (the test and update name the
    /// same frame slot or declared top-level var) — the loop's per-iteration
    /// head (increment + re-test + back-jump) becomes one `Step::FastLoopHead`
    /// instead of `IncGlobal` + `JumpIfLtGlobalImm` + `Jump`, while the body
    /// dispatches inline. `None` when the shape doesn't qualify and the
    /// regular loop must be emitted.
    fn compile_fast_loop(
        &mut self,
        test: &Expr,
        update: Option<&Expr>,
    ) -> Result<Option<FastLoopShape>, JsError> {
        let Some(update) = update else {
            return Ok(None);
        };
        let Some((op, loc, name, limit)) = self.fused_rel_test(test) else {
            return Ok(None);
        };
        let Some((inc_loc, inc_name, inc_op)) = self.fused_update(update) else {
            return Ok(None);
        };
        let var = match (loc, inc_loc) {
            (BindingLoc::Slot(slot), BindingLoc::Slot(inc_slot)) if slot == inc_slot => {
                FastLoopVar::Slot(slot)
            }
            (BindingLoc::Global, BindingLoc::Global) if name == inc_name => {
                FastLoopVar::Global(name)
            }
            _ => return Ok(None),
        };
        Ok(Some(FastLoopShape {
            var,
            loc,
            name,
            op,
            limit,
            inc: inc_op,
        }))
    }

    /// Whether the loop body can run with its counter in the VM accumulator
    /// (Cut 17): the counter appears only as (a) a plain read, (b) a simple
    /// `counter = expr` assignment whose expression is a statement, or (c) a
    /// `counter++`/`counter--` whose expression is a statement. Anything
    /// else — value-position assignments/updates, compound assigns, var-decl
    /// or for-head rebinds — would read/write through the binding, which is
    /// stale mid-loop.
    fn acc_body_safe(&self, body: &Stmt, name: crux::AtomId) -> bool {
        acc_stmt_safe(body, name)
    }

    fn new_label(&mut self) -> usize {
        let label = self.next_label;
        self.next_label += 1;
        label
    }

    fn place(&mut self, label: usize) {
        self.labels.insert(label, self.steps.len());
    }

    fn emit(&mut self, step: Step) {
        // A step that switches the lexical environment (block/loop/catch/
        // with envs) makes the body's env non-constant: the dispatch loop
        // must keep syncing the running context for it.
        if matches!(
            &step,
            Step::EnterBlock { .. }
                | Step::EnterLoopEnv { .. }
                | Step::EnterIterTdzEnv { .. }
                | Step::PerIteration { .. }
                | Step::EnterPerIteration { .. }
                | Step::EnterWith
                | Step::CatchBind { .. }
        ) {
            self.env_changing = true;
        }
        self.steps.push(step);
    }

    fn jump(&mut self, target: usize) {
        let index = self.steps.len();
        self.steps.push(Step::Jump(0));
        self.fixups.push(Fixup::Jump(index, target));
    }

    fn jump_if_false(&mut self, target: usize) {
        let index = self.steps.len();
        self.steps.push(Step::JumpIfFalse(0));
        self.fixups.push(Fixup::JumpIfFalse(index, target));
    }

    fn jump_if_true(&mut self, target: usize) {
        let index = self.steps.len();
        self.steps.push(Step::JumpIfTrue(0));
        self.fixups.push(Fixup::JumpIfTrue(index, target));
    }

    fn jump_if_false_keep(&mut self, target: usize) {
        let index = self.steps.len();
        self.steps.push(Step::JumpIfFalseKeep(0));
        self.fixups.push(Fixup::JumpIfFalseKeep(index, target));
    }

    fn jump_if_true_keep(&mut self, target: usize) {
        let index = self.steps.len();
        self.steps.push(Step::JumpIfTrueKeep(0));
        self.fixups.push(Fixup::JumpIfTrueKeep(index, target));
    }

    fn jump_if_nullish_keep(&mut self, target: usize) {
        let index = self.steps.len();
        self.steps.push(Step::JumpIfNullishKeep(0));
        self.fixups.push(Fixup::JumpIfNullishKeep(index, target));
    }

    fn jump_if_chain_short(&mut self, target: usize) {
        let index = self.steps.len();
        self.steps.push(Step::JumpIfChainShort(0));
        self.fixups.push(Fixup::JumpIfChainShort(index, target));
    }

    /// Enter an optional-chain node: the outermost node of a chain that may
    /// short-circuit emits the runtime clear when it finishes. Returns
    /// whether the node contributes a chain depth — the paired
    /// [`Compiler::leave_chain`] needs it, because a nested non-optional
    /// member between chain links (`a.b?.c`'s `a.b`) must not consume the
    /// enclosing chain's depth (that premature clear was the `a?.b.m` bug:
    /// the flag was cleared before the `.m` guard).
    fn enter_chain(&mut self, expr: &Expr) -> bool {
        if expr_may_short_circuit(expr) {
            self.chain_depth += 1;
            true
        } else {
            false
        }
    }

    fn leave_chain(&mut self, entered: bool) {
        if entered {
            self.chain_depth -= 1;
            if self.chain_depth == 0 {
                self.emit(Step::ClearChainShort);
            }
        }
    }

    /// Compile a member property access, skipping it when an upstream `?.`
    /// short-circuited (the chain value is already `undefined` on the stack,
    /// spec 13.4.3).
    fn compile_member_property_guarded(
        &mut self,
        member: &syntax::ast::MemberExpr,
    ) -> Result<(), JsError> {
        if expr_may_short_circuit(&member.object) {
            let end = self.new_label();
            self.jump_if_chain_short(end);
            self.compile_member_property(member)?;
            self.place(end);
        } else {
            self.compile_member_property(member)?;
        }
        Ok(())
    }

    /// Compile a call's arguments and the call step, skipping both when an
    /// upstream `?.` short-circuited: the whole chain is `undefined` (spec
    /// 13.4.3). When no optional chain is open the guard is provably dead
    /// (`chain_short` is set only inside a chain and cleared on leaving it,
    /// and a parenthesized callee's own `?.` is cleared before the call) — a
    /// plain `f(n)` in a hot loop would otherwise dispatch the guard's
    /// `JumpIfChainShort`/`Jump` pair every iteration.
    fn compile_call_args_guarded(
        &mut self,
        args: &[Argument],
        direct_eval: bool,
    ) -> Result<(), JsError> {
        if self.chain_depth == 0 {
            return self.compile_call_args(args, direct_eval);
        }
        let short = self.new_label();
        let end = self.new_label();
        self.jump_if_chain_short(short);
        self.compile_call_args(args, direct_eval)?;
        self.jump(end);
        self.place(short);
        self.emit(Step::Pop);
        self.emit(Step::Pop);
        self.emit(Step::Push(Value::Undefined));
        self.place(end);
        Ok(())
    }

    /// The argument compilation + call step (fast plain args or the vector
    /// form), shared by the guarded and unguarded call paths.
    fn compile_call_args(&mut self, args: &[Argument], direct_eval: bool) -> Result<(), JsError> {
        let tail = self.tail;
        self.tail = false; // arguments are never in tail position
        // A direct eval ALWAYS takes the vector form (Cut 50): the fast
        // form's JIT path does not handle eval, and the vector handlers do —
        // so its arguments must be built in the VM's vector, not on the
        // stack.
        let argc = self.compile_arguments(args, !direct_eval)?;
        self.tail = tail;
        // A direct eval stays a tail call when in tail position: the flag is
        // name-based (`eval` as the callee identifier — a shadowed `eval`
        // function is still tail-called), and the vector-form handlers route
        // a callee that really is %eval% through `perform_eval` with the
        // caller's environment intact instead of frame-replacing. A direct
        // eval ALWAYS takes the vector form (Cut 50): the fast form's JIT
        // path does not handle eval, and the vector handlers do.
        let fast = !direct_eval && argc.is_some();
        match (fast, tail) {
            (true, true) => self.emit(Step::TailCallFast {
                argc: argc.unwrap() as u8,
                direct_eval: false,
            }),
            (false, true) => self.emit(Step::TailCall { direct_eval }),
            (true, false) => self.emit(Step::CallFast {
                argc: argc.unwrap() as u8,
                direct_eval: false,
            }),
            (false, false) => self.emit(Step::Call { direct_eval }),
        }
        Ok(())
    }

    fn jump_if_not_nullish_keep(&mut self, target: usize) {
        let index = self.steps.len();
        self.steps.push(Step::JumpIfNotNullishKeep(0));
        self.fixups.push(Fixup::JumpIfNotNullishKeep(index, target));
    }

    fn emit_destructure_next(&mut self) {
        self.steps.push(Step::DestructureNext);
    }

    fn emit_destructure_undef(&mut self, use_default: usize) {
        let index = self.steps.len();
        self.steps.push(Step::DestructureUndef { use_default: 0 });
        self.fixups
            .push(Fixup::DestructureUndef(index, use_default));
    }

    fn leave_scopes(&mut self, count: usize) {
        for _ in 0..count {
            self.emit(Step::LeaveBlock);
        }
    }

    /// A label scoping a loop defers its continue target to the loop with a
    /// sentinel (see `labeled_continue_target`): when the loop's scope is
    /// pushed, resolve any sentinel targets in the label scopes directly
    /// beneath it (an intermediate non-loop label or other scope stops the
    /// walk).
    fn resolve_labeled_continue(&mut self, continue_target: usize, continue_count: usize) {
        // The loop's own scope is on top; the labels it resolves are beneath.
        for scope in self.scope_stack.iter_mut().rev().skip(1) {
            match scope {
                Scope::Label {
                    continue_target: target,
                    ..
                } => {
                    if let Some((usize::MAX, _)) = target {
                        *target = Some((continue_target, continue_count));
                    } else {
                        break;
                    }
                }
                _ => break,
            }
        }
    }

    /// Whether a for-in/for-of head needs its lexical names in TDZ while the
    /// RHS evaluates, and if so emit the TDZ environment (spec 14.7.5.4 /
    /// 14.7.6.1).
    fn enter_iter_tdz_env(&mut self, left: &ForBinding) -> bool {
        if let ForBinding::VarDecl { kind, pattern, .. } = left
            && *kind != VarDeclKind::Var
        {
            let mut names = Vec::new();
            crate::script::bound_names(pattern, &mut names);
            if !names.is_empty() {
                self.emit(Step::EnterIterTdzEnv { names });
                return true;
            }
        }
        false
    }

    fn leave_iter_tdz_env(&mut self, entered: bool) {
        if entered {
            self.emit(Step::LeaveIterTdzEnv);
        }
    }

    fn resolve(&mut self) {
        for fixup in std::mem::take(&mut self.fixups) {
            match fixup {
                Fixup::Jump(index, label) => {
                    self.steps[index] = Step::Jump(self.labels[&label]);
                }
                Fixup::JumpIfFalse(index, label) => {
                    self.steps[index] = Step::JumpIfFalse(self.labels[&label]);
                }
                Fixup::JumpIfTrue(index, label) => {
                    self.steps[index] = Step::JumpIfTrue(self.labels[&label]);
                }
                Fixup::JumpIfFalseKeep(index, label) => {
                    self.steps[index] = Step::JumpIfFalseKeep(self.labels[&label]);
                }
                Fixup::JumpIfTrueKeep(index, label) => {
                    self.steps[index] = Step::JumpIfTrueKeep(self.labels[&label]);
                }
                Fixup::JumpIfNullishKeep(index, label) => {
                    self.steps[index] = Step::JumpIfNullishKeep(self.labels[&label]);
                }
                Fixup::JumpIfNotNullishKeep(index, label) => {
                    self.steps[index] = Step::JumpIfNotNullishKeep(self.labels[&label]);
                }
                Fixup::JumpIfRelImm {
                    index,
                    label,
                    op,
                    slot,
                    imm,
                } => {
                    let target = self.labels[&label];
                    self.steps[index] = match op {
                        BinaryOp::LessThan => Step::JumpIfLtImm { slot, imm, target },
                        BinaryOp::LessEqual => Step::JumpIfLeImm { slot, imm, target },
                        BinaryOp::GreaterThan => Step::JumpIfGtImm { slot, imm, target },
                        BinaryOp::GreaterEqual => Step::JumpIfGeImm { slot, imm, target },
                        _ => unreachable!("JumpIfRelImm fixup with a non-relational op"),
                    };
                }
                Fixup::JumpIfRelGlobalImm {
                    index,
                    label,
                    op,
                    name,
                    imm,
                } => {
                    let target = self.labels[&label];
                    self.steps[index] = match op {
                        BinaryOp::LessThan => Step::JumpIfLtGlobalImm { name, imm, target },
                        BinaryOp::LessEqual => Step::JumpIfLeGlobalImm { name, imm, target },
                        BinaryOp::GreaterThan => Step::JumpIfGtGlobalImm { name, imm, target },
                        BinaryOp::GreaterEqual => Step::JumpIfGeGlobalImm { name, imm, target },
                        _ => unreachable!("JumpIfRelGlobalImm fixup with a non-relational op"),
                    };
                }
                Fixup::JumpIfRelLimit { index, label } => {
                    if let Step::JumpIfRelLimit { target, .. } = &mut self.steps[index] {
                        *target = self.labels[&label];
                    }
                }
                Fixup::JumpIfStrictEqImm {
                    index,
                    label,
                    neq,
                    slot,
                    imm,
                } => {
                    let target = self.labels[&label];
                    self.steps[index] = if neq {
                        Step::JumpIfNeqImm { slot, imm, target }
                    } else {
                        Step::JumpIfEqImm { slot, imm, target }
                    };
                }
                Fixup::TypedArrayLengthHoist { index, label } => {
                    if let Step::TypedArrayLengthHoist { target } = &mut self.steps[index] {
                        *target = self.labels[&label];
                    }
                }
                Fixup::FastLoopHead(index, body_label, after_label) => {
                    if let Step::FastLoopHead {
                        body_start, after, ..
                    } = &mut self.steps[index]
                    {
                        *body_start = self.labels[&body_label];
                        *after = self.labels[&after_label];
                    }
                }
                Fixup::Break(index, label) => {
                    self.steps[index] = Step::Break {
                        target: self.labels[&label],
                    };
                }
                Fixup::Continue(index, label) => {
                    self.steps[index] = Step::Continue {
                        target: self.labels[&label],
                    };
                }
                Fixup::JumpIfChainShort(index, label) => {
                    self.steps[index] = Step::JumpIfChainShort(self.labels[&label]);
                }
                Fixup::Exit(index, label) => {
                    self.steps[index] = Step::Exit {
                        after: self.labels[&label],
                    };
                }
                Fixup::ForInNext(index, label) => {
                    if let Step::ForInNext { done, .. } = &mut self.steps[index] {
                        *done = self.labels[&label];
                    }
                }
                Fixup::ForOfBoundary(index, top, end) => {
                    self.steps[index] = Step::ForOfBegin {
                        top: self.labels[&top],
                        end: self.labels[&end],
                    };
                }
                Fixup::AsyncForOfBoundary(index, top, end) => {
                    self.steps[index] = Step::AsyncForOfBegin {
                        top: self.labels[&top],
                        end: self.labels[&end],
                    };
                }
                Fixup::ForOfNext(index, label) => {
                    if let Step::ForOfNext { done, .. } = &mut self.steps[index] {
                        *done = self.labels[&label];
                    }
                }
                Fixup::ForOfNextBindLocal(index, label) => {
                    if let Step::ForOfNextBindLocal { done, .. } = &mut self.steps[index] {
                        *done = self.labels[&label];
                    }
                }
                Fixup::DestructureUndef(index, label) => {
                    self.steps[index] = Step::DestructureUndef {
                        use_default: self.labels[&label],
                    };
                }
                Fixup::AsyncForOfNext(index, label) => {
                    self.steps[index] = Step::AsyncForOfTest {
                        done: self.labels[&label],
                    };
                }
                Fixup::SwitchTest(index, label) => {
                    self.steps[index] = Step::SwitchTest {
                        case: self.labels[&label],
                    };
                }
                Fixup::YieldStarNext(index, label) => {
                    self.steps[index] = Step::YieldStarNext {
                        done: self.labels[&label],
                    };
                }
                Fixup::YieldStarResume(index, loop_label, done_label, yield_label) => {
                    self.steps[index] = Step::YieldStarResume {
                        loop_top: self.labels[&loop_label],
                        done: self.labels[&done_label],
                        yield_at: self.labels[&yield_label],
                    };
                }
                Fixup::AsyncYieldStarNext(index, label) => {
                    self.steps[index] = Step::AsyncYieldStarNext {
                        done: self.labels[&label],
                    };
                }
                Fixup::AsyncYieldStarInspect(index, label) => {
                    self.steps[index] = Step::AsyncYieldStarInspect {
                        done: self.labels[&label],
                    };
                }
                Fixup::AsyncYieldStarResume(index, loop_label, done_label, inspect_index) => {
                    self.steps[index] = Step::AsyncYieldStarResume {
                        loop_top: self.labels[&loop_label],
                        done: self.labels[&done_label],
                        inspect: inspect_index,
                    };
                }
            }
        }
    }

    fn break_target(&self, label: Option<&crux::AtomId>) -> Result<(usize, usize), JsError> {
        match label {
            None => {
                for scope in self.scope_stack.iter().rev() {
                    match scope {
                        Scope::Loop {
                            break_target,
                            break_count,
                            ..
                        } => return Ok((*break_target, *break_count)),
                        Scope::Switch {
                            break_target,
                            break_count,
                        } => return Ok((*break_target, *break_count)),
                        Scope::Iteration {
                            break_target,
                            closed,
                            ..
                        } => return Ok((*break_target, *closed)),
                        _ => {}
                    }
                }
                Err(JsError::new(
                    ErrorKind::SyntaxError,
                    "Illegal break statement".into(),
                ))
            }
            Some(label) => {
                for scope in self.scope_stack.iter().rev() {
                    if let Scope::Label {
                        name,
                        break_target,
                        break_count,
                        ..
                    } = scope
                        && name == label
                    {
                        return Ok((*break_target, *break_count));
                    }
                }
                Err(JsError::new(
                    ErrorKind::SyntaxError,
                    "Undefined label in break statement".into(),
                ))
            }
        }
    }

    fn continue_target(&self, label: Option<&crux::AtomId>) -> Result<(usize, usize), JsError> {
        match label {
            None => {
                for scope in self.scope_stack.iter().rev() {
                    match scope {
                        Scope::Loop {
                            continue_target,
                            continue_count,
                            ..
                        } => return Ok((*continue_target, *continue_count)),
                        Scope::Iteration {
                            continue_target,
                            open,
                            ..
                        } => return Ok((*continue_target, *open)),
                        _ => {}
                    }
                }
                Err(JsError::new(
                    ErrorKind::SyntaxError,
                    "Illegal continue statement".into(),
                ))
            }
            Some(label) => {
                // A labelled loop's continue target is the innermost loop
                // scope beneath the label.
                let mut found_label = false;
                for scope in self.scope_stack.iter().rev() {
                    match scope {
                        Scope::Label {
                            name,
                            continue_target,
                            ..
                        } => {
                            if name == label
                                && let Some((target, count)) = continue_target
                                && *target != usize::MAX
                            {
                                return Ok((*target, *count));
                            }
                            if name == label {
                                found_label = true;
                            }
                        }
                        Scope::Loop {
                            continue_target,
                            continue_count,
                            ..
                        } if found_label => {
                            return Ok((*continue_target, *continue_count));
                        }
                        Scope::Iteration {
                            continue_target,
                            open,
                            ..
                        } if found_label => {
                            return Ok((*continue_target, *open));
                        }
                        _ => {}
                    }
                }
                Err(JsError::new(
                    ErrorKind::SyntaxError,
                    "Undefined label in continue statement".into(),
                ))
            }
        }
    }
}

impl Compiler {
    fn compile_statements(&mut self, stmts: &[Stmt]) -> Result<(), JsError> {
        for stmt in stmts {
            self.compile_statement(stmt)?;
        }
        Ok(())
    }

    /// The declarations a block environment instantiates at entry:
    /// `block_declaration_instantiation` ignores every other statement kind.
    fn block_decls(stmts: &[Stmt]) -> Vec<Stmt> {
        stmts
            .iter()
            .filter(|stmt| match &stmt.kind {
                StmtKind::VarDecl { kind, .. } => *kind != VarDeclKind::Var,
                StmtKind::UsingDecl { .. } | StmtKind::ClassDecl(_) | StmtKind::FunctionDecl(_) => {
                    true
                }
                _ => false,
            })
            .cloned()
            .collect()
    }

    /// A block's interior: the Annex B entries / block environment and its
    /// statement list. `compile_statement` wraps it in `ListBegin`/
    /// `ListEnd`; a `for` body whose completion the loop discards compiles
    /// the interior alone (see `compile_for_body`).
    fn compile_block_contents(&mut self, block: &Block) -> Result<(), JsError> {
        if self.fast_block(&block.stmts) {
            // Cut 3: a fast body's block has no lexical declarations
            // that need an environment, so it contributes no
            // environment (the per-iteration env allocation in hot
            // loops disappears). The scope count is untouched, so
            // control-transfer unwinds stay balanced.
            //
            // Cut 6 first slice: an Annex B block function
            // declaration keeps the block env-free — the block
            // binding is a frame slot initialized at block entry
            // (14.2.3) with the hoisted var reset to *undefined*
            // (B.3.2.1) first, and the declaration statement copies
            // the block binding into the var binding (B.3.3.3).
            let indices = self.annex_b_block_entries(&block.stmts);
            self.annex_b_stack.push(indices.clone());
            for &index in &indices {
                let (name, function, block_slot, var_slot) = {
                    let scope = self
                        .scope
                        .as_ref()
                        .expect("Annex B entries imply a certified body");
                    let entry = &scope.annex_b[index];
                    (
                        entry.name,
                        entry.function.clone(),
                        entry.block_slot,
                        entry.var_slot,
                    )
                };
                if let Some(var_slot) = var_slot {
                    self.emit(Step::Push(Value::Undefined));
                    self.emit(Step::InitLocal { slot: var_slot });
                }
                let outer_chain = self.closure_outer_chain();
                let per_iteration_chain = self.closure_per_iteration_chain();
                self.emit(Step::FunctionDeclInit {
                    name,
                    function,
                    frame_slot: Some(block_slot),
                    context_slot: None,
                    outer_chain,
                    per_iteration_chain,
                });
            }
            self.compile_statements(&block.stmts)?;
            self.annex_b_stack.pop();
        } else {
            self.emit(Step::EnterBlock {
                decls: Self::block_decls(&block.stmts),
            });
            self.scope_count += 1;
            self.compile_statements(&block.stmts)?;
            self.scope_count -= 1;
            self.emit(Step::LeaveBlock);
        }
        Ok(())
    }

    fn compile_statement(&mut self, stmt: &Stmt) -> Result<(), JsError> {
        match &stmt.kind {
            StmtKind::Block(block) => {
                self.emit(Step::ListBegin);
                self.compile_block_contents(block)?;
                self.emit(Step::ListEnd);
            }
            StmtKind::Expr(expr) => {
                // Cut 34: a statement-position assignment to a fast binding
                // stores AND sets the statement completion in one step
                // (`FusedStore*`), so no result `Dup` for `SetCompletion` to
                // pop. Any other expression still leaves its value for
                // `SetCompletion`.
                let prev = self.statement_expr;
                self.statement_expr = true;
                self.fused_completion = false;
                self.compile_expr(expr)?;
                self.statement_expr = prev;
                if self.fused_completion {
                    self.fused_completion = false;
                } else {
                    self.emit(Step::SetCompletion);
                }
            }
            StmtKind::VarDecl { kind, decls, .. } => {
                let declaration = *kind != VarDeclKind::Var;
                for decl in decls {
                    if let Some(init) = &decl.init {
                        // Cut 3/5 fast path: `var x = init` with a fast
                        // binding — the slot exists (hoisted, undefined) or
                        // the global property exists (instantiation created
                        // it), so the initializer writes it directly. The
                        // resolve-before-init rule is only observable via a
                        // `with` scope (excluded from the fast path).
                        if let BindingPattern::Ident(name) = &decl.pattern {
                            match self.binding(*name) {
                                BindingLoc::Slot(slot) => {
                                    self.begin_named_initializer(*name, init);
                                    self.compile_expr(init)?;
                                    self.emit(Step::InitLocal { slot });
                                    continue;
                                }
                                BindingLoc::Context(0, index) => {
                                    self.begin_named_initializer(*name, init);
                                    self.compile_expr(init)?;
                                    self.emit(Step::InitContextSlot { index });
                                    continue;
                                }
                                BindingLoc::Global => {
                                    self.begin_named_initializer(*name, init);
                                    self.compile_expr(init)?;
                                    if crate::function::is_anonymous_function_definition(init) {
                                        self.emit(Step::SetFunctionName { name: *name });
                                    }
                                    self.emit(Step::StoreGlobal { name: *name });
                                    continue;
                                }
                                // A declaration's name is bound in this body,
                                // never an enclosing body's capture.
                                BindingLoc::Context(_, _) | BindingLoc::CapturedIteration(_, _) => {
                                    unreachable!("a declaration cannot bind an outer context")
                                }
                                // A declaration of an active accumulator
                                // counter is rejected by the loop-body scan.
                                BindingLoc::Acc => {
                                    unreachable!("a loop body cannot redeclare its counter")
                                }
                                BindingLoc::Env => {}
                            }
                        }
                        // spec 14.3.2 step 2: a `var` identifier's binding is
                        // resolved before its initializer runs — a `with`
                        // object's property is the assignment target even
                        // when the initializer mutates the object.
                        if !declaration && let BindingPattern::Ident(name) = &decl.pattern {
                            self.emit(Step::ResolveVarIdent { name: *name });
                        }
                        if let BindingPattern::Ident(name) = &decl.pattern {
                            self.begin_named_initializer(*name, init);
                        }
                        self.compile_expr(init)?;
                        if let BindingPattern::Ident(name) = &decl.pattern
                            && crate::function::is_anonymous_function_definition(init)
                        {
                            // NamedEvaluation (spec 14.2.2 step 2.d): an
                            // anonymous function/class initializer is named
                            // after its binding.
                            self.emit(Step::SetFunctionName { name: *name });
                        }
                        if self.binding_pattern_contains_suspension(&decl.pattern)
                            || self.scope.is_some()
                        {
                            // Defaults/computed keys with `yield`/`await`
                            // compile inline so they can suspend; a certified
                            // body (Cut 59) compiles EVERY pattern to the
                            // primitive `Destructure*` steps with flat
                            // slot/context binds (the wholesale
                            // `DeclInit`/`Destructure` steps bind through the
                            // environment machinery, which a certified body
                            // never consults).
                            self.compile_destructure_binding(&decl.pattern, declaration)?;
                        } else if !declaration && matches!(decl.pattern, BindingPattern::Ident(_)) {
                            self.emit(Step::PutVarReference);
                            // The binding step re-pushed the initialized
                            // value (its assignment-expression semantics); a
                            // declaration statement completes empty, so the
                            // value is discarded. Without this, an
                            // env-path declaration inside a loop body
                            // leaves one handle per iteration on the
                            // precisely-traced value stack, retaining every
                            // initialized object for the loop's duration.
                            self.emit(Step::Pop);
                        } else {
                            let step = if declaration {
                                Step::DeclInit {
                                    pattern: decl.pattern.clone(),
                                }
                            } else {
                                Step::Destructure {
                                    pattern: decl.pattern.clone(),
                                }
                            };
                            self.emit(step);
                            // See the `PutVarReference` branch above: a
                            // statement-position declaration's bound value
                            // is not the statement's result.
                            self.emit(Step::Pop);
                        }
                    } else if declaration {
                        // `let x;` initializes the binding to *undefined*
                        // (spec 14.2.1 step 4); the binding was created
                        // uninitialized by declaration instantiation. A
                        // slot-bound identifier writes the frame slot
                        // directly (the frame started it in the TDZ); a
                        // certified destructuring pattern (Cut 59) compiles
                        // the primitive steps over the pushed `undefined`
                        // (a no-init array/object pattern destructures it
                        // and throws).
                        if let BindingPattern::Ident(name) = &decl.pattern
                            && let BindingLoc::Slot(slot) = self.binding(*name)
                        {
                            self.emit(Step::Push(Value::Undefined));
                            self.emit(Step::InitLocal { slot });
                        } else if self.scope.is_some() {
                            self.emit(Step::Push(Value::Undefined));
                            self.compile_destructure_binding(&decl.pattern, declaration)?;
                        } else {
                            self.emit(Step::Push(Value::Undefined));
                            self.emit(Step::DeclInit {
                                pattern: decl.pattern.clone(),
                            });
                            self.emit(Step::Pop);
                        }
                    }
                }
            }
            StmtKind::UsingDecl { is_await, decls } => {
                for decl in decls {
                    if let Some(init) = &decl.init {
                        self.compile_expr(init)?;
                        if let BindingPattern::Ident(name) = &decl.pattern
                            && crate::function::is_anonymous_function_definition(init)
                        {
                            // NamedEvaluation (spec 14.2.2 step 2.d): an
                            // anonymous function/class initializer is named
                            // after its binding.
                            self.emit(Step::SetFunctionName { name: *name });
                        }
                        self.has_using = true;
                        self.emit(Step::UsingInit {
                            pattern: decl.pattern.clone(),
                            is_await: *is_await,
                        });
                        // `UsingInit` re-pushes the registered value like
                        // `DeclInit`; the declaration statement's value is
                        // empty, so it is discarded.
                        self.emit(Step::Pop);
                    }
                }
            }
            StmtKind::Return(expr) => {
                let has_value = expr.is_some();
                if let Some(expr) = expr {
                    // A proper tail call (spec 14.2.2): strict mode, outside
                    // any try, no `with` in scope (the callee could resolve
                    // through it), in an ordinary body, with no `using`
                    // declarations (their disposal would be skipped by the
                    // frame replacement) — the argument's final call compiles
                    // to a frame-replacing tail call. A return in the
                    // innermost try's own catch-without-finally or finally
                    // clause is also tail-eligible (`tail_safe_depth ==
                    // try_depth`): the try's frame is already consumed when
                    // the clause runs, and with `try_depth <= 1` no outer
                    // catch could observe a throw from the callee and no
                    // outer finally must run after it. The env unwind and
                    // `Return` below still emit: they are dead after a
                    // replaced frame but required by the non-tail branches of
                    // a forwarded shape (`return a ? 0 : f(b)`).
                    let eligible = self.strict
                        && self.try_depth == self.tail_safe_depth
                        && self.try_depth <= 1
                        && self.with_depth == 0
                        && !self.is_async_generator
                        && !self.has_using;
                    let saved = self.tail;
                    self.tail = eligible;
                    self.compile_expr(expr)?;
                    self.tail = saved;
                } else {
                    self.emit(Step::Push(Value::Undefined));
                }
                self.leave_scopes(self.scope_count);
                if self.is_async_generator && has_value {
                    // spec ReturnStatement evaluation step 3: only
                    // `return Expression` in an async generator awaits
                    // the value before completing
                    // (AsyncGeneratorCompleteStep does not unwrap);
                    // `return;` completes with `undefined` without
                    // awaiting.
                    self.emit(Step::Await);
                }
                self.emit(Step::Return);
            }
            StmtKind::Throw(expr) => {
                self.compile_expr(expr)?;
                self.emit(Step::Throw);
            }
            StmtKind::If {
                test,
                consequent,
                alternate,
            } => {
                // A certified loop body's statements lower to register runs
                // (or step-path statements whose own SetCompletion writes the
                // register), and the loop's own trailing NormalizeCompletion
                // defines its completion — the per-if reset exists only so the
                // if's own NormalizeCompletion can turn an empty register into
                // Normal(undefined), which the loop boundary already does. It
                // is a redundant per-iteration dispatch on the branchy hot
                // path, so emit it only outside certified loop bodies (the
                // register runs never touch the completion register, so
                // skipping it there is unobservable).
                let in_certified_loop = self.scope.is_some()
                    && self
                        .scope_stack
                        .iter()
                        .any(|s| matches!(s, Scope::Loop { .. }));
                if !in_certified_loop {
                    self.emit(Step::ResetCompletion);
                }
                let else_label = self.new_label();
                let end_label = self.new_label();
                if let Some((slot, imm, neq)) = self.fused_strict_eq_test(test) {
                    // The `x === N` / `x !== N` condition fuses with the
                    // false-jump (LoadLocal + BinaryImm + JumpIfFalse).
                    self.emit_fused_strict_eq_test(neq, slot, imm, else_label);
                } else {
                    self.compile_expr(test)?;
                    self.jump_if_false(else_label);
                }
                self.compile_statement(consequent)?;
                self.jump(end_label);
                self.place(else_label);
                if let Some(alternate) = alternate {
                    self.compile_statement(alternate)?;
                }
                self.place(end_label);
                self.emit(Step::NormalizeCompletion);
            }
            StmtKind::While { test, body } => {
                self.emit(Step::ResetCompletion);
                let test_label = self.new_label();
                let end_label = self.new_label();
                let break_count = self.scope_count;
                let continue_count = self.scope_count;
                self.scope_stack.push(Scope::Loop {
                    break_target: end_label,
                    break_count,
                    continue_target: test_label,
                    continue_count,
                });
                self.resolve_labeled_continue(test_label, continue_count);
                self.place(test_label);
                if let Some((slot, imm, neq)) = self.fused_strict_eq_test(test) {
                    // The `x === N` / `x !== N` condition fuses with the
                    // false-jump (LoadLocal + BinaryImm + JumpIfFalse).
                    self.emit_fused_strict_eq_test(neq, slot, imm, end_label);
                } else if let Some((op, loc, name, imm)) = self.fused_rel_test(test) {
                    // Cut 4/5: the loop test `binding <op> imm` fuses with
                    // the false-jump (LoadLocal/LoadGlobal + BinaryImm +
                    // JumpIfFalse).
                    self.emit_fused_rel_test(op, loc, name, imm, end_label);
                } else {
                    self.compile_expr(test)?;
                    self.jump_if_false(end_label);
                }
                self.compile_statement(body)?;
                self.jump(test_label);
                self.place(end_label);
                self.emit(Step::NormalizeCompletion);
                self.scope_stack.pop();
            }
            StmtKind::DoWhile { body, test } => {
                self.emit(Step::ResetCompletion);
                let body_label = self.new_label();
                let test_label = self.new_label();
                let end_label = self.new_label();
                let break_count = self.scope_count;
                let continue_count = self.scope_count;
                self.scope_stack.push(Scope::Loop {
                    break_target: end_label,
                    break_count,
                    continue_target: test_label,
                    continue_count,
                });
                self.resolve_labeled_continue(test_label, continue_count);
                self.place(body_label);
                self.compile_statement(body)?;
                self.place(test_label);
                self.compile_expr(test)?;
                self.jump_if_true(body_label);
                self.place(end_label);
                self.emit(Step::NormalizeCompletion);
                self.scope_stack.pop();
            }
            StmtKind::For {
                init,
                test,
                update,
                body,
            } => self.compile_for(init.as_ref(), test.as_ref(), update.as_ref(), body)?,
            StmtKind::ForIn { left, right, body } => {
                self.compile_for_in(left, right, body)?;
            }
            StmtKind::ForOf {
                left,
                right,
                body,
                is_await,
            } => {
                if *is_await {
                    self.compile_async_for_of(left, right, body)?;
                } else {
                    self.compile_for_of(left, right, body)?;
                }
            }
            StmtKind::Labeled { label, body } => {
                self.emit(Step::ResetCompletion);
                let break_target = self.new_label();
                let break_count = self.scope_count;
                let continue_target = labeled_continue_target(body);
                self.scope_stack.push(Scope::Label {
                    name: *label,
                    break_target,
                    break_count,
                    continue_target,
                });
                self.compile_statement(body)?;
                self.place(break_target);
                self.emit(Step::NormalizeCompletion);
                self.scope_stack.pop();
            }
            StmtKind::Break(label) => {
                let (target, count) = self.break_target(label.as_ref())?;
                self.leave_scopes(self.scope_count.saturating_sub(count));
                let index = self.steps.len();
                self.emit(Step::Break { target: 0 });
                self.fixups.push(Fixup::Break(index, target));
            }
            StmtKind::Continue(label) => {
                let (target, count) = self.continue_target(label.as_ref())?;
                self.leave_scopes(self.scope_count.saturating_sub(count));
                let index = self.steps.len();
                self.emit(Step::Continue { target: 0 });
                self.fixups.push(Fixup::Continue(index, target));
            }
            StmtKind::Switch {
                discriminant,
                cases,
            } => self.compile_switch(discriminant, cases)?,
            StmtKind::Try {
                block,
                handler,
                finalizer,
            } => self.compile_try(block, handler.as_ref(), finalizer.as_ref())?,
            StmtKind::With { object, body } => {
                self.emit(Step::ResetCompletion);
                self.compile_expr(object)?;
                self.emit(Step::EnterWith);
                self.scope_count += 1;
                self.with_depth += 1;
                self.compile_statement(body)?;
                self.with_depth -= 1;
                self.scope_count -= 1;
                self.emit(Step::LeaveBlock);
                self.emit(Step::NormalizeCompletion);
            }
            StmtKind::ClassDecl(class) => {
                // A class declaration whose heritage or computed names
                // suspend: evaluate the definition through the VM, then
                // initialize the declaration's binding (created uninitialized
                // by declaration instantiation).
                self.compile_class(class)?;
                if let Some(name) = class.name {
                    self.emit(Step::DeclInit {
                        pattern: BindingPattern::Ident(name),
                    });
                    // `DeclInit` re-pushed the class value; a class
                    // declaration completes empty.
                    self.emit(Step::Pop);
                }
            }
            StmtKind::Empty | StmtKind::Debugger => {}
            StmtKind::FunctionDecl(function) => {
                if self.scope.is_none() {
                    // A certified body's top-level declarations were
                    // initialized at entry (`FunctionDeclInit`); the
                    // declaration statement itself is empty (15.2.6). The
                    // env path evaluates it in place (incl. the Annex B
                    // forms).
                    self.emit(Step::FunctionDecl {
                        stmt: Box::new(stmt.clone()),
                    });
                } else if function.statement_position {
                    // Cut 6 continuation (Annex B): a statement-position
                    // declaration instantiates the closure into the hoisted
                    // var binding's slot — the transient block env of the
                    // env path is unobservable. A dead declaration (no
                    // entry) is empty.
                    if let Some(entry) = self.statement_fn(function) {
                        let outer_chain = self.closure_outer_chain();
                        let per_iteration_chain = self.closure_per_iteration_chain();
                        self.emit(Step::FunctionDeclInit {
                            name: entry.name,
                            function: Box::new(function.clone()),
                            frame_slot: entry.frame_slot,
                            context_slot: entry.context_slot,
                            outer_chain,
                            per_iteration_chain,
                        });
                    }
                } else if let Some((block_slot, var_slot)) = self.annex_b_copy_target(function) {
                    // Cut 6 first slice: an Annex B block function — the
                    // declaration statement copies the block binding (its
                    // current value) into the hoisted var binding; the
                    // block binding itself was initialized at block entry.
                    self.emit(Step::LoadLocal { slot: block_slot });
                    self.emit(Step::InitLocal { slot: var_slot });
                }
            }
        }
        Ok(())
    }

    /// The step index a `Fixup` patches (the first field of every variant).
    fn fixup_index(fixup: &mut Fixup) -> &mut usize {
        match fixup {
            Fixup::Jump(index, _)
            | Fixup::JumpIfFalse(index, _)
            | Fixup::JumpIfTrue(index, _)
            | Fixup::JumpIfFalseKeep(index, _)
            | Fixup::JumpIfTrueKeep(index, _)
            | Fixup::JumpIfNullishKeep(index, _)
            | Fixup::JumpIfNotNullishKeep(index, _) => index,
            Fixup::ForOfBoundary(index, _, _) => index,
            Fixup::AsyncForOfBoundary(index, _, _) => index,
            Fixup::JumpIfRelImm { index, .. } => index,
            Fixup::JumpIfRelGlobalImm { index, .. } => index,
            Fixup::JumpIfRelLimit { index, .. } => index,
            Fixup::JumpIfStrictEqImm { index, .. } => index,
            Fixup::FastLoopHead(index, _, _) => index,
            Fixup::TypedArrayLengthHoist { index, .. } => index,
            Fixup::Break(index, _) => index,
            Fixup::Continue(index, _) => index,
            Fixup::JumpIfChainShort(index, _) => index,
            Fixup::Exit(index, _) => index,
            Fixup::ForInNext(index, _) => index,
            Fixup::ForOfNext(index, _) => index,
            Fixup::ForOfNextBindLocal(index, _) => index,
            Fixup::DestructureUndef(index, _) => index,
            Fixup::AsyncForOfNext(index, _) => index,
            Fixup::SwitchTest(index, _) => index,
            Fixup::YieldStarNext(index, _) => index,
            Fixup::YieldStarResume(index, _, _, _) => index,
            Fixup::AsyncYieldStarNext(index, _) => index,
            Fixup::AsyncYieldStarInspect(index, _) => index,
            Fixup::AsyncYieldStarResume(index, _, _, _) => index,
        }
    }

    /// Replace the segmented straight-line runs of a compiled body (offsets
    /// into `steps[base..]`) with `RunRegBody` steps and re-base the labels
    /// and the fixups recorded from `base` onward (the collapse shifts the
    /// remaining steps). A label placed strictly inside a run would lose its
    /// target to the collapse, so the body stays unsegmented then.
    fn apply_register_runs(
        &mut self,
        base: usize,
        body_fixups: usize,
        runs: Vec<(usize, usize, Box<[LeafOp]>)>,
    ) {
        if runs.is_empty() {
            return;
        }
        let runs: Vec<(usize, usize, Box<[LeafOp]>)> = runs
            .into_iter()
            .map(|(start, end, ops)| (start + base, end + base, ops))
            .collect();
        // A jump target (a label) strictly inside a run cannot be patched to
        // the middle of a register body — keep the whole body on the step
        // path.
        if self.labels.values().any(|&label| {
            runs.iter()
                .any(|(start, end, _)| *start < label && label < *end)
        }) {
            return;
        }
        // The number of steps each run absorbs, and the cumulative absorbed
        // count before a position (runs are disjoint, in order).
        let absorbed_at = |pos: usize| {
            runs.iter()
                .filter(|(_, end, _)| *end <= pos)
                .map(|(start, end, _)| end - start - 1)
                .sum::<usize>()
        };
        // Collapse each run from the end backwards (the earlier offsets stay
        // valid during the splices).
        for (start, end, ops) in runs.iter().rev() {
            let step = Step::RunRegBody { ops: ops.clone() };
            self.steps.splice(*start..*end, std::iter::once(step));
        }
        // Re-base the labels (step indices) and the body's fixup step
        // indices by the absorbed count before each.
        for label in self.labels.values_mut() {
            *label -= absorbed_at(*label);
        }
        for fixup in &mut self.fixups[body_fixups..] {
            let index = Self::fixup_index(fixup);
            *index -= absorbed_at(*index);
        }
    }

    /// The interned "length" atom, cached once (the hoist eligibility check
    /// runs per `for` compile).
    fn length_atom() -> crux::AtomId {
        use std::sync::OnceLock;
        static LENGTH: OnceLock<crux::AtomId> = OnceLock::new();
        *LENGTH.get_or_init(|| crux::string::intern_utf8("length"))
    }

    /// Reserve a fresh hidden frame slot beyond the named bindings (gap-close
    /// M6 slice 2): `Compiler.scope` is owned, and the frame is sized from
    /// `ScopeInfo::frame_size` only when a compiled body runs, so growing it
    /// mid-compile is sound (the slot initializes `undefined`; hidden slots
    /// never carry the TDZ marker and never appear in leaf bodies).
    fn alloc_hoist_slot(&mut self) -> usize {
        let scope = self
            .scope
            .as_mut()
            .expect("a hoist requires a certified body");
        let slot = scope.frame_size;
        scope.frame_size += 1;
        scope.tdz_store.push(false);
        slot
    }

    /// Whether the loop qualifies for the typed-array `length`-limit hoist
    /// (gap-close M6 slice 2): a certified `for (var …; K <op> RECV.length;
    /// K++)` where RECV is a frame slot that the loop never assigns and the
    /// body + update are "length-pure" (no calls — nothing can detach/
    /// resize/define-`length` the view — and member access only as
    /// `RECV.length` reads or `RECV[expr] = v` stores, which cannot change
    /// the accessor-served length). Returns the receiver's frame slot.
    fn hoistable_length_loop(
        &self,
        init: Option<&ForInit>,
        test: Option<&Expr>,
        update: Option<&Expr>,
        body: &Stmt,
    ) -> Option<usize> {
        let length_atom = Self::length_atom();
        // A `var` head (a lexical head's per-iteration env machinery would
        // need duplicating across the two loop copies; keep to the common
        // shape).
        let head_names: Vec<crux::AtomId> = match init {
            Some(ForInit::VarDecl {
                kind: VarDeclKind::Var,
                decls,
            }) => decls
                .iter()
                .filter_map(|decl| match &decl.pattern {
                    BindingPattern::Ident(name) => Some(*name),
                    _ => None,
                })
                .collect(),
            _ => return None,
        };
        if head_names.is_empty() {
            return None;
        }
        // The test: `K <op> RECV.length` (a name-keyed, non-optional member
        // read of the `length` atom — the only property whose read the guard
        // probes).
        let (_, left, right) = match test {
            Some(Expr {
                kind: ExprKind::Binary { op, left, right },
                ..
            }) if matches!(
                op,
                BinaryOp::LessThan
                    | BinaryOp::LessEqual
                    | BinaryOp::GreaterThan
                    | BinaryOp::GreaterEqual
            ) =>
            {
                (op, left, right)
            }
            _ => return None,
        };
        let ExprKind::Ident(counter) = &left.kind else {
            return None;
        };
        let ExprKind::Member(MemberExpr {
            object,
            property: MemberProperty::Name(prop),
            optional: false,
            ..
        }) = &right.kind
        else {
            return None;
        };
        if *prop != length_atom {
            return None;
        }
        let ExprKind::Ident(recv_name) = &object.kind else {
            return None;
        };
        if *recv_name == *counter || head_names.contains(recv_name) {
            return None;
        }
        // The head init runs AFTER the guard in the fast copy, so a call
        // there could mutate RECV — its initializer expressions must be pure
        // too.
        let head_pure = match init {
            Some(ForInit::VarDecl { decls, .. }) => decls.iter().all(|decl| {
                matches!(&decl.pattern, BindingPattern::Ident(_))
                    && decl
                        .init
                        .as_ref()
                        .is_none_or(|init| expr_is_hoist_pure(init, *recv_name, length_atom))
            }),
            _ => false,
        };
        if !head_pure {
            return None;
        }
        // RECV must be a frame slot; the counter must not be the accumulator
        // of an enclosing loop (the recursion below compiles the head twice,
        // and an acc-path counter is a per-body singleton).
        let BindingLoc::Slot(recv_slot) = self.binding(*recv_name) else {
            return None;
        };
        if self.acc_binding.is_some() {
            return None;
        }
        // RECV is never assigned in the body, update, or head initializers
        // (a head re-declaration of RECV was excluded above; a head init
        // that writes RECV would leave the guard's hoisted length stale —
        // the fast copy probes RECV BEFORE the head init runs, so the scan
        // must cover those initializers too).
        let mut assigned = HashSet::new();
        collect_assigned_stmt(body, &mut assigned);
        if let Some(update) = update {
            collect_assigned_expr(update, &mut assigned);
        }
        if let Some(ForInit::VarDecl { decls, .. }) = init {
            for decl in decls {
                if let Some(init) = &decl.init {
                    collect_assigned_expr(init, &mut assigned);
                }
            }
        }
        if assigned.contains(recv_name) {
            return None;
        }
        // Body + update are length-pure.
        if !stmt_is_hoist_pure(body, *recv_name, length_atom)
            || update.is_some_and(|update| !expr_is_hoist_pure(update, *recv_name, length_atom))
        {
            return None;
        }
        Some(recv_slot)
    }

    /// Emit the hoisted loop (gap-close M6 slice 2): a once-per-loop guard
    /// probes `RECV.length` (the exact typed-array probe — an IntegerIndexed
    /// object with no own `length`); on a hit the length lands in a fresh
    /// hidden frame slot and the SAME for-loop re-compiles with its test
    /// limit read from that slot (the existing fused canonical loop —
    /// `RelLimit::Slot`), on a miss it re-compiles unchanged as the general
    /// per-iteration loop (only one of the two copies ever runs). Both copies
    /// re-emit the head init, so each starts its counter fresh; the body
    /// compiles identically in both (its `RECV.length` reads re-resolve
    /// exactly each iteration).
    fn compile_hoisted_length_for(
        &mut self,
        init: Option<&ForInit>,
        test: Option<&Expr>,
        update: Option<&Expr>,
        body: &Stmt,
        recv_slot: usize,
    ) -> Result<(), JsError> {
        self.emit(Step::ResetCompletion);
        // The guard: pop RECV, push its effective length on a probe hit.
        self.emit(Step::LoadLocal { slot: recv_slot });
        let miss_label = self.new_label();
        let guard_index = self.steps.len();
        self.emit(Step::TypedArrayLengthHoist { target: 0 });
        self.fixups.push(Fixup::TypedArrayLengthHoist {
            index: guard_index,
            label: miss_label,
        });
        // Stash the hoisted length in a fresh hidden slot.
        let hoist_slot = self.alloc_hoist_slot();
        self.emit(Step::InitLocal { slot: hoist_slot });
        // Bind a synthetic (NUL-prefixed — impossible in source) name to the
        // hidden slot so the fast copy's test `K <op> HIDDEN` resolves
        // `RelLimit::Slot` and takes the fused canonical loop.
        let hoist_name = crux::intern_utf8(&format!("\u{0}hoist{hoist_slot}"));
        self.scope
            .as_mut()
            .expect("a hoist requires a certified body")
            .slots
            .insert(hoist_name, hoist_slot);
        let Some(Expr {
            span,
            kind: ExprKind::Binary { op, left, .. },
        }) = test
        else {
            unreachable!("hoistable_length_loop requires a test")
        };
        let fake_test = Expr {
            span: *span,
            kind: ExprKind::Binary {
                op: *op,
                left: left.clone(),
                right: Box::new(Expr {
                    span: *span,
                    kind: ExprKind::Ident(hoist_name),
                }),
            },
        };
        let done_label = self.new_label();
        // Fast copy: the fused canonical loop against the hoisted limit, with
        // the body's `RECV.length` reads lowered to the hidden slot (gap-close
        // M6 slice 3 — the probe hit + body purity make the length
        // loop-invariant). Save/restore so a nested hoisted loop inside this
        // copy re-establishes its own redirect and the outer one resumes.
        let saved = self.hoisted_length;
        self.hoisted_length = Some((recv_slot, hoist_slot));
        self.compile_for(init, Some(&fake_test), update, body)?;
        self.hoisted_length = saved;
        self.jump(done_label);
        // Fallback copy: the original per-iteration member test. Suppress the
        // re-hoist (the test is the same eligible shape) — the suppression
        // also covers any nested loops in this copy, which is merely
        // conservative.
        self.place(miss_label);
        let saved = self.hoist_suppressed;
        self.hoist_suppressed = true;
        self.compile_for(init, test, update, body)?;
        self.hoist_suppressed = saved;
        self.place(done_label);
        Ok(())
    }

    /// Compile a `for` body. A braced block whose statements never transfer
    /// control out of it compiles without the statement-list wrapper: its
    /// per-iteration `ListBegin`/`ListEnd` would only save/restore the
    /// running completion when a statement list ends empty, and an iteration
    /// body that can end empty (only empty/declaration statements — control
    /// statements normalize their own completion) ends empty from the loop's
    /// empty register on every iteration, so the restore never changes the
    /// result. A body with a `break`/`continue`/`return`/`throw` — or a
    /// `yield`/`await` that can resume with one — skips the `ListEnd` on
    /// that transfer, so its push must stay.
    fn compile_for_body(&mut self, body: &Stmt) -> Result<(), JsError> {
        if let StmtKind::Block(block) = &body.kind
            && !stmt_contains_suspension(body)
            && block.stmts.iter().all(stmt_has_no_outgoing_transfer)
        {
            self.compile_block_contents(block)
        } else {
            self.compile_statement(body)
        }
    }

    fn compile_for(
        &mut self,
        init: Option<&ForInit>,
        test: Option<&Expr>,
        update: Option<&Expr>,
        body: &Stmt,
    ) -> Result<(), JsError> {
        // Gap-close M6 slice 2: hoist a certified loop's typed-array
        // `length` test limit. The hoist needs its own emission (a guard +
        // two loop copies), so the eligible shape returns before the normal
        // path. `hoist_suppressed` stops the fallback loop's own re-hoist
        // (its test is the original member shape).
        if !self.hoist_suppressed
            && let Some(recv_slot) = self.hoistable_length_loop(init, test, update, body)
        {
            return self.compile_hoisted_length_for(init, test, update, body, recv_slot);
        }
        self.emit(Step::ResetCompletion);
        let mut has_loop_env = false;
        let mut per_iteration: Vec<JsString> = Vec::new();
        // The certified per-iteration path emits `EnterPerIteration` for the
        // first env (the env path emits `PerIteration` after `EnterLoopEnv`).
        let mut per_iteration_entered = false;
        match init {
            None => {}
            Some(ForInit::Expr(expr)) => {
                self.compile_expr(expr)?;
                self.emit(Step::Pop);
            }
            Some(ForInit::VarDecl { kind, decls }) => {
                if *kind == VarDeclKind::Var {
                    for decl in decls {
                        if let Some(init) = &decl.init {
                            // Cut 3/5 fast path: a `var` head binding is a
                            // fast binding (hoisted, undefined — or a global
                            // property instantiation created), so the
                            // initializer writes it directly — `Destructure`
                            // would walk the env for a binding the fast path
                            // never created. The resolve-before-init rule is
                            // only observable via a `with` scope (excluded
                            // from the fast path).
                            if let BindingPattern::Ident(name) = &decl.pattern {
                                match self.binding(*name) {
                                    BindingLoc::Slot(slot) => {
                                        self.compile_expr(init)?;
                                        self.emit(Step::InitLocal { slot });
                                        continue;
                                    }
                                    BindingLoc::Context(0, index) => {
                                        self.compile_expr(init)?;
                                        self.emit(Step::InitContextSlot { index });
                                        continue;
                                    }
                                    BindingLoc::Global => {
                                        self.compile_expr(init)?;
                                        self.emit(Step::StoreGlobal { name: *name });
                                        continue;
                                    }
                                    // A for-head over an active accumulator
                                    // counter is rejected by the loop-body
                                    // scan.
                                    BindingLoc::Acc => {
                                        unreachable!("a nested for-head cannot rebind its counter")
                                    }
                                    // A `var` head's name is bound in this
                                    // body, never an enclosing body's capture.
                                    BindingLoc::Context(_, _)
                                    | BindingLoc::CapturedIteration(_, _) => {
                                        unreachable!("a for-head cannot bind an outer context")
                                    }
                                    BindingLoc::Env => {}
                                }
                            }
                            self.compile_expr(init)?;
                            if self.scope.is_some() {
                                // Cut 59: a certified body's var-pattern head
                                // compiles the primitive steps with flat
                                // slot/context binds (the wholesale
                                // `Destructure` binds through the env).
                                self.compile_destructure_binding(&decl.pattern, false)?;
                            } else {
                                self.emit(Step::Destructure {
                                    pattern: decl.pattern.clone(),
                                });
                                // The head initializer's value is discarded
                                // (`Destructure` re-pushed it) — without the
                                // pop an env-path `for` head leaves a handle
                                // on the stack for the loop's duration.
                                self.emit(Step::Pop);
                            }
                        }
                    }
                } else if *kind == VarDeclKind::Using || *kind == VarDeclKind::AwaitUsing {
                    // A `using` head needs the loop environment for the
                    // disposal machinery (the certification rejects
                    // `using`, so its bindings are never slots).
                    self.emit(Step::EnterLoopEnv {
                        kind: *kind,
                        decls: decls.clone(),
                    });
                    self.scope_count += 1;
                    has_loop_env = true;
                } else {
                    // A lexical head whose bindings are certified frame
                    // slots (no closures — the per-iteration freshness is
                    // unobservable) initializes the slots directly, skipping
                    // the per-iteration environment machinery. A head
                    // binding a body closure captures runs through
                    // per-iteration envs (fresh copies the closures
                    // observe); anything else keeps the env path below.
                    let all_slots = decls.iter().all(|decl| {
                        matches!(
                            &decl.pattern,
                            BindingPattern::Ident(name)
                                if matches!(self.binding(*name), BindingLoc::Slot(_))
                        )
                    });
                    let has_context = decls.iter().any(|decl| {
                        matches!(
                            &decl.pattern,
                            BindingPattern::Ident(name)
                                if matches!(self.binding(*name), BindingLoc::Context(0, _))
                        )
                    });
                    if all_slots {
                        for decl in decls {
                            if let Some(init) = &decl.init {
                                self.compile_expr(init)?;
                            } else {
                                // `for (let i; ...)`: the binding initializes
                                // to *undefined* (spec 14.2.1 step 4).
                                self.emit(Step::Push(Value::Undefined));
                            }
                            let BindingPattern::Ident(name) = decl.pattern else {
                                unreachable!("all_slots checked the pattern")
                            };
                            let BindingLoc::Slot(slot) = self.binding(name) else {
                                unreachable!("all_slots checked the binding")
                            };
                            self.emit(Step::InitLocal { slot });
                        }
                    } else if has_context {
                        // Cut 3 continuation (per-iteration loop heads): a
                        // closure in the body captures the head binding, so
                        // each iteration needs a fresh env holding it. The
                        // head inits write the capture-context slots the
                        // first per-iteration env copies from; the body's
                        // own reads/writes of the captured head go through
                        // the per-iteration env (the non-captured heads in
                        // the same head list stay frame slots — their
                        // freshness is unobservable).
                        let mut heads: Vec<crux::AtomId> = Vec::new();
                        for decl in decls {
                            if let Some(init) = &decl.init {
                                self.compile_expr(init)?;
                            } else {
                                self.emit(Step::Push(Value::Undefined));
                            }
                            let BindingPattern::Ident(name) = decl.pattern else {
                                unreachable!("the certified scan only allows ident heads")
                            };
                            match self.binding(name) {
                                BindingLoc::Slot(slot) => {
                                    self.emit(Step::InitLocal { slot });
                                }
                                BindingLoc::Context(0, index) => {
                                    self.emit(Step::InitContextSlot { index });
                                    heads.push(name);
                                }
                                _ => unreachable!(
                                    "a certified lexical head binds a slot or the capture context"
                                ),
                            }
                        }
                        per_iteration_entered = true;
                        let names: Vec<JsString> =
                            heads.iter().map(|id| crux::lookup(*id)).collect();
                        self.scope_count += 1;
                        has_loop_env = true;
                        self.per_iteration_heads.push(heads);
                        per_iteration.extend(names);
                    } else if self.scope.is_some() {
                        // Cut 59: a certified LEXICAL pattern head (the scan
                        // rejects one whose names a body closure captures —
                        // per-iteration freshness covers only ident heads)
                        // compiles the primitive steps with flat binds; the
                        // per-iteration envs are unobservable without
                        // closures.
                        for decl in decls {
                            if let Some(init) = &decl.init {
                                self.compile_expr(init)?;
                            } else {
                                self.emit(Step::Push(Value::Undefined));
                            }
                            self.compile_destructure_binding(&decl.pattern, true)?;
                        }
                    } else {
                        self.emit(Step::EnterLoopEnv {
                            kind: *kind,
                            decls: decls.clone(),
                        });
                        self.scope_count += 1;
                        has_loop_env = true;
                        for decl in decls {
                            // `const` heads share one binding — the update
                            // would otherwise mutate a per-iteration copy
                            // instead of throwing on the immutable binding
                            // (spec 14.7.4.2, mirroring the tree-walker).
                            if *kind == VarDeclKind::Const {
                                continue;
                            }
                            let mut names = Vec::new();
                            crate::script::bound_names(&decl.pattern, &mut names);
                            per_iteration.extend(names);
                        }
                    }
                }
            }
        }
        if per_iteration_entered {
            self.emit(Step::EnterPerIteration {
                names: per_iteration.clone(),
            });
        } else if !per_iteration.is_empty() {
            self.emit(Step::PerIteration {
                names: per_iteration.clone(),
            });
        }
        let test_label = self.new_label();
        let continue_label = self.new_label();
        let end_label = self.new_label();
        let break_count = self.scope_count;
        let continue_count = self.scope_count;
        self.scope_stack.push(Scope::Loop {
            break_target: end_label,
            break_count,
            continue_target: continue_label,
            continue_count,
        });
        self.resolve_labeled_continue(continue_label, continue_count);
        self.place(test_label);
        match test {
            Some(test) => {
                // The fused canonical loop: `for (var i = INIT; i <op>
                // LIMIT; i++)` with a simple body — one dispatch per
                // iteration (test + nested body + increment). Lexical heads
                // stay on the regular path (per-iteration freshness).
                let fast_head = match init {
                    None => true,
                    Some(ForInit::Expr(_)) => true,
                    Some(ForInit::VarDecl { kind, .. }) => *kind == VarDeclKind::Var,
                };
                if fast_head
                    && let Some(FastLoopShape {
                        var,
                        loc,
                        name,
                        op,
                        limit,
                        inc,
                    }) = self.compile_fast_loop(test, update)?
                {
                    // Cut 17: when the counter is a frame slot (never a
                    // global — the stale-global window would be observable
                    // through calls/`globalThis` in non-slotified scripts)
                    // and can live in the VM accumulator for the loop's
                    // duration (no enclosing accumulator loop, and the body
                    // only reads it or assigns/updates it in statement
                    // position), the head works on the accumulator — no
                    // frame round-trip per iteration.
                    if matches!(var, FastLoopVar::Slot(_))
                        && self.acc_binding.is_none()
                        // Cut 35 slice 22: the acc-path counter lives in an
                        // f64 field, so the init must be a Number (the slot
                        // path handles non-Number counters).
                        && for_init_counter_number(init, name)
                        && self.acc_body_safe(body, name)
                        // The acc path syncs the counter to the binding only
                        // at the loop's end step, so a body that can
                        // transfer to a label outside the loop (a labeled
                        // break/continue to an enclosing label — past that
                        // step) must stay on the slot path, whose head
                        // writes the binding every iteration.
                        && acc_body_label_transfers_inside(body)
                    {
                        // The counter prologue loads the binding (just
                        // written by the loop init) into the accumulator
                        // before the initial test, so a zero-iteration loop
                        // still stores the init value back.
                        self.emit(Step::FastLoopBind { var });
                        self.emit_fused_rel_test(op, loc, name, limit, end_label);
                        let body_start = self.new_label();
                        self.place(body_start);
                        let saved = self.acc_binding.replace(name);
                        let body_steps = self.steps.len();
                        let body_fixups = self.fixups.len();
                        self.compile_for_body(body)?;
                        // Cut 35 slice 9: a body that lowers to register ops
                        // runs on the register executor in one dispatch
                        // (`RunRegBody` saves/restores the accumulator
                        // counter). `lower_leaf_ops_segmented` splits the
                        // body into maximal straight-line runs, so a
                        // control-flow statement (an `if`, a break) keeps
                        // the surrounding statements on the register path.
                        if let Some(scope) = self.scope.as_ref() {
                            let runs = lower_leaf_ops_segmented(&self.steps[body_steps..], scope);
                            self.apply_register_runs(body_steps, body_fixups, runs);
                        }
                        self.acc_binding = saved;
                        self.place(continue_label);
                        let index = self.steps.len();
                        self.emit(Step::FastLoopHead {
                            var: FastLoopVar::Counter,
                            op,
                            limit,
                            inc,
                            body_start,
                            after: end_label,
                        });
                        self.fixups
                            .push(Fixup::FastLoopHead(index, body_start, end_label));
                        // The store sits on the `end_label` path, so a
                        // `break` writes the counter back too (a `continue`
                        // skips it via the head's back-jump).
                        self.place(end_label);
                        self.emit(Step::FastLoopStore { var });
                        self.emit(Step::NormalizeCompletion);
                        self.scope_stack.pop();
                        return Ok(());
                    }
                    // The fused canonical loop: the initial test (the
                    // existing fused step), the inline body, then the
                    // per-iteration head — increment, re-test, and the
                    // back-jump in one dispatch. The continue target is the
                    // head (a `continue` skips to the increment).
                    self.emit_fused_rel_test(op, loc, name, limit, end_label);
                    let body_start = self.new_label();
                    self.place(body_start);
                    self.compile_for_body(body)?;
                    self.place(continue_label);
                    let index = self.steps.len();
                    self.emit(Step::FastLoopHead {
                        var,
                        op,
                        limit,
                        inc,
                        body_start,
                        after: end_label,
                    });
                    self.fixups
                        .push(Fixup::FastLoopHead(index, body_start, end_label));
                    self.place(end_label);
                    self.emit(Step::NormalizeCompletion);
                    self.scope_stack.pop();
                    return Ok(());
                }
                if let Some((op, loc, name, imm)) = self.fused_rel_test(test) {
                    // Cut 4/5: the loop test `binding <op> imm` fuses with
                    // the false-jump (LoadLocal/LoadGlobal + BinaryImm +
                    // JumpIfFalse).
                    self.emit_fused_rel_test(op, loc, name, imm, end_label);
                } else {
                    self.compile_expr(test)?;
                    self.jump_if_false(end_label);
                }
            }
            None => self.emit(Step::Push(Value::Boolean(true))),
        }
        self.compile_for_body(body)?;
        self.place(continue_label);
        if !per_iteration.is_empty() {
            self.emit(Step::PerIteration {
                names: per_iteration.clone(),
            });
        }
        if let Some(update) = update {
            if let Some((loc, name, op)) = self.fused_update(update) {
                // Cut 4/5: the update's value is discarded by the loop
                // protocol, so a bare `i++`/`i--` on a fast binding fuses to
                // one step (no result push to pop). `i += 1` stays on the
                // general path (`+=` concatenates strings, `++` does not).
                let step = match (loc, op) {
                    (BindingLoc::Slot(slot), UpdateOp::Increment) => Step::Inc { slot },
                    (BindingLoc::Slot(slot), UpdateOp::Decrement) => Step::Dec { slot },
                    (BindingLoc::Global, UpdateOp::Increment) => Step::IncGlobal { name },
                    (BindingLoc::Global, UpdateOp::Decrement) => Step::DecGlobal { name },
                    (BindingLoc::Acc, _) => {
                        unreachable!("fused_update on the accumulator (the scan rejects it)")
                    }
                    (BindingLoc::Context(_, _) | BindingLoc::CapturedIteration(_, _), _) => {
                        unreachable!("fused_update on a captured binding (the scan rejects it)")
                    }
                    (BindingLoc::Env, _) => unreachable!("fused_update on the environment path"),
                };
                self.emit(step);
            } else {
                self.compile_expr(update)?;
                self.emit(Step::Pop);
            }
        }
        self.jump(test_label);
        if per_iteration_entered {
            // The loop body compiled with the captured-head names resolving
            // to per-iteration env steps; the machinery is closed now.
            self.per_iteration_heads.pop();
        }
        self.place(end_label);
        self.emit(Step::NormalizeCompletion);
        self.scope_stack.pop();
        if has_loop_env {
            self.scope_count -= 1;
            self.emit(Step::LeaveBlock);
        }
        Ok(())
    }

    /// The certified for-of/for-in head bind: the element/key (already on
    /// the stack) writes its binding directly. A `var` head writes the
    /// slot/global/context binding; an uncaptured lexical head re-inits its
    /// flat slot each iteration (the write is the initialization, so no TDZ
    /// check); a captured lexical head writes the current per-iteration env
    /// (a fresh copy the body's closures observe).
    fn emit_certified_for_bind(&mut self, name: crux::AtomId, kind: VarDeclKind) {
        let lexical = kind != VarDeclKind::Var;
        match self.binding(name) {
            BindingLoc::Slot(slot) => self.emit(Step::ForOfBindLocal { slot }),
            BindingLoc::Global => self.emit(Step::ForOfBindGlobal { name }),
            BindingLoc::Context(0, _) if lexical => {
                let (depth, index) = match self.per_iteration(name) {
                    Some(loc) => loc,
                    None => unreachable!("a captured lexical for-of/in head is registered"),
                };
                self.emit(Step::StorePerIteration { depth, index });
            }
            BindingLoc::Context(0, index) => self.emit(Step::InitContextSlot { index }),
            _ => unreachable!(
                "a certified for-of/in head binds a slot, global, or the capture context"
            ),
        }
    }

    /// The shared certified for-of/for-in loop shape (the scan guarantees
    /// an Ident VarDecl head): the element/key binds directly to the head's
    /// slot/context/global — no TDZ environment (the head's slot/context
    /// marker reproduces the RHS TDZ), and no per-iteration environments
    /// unless a body closure captures the head (then each iteration's
    /// binding is a fresh copy the closures observe, mirroring the
    /// certified `For`).
    ///
    /// `per_iteration` names are the captured lexical head names (empty for
    /// var/uncaptured heads); the caller emits the iteration-protocol step
    /// that pushes each element/key.
    fn compile_certified_for_loop(
        &mut self,
        left: &ForBinding,
        body: &Stmt,
        emit_next: Step,
        protocol_entered: bool,
    ) -> Result<(usize, usize), JsError> {
        let ForBinding::VarDecl { kind, pattern, .. } = left else {
            unreachable!("the certified scan only allows Ident VarDecl for-of/in heads")
        };
        let BindingPattern::Ident(name) = pattern else {
            unreachable!("the certified scan only allows Ident for-of/in heads")
        };
        let lexical = *kind != VarDeclKind::Var;
        let captured = matches!(self.binding(*name), BindingLoc::Context(0, _));
        let mut per_iteration: Vec<JsString> = Vec::new();
        if lexical && captured {
            // The capture-context slot is TDZ'd at entry and EnterPerIteration
            // copies it, so pre-init it with undefined — the only TDZ window
            // (the RHS) already ran, and the first bind overwrites it.
            let BindingLoc::Context(0, index) = self.binding(*name) else {
                unreachable!("a captured lexical head is in the capture context")
            };
            self.emit(Step::Push(Value::Undefined));
            self.emit(Step::InitContextSlot { index });
            self.scope_count += 1;
            self.per_iteration_heads.push(vec![*name]);
            per_iteration.push(crux::lookup(*name));
            self.emit(Step::EnterPerIteration {
                names: per_iteration.clone(),
            });
        }
        let top_label = self.new_label();
        let end_label = self.new_label();
        let continue_label = self.new_label();
        let done_label = self.new_label();
        let scope = self.scope_count;
        self.scope_stack.push(Scope::Iteration {
            open: scope,
            closed: scope,
            continue_target: continue_label,
            break_target: end_label,
        });
        self.resolve_labeled_continue(continue_label, scope);
        self.place(top_label);
        let step_index = self.steps.len();
        // Cut 21: a for-of head bound to a frame slot fuses the protocol
        // step and the bind — the element writes the slot directly, one less
        // dispatch and no value-stack round-trip per element (the dense-array
        // bench inner-loop hot path).
        let fused_slot = match &emit_next {
            Step::ForOfNext { .. } => match self.binding(*name) {
                BindingLoc::Slot(slot) => Some(slot),
                _ => None,
            },
            _ => None,
        };
        if let Some(slot) = fused_slot {
            self.emit(Step::ForOfNextBindLocal {
                slot,
                done: 0,
                back: 0,
            });
            self.fixups
                .push(Fixup::ForOfNextBindLocal(step_index, done_label));
        } else {
            self.emit(emit_next.clone());
            match &emit_next {
                Step::ForInNext { .. } => {
                    self.fixups.push(Fixup::ForInNext(step_index, done_label))
                }
                Step::ForOfNext { .. } => {
                    self.fixups.push(Fixup::ForOfNext(step_index, done_label))
                }
                _ => unreachable!("the certified loop protocol step is ForInNext or ForOfNext"),
            }
            self.emit_certified_for_bind(*name, *kind);
        }
        // Cut 35 slice 18: the do-while back target — the step right after
        // the fetch (the head bind, or the body start when fused). Both the
        // prologue fetch and the per-iteration fetch at the loop bottom
        // share it, so a successful fetch continues straight at the bind /
        // body start with no per-element back-jump.
        let back = step_index + 1;
        match &mut self.steps[step_index] {
            Step::ForInNext { back: target, .. }
            | Step::ForOfNext { back: target, .. }
            | Step::ForOfNextBindLocal { back: target, .. } => *target = back,
            _ => unreachable!("the certified loop protocol step is ForInNext or ForOfNext"),
        }
        let body_steps = self.steps.len();
        let body_fixups = self.fixups.len();
        self.compile_statement(body)?;
        // Cut 35 slice 9: a body that lowers to register ops runs on the
        // register executor in one dispatch (`RunRegBody` saves/restores
        // the enclosing accumulator-loop counter). `lower_leaf_ops_segmented`
        // splits the body into maximal straight-line runs, so a
        // control-flow statement (an `if`, a break/continue) keeps the
        // surrounding statements on the register path.
        if let Some(scope) = self.scope.as_ref() {
            let runs = lower_leaf_ops_segmented(&self.steps[body_steps..], scope);
            self.apply_register_runs(body_steps, body_fixups, runs);
        }
        self.place(continue_label);
        if lexical && captured {
            self.emit(Step::PerIteration {
                names: per_iteration.clone(),
            });
        }
        // Cut 35 slice 18: the do-while back edge — the per-iteration fetch
        // at the loop bottom re-runs the protocol step in place of the old
        // `Jump(top_label)`, so a straight-line body has no per-element jump
        // dispatch. Its `back` targets the head bind / body start above; a
        // `continue` falls into the copy (captured heads) and the fetch.
        let loop_fetch = self.steps.len();
        if let Some(slot) = fused_slot {
            self.emit(Step::ForOfNextBindLocal {
                slot,
                done: 0,
                back,
            });
            self.fixups
                .push(Fixup::ForOfNextBindLocal(loop_fetch, done_label));
        } else {
            match &emit_next {
                Step::ForInNext { .. } => {
                    self.emit(Step::ForInNext { done: 0, back });
                    self.fixups.push(Fixup::ForInNext(loop_fetch, done_label));
                }
                Step::ForOfNext { .. } => {
                    self.emit(Step::ForOfNext { done: 0, back });
                    self.fixups.push(Fixup::ForOfNext(loop_fetch, done_label));
                }
                _ => unreachable!("the certified loop protocol step is ForInNext or ForOfNext"),
            }
        }
        self.place(end_label);
        if lexical && captured {
            self.emit(Step::LeaveBlock);
        }
        if protocol_entered {
            self.emit(Step::ForOfClose);
        }
        self.emit(Step::NormalizeCompletion);
        self.place(done_label);
        if lexical && captured {
            self.emit(Step::LeaveBlock);
        }
        self.emit(Step::NormalizeCompletion);
        self.scope_stack.pop();
        if lexical && captured {
            self.scope_count -= 1;
            self.per_iteration_heads.pop();
        }
        Ok((top_label, end_label))
    }

    fn compile_certified_for_in(
        &mut self,
        left: &ForBinding,
        right: &Expr,
        body: &Stmt,
    ) -> Result<(), JsError> {
        // Annex B.2.6: `for (var a = init in expr)` — the initializer runs
        // once and binds `a` before the RHS is evaluated (sloppy mode only).
        if let ForBinding::VarDecl {
            init: Some(init_expr),
            ..
        } = left
        {
            let ForBinding::VarDecl { kind, pattern, .. } = left else {
                unreachable!("Annex B for-in heads are VarDecl")
            };
            let BindingPattern::Ident(name) = pattern else {
                unreachable!("the certified scan only allows Ident for-in heads")
            };
            self.compile_expr(init_expr)?;
            self.emit_certified_for_bind(*name, *kind);
        }
        self.compile_expr(right)?;
        self.emit(Step::ForInBegin);
        self.compile_certified_for_loop(left, body, Step::ForInNext { done: 0, back: 0 }, false)?;
        Ok(())
    }

    fn compile_certified_for_of(
        &mut self,
        left: &ForBinding,
        right: &Expr,
        body: &Stmt,
    ) -> Result<(), JsError> {
        self.compile_expr(right)?;
        self.emit(Step::ForOfBegin { top: 0, end: 0 });
        let begin_index = self.steps.len() - 1;
        let (top, end) = self.compile_certified_for_loop(
            left,
            body,
            Step::ForOfNext { done: 0, back: 0 },
            true,
        )?;
        self.fixups
            .push(Fixup::ForOfBoundary(begin_index, top, end));
        Ok(())
    }

    fn compile_for_in(
        &mut self,
        left: &ForBinding,
        right: &Expr,
        body: &Stmt,
    ) -> Result<(), JsError> {
        self.emit(Step::ResetCompletion);
        // Certified body: the scan accepted an Ident VarDecl head (any other
        // head shape would have bailed it) — bind directly, skipping the TDZ
        // environment (the head's slot/context marker reproduces the RHS
        // TDZ) and the per-iteration environments unless a body closure
        // captures the head.
        if self.scope.is_some() {
            return self.compile_certified_for_in(left, right, body);
        }
        // Annex B.2.6: `for (var a = init in expr)` — the initializer runs
        // once and binds `a` before the RHS is evaluated (sloppy mode only).
        if let ForBinding::VarDecl {
            kind: VarDeclKind::Var,
            pattern,
            init: Some(init_expr),
            ..
        } = left
        {
            self.compile_expr(init_expr)?;
            self.emit(Step::ForInBind {
                left: ForBinding::VarDecl {
                    kind: VarDeclKind::Var,
                    pattern: pattern.clone(),
                    init: None,
                },
            });
        }
        let tdz = self.enter_iter_tdz_env(left);
        self.compile_expr(right)?;
        self.leave_iter_tdz_env(tdz);
        self.emit(Step::ForInBegin);
        let top_label = self.new_label();
        let end_label = self.new_label();
        let continue_label = self.new_label();
        let done_label = self.new_label();
        // A lexical head pushes a per-iteration environment on the stack that
        // counts as one scope for the body, so every exit — fall-through,
        // continue, break, labeled break — unwinds it with the same
        // LeaveBlock/restore machinery (spec 14.7.5.5 step 6). The exhausted
        // path (done_label) needs no restore: the last iteration's
        // fall-through or continue already ran it.
        let lexical_head = matches!(
            left,
            ForBinding::VarDecl { kind, .. } if *kind != VarDeclKind::Var
        );
        let scope = self.scope_count + usize::from(lexical_head);
        self.scope_stack.push(Scope::Iteration {
            open: scope,
            closed: scope,
            continue_target: continue_label,
            break_target: end_label,
        });
        self.resolve_labeled_continue(continue_label, scope);
        self.place(top_label);
        let step_index = self.steps.len();
        self.emit(Step::ForInNext {
            done: 0,
            back: step_index + 1,
        });
        self.fixups.push(Fixup::ForInNext(step_index, done_label));
        self.emit(Step::ForInBind { left: left.clone() });
        if lexical_head {
            self.scope_count += 1;
        }
        self.compile_statement(body)?;
        self.place(continue_label);
        if lexical_head {
            self.emit(Step::ForInRestore);
            self.scope_count -= 1;
        }
        self.jump(top_label);
        self.place(end_label);
        if lexical_head {
            self.emit(Step::ForInRestore);
        }
        self.emit(Step::NormalizeCompletion);
        self.place(done_label);
        self.emit(Step::NormalizeCompletion);
        self.scope_stack.pop();
        Ok(())
    }

    fn compile_for_of(
        &mut self,
        left: &ForBinding,
        right: &Expr,
        body: &Stmt,
    ) -> Result<(), JsError> {
        self.emit(Step::ResetCompletion);
        // Certified body: the scan accepted an Ident VarDecl head (see
        // `compile_for_in`).
        if self.scope.is_some() {
            return self.compile_certified_for_of(left, right, body);
        }
        let tdz = self.enter_iter_tdz_env(left);
        self.compile_expr(right)?;
        self.leave_iter_tdz_env(tdz);
        self.emit(Step::ForOfBegin { top: 0, end: 0 });
        let top_label = self.new_label();
        let end_label = self.new_label();
        let done_label = self.new_label();
        let continue_label = self.new_label();
        let begin_index = self.steps.len() - 1;
        self.fixups
            .push(Fixup::ForOfBoundary(begin_index, top_label, end_label));
        // A lexical head pushes a per-iteration environment on the stack that
        // counts as one scope for the body, so every exit — fall-through,
        // continue, break, labeled break — unwinds it with the same
        // LeaveBlock/restore machinery (spec 14.7.5.6 step 6). The exhausted
        // path (done_label) needs no restore: the last iteration's
        // fall-through or continue already ran it.
        let lexical_head = matches!(
            left,
            ForBinding::VarDecl { kind, .. } if *kind != VarDeclKind::Var
        );
        let scope = self.scope_count + usize::from(lexical_head);
        self.scope_stack.push(Scope::Iteration {
            open: scope,
            closed: scope,
            continue_target: continue_label,
            break_target: end_label,
        });
        self.resolve_labeled_continue(continue_label, scope);
        self.place(top_label);
        let step_index = self.steps.len();
        self.emit(Step::ForOfNext {
            done: 0,
            back: step_index + 1,
        });
        self.fixups.push(Fixup::ForOfNext(step_index, done_label));
        // A destructuring head is compiled as steps (member targets and
        // defaults with `yield`/`await` need the resumable machinery).
        match left {
            ForBinding::Expr(expr)
                if matches!(expr.kind, ExprKind::Array(_) | ExprKind::Object(_)) =>
            {
                self.compile_destructure_assign(expr)?;
            }
            // A simple `var` ident head binds directly at its compile-time
            // location (frame slot / global cell), skipping the per-element
            // binding-initialization machinery.
            ForBinding::VarDecl {
                kind: VarDeclKind::Var,
                pattern: BindingPattern::Ident(name),
                ..
            } => match self.binding(*name) {
                BindingLoc::Global => self.emit(Step::ForOfBindGlobal { name: *name }),
                BindingLoc::Slot(slot) => self.emit(Step::ForOfBindLocal { slot }),
                // A for-of head over a captured binding resolves through the
                // environment like the env path (the binding is in the
                // capture context).
                BindingLoc::Context(_, _) => self.emit(Step::ForOfBind { left: left.clone() }),
                // A for-of head over an active accumulator counter is
                // rejected by the loop-body scan.
                BindingLoc::Acc => unreachable!("a for-of head cannot bind its counter"),
                BindingLoc::CapturedIteration(_, _) => {
                    self.emit(Step::ForOfBind { left: left.clone() })
                }
                BindingLoc::Env => self.emit(Step::ForOfBind { left: left.clone() }),
            },
            _ => self.emit(Step::ForOfBind { left: left.clone() }),
        }
        if lexical_head {
            self.scope_count += 1;
        }
        self.compile_statement(body)?;
        self.place(continue_label);
        if lexical_head {
            self.emit(Step::ForOfRestore);
            self.scope_count -= 1;
        }
        self.jump(top_label);
        self.place(end_label);
        if lexical_head {
            self.emit(Step::ForOfRestore);
        }
        self.emit(Step::ForOfClose);
        // The exhausted path jumped past the close (the iterator was already
        // popped by ForOfNext), so a `break` is the only way to reach it.
        self.place(done_label);
        self.emit(Step::NormalizeCompletion);
        self.scope_stack.pop();
        Ok(())
    }

    fn compile_async_for_of(
        &mut self,
        left: &ForBinding,
        right: &Expr,
        body: &Stmt,
    ) -> Result<(), JsError> {
        self.emit(Step::ResetCompletion);
        let tdz = self.enter_iter_tdz_env(left);
        self.compile_expr(right)?;
        self.leave_iter_tdz_env(tdz);
        self.emit(Step::AsyncForOfBegin { top: 0, end: 0 });
        let top_label = self.new_label();
        let end_label = self.new_label();
        let done_label = self.new_label();
        let continue_label = self.new_label();
        let begin_index = self.steps.len() - 1;
        self.fixups
            .push(Fixup::AsyncForOfBoundary(begin_index, top_label, end_label));
        // A lexical head pushes a per-iteration environment on the stack that
        // counts as one scope for the body, so every exit — fall-through,
        // continue, break, labeled break — unwinds it with the same
        // LeaveBlock/restore machinery. The exhausted path (done_label)
        // needs no restore: the last iteration's fall-through or continue
        // already ran it.
        let lexical_head = matches!(
            left,
            ForBinding::VarDecl { kind, .. } if *kind != VarDeclKind::Var
        );
        let scope = self.scope_count + usize::from(lexical_head);
        self.scope_stack.push(Scope::Iteration {
            open: scope,
            closed: scope,
            continue_target: continue_label,
            break_target: end_label,
        });
        self.resolve_labeled_continue(continue_label, scope);
        self.place(top_label);
        self.emit(Step::AsyncForOfNext);
        let step_index = self.steps.len();
        self.emit(Step::AsyncForOfTest { done: 0 });
        self.fixups
            .push(Fixup::AsyncForOfNext(step_index, done_label));
        // A destructuring head is compiled as steps (member targets and
        // defaults with `await` need the resumable machinery), mirroring the
        // sync for-of compiler.
        match left {
            ForBinding::Expr(expr)
                if matches!(expr.kind, ExprKind::Array(_) | ExprKind::Object(_)) =>
            {
                self.compile_destructure_assign(expr)?;
            }
            _ => self.emit(Step::AsyncForOfBind { left: left.clone() }),
        }
        if lexical_head {
            self.scope_count += 1;
        }
        self.compile_statement(body)?;
        self.place(continue_label);
        if lexical_head {
            self.emit(Step::AsyncForOfRestore);
            self.scope_count -= 1;
        }
        self.jump(top_label);
        self.place(end_label);
        if lexical_head {
            self.emit(Step::AsyncForOfRestore);
        }
        self.emit(Step::AsyncForOfClose);
        // The exhausted path jumped past the close (the iterator was already
        // popped by AsyncForOfTest), so a `break` is the only way to reach it.
        self.place(done_label);
        self.emit(Step::NormalizeCompletion);
        self.scope_stack.pop();
        Ok(())
    }

    fn compile_switch(&mut self, discriminant: &Expr, cases: &[SwitchCase]) -> Result<(), JsError> {
        self.emit(Step::ResetCompletion);
        self.compile_expr(discriminant)?;
        self.emit(Step::SwitchDisc);
        let all_stmts: Vec<Stmt> = cases.iter().flat_map(|c| c.consequent.clone()).collect();
        self.emit(Step::EnterBlock {
            decls: Self::block_decls(&all_stmts),
        });
        self.emit(Step::ListBegin);
        self.scope_count += 1;
        let end_label = self.new_label();
        let default_label = self.new_label();
        self.scope_stack.push(Scope::Switch {
            break_target: end_label,
            break_count: self.scope_count - 1,
        });
        let mut case_labels = Vec::new();
        for _case in cases {
            case_labels.push(self.new_label());
        }
        for (index, case) in cases.iter().enumerate() {
            if let Some(test) = &case.test {
                self.compile_expr(test)?;
                let step_index = self.steps.len();
                self.emit(Step::SwitchTest { case: 0 });
                self.fixups
                    .push(Fixup::SwitchTest(step_index, case_labels[index]));
            }
        }
        self.jump(default_label);
        let mut has_default = false;
        for (index, case) in cases.iter().enumerate() {
            self.place(case_labels[index]);
            if case.test.is_none() {
                // The no-match path lands on the default case's statements.
                self.place(default_label);
                has_default = true;
            }
            self.compile_statements(&case.consequent)?;
        }
        if !has_default {
            self.place(default_label);
        }
        self.scope_stack.pop();
        self.scope_count -= 1;
        self.emit(Step::LeaveBlock);
        self.emit(Step::ListEnd);
        self.place(end_label);
        self.emit(Step::NormalizeCompletion);
        Ok(())
    }

    fn compile_try(
        &mut self,
        block: &syntax::ast::Block,
        handler: Option<&syntax::ast::CatchClause>,
        finalizer: Option<&syntax::ast::Block>,
    ) -> Result<(), JsError> {
        let handler_index = self.handlers.len();
        self.handlers.push(Handler {
            start: 0,
            try_end: 0,
            catch: None,
            finally: None,
        });
        let start = self.steps.len();
        self.handlers[handler_index].start = start;
        self.emit(Step::EnterTry {
            handler: handler_index,
        });
        self.emit(Step::ResetCompletion);
        self.emit(Step::ListBegin);
        self.emit(Step::EnterBlock {
            decls: Self::block_decls(&block.stmts),
        });
        self.scope_count += 1;
        self.try_depth += 1;
        // A return in the try Block is never tail-safe: the enclosing
        // catch/finally must run after the call (and its handler coverage
        // would be lost by the frame replacement).
        let saved_safe = self.tail_safe_depth;
        self.tail_safe_depth = 0;
        self.compile_statements(&block.stmts)?;
        self.tail_safe_depth = saved_safe;
        self.try_depth -= 1;
        self.scope_count -= 1;
        self.emit(Step::LeaveBlock);
        self.emit(Step::ListEnd);
        let exit_index = self.steps.len();
        self.emit(Step::Exit { after: 0 });
        let after_label = self.new_label();
        self.fixups.push(Fixup::Exit(exit_index, after_label));
        self.handlers[handler_index].try_end = exit_index;

        if let Some(handler) = handler {
            let catch_start = self.steps.len();
            self.emit(Step::CatchBind {
                param: handler.param.clone(),
                decls: Self::block_decls(&handler.body.stmts),
            });
            self.emit(Step::ResetCompletion);
            self.emit(Step::ListBegin);
            // `CatchBind` pushes the block env, the parameter env and the
            // body env (3 for a binding catch, 1 for a bare catch) at
            // runtime — count them as one scope per env so an abrupt
            // control transfer's `leave_scopes` pops the whole chain (the
            // normal path pops them with the explicit `LeaveBlock`s below).
            self.scope_count += if handler.param.is_some() { 3 } else { 1 };
            self.try_depth += 1;
            // A catch is tail-safe only when its try has no finally (the
            // finally would run after the catch's return).
            let saved_safe = self.tail_safe_depth;
            self.tail_safe_depth = if finalizer.is_none() {
                self.try_depth
            } else {
                0
            };
            self.compile_statements(&handler.body.stmts)?;
            self.tail_safe_depth = saved_safe;
            self.try_depth -= 1;
            self.scope_count -= if handler.param.is_some() { 3 } else { 1 };
            if handler.param.is_some() {
                // CatchBind pushed the block env and the parameter env in
                // addition to the body env: unwind the parameter chain before
                // the body's own LeaveBlock restores the pre-catch
                // environment.
                self.emit(Step::LeaveBlock);
                self.emit(Step::LeaveBlock);
            }
            self.emit(Step::LeaveBlock);
            self.emit(Step::ListEnd);
            let exit_index = self.steps.len();
            self.emit(Step::Exit { after: 0 });
            self.fixups.push(Fixup::Exit(exit_index, after_label));
            self.handlers[handler_index].catch = Some(CatchHandler {
                start: catch_start,
                end: exit_index,
            });
        }

        if let Some(finalizer) = finalizer {
            let finally_start = self.steps.len();
            self.handlers[handler_index].finally = Some(finally_start);
            self.emit(Step::SaveCompletion);
            self.emit(Step::ListBegin);
            self.emit(Step::EnterBlock {
                decls: Self::block_decls(&finalizer.stmts),
            });
            self.scope_count += 1;
            self.try_depth += 1;
            // A return in the finally is tail-safe (it overrides the pending
            // control; the finally is already running) — provided no OUTER
            // try encloses it (checked by the `try_depth <= 1` gate).
            let saved_safe = self.tail_safe_depth;
            self.tail_safe_depth = self.try_depth;
            self.compile_statements(&finalizer.stmts)?;
            self.tail_safe_depth = saved_safe;
            self.try_depth -= 1;
            self.scope_count -= 1;
            self.emit(Step::LeaveBlock);
            self.emit(Step::ListEnd);
            self.emit(Step::RestoreCompletion);
            self.emit(Step::FinallyEnd);
        }
        self.place(after_label);
        self.emit(Step::NormalizeCompletion);
        Ok(())
    }

    /// Compile an expression, tracking the nesting depth (Cut 34): the
    /// statement-position `statement_expr` fusion applies only to the
    /// statement's own assignment (`expr_depth == 1`), never a nested
    /// assignment in an operand.
    fn compile_expr(&mut self, expr: &Expr) -> Result<(), JsError> {
        // Tail position (spec 14.2.2): only a call whose value is directly
        // the return value may replace the frame. The compound shapes below
        // forward the flag to their tail subexpression; every other shape's
        // subexpressions are consumed by operations, so none is in tail
        // position. Parens are transparent. The flag is restored on the way
        // out so a sibling subexpression (e.g. a conditional's other branch)
        // keeps the caller's tail position.
        let saved = self.tail;
        match &expr.kind {
            ExprKind::Call(_)
            | ExprKind::TaggedTemplate { .. }
            | ExprKind::Conditional { .. }
            | ExprKind::Logical { .. }
            | ExprKind::Sequence(_)
            | ExprKind::Paren(_) => {}
            _ => self.tail = false,
        }
        self.expr_depth += 1;
        let result = self.compile_expr_inner(expr);
        self.expr_depth -= 1;
        self.tail = saved;
        result
    }

    fn compile_expr_inner(&mut self, expr: &Expr) -> Result<(), JsError> {
        match &expr.kind {
            ExprKind::Paren(inner) => self.compile_expr(inner),
            ExprKind::Sequence(exprs) => {
                for (index, expr) in exprs.iter().enumerate() {
                    let is_last = index + 1 == exprs.len();
                    if !is_last {
                        let saved = self.tail;
                        self.tail = false;
                        self.compile_expr(expr)?;
                        self.tail = saved;
                    } else {
                        self.compile_expr(expr)?;
                    }
                    if !is_last {
                        self.emit(Step::Pop);
                    }
                }
                Ok(())
            }
            ExprKind::Literal(literal) => self.compile_literal(literal),
            ExprKind::Ident(name) => {
                match self.binding(*name) {
                    // Cut 3 fast path: the binding is a frame slot.
                    BindingLoc::Slot(slot) => self.emit(Step::LoadLocal { slot }),
                    // Cut 3 continuation: the binding is captured — read
                    // the capture context (or the current per-iteration env
                    // for a captured for-head inside its loop; an enclosing
                    // body's captured binding reads the static context
                    // chain).
                    BindingLoc::Context(depth, index) => {
                        if depth == 0
                            && let Some((depth, index)) = self.per_iteration(*name)
                        {
                            self.emit(Step::LoadPerIteration { depth, index });
                        } else {
                            self.emit(Step::LoadContextSlot { depth, index });
                        }
                    }
                    // Cut 5 fast script: a declared top-level var, read
                    // directly off the global object.
                    BindingLoc::Global => self.emit(Step::LoadGlobal { name: *name }),
                    // Cut 17: the fused loop counter lives in the accumulator.
                    BindingLoc::Acc => self.emit(Step::PushAcc),
                    // Cut 28: a captured per-iteration head reads the
                    // closure's own captured per-iteration env.
                    BindingLoc::CapturedIteration(depth, index) => {
                        self.emit(Step::LoadPerIteration { depth, index })
                    }
                    BindingLoc::Env => self.emit(Step::LoadIdent { name: *name }),
                }
                Ok(())
            }
            ExprKind::This => {
                // Cut 3 continuation (this slots): a certified non-arrow
                // body reads `this` from its dedicated frame slot (the call
                // filled it with the OrdinaryCallBindThis result); the env
                // path reads the running context's this binding. Tasklist
                // 2.3: a certified ARROW body's `this` is lexical — the
                // enclosing certified body captured it into its context (the
                // reserved marker is in the outer chain), so the read is a
                // context-chain load.
                if let Some(slot) = self.scope.as_ref().and_then(|scope| scope.this_slot) {
                    self.emit(Step::LoadLocal { slot });
                } else if let Some((depth, index)) = self.outer_context(captured_this_atom()) {
                    self.emit(Step::LoadContextSlot { depth, index });
                } else {
                    self.emit(Step::ThisValue);
                }
                Ok(())
            }
            ExprKind::Super => Err(JsError::new(
                ErrorKind::SyntaxError,
                "super is not valid here".into(),
            )),
            ExprKind::Function(function) => {
                let outer_chain = self.closure_outer_chain();
                let per_iteration_chain = self.closure_per_iteration_chain();
                self.emit(Step::CreateFunction {
                    function: Box::new(function.clone()),
                    strict: self.strict || self.class_depth > 0,
                    outer_chain,
                    per_iteration_chain,
                });
                Ok(())
            }
            ExprKind::Arrow {
                is_async,
                params,
                body,
            } => {
                let outer_chain = self.closure_outer_chain();
                let per_iteration_chain = self.closure_per_iteration_chain();
                self.emit(Step::CreateArrow {
                    is_async: *is_async,
                    params: params.clone(),
                    body: body.clone(),
                    strict: self.strict || self.class_depth > 0,
                    outer_chain,
                    per_iteration_chain,
                });
                Ok(())
            }
            ExprKind::Unary { op, operand } => match op {
                UnaryOp::Delete => self.compile_delete(operand),
                UnaryOp::Void => {
                    self.compile_expr(operand)?;
                    self.emit(Step::Pop);
                    self.emit(Step::Push(Value::Undefined));
                    Ok(())
                }
                UnaryOp::Typeof => {
                    // spec 13.5.3.2 step 1: `typeof` of an unresolvable
                    // identifier reference is "undefined", not an error
                    // (parentheses are transparent).
                    let mut operand = operand;
                    while let ExprKind::Paren(inner) = &operand.kind {
                        operand = inner;
                    }
                    if let ExprKind::Ident(name) = &operand.kind {
                        match self.binding(*name) {
                            // Cut 3/5 fast path: a fast binding always exists
                            // (never an unresolvable reference), so load it
                            // and compute the type — `TypeofIdent` would walk
                            // the environment for a binding the fast path
                            // never created. `LoadLocal`'s TDZ check
                            // preserves `typeof` of a `let`/`const` slot
                            // throwing (spec 13.5.3.2 step 1).
                            BindingLoc::Slot(slot) => {
                                self.emit(Step::LoadLocal { slot });
                                self.emit(Step::TypeofTop);
                            }
                            BindingLoc::Global => {
                                self.emit(Step::LoadGlobal { name: *name });
                                self.emit(Step::TypeofTop);
                            }
                            // Cut 3 continuation: `typeof` of a captured
                            // binding reads the capture context (or the
                            // current per-iteration env inside its loop, or
                            // an enclosing body's context on the chain).
                            BindingLoc::Context(depth, index) => {
                                if depth == 0
                                    && let Some((depth, index)) = self.per_iteration(*name)
                                {
                                    self.emit(Step::LoadPerIteration { depth, index });
                                } else {
                                    self.emit(Step::LoadContextSlot { depth, index });
                                }
                                self.emit(Step::TypeofTop);
                            }
                            // Cut 17: `typeof` of the fused loop counter is
                            // a read of the accumulator.
                            BindingLoc::Acc => {
                                self.emit(Step::PushAcc);
                                self.emit(Step::TypeofTop);
                            }
                            // Cut 28: a captured per-iteration head reads
                            // the closure's own captured per-iteration env.
                            BindingLoc::CapturedIteration(depth, index) => {
                                self.emit(Step::LoadPerIteration { depth, index });
                                self.emit(Step::TypeofTop);
                            }
                            BindingLoc::Env => {
                                self.emit(Step::TypeofIdent { name: *name });
                            }
                        }
                    } else {
                        self.compile_expr(operand)?;
                        self.emit(Step::TypeofTop);
                    }
                    Ok(())
                }
                _ => {
                    self.compile_expr(operand)?;
                    self.emit(Step::Unary(*op));
                    Ok(())
                }
            },
            ExprKind::Update { op, prefix, target } => self.compile_update(op, *prefix, target),
            ExprKind::Binary { op, left, right } => {
                self.compile_expr(left)?;
                // A `Number` literal right operand has no evaluation: fold it
                // into the step (a `Push`/`Pop` round-trip saved per fused
                // op; `i * 2`, `i < 1_000_000`, `x + 1` in the hot loops).
                match &right.kind {
                    ExprKind::Literal(syntax::ast::Literal::Number(n)) => {
                        self.emit(Step::BinaryImm { op: *op, imm: *n });
                    }
                    _ => {
                        self.compile_expr(right)?;
                        self.emit(Step::Binary(*op));
                    }
                }
                Ok(())
            }
            ExprKind::Logical { op, left, right } => {
                let saved = self.tail;
                self.tail = false;
                self.compile_expr(left)?;
                self.tail = saved;
                let end_label = self.new_label();
                match op {
                    LogicalOp::And => self.jump_if_false_keep(end_label),
                    LogicalOp::Or => self.jump_if_true_keep(end_label),
                    LogicalOp::Nullish => self.jump_if_not_nullish_keep(end_label),
                }
                self.emit(Step::Pop);
                self.compile_expr(right)?;
                self.place(end_label);
                Ok(())
            }
            ExprKind::Conditional {
                test,
                consequent,
                alternate,
            } => {
                let saved = self.tail;
                self.tail = false;
                self.compile_expr(test)?;
                self.tail = saved;
                let else_label = self.new_label();
                let end_label = self.new_label();
                self.jump_if_false(else_label);
                self.compile_expr(consequent)?;
                self.jump(end_label);
                self.place(else_label);
                self.compile_expr(alternate)?;
                self.place(end_label);
                Ok(())
            }
            ExprKind::Assign { op, target, value } => self.compile_assign(op, target, value),
            ExprKind::PrivateIn { name, object } => {
                self.compile_expr(object)?;
                self.emit(Step::PrivateIn { atom: *name });
                Ok(())
            }
            ExprKind::Call(call) => {
                let entered = self.enter_chain(expr);
                self.compile_call(call)?;
                self.leave_chain(entered);
                Ok(())
            }
            ExprKind::New(new) => {
                if matches!(new.callee.kind, ExprKind::Super) {
                    return Err(JsError::new(
                        ErrorKind::SyntaxError,
                        "new super is a syntax error".into(),
                    ));
                }
                self.compile_expr(&new.callee)?;
                self.compile_arguments(&new.args, false)?;
                self.emit(Step::Construct);
                Ok(())
            }
            ExprKind::Member(member) => {
                let entered = self.enter_chain(expr);
                self.compile_member(member)?;
                self.leave_chain(entered);
                Ok(())
            }
            ExprKind::TaggedTemplate { tag, quasi } => {
                let tail = self.tail;
                self.tail = false;
                // A member tag keeps its base object as the call's this (spec
                // 13.3.6.2: EvaluateCall with the tag reference); a plain tag
                // is an undefined-receiver call.
                let mut tag = tag;
                while let ExprKind::Paren(inner) = &tag.kind {
                    tag = inner;
                }
                if let ExprKind::Member(member) = &tag.kind
                    && !matches!(member.object.kind, ExprKind::Super)
                {
                    self.compile_expr(&member.object)?;
                    self.emit(Step::Dup);
                    self.compile_member_property_guarded(member)?;
                } else {
                    self.emit(Step::Push(Value::Undefined));
                    self.compile_expr(tag)?;
                }
                self.emit(Step::ArgsBase);
                for expr in &quasi.exprs {
                    self.compile_expr(expr)?;
                    self.emit(Step::ArgsPush);
                }
                self.tail = tail;
                if tail {
                    self.emit(Step::TailTaggedTemplate(quasi.clone()));
                } else {
                    self.emit(Step::TaggedTemplate(quasi.clone()));
                }
                Ok(())
            }
            ExprKind::Template(template) => self.compile_template(template),
            ExprKind::Array(literal) => {
                self.emit(Step::ArrayBegin);
                for element in &literal.elements {
                    match element {
                        ArrayElement::Hole => self.emit(Step::ArrayHole),
                        ArrayElement::Expr(expr) => {
                            self.compile_expr(expr)?;
                            self.emit(Step::ArrayElement);
                        }
                        ArrayElement::Spread(expr) => {
                            self.compile_expr(expr)?;
                            self.emit(Step::ArraySpread);
                        }
                    }
                }
                self.emit(Step::ArrayEnd);
                Ok(())
            }
            ExprKind::Class(class) => self.compile_class(class),
            ExprKind::Object(literal) => self.compile_object(literal),
            ExprKind::Yield { delegate, argument } => {
                match argument {
                    Some(argument) => self.compile_expr(argument)?,
                    None => self.emit(Step::Push(Value::Undefined)),
                }
                if *delegate {
                    // yield* (spec 14.5.5): the delegation loop. Async
                    // generators await each inner result through the driver.
                    if self.is_async_generator {
                        self.emit(Step::AsyncYieldStarBegin);
                        let loop_label = self.new_label();
                        let done_label = self.new_label();
                        self.place(loop_label);
                        let step_index = self.steps.len();
                        self.emit(Step::AsyncYieldStarNext { done: 0 });
                        self.fixups
                            .push(Fixup::AsyncYieldStarNext(step_index, done_label));
                        let inspect_index = self.steps.len();
                        self.emit(Step::AsyncYieldStarInspect { done: 0 });
                        self.fixups
                            .push(Fixup::AsyncYieldStarInspect(inspect_index, done_label));
                        self.emit(Step::Yield { delegate: true });
                        let resume_index = self.steps.len();
                        self.emit(Step::AsyncYieldStarResume {
                            loop_top: 0,
                            done: 0,
                            inspect: 0,
                        });
                        self.fixups.push(Fixup::AsyncYieldStarResume(
                            resume_index,
                            loop_label,
                            done_label,
                            inspect_index,
                        ));
                        self.place(done_label);
                    } else {
                        self.emit(Step::YieldStarBegin);
                        let loop_label = self.new_label();
                        let done_label = self.new_label();
                        let yield_label = self.new_label();
                        self.place(loop_label);
                        let step_index = self.steps.len();
                        self.emit(Step::YieldStarNext { done: 0 });
                        self.fixups
                            .push(Fixup::YieldStarNext(step_index, done_label));
                        self.place(yield_label);
                        self.emit(Step::Yield { delegate: true });
                        let resume_index = self.steps.len();
                        self.emit(Step::YieldStarResume {
                            loop_top: 0,
                            done: 0,
                            yield_at: 0,
                        });
                        self.fixups.push(Fixup::YieldStarResume(
                            resume_index,
                            loop_label,
                            done_label,
                            yield_label,
                        ));
                        self.place(done_label);
                    }
                } else {
                    self.emit(Step::Yield { delegate: false });
                }
                Ok(())
            }
            ExprKind::Await(argument) => {
                self.compile_expr(argument)?;
                self.emit(Step::Await);
                Ok(())
            }
            ExprKind::ImportCall {
                specifier,
                options,
                phase,
            } => {
                self.compile_expr(specifier)?;
                let has_options = options.is_some();
                if let Some(options) = options {
                    self.compile_expr(options)?;
                }
                self.emit(Step::ImportCall {
                    has_options,
                    phase: *phase,
                });
                Ok(())
            }
            ExprKind::MetaProperty { meta, property } => {
                let meta_name = crux::lookup(*meta).to_string_lossy();
                let property_name = crux::lookup(*property).to_string_lossy();
                if meta_name == "import" && property_name == "meta" {
                    self.emit(Step::ImportMeta);
                } else {
                    // new.target (spec 13.3.5.3).
                    self.emit(Step::NewTarget);
                }
                Ok(())
            }
        }
    }

    /// A literal's value is known at compile time; a `RegExp` literal
    /// constructs its object at runtime (spec 13.2.4.4).
    fn compile_literal(&mut self, literal: &syntax::ast::Literal) -> Result<(), JsError> {
        match literal {
            syntax::ast::Literal::Null => self.emit(Step::Push(Value::Null)),
            syntax::ast::Literal::Boolean(value) => {
                self.emit(Step::Push(Value::Boolean(*value)));
            }
            syntax::ast::Literal::Number(value) => self.emit(Step::Push(Value::Number(*value))),
            syntax::ast::Literal::BigInt(value) => {
                self.emit(Step::Push(Value::BigInt(Handle::new(value.clone()))));
            }
            syntax::ast::Literal::Str(value) => {
                self.emit(Step::Push(Value::String(Handle::new(value.clone()))));
            }
            syntax::ast::Literal::RegExp { pattern, flags } => {
                self.emit(Step::RegExpLiteral {
                    pattern: pattern.clone(),
                    flags: flags.clone(),
                });
            }
        }
        Ok(())
    }

    fn compile_delete(&mut self, operand: &Expr) -> Result<(), JsError> {
        // A parenthesized operand is transparent: `delete (x)` deletes the
        // covered reference (the grouping fixtures), and `delete (o.x)` the
        // member.
        let mut operand = operand;
        while let ExprKind::Paren(inner) = &operand.kind {
            operand = inner;
        }
        match &operand.kind {
            ExprKind::Ident(name) => {
                if !matches!(self.binding(*name), BindingLoc::Env) {
                    // Cut 3/5 fast path: a fast binding is never
                    // unresolvable, and strict-mode `delete x` is a parse
                    // error, so the result is always false (spec 13.5.1.2
                    // step 3) — `DeleteIdent` would walk the environment for
                    // a binding the fast path never created.
                    self.emit(Step::Push(Value::Boolean(false)));
                } else {
                    self.emit(Step::DeleteIdent { name: *name });
                }
                Ok(())
            }
            ExprKind::Member(member) => {
                if matches!(member.object.kind, ExprKind::Super) {
                    // `delete super.x` throws a ReferenceError before the key
                    // evaluates (spec 13.5.1.2 step 4.b).
                    self.emit(Step::DeleteSuper);
                    return Ok(());
                }
                match &member.property {
                    MemberProperty::Name(name) => {
                        self.compile_expr(&member.object)?;
                        self.emit(Step::DeleteMemberName { name: *name });
                    }
                    MemberProperty::Computed(key) => {
                        self.compile_expr(&member.object)?;
                        self.compile_expr(key)?;
                        self.emit(Step::DeleteMemberComputed);
                    }
                    MemberProperty::Private(_) => {
                        return Err(JsError::new(
                            ErrorKind::SyntaxError,
                            "delete of a private name is a syntax error".into(),
                        ));
                    }
                }
                Ok(())
            }
            _ => {
                self.compile_expr(operand)?;
                self.emit(Step::Pop);
                self.emit(Step::Push(Value::Boolean(true)));
                Ok(())
            }
        }
    }

    fn compile_update(
        &mut self,
        op: &UpdateOp,
        prefix: bool,
        target: &Expr,
    ) -> Result<(), JsError> {
        // A parenthesized target is transparent: `(x)++` and `(o.x)++` are
        // valid updates of the covered reference (the IsValidSimpleAssignment
        // Target fixtures). The destructuring targets stay unparenthesized
        // (a parenthesized object/array literal is not a valid target).
        let mut target = target;
        while let ExprKind::Paren(inner) = &target.kind {
            target = inner;
        }
        match &target.kind {
            ExprKind::Ident(name) => {
                match self.binding(*name) {
                    BindingLoc::Slot(slot) => {
                        // Cut 3 fast path: the update reads and writes the
                        // frame slot directly.
                        self.emit(Step::UpdateLocal {
                            slot,
                            op: *op,
                            prefix,
                        });
                        return Ok(());
                    }
                    BindingLoc::Global => {
                        // Cut 5 fast script: the update reads and writes the
                        // global binding directly.
                        self.emit(Step::UpdateGlobal {
                            name: *name,
                            op: *op,
                            prefix,
                        });
                        return Ok(());
                    }
                    BindingLoc::Acc => {
                        // Cut 17: the fused loop counter lives in the
                        // accumulator — push the old value (the statement's
                        // `SetCompletion` discards it) and update the
                        // accumulator in place.
                        self.emit(Step::PushAcc);
                        self.emit(if matches!(op, UpdateOp::Increment) {
                            Step::IncAcc
                        } else {
                            Step::DecAcc
                        });
                        return Ok(());
                    }
                    BindingLoc::Context(depth, index) => {
                        // Cut 3 continuation: the update reads and writes
                        // the capture context (or the current per-iteration
                        // env for a captured for-head inside its loop, or an
                        // enclosing body's context on the chain).
                        if depth == 0
                            && let Some((depth, index)) = self.per_iteration(*name)
                        {
                            self.emit(Step::UpdatePerIteration {
                                depth,
                                index,
                                op: *op,
                                prefix,
                            });
                        } else {
                            self.emit(Step::UpdateContextSlot {
                                depth,
                                index,
                                op: *op,
                                prefix,
                            });
                        }
                        return Ok(());
                    }
                    BindingLoc::CapturedIteration(depth, index) => {
                        // Cut 28: the update reads and writes the closure's
                        // own captured per-iteration env.
                        self.emit(Step::UpdatePerIteration {
                            depth,
                            index,
                            op: *op,
                            prefix,
                        });
                        return Ok(());
                    }
                    BindingLoc::Env => {}
                }
                // The assignment target's reference resolves before the RHS:
                // PutValue uses the initially created reference even when the
                // binding disappears while the RHS evaluates (spec 13.15.3
                // steps 1, 5 — a `with` scope whose binding the RHS deletes).
                self.emit(Step::ResolveVarIdent { name: *name });
                self.emit(Step::GetVarReference);
                self.emit(Step::UpdateVarReference { op: *op, prefix });
            }
            ExprKind::Member(member) => {
                if matches!(member.object.kind, ExprKind::Super) {
                    // super.x++ / super[x]++ (spec 13.3.7.1): GetValue
                    // through the super reference, then PutValue the
                    // incremented value.
                    match &member.property {
                        MemberProperty::Name(name) => {
                            self.emit(Step::ResolveSuperRefName { name: *name });
                        }
                        MemberProperty::Computed(key) => {
                            // GetSuperBase runs the this-binding check before
                            // the key evaluates.
                            self.emit(Step::GetSuperBase);
                            self.compile_expr(key)?;
                            self.emit(Step::ResolveSuperRefComputed);
                        }
                        MemberProperty::Private(_) => {
                            return Err(JsError::new(
                                ErrorKind::SyntaxError,
                                "update of super.#x is a syntax error".into(),
                            ));
                        }
                    }
                    self.emit(Step::GetVarReference);
                    self.emit(Step::UpdateVarReference { op: *op, prefix });
                    return Ok(());
                }
                self.compile_expr(&member.object)?;
                match &member.property {
                    MemberProperty::Name(name) => {
                        self.emit(Step::Dup);
                        self.emit(Step::GetMemberName { name: *name });
                        self.emit(Step::UpdateMemberName {
                            name: *name,
                            op: *op,
                            prefix,
                        });
                    }
                    MemberProperty::Computed(key) => {
                        self.compile_expr(key)?;
                        self.emit(Step::Dup2);
                        self.emit(Step::GetMemberComputedKeep);
                        self.emit(Step::UpdateMemberComputed { op: *op, prefix });
                    }
                    MemberProperty::Private(atom) => {
                        self.emit(Step::Dup);
                        self.emit(Step::GetPrivate { atom: *atom });
                        self.emit(Step::UpdatePrivate {
                            atom: *atom,
                            op: *op,
                            prefix,
                        });
                    }
                }
            }
            ExprKind::Super => {
                return Err(JsError::new(
                    ErrorKind::SyntaxError,
                    "update of super is a syntax error".into(),
                ));
            }
            ExprKind::Call(_) => {
                // Annex B web-compat: a sloppy-mode call target evaluates its
                // operand, then the update's PutValue throws a ReferenceError.
                self.compile_expr(target)?;
                self.emit(Step::Pop);
                self.emit(Step::InvalidAssignmentTarget);
            }
            _ => {
                return Err(JsError::new(
                    ErrorKind::SyntaxError,
                    "Invalid left-hand side in update expression".into(),
                ));
            }
        }
        Ok(())
    }

    fn compile_assign(
        &mut self,
        op: &AssignOp,
        target: &Expr,
        value: &Expr,
    ) -> Result<(), JsError> {
        if matches!(target.kind, ExprKind::Object(_) | ExprKind::Array(_)) {
            self.compile_expr(value)?;
            if Self::destructure_needs_steps(target) || self.scope.is_some() {
                // Keep a copy: the assignment expression's value is the RHS.
                // A certified body (Cut 59) compiles EVERY pattern to the
                // primitive `Destructure*` steps with flat slot/context
                // stores (the wholesale `Destructure { pattern }` step binds
                // through the environment machinery, which a certified body
                // never consults).
                self.emit(Step::Dup);
                self.compile_destructure_assign(target)?;
            } else {
                let pattern = pattern_of_target(target)?;
                self.emit(Step::Destructure { pattern });
            }
            return Ok(());
        }
        // A parenthesized target is transparent for the simple targets
        // (`(x) = v` assigns the covered reference); the destructuring
        // targets above stay unparenthesized. NamedEvaluation requires an
        // actual IdentifierReference, though: `(fn) = function(){}` leaves the
        // function unnamed (parens break IsIdentifierRef, spec 13.15.3 step
        // 2.c), so `set_name` is computed on the unparenthesized target.
        let set_name = matches!(target.kind, ExprKind::Ident(_))
            && crate::function::is_anonymous_function_definition(value);
        let mut target = target;
        while let ExprKind::Paren(inner) = &target.kind {
            target = inner;
        }
        match &target.kind {
            ExprKind::Ident(name) => {
                match self.binding(*name) {
                    loc @ (BindingLoc::Slot(_)
                    | BindingLoc::Context(_, _)
                    | BindingLoc::CapturedIteration(_, _)
                    | BindingLoc::Global
                    | BindingLoc::Acc) => {
                        // Cut 3/17 fast paths: the target is a frame slot,
                        // a captured binding, a declared top-level var, or
                        // the fused loop counter; no reference machinery
                        // (there is no `with` to observe the
                        // resolve-before-RHS rule, and function-literal
                        // initializers bail the fast path so `set_name`
                        // cannot trigger). The `Dup` before the store leaves
                        // the assigned value as the expression's result.
                        match op {
                            AssignOp::Assign => {
                                self.begin_named_initializer(*name, value);
                                self.compile_expr(value)?;
                                if set_name {
                                    // NamedEvaluation (spec 13.15.3 step
                                    // 2.d): a plain assignment of an
                                    // anonymous function names it after the
                                    // binding — the env path does this too.
                                    self.emit(Step::SetFunctionName { name: *name });
                                }
                                self.emit_statement_store(loc, *name);
                            }
                            AssignOp::AndAssign | AssignOp::OrAssign | AssignOp::NullishAssign => {
                                self.emit_load(loc, *name);
                                let end_label = self.new_label();
                                match op {
                                    AssignOp::AndAssign => self.jump_if_false_keep(end_label),
                                    AssignOp::OrAssign => self.jump_if_true_keep(end_label),
                                    _ => self.jump_if_not_nullish_keep(end_label),
                                }
                                self.emit(Step::Pop);
                                self.compile_expr(value)?;
                                if set_name {
                                    // NamedEvaluation (spec 13.15.3 step 5.a)
                                    // applies on the executed path only.
                                    self.emit(Step::SetFunctionName { name: *name });
                                }
                                // Both paths leave a value (the old binding
                                // on the short circuit), so the result `Dup`
                                // is always needed.
                                self.emit_dup_store(loc, *name);
                                self.place(end_label);
                            }
                            _ => {
                                self.emit_load(loc, *name);
                                self.compile_expr(value)?;
                                self.emit(Step::Binary(crate::expr::compound_binary(*op)));
                                self.emit_statement_store(loc, *name);
                            }
                        }
                        Ok(())
                    }
                    BindingLoc::Env => {
                        match op {
                            AssignOp::Assign => {
                                // Resolve the reference before the RHS: PutValue
                                // uses the initially created reference even if
                                // the binding disappears while the RHS evaluates
                                // (spec 13.15.3 steps 1, 5 — e.g. a `with`
                                // scope whose binding the RHS deletes).
                                self.emit(Step::ResolveVarIdent { name: *name });
                                self.begin_named_initializer(*name, value);
                                self.compile_expr(value)?;
                                if set_name {
                                    self.emit(Step::SetFunctionName { name: *name });
                                }
                                self.emit(Step::PutVarReference);
                            }
                            AssignOp::AndAssign | AssignOp::OrAssign | AssignOp::NullishAssign => {
                                self.emit(Step::LoadIdent { name: *name });
                                let end_label = self.new_label();
                                match op {
                                    AssignOp::AndAssign => self.jump_if_false_keep(end_label),
                                    AssignOp::OrAssign => self.jump_if_true_keep(end_label),
                                    _ => self.jump_if_not_nullish_keep(end_label),
                                }
                                // The keep re-pushed the old value: AssignIdent
                                // pops it alongside the RHS result (no separate
                                // Pop — the slot arm's emit_dup_store consumes
                                // it instead).
                                self.compile_expr(value)?;
                                self.emit(Step::AssignIdent {
                                    name: *name,
                                    op: *op,
                                    set_name,
                                });
                                self.place(end_label);
                            }
                            _ => {
                                self.emit(Step::ResolveVarIdent { name: *name });
                                self.emit(Step::GetVarReference);
                                self.compile_expr(value)?;
                                self.emit(Step::PutVarReferenceOp { op: *op });
                            }
                        }
                        Ok(())
                    }
                }
            }
            ExprKind::Member(member) => self.compile_member_assign(member, op, value),
            ExprKind::Call(_) => {
                // Annex B web-compat: a sloppy-mode function-call assignment
                // target evaluates the call, then throws a ReferenceError
                // before the RHS evaluates (spec 13.15.3). Strict mode
                // rejects the syntax at parse time.
                self.compile_expr(target)?;
                self.emit(Step::Pop);
                self.emit(Step::InvalidAssignmentTarget);
                Ok(())
            }
            ExprKind::Super => Err(JsError::new(
                ErrorKind::SyntaxError,
                "Invalid left-hand side in assignment".into(),
            )),
            _ => Err(JsError::new(
                ErrorKind::SyntaxError,
                "Invalid left-hand side in assignment".into(),
            )),
        }
    }

    /// Whether a destructuring assignment target needs step-based compilation:
    /// a member target (the tree-walker has no reference machinery for it) or
    /// a suspension point in a default or computed key.
    fn destructure_needs_steps(target: &Expr) -> bool {
        fn member_in(expr: &Expr) -> bool {
            match &expr.kind {
                ExprKind::Member(_) => true,
                ExprKind::Assign { target, value, .. } => member_in(target) || member_in(value),
                ExprKind::Array(lit) => lit.elements.iter().any(|el| match el {
                    ArrayElement::Expr(e) | ArrayElement::Spread(e) => member_in(e),
                    ArrayElement::Hole => false,
                }),
                ExprKind::Object(lit) => lit.props.iter().any(|prop| match prop {
                    ObjectProperty::Init { value, .. } | ObjectProperty::Spread(value) => {
                        member_in(value)
                    }
                    _ => false,
                }),
                ExprKind::Paren(inner) => member_in(inner),
                _ => false,
            }
        }
        member_in(target) || expr_contains_suspension(target)
    }

    /// Whether a binding pattern contains a suspension point in any default
    /// initializer or computed key. Such patterns must be compiled to steps
    /// (the runtime `binding_initialization` evaluates defaults through the
    /// synchronous tree-walker, which cannot suspend).
    fn binding_pattern_contains_suspension(&self, pattern: &BindingPattern) -> bool {
        match pattern {
            BindingPattern::Ident(_) => false,
            BindingPattern::Object(props) => props.iter().any(|prop| match prop {
                syntax::ast::ObjectBindingProperty::Property { key, element, .. } => {
                    pattern_element_contains_suspension(element)
                        || matches!(key, PropertyName::Computed(e) if expr_contains_suspension(e))
                }
                syntax::ast::ObjectBindingProperty::Rest(element) => {
                    pattern_element_contains_suspension(element)
                }
            }),
            BindingPattern::Array(elements) => elements.iter().any(|element| match element {
                ArrayBindingElement::Hole => false,
                ArrayBindingElement::Element(e) | ArrayBindingElement::Rest(e) => {
                    pattern_element_contains_suspension(e)
                }
            }),
        }
    }

    /// Compile a destructuring binding pattern into steps (spec 13.13.11):
    /// the value is on top of the stack; defaults and computed keys compile
    /// inline so `yield`/`await` in them suspends the resumable body, and
    /// each element binds into the lexical (`DeclInit`) or var (`Destructure`)
    /// environment. Only used when `binding_pattern_contains_suspension` is
    /// true — otherwise the single-step wholesale binding is faster.
    fn compile_destructure_binding(
        &mut self,
        pattern: &BindingPattern,
        lexical: bool,
    ) -> Result<(), JsError> {
        let bind = |compiler: &mut Self, element: &BindingElement| -> Result<(), JsError> {
            // A default initializer compiles inline so it can suspend; a
            // nested pattern with suspension recurses step-wise; otherwise
            // the whole element binds in one step. The value is on top of
            // the stack either way (spec 13.13.11 step 5.d). A certified
            // body (Cut 59) always compiles the primitive steps — the
            // wholesale `DeclInit`/`Destructure` binds through the
            // environment machinery, which a certified body never consults.
            let bind_element = |compiler: &mut Self| -> Result<(), JsError> {
                if compiler.scope.is_some()
                    || compiler.binding_pattern_contains_suspension(&element.pattern)
                {
                    compiler.compile_destructure_binding(&element.pattern, lexical)
                } else {
                    compiler.emit(if lexical {
                        Step::DeclInit {
                            pattern: element.pattern.clone(),
                        }
                    } else {
                        Step::Destructure {
                            pattern: element.pattern.clone(),
                        }
                    });
                    compiler.emit(Step::Pop);
                    Ok(())
                }
            };
            if let Some(init) = &element.init {
                let use_default = compiler.new_label();
                let after = compiler.new_label();
                compiler.emit_destructure_undef(use_default);
                bind_element(compiler)?;
                compiler.jump(after);
                compiler.place(use_default);
                compiler.compile_expr(init)?;
                bind_element(compiler)?;
                compiler.place(after);
            } else {
                bind_element(compiler)?;
            }
            Ok(())
        };
        match pattern {
            BindingPattern::Ident(_) => {
                // A plain identifier with a suspension default cannot occur
                // (the default belongs to the declaration's init, not the
                // pattern); treat as a plain binding. A certified body's
                // identifier element writes the flat slot directly (Cut 59).
                if self.scope.is_some() {
                    self.emit_certified_bind(pattern, lexical);
                } else {
                    self.emit(if lexical {
                        Step::DeclInit {
                            pattern: pattern.clone(),
                        }
                    } else {
                        Step::Destructure {
                            pattern: pattern.clone(),
                        }
                    });
                    self.emit(Step::Pop);
                }
            }
            BindingPattern::Array(elements) => {
                self.emit(Step::DestructureBegin);
                let end_label = self.new_label();
                for element in elements {
                    match element {
                        ArrayBindingElement::Hole => {
                            self.emit_destructure_next();
                            self.emit(Step::Pop);
                        }
                        ArrayBindingElement::Element(element) => {
                            self.emit_destructure_next();
                            bind(self, element)?;
                        }
                        ArrayBindingElement::Rest(element) => {
                            self.emit(Step::DestructureRest);
                            bind(self, element)?;
                            self.place(end_label);
                            return Ok(());
                        }
                    }
                }
                self.emit(Step::DestructureClose);
                self.place(end_label);
            }
            BindingPattern::Object(props) => {
                let mut excluded: Vec<crux::property::PropertyKey> = Vec::new();
                self.emit(Step::DestructureObjCoercible);
                for prop in props {
                    match prop {
                        syntax::ast::ObjectBindingProperty::Property { key, element, .. } => {
                            match key {
                                PropertyName::Ident(id) => {
                                    let key = crux::property::PropertyKey::String(*id);
                                    self.emit(Step::DestructureObjKey { key: key.clone() });
                                    excluded.push(key);
                                }
                                PropertyName::Str(text) => {
                                    let key = crux::property::PropertyKey::from_js_string(text);
                                    self.emit(Step::DestructureObjKey { key: key.clone() });
                                    excluded.push(key);
                                }
                                PropertyName::Number(n) => {
                                    let key = crux::property::PropertyKey::from_js_string(
                                        &crux::convert::to_string(&Value::Number(*n))?,
                                    );
                                    self.emit(Step::DestructureObjKey { key: key.clone() });
                                    excluded.push(key);
                                }
                                PropertyName::Computed(expr) => {
                                    self.compile_expr(expr)?;
                                    self.emit(Step::DestructureObjKeyComputed);
                                }
                            }
                            bind(self, element)?;
                        }
                        syntax::ast::ObjectBindingProperty::Rest(element) => {
                            self.emit(Step::DestructureObjRest {
                                excluded: excluded.clone(),
                            });
                            bind(self, element)?;
                        }
                    }
                }
                self.emit(Step::DestructureObjEnd);
            }
        }
        Ok(())
    }

    /// Compile a destructuring assignment pattern into steps (spec 13.15.5):
    /// the value is on top of the stack. Defaults and computed keys are
    /// compiled inline, so `yield`/`await` in them suspends the resumable
    /// body; member targets assign through references.
    fn compile_destructure_assign(&mut self, target: &Expr) -> Result<(), JsError> {
        match &target.kind {
            ExprKind::Array(lit) => {
                self.emit(Step::DestructureBegin);
                let end_label = self.new_label();
                for element in &lit.elements {
                    match element {
                        ArrayElement::Hole => {
                            self.emit_destructure_next();
                            self.emit(Step::Pop);
                        }
                        ArrayElement::Expr(expr) => {
                            let (inner, init) = unwrap_default(expr);
                            // A member target evaluates its reference before
                            // the iterator steps (spec 13.15.5.5 note).
                            if let ExprKind::Member(member) = &inner.kind {
                                self.compile_member_reference(member)?;
                            }
                            self.emit_destructure_next();
                            self.compile_assign_value(inner, init)?;
                        }
                        ArrayElement::Spread(expr) => {
                            // The rest target's reference is evaluated before
                            // the remaining values are collected (spec
                            // 13.15.5.5); a `yield`/`await` in a computed key
                            // suspends here.
                            if let ExprKind::Member(member) = &expr.kind {
                                self.compile_member_reference(member)?;
                            }
                            self.emit(Step::DestructureRest);
                            self.compile_assign_value(expr, None)?;
                            self.place(end_label);
                            return Ok(());
                        }
                    }
                }
                self.emit(Step::DestructureClose);
                self.place(end_label);
                Ok(())
            }
            ExprKind::Object(lit) => {
                let mut excluded: Vec<crux::property::PropertyKey> = Vec::new();
                self.emit(Step::DestructureObjCoercible);
                for prop in &lit.props {
                    match prop {
                        ObjectProperty::Init { key, value, .. } => {
                            let (inner, init) = unwrap_default(value);
                            // KeyedDestructuringAssignmentEvaluation (spec
                            // 13.15.5.6): the pattern's computed PropertyName
                            // evaluates (and is converted) before the target
                            // reference, whose own computed key conversion is
                            // deferred to the write — but the property READ
                            // runs after the target reference.
                            if let PropertyName::Computed(expr) = key {
                                self.compile_expr(expr)?;
                                self.emit(Step::ObjectKeyToPropertyKey);
                                self.emit(Step::DestructureObjKeyStore);
                            }
                            if let ExprKind::Member(member) = &inner.kind {
                                self.compile_member_reference(member)?;
                            }
                            match key {
                                PropertyName::Ident(id) => {
                                    let key = crux::property::PropertyKey::String(*id);
                                    self.emit(Step::DestructureObjKey { key: key.clone() });
                                    excluded.push(key);
                                }
                                PropertyName::Str(text) => {
                                    let key = crux::property::PropertyKey::from_js_string(text);
                                    self.emit(Step::DestructureObjKey { key: key.clone() });
                                    excluded.push(key);
                                }
                                PropertyName::Number(n) => {
                                    let key = crux::property::PropertyKey::from_js_string(
                                        &crux::convert::to_string(&Value::Number(*n))?,
                                    );
                                    self.emit(Step::DestructureObjKey { key: key.clone() });
                                    excluded.push(key);
                                }
                                PropertyName::Computed(_) => {
                                    self.emit(Step::DestructureObjKeyGet);
                                }
                            }
                            self.compile_assign_value(inner, init)?;
                        }
                        ObjectProperty::Spread(expr) => {
                            // The rest target's reference is evaluated before
                            // the rest object is collected (mirroring the
                            // array-pattern case above; the tree-walker
                            // evaluates it after CopyDataProperties, but the
                            // stack protocol needs the base below the value).
                            if let ExprKind::Member(member) = &expr.kind {
                                self.compile_member_reference(member)?;
                            }
                            self.emit(Step::DestructureObjRest {
                                excluded: excluded.clone(),
                            });
                            self.compile_assign_value(expr, None)?;
                        }
                        _ => {
                            return Err(JsError::new(
                                ErrorKind::SyntaxError,
                                "Invalid destructuring assignment target".into(),
                            ));
                        }
                    }
                }
                self.emit(Step::DestructureObjEnd);
                Ok(())
            }
            ExprKind::Paren(inner) => self.compile_destructure_assign(inner),
            _ => Err(JsError::new(
                ErrorKind::SyntaxError,
                "Invalid destructuring assignment target".into(),
            )),
        }
    }

    /// Assign the value on top of the stack to an element target, applying
    /// the default when it is undefined (spec 13.15.5.5). Nested patterns
    /// recurse; member targets consume the pre-compiled reference below the
    /// value.
    fn compile_assign_value(&mut self, inner: &Expr, init: Option<&Expr>) -> Result<(), JsError> {
        match &inner.kind {
            ExprKind::Array(_) | ExprKind::Object(_) => {
                if let Some(init) = init {
                    let use_default = self.new_label();
                    let after = self.new_label();
                    self.emit_destructure_undef(use_default);
                    self.compile_destructure_assign(inner)?;
                    self.jump(after);
                    self.place(use_default);
                    self.compile_expr(init)?;
                    self.compile_destructure_assign(inner)?;
                    self.place(after);
                } else {
                    self.compile_destructure_assign(inner)?;
                }
                Ok(())
            }
            ExprKind::Ident(id) => {
                if let Some(init) = init {
                    let use_default = self.new_label();
                    let after = self.new_label();
                    let set_name = crate::function::is_anonymous_function_definition(init);
                    self.emit_destructure_undef(use_default);
                    if set_name {
                        // NamedEvaluation (spec 13.15.5.5): a default that
                        // is an anonymous function definition names it after
                        // the binding.
                        self.emit(Step::SetFunctionName { name: *id });
                    }
                    self.emit_certified_assign_store(*id);
                    self.jump(after);
                    self.place(use_default);
                    self.compile_expr(init)?;
                    if set_name {
                        self.emit(Step::SetFunctionName { name: *id });
                    }
                    self.emit_certified_assign_store(*id);
                    self.place(after);
                } else {
                    self.emit_certified_assign_store(*id);
                }
                Ok(())
            }
            ExprKind::Member(member) => {
                if let Some(init) = init {
                    let use_default = self.new_label();
                    let after = self.new_label();
                    self.emit_destructure_undef(use_default);
                    self.emit_member_assign(member)?;
                    self.emit(Step::Pop);
                    self.jump(after);
                    self.place(use_default);
                    self.compile_expr(init)?;
                    self.emit_member_assign(member)?;
                    self.emit(Step::Pop);
                    self.place(after);
                } else {
                    self.emit_member_assign(member)?;
                    self.emit(Step::Pop);
                }
                Ok(())
            }
            ExprKind::Paren(inner) => self.compile_assign_value(inner, init),
            _ => Err(JsError::new(
                ErrorKind::SyntaxError,
                "Invalid destructuring assignment target".into(),
            )),
        }
    }

    /// The reference parts of a member target: the base (and computed key)
    /// are pushed for the later `AssignMember*` step (spec 13.15.5.5: the
    /// reference is evaluated before the iterator steps).
    fn compile_member_reference(
        &mut self,
        member: &syntax::ast::MemberExpr,
    ) -> Result<(), JsError> {
        if matches!(member.object.kind, ExprKind::Super) {
            self.emit(Step::GetSuperBase);
            if let MemberProperty::Computed(key) = &member.property {
                self.compile_expr(key)?;
            }
            return Ok(());
        }
        self.compile_expr(&member.object)?;
        if let MemberProperty::Computed(key) = &member.property {
            self.compile_expr(key)?;
        }
        Ok(())
    }

    /// The `AssignMember*`/`AssignPrivate` step consuming the pre-compiled
    /// reference and the value on top of the stack.
    fn emit_member_assign(&mut self, member: &syntax::ast::MemberExpr) -> Result<(), JsError> {
        match &member.property {
            MemberProperty::Name(name) => {
                self.emit(Step::AssignMemberName {
                    name: *name,
                    op: AssignOp::Assign,
                });
            }
            MemberProperty::Computed(_) => {
                self.emit(Step::AssignMemberComputed {
                    op: AssignOp::Assign,
                });
            }
            MemberProperty::Private(atom) => {
                self.emit(Step::AssignPrivate {
                    atom: *atom,
                    op: AssignOp::Assign,
                });
            }
        }
        Ok(())
    }

    /// `&&=`, `||=`, `??=` on a member/super/private target (spec 13.15.4-6):
    /// resolve the reference (base consumed), read the old value, test it,
    /// short-circuit with the old value as the expression result, or evaluate
    /// the RHS and assign. The reference lives on the var-reference stack, so
    /// both paths leave exactly one value.
    fn compile_logical_assign(
        &mut self,
        member: &syntax::ast::MemberExpr,
        op: &AssignOp,
        value: &Expr,
    ) -> Result<(), JsError> {
        let end_label = self.new_label();
        let short_label = self.new_label();
        if matches!(member.object.kind, ExprKind::Super) {
            match &member.property {
                MemberProperty::Name(name) => {
                    self.emit(Step::ResolveSuperRefName { name: *name });
                }
                MemberProperty::Computed(key) => {
                    // GetSuperBase runs the this-binding check before the key
                    // evaluates (spec 13.3.7.1); the base copy it leaves is
                    // consumed by ResolveSuperRefComputed.
                    self.emit(Step::GetSuperBase);
                    self.compile_expr(key)?;
                    self.emit(Step::ResolveSuperRefComputed);
                }
                MemberProperty::Private(_) => {
                    return Err(JsError::new(
                        ErrorKind::SyntaxError,
                        "super.#x is a syntax error".into(),
                    ));
                }
            }
        } else {
            self.compile_expr(&member.object)?;
            match &member.property {
                MemberProperty::Name(name) => {
                    self.emit(Step::ResolveMemberRefName { name: *name });
                }
                MemberProperty::Computed(key) => {
                    self.compile_expr(key)?;
                    self.emit(Step::ResolveMemberRefComputed);
                }
                MemberProperty::Private(atom) => {
                    self.emit(Step::ResolvePrivateRef { atom: *atom });
                }
            }
        }
        self.emit(Step::GetVarReference);
        match op {
            AssignOp::AndAssign => self.jump_if_false_keep(short_label),
            AssignOp::OrAssign => self.jump_if_true_keep(short_label),
            _ => self.jump_if_not_nullish_keep(short_label),
        }
        // The write path: the Keep re-pushed the old value — discard it,
        // evaluate the RHS, assign through the pre-resolved reference.
        self.emit(Step::Pop);
        self.compile_expr(value)?;
        self.emit(Step::PutVarReference);
        self.jump(end_label);
        // The short-circuit path: the Keep re-pushed the old value as the
        // expression result; drop the reference.
        self.place(short_label);
        self.emit(Step::PopVarReference);
        self.place(end_label);
        Ok(())
    }

    fn compile_member_assign(
        &mut self,
        member: &syntax::ast::MemberExpr,
        op: &AssignOp,
        value: &Expr,
    ) -> Result<(), JsError> {
        if matches!(
            op,
            AssignOp::AndAssign | AssignOp::OrAssign | AssignOp::NullishAssign
        ) {
            return self.compile_logical_assign(member, op, value);
        }
        if matches!(member.object.kind, ExprKind::Super) {
            // super.x = v / super[x] = v
            self.emit(Step::GetSuperBase);
            match &member.property {
                MemberProperty::Name(name) => {
                    let needs_old = matches!(
                        op,
                        AssignOp::AddAssign
                            | AssignOp::SubAssign
                            | AssignOp::MulAssign
                            | AssignOp::DivAssign
                            | AssignOp::RemAssign
                            | AssignOp::ExpAssign
                            | AssignOp::LeftShiftAssign
                            | AssignOp::RightShiftAssign
                            | AssignOp::UnsignedRightShiftAssign
                            | AssignOp::BitAndAssign
                            | AssignOp::BitXorAssign
                            | AssignOp::BitOrAssign
                    );
                    if needs_old {
                        self.emit(Step::Dup);
                        self.emit(Step::GetSuperName { name: *name });
                    }
                    self.compile_expr(value)?;
                    self.emit(Step::AssignSuperName {
                        name: *name,
                        op: *op,
                    });
                }
                MemberProperty::Computed(key) => {
                    self.compile_expr(key)?;
                    let needs_old = matches!(
                        op,
                        AssignOp::AddAssign
                            | AssignOp::SubAssign
                            | AssignOp::MulAssign
                            | AssignOp::DivAssign
                            | AssignOp::RemAssign
                            | AssignOp::ExpAssign
                            | AssignOp::LeftShiftAssign
                            | AssignOp::RightShiftAssign
                            | AssignOp::UnsignedRightShiftAssign
                            | AssignOp::BitAndAssign
                            | AssignOp::BitXorAssign
                            | AssignOp::BitOrAssign
                    );
                    if needs_old {
                        self.emit(Step::Dup2);
                        self.emit(Step::GetSuperComputedKeep);
                    }
                    self.compile_expr(value)?;
                    self.emit(Step::AssignSuperComputed { op: *op });
                }
                MemberProperty::Private(_) => {
                    return Err(JsError::new(
                        ErrorKind::SyntaxError,
                        "super.#x is a syntax error".into(),
                    ));
                }
            }
            return Ok(());
        }
        match &member.property {
            MemberProperty::Name(name) => {
                // Cut 35 slice 30: detect `this.name = value` in constructor
                // bodies to collect property patterns for store-cache pre-warm.
                if matches!(op, AssignOp::Assign)
                    && let ExprKind::Ident(ident) = &member.object.kind
                    && syntax::keywords::from_identifier(*ident)
                        == Some(syntax::keywords::Keyword::This)
                    && self.scope.as_ref().is_some_and(|s| s.this_slot.is_some())
                {
                    let (count, arr) = &mut self.this_writes;
                    if *count < 4 {
                        arr[*count] = *name;
                        *count += 1;
                    }
                }
                self.compile_expr(&member.object)?;
                let needs_old = is_compound_assign(op);
                if needs_old {
                    self.emit(Step::Dup);
                    self.emit(Step::GetMemberName { name: *name });
                }
                self.compile_expr(value)?;
                self.emit(Step::AssignMemberName {
                    name: *name,
                    op: *op,
                });
            }
            MemberProperty::Computed(key) => {
                self.compile_expr(&member.object)?;
                self.compile_expr(key)?;
                if is_compound_assign(op) {
                    // ToPropertyKey runs once, after the nullish check, with
                    // the converted key shared by the read and the write (spec
                    // 13.15.4 step 2.c).
                    self.emit(Step::Dup2);
                    self.emit(Step::GetMemberComputedKeep);
                }
                self.compile_expr(value)?;
                self.emit(Step::AssignMemberComputed { op: *op });
            }
            MemberProperty::Private(atom) => {
                self.compile_expr(&member.object)?;
                self.compile_expr(value)?;
                self.emit(Step::AssignPrivate {
                    atom: *atom,
                    op: *op,
                });
            }
        }
        Ok(())
    }

    /// Gap-close M6 slice 3: whether a member read compiles to the hoisted
    /// length. Inside the fast copy of a hoisted `for (…; K <op> RECV.length;
    /// …)` loop, a `RECV.length` read whose receiver resolves to the exact
    /// slot the guard probed lowers to a plain `LoadLocal` of the hidden
    /// slot — the probe verified the IntegerIndexed/no-own-`length` receiver
    /// and the loop's body purity (no calls, no RECV writes) makes the length
    /// loop-invariant, so the per-iteration member read and the slot agree.
    /// Emits the load and returns true; false leaves the member path to run
    /// (a shadowing declaration of the name resolves to a different slot and
    /// must keep the member read).
    fn try_hoisted_length_read(&mut self, member: &syntax::ast::MemberExpr) -> bool {
        let Some((recv_slot, hoist_slot)) = self.hoisted_length else {
            return false;
        };
        if member.optional || matches!(member.object.kind, ExprKind::Super) {
            return false;
        }
        let syntax::ast::MemberProperty::Name(prop) = &member.property else {
            return false;
        };
        if *prop != Self::length_atom() {
            return false;
        }
        let mut object = &member.object;
        while let ExprKind::Paren(inner) = &object.kind {
            object = inner;
        }
        let ExprKind::Ident(name) = &object.kind else {
            return false;
        };
        if !matches!(self.binding(*name), BindingLoc::Slot(slot) if slot == recv_slot) {
            return false;
        }
        self.emit(Step::LoadLocal { slot: hoist_slot });
        true
    }

    fn compile_member(&mut self, member: &syntax::ast::MemberExpr) -> Result<(), JsError> {
        if self.try_hoisted_length_read(member) {
            return Ok(());
        }
        if matches!(member.object.kind, ExprKind::Super) {
            self.emit(Step::GetSuperBase);
            match &member.property {
                MemberProperty::Name(name) => {
                    self.emit(Step::GetSuperName { name: *name });
                }
                MemberProperty::Computed(key) => {
                    self.compile_expr(key)?;
                    self.emit(Step::GetSuperComputed);
                }
                MemberProperty::Private(_) => {
                    return Err(JsError::new(
                        ErrorKind::SyntaxError,
                        "super.#x is a syntax error".into(),
                    ));
                }
            }
            return Ok(());
        }
        if member.optional {
            let short = self.new_label();
            let end = self.new_label();
            self.compile_expr(&member.object)?;
            self.emit(Step::Dup);
            self.jump_if_nullish_keep(short);
            self.compile_member_property_guarded(member)?;
            self.jump(end);
            self.place(short);
            self.emit(Step::Pop);
            self.emit(Step::Pop);
            self.emit(Step::Push(Value::Undefined));
            // The rest of the chain (keys, args, links) is skipped.
            self.emit(Step::SetChainShort);
            self.place(end);
        } else {
            self.compile_expr(&member.object)?;
            self.compile_member_property_guarded(member)?;
        }
        Ok(())
    }

    fn compile_member_property(&mut self, member: &syntax::ast::MemberExpr) -> Result<(), JsError> {
        match &member.property {
            MemberProperty::Name(name) => {
                self.emit(Step::GetMemberName { name: *name });
            }
            MemberProperty::Computed(key) => {
                self.compile_expr(key)?;
                self.emit(Step::GetMemberComputed);
            }
            MemberProperty::Private(atom) => {
                self.emit(Step::GetPrivate { atom: *atom });
            }
        }
        Ok(())
    }

    /// Compile call arguments. Returns the argument layout: `Some(argc)` when
    /// the plain (non-spread) arguments were pushed onto the value stack
    /// (the `CallFast` form), `None` when they went into the VM's argument
    /// vector (`ArgsBase` + `ArgsPush`/`ArgsSpread`, the `Call`/`Construct`/
    /// `SuperCall` form). `allow_fast` is false when the consumer needs the
    /// vector form regardless (constructs and super calls).
    fn compile_arguments(
        &mut self,
        args: &[Argument],
        allow_fast: bool,
    ) -> Result<Option<usize>, JsError> {
        if allow_fast
            && args.len() <= FAST_CALL_MAX_ARGS
            && args.iter().all(|a| matches!(a, Argument::Expr(_)))
        {
            for argument in args {
                if let Argument::Expr(expr) = argument {
                    self.compile_expr(expr)?;
                }
            }
            return Ok(Some(args.len()));
        }
        self.emit(Step::ArgsBase);
        for argument in args {
            match argument {
                Argument::Expr(expr) => {
                    self.compile_expr(expr)?;
                    self.emit(Step::ArgsPush);
                }
                Argument::Spread(expr) => {
                    self.compile_expr(expr)?;
                    self.emit(Step::ArgsSpread);
                }
            }
        }
        Ok(None)
    }

    fn compile_call(&mut self, call: &syntax::ast::CallExpr) -> Result<(), JsError> {
        // A tail-position call: every load below (callee, keys, args) is NOT
        // the tail call itself; the final call step re-checks the flag.
        let tail = self.tail;
        self.tail = false;
        if matches!(call.callee.kind, ExprKind::Super) {
            self.compile_arguments(&call.args, false)?;
            self.emit(Step::SuperCall);
            return Ok(());
        }
        if let ExprKind::Member(member) = &call.callee.kind {
            if matches!(member.object.kind, ExprKind::Super) {
                // super.m(args): this value first, then base, then the method.
                self.emit(Step::ThisValue);
                self.emit(Step::GetSuperBase);
                match &member.property {
                    MemberProperty::Name(name) => {
                        self.emit(Step::GetSuperName { name: *name });
                    }
                    MemberProperty::Computed(key) => {
                        self.compile_expr(key)?;
                        self.emit(Step::GetSuperComputed);
                    }
                    MemberProperty::Private(_) => {
                        return Err(JsError::new(
                            ErrorKind::SyntaxError,
                            "super.#m() is a syntax error".into(),
                        ));
                    }
                }
                if call.optional {
                    self.compile_optional_call_tail(&call.args)?;
                } else {
                    match self.compile_arguments(&call.args, true)? {
                        Some(argc) => self.emit(Step::CallFast {
                            argc: argc as u8,
                            direct_eval: false,
                        }),
                        None => self.emit(Step::Call { direct_eval: false }),
                    }
                }
                return Ok(());
            }
            // obj.m(args)
            if self.try_compile_apply_call(member, call, tail)? {
                return Ok(());
            }
            self.compile_expr(&member.object)?;
            self.emit(Step::Dup);
            if member.optional {
                // `?.` on the member: a nullish object short-circuits the
                // whole chain — the property access and the call are skipped.
                let short = self.new_label();
                let end = self.new_label();
                self.jump_if_nullish_keep(short);
                // The keep consumed the dup'd object on the fall-through;
                // re-dup so the property read leaves the base for `this`.
                self.emit(Step::Dup);
                self.compile_member_property_guarded(member)?;
                if call.optional {
                    self.compile_optional_call_tail(&call.args)?;
                } else {
                    self.compile_call_args_guarded(&call.args, false)?;
                }
                self.jump(end);
                self.place(short);
                self.emit(Step::Pop);
                self.emit(Step::Pop);
                self.emit(Step::Push(Value::Undefined));
                self.emit(Step::SetChainShort);
                self.place(end);
            } else {
                self.compile_member_property_guarded(member)?;
                if call.optional {
                    // The callee is on top: nullish → undefined.
                    self.compile_optional_call_tail(&call.args)?;
                } else {
                    // The member chain may still have short-circuited
                    // upstream (`a?.b.m(args)`): skip the argument
                    // evaluation and call.
                    self.tail = tail;
                    self.compile_call_args_guarded(&call.args, false)?;
                }
            }
            return Ok(());
        }
        // A plain callee. Parentheses are transparent to references (spec
        // 13.4.3: `(a.b)()` calls with the base object as `this`), but an
        // optional chain inside the parens terminates there — the nullish
        // result is a value, so the call still runs (and throws a TypeError
        // on `undefined`).
        let mut callee = &call.callee;
        while let ExprKind::Paren(inner) = &callee.kind {
            callee = inner;
        }
        if let ExprKind::Member(member) = &callee.kind
            && !matches!(member.object.kind, ExprKind::Super)
        {
            self.compile_expr(&member.object)?;
            self.emit(Step::Dup);
            if member.optional {
                let short = self.new_label();
                let end = self.new_label();
                self.jump_if_nullish_keep(short);
                self.emit(Step::Dup);
                self.compile_member_property_guarded(member)?;
                self.jump(end);
                self.place(short);
                self.emit(Step::Pop);
                self.emit(Step::Pop);
                // this + callee both `undefined`: the call runs on the value
                // the chain produced (spec — the chain ended at the paren).
                self.emit(Step::Push(Value::Undefined));
                self.emit(Step::Push(Value::Undefined));
                self.place(end);
            } else {
                self.compile_member_property_guarded(member)?;
            }
            self.emit(Step::ClearChainShort);
            if call.optional {
                self.compile_optional_call_tail(&call.args)?;
            } else {
                self.tail = tail;
                self.compile_call_args_guarded(&call.args, false)?;
            }
            return Ok(());
        }
        let direct_eval = matches!(
            call.callee.kind,
            ExprKind::Ident(id) if crux::lookup(id) == JsString::from_utf8("eval")
        );
        if self.with_depth > 0
            && let ExprKind::Ident(name) = &callee.kind
        {
            // A plain identifier callee under a `with`: the call's `this`
            // is the WithBaseObject of the environment that resolved it,
            // not `undefined` (spec 13.4.3 step 4.b).
            self.emit(Step::ResolveVarIdent { name: *name });
            self.emit(Step::GetVarReferenceThis);
            self.emit(Step::GetVarReference);
            if call.optional {
                self.compile_optional_call_tail(&call.args)?;
            } else {
                self.tail = tail;
                self.compile_call_args_guarded(&call.args, direct_eval)?;
            }
            self.emit(Step::PopVarReference);
            return Ok(());
        }
        // Cut 46: a tail call whose callee is the enclosing named function
        // expression's own name, resolving only through the (immutable)
        // self-binding scope — statically the running body itself. The call
        // compiles to `TailCallSelf`: the arguments only, no receiver/callee
        // push, and the handler rebinds the frame in place and re-enters the
        // body (no callee lookup, no context swap, no runtime round-trip).
        // Gated on the certified capture-free, arguments-free frame path —
        // those shapes re-create no per-call env, so the in-place rebind is
        // exactly what the frame replacement would do. The `Env` binding
        // check excludes any shadowing param/local/captured/global binding;
        // `binding` returns `Env` for the self-binding because the scan
        // never sees the named expression's own scope.
        if tail
            && let ExprKind::Ident(name) = &callee.kind
            && self.named_expression
            && self.function_name == Some(*name)
            && self
                .scope
                .as_ref()
                .is_some_and(|s| s.context_names.is_empty())
            && self
                .scope
                .as_ref()
                .is_some_and(|s| s.arguments_slot.is_none())
            && matches!(self.binding(*name), BindingLoc::Env)
            && !call.optional
            && self.chain_depth == 0
        {
            let saved = self.tail;
            self.tail = false; // the arguments are never in tail position
            match self.compile_arguments(&call.args, true)? {
                Some(argc) => {
                    self.tail = saved;
                    self.emit(Step::TailCallSelf { argc: argc as u8 });
                }
                None => {
                    // Cut 51: the vector form (a spread or more than
                    // `FAST_CALL_MAX_ARGS` plain arguments) —
                    // `compile_arguments` already built the argument vector;
                    // the jump rebinds the frame from it.
                    self.tail = saved;
                    self.emit(Step::TailCallSelfVector);
                }
            }
            return Ok(());
        }
        // Cut 47: the same shape in a body that is NOT a named expression —
        // a top-level or enclosing function declaration whose own name
        // resolves through the global/outer env, where it COULD have been
        // reassigned. The receiver and callee are pushed and loaded normally
        // (the machine code must see the resolved callee); the compiled step
        // compares it against the running closure and jumps to the body's
        // re-entry on a match, else runs the general `tail_call` helper.
        if tail
            && let ExprKind::Ident(name) = &callee.kind
            && !self.named_expression
            && self.function_name == Some(*name)
            && self
                .scope
                .as_ref()
                .is_some_and(|s| s.context_names.is_empty())
            && self
                .scope
                .as_ref()
                .is_some_and(|s| s.arguments_slot.is_none())
            && matches!(self.binding(*name), BindingLoc::Env)
            && !call.optional
            && self.chain_depth == 0
        {
            self.emit(Step::Push(Value::Undefined));
            self.compile_expr(&call.callee)?;
            let saved = self.tail;
            self.tail = false; // the arguments are never in tail position
            match self.compile_arguments(&call.args, true)? {
                Some(argc) => {
                    self.tail = saved;
                    self.emit(Step::TailCallSelfCheck { argc: argc as u8 });
                }
                None => {
                    // Cut 51: the vector form — `compile_arguments` already
                    // built the argument vector; the jump rebinds the frame
                    // from it after the identity check.
                    self.tail = saved;
                    self.emit(Step::TailCallSelfCheckVector);
                }
            }
            return Ok(());
        }
        // Cut 35 slice 2/4: a plain named callee with an undefined receiver
        // fuses the receiver push and the callee load into the call step (2
        // fewer dispatches per call in a hot loop). Requires no `?.` on the
        // call, no `with`, no `eval`, and no enclosing optional chain
        // (`chain_depth == 0` — the guard would be dead anyway, so there is
        // no short-circuit path to skip the call).
        //
        // The callee's GetValue (spec 13.4.3 step 2) moves after the
        // arguments (step 4): the handler reads the global cell / frame slot
        // once the args are on the stack. Unobservable for a declared var's
        // data property or a frame slot — except when an argument WRITES the
        // callee: a certified script's args can write a declared var only
        // directly, so a global callee (a certified function, never
        // assigned) is always safe, and a slot callee fuses only when no
        // argument expression assigns its name.
        if !call.optional
            && !direct_eval
            && self.chain_depth == 0
            && let ExprKind::Ident(name) = &callee.kind
            && call.args.len() <= 2
            && call.args.iter().all(|a| matches!(a, Argument::Expr(_)))
        {
            let step =
                match self.binding(*name) {
                    // A global callee fuses only when its binding is never
                    // assigned anywhere in the script (its global value is then
                    // stable — the certified gate guarantees this on the frame
                    // path, and the assigned set covers the global-only path,
                    // including writes inside function bodies) and no argument
                    // can run arbitrary code (a builtin like
                    // `Object.defineProperty(globalThis, ...)` could rewrite the
                    // global callee).
                    BindingLoc::Global
                        if !self
                            .script_assigned
                            .as_ref()
                            .is_some_and(|assigned| assigned.contains(name))
                            && !call.args.iter().any(
                                |a| matches!(a, Argument::Expr(e) if expr_contains_call(e)),
                            ) =>
                    {
                        Some(Step::CallFastGlobal {
                            name: *name,
                            argc: call.args.len() as u8,
                            direct_eval: false,
                        })
                    }
                    // A slot callee (certified-value var — frame path only): the
                    // slot read is side-effect-free, so the only ordering hazard
                    // is an argument that WRITES the slot, which a certified
                    // script's args can do only directly.
                    BindingLoc::Slot(slot)
                        if !call.args.iter().any(
                            |a| matches!(a, Argument::Expr(e) if expr_assigns_name(e, *name)),
                        ) =>
                    {
                        Some(Step::CallFastSlot {
                            slot,
                            argc: call.args.len() as u8,
                        })
                    }
                    _ => None,
                };
            if let Some(step) = step {
                for argument in &call.args {
                    if let Argument::Expr(expr) = argument {
                        self.compile_expr(expr)?;
                    }
                }
                self.tail = tail;
                if tail {
                    match step {
                        Step::CallFastGlobal { name, argc, .. } => {
                            self.emit(Step::TailCallFastGlobal { name, argc });
                        }
                        Step::CallFastSlot { slot, argc } => {
                            self.emit(Step::TailCallFastSlot { slot, argc });
                        }
                        other => self.emit(other),
                    }
                } else {
                    self.emit(step);
                }
                return Ok(());
            }
        }
        self.emit(Step::Push(Value::Undefined));
        self.compile_expr(&call.callee)?;
        if call.optional {
            self.compile_optional_call_tail(&call.args)?;
        } else {
            // An upstream `?.` in the callee (`(a?.b)()`) skips the arguments.
            self.tail = tail;
            self.compile_call_args_guarded(&call.args, direct_eval)?;
        }
        Ok(())
    }

    /// Call-site recognition of `Function.prototype.apply`/`call` (perf.md
    /// "remaining apply floor"): `f.apply(x, arr)` / `f.call(x, ...)`
    /// compiles to the normal member read — a shadowed `apply`/`call`
    /// resolves onto the stack and is called normally — plus `Step::CallApply`,
    /// whose handler calls `f` directly when the resolved function is the
    /// realm's intrinsic (skipping the builtin dispatch, the per-call
    /// argument-list build, and the pooled-Vm round trip) and falls back to
    /// the general call otherwise. Only the fast form takes the step: all
    /// plain expressions, at most `FAST_CALL_MAX_ARGS` total arguments, no
    /// optional chain anywhere (an upstream `?.` guard would need the
    /// short-circuited argument skip), no tail position (a proper tail call
    /// of the resolved function would need a tail step), and an object
    /// without an internal optional chain.
    fn try_compile_apply_call(
        &mut self,
        member: &syntax::ast::MemberExpr,
        call: &syntax::ast::CallExpr,
        tail: bool,
    ) -> Result<bool, JsError> {
        let kind = match &member.property {
            MemberProperty::Name(name) if crux::lookup(*name) == JsString::from_utf8("apply") => {
                ApplyKind::Apply
            }
            MemberProperty::Name(name) if crux::lookup(*name) == JsString::from_utf8("call") => {
                ApplyKind::Call
            }
            _ => return Ok(false),
        };
        if tail
            || member.optional
            || call.optional
            || self.chain_depth != 0
            || call.args.len() > FAST_CALL_MAX_ARGS
            || !call.args.iter().all(|a| matches!(a, Argument::Expr(_)))
            || expr_may_short_circuit(&member.object)
        {
            return Ok(false);
        }
        // `[..., f]` then `Dup` + the member read: `[..., f, apply/call]`
        // exactly as the general member call, so the resolved function (and
        // a shadowing own/prototype `apply`) is whatever the spec's GetValue
        // produces — the step compares it against the intrinsic.
        self.compile_expr(&member.object)?;
        self.emit(Step::Dup);
        self.compile_member_property_guarded(member)?;
        for argument in &call.args {
            if let Argument::Expr(expr) = argument {
                self.compile_expr(expr)?;
            }
        }
        self.emit(Step::CallApply {
            argc: call.args.len() as u8,
            kind,
        });
        Ok(true)
    }

    /// The optional-call tail: nullish callee → *undefined* (no argument
    /// evaluation); otherwise call. The short path pops three values — the
    /// receiver (the `this`/object pushed before the callee), the callee, and
    /// the dup'd callee the nullish test pushed back — so the chain leaves
    /// exactly `[undefined]` (a two-pop short leaked the receiver into the
    /// enclosing expression, shifting every later stack read).
    fn compile_optional_call_tail(&mut self, args: &[Argument]) -> Result<(), JsError> {
        let short = self.new_label();
        let end = self.new_label();
        self.emit(Step::Dup);
        self.jump_if_nullish_keep(short);
        self.compile_call_args_guarded(args, false)?;
        self.jump(end);
        self.place(short);
        self.emit(Step::Pop);
        self.emit(Step::Pop);
        self.emit(Step::Pop);
        self.emit(Step::Push(Value::Undefined));
        self.emit(Step::SetChainShort);
        self.place(end);
        Ok(())
    }

    fn compile_template(&mut self, template: &syntax::ast::TemplateLiteral) -> Result<(), JsError> {
        let first = template
            .quasis
            .first()
            .map(|q| q.cooked.clone().unwrap_or_else(|| JsString::from_utf8("")))
            .unwrap_or_else(|| JsString::from_utf8(""));
        self.emit(Step::PushStr(first));
        for (index, expr) in template.exprs.iter().enumerate() {
            self.compile_expr(expr)?;
            self.emit(Step::ConcatStr);
            let quasi = template
                .quasis
                .get(index + 1)
                .map(|q| q.cooked.clone().unwrap_or_else(|| JsString::from_utf8("")))
                .unwrap_or_else(|| JsString::from_utf8(""));
            self.emit(Step::ConcatStrConst(quasi));
        }
        Ok(())
    }

    /// A class definition whose heritage or a computed element name contains a
    /// suspension point: the VM sets up the class scope, evaluates the
    /// heritage and each computed name in order (suspending as needed), and
    /// builds the class from the precomputed keys (spec 15.7.14).
    fn compile_class(&mut self, class: &Class) -> Result<(), JsError> {
        // An anonymous class expression evaluated as an assignment/declaration
        // initializer inherits the binding's name (NamedEvaluation) — it must
        // be in place before the static field initializers run (spec 15.7.14
        // step 8), so it is threaded here rather than applied after.
        let binding = self.pending_class_name.take().or(class.name);
        let key_count = class
            .elements
            .iter()
            .filter(|e| has_computed_public_name(e))
            .count();
        self.emit(Step::ClassBegin {
            class: Box::new(class.clone()),
            binding,
            key_count,
        });
        // Every part of a class is strict mode code (spec 15.2.1): function
        // expressions/arrows in the heritage and computed keys inherit strict
        // even from a sloppy script.
        self.class_depth += 1;
        if let Some(heritage) = &class.heritage {
            self.compile_expr(heritage)?;
            self.emit(Step::ClassHeritage);
        }
        for element in &class.elements {
            if let Some(expr) = computed_public_name(element) {
                self.compile_expr(expr)?;
                self.emit(Step::ClassKeyToPropertyKey);
            }
        }
        self.class_depth -= 1;
        self.emit(Step::ClassFinish {
            class: Box::new(class.clone()),
            binding,
            key_count,
        });
        Ok(())
    }

    fn compile_object(&mut self, literal: &ObjectLiteral) -> Result<(), JsError> {
        self.emit(Step::ObjectBegin);
        for property in &literal.props {
            match property {
                ObjectProperty::Init {
                    key,
                    value,
                    shorthand,
                } => {
                    let set_name = crate::function::is_anonymous_function_definition(value);
                    match key {
                        PropertyName::Ident(id) => {
                            self.compile_expr(value)?;
                            self.emit(Step::ObjectInitName {
                                name: *id,
                                set_name,
                                shorthand: *shorthand,
                            });
                        }
                        PropertyName::Computed(key_expr) => {
                            self.compile_expr(key_expr)?;
                            // ToPropertyKey before the value evaluates (spec
                            // 13.2.5.5 step 1 vs 6.a).
                            self.emit(Step::ObjectKeyToPropertyKey);
                            self.compile_expr(value)?;
                            self.emit(Step::ObjectInitComputed { set_name });
                        }
                        PropertyName::Str(text) => {
                            self.compile_expr(value)?;
                            let id = crux::intern(text.as_slice());
                            self.emit(Step::ObjectInitName {
                                name: id,
                                set_name,
                                shorthand: false,
                            });
                        }
                        PropertyName::Number(n) => {
                            self.compile_expr(value)?;
                            let text = crux::convert::to_string(&Value::Number(*n))?;
                            let id = crux::intern(text.as_slice());
                            self.emit(Step::ObjectInitName {
                                name: id,
                                set_name,
                                shorthand: false,
                            });
                        }
                    }
                }
                ObjectProperty::Method { key, function } => match key {
                    PropertyName::Ident(id) => {
                        self.emit(Step::ObjectMethodName {
                            name: *id,
                            function: function.clone(),
                        });
                    }
                    PropertyName::Computed(key_expr) => {
                        self.compile_expr(key_expr)?;
                        self.emit(Step::ObjectMethodComputed {
                            function: function.clone(),
                        });
                    }
                    PropertyName::Str(text) => {
                        let id = crux::intern(text.as_slice());
                        self.emit(Step::ObjectMethodName {
                            name: id,
                            function: function.clone(),
                        });
                    }
                    PropertyName::Number(n) => {
                        let text = crux::convert::to_string(&Value::Number(*n))?;
                        let id = crux::intern(text.as_slice());
                        self.emit(Step::ObjectMethodName {
                            name: id,
                            function: function.clone(),
                        });
                    }
                },
                ObjectProperty::Get { key, body } => {
                    self.compile_accessor(key, true, None, body)?;
                }
                ObjectProperty::Set {
                    key,
                    param,
                    init,
                    body,
                } => {
                    let element = BindingElement {
                        pattern: param.clone(),
                        init: init.clone(),
                        rest: false,
                        span: body.span,
                    };
                    self.compile_accessor(key, false, Some(element), body)?;
                }
                ObjectProperty::Spread(expr) => {
                    self.compile_expr(expr)?;
                    self.emit(Step::ObjectSpread);
                }
            }
        }
        Ok(())
    }

    fn compile_accessor(
        &mut self,
        key: &PropertyName,
        get: bool,
        param: Option<BindingElement>,
        body: &syntax::ast::Block,
    ) -> Result<(), JsError> {
        match key {
            PropertyName::Ident(id) => {
                self.emit(Step::ObjectAccessorName {
                    name: *id,
                    get,
                    param,
                    body: body.clone(),
                });
            }
            PropertyName::Computed(key_expr) => {
                self.compile_expr(key_expr)?;
                self.emit(Step::ObjectAccessorComputed {
                    get,
                    param,
                    body: body.clone(),
                });
            }
            PropertyName::Str(text) => {
                let id = crux::intern(text.as_slice());
                self.emit(Step::ObjectAccessorName {
                    name: id,
                    get,
                    param,
                    body: body.clone(),
                });
            }
            PropertyName::Number(n) => {
                let text = crux::convert::to_string(&Value::Number(*n))?;
                let id = crux::intern(text.as_slice());
                self.emit(Step::ObjectAccessorName {
                    name: id,
                    get,
                    param,
                    body: body.clone(),
                });
            }
        }
        Ok(())
    }
}

/// The certified body's capture context (Cut 3 continuation): its lexical
/// environment is the per-call declarative environment holding the captured
/// bindings.
pub(crate) fn context_env(env: &EnvRef) -> &DeclarativeEnv {
    match &**env {
        EnvRecord::Declarative(declarative) => declarative,
        _ => unreachable!("a context slot without a capture-context env"),
    }
}

/// Whether an env is transparent to the static context-chain walk: a
/// per-iteration copy (holds only the loop-head names) or a named function
/// expression's self-binding scope (holds only the function's own name) —
/// a reference to an enclosing body's captured binding must reach past
/// them.
fn is_context_transparent(env: &EnvRef) -> bool {
    matches!(&**env, EnvRecord::Declarative(e) if e.context_transparent.get())
}

pub fn is_compound_assign(op: &AssignOp) -> bool {
    matches!(
        op,
        AssignOp::AddAssign
            | AssignOp::SubAssign
            | AssignOp::MulAssign
            | AssignOp::DivAssign
            | AssignOp::RemAssign
            | AssignOp::ExpAssign
            | AssignOp::LeftShiftAssign
            | AssignOp::RightShiftAssign
            | AssignOp::UnsignedRightShiftAssign
            | AssignOp::BitAndAssign
            | AssignOp::BitXorAssign
            | AssignOp::BitOrAssign
    )
}

/// The continue target of a labelled statement, when it is a loop.
fn labeled_continue_target(body: &Stmt) -> Option<(usize, usize)> {
    // The label scope is resolved against the loop scope when the loop is
    // compiled beneath it; `continue label` uses the innermost loop scope
    // whose break target the label's break target shares. We represent the
    // target by deferring to the loop scope: the label's continue target is
    // marked with a sentinel that continue_target resolves through the loop
    // scopes.
    let is_loop = matches!(
        body.kind,
        StmtKind::While { .. }
            | StmtKind::DoWhile { .. }
            | StmtKind::For { .. }
            | StmtKind::ForIn { .. }
            | StmtKind::ForOf { .. }
    );
    if is_loop { Some((usize::MAX, 0)) } else { None }
}

/// The jump targets of a step (Cut 69), mirroring
/// `crates/jit/src/compiler.rs::step_targets` — the JIT compiler's
/// back-edge detector. The runtime owns the [`Step`] enum, so the mirror
/// lives here; keep the two in sync (a target added on one side but not
/// the other skews the loop heuristic, never semantics).
fn step_targets(step: &Step) -> Vec<usize> {
    match step {
        Step::Jump(t)
        | Step::JumpIfFalse(t)
        | Step::JumpIfTrue(t)
        | Step::JumpIfFalseKeep(t)
        | Step::JumpIfTrueKeep(t)
        | Step::JumpIfNullishKeep(t)
        | Step::JumpIfNotNullishKeep(t)
        | Step::Break { target: t }
        | Step::Continue { target: t } => vec![*t],
        Step::JumpIfLtImm { target, .. }
        | Step::JumpIfLeImm { target, .. }
        | Step::JumpIfGtImm { target, .. }
        | Step::JumpIfGeImm { target, .. }
        | Step::JumpIfEqImm { target, .. }
        | Step::JumpIfNeqImm { target, .. }
        | Step::JumpIfLtGlobalImm { target, .. }
        | Step::JumpIfLeGlobalImm { target, .. }
        | Step::JumpIfGtGlobalImm { target, .. }
        | Step::JumpIfGeGlobalImm { target, .. }
        | Step::JumpIfRelLimit { target, .. } => vec![*target],
        Step::TypedArrayLengthHoist { target } => vec![*target],
        Step::FastLoopHead {
            body_start, after, ..
        } => vec![*body_start, *after],
        Step::JumpIfChainShort(t) => vec![*t],
        Step::Exit { after } => vec![*after],
        Step::SwitchTest { case } => vec![*case],
        Step::ForInNext { back, .. } | Step::ForOfNext { back, .. } => vec![*back],
        Step::ForOfNextBindLocal { back, .. } => vec![*back],
        Step::DestructureUndef { use_default } => vec![*use_default],
        _ => Vec::new(),
    }
}

/// Cut 69: whether the body contains a loop — a back edge (a step whose
/// jump targets include a step index before its own, the exact rule
/// [`step_targets`] feeds the JIT's `back_targets`), a fused/register
/// loop step whose back edge is implicit ([`Step::FastLoopHead`]/
/// [`Step::RunRegBody`]), or a self-tail-call step (the callee is
/// statically the running body itself — the interpreter's TCO loop
/// re-enters the body's entry without re-consulting the JIT, so a
/// consult-count threshold could never promote a recursive chain). All
/// of these run once with many internal iterations, so a pure count
/// would never promote them; they compile on first JIT use.
pub(crate) fn body_has_loop(steps: &[Step]) -> bool {
    for (index, step) in steps.iter().enumerate() {
        if matches!(
            step,
            Step::FastLoopHead { .. }
                | Step::RunRegBody { .. }
                | Step::TailCallSelf { .. }
                | Step::TailCallSelfCheck { .. }
                | Step::TailCallSelfVector
                | Step::TailCallSelfCheckVector
        ) {
            return true;
        }
        for target in step_targets(step) {
            if target < index {
                return true;
            }
        }
    }
    false
}

/// Whether the body contains a `Step::CallApply` site (M10): the JIT's
/// per-run context snapshots the realm's `apply`/`call` intrinsic bits
/// only for bodies with one.
pub(crate) fn body_has_call_apply(steps: &[Step]) -> bool {
    steps
        .iter()
        .any(|step| matches!(step, Step::CallApply { .. }))
}

/// Cut 25: whether `step` is safe to run on the CALLER's Vm (a certified
/// body whose every step allows it is a *leaf* — see [`CompiledBody::leaf`]).
/// Every step that re-enters the VM with a fresh frame (calls/constructs),
/// reads the running execution context — the caller's, when inlined — or
/// touches a VM stack the caller's abrupt-completion machinery walks
/// (try/pending/for-of/for-in/destructure/env) disqualifies the body. The
/// remaining steps touch only the value stack, the frame, the capture
/// context, the global cache, and the completion register, all of which the
/// inline run saves and restores.
fn steps_are_leaf(steps: &[Step]) -> bool {
    steps.iter().all(|step| {
        !matches!(
            step,
            // Re-entry: a nested call/construct/tagged template runs on its
            // own Vm. A leaf must contain none, so it cannot recurse.
            Step::Call { .. }
                | Step::CallFast { .. }
                | Step::CallFastGlobal { .. }
                | Step::CallFastSlot { .. }
                | Step::CallFastSlotStore { .. }
                | Step::CallFastGlobalStore { .. }
                | Step::TailCall { .. }
                | Step::TailCallFast { .. }
                | Step::TailCallFastGlobal { .. }
                | Step::TailCallFastSlot { .. }
                | Step::TailCallSelf { .. }
                | Step::TailCallSelfCheck { .. }
                | Step::TailCallSelfVector
                | Step::TailCallSelfCheckVector
                | Step::TailTaggedTemplate(_)
                | Step::Construct
                | Step::SuperCall
                | Step::TaggedTemplate(_)
                | Step::ImportCall { .. }
                | Step::ImportMeta
                | Step::ArgsBase
                | Step::ArgsPush
                | Step::ArgsSpread
                // The running execution context's env: an inlined body sees
                // the caller's env, so every reference-resolution and
                // reference-machinery step is out.
                | Step::LoadIdent { .. }
                | Step::ResolveVarIdent { .. }
                | Step::GetVarReference
                | Step::GetVarReferenceThis
                | Step::PutVarReference
                | Step::PutVarReferenceOp { .. }
                | Step::UpdateVarReference { .. }
                | Step::PopVarReference
                | Step::DeleteIdent { .. }
                | Step::TypeofIdent { .. }
                | Step::UpdateIdent { .. }
                | Step::ResolveMemberRefName { .. }
                | Step::ResolveMemberRefComputed
                | Step::ResolvePrivateRef { .. }
                | Step::ResolveSuperRefName { .. }
                | Step::ResolveSuperRefComputed
                | Step::GetSuperBase
                | Step::GetSuperName { .. }
                | Step::GetSuperComputed
                | Step::GetSuperComputedKeep
                | Step::AssignSuperName { .. }
                | Step::AssignSuperComputed { .. }
                | Step::DeleteSuper
                | Step::PrivateIn { .. }
                | Step::UpdateSuperName { .. }
                | Step::UpdateSuperComputed { .. }
                | Step::UpdatePrivate { .. }
                | Step::AssignPrivate { .. }
                | Step::NewTarget
                | Step::ThisValue
                // Closure creation captures the running context's env.
                | Step::CreateFunction { .. }
                | Step::CreateArrow { .. }
                | Step::FunctionDecl { .. }
                | Step::FunctionDeclInit { .. }
                | Step::ObjectMethodName { .. }
                | Step::ObjectMethodComputed { .. }
                | Step::ObjectAccessorName { .. }
                | Step::ObjectAccessorComputed { .. }
                | Step::SetFunctionName { .. }
                // Environment machinery (block/with/try/using/per-iteration
                // envs): writes the env stack the caller's unwinds walk.
                | Step::EnterBlock { .. }
                | Step::LeaveBlock
                | Step::EnterWith
                | Step::EnterTry { .. }
                | Step::Exit { .. }
                | Step::CatchBind { .. }
                | Step::FinallyEnd
                | Step::PerIteration { .. }
                | Step::EnterLoopEnv { .. }
                | Step::EnterIterTdzEnv { .. }
                | Step::LeaveIterTdzEnv
                | Step::EnterPerIteration { .. }
                | Step::UsingInit { .. }
                | Step::DeclInit { .. }
                // The per-iteration READS are leaf-safe (Cut 28): a closure
                // body's `LoadPerIteration`/`StorePerIteration`/
                // `UpdatePerIteration` target its own captured per-iteration
                // env through `lexical_env`, which the inline run sets; the
                // env-CREATING steps above stay excluded.
                // `Break`/`Continue` (gap-close M6 follow-up): a leaf's
                // compiled run keeps the fused-loop counter in machine state
                // synced to the binding by a single `FastLoopStore` at the
                // loop's end step, and a transfer out of the loop — a `break`
                // to the loop end or a labeled `break`/`continue` to an
                // enclosing label — jumps the machine code past that step
                // mid-run, leaving the caller's Vm inconsistent when the body
                // is leaf-inlined (the JIT leaf run of such a body corrupted
                // the caller: blank output / wrong calls after the leaf
                // returned). A switch's breaks never reach a leaf (the
                // switch steps are excluded below); the leaf-eligible
                // transfers all exit the body's own loop or label, so such
                // bodies run the general path (their own frame/buffer),
                // which is exact.
                | Step::Break { .. }
                | Step::Continue { .. }
                // Iterator machinery: protocol calls plus the for-of/for-in
                // stacks the caller's break/return/throw paths close.
                | Step::ForInBegin
                | Step::ForInNext { .. }
                | Step::ForInBind { .. }
                | Step::ForInRestore
                | Step::ForOfBegin { .. }
                | Step::ForOfNext { .. }
                | Step::ForOfNextBindLocal { .. }
                | Step::ForOfBind { .. }
                | Step::ForOfBindLocal { .. }
                | Step::ForOfBindGlobal { .. }
                | Step::ForOfRestore
                | Step::ForOfClose
                | Step::AsyncForOfBegin { .. }
                | Step::AsyncForOfNext
                | Step::AsyncForOfTest { .. }
                | Step::AsyncForOfBind { .. }
                | Step::AsyncForOfRestore
                | Step::AsyncForOfClose
                | Step::ObjectSpread
                | Step::ArraySpread
                | Step::Destructure { .. }
                | Step::DestructureBegin
                | Step::DestructureNext
                | Step::DestructureUndef { .. }
                | Step::DestructureRest
                | Step::DestructureObjCoercible
                | Step::DestructureObjKey { .. }
                | Step::DestructureObjKeyComputed
                | Step::DestructureObjKeyStore
                | Step::DestructureObjKeyGet
                | Step::DestructureObjRest { .. }
                | Step::DestructureClose
                | Step::DestructureObjEnd
                // Suspension.
                | Step::Yield { .. }
                | Step::Await
                | Step::YieldStarBegin
                | Step::YieldStarNext { .. }
                | Step::YieldStarResume { .. }
                | Step::AsyncYieldStarBegin
                | Step::AsyncYieldStarNext { .. }
                | Step::AsyncYieldStarInspect { .. }
                | Step::AsyncYieldStarResume { .. }
                // Control machinery the inline run cannot reproduce (never
                // certified, listed for completeness).
                | Step::SwitchDisc
                | Step::SwitchTest { .. }
                | Step::ClassBegin { .. }
                | Step::ClassHeritage
                | Step::ClassKeyToPropertyKey
                | Step::ClassFinish { .. }
                | Step::RegExpLiteral { .. }
                // `CreateArguments` (Cut 60): the helper writes the body's
                // `arguments` slot through `vm.frame`, but an inlined leaf's
                // frame is a PRIVATE buffer (`run_jit_leaf` builds its own,
                // separate from `vm.frame`) — a helper-written frame slot is
                // wrong for a leaf. The mapped form additionally reads the
                // running context's `function` (the caller's, when inlined).
                // Both stay out of leaves.
                | Step::CreateArguments { .. }
        ) && !string_literal_step_reads_body(step)
    })
}

/// Cut 54: a step whose JIT lowering reads its payload back from the RUNNING
/// body via `JitCallContext::body` (a step-index helper). An inlined leaf's
/// helpers see the CALLER's body, so these must not inline — they run on the
/// general path with their own Vm/context instead (where `ctx.body` is the
/// callee's own). `ConcatStr` is safe (it takes both operands by value); the
/// const forms carry their `JsString`/`Value` payload in the step.
fn string_literal_step_reads_body(step: &Step) -> bool {
    match step {
        Step::PushStr(_) | Step::ConcatStrConst(_) => true,
        Step::Push(value) => value_is_heap(value),
        Step::RunRegBody { ops } => ops.iter().any(leaf_op_has_heap_const),
        _ => false,
    }
}

fn value_is_heap(value: &Value) -> bool {
    matches!(value.kind(), ValueKind::String(_) | ValueKind::BigInt(_))
}

fn leaf_op_has_heap_const(op: &LeafOp) -> bool {
    let operand =
        |operand: &RegOperand| matches!(operand, RegOperand::Const(value) if value_is_heap(value));
    match op {
        LeafOp::LoadConst(value) | LeafOp::BinConst { value, .. } => value_is_heap(value),
        LeafOp::StoreMemberName { value, .. } => operand(value),
        LeafOp::StoreMemberComputed { key, value } => operand(key) || operand(value),
        LeafOp::StoreMemberComputedLocal { key, .. } => operand(key),
        LeafOp::CompoundMemberComputedLocal { key, rhs, .. } => operand(key) || operand(rhs),
        LeafOp::UpdateMemberComputedLocal { key, .. } => operand(key),
        LeafOp::GetMemberComputed { key, .. } | LeafOp::GetMemberComputedLocal { key, .. } => {
            operand(key)
        }
        _ => false,
    }
}

/// One value on the lowering's shadow stack: a `Load*`/`Push` result. `Acc`
/// is the value currently held by the register executor's accumulator (the
/// only value that can sit at the bottom of a binary pair). Carried by
/// [`LeafOp::StoreMemberName`] for the value operand (the binary ops encode
/// the operand source in their variants instead).
#[derive(Debug, Clone)]
pub enum RegOperand {
    Acc,
    /// The value was spilled onto the value stack by `PushAcc` (Cut 35
    /// slice 10): it is consumed by `BinAccPop`'s pop, not by any load.
    Spilled,
    /// The accumulator-loop counter (Cut 35 slice 16): the body read it
    /// via `Step::PushAcc`; a `LoadCounter` (or a member op's operand
    /// resolution) reads the dedicated `Vm::loop_counter` field directly —
    /// no stack round-trip since slice 21. At most two reads per run (the
    /// computed-store key + value shape; the lowering guard caps the
    /// `PushAcc` count).
    Counter,
    Reg {
        slot: usize,
        tdz: bool,
    },
    /// A post-increment/--decrement key (`a[l++] = v`): loading the operand
    /// reads the slot, writes the update back, and yields the OLD value —
    /// exactly what `Step::UpdateLocal` with `prefix: false` computes. Only
    /// the computed member store consumes it (any other position — a read
    /// key, a binary operand, a plain store value — keeps the body on the
    /// step path, where the `UpdateLocal` step's ordering is preserved).
    PostInc {
        slot: usize,
        tdz: bool,
        op: UpdateOp,
    },
    Ctx {
        index: usize,
    },
    PerIter {
        index: usize,
    },
    Const(Value),
}

/// The frame source for a register-leaf run (Cut 35 slice 1): the caller's
/// argument region aliased directly, or a pushed frame built from the
/// copied arguments.
#[derive(Clone, Copy)]
enum LeafFrame<'a> {
    /// Overlay the frame on the caller's argument region at `stack[base..]`
    /// (every frame slot is a present parameter — no copy, no push).
    Alias(usize),
    /// Cut 35 slice 23: the frame IS the caller's frame at `base..` — the
    /// caller's `leaf_frame_base` stays active and `leaf_frame_offset`
    /// addresses its slots directly (a read-only-param register leaf: no
    /// copy, no push, nothing to unwind).
    CallerSlots { base: usize },
    /// Build the frame at the stack top from `args` (missing arguments stay
    /// `undefined`, spec 10.2.11).
    Pushed(&'a [Value]),
}

/// Load an operand into the accumulator (a no-op when it is already there).
fn load_operand(ops: &mut Vec<LeafOp>, operand: RegOperand) -> bool {
    match operand {
        RegOperand::Acc => true,
        RegOperand::Reg { slot, tdz } => {
            ops.push(LeafOp::LoadReg { slot, tdz });
            true
        }
        // A post-increment is only a member-store key (its write-back cannot
        // be a general load — `x = l++` stays on the step path).
        RegOperand::PostInc { .. } => false,
        RegOperand::Ctx { index } => {
            ops.push(LeafOp::LoadContext { index });
            true
        }
        RegOperand::PerIter { index } => {
            ops.push(LeafOp::LoadPerIter { index });
            true
        }
        RegOperand::Const(value) => {
            ops.push(LeafOp::LoadConst(value));
            true
        }
        // A spilled value sits on the value stack; only `BinAccPop` can
        // bring it back.
        RegOperand::Spilled => false,
        // The counter lives in the dedicated field; `LoadCounter` reads it.
        RegOperand::Counter => {
            ops.push(LeafOp::LoadCounter);
            true
        }
    }
}

/// Spill a live accumulator value (the top of the shadow stack) onto the
/// value stack so an op can overwrite the accumulator (Cut 35 slice 10).
fn spill_live_acc(ops: &mut Vec<LeafOp>, stack: &mut [RegOperand]) {
    if matches!(stack.last(), Some(RegOperand::Acc)) {
        ops.push(LeafOp::PushAcc);
        *stack.last_mut().unwrap() = RegOperand::Spilled;
    }
}

/// Whether a computed member key operand is re-readable and stable at the
/// fused op's execution point: a `tdz=false` frame slot (getters cannot
/// reach the body's own frame slots) or a constant (immutable). Anything
/// else — a live accumulator value, a spill, a counter, a post-increment —
/// stays on the step path.
fn is_stable_computed_key(operand: &RegOperand) -> bool {
    // A `Counter` (the loop counter field) is stable like a `Const`: the
    // acc-path head updates the field only between iterations, so its
    // value cannot change between the read-side key conversion and the
    // late store-time re-read of a fused computed op.
    matches!(
        operand,
        RegOperand::Reg { tdz: false, .. } | RegOperand::Const(_) | RegOperand::Counter
    )
}

/// Lower a leaf body's straight-line step stream to register ops (Cut 35
/// slice 1). `None` means a step has no register form, the shadow stack
/// holds a value the single-accumulator model cannot address (a right-leaning
/// `a + (b + c)` temp, a `Dup`/`Pop`, a dead `return` followed by code), or
/// the body falls off the end — such bodies keep the step path. The accepted
/// shapes are the left-leaning evaluation orders the hot leaf bodies produce:
/// `return x + 1`, `return x + y` with a captured or per-iteration operand,
/// statement stores feeding a final `return`, and the per-iteration/context
/// reads of the closure bench. The `tdz` bits are precomputed from the scope
/// layout so the executor skips the check for plain `var`/param slots.
/// Lower one step into a register-op stream. `index`/`total` locate the
/// step for the `Return`-is-last rule, `scope` resolves the TDZ flags.
/// Returns `None` (the step stays on the step path) when the step has no
/// register form. The state may be partially mutated on rejection — the
/// callers discard it (the whole body, or the uncommitted run tail).
#[allow(clippy::too_many_arguments)]
fn lower_step(
    step: &Step,
    index: usize,
    total: usize,
    next: Option<&Step>,
    scope: &ScopeInfo,
    ops: &mut Vec<LeafOp>,
    stack: &mut Vec<RegOperand>,
    counter_reads: &mut usize,
) -> Option<()> {
    match step {
        Step::Push(value) => stack.push(RegOperand::Const(*value)),
        Step::PushAcc => {
            // At most two accumulator-loop counter reads per body: the
            // computed-store shape `o[k] = <counter-derived value>` reads
            // the counter as the key AND in the value expression. The
            // counter lives in the dedicated field and nothing in the run
            // writes it, so each read resolves the same value (slice 21:
            // no entry push — the ops read the field directly).
            if *counter_reads >= 2 {
                return None;
            }
            *counter_reads += 1;
            stack.push(RegOperand::Counter);
        }
        Step::Dup => {
            // Duplicate the top shadow operand. A loadable operand with no
            // accumulator residency duplicates freely (a `Reg`/`Const`/
            // `Ctx`/`PerIter` source is re-readable at each consumption);
            // an `Acc` value exists once in the accumulator, a `PostInc`
            // would run its write-back twice, and a `Counter` would read
            // the loop counter twice (the single-read guard counts only
            // `PushAcc` steps) — all stay on the step path.
            let top = stack.last()?;
            match top {
                RegOperand::Reg { .. }
                | RegOperand::Const(_)
                | RegOperand::Ctx { .. }
                | RegOperand::PerIter { .. } => stack.push(top.clone()),
                _ => return None,
            }
        }
        Step::Dup2 => {
            // Duplicate the top two shadow operands (the computed
            // compound/update path's `[object, key]` reference pair: the
            // read consumes the dup copies, the originals stay below for
            // the write). Same re-readability rule as `Dup` — each
            // duplicated operand must be loadable again at each
            // consumption. A `Counter` key is re-readable (the dedicated
            // loop-counter field is run-invariant, so the read-side and
            // write-side resolutions see the same value); a `PostInc`
            // would run its write-back twice and stays on the step path.
            let b = stack.pop()?;
            let a = stack.pop()?;
            if !matches!(
                a,
                RegOperand::Reg { .. }
                    | RegOperand::Const(_)
                    | RegOperand::Ctx { .. }
                    | RegOperand::PerIter { .. }
                    | RegOperand::Counter
            ) || !matches!(
                b,
                RegOperand::Reg { .. }
                    | RegOperand::Const(_)
                    | RegOperand::Ctx { .. }
                    | RegOperand::PerIter { .. }
                    | RegOperand::Counter
            ) {
                return None;
            }
            stack.push(a.clone());
            stack.push(b.clone());
            stack.push(a);
            stack.push(b);
        }
        Step::LoadLocal { slot } => {
            let tdz = scope.tdz_store.get(*slot).copied().unwrap_or(false);
            stack.push(RegOperand::Reg { slot: *slot, tdz });
        }
        Step::LoadContextSlot { depth: 0, index } => {
            stack.push(RegOperand::Ctx { index: *index });
        }
        Step::LoadPerIteration { depth: 0, index } => {
            stack.push(RegOperand::PerIter { index: *index });
        }
        Step::Binary(op) => {
            let right = stack.pop()?;
            let left = stack.pop()?;
            if matches!(right, RegOperand::Counter) {
                // The acc-path loop counter as the RIGHT operand (the
                // `s += i` shape: `i` reads as `PushAcc`). The counter
                // lives in the dedicated field, so it loads into the
                // accumulator without touching the frame; the left
                // operand then combines exactly like the right-in-acc
                // shapes below (`BinAccPop` for a spilled left,
                // `BinLeftReg` for a late-readable frame-slot left). The
                // frame-slot read is safe late for a `tdz=false` slot:
                // nothing in the straight-line run writes it between the
                // counter load and the combine.
                ops.push(LeafOp::LoadCounter);
                match left {
                    RegOperand::Spilled => ops.push(LeafOp::BinAccPop { op: *op }),
                    RegOperand::Reg { slot, tdz: false } => {
                        ops.push(LeafOp::BinLeftReg { op: *op, slot })
                    }
                    _ => return None,
                }
                stack.push(RegOperand::Acc);
            } else if matches!(right, RegOperand::Acc) {
                // The right operand is the accumulator's live value. A
                // spilled left operand combines by popping it back
                // (`BinAccPop`); a frame-slot left operand reads the
                // slot at the combine (`BinLeftReg`) — safe only for
                // `tdz=false` slots, since the slot is read after the
                // accumulator value was computed (a member read's
                // getters cannot reach the body's own frame slots, and
                // the accepted shapes write no slot between the load
                // and the combine). Anything else (a second computed
                // value, a captured/constant left) cannot be held.
                match left {
                    RegOperand::Spilled => ops.push(LeafOp::BinAccPop { op: *op }),
                    RegOperand::Reg { slot, tdz: false } => {
                        ops.push(LeafOp::BinLeftReg { op: *op, slot })
                    }
                    _ => return None,
                }
                stack.push(RegOperand::Acc);
            } else {
                match (left, right) {
                    // Cut 35 slice 14: a captured left with a
                    // frame-slot right fuses into one op (the
                    // `(y) => x + y` leaf: `LoadContext` + `BinReg` —
                    // the env walk and the slot read have no side
                    // effects between them, so the order is unchanged).
                    (RegOperand::Ctx { index }, RegOperand::Reg { slot, tdz }) => {
                        ops.push(LeafOp::BinCtxReg {
                            op: *op,
                            index,
                            slot,
                            tdz,
                        });
                        stack.push(RegOperand::Acc);
                    }
                    (left, right) => {
                        if !load_operand(ops, left) {
                            return None;
                        }
                        match right {
                            RegOperand::Reg { slot, tdz } => {
                                ops.push(LeafOp::BinReg { op: *op, slot, tdz });
                            }
                            RegOperand::Ctx { index } => {
                                ops.push(LeafOp::BinContext { op: *op, index });
                            }
                            RegOperand::PerIter { index } => {
                                ops.push(LeafOp::BinPerIter { op: *op, index });
                            }
                            RegOperand::Const(value) => {
                                ops.push(LeafOp::BinConst { op: *op, value });
                            }
                            // A computed, spilled, or counter right
                            // operand cannot be held while the left
                            // operand loads into the accumulator.
                            RegOperand::Acc
                            | RegOperand::Spilled
                            | RegOperand::Counter
                            | RegOperand::PostInc { .. } => {
                                return None;
                            }
                        }
                        stack.push(RegOperand::Acc);
                    }
                }
            }
        }
        Step::BinaryImm { op, imm } => {
            let left = stack.pop()?;
            match left {
                RegOperand::Reg { slot, tdz } => {
                    // Cut 35 slice 14: a frame-slot left fuses into the
                    // immediate binary (the `return x + 1` leaf: one
                    // dispatch, skipping the load).
                    ops.push(LeafOp::BinImmLocal {
                        op: *op,
                        slot,
                        tdz,
                        imm: *imm,
                    });
                }
                left => {
                    if !load_operand(ops, left) {
                        return None;
                    }
                    ops.push(LeafOp::BinImm { op: *op, imm: *imm });
                }
            }
            stack.push(RegOperand::Acc);
        }
        Step::UpdateLocal { slot, op, prefix } => {
            // A statement-position local update (`l++;` / `++l;` / `l--;`):
            // the immediately-following `SetCompletion` discards the result,
            // so the run stores the update in place and pushes nothing
            // (`UpdateReg` — the shadow stays empty and the run commits at
            // that SetCompletion). An expression-position postfix update is
            // deferred as a `PostInc` operand (`a[l++] = v` keys, `x =
            // l++`): its write-back runs when the operand loads, preserving
            // evaluation order. An expression-position prefix update yields
            // the NEW value and has no register shape.
            if matches!(next, Some(Step::SetCompletion)) {
                let tdz = scope.tdz_store.get(*slot).copied().unwrap_or(false);
                ops.push(LeafOp::UpdateReg {
                    slot: *slot,
                    tdz,
                    op: *op,
                });
            } else if *prefix {
                return None;
            } else {
                let tdz = scope.tdz_store.get(*slot).copied().unwrap_or(false);
                stack.push(RegOperand::PostInc {
                    slot: *slot,
                    tdz,
                    op: *op,
                });
            }
        }
        Step::StoreLocal { slot } | Step::FusedStoreLocal { slot } => {
            let value = stack.pop()?;
            let tdz = scope.tdz_store.get(*slot).copied().unwrap_or(false);
            // Fuse a slot compound's tail: `s op= <rhs>` (or `s = s op
            // <rhs>`) whose RHS resolved into the accumulator lowers to
            // `BinLeftReg` + `StoreReg` back into the SAME slot. The store
            // directly consumes the binary's accumulator result (nothing
            // sits between them), so the pair collapses into one op — the
            // RMW loses a dispatch. Only the `tdz=false` shape fuses: a
            // `BinLeftReg` left is late-read (the lowering already rejected
            // a TDZ slot there), and a `tdz=true` store must keep its
            // uninitialized check. `fused_tail` is `Some(op)` when the
            // store's accumulator value is the direct result of a
            // `BinLeftReg` on the SAME slot — the extract-and-compare ends
            // the `ops.last()` borrow before the in-place rewrite.
            let fused_tail = if !tdz && matches!(value, RegOperand::Acc) {
                match ops.last() {
                    Some(LeafOp::BinLeftReg {
                        op,
                        slot: left_slot,
                    }) if *left_slot == *slot => Some(*op),
                    _ => None,
                }
            } else {
                None
            };
            if let Some(op) = fused_tail {
                ops.pop();
                ops.push(LeafOp::BinStoreReg { op, slot: *slot });
                return Some(());
            }
            if !load_operand(ops, value) {
                return None;
            }
            ops.push(LeafOp::StoreReg { slot: *slot, tdz });
        }
        Step::InitLocal { slot } => {
            let value = stack.pop()?;
            if !load_operand(ops, value) {
                return None;
            }
            ops.push(LeafOp::StoreReg {
                slot: *slot,
                tdz: false,
            });
        }
        Step::AssignMemberName { name, op } => {
            let value = stack.pop()?;
            match op {
                AssignOp::Assign => {
                    let object = stack.pop()?;
                    // `this.x = x` / `o.x = v` (plain `=`): the value is a
                    // direct operand, or a computed value live in the
                    // accumulator when the object is a frame slot (the
                    // store keeps the value in the accumulator and reads
                    // the object from the slot).
                    if matches!(value, RegOperand::Spilled | RegOperand::PostInc { .. }) {
                        // A `PostInc` value would run the write-back after
                        // the nullish check, inverting the step path's
                        // order (`l++` evaluates before [[Set]] throws on a
                        // nullish receiver) — keep it on the step path.
                        return None;
                    }
                    if matches!(value, RegOperand::Acc) {
                        // A computed value: only a `tdz=false` frame-slot
                        // object works (the store reads the slot at store
                        // time, so the value is never clobbered).
                        let RegOperand::Reg { slot, tdz: false } = object else {
                            return None;
                        };
                        ops.push(LeafOp::StoreMemberNameLocal {
                            object_slot: slot,
                            name: *name,
                        });
                    } else {
                        // A direct operand value: load the object into the
                        // accumulator and store (the loop Counter resolves
                        // from the dedicated field at execution time, after
                        // the object load).
                        if !load_operand(ops, object) {
                            return None;
                        }
                        ops.push(LeafOp::StoreMemberName { name: *name, value });
                    }
                }
                op @ (AssignOp::AddAssign
                | AssignOp::SubAssign
                | AssignOp::MulAssign
                | AssignOp::DivAssign
                | AssignOp::RemAssign
                | AssignOp::ExpAssign
                | AssignOp::LeftShiftAssign
                | AssignOp::RightShiftAssign
                | AssignOp::UnsignedRightShiftAssign
                | AssignOp::BitAndAssign
                | AssignOp::BitOrAssign
                | AssignOp::BitXorAssign) => {
                    // A binary compound member assign (`o.x += v`, ...):
                    // decompose into the plain binary on the cached old
                    // value (live in the accumulator) plus a plain store of
                    // the result. Sound because `o.x op= v` ≡ `o.x = o.x
                    // <bop> v` (`apply_compound` is `apply_binary` of the
                    // compound's binary op) — the store is a plain assign
                    // of the computed value, so a setter/chain receiver
                    // runs exactly once on the write. The RHS must be a
                    // pure operand (no side effects between the old read
                    // and the store), and the object a `tdz=false` frame
                    // slot (late-read contract).
                    let old = stack.pop()?;
                    let object = stack.pop()?;
                    if !matches!(old, RegOperand::Acc) {
                        return None;
                    }
                    let RegOperand::Reg {
                        slot: object_slot,
                        tdz: false,
                    } = object
                    else {
                        return None;
                    };
                    let bop = crate::expr::compound_binary(*op);
                    match value {
                        RegOperand::Reg { slot, tdz: false } => ops.push(LeafOp::BinReg {
                            op: bop,
                            slot,
                            tdz: false,
                        }),
                        RegOperand::Const(v) => ops.push(LeafOp::BinConst { op: bop, value: v }),
                        RegOperand::Ctx { index } => {
                            ops.push(LeafOp::BinContext { op: bop, index })
                        }
                        RegOperand::PerIter { index } => {
                            ops.push(LeafOp::BinPerIter { op: bop, index })
                        }
                        // The loop counter as the RHS (`o.x += i`): spill the
                        // cached old value (in the accumulator), load the
                        // counter, and combine by popping the spill back.
                        RegOperand::Counter => {
                            ops.push(LeafOp::PushAcc);
                            ops.push(LeafOp::LoadCounter);
                            ops.push(LeafOp::BinAccPop { op: bop });
                        }
                        _ => return None,
                    }
                    ops.push(LeafOp::StoreMemberNameLocal {
                        object_slot,
                        name: *name,
                    });
                }
                // The logical assigns (`&&=`, `||=`, `??=`) short-circuit on
                // the old value and may skip the write — no register form.
                _ => return None,
            }
        }
        Step::UpdateMemberName {
            name,
            op,
            prefix: _,
        } => {
            // A statement-position member update (`o.x++` / `o.x--`): the
            // cached old value (read by the preceding `GetMemberName`, live
            // in the accumulator) updates in place and stores back onto the
            // frame-slot object. The result (old for postfix, new for
            // prefix) is discarded at the statement boundary, so the form is
            // identical for both; an expression-position update leaves its
            // result unconsumed and the run machinery keeps it on the step
            // path.
            let old = stack.pop()?;
            let object = stack.pop()?;
            if !matches!(old, RegOperand::Acc) {
                return None;
            }
            let RegOperand::Reg {
                slot: object_slot,
                tdz: false,
            } = object
            else {
                return None;
            };
            ops.push(LeafOp::UpdateAcc { op: *op });
            ops.push(LeafOp::StoreMemberNameLocal {
                object_slot,
                name: *name,
            });
        }
        Step::AssignMemberComputed {
            op: AssignOp::Assign,
        } => {
            // `o[k] = v` (plain `=` only): the object is the accumulator,
            // the key and value direct operands. A computed value (`Acc`)
            // with a frame-slot object and key (the `o[k] = o[k] + 1`
            // shape — the value computed after the key) stores via
            // `StoreMemberComputedLocal`, which reads the object and key
            // from their slots at store time so the accumulator value is
            // never clobbered; any other computed key/value (`Acc`) cannot
            // be held while the object load overwrites the accumulator and
            // keeps the body on the step path.
            let value = stack.pop()?;
            let key = stack.pop()?;
            let object = stack.pop()?;
            if matches!(value, RegOperand::Acc) {
                // A computed value: the store keeps the value in the
                // accumulator and re-reads the object (a `tdz=false` frame
                // slot) and the key (a `Reg`/`Const` operand) at store time.
                if !is_stable_computed_key(&key) {
                    return None;
                }
                let RegOperand::Reg {
                    slot: object_slot,
                    tdz: false,
                } = object
                else {
                    return None;
                };
                ops.push(LeafOp::StoreMemberComputedLocal { object_slot, key });
                return Some(());
            }
            // A computed key (`Acc`) or a spilled value cannot be held
            // while the object load overwrites the accumulator. A `Counter`
            // (the single per-run loop-counter read, resolved from the
            // dedicated field) and a `PostInc` key (the write-back happens
            // at load time, before the store's nullish check — matching JS
            // evaluation order) are direct operands.
            if matches!(key, RegOperand::Acc | RegOperand::Spilled)
                || matches!(value, RegOperand::Acc | RegOperand::Spilled)
            {
                return None;
            }
            if !load_operand(ops, object) {
                return None;
            }
            ops.push(LeafOp::StoreMemberComputed { key, value });
        }
        Step::AssignMemberComputed {
            op:
                op @ (AssignOp::AddAssign
                | AssignOp::SubAssign
                | AssignOp::MulAssign
                | AssignOp::DivAssign
                | AssignOp::RemAssign
                | AssignOp::ExpAssign
                | AssignOp::LeftShiftAssign
                | AssignOp::RightShiftAssign
                | AssignOp::UnsignedRightShiftAssign
                | AssignOp::BitAndAssign
                | AssignOp::BitOrAssign
                | AssignOp::BitXorAssign),
        } => {
            // A binary compound computed member assign (`o[k] += v`, ...):
            // one fused op (`CompoundMemberComputedLocal`) that converts the
            // key ONCE (the preceding `GetMemberComputedKeep` deferred its
            // read into this op — sound because the RHS is a pure operand
            // whose load emits no op and is stable across the read, so
            // nothing observable runs between the keep and this op), reads
            // the old value, applies the compound, and stores through the
            // same key. The object must be a `tdz=false` frame slot and the
            // key a `Reg`/`Const` operand; the RHS a pure operand
            // (`Reg`/`Const`/`Counter` — a computed `Acc`/spilled value means
            // side-effectful RHS work ran between the keep and here, whose
            // order this op cannot preserve). The logical assigns
            // (`&&=`/`||=`/`??=`) stay on the step path (they short-circuit).
            let value = stack.pop()?;
            let key = stack.pop()?;
            let object = stack.pop()?;
            if !matches!(
                value,
                RegOperand::Reg { tdz: false, .. } | RegOperand::Const(_) | RegOperand::Counter
            ) {
                return None;
            }
            if !is_stable_computed_key(&key) {
                return None;
            }
            let RegOperand::Reg {
                slot: object_slot,
                tdz: false,
            } = object
            else {
                return None;
            };
            ops.push(LeafOp::CompoundMemberComputedLocal {
                object_slot,
                key,
                op: *op,
                rhs: value,
            });
        }
        Step::UpdateMemberComputed { op, prefix: _ } => {
            // A statement-position computed member update (`o[k]++` /
            // `o[k]--`): one fused op (`UpdateMemberComputedLocal`) with the
            // once-converted-key read, update, and store. The result (old
            // for postfix, new for prefix) is discarded at the statement
            // boundary, so the form is identical for both; an
            // expression-position update leaves its result unconsumed and
            // the run machinery keeps it on the step path.
            let key = stack.pop()?;
            let object = stack.pop()?;
            if !is_stable_computed_key(&key) {
                return None;
            }
            let RegOperand::Reg {
                slot: object_slot,
                tdz: false,
            } = object
            else {
                return None;
            };
            ops.push(LeafOp::UpdateMemberComputedLocal {
                object_slot,
                key,
                op: *op,
            });
        }
        Step::GetMemberComputedKeep => {
            // The computed compound/update path's read is deferred into the
            // fused `CompoundMemberComputedLocal`/`UpdateMemberComputedLocal`
            // op emitted at the following assign/update step (which converts
            // the key once and shares it between its internal read and
            // write). Here the duplicated `(object, key)` reference pair's
            // copies are consumed — the originals stay on the shadow for the
            // fused op. The op emits nothing: nothing observable runs between
            // this step and the assign (the RHS must be a pure operand for
            // the run to lower, which the assign's arm enforces), so the
            // deferred read is unobservable. A group that cannot lower (a
            // side-effectful RHS, an object that is not a frame slot, a
            // non-Reg/Const key) discards the whole run at the assign and
            // keeps the step path.
            let key = stack.pop()?;
            let object = stack.pop()?;
            if !is_stable_computed_key(&key) {
                return None;
            }
            if !matches!(object, RegOperand::Reg { tdz: false, .. }) {
                return None;
            }
        }
        Step::GetMemberName { name } => {
            // `o.x` (in value position): a frame-slot object fuses the
            // load into the read (`GetMemberNameLocal`, one dispatch);
            // any other object loads into the accumulator first. A live
            // accumulator below the object (the `o.a + o.b` shape) is
            // spilled so the read can overwrite it.
            let object = stack.pop()?;
            match object {
                RegOperand::Reg { slot, tdz } => {
                    spill_live_acc(ops, stack);
                    ops.push(LeafOp::GetMemberNameLocal {
                        object_slot: slot,
                        tdz,
                        name: *name,
                    });
                }
                object => {
                    if !matches!(object, RegOperand::Acc) {
                        spill_live_acc(ops, stack);
                    }
                    if !load_operand(ops, object) {
                        return None;
                    }
                    ops.push(LeafOp::GetMemberName { name: *name });
                }
            }
            stack.push(RegOperand::Acc);
        }
        Step::GetMemberComputed => {
            // `o[k]`: a frame-slot object fuses the load into the read
            // (`GetMemberComputedLocal`, one dispatch). Any other object
            // loads into the accumulator first, so a computed key cannot
            // be held then; a spilled key cannot be re-read; and a live
            // accumulator below the object is spilled before the load.
            // (An `Acc` key is rejected even in the fused form: with a
            // live accumulator below it, the spill would push the key,
            // not the live value.)
            let key = stack.pop()?;
            let object = stack.pop()?;
            if matches!(key, RegOperand::Acc | RegOperand::Spilled) {
                return None;
            }
            match object {
                RegOperand::Reg { slot, tdz } => {
                    spill_live_acc(ops, stack);
                    ops.push(LeafOp::GetMemberComputedLocal {
                        object_slot: slot,
                        tdz,
                        key,
                    });
                }
                object => {
                    if !matches!(object, RegOperand::Acc) {
                        spill_live_acc(ops, stack);
                    }
                    if !load_operand(ops, object) {
                        return None;
                    }
                    ops.push(LeafOp::GetMemberComputed { key });
                }
            }
            stack.push(RegOperand::Acc);
        }
        // A statement's completion is only read at the body's end, where
        // the register path's `Empty` maps identically to the step path's
        // `Normal` for leaf calls and constructs — nothing to emit. The
        // statement-list and reset/normalize wrappers (a block body, a
        // loop body) carry no values, so they are skipped too.
        Step::SetCompletion
        | Step::ListBegin
        | Step::ListEnd
        | Step::ResetCompletion
        | Step::NormalizeCompletion => {}
        Step::Return => {
            // A leaf body's `return` is its last statement; dead code
            // after it (hoisted-var initializers) keeps the step path.
            if index + 1 != total {
                return None;
            }
            let value = stack.pop()?;
            if !load_operand(ops, value) {
                return None;
            }
            ops.push(LeafOp::ReturnAcc);
            if !stack.is_empty() {
                return None;
            }
        }
        _ => return None,
    }
    Some(())
}

/// Segment a step slice into maximal straight-line register runs. Each run
/// starts at an empty shadow stack and closes at the last statement
/// boundary (a `SetCompletion`, a self-balancing fused statement-terminal
/// store, or the slice end) where the shadow is empty and a meaningful op
/// was emitted — a non-lowerable step (a jump, an env step, a prefix
/// update, a statement-position update whose write-back is never consumed)
/// closes the run at the previous boundary and stays on the step path. The
/// list wrappers (`ListBegin`/`ListEnd`) are never absorbed INTO a run's
/// ops (they push/pop the completion state on the step path), but a run
/// bracketed directly by a matching pair — a block whose every statement
/// lowered — absorbs the pair into its span (see the post-pass below), so
/// a braced loop body's per-iteration list push/pop disappears. Returns
/// the `(start, end, ops)` runs (offsets into `steps`, in order) to
/// replace with `Step::RunRegBody`; the remaining steps run on the step
/// path.
fn lower_leaf_ops_segmented(
    steps: &[Step],
    scope: &ScopeInfo,
) -> Vec<(usize, usize, Box<[LeafOp]>)> {
    let mut runs = Vec::new();
    let mut i = 0;
    while i < steps.len() {
        // A leading list wrapper or `SetCompletion` stays on the step path
        // (see the inner loop) — a run never spans a list wrapper, and a run
        // must not absorb a `SetCompletion` whose statement's steps are NOT
        // in the run (the statement's value would stay on the stack — a
        // per-iteration drift in the compiled path, which pre-allocates its
        // working area from `max_stack_usage`).
        if matches!(
            steps[i],
            Step::ListBegin | Step::ListEnd | Step::SetCompletion
        ) {
            i += 1;
            continue;
        }
        let mut ops = Vec::new();
        let mut stack: Vec<RegOperand> = Vec::new();
        // Cut 35 slice 16/21: at most two counter reads per run (the counter
        // lives in the dedicated field; the guard keeps the shadow stack at
        // most two `Counter` entries — the computed-store key + value shape).
        let mut counter_reads = 0;
        let run_start = i;
        // The last (exclusive end, ops length) where the run is committed:
        // the shadow is empty, a meaningful op exists, and the boundary is a
        // statement end.
        let mut commit: Option<(usize, usize)> = None;
        while i < steps.len() {
            // `ListBegin` pushes the completion state and `ListEnd` pops it
            // on the step path — a run must end before one so the pair
            // stays balanced (the register path discards the completion it
            // would restore, so a step-path `ListEnd` must still pop what
            // its step-path `ListBegin` pushed).
            if matches!(steps[i], Step::ListBegin | Step::ListEnd) {
                break;
            }
            if lower_step(
                &steps[i],
                i,
                steps.len(),
                steps.get(i + 1),
                scope,
                &mut ops,
                &mut stack,
                &mut counter_reads,
            )
            .is_none()
            {
                break;
            }
            if stack.is_empty() && !ops.is_empty() {
                // A run may close at the slice end, at a `SetCompletion`
                // (absorbed into the run span — its statement's value was
                // consumed by the register ops), or at a self-balancing
                // fused statement-terminal store: `FusedStoreLocal`/
                // `StoreLocal`/`InitLocal` pop their own value on the step
                // path and leave nothing for a later step to pop, so a
                // braced body whose last statement is such a store (the
                // store followed only by the block's `ListEnd`) can still
                // close a run. A MEMBER store is not such a boundary — its
                // statement's step-path form leaves the assigned value on
                // the stack for the trailing `SetCompletion` to pop, so a
                // run ending at the member store would strand that pop
                // (the `a[l++] = i` buildString corruption). The run must
                // absorb the member store's `SetCompletion` with it.
                let statement_store = matches!(
                    steps[i],
                    Step::FusedStoreLocal { .. } | Step::StoreLocal { .. } | Step::InitLocal { .. }
                );
                if i == steps.len() - 1
                    || matches!(steps[i], Step::SetCompletion)
                    || statement_store
                {
                    commit = Some((i + 1, ops.len()));
                }
            }
            i += 1;
        }
        if let Some((end, ops_len)) = commit {
            runs.push((run_start, end, ops[..ops_len].to_vec().into_boxed_slice()));
            i = end;
        } else {
            i = run_start + 1;
        }
    }
    // A run bracketed directly by a `ListBegin`/`ListEnd` pair (a braced
    // block whose EVERY statement lowered into the run — nothing step-path
    // sits between the wrappers) absorbs the pair: over an all-register
    // block the wrappers are a no-op on the step path. `ListBegin` saves
    // the completion state and `ListEnd` restores it only when the body
    // left it empty, and the register ops never write the completion — so
    // dropping the pair (and its per-iteration list push/pop) is
    // unobservable. The run contains no abrupt control (breaks/jumps never
    // lower), so the pop can never be skipped. Nested all-register blocks
    // absorb outward one pair at a time.
    for run in runs.iter_mut() {
        while run.0 > 0
            && run.1 < steps.len()
            && matches!(steps[run.0 - 1], Step::ListBegin)
            && matches!(steps[run.1], Step::ListEnd)
        {
            run.0 -= 1;
            run.1 += 1;
        }
    }
    runs
}

fn lower_leaf_ops(steps: &[Step], scope: &ScopeInfo) -> Option<Box<[LeafOp]>> {
    let mut ops = Vec::new();
    let mut stack: Vec<RegOperand> = Vec::new();
    // Cut 35 slice 16/21: at most two accumulator-loop counter reads per
    // body (the counter lives in the dedicated field; the guard keeps at
    // most two `Counter` entries on the shadow stack).
    let mut counter_reads = 0;
    for (index, step) in steps.iter().enumerate() {
        lower_step(
            step,
            index,
            steps.len(),
            steps.get(index + 1),
            scope,
            &mut ops,
            &mut stack,
            &mut counter_reads,
        )?;
    }
    match ops.last() {
        // A `return` body completes `Return`; a fall-off body (statement
        // stores, an empty body) completes `Empty` — the leaf callers map
        // both identically, so only the stack must be clean.
        Some(LeafOp::ReturnAcc)
        | Some(LeafOp::StoreReg { .. })
        | Some(LeafOp::BinStoreReg { .. })
        | Some(LeafOp::StoreMemberName { .. })
        | Some(LeafOp::StoreMemberComputed { .. })
        | Some(LeafOp::StoreMemberComputedLocal { .. })
        | Some(LeafOp::CompoundMemberComputedLocal { .. })
        | Some(LeafOp::UpdateMemberComputedLocal { .. })
        | None => {}
        _ => return None,
    }
    if !stack.is_empty() {
        return None;
    }
    Some(ops.into_boxed_slice())
}

/// Compile a function body and collect its `this.*` property writes.
/// Returns `(compiled_body, (count, array))` where the tuple holds the
/// count of property names and up to 4 AtomIds (empty if the body
/// doesn't use lexical `this` or is not a constructor).
pub fn compile_body(
    function: &EcmaFunction,
) -> Result<(CompiledBody, (usize, [crux::AtomId; 4])), JsError> {
    let _guard = CompilingGuard::new();
    let scope = analyze_scope(function);
    let mut compiler = Compiler {
        is_async_generator: function.is_generator && function.is_async,
        scope,
        strict: function.strict,
        outer_chain: function.outer_chain.clone(),
        per_iteration_chain: function.per_iteration_chain.clone(),
        function_name: function
            .name
            .as_ref()
            .map(|name| crux::intern(name.as_slice())),
        named_expression: function.named_expression,
        ..Compiler::default()
    };
    // Cut 3 continuation: the body's `arguments` slot is filled at entry —
    // the object needs the realm's intrinsics and the call's arguments, so
    // it cannot be compiled inline.
    if let Some(scope) = &compiler.scope
        && let Some(slot) = scope.arguments_slot
    {
        compiler.emit(Step::CreateArguments {
            slot,
            mapped: scope.arguments_formals.clone(),
        });
    }
    // Tasklist 2.3: a body whose arrows capture `this` stores its this
    // value into the capture-context slot at entry (the this slot was filled
    // by the certified call before the steps ran; the value is fixed for the
    // run). The arrows read it through the context chain.
    if let Some(scope) = &compiler.scope
        && let (Some(this_slot), Some(context_index)) = (scope.this_slot, scope.captured_this)
    {
        compiler.emit(Step::LoadLocal { slot: this_slot });
        compiler.emit(Step::StoreContextSlot {
            depth: 0,
            index: context_index,
        });
    }
    // A certified body's top-level function declarations are hoisted: each
    // binding is initialized with its closure at entry (spec 10.2.11), and
    // the declaration statement itself evaluates to nothing (15.2.6).
    if compiler.scope.is_some() {
        for stmt in &function.body.stmts {
            if let StmtKind::FunctionDecl(function) = &stmt.kind
                && function.name.is_some()
            {
                let name = function.name.unwrap();
                let (frame_slot, context_slot) = match compiler.binding(name) {
                    BindingLoc::Slot(slot) => (Some(slot), None),
                    BindingLoc::Context(0, index) => (None, Some(index)),
                    _ => continue,
                };
                let outer_chain = compiler.closure_outer_chain();
                compiler.emit(Step::FunctionDeclInit {
                    name,
                    function: Box::new(function.clone()),
                    frame_slot,
                    context_slot,
                    outer_chain,
                    // The hoisted declaration instantiates at body entry,
                    // before this body's own loops start, so it inherits
                    // only the enclosing chain.
                    per_iteration_chain: compiler.per_iteration_chain.clone(),
                });
            }
        }
    }
    compiler.compile_statements(&function.body.stmts)?;
    compiler.resolve();
    // A per-iteration loop switches the lexical environment each iteration,
    // so the per-step context sync must run (closures created in the loop
    // body capture the per-iteration env, not the capture context).
    let env_constant = compiler.scope.is_some() && !compiler.env_changing;
    // Cut 58: a resumable body is never a leaf — an async function with no
    // `await` (or a generator with no `yield`) still routes through its
    // driver, which wraps/defers the result; the leaf path would run it
    // synchronously and return the raw value.
    let leaf = compiler.scope.is_some()
        && !function.is_async
        && !function.is_generator
        && steps_are_leaf(&compiler.steps);
    let leaf_needs_env = compiler.steps.iter().any(|step| {
        matches!(
            step,
            Step::LoadPerIteration { .. }
                | Step::StorePerIteration { .. }
                | Step::UpdatePerIteration { .. }
        )
    });
    // A leaf reads an environment iff it has context-slot steps
    // (resolve `body_context`) or per-iteration steps (resolve
    // `lexical_env`); with neither, `run_leaf_body` skips the env work.
    let leaf_uses_env = leaf_needs_env
        || compiler.steps.iter().any(|step| {
            matches!(
                step,
                Step::LoadContextSlot { .. }
                    | Step::StoreContextSlot { .. }
                    | Step::UpdateContextSlot { .. }
            )
        });
    let leaf_ops = if leaf {
        lower_leaf_ops(
            &compiler.steps,
            compiler.scope.as_ref().expect("a leaf is certified"),
        )
    } else {
        None
    };
    let has_loop = body_has_loop(&compiler.steps);
    let has_call_apply = body_has_call_apply(&compiler.steps);
    Ok((
        CompiledBody {
            steps: compiler.steps,
            handlers: compiler.handlers,
            strict: function.strict,
            scope: compiler.scope,
            env_constant,
            leaf,
            leaf_needs_env,
            leaf_uses_env,
            leaf_ops,
            script_globals: None,
            jit_info: std::cell::Cell::new(0),
            jit_calls: std::cell::Cell::new(0),
            has_loop,
            has_call_apply,
        },
        compiler.this_writes,
    ))
}

/// Compile a statement list standalone (modules and top-level await).
/// `fast_script` certifies a top-level *script* for the script-level
/// binding fast path (declared `var`s read/written directly on the global
/// object); modules and eval bodies pass `false` — modules bind into the
/// module environment, and eval bodies can see (and shadow) the caller's
/// lexical environment, so neither may bypass the env walk.
pub fn compile_statements(
    stmts: &[Stmt],
    strict: bool,
    fast_script: bool,
) -> Result<CompiledBody, JsError> {
    let _guard = CompilingGuard::new();
    let (slots, script_globals, script_assigned) = if fast_script {
        match analyze_script_scope(stmts) {
            Some((slots, globals, assigned)) => (slots, Some(globals), Some(assigned)),
            None => (None, None, None),
        }
    } else {
        (None, None, None)
    };
    let mut compiler = Compiler {
        scope: slots.as_ref().map(|slots| slots.scope.clone()),
        script_globals,
        script_assigned,
        strict,
        ..Compiler::default()
    };
    // Cut 16: a slotified script's prologue loads each declared var's
    // current global value into its frame slot — a re-evaluation in the
    // same realm must see the previous evaluation's value (var
    // redeclaration keeps the property) — then the script's reads/writes
    // touch only the borrow-free frame.
    if let Some(slots) = &slots {
        for (slot, name) in slots.names.iter().enumerate() {
            compiler.emit(Step::LoadGlobal { name: *name });
            compiler.emit(Step::InitLocal { slot });
        }
    }
    compiler.compile_statements(stmts)?;
    // The epilogue writes every assigned slot back to the global object (a
    // normal completion only — an uncaught throw exits the realm, so the
    // stale frame is unobservable). A declared-but-never-assigned var (e.g.
    // a read-only global like `Infinity`) is left alone — its slot only
    // mirrors the global it was prologue-loaded from.
    if let Some(slots) = &slots {
        for (slot, name) in slots.names.iter().enumerate() {
            if !slots.assigned.contains(name) {
                continue;
            }
            compiler.emit(Step::LoadLocal { slot });
            compiler.emit(Step::StoreGlobal { name: *name });
        }
    }
    compiler.resolve();
    let has_loop = body_has_loop(&compiler.steps);
    let has_call_apply = body_has_call_apply(&compiler.steps);
    Ok(CompiledBody {
        steps: compiler.steps,
        handlers: compiler.handlers,
        strict,
        scope: compiler.scope,
        env_constant: !compiler.env_changing,
        // Scripts are never the callee of a call, so the leaf-inline fast
        // path never sees them.
        leaf: false,
        leaf_needs_env: false,
        leaf_uses_env: false,
        leaf_ops: None,
        script_globals: compiler.script_globals,
        jit_info: std::cell::Cell::new(0),
        jit_calls: std::cell::Cell::new(0),
        has_loop,
        has_call_apply,
    })
}

/// Render a compiled body for `--print-bytecode` (the Cut 5 debugging
/// tool): the binding layout header, then one line per step. Jump targets
/// are the already-resolved step indices (the fixups were applied at
/// compile end).
pub fn debug_print_body(body: &CompiledBody) {
    if let Some(scope) = &body.scope {
        println!(
            "frame: {} slots, arity {}, {} tdz marks",
            scope.frame_size,
            scope.arity,
            scope.tdz_store.len()
        );
        let mut slots: Vec<_> = scope.slots.iter().collect();
        slots.sort_by_key(|(_, slot)| **slot);
        for (name, slot) in slots {
            println!("  slot {slot}: {}", crux::lookup(*name).to_string_lossy());
        }
    }
    if let Some(globals) = &body.script_globals {
        let mut names: Vec<&String> = globals.iter().collect();
        names.sort();
        println!(
            "script globals: {}",
            names
                .iter()
                .map(|name| name.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    println!("env_constant: {}", body.env_constant);
    for (index, step) in body.steps.iter().enumerate() {
        // A `FunctionDeclInit` carries the whole declaration AST; print just
        // the binding so the step stream stays readable.
        if let Step::FunctionDeclInit {
            name,
            frame_slot,
            context_slot,
            ..
        } = step
        {
            println!(
                "{index:4}: FunctionDeclInit({} -> frame {frame_slot:?}, context {context_slot:?})",
                crux::lookup(*name).to_string_lossy()
            );
        } else {
            println!("{index:4}: {step:?}");
        }
    }
}

// ---- Cut 3 scope analysis ----
//
// Certify a function body for the frame-slot fast path and lay out its
// frame. The certified slice: simple identifier params, `var` plus
// `let`/`const` declarations (each lexical binding gets a unique frame
// slot that starts in the TDZ and is referenced only inside its declaring
// scope; `const` is never reassigned), side-effect-free array/object
// literals, no closures, no `eval`/`with`, no `new.target`/`super`, no
// `try`/`switch`/`for-in`/`for-of`/destructuring, no tagged templates. A
// non-arrow body's `this`/`arguments` reads get frame slots the certified
// call fills (this slot, unmapped/mapped arguments object). Anything else
// returns `None` and the body compiles through the existing environment
// machinery (the correctness backstop).

/// Lay out the frame for a fast-path body, or return `None` when the body
/// needs the environment path.
fn analyze_scope(function: &EcmaFunction) -> Option<ScopeInfo> {
    // An async GENERATOR's body mixes `yield` and `await` with the
    // async-generator delegation machinery (`AsyncYieldStar*`), which the
    // JIT does not lower yet — those bodies stay on the env path. Plain
    // generators (`yield`) and async functions (`await`) certify.
    if function.is_async && function.is_generator {
        return None;
    }
    // A non-arrow body's own `arguments` reads are arguments-object reads:
    // strict gets the unmapped object, sloppy the mapped one (aliasing the
    // simple params — a body whose `var`/param shapes differ stays on the
    // env path). An arrow's `arguments` is lexical. The strict binding is
    // const-like: an assignment to `arguments` bails the body (the slot
    // path has no const enforcement; the parser rejects it in strict
    // anyway).
    let allow_arguments = function.this_mode != crate::function::ThisMode::Lexical;
    let allow_this = function.this_mode != crate::function::ThisMode::Lexical;
    // Cut 61: super property access certifies in non-arrow method/accessor
    // bodies (the home object's prototype is the base; the certified this
    // slot is the receiver). Class CONSTRUCTORS stay on the env path — a
    // derived constructor's `super()` and the this-before-super() TDZ need
    // the Function env the certified layout never creates.
    let allow_super = allow_this && !function.is_class_constructor;
    let arguments_id = crux::intern_utf8("arguments");
    let mut scan = FastScopeScan {
        allow_arguments,
        allow_this,
        allow_super,
        ..FastScopeScan::default()
    };
    if allow_arguments && function.strict {
        scan.consts.insert(arguments_id);
    }
    // Params: every param keeps a dense frame slot (`setup_frame` copies
    // `args[0..arity]` by position); a captured param *additionally* gets a
    // context binding initialized with its argument (its frame slot is
    // dead — the body reads the context).
    for (position, param) in function.params.iter().enumerate() {
        if param.rest || param.init.is_some() {
            return None;
        }
        let BindingPattern::Ident(name) = param.pattern else {
            return None;
        };
        scan.slots.insert(name, scan.next_slot);
        scan.tdz.push(false);
        scan.next_slot += 1;
        scan.param_position.insert(name, position);
    }
    let arity = scan.next_slot;
    // Every name bound anywhere in the body, collected before the scan — a
    // closure can reference a binding declared later, so the capture check
    // cannot run against the incremental `slots` map.
    scan.bindings = collect_body_bindings(&function.params, &function.body);
    // The names the body's closures capture (Cut 3 continuation): a
    // pre-pass so the frame/context layout can be decided before any slot
    // assignment. A closure with a dynamic construct (this/arguments/eval/
    // with/...) bails the body now, before the layout is built.
    if !collect_captures(&function.body.stmts, &scan.bindings, &mut scan.captured) {
        return None;
    }
    // Tasklist 2.3: an arrow in the body references `this` (the walker
    // recorded the reserved marker as a capture). A NON-ARROW body can
    // supply its own `this` (it captures the value into a context slot
    // below); an ARROW body only when its own outer chain carries the
    // marker (an enclosing certified body captured it). Class constructors
    // stay on the env path for now (their `this` is construct machinery).
    let captures_this = scan.captured.contains(&captured_this_atom());
    let this_from_chain = function
        .outer_chain
        .iter()
        .flatten()
        .any(|name| *name == captured_this_atom());
    if captures_this && !this_from_chain && (!allow_this || function.is_class_constructor) {
        return None;
    }
    scan.this_from_chain = this_from_chain;
    // Captured params get their context bindings first (context slots
    // `0..k`), so the declaration-order walk below appends the captured
    // declared bindings after them.
    for (position, param) in function.params.iter().enumerate() {
        let BindingPattern::Ident(name) = param.pattern else {
            unreachable!("the param loop checked the pattern")
        };
        if scan.captured.contains(&name) {
            scan.context_slots.insert(name, scan.context_names.len());
            scan.context_names.push(name);
            scan.context_tdz.push(false);
            scan.context_const.push(false);
            scan.context_param.push(Some(position));
        }
    }
    // Cut 6 first slice (Annex B): the body's strictness, its top-level
    // lexical names, and the body-wide hoist decisions — the enclosing-
    // lexical conflict check must see the whole body, not the incremental
    // walk (a `let` after a block function suppresses its hoist too).
    scan.strict = function.strict;
    scan.top_lexicals = crate::script::top_level_lexically_declared_names(&function.body.stmts)
        .into_iter()
        .map(|name| crux::intern_utf8(&name.to_string_lossy()))
        .collect();
    if !function.strict {
        for (_, span, hoistable) in crate::script::annex_b_function_hoists(&function.body.stmts) {
            scan.hoist_spans.insert((span.start, span.end), hoistable);
        }
    }
    if !scan.stmts(&function.body.stmts, 0) {
        return None;
    }
    // A closure capturing a lexical binding declared inside a loop body
    // observes its per-iteration freshness (the body block re-creates each
    // iteration); the certified per-iteration machinery covers only the
    // loop-head names, so such a body stays on the env path.
    if scan
        .captured
        .iter()
        .any(|name| scan.loop_body_lexicals.contains(name))
    {
        return None;
    }
    // Cut 3 continuation (mapped arguments slice): a sloppy body observing
    // `arguments` needs the mapped object aliasing its simple params — every
    // param moves into the capture context (the mapped object's accessors
    // read/write the same bindings the body's `LoadContextSlot` steps use;
    // the dead frame slot keeps `setup_frame`'s dense param copy intact). A
    // body that declares a binding named `arguments` (var/let/const/
    // function/catch/param — the parser already forbids strict) bails: the
    // env path's declaration instantiation decides whether an arguments
    // object exists at all. Duplicate param names bail too — the capture
    // context cannot hold two bindings with one name.
    let arguments_formals = if scan.observes_arguments && !function.strict {
        if scan.bindings.contains(&arguments_id) {
            return None;
        }
        let mut seen: HashSet<crux::AtomId> = HashSet::new();
        let mut formals = Vec::new();
        for (position, param) in function.params.iter().enumerate() {
            let BindingPattern::Ident(name) = param.pattern else {
                unreachable!("the param loop checked the pattern")
            };
            if !seen.insert(name) {
                return None;
            }
            formals.push(name);
            if !scan.captured.contains(&name) {
                scan.captured.insert(name);
                scan.context_slots.insert(name, scan.context_names.len());
                scan.context_names.push(name);
                scan.context_tdz.push(false);
                scan.context_const.push(false);
                scan.context_param.push(Some(position));
            }
        }
        Some(formals)
    } else {
        None
    };
    // The body's `arguments` binding is a frame slot filled at entry by
    // `Step::CreateArguments` (strict unmapped or sloppy mapped — the object
    // needs the realm intrinsics and the call's arguments); it is never the
    // TDZ marker.
    let arguments_slot = if scan.observes_arguments {
        let slot = scan.next_slot;
        scan.slots.insert(arguments_id, slot);
        scan.tdz.push(false);
        scan.next_slot += 1;
        Some(slot)
    } else {
        None
    };
    // Tasklist 2.3: a non-arrow body whose arrows capture `this` puts the
    // value into a capture-context slot — the certified entry stores the
    // this slot into it (compile_body emits the store), and the arrows read
    // it through the context chain (their `outer_chain` carries the marker
    // via `own_context_entry`).
    let captured_this = if captures_this && allow_this && !function.is_class_constructor {
        let index = scan.context_names.len();
        scan.context_slots.insert(captured_this_atom(), index);
        scan.context_names.push(captured_this_atom());
        scan.context_tdz.push(false);
        scan.context_const.push(false);
        scan.context_param.push(None);
        Some(index)
    } else {
        None
    };
    // The body's `this` value is a frame slot the certified call fills with
    // the OrdinaryCallBindThis result; `this` is not a name, so it has no
    // `slots`-map entry. A `super` body (Cut 61) gets the slot too — the
    // super receiver is the this binding. An arrow-capturing body gets it so
    // the entry store can copy the value into the capture context.
    let this_slot = if scan.observes_this || scan.observes_super || captured_this.is_some() {
        let slot = scan.next_slot;
        scan.tdz.push(false);
        scan.next_slot += 1;
        Some(slot)
    } else {
        None
    };
    let frame_size = scan.next_slot;
    // Cut 35 slice 23: the params are exactly the frame and none is ever
    // assigned — the body has no `this`/`arguments`/`var` slots (each
    // would push `frame_size` past `arity`) and the assigned-name
    // collection (which walks nested closures too — a closure writing a
    // captured param writes the binding) hits no param. A register leaf
    // with this flag can read its args straight from the caller's frame
    // slots at a fused call site.
    let args_alias = frame_size == arity && {
        let mut assigned = HashSet::new();
        collect_assigned_stmts(&function.body.stmts, &mut assigned);
        !function.params.iter().any(|param| {
            let BindingPattern::Ident(name) = param.pattern else {
                unreachable!("the param loop checked the pattern")
            };
            assigned.contains(&name)
        })
    };
    Some(ScopeInfo {
        frame_size,
        arity,
        slots: scan.slots,
        tdz_store: scan.tdz,
        context_names: scan.context_names,
        context_tdz: scan.context_tdz,
        context_const: scan.context_const,
        context_param: scan.context_param,
        context_slots: scan.context_slots,
        arguments_slot,
        arguments_formals,
        this_slot,
        captured_this,
        args_alias,
        annex_b: scan.annex_b,
        statement_fns: scan.statement_fns,
    })
}

/// Every name bound anywhere in a body — params and every
/// `var`/`let`/`const`/`function`/`class`/catch/for-head/`using`
/// declaration at any depth (over-collecting names declared inside nested
/// functions only makes the closure-capture check more conservative).
fn collect_body_bindings(params: &[BindingElement], body: &Block) -> HashSet<crux::AtomId> {
    let mut bindings = HashSet::new();
    let mut names = Vec::new();
    for param in params {
        crate::script::bound_names(&param.pattern, &mut names);
    }
    for name in &names {
        bindings.insert(crux::intern_utf8(&name.to_string_lossy()));
    }
    collect_stmt_bindings(&body.stmts, &mut bindings);
    bindings
}

fn collect_stmt_bindings(stmts: &[Stmt], bindings: &mut HashSet<crux::AtomId>) {
    for stmt in stmts {
        match &stmt.kind {
            StmtKind::Block(block) => collect_stmt_bindings(&block.stmts, bindings),
            StmtKind::VarDecl { decls, .. } | StmtKind::UsingDecl { decls, .. } => {
                let mut names = Vec::new();
                for decl in decls {
                    crate::script::bound_names(&decl.pattern, &mut names);
                }
                for name in names {
                    bindings.insert(crux::intern_utf8(&name.to_string_lossy()));
                }
            }
            StmtKind::FunctionDecl(function) => {
                if let Some(name) = function.name {
                    bindings.insert(name);
                }
                collect_stmt_bindings(&function.body.stmts, bindings);
            }
            StmtKind::If {
                consequent,
                alternate,
                ..
            } => {
                collect_stmt_bindings(std::slice::from_ref(consequent), bindings);
                if let Some(alternate) = alternate {
                    collect_stmt_bindings(std::slice::from_ref(alternate), bindings);
                }
            }
            StmtKind::While { body, .. } | StmtKind::DoWhile { body, .. } => {
                collect_stmt_bindings(std::slice::from_ref(body), bindings);
            }
            StmtKind::For { init, body, .. } => {
                if let Some(ForInit::VarDecl { decls, .. }) = init {
                    let mut names = Vec::new();
                    for decl in decls {
                        crate::script::bound_names(&decl.pattern, &mut names);
                    }
                    for name in names {
                        bindings.insert(crux::intern_utf8(&name.to_string_lossy()));
                    }
                }
                collect_stmt_bindings(std::slice::from_ref(body), bindings);
            }
            StmtKind::ForIn { left, body, .. } | StmtKind::ForOf { left, body, .. } => {
                if let ForBinding::VarDecl { pattern, .. } = left {
                    let mut names = Vec::new();
                    crate::script::bound_names(pattern, &mut names);
                    for name in names {
                        bindings.insert(crux::intern_utf8(&name.to_string_lossy()));
                    }
                }
                collect_stmt_bindings(std::slice::from_ref(body), bindings);
            }
            StmtKind::Try {
                block,
                handler,
                finalizer,
            } => {
                collect_stmt_bindings(&block.stmts, bindings);
                if let Some(handler) = handler {
                    if let Some(param) = &handler.param {
                        let mut names = Vec::new();
                        crate::script::bound_names(param, &mut names);
                        for name in names {
                            bindings.insert(crux::intern_utf8(&name.to_string_lossy()));
                        }
                    }
                    collect_stmt_bindings(&handler.body.stmts, bindings);
                }
                if let Some(finalizer) = finalizer {
                    collect_stmt_bindings(&finalizer.stmts, bindings);
                }
            }
            StmtKind::Switch { cases, .. } => {
                for case in cases {
                    collect_stmt_bindings(&case.consequent, bindings);
                }
            }
            StmtKind::Labeled { body, .. } => {
                collect_stmt_bindings(std::slice::from_ref(body), bindings);
            }
            // Class/with are rejected by the certified-body scan; the rest
            // (expressions, return/throw) declare nothing.
            StmtKind::Empty
            | StmtKind::Debugger
            | StmtKind::Break(_)
            | StmtKind::Continue(_)
            | StmtKind::Expr(_)
            | StmtKind::Return(_)
            | StmtKind::Throw(_)
            | StmtKind::ClassDecl(_)
            | StmtKind::With { .. } => {}
        }
    }
}

// ---- Cut 3 continuation: closure capture ----

/// The names the body's closures capture (Cut 3 continuation): walk the
/// body for closure creation sites (function/arrow/method expressions and
/// function declarations) and collect the body bindings they reference —
/// the body's *own* references are not captures. Returns `false` when a
/// closure contains a construct that observes the body's bindings through
/// the environment or the body's absent `this`/`arguments`/`new.target`/
/// `super` (arrows inherit them lexically; a direct `eval`/`with` can see
/// the body's names) — such a body stays on the environment path. The
/// loop-head per-iteration capture rule is not applied here (the scan
/// checks it while walking with the open loops).
fn collect_captures(
    stmts: &[Stmt],
    bindings: &HashSet<crux::AtomId>,
    captured: &mut HashSet<crux::AtomId>,
) -> bool {
    stmts.iter().all(|stmt| match &stmt.kind {
        StmtKind::Block(block) => collect_captures(&block.stmts, bindings, captured),
        StmtKind::Expr(expr) => collect_expr_captures(expr, bindings, captured),
        StmtKind::VarDecl { decls, .. } | StmtKind::UsingDecl { decls, .. } => {
            decls.iter().all(|decl| {
                decl.init
                    .as_ref()
                    .is_none_or(|init| collect_expr_captures(init, bindings, captured))
            })
        }
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            collect_expr_captures(test, bindings, captured)
                && collect_captures(&[consequent.as_ref().clone()], bindings, captured)
                && alternate
                    .as_ref()
                    .is_none_or(|a| collect_captures(&[a.as_ref().clone()], bindings, captured))
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            collect_expr_captures(test, bindings, captured)
                && collect_captures(&[body.as_ref().clone()], bindings, captured)
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            let init_ok = match init {
                None => true,
                Some(ForInit::Expr(expr)) => collect_expr_captures(expr, bindings, captured),
                Some(ForInit::VarDecl { decls, .. }) => decls.iter().all(|decl| {
                    decl.init
                        .as_ref()
                        .is_none_or(|init| collect_expr_captures(init, bindings, captured))
                }),
            };
            init_ok
                && test
                    .as_ref()
                    .is_none_or(|t| collect_expr_captures(t, bindings, captured))
                && update
                    .as_ref()
                    .is_none_or(|u| collect_expr_captures(u, bindings, captured))
                && collect_captures(&[body.as_ref().clone()], bindings, captured)
        }
        StmtKind::Return(expr) => expr
            .as_ref()
            .is_none_or(|e| collect_expr_captures(e, bindings, captured)),
        StmtKind::Throw(expr) => collect_expr_captures(expr, bindings, captured),
        StmtKind::Labeled { body, .. } => {
            collect_captures(&[body.as_ref().clone()], bindings, captured)
        }
        StmtKind::FunctionDecl(function) => {
            closure_allows(&function.params, &function.body.stmts, bindings, captured)
        }
        StmtKind::ForIn {
            left, right, body, ..
        }
        | StmtKind::ForOf {
            left, right, body, ..
        } => {
            let left_ok = match left {
                ForBinding::Expr(expr) => collect_expr_captures(expr, bindings, captured),
                ForBinding::VarDecl { init, .. } => init
                    .as_ref()
                    .is_none_or(|init| collect_expr_captures(init, bindings, captured)),
            };
            left_ok
                && collect_expr_captures(right, bindings, captured)
                && collect_captures(&[body.as_ref().clone()], bindings, captured)
        }
        StmtKind::Try {
            block,
            handler,
            finalizer,
        } => {
            collect_captures(&block.stmts, bindings, captured)
                && handler
                    .as_ref()
                    .is_none_or(|handler| collect_captures(&handler.body.stmts, bindings, captured))
                && finalizer
                    .as_ref()
                    .is_none_or(|f| collect_captures(&f.stmts, bindings, captured))
        }
        StmtKind::Switch {
            discriminant,
            cases,
            ..
        } => {
            collect_expr_captures(discriminant, bindings, captured)
                && cases.iter().all(|case| {
                    case.test
                        .as_ref()
                        .is_none_or(|t| collect_expr_captures(t, bindings, captured))
                        && collect_captures(&case.consequent, bindings, captured)
                })
        }
        StmtKind::Empty
        | StmtKind::Debugger
        | StmtKind::Break(_)
        | StmtKind::Continue(_)
        | StmtKind::ClassDecl(_)
        | StmtKind::With { .. } => true,
    })
}

/// Walk an expression for closure creation sites (function/arrow
/// expressions, object methods/getters/setters), collecting the body
/// bindings they capture. A plain reference in the body's own code is not
/// a capture — the main scan enforces the body's own dynamic-construct
/// rules.
fn collect_expr_captures(
    expr: &Expr,
    bindings: &HashSet<crux::AtomId>,
    captured: &mut HashSet<crux::AtomId>,
) -> bool {
    match &expr.kind {
        ExprKind::Function(function) => {
            closure_allows(&function.params, &function.body.stmts, bindings, captured)
        }
        ExprKind::Arrow { params, body, .. } => {
            closure_arrow_allows(params, body, bindings, captured, false)
        }
        ExprKind::Object(object) => object.props.iter().all(|prop| match prop {
            ObjectProperty::Method { function, .. } => {
                closure_allows(&function.params, &function.body.stmts, bindings, captured)
            }
            ObjectProperty::Get { body, .. } => {
                closure_allows(&[], &body.stmts, bindings, captured)
            }
            ObjectProperty::Set { body, .. } => {
                closure_allows(&[], &body.stmts, bindings, captured)
            }
            ObjectProperty::Init { key, value, .. } => {
                let key_ok = match key {
                    PropertyName::Ident(_) | PropertyName::Str(_) | PropertyName::Number(_) => true,
                    PropertyName::Computed(key_expr) => {
                        collect_expr_captures(key_expr, bindings, captured)
                    }
                };
                key_ok && collect_expr_captures(value, bindings, captured)
            }
            ObjectProperty::Spread(e) => collect_expr_captures(e, bindings, captured),
        }),
        ExprKind::Array(array) => array.elements.iter().all(|element| match element {
            ArrayElement::Hole => true,
            ArrayElement::Expr(e) | ArrayElement::Spread(e) => {
                collect_expr_captures(e, bindings, captured)
            }
        }),
        ExprKind::Paren(inner) => collect_expr_captures(inner, bindings, captured),
        ExprKind::Unary { operand, .. } => collect_expr_captures(operand, bindings, captured),
        ExprKind::Update { target, .. } => collect_expr_captures(target, bindings, captured),
        ExprKind::Binary { left, right, .. } => {
            collect_expr_captures(left, bindings, captured)
                && collect_expr_captures(right, bindings, captured)
        }
        ExprKind::Logical { left, right, .. } => {
            collect_expr_captures(left, bindings, captured)
                && collect_expr_captures(right, bindings, captured)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            collect_expr_captures(test, bindings, captured)
                && collect_expr_captures(consequent, bindings, captured)
                && collect_expr_captures(alternate, bindings, captured)
        }
        ExprKind::Assign { target, value, .. } => {
            collect_expr_captures(target, bindings, captured)
                && collect_expr_captures(value, bindings, captured)
        }
        ExprKind::Member(member) => {
            collect_expr_captures(&member.object, bindings, captured)
                && match &member.property {
                    MemberProperty::Computed(key) => collect_expr_captures(key, bindings, captured),
                    _ => true,
                }
        }
        ExprKind::Call(call) => {
            collect_expr_captures(&call.callee, bindings, captured)
                && call.args.iter().all(|arg| match arg {
                    Argument::Expr(e) | Argument::Spread(e) => {
                        collect_expr_captures(e, bindings, captured)
                    }
                })
        }
        ExprKind::New(new) => {
            collect_expr_captures(&new.callee, bindings, captured)
                && new.args.iter().all(|arg| match arg {
                    Argument::Expr(e) | Argument::Spread(e) => {
                        collect_expr_captures(e, bindings, captured)
                    }
                })
        }
        ExprKind::Template(template) => template
            .exprs
            .iter()
            .all(|e| collect_expr_captures(e, bindings, captured)),
        ExprKind::Sequence(exprs) => exprs
            .iter()
            .all(|e| collect_expr_captures(e, bindings, captured)),
        // The body's own dynamic constructs (this/arguments/eval/with/...)
        // and its own plain references are the main scan's business, not a
        // capture. A suspension point's ARGUMENT is a closure-creation site
        // (a `yield function () { return i; }` — Cut 58): walk it.
        ExprKind::Yield { argument, .. } => argument
            .as_ref()
            .is_none_or(|arg| collect_expr_captures(arg, bindings, captured)),
        ExprKind::Await(argument) => collect_expr_captures(argument, bindings, captured),
        ExprKind::Ident(_)
        | ExprKind::Literal(_)
        | ExprKind::This
        | ExprKind::Super
        | ExprKind::Class(_)
        | ExprKind::PrivateIn { .. }
        | ExprKind::TaggedTemplate { .. }
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => true,
    }
}

/// The interned marker for a `this` captured by an arrow from an enclosing
/// certified body (tasklist 2.3): it names a synthetic capture-context
/// binding holding the enclosing non-arrow body's `this` value. The name
/// contains a control character, so no source identifier can equal it — it
/// never collides with a real binding (`collect_body_bindings` can never
/// produce it). Resolved once.
fn captured_this_atom() -> crux::AtomId {
    use std::sync::OnceLock;
    static ATOM: OnceLock<crux::AtomId> = OnceLock::new();
    *ATOM.get_or_init(|| crux::string::intern_utf8("\u{1}captured-this"))
}

/// The marker's canonical name (`JsString`), shared with the env layer: the
/// capture context binds it, and an env-path arrow resolving its lexical
/// `this` recognizes the binding (env.rs `DeclarativeEnv::has_captured_this`).
/// `crux::lookup` is the interned canonical handle, so handle equality with
/// the stored binding name is exact.
pub(crate) fn captured_this_name() -> JsString {
    crux::lookup(captured_this_atom())
}

/// Whether a closure can be created inside a certified body (Cut 3
/// continuation): every identifier it references that binds in the body is
/// added to `captured` (the body context-allocates it); a reference to a
/// currently-open loop-head lexical binding bails (per-iteration contexts
/// are deferred), as does any construct that observes the body's bindings
/// through the environment or the certified body's absent
/// `this`/`arguments`/`new.target`/`super` (arrows inherit them lexically;
/// a direct `eval` or `with` can see the body's names). Its own body
/// compiles separately, so everything else is that compilation's business.
/// A body whose closure fails the check stays on the environment path
/// (correct, just slower).
fn closure_allows(
    params: &[BindingElement],
    stmts: &[Stmt],
    bindings: &HashSet<crux::AtomId>,
    captured: &mut HashSet<crux::AtomId>,
) -> bool {
    // A non-arrow function (a declaration/expression/method/getter/setter)
    // has its OWN `this`/`arguments`/`new.target`, bound at its own call:
    // walking its body in the `own` mode lets those through (they are the
    // nested function's, not observations of the analyzed body) instead of
    // bailing the enclosing body's certification.
    params.iter().all(|param| {
        param
            .init
            .as_ref()
            .is_none_or(|init| closure_expr_allows(init, bindings, captured, true))
    }) && stmts
        .iter()
        .all(|stmt| closure_stmt_allows(stmt, bindings, captured, true))
}

fn closure_arrow_allows(
    params: &[BindingElement],
    body: &ArrowBody,
    bindings: &HashSet<crux::AtomId>,
    captured: &mut HashSet<crux::AtomId>,
    own: bool,
) -> bool {
    // An arrow inherits `this`/`arguments`/`new.target` lexically from the
    // innermost enclosing non-arrow: `own` stays false for an arrow created
    // directly in the analyzed body (its references observe the body's
    // bindings) and true for an arrow inside a nested non-arrow function.
    params.iter().all(|param| {
        param
            .init
            .as_ref()
            .is_none_or(|init| closure_expr_allows(init, bindings, captured, own))
    }) && match body {
        ArrowBody::Expr(expr) => closure_expr_allows(expr, bindings, captured, own),
        ArrowBody::Block(block) => block
            .stmts
            .iter()
            .all(|s| closure_stmt_allows(s, bindings, captured, own)),
    }
}

fn closure_stmt_allows(
    stmt: &Stmt,
    bindings: &HashSet<crux::AtomId>,
    captured: &mut HashSet<crux::AtomId>,
    own: bool,
) -> bool {
    match &stmt.kind {
        StmtKind::Block(block) => block
            .stmts
            .iter()
            .all(|s| closure_stmt_allows(s, bindings, captured, own)),
        StmtKind::Empty | StmtKind::Debugger | StmtKind::Break(_) | StmtKind::Continue(_) => true,
        StmtKind::Expr(expr) => closure_expr_allows(expr, bindings, captured, own),
        StmtKind::VarDecl { decls, .. } | StmtKind::UsingDecl { decls, .. } => {
            decls.iter().all(|decl| {
                // The declared names are bound here (shadowing); only the
                // initializers are references.
                decl.init
                    .as_ref()
                    .is_none_or(|init| closure_expr_allows(init, bindings, captured, own))
            })
        }
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            closure_expr_allows(test, bindings, captured, own)
                && closure_stmt_allows(consequent, bindings, captured, own)
                && alternate
                    .as_deref()
                    .is_none_or(|a| closure_stmt_allows(a, bindings, captured, own))
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            closure_expr_allows(test, bindings, captured, own)
                && closure_stmt_allows(body, bindings, captured, own)
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            let init_ok = match init {
                None => true,
                Some(ForInit::Expr(expr)) => closure_expr_allows(expr, bindings, captured, own),
                Some(ForInit::VarDecl { decls, .. }) => decls.iter().all(|decl| {
                    decl.init
                        .as_ref()
                        .is_none_or(|init| closure_expr_allows(init, bindings, captured, own))
                }),
            };
            init_ok
                && test
                    .as_ref()
                    .is_none_or(|t| closure_expr_allows(t, bindings, captured, own))
                && update
                    .as_ref()
                    .is_none_or(|u| closure_expr_allows(u, bindings, captured, own))
                && closure_stmt_allows(body, bindings, captured, own)
        }
        StmtKind::Return(expr) => expr
            .as_ref()
            .is_none_or(|e| closure_expr_allows(e, bindings, captured, own)),
        StmtKind::Throw(expr) => closure_expr_allows(expr, bindings, captured, own),
        StmtKind::Labeled { body, .. } => closure_stmt_allows(body, bindings, captured, own),
        StmtKind::FunctionDecl(function) => {
            closure_allows(&function.params, &function.body.stmts, bindings, captured)
        }
        StmtKind::ForIn {
            left, right, body, ..
        }
        | StmtKind::ForOf {
            left, right, body, ..
        } => {
            let left_ok = match left {
                ForBinding::Expr(expr) => closure_expr_allows(expr, bindings, captured, own),
                ForBinding::VarDecl { init, .. } => init
                    .as_ref()
                    .is_none_or(|init| closure_expr_allows(init, bindings, captured, own)),
            };
            left_ok
                && closure_expr_allows(right, bindings, captured, own)
                && closure_stmt_allows(body, bindings, captured, own)
        }
        StmtKind::Try {
            block,
            handler,
            finalizer,
        } => {
            block
                .stmts
                .iter()
                .all(|s| closure_stmt_allows(s, bindings, captured, own))
                && handler.as_ref().is_none_or(|handler| {
                    // The catch parameter is bound; its body walks.
                    handler
                        .body
                        .stmts
                        .iter()
                        .all(|s| closure_stmt_allows(s, bindings, captured, own))
                })
                && finalizer.as_ref().is_none_or(|f| {
                    f.stmts
                        .iter()
                        .all(|s| closure_stmt_allows(s, bindings, captured, own))
                })
        }
        StmtKind::Switch {
            discriminant,
            cases,
            ..
        } => {
            closure_expr_allows(discriminant, bindings, captured, own)
                && cases.iter().all(|case| {
                    case.test
                        .as_ref()
                        .is_none_or(|t| closure_expr_allows(t, bindings, captured, own))
                        && case
                            .consequent
                            .iter()
                            .all(|s| closure_stmt_allows(s, bindings, captured, own))
                })
        }
        StmtKind::ClassDecl(_) | StmtKind::With { .. } => false,
    }
}

fn closure_expr_allows(
    expr: &Expr,
    bindings: &HashSet<crux::AtomId>,
    captured: &mut HashSet<crux::AtomId>,
    own: bool,
) -> bool {
    match &expr.kind {
        // A read or write of a body binding is a capture: the body
        // context-allocates it. `arguments` is the special binding the fast
        // path never creates — for the ANALYZED body; inside a nested
        // non-arrow function (`own`) it is that function's own arguments
        // object. A lexical for-head binding is captured like any other —
        // the loop's per-iteration env gives the closure the
        // fresh-per-iteration value it needs.
        ExprKind::Ident(name) => {
            if !own && crux::lookup(*name) == JsString::from_utf8("arguments") {
                return false;
            }
            if bindings.contains(name) {
                captured.insert(*name);
            }
            true
        }
        ExprKind::Literal(_) => true,
        ExprKind::Array(array) => array.elements.iter().all(|element| match element {
            ArrayElement::Hole => true,
            ArrayElement::Expr(e) | ArrayElement::Spread(e) => {
                closure_expr_allows(e, bindings, captured, own)
            }
        }),
        ExprKind::Object(object) => object.props.iter().all(|prop| match prop {
            // A method/getter/setter is a nested closure: a body-binding
            // reference inside it is a capture too.
            ObjectProperty::Method { function, .. } => {
                closure_allows(&function.params, &function.body.stmts, bindings, captured)
            }
            ObjectProperty::Get { body, .. } => {
                closure_allows(&[], &body.stmts, bindings, captured)
            }
            ObjectProperty::Set { body, .. } => {
                // The setter's parameter is bound in the closure.
                closure_allows(&[], &body.stmts, bindings, captured)
            }
            ObjectProperty::Init { key, value, .. } => {
                let key_ok = match key {
                    // A property key is not a reference.
                    PropertyName::Ident(_) | PropertyName::Str(_) | PropertyName::Number(_) => true,
                    PropertyName::Computed(e) => closure_expr_allows(e, bindings, captured, own),
                };
                key_ok && closure_expr_allows(value, bindings, captured, own)
            }
            ObjectProperty::Spread(e) => closure_expr_allows(e, bindings, captured, own),
        }),
        ExprKind::Paren(inner) => closure_expr_allows(inner, bindings, captured, own),
        ExprKind::Unary { operand, .. } => closure_expr_allows(operand, bindings, captured, own),
        ExprKind::Update { target, .. } => closure_expr_allows(target, bindings, captured, own),
        ExprKind::Binary { left, right, .. } => {
            closure_expr_allows(left, bindings, captured, own)
                && closure_expr_allows(right, bindings, captured, own)
        }
        ExprKind::Logical { left, right, .. } => {
            closure_expr_allows(left, bindings, captured, own)
                && closure_expr_allows(right, bindings, captured, own)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            closure_expr_allows(test, bindings, captured, own)
                && closure_expr_allows(consequent, bindings, captured, own)
                && closure_expr_allows(alternate, bindings, captured, own)
        }
        ExprKind::Assign { target, value, .. } => {
            // An assignment target is a reference (writing a body binding is
            // a capture).
            closure_expr_allows(target, bindings, captured, own)
                && closure_expr_allows(value, bindings, captured, own)
        }
        ExprKind::Member(member) => {
            if matches!(member.property, MemberProperty::Private(_)) {
                return false;
            }
            let object_ok = closure_expr_allows(&member.object, bindings, captured, own);
            let key_ok = match &member.property {
                // A property name is not a reference.
                MemberProperty::Computed(key) => closure_expr_allows(key, bindings, captured, own),
                _ => true,
            };
            object_ok && key_ok
        }
        ExprKind::Call(call) => {
            if matches!(
                &call.callee.kind,
                ExprKind::Ident(id) if crux::lookup(*id) == JsString::from_utf8("eval")
            ) {
                return false;
            }
            closure_expr_allows(&call.callee, bindings, captured, own)
                && call.args.iter().all(|arg| match arg {
                    Argument::Expr(e) | Argument::Spread(e) => {
                        closure_expr_allows(e, bindings, captured, own)
                    }
                })
        }
        ExprKind::New(new) => {
            closure_expr_allows(&new.callee, bindings, captured, own)
                && new.args.iter().all(|arg| match arg {
                    Argument::Expr(e) | Argument::Spread(e) => {
                        closure_expr_allows(e, bindings, captured, own)
                    }
                })
        }
        ExprKind::Template(template) => template
            .exprs
            .iter()
            .all(|e| closure_expr_allows(e, bindings, captured, own)),
        ExprKind::Sequence(exprs) => exprs
            .iter()
            .all(|e| closure_expr_allows(e, bindings, captured, own)),
        ExprKind::Function(function) => {
            closure_allows(&function.params, &function.body.stmts, bindings, captured)
        }
        ExprKind::Arrow { params, body, .. } => {
            closure_arrow_allows(params, body, bindings, captured, own)
        }
        // `yield`/`await` suspend the closure itself, never the enclosing
        // body, so they are fine here — their operands still walk.
        ExprKind::Yield {
            argument: Some(argument),
            ..
        }
        | ExprKind::Await(argument) => closure_expr_allows(argument, bindings, captured, own),
        ExprKind::Yield { argument: None, .. } => true,
        // The analyzed body's `this` is never visible inside a closure
        // unless the closure is an arrow (then `own` is false). Under `own`
        // (a nested non-arrow function) `this` is that function's own.
        // Tasklist 2.3: an ARROW's lexical `this` no longer bails the body —
        // the walk records the reserved marker as a capture (the analyzed
        // body decides, in `analyze_scope`, whether it can supply `this`: a
        // non-arrow captures it into its context; an arrow reads it from its
        // own outer chain; either is absent -> env path).
        // `super`/class/private/tagged/import constructs stay rejected even
        // under `own` — they need machinery this walk does not model (a
        // class body could capture body bindings through methods the walk
        // never enters), so such closures still bail the body.
        ExprKind::This => {
            if own {
                true
            } else {
                captured.insert(captured_this_atom());
                true
            }
        }
        ExprKind::Super
        | ExprKind::Class(_)
        | ExprKind::PrivateIn { .. }
        | ExprKind::TaggedTemplate { .. }
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => false,
    }
}

/// The frame layout under construction: the flat name→slot map (safe
/// because a certified body declares every lexical binding exactly once and
/// references it only inside its declaring scope), the per-slot TDZ marks,
/// the `const` names (the frame has no const enforcement, so the scan
/// rejects any reassignment), and each lexical binding's block depth.
#[derive(Default)]
struct FastScopeScan {
    slots: HashMap<crux::AtomId, usize>,
    next_slot: usize,
    /// In lockstep with `slots`: `true` for a `let`/`const` slot, which the
    /// frame starts uninitialized (the TDZ marker `LoadLocal`/`StoreLocal`
    /// check).
    tdz: Vec<bool>,
    consts: HashSet<crux::AtomId>,
    /// The block depth each lexical binding was declared at: a reference
    /// must sit at an equal or deeper depth (inside its scope).
    declared_depth: HashMap<crux::AtomId, usize>,
    /// The block depths of the loop bodies currently being scanned: a
    /// lexical binding declared at or below one (a loop-body declaration)
    /// is fresh per iteration (spec 14.7.4.3 — the body block re-creates
    /// each iteration), which the certified per-iteration machinery covers
    /// only for the loop-head names.
    open_loop_body_depths: Vec<usize>,
    /// The lexical bindings declared inside an open loop body: a closure
    /// capturing one bails the body to the env path (the per-iteration
    /// freshness of a body-block scope is not flattenable into the capture
    /// context).
    loop_body_lexicals: HashSet<crux::AtomId>,
    /// Every name bound anywhere in the body (see `collect_body_bindings`):
    /// the closure-capture check tests references against this complete
    /// set, not the incremental `slots`.
    bindings: HashSet<crux::AtomId>,
    /// Param name → position (a captured param's context binding is
    /// initialized with the call argument).
    param_position: HashMap<crux::AtomId, usize>,
    /// The names a closure in the body captures (Cut 3 continuation): these
    /// get context bindings instead of frame slots. The frame/context
    /// layout for the captured declared bindings is decided in `decls`.
    captured: HashSet<crux::AtomId>,
    context_slots: HashMap<crux::AtomId, usize>,
    context_names: Vec<crux::AtomId>,
    context_tdz: Vec<bool>,
    context_const: Vec<bool>,
    context_param: Vec<Option<usize>>,
    /// Whether the body is a strict non-arrow function whose own `arguments`
    /// reads are the unmapped arguments object (Cut 3 continuation).
    allow_arguments: bool,
    /// The body references `arguments`: it gets an `arguments` slot the
    /// certified call fills with the unmapped arguments object.
    observes_arguments: bool,
    /// Whether the body is a non-arrow function whose own `this` reads are
    /// the call's `this` value (Cut 3 continuation; arrows' `this` is
    /// lexical).
    allow_this: bool,
    /// Tasklist 2.3: whether an ARROW body's lexical `this` is available
    /// from its outer chain — the enclosing certified body captured it (the
    /// [`captured_this_atom`] marker is in the function record's
    /// `outer_chain`). Direct `this` reads in such a body compile to a
    /// context-chain read instead of bailing to the env path.
    this_from_chain: bool,
    /// The body references `this`: it gets a `this` slot the certified call
    /// fills with the OrdinaryCallBindThis result.
    observes_this: bool,
    /// Whether the body is a non-arrow method/accessor whose `super` reads
    /// resolve through the home object (Cut 61): class and object-literal
    /// methods and accessors — class CONSTRUCTORS (and arrows, whose `super`
    /// is lexical) stay on the env path (a derived constructor's `super()`
    /// and the this-before-super() TDZ need the Function env).
    allow_super: bool,
    /// The body references `super` (property access or `super.m()` calls):
    /// it gets a `this` slot too — the super receiver is the this binding.
    observes_super: bool,
    /// Whether the body is strict (Cut 6 first slice): a strict body's
    /// block function declarations are block-scoped only — no Annex B var
    /// hoist.
    strict: bool,
    /// The body's top-level lexical declaration names (let/const/class/
    /// using): an Annex B block function whose name collides stays
    /// block-scoped (B.3.3.4 step 2).
    top_lexicals: HashSet<crux::AtomId>,
    /// The body-wide Annex B hoist decision per declaration span
    /// (script::annex_b_function_hoists): `false` when the name collides
    /// with a lexical in any enclosing statement list (order-independent).
    hoist_spans: HashMap<(u32, u32), bool>,
    /// The live Annex B block functions allocated so far, in declaration
    /// order (Carried to the ScopeInfo for the compiler).
    annex_b: Vec<AnnexBFunction>,
    /// The hoisted Annex B statement-position function declarations (Cut 6
    /// continuation): (span → entry) for the statement's compile.
    statement_fns: Vec<AnnexBStatementFn>,
    /// The names bound in each open block statement (Cut 6 first slice):
    /// the already-bound check is per block — a `let` or function
    /// declaration in a sibling block does not suppress this block's
    /// declaration (B.3.2.1 step 3 checks the block env's own bindings).
    block_names_stack: Vec<HashSet<crux::AtomId>>,
    /// The for-head lexical names, keyed by the for statement's depth: a
    /// reference outside the open loop (after the statement, or in a
    /// sibling scope) would leak the flat slot, so the scan rejects it.
    for_head_lexicals: HashMap<crux::AtomId, usize>,
    /// The for-head lexicals of the loops currently being scanned (the
    /// head exprs and body are inside the loop's scope; the same depth
    /// after the loop is not).
    open_for_heads: Vec<HashSet<crux::AtomId>>,
}

impl FastScopeScan {
    fn stmts(&mut self, stmts: &[Stmt], depth: usize) -> bool {
        stmts.iter().all(|stmt| self.stmt(stmt, depth))
    }

    fn stmt(&mut self, stmt: &Stmt, depth: usize) -> bool {
        match &stmt.kind {
            StmtKind::Block(block) => {
                self.block_names_stack.push(HashSet::new());
                let result = self.stmts(&block.stmts, depth + 1);
                self.block_names_stack.pop();
                result
            }
            StmtKind::Empty | StmtKind::Debugger | StmtKind::Break(_) | StmtKind::Continue(_) => {
                true
            }
            StmtKind::Expr(expr) => self.expr(expr, depth),
            StmtKind::VarDecl { kind, decls } => self.decls(kind, decls, depth),
            StmtKind::If {
                test,
                consequent,
                alternate,
            } => {
                self.expr(test, depth)
                    && self.stmt(consequent, depth + 1)
                    && alternate.as_deref().is_none_or(|a| self.stmt(a, depth + 1))
            }
            StmtKind::While { test, body } => self.expr(test, depth) && self.stmt(body, depth + 1),
            StmtKind::DoWhile { body, test } => {
                self.stmt(body, depth + 1) && self.expr(test, depth)
            }
            StmtKind::For {
                init,
                test,
                update,
                body,
            } => {
                // A lexical for-head binding is scoped to the for statement
                // itself (its head exprs and body): a reference at the same
                // depth after the loop would leak the flat slot, so the
                // scan rejects it (the body bails to the env path). Pattern
                // heads (Cut 59) contribute every bound name.
                let mut head_names = HashSet::new();
                let mut pattern_head_captured = false;
                if let Some(ForInit::VarDecl { kind, decls, .. }) = init
                    && *kind != VarDeclKind::Var
                {
                    for decl in decls {
                        if let BindingPattern::Ident(name) = decl.pattern {
                            head_names.insert(name);
                            self.for_head_lexicals.insert(name, depth);
                        } else {
                            // A captured lexical PATTERN head needs
                            // per-iteration freshness, which the certified
                            // machinery covers only for ident heads — stay on
                            // the env path. The names still scope to the loop
                            // (a reference after it would leak the flat slot).
                            let mut names = Vec::new();
                            crate::script::bound_names(&decl.pattern, &mut names);
                            for name in names {
                                let name = crux::intern_utf8(&name.to_string_lossy());
                                if self.captured.contains(&name) {
                                    pattern_head_captured = true;
                                }
                                head_names.insert(name);
                                self.for_head_lexicals.insert(name, depth);
                            }
                        }
                    }
                }
                self.open_for_heads.push(head_names);
                let init_ok = match init {
                    None => true,
                    Some(ForInit::Expr(expr)) => self.expr(expr, depth),
                    Some(ForInit::VarDecl { kind, decls }) => self.decls(kind, decls, depth),
                };
                self.open_loop_body_depths.push(depth + 1);
                let result = !pattern_head_captured
                    && init_ok
                    && test.as_ref().is_none_or(|t| self.expr(t, depth))
                    && update.as_ref().is_none_or(|u| self.expr(u, depth))
                    && self.stmt(body, depth + 1);
                self.open_loop_body_depths.pop();
                self.open_for_heads.pop();
                result
            }
            StmtKind::Return(expr) => expr.as_ref().is_none_or(|e| self.expr(e, depth)),
            StmtKind::Throw(expr) => self.expr(expr, depth),
            StmtKind::Labeled { body, .. } => self.stmt(body, depth),
            StmtKind::FunctionDecl(function) => {
                // A top-level function declaration binds a function-scoped
                // name like a `var` (initialized to the function value at
                // entry — spec 10.2.11), so it certifies; the declaration
                // statement itself is empty (15.2.6).
                if depth == 0 {
                    if function.statement_position {
                        return false;
                    }
                    let Some(name) = function.name else {
                        return false;
                    };
                    if self.captured.contains(&name) && !self.context_slots.contains_key(&name) {
                        self.context_slots.insert(name, self.context_names.len());
                        self.context_names.push(name);
                        self.context_tdz.push(false);
                        self.context_const.push(false);
                        self.context_param.push(None);
                    } else if !self.captured.contains(&name) && !self.slots.contains_key(&name) {
                        let slot = self.next_slot;
                        self.tdz.push(false);
                        self.next_slot += 1;
                        self.slots.insert(name, slot);
                    }
                    return true;
                }
                // Cut 6 continuation (Annex B): a statement-position
                // function declaration (`if (x) function f() {}`) — the
                // hoisted var binding is the only observable binding (the
                // env path's transient block env is unobservable), so the
                // statement instantiates the closure into its slot. The
                // hoist conditions match the block-level form; a dead
                // declaration (parameter/lexical conflict, async/generator)
                // compiles to nothing.
                if function.statement_position {
                    let Some(name) = function.name else {
                        return false;
                    };
                    let hoisted = !self.strict
                        && !function.is_async
                        && !function.is_generator
                        && !self.top_lexicals.contains(&name)
                        && !self.param_position.contains_key(&name)
                        && self
                            .hoist_spans
                            .get(&(function.span.start, function.span.end))
                            .copied()
                            .unwrap_or(false);
                    if hoisted {
                        // A captured name's var binding lives in the capture
                        // context (like any captured var); otherwise the
                        // function-scoped frame slot (reused when a `var` or
                        // top-level declaration already claims it).
                        let (frame_slot, context_slot) = if self.captured.contains(&name)
                            && !self.context_slots.contains_key(&name)
                        {
                            let index = self.context_names.len();
                            self.context_slots.insert(name, index);
                            self.context_names.push(name);
                            self.context_tdz.push(false);
                            self.context_const.push(false);
                            self.context_param.push(None);
                            (None, Some(index))
                        } else if self.captured.contains(&name) {
                            (None, self.context_slots.get(&name).copied())
                        } else if !self.slots.contains_key(&name) {
                            let slot = self.next_slot;
                            self.tdz.push(false);
                            self.next_slot += 1;
                            self.slots.insert(name, slot);
                            (Some(slot), None)
                        } else {
                            (self.slots.get(&name).copied(), None)
                        };
                        self.statement_fns.push(AnnexBStatementFn {
                            name,
                            span: function.span,
                            frame_slot,
                            context_slot,
                        });
                    }
                    return true;
                }
                // Cut 6 first slice (Annex B): a block-level function
                // declaration binds a block-scoped binding (initialized at
                // block entry) and, when the hoist applies, the
                // function-scoped var binding. Statement-position
                // declarations (bare `if (x) function f() {}`) and
                // declarations whose name a closure captures (the per-block
                // binding must be reachable through the env chain) stay on
                // the env path.
                let Some(name) = function.name else {
                    return false;
                };
                if self.captured.contains(&name) {
                    return false;
                }
                // Already bound in this block (an earlier function
                // declaration, or a same-block lexical): the declaration is
                // dead (14.2.3) — no block binding, no hoist. The check is
                // per block: a sibling block's binding does not apply.
                if self
                    .block_names_stack
                    .last()
                    .is_some_and(|names| names.contains(&name))
                {
                    return true;
                }
                // The hoist (B.3.3.4): a sloppy plain declaration whose
                // name is not a top-level lexical, a parameter, or any
                // enclosing statement list's lexical. The var binding
                // reuses an existing function-scoped slot (`var` or a
                // top-level function declaration of the same name) or gets
                // a fresh one.
                let var_slot = if !self.strict
                    && !function.is_async
                    && !function.is_generator
                    && !self.top_lexicals.contains(&name)
                    && !self.param_position.contains_key(&name)
                    && self
                        .hoist_spans
                        .get(&(function.span.start, function.span.end))
                        .copied()
                        .unwrap_or(false)
                {
                    match self.slots.get(&name) {
                        Some(slot) => Some(*slot),
                        None => {
                            let slot = self.next_slot;
                            self.tdz.push(false);
                            self.next_slot += 1;
                            self.slots.insert(name, slot);
                            Some(slot)
                        }
                    }
                } else {
                    None
                };
                let block_slot = self.next_slot;
                self.tdz.push(false);
                self.next_slot += 1;
                self.annex_b.push(AnnexBFunction {
                    name,
                    span: function.span,
                    function: Box::new(function.clone()),
                    block_slot,
                    var_slot,
                });
                if let Some(top) = self.block_names_stack.last_mut() {
                    top.insert(name);
                }
                true
            }
            StmtKind::ForIn {
                left, right, body, ..
            }
            | StmtKind::ForOf {
                left, right, body, ..
            } => {
                // Cut 3 continuation (for-of/for-in heads): a certified head
                // is a plain Ident VarDecl (var/let/const) whose binding is a
                // flat slot or the capture context, written per iteration.
                // Destructuring heads, expression targets (member/ident
                // assignment references), and `using` heads bind through the
                // environment machinery and keep the whole body on the env
                // path.
                if matches!(&stmt.kind, StmtKind::ForOf { is_await: true, .. }) {
                    return false;
                }
                let (kind, pattern, init) = match left {
                    ForBinding::VarDecl {
                        kind,
                        pattern,
                        init,
                    } => (*kind, pattern, init.as_ref()),
                    ForBinding::Expr(_) => return false,
                };
                if matches!(kind, VarDeclKind::Using | VarDeclKind::AwaitUsing) {
                    return false;
                }
                let BindingPattern::Ident(name) = pattern else {
                    return false;
                };
                let lexical = kind != VarDeclKind::Var;
                if lexical {
                    // A lexical head binding is scoped to the loop and must
                    // be unique (the flat slot/context layout cannot tell
                    // two scopes apart), mirroring `decls`.
                    if self.slots.contains_key(name) || self.context_slots.contains_key(name) {
                        return false;
                    }
                    self.declared_depth.insert(*name, depth);
                    if kind == VarDeclKind::Const {
                        self.consts.insert(*name);
                    }
                    if self.captured.contains(name) && !self.context_slots.contains_key(name) {
                        self.context_slots.insert(*name, self.context_names.len());
                        self.context_names.push(*name);
                        self.context_tdz.push(true);
                        self.context_const.push(kind == VarDeclKind::Const);
                        self.context_param.push(None);
                    } else if !self.captured.contains(name) && !self.slots.contains_key(name) {
                        let slot = self.next_slot;
                        self.tdz.push(true);
                        self.next_slot += 1;
                        self.slots.insert(*name, slot);
                    }
                    // The head is scoped to the loop: a reference outside
                    // the open loop would leak the flat slot.
                    self.for_head_lexicals.insert(*name, depth);
                    let mut head_names = HashSet::new();
                    head_names.insert(*name);
                    self.open_for_heads.push(head_names);
                    self.open_loop_body_depths.push(depth + 1);
                    let result = init.is_none_or(|init| self.expr(init, depth))
                        && self.expr(right, depth)
                        && self.stmt(body, depth + 1);
                    self.open_loop_body_depths.pop();
                    self.open_for_heads.pop();
                    result
                } else {
                    // A `var` head is function-scoped (hoisted): reuse the
                    // existing slot/context binding or allocate one.
                    if self.captured.contains(name) && !self.context_slots.contains_key(name) {
                        self.context_slots.insert(*name, self.context_names.len());
                        self.context_names.push(*name);
                        self.context_tdz.push(false);
                        self.context_const.push(false);
                        self.context_param.push(None);
                    } else if !self.captured.contains(name) && !self.slots.contains_key(name) {
                        let slot = self.next_slot;
                        self.tdz.push(false);
                        self.next_slot += 1;
                        self.slots.insert(*name, slot);
                    }
                    self.open_loop_body_depths.push(depth + 1);
                    let result = init.is_none_or(|init| self.expr(init, depth))
                        && self.expr(right, depth)
                        && self.stmt(body, depth + 1);
                    self.open_loop_body_depths.pop();
                    result
                }
            }
            StmtKind::Try {
                block,
                handler,
                finalizer,
            } => {
                // The try block is a block scope at depth + 1.
                self.block_names_stack.push(HashSet::new());
                let try_ok = self.stmts(&block.stmts, depth + 1);
                self.block_names_stack.pop();
                // The catch binds its parameter in a scope of its own (the
                // parameter env sits between the block env and the body env).
                // A simple Ident parameter gets a flat slot, written by
                // `CatchBind` at catch entry — its per-entry freshness is
                // unobservable without closures, so a captured parameter
                // (whose closure must see the fresh binding) and a
                // destructuring parameter (the pattern bindings need the env
                // machinery) keep the body on the env path. The catch body is
                // scanned one depth deeper than the try block so a try-block
                // reference to the parameter bails (it is not in scope there).
                let catch_ok = match handler {
                    None => true,
                    Some(handler) => {
                        if let Some(param) = &handler.param {
                            let BindingPattern::Ident(name) = param else {
                                return false;
                            };
                            if self.captured.contains(name)
                                || self.slots.contains_key(name)
                                || self.context_slots.contains_key(name)
                            {
                                return false;
                            }
                            let slot = self.next_slot;
                            self.tdz.push(false);
                            self.next_slot += 1;
                            self.slots.insert(*name, slot);
                            self.declared_depth.insert(*name, depth + 2);
                        }
                        self.block_names_stack.push(HashSet::new());
                        if let Some(param) = &handler.param
                            && let BindingPattern::Ident(name) = param
                            && let Some(top) = self.block_names_stack.last_mut()
                        {
                            // The parameter shadows a same-name block function
                            // declaration in the catch body (it is a lexical
                            // binding in the enclosing scope).
                            top.insert(*name);
                        }
                        let body_ok = self.stmts(&handler.body.stmts, depth + 2);
                        self.block_names_stack.pop();
                        body_ok
                    }
                };
                let finalizer_ok = finalizer.as_ref().is_none_or(|f| {
                    self.block_names_stack.push(HashSet::new());
                    let ok = self.stmts(&f.stmts, depth + 1);
                    self.block_names_stack.pop();
                    ok
                });
                try_ok && catch_ok && finalizer_ok
            }
            StmtKind::Switch {
                discriminant,
                cases,
                ..
            } => {
                // The discriminant and case tests evaluate BEFORE the switch
                // block's bindings initialize (the tests run first in the
                // compiled step stream), so they scan at the outer depth — a
                // test referencing a case-body lexical bails (it would read a
                // TDZ slot). The case consequents share ONE block scope (the
                // compiled `EnterBlock` holds all their declarations), so they
                // scan together at depth + 1 under a single block-names frame.
                if !self.expr(discriminant, depth) {
                    return false;
                }
                let tests_ok = cases
                    .iter()
                    .all(|case| case.test.as_ref().is_none_or(|t| self.expr(t, depth)));
                self.block_names_stack.push(HashSet::new());
                let body_ok = cases.iter().all(|case| {
                    // An Annex B block function declaration DIRECTLY in a
                    // case consequent needs the block-scope copy machinery
                    // the compiler activates only for `StmtKind::Block` (the
                    // case bodies compile as bare statement lists) — bail to
                    // the env path. A function nested in a block inside the
                    // consequent is fine (the inner Block arm activates it).
                    !case
                        .consequent
                        .iter()
                        .any(|stmt| matches!(stmt.kind, StmtKind::FunctionDecl(_)))
                        && self.stmts(&case.consequent, depth + 1)
                });
                self.block_names_stack.pop();
                tests_ok && body_ok
            }
            StmtKind::UsingDecl { .. } | StmtKind::ClassDecl(_) | StmtKind::With { .. } => false,
        }
    }

    fn decls(&mut self, kind: &VarDeclKind, decls: &[VarDeclarator], depth: usize) -> bool {
        let lexical = *kind != VarDeclKind::Var;
        for decl in decls {
            if !self.declare_pattern(&decl.pattern, lexical, *kind == VarDeclKind::Const, depth) {
                return false;
            }
            if let Some(init) = &decl.init
                && !self.expr(init, depth)
            {
                return false;
            }
        }
        true
    }

    /// Allocate every name a destructuring declaration pattern binds (Cut
    /// 59): the frame/context slot layout and the lexical bookkeeping
    /// (`declared_depth`, consts, block/loop-body scoping) apply per name
    /// exactly as the `Ident`-pattern fast path does; defaults and computed
    /// keys scan as expressions. The certified path compiles the pattern to
    /// the primitive `Destructure*` steps with slot binds, so any pattern
    /// shape (nested patterns, defaults, rest) certifies.
    fn declare_pattern(
        &mut self,
        pattern: &BindingPattern,
        lexical: bool,
        is_const: bool,
        depth: usize,
    ) -> bool {
        match pattern {
            BindingPattern::Ident(name) => {
                self.declare_pattern_name(*name, lexical, is_const, depth)
            }
            BindingPattern::Array(elements) => elements.iter().all(|element| match element {
                ArrayBindingElement::Hole => true,
                ArrayBindingElement::Element(element) | ArrayBindingElement::Rest(element) => {
                    self.declare_pattern_element(element, lexical, is_const, depth)
                }
            }),
            BindingPattern::Object(props) => props.iter().all(|prop| match prop {
                syntax::ast::ObjectBindingProperty::Property { key, element, .. } => {
                    let key_ok = match key {
                        PropertyName::Computed(expr) => self.expr(expr, depth),
                        _ => true,
                    };
                    key_ok && self.declare_pattern_element(element, lexical, is_const, depth)
                }
                syntax::ast::ObjectBindingProperty::Rest(element) => {
                    self.declare_pattern_element(element, lexical, is_const, depth)
                }
            }),
        }
    }

    fn declare_pattern_element(
        &mut self,
        element: &BindingElement,
        lexical: bool,
        is_const: bool,
        depth: usize,
    ) -> bool {
        self.declare_pattern(&element.pattern, lexical, is_const, depth)
            && element
                .init
                .as_ref()
                .is_none_or(|init| self.expr(init, depth))
    }

    fn declare_pattern_name(
        &mut self,
        name: crux::AtomId,
        lexical: bool,
        is_const: bool,
        depth: usize,
    ) -> bool {
        if lexical {
            // A lexical binding must be unique (the flat slot maps
            // cannot tell two scopes apart) and referenced only within
            // its scope; the per-iteration freshness of a `for`-head
            // binding is unobservable without closures, which the scan
            // rejects.
            if self.slots.contains_key(&name) || self.context_slots.contains_key(&name) {
                return false;
            }
            self.declared_depth.insert(name, depth);
            if is_const {
                self.consts.insert(name);
            }
            // Cut 6 first slice: a same-block lexical makes a later
            // block function declaration dead (the block env already
            // binds the name).
            if let Some(top) = self.block_names_stack.last_mut() {
                top.insert(name);
            }
            // A binding declared inside an open loop body is fresh per
            // iteration (the body block re-creates each iteration): a
            // closure capturing it must stay on the env path — the
            // certified per-iteration machinery covers only the
            // loop-head names.
            if self
                .open_loop_body_depths
                .iter()
                .any(|&body_depth| depth >= body_depth)
            {
                self.loop_body_lexicals.insert(name);
            }
        }
        // A captured binding lives in the capture context; a `var`
        // redeclaration reuses its existing slot/context binding.
        if self.captured.contains(&name) && !self.context_slots.contains_key(&name) {
            self.context_slots.insert(name, self.context_names.len());
            self.context_names.push(name);
            self.context_tdz.push(lexical);
            self.context_const.push(is_const);
            self.context_param.push(None);
        } else if !self.captured.contains(&name) && !self.slots.contains_key(&name) {
            let slot = self.next_slot;
            self.tdz.push(lexical);
            self.next_slot += 1;
            self.slots.insert(name, slot);
        }
        true
    }

    /// Whether a destructuring ASSIGNMENT target (`[a, b] = v`, `({x} = o)`)
    /// certifies (Cut 59): every element target is an identifier (a
    /// slot/context/global store) or a nested pattern; member targets need
    /// the reference machinery and reject the body. Defaults and computed
    /// keys scan as expressions.
    fn destructure_assign_target(&mut self, target: &Expr, depth: usize) -> bool {
        match &target.kind {
            ExprKind::Array(array) => array.elements.iter().all(|element| match element {
                ArrayElement::Hole => true,
                ArrayElement::Expr(expr) | ArrayElement::Spread(expr) => {
                    self.destructure_assign_element(expr, depth)
                }
            }),
            ExprKind::Object(object) => object.props.iter().all(|prop| match prop {
                ObjectProperty::Init { key, value, .. } => {
                    let key_ok = match key {
                        PropertyName::Computed(expr) => self.expr(expr, depth),
                        _ => true,
                    };
                    key_ok && self.destructure_assign_element(value, depth)
                }
                ObjectProperty::Spread(value) => self.destructure_assign_element(value, depth),
                _ => false,
            }),
            ExprKind::Paren(inner) => self.destructure_assign_target(inner, depth),
            _ => false,
        }
    }

    fn destructure_assign_element(&mut self, expr: &Expr, depth: usize) -> bool {
        match &expr.kind {
            ExprKind::Assign {
                op: AssignOp::Assign,
                target,
                value,
                ..
            } => self.destructure_assign_leaf(target, depth) && self.expr(value, depth),
            _ => self.destructure_assign_leaf(expr, depth),
        }
    }

    fn destructure_assign_leaf(&mut self, expr: &Expr, depth: usize) -> bool {
        match &expr.kind {
            ExprKind::Ident(name) => {
                // A `const` binding cannot be reassigned (the frame slot
                // has no const enforcement).
                !self.consts.contains(name) && self.expr(expr, depth)
            }
            ExprKind::Array(_) | ExprKind::Object(_) => self.destructure_assign_target(expr, depth),
            ExprKind::Paren(inner) => self.destructure_assign_leaf(inner, depth),
            // A member target needs the reference machinery.
            _ => false,
        }
    }

    fn expr(&mut self, expr: &Expr, depth: usize) -> bool {
        match &expr.kind {
            ExprKind::Literal(_) => true,
            // Array/object literals are side-effect-free, but their contents
            // are scanned: a method/getter/setter (a closure) or a closure
            // element could capture a certified slot, and a computed key is
            // an expression.
            ExprKind::Array(array) => array.elements.iter().all(|element| match element {
                ArrayElement::Hole => true,
                ArrayElement::Expr(expr) | ArrayElement::Spread(expr) => self.expr(expr, depth),
            }),
            ExprKind::Object(object) => object.props.iter().all(|prop| match prop {
                ObjectProperty::Method { .. }
                | ObjectProperty::Get { .. }
                | ObjectProperty::Set { .. } => false,
                ObjectProperty::Init { key, value, .. } => {
                    self.property_name(key, depth) && self.expr(value, depth)
                }
                ObjectProperty::Spread(expr) => self.expr(expr, depth),
            }),
            // `arguments` is the special unmapped/mapped binding the fast
            // path doesn't create — a reference must fall back to the
            // environment machinery. A lexical reference must sit inside
            // its declaring scope (equal or deeper block depth).
            ExprKind::Ident(name) => {
                let text = crux::lookup(*name);
                if text == JsString::from_utf8("arguments") {
                    // Cut 3 continuation (unmapped slice): a strict
                    // non-arrow body's own `arguments` reads get an
                    // `arguments` slot the certified call fills; a sloppy
                    // body needs the mapped object (deferred) and an arrow's
                    // `arguments` is lexical.
                    if !self.allow_arguments {
                        return false;
                    }
                    self.observes_arguments = true;
                    return true;
                }
                // A for-head lexical is scoped to its loop: a reference
                // outside the open loop (after the statement, or in a
                // sibling scope) would leak the flat slot — bail to the env
                // path.
                if self.for_head_lexicals.contains_key(name)
                    && !self.open_for_heads.iter().any(|set| set.contains(name))
                {
                    return false;
                }
                self.declared_depth
                    .get(name)
                    .is_none_or(|&declared| depth >= declared)
            }
            ExprKind::Paren(inner) => self.expr(inner, depth),
            ExprKind::Unary { operand, .. } => self.expr(operand, depth),
            ExprKind::Update { target, .. } => {
                // The frame has no const enforcement: a `const` target must
                // bail.
                !matches!(target.kind, ExprKind::Ident(name) if self.consts.contains(&name))
                    && self.expr(target, depth)
            }
            ExprKind::Binary { left, right, .. } => {
                self.expr(left, depth) && self.expr(right, depth)
            }
            ExprKind::Logical { left, right, .. } => {
                self.expr(left, depth) && self.expr(right, depth)
            }
            ExprKind::Conditional {
                test,
                consequent,
                alternate,
            } => {
                self.expr(test, depth)
                    && self.expr(consequent, depth)
                    && self.expr(alternate, depth)
            }
            ExprKind::Assign { target, value, .. } => {
                if matches!(target.kind, ExprKind::Object(_) | ExprKind::Array(_)) {
                    // Destructuring assignment (Cut 59): every element
                    // target is an identifier (slot/context/global store) or
                    // a nested pattern — member targets need the reference
                    // machinery. Defaults and computed keys scan below.
                    return self.destructure_assign_target(target, depth);
                }
                // A `const` binding cannot be reassigned (the frame slot
                // has no const enforcement).
                !matches!(target.kind, ExprKind::Ident(name) if self.consts.contains(&name))
                    && self.expr(target, depth)
                    && self.expr(value, depth)
            }
            ExprKind::Member(member) => {
                if matches!(member.property, MemberProperty::Private(_)) {
                    return false;
                }
                let object_ok = self.expr(&member.object, depth);
                let key_ok = match &member.property {
                    MemberProperty::Computed(key) => self.expr(key, depth),
                    _ => true,
                };
                object_ok && key_ok
            }
            ExprKind::Call(call) => {
                if matches!(
                    &call.callee.kind,
                    ExprKind::Ident(id) if crux::lookup(*id) == JsString::from_utf8("eval")
                ) {
                    return false;
                }
                let callee_ok = self.expr(&call.callee, depth);
                let args_ok = call.args.iter().all(|arg| match arg {
                    Argument::Expr(expr) => self.expr(expr, depth),
                    Argument::Spread(expr) => self.expr(expr, depth),
                });
                callee_ok && args_ok
            }
            ExprKind::New(new) => {
                let callee_ok = self.expr(&new.callee, depth);
                let args_ok = new.args.iter().all(|arg| match arg {
                    Argument::Expr(expr) => self.expr(expr, depth),
                    Argument::Spread(expr) => self.expr(expr, depth),
                });
                callee_ok && args_ok
            }
            ExprKind::Template(template) => template.exprs.iter().all(|e| self.expr(e, depth)),
            ExprKind::Sequence(exprs) => exprs.iter().all(|e| self.expr(e, depth)),

            ExprKind::This => {
                // Cut 3 continuation (this slots): a non-arrow body's own
                // `this` reads get a `this` slot the certified call fills
                // with the OrdinaryCallBindThis result; an arrow's `this` is
                // lexical — tasklist 2.3 certifies it when the enclosing
                // certified body captured it (the marker is in the outer
                // chain; the compile resolves it to a context read).
                if !self.allow_this {
                    return self.this_from_chain;
                }
                self.observes_this = true;
                true
            }
            ExprKind::Super => {
                // Cut 61: a method/accessor body's `super` — the base is the
                // home object's prototype, the receiver the certified this
                // slot. A closure (arrow) containing `super` bails the
                // enclosing body via `closure_expr_allows` (its `super` is
                // lexical); a class constructor's `super()` stays env-path.
                if !self.allow_super {
                    return false;
                }
                self.observes_super = true;
                true
            }
            ExprKind::MetaProperty { meta, property } => {
                // Cut 62: `new.target` certifies in non-arrow bodies — the
                // certified `NewTarget` step reads the per-run
                // `current_new_target` (the frame-slot model has no
                // FunctionEnv). An arrow's `new.target` is lexical (the
                // enclosing function's — like `this`), so it bails here;
                // `import.meta` (modules — never certified anyway) stays on
                // the env path.
                self.allow_this
                    && crux::lookup(*meta) == JsString::from_utf8("new")
                    && crux::lookup(*property) == JsString::from_utf8("target")
            }
            ExprKind::Class(_)
            | ExprKind::PrivateIn { .. }
            | ExprKind::TaggedTemplate { .. }
            | ExprKind::ImportCall { .. } => false,
            // A generator/async body's suspension points (Cut 58): the
            // argument scans like any other expression. A `yield*`
            // delegation (`delegate: true`) stays on the env path — its
            // `YieldStar*` machinery steps are not JIT-lowered.
            ExprKind::Yield {
                delegate: false,
                argument,
                ..
            } => argument.as_ref().is_none_or(|arg| self.expr(arg, depth)),
            ExprKind::Yield { delegate: true, .. } => false,
            ExprKind::Await(argument) => self.expr(argument, depth),
            ExprKind::Function(function) => {
                // Cut 3 continuation (closure capture): a closure created by
                // a certified body — its references to body bindings are
                // captures (the body context-allocates them); a construct
                // that observes the body's absent `this`/`arguments`/
                // `new.target`/`super` (arrows inherit them lexically; a
                // direct `eval`/`with` can see the body's names) bails the
                // body. Its own body compiles separately.
                closure_allows(
                    &function.params,
                    &function.body.stmts,
                    &self.bindings,
                    &mut self.captured,
                )
            }
            ExprKind::Arrow { params, body, .. } => {
                closure_arrow_allows(params, body, &self.bindings, &mut self.captured, false)
            }
        }
    }

    fn property_name(&mut self, name: &PropertyName, depth: usize) -> bool {
        match name {
            PropertyName::Ident(_) | PropertyName::Str(_) | PropertyName::Number(_) => true,
            PropertyName::Computed(expr) => self.expr(expr, depth),
        }
    }
}

// ---- Script-level bindings (fast scripts) ----
//
// Certify a top-level *script* for direct global-object access: every
// declared `var`/function name becomes a `LoadGlobal`/`StoreGlobal`
// binding, skipping the env-chain resolve walk that top-level reads pay
// today (the bench loops and host tools are top-level scripts). Script
// instantiation already created the global properties, so a fast read is
// guaranteed to resolve; undeclared names stay on the env path (the
// ReferenceError / host-global cases). Modules and eval bodies never take
// this path — modules bind into the module environment, and eval bodies
// can see (and shadow) the caller's lexical environment.

/// The declared var names of a certified script, laid out as frame slots
/// (Cut 16): the script runs with its vars in the borrow-free frame, and
/// the prologue/epilogue sync them to the global object. The per-access
/// cost drops from the global fast path (direct-mapped probe + `Rc` clone
/// of the global handle + `RefCell` borrow + key compare) to a plain frame
/// read/write — V8's model for non-escaping script vars (context slots).
struct ScriptSlots {
    scope: ScopeInfo,
    /// Slot order → declared name (the prologue/epilogue sync steps).
    names: Vec<crux::AtomId>,
    /// The vars the script assigns (initializer, `=`/compound, `++`/`--`,
    /// for-of head): only these need the epilogue write-back — a declared
    /// read-only global like `Infinity` must not be written just because it
    /// was declared.
    assigned: HashSet<crux::AtomId>,
}

/// Analyze a top-level script for the certified binding paths: the
/// The vars the script assigns (initializers, `=`/compound assignments,
/// `++`/`--`, for-of heads) — the epilogue write-back set (Cut 16).
/// Collected as a prepass: the certified-function analysis needs it to
/// reject assignments to certified names, and the slot scan needs it
/// read-only. Mirrors the assignments the slot scan records; a destructuring
/// pattern keeps the script off the frame path either way, so only Ident
/// targets are collected.
fn collect_script_assigned(stmts: &[Stmt], assigned: &mut HashSet<crux::AtomId>) {
    for stmt in stmts {
        collect_assigned_stmt(stmt, assigned);
    }
}

fn collect_assigned_stmt(stmt: &Stmt, assigned: &mut HashSet<crux::AtomId>) {
    match &stmt.kind {
        StmtKind::Block(block) => collect_script_assigned(&block.stmts, assigned),
        StmtKind::Expr(expr) => collect_assigned_expr(expr, assigned),
        StmtKind::VarDecl { decls, .. } => {
            for decl in decls {
                if let BindingPattern::Ident(name) = &decl.pattern
                    && decl.init.is_some()
                {
                    assigned.insert(*name);
                }
            }
        }
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            collect_assigned_expr(test, assigned);
            collect_assigned_stmt(consequent, assigned);
            if let Some(alternate) = alternate {
                collect_assigned_stmt(alternate, assigned);
            }
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            collect_assigned_expr(test, assigned);
            collect_assigned_stmt(body, assigned);
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            match init {
                Some(ForInit::Expr(expr)) => collect_assigned_expr(expr, assigned),
                Some(ForInit::VarDecl { decls, .. }) => {
                    for decl in decls {
                        if let BindingPattern::Ident(name) = &decl.pattern
                            && decl.init.is_some()
                        {
                            assigned.insert(*name);
                        }
                    }
                }
                None => {}
            }
            if let Some(test) = test {
                collect_assigned_expr(test, assigned);
            }
            if let Some(update) = update {
                collect_assigned_expr(update, assigned);
            }
            collect_assigned_stmt(body, assigned);
        }
        StmtKind::Return(expr) => {
            if let Some(expr) = expr {
                collect_assigned_expr(expr, assigned);
            }
        }
        StmtKind::Throw(expr) => collect_assigned_expr(expr, assigned),
        StmtKind::Labeled { body, .. } => collect_assigned_stmt(body, assigned),
        StmtKind::ForOf {
            left, right, body, ..
        } => {
            if let ForBinding::VarDecl {
                pattern: BindingPattern::Ident(name),
                ..
            } = left
            {
                assigned.insert(*name);
            }
            collect_assigned_expr(right, assigned);
            collect_assigned_stmt(body, assigned);
        }
        StmtKind::Empty
        | StmtKind::Debugger
        | StmtKind::Break(_)
        | StmtKind::Continue(_)
        | StmtKind::ClassDecl(_)
        | StmtKind::With { .. }
        | StmtKind::Try { .. }
        | StmtKind::Switch { .. }
        | StmtKind::ForIn { .. }
        | StmtKind::UsingDecl { .. } => {}
        // A function body can assign a declared name (an uncertified
        // function's write lands on the global object) — the prepass must
        // walk it so the fused-call never-assigned check sees the write.
        StmtKind::FunctionDecl(function) => collect_assigned_stmts(&function.body.stmts, assigned),
    }
}

fn collect_assigned_stmts(stmts: &[Stmt], assigned: &mut HashSet<crux::AtomId>) {
    for stmt in stmts {
        collect_assigned_stmt(stmt, assigned);
    }
}

fn collect_assigned_expr(expr: &Expr, assigned: &mut HashSet<crux::AtomId>) {
    match &expr.kind {
        ExprKind::Paren(inner) => collect_assigned_expr(inner, assigned),
        ExprKind::Unary { operand, .. } => collect_assigned_expr(operand, assigned),
        ExprKind::Update { target, .. } => {
            record_assign_target(target, assigned);
            collect_assigned_expr(target, assigned);
        }
        ExprKind::Binary { left, right, .. } | ExprKind::Logical { left, right, .. } => {
            collect_assigned_expr(left, assigned);
            collect_assigned_expr(right, assigned);
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            collect_assigned_expr(test, assigned);
            collect_assigned_expr(consequent, assigned);
            collect_assigned_expr(alternate, assigned);
        }
        ExprKind::Assign { target, value, .. } => {
            record_assign_target(target, assigned);
            collect_assigned_expr(target, assigned);
            collect_assigned_expr(value, assigned);
        }
        ExprKind::Member(member) => {
            collect_assigned_expr(&member.object, assigned);
            if let MemberProperty::Computed(key) = &member.property {
                collect_assigned_expr(key, assigned);
            }
        }
        ExprKind::Array(array) => {
            for element in &array.elements {
                match element {
                    ArrayElement::Hole => {}
                    ArrayElement::Expr(e) | ArrayElement::Spread(e) => {
                        collect_assigned_expr(e, assigned)
                    }
                }
            }
        }
        ExprKind::Object(object) => {
            for prop in &object.props {
                match prop {
                    ObjectProperty::Method { .. }
                    | ObjectProperty::Get { .. }
                    | ObjectProperty::Set { .. } => {}
                    ObjectProperty::Init { key, value, .. } => {
                        if let PropertyName::Computed(key_expr) = key {
                            collect_assigned_expr(key_expr, assigned);
                        }
                        collect_assigned_expr(value, assigned);
                    }
                    ObjectProperty::Spread(e) => collect_assigned_expr(e, assigned),
                }
            }
        }
        ExprKind::Template(template) => {
            for e in &template.exprs {
                collect_assigned_expr(e, assigned);
            }
        }
        ExprKind::Sequence(exprs) => {
            for e in exprs {
                collect_assigned_expr(e, assigned);
            }
        }
        ExprKind::Call(call) => {
            collect_assigned_expr(&call.callee, assigned);
            for arg in &call.args {
                match arg {
                    Argument::Expr(e) | Argument::Spread(e) => collect_assigned_expr(e, assigned),
                }
            }
        }
        ExprKind::New(new) => {
            collect_assigned_expr(&new.callee, assigned);
            for arg in &new.args {
                match arg {
                    Argument::Expr(e) | Argument::Spread(e) => collect_assigned_expr(e, assigned),
                }
            }
        }
        // A function/arrow body can assign a declared name (an uncertified
        // closure's write lands on the global object) — walk it for the
        // fused-call never-assigned check.
        ExprKind::Function(function) => collect_assigned_stmts(&function.body.stmts, assigned),
        ExprKind::Arrow { body, .. } => match body {
            syntax::ast::ArrowBody::Expr(expr) => collect_assigned_expr(expr, assigned),
            syntax::ast::ArrowBody::Block(block) => collect_assigned_stmts(&block.stmts, assigned),
        },
        ExprKind::Ident(_)
        | ExprKind::Literal(_)
        | ExprKind::This
        | ExprKind::Super
        | ExprKind::Class(_)
        | ExprKind::TaggedTemplate { .. }
        | ExprKind::PrivateIn { .. }
        | ExprKind::Yield { .. }
        | ExprKind::Await(_)
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => {}
    }
}

// ---- Gap-close M6 slice 2: the hoisted-loop purity walkers ----
//
// A loop whose `RECV.length` test limit is hoisted needs its body + update
// to be "length-pure": nothing may run user code (a call, a getter/setter
// via a member access — anything that could detach/resize/redefine the
// view) and the only member access allowed is a `RECV.length` READ or a
// `RECV[expr] = v` STORE (element writes and own-prop defines cannot change
// the accessor-served length; other receivers could alias RECV through a
// global, so they are excluded entirely).

/// Whether `expr` may appear in a hoisted loop's body (see the module note).
fn expr_is_hoist_pure(expr: &Expr, recv: crux::AtomId, length_atom: crux::AtomId) -> bool {
    match &expr.kind {
        ExprKind::Literal(_) | ExprKind::Ident(_) | ExprKind::This => true,
        ExprKind::Paren(inner) => expr_is_hoist_pure(inner, recv, length_atom),
        ExprKind::Unary { op, operand } => {
            !matches!(op, UnaryOp::Delete) && expr_is_hoist_pure(operand, recv, length_atom)
        }
        ExprKind::Update { target, .. } => {
            // A bare `++`/`--` on a binding; an update of RECV is already
            // rejected by the assigned scan.
            matches!(&target.kind, ExprKind::Ident(_))
                && expr_is_hoist_pure(target, recv, length_atom)
        }
        ExprKind::Binary { left, right, .. } | ExprKind::Logical { left, right, .. } => {
            expr_is_hoist_pure(left, recv, length_atom)
                && expr_is_hoist_pure(right, recv, length_atom)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            expr_is_hoist_pure(test, recv, length_atom)
                && expr_is_hoist_pure(consequent, recv, length_atom)
                && expr_is_hoist_pure(alternate, recv, length_atom)
        }
        ExprKind::Sequence(exprs) => exprs
            .iter()
            .all(|e| expr_is_hoist_pure(e, recv, length_atom)),
        ExprKind::Template(template) => template
            .exprs
            .iter()
            .all(|e| expr_is_hoist_pure(e, recv, length_atom)),
        ExprKind::Assign {
            op, target, value, ..
        } => {
            let target_ok = match &target.kind {
                // A binding assignment (RECV itself excluded by the assigned
                // scan); compound forms read/write the binding, which is
                // fine.
                ExprKind::Ident(_) => expr_is_hoist_pure(target, recv, length_atom),
                // The allowed element store: `RECV[expr] = v` (plain assign
                // only — the compound form's read runs through the general
                // member rule). For canonical keys this is the pure
                // IntegerIndexedElementSet write; a non-canonical key defines
                // an own property (or no-ops), which cannot change the
                // accessor-served length. Only the key is recursed — the
                // member expression itself is the special-cased target.
                ExprKind::Member(MemberExpr {
                    object,
                    property: MemberProperty::Computed(key),
                    optional: false,
                    ..
                }) if matches!(op, AssignOp::Assign) => {
                    matches!(&object.kind, ExprKind::Ident(name) if *name == recv)
                        && expr_is_hoist_pure(key, recv, length_atom)
                }
                _ => false,
            };
            target_ok && expr_is_hoist_pure(value, recv, length_atom)
        }
        ExprKind::Member(MemberExpr {
            object,
            property: MemberProperty::Name(prop),
            optional: false,
            ..
        }) => {
            // The allowed read: `RECV.length` (probe-served — no accessor
            // invocation, exact). Any other member access is rejected.
            *prop == length_atom
                && matches!(&object.kind, ExprKind::Ident(name) if *name == recv)
                && expr_is_hoist_pure(object, recv, length_atom)
        }
        ExprKind::Call(_)
        | ExprKind::New(_)
        | ExprKind::Member(_)
        | ExprKind::Array(_)
        | ExprKind::Object(_)
        | ExprKind::Function(_)
        | ExprKind::Class(_)
        | ExprKind::Arrow { .. }
        | ExprKind::TaggedTemplate { .. }
        | ExprKind::PrivateIn { .. }
        | ExprKind::Super
        | ExprKind::Yield { .. }
        | ExprKind::Await(_)
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => false,
    }
}

/// Whether `stmt` may appear in a hoisted loop's body (see the module note).
fn stmt_is_hoist_pure(stmt: &Stmt, recv: crux::AtomId, length_atom: crux::AtomId) -> bool {
    match &stmt.kind {
        // Break/continue/return/throw exit the hoisted loop's fused copy —
        // the JIT's fused canonical loop has pre-existing control-transfer
        // bugs (break/continue in a fused body corrupt the machine state),
        // so only bodies whose control flow stays inside (if/while/for with
        // no out-of-body transfer) hoist.
        StmtKind::Empty | StmtKind::Debugger => true,
        StmtKind::Block(block) => block
            .stmts
            .iter()
            .all(|s| stmt_is_hoist_pure(s, recv, length_atom)),
        StmtKind::Expr(expr) => expr_is_hoist_pure(expr, recv, length_atom),
        StmtKind::VarDecl { decls, .. } => decls.iter().all(|decl| {
            matches!(&decl.pattern, BindingPattern::Ident(_))
                && decl
                    .init
                    .as_ref()
                    .is_none_or(|init| expr_is_hoist_pure(init, recv, length_atom))
        }),
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            expr_is_hoist_pure(test, recv, length_atom)
                && stmt_is_hoist_pure(consequent, recv, length_atom)
                && alternate
                    .as_ref()
                    .is_none_or(|a| stmt_is_hoist_pure(a, recv, length_atom))
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            expr_is_hoist_pure(test, recv, length_atom)
                && stmt_is_hoist_pure(body, recv, length_atom)
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            let init_ok = match init {
                None => true,
                Some(ForInit::Expr(expr)) => expr_is_hoist_pure(expr, recv, length_atom),
                Some(ForInit::VarDecl { decls, .. }) => decls.iter().all(|decl| {
                    matches!(&decl.pattern, BindingPattern::Ident(_))
                        && decl
                            .init
                            .as_ref()
                            .is_none_or(|init| expr_is_hoist_pure(init, recv, length_atom))
                }),
            };
            init_ok
                && test
                    .as_ref()
                    .is_none_or(|t| expr_is_hoist_pure(t, recv, length_atom))
                && update
                    .as_ref()
                    .is_none_or(|u| expr_is_hoist_pure(u, recv, length_atom))
                && stmt_is_hoist_pure(body, recv, length_atom)
        }
        StmtKind::Labeled { .. } => false,
        StmtKind::Break(_) | StmtKind::Continue(_) | StmtKind::Return(_) | StmtKind::Throw(_) => {
            false
        }
        StmtKind::FunctionDecl(_)
        | StmtKind::ClassDecl(_)
        | StmtKind::UsingDecl { .. }
        | StmtKind::Try { .. }
        | StmtKind::Switch { .. }
        | StmtKind::With { .. }
        | StmtKind::ForIn { .. }
        | StmtKind::ForOf { .. } => false,
    }
}

/// The top-level function-declaration names that are "global-blind" (Cut 35
/// slice 3): a fixpoint — a function certifies when its body never observes
/// the global object given the already-certified names (a body may read a
/// certified name's stable entry-instantiated global binding, so a function
/// whose body calls/reads another certifies after it). Recursion never
/// certifies (a function cannot read its own name in the pass before it is
/// certified). An assigned name is never a candidate: its global binding
/// could change, so reading it is unsafe.
fn certified_functions(
    names: &[crux::AtomId],
    assigned: &HashSet<crux::AtomId>,
    stmts: &[Stmt],
) -> HashSet<crux::AtomId> {
    let declared: HashSet<crux::AtomId> = names.iter().copied().collect();
    let mut candidates: Vec<&syntax::ast::Function> = Vec::new();
    for stmt in stmts {
        if let StmtKind::FunctionDecl(function) = &stmt.kind
            && let Some(name) = function.name
            && !assigned.contains(&name)
        {
            candidates.push(function);
        }
    }
    let mut certified: HashSet<crux::AtomId> = HashSet::new();
    loop {
        let mut changed = false;
        for function in &candidates {
            let Some(name) = function.name else {
                continue;
            };
            if certified.contains(&name) {
                continue;
            }
            if certified_fn_allows(function, &declared, &certified) {
                certified.insert(name);
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }
    certified
}

/// Whether a top-level function declaration is "global-blind": its body can
/// never observe the global object while the script's frame slots are
/// authoritative. The body may read/write only its own params and locals,
/// undeclared names (real, never-stale global properties), and the stable
/// entry-instantiated bindings of other certified functions; it may not
/// reference any other declared var (a stale slot on the global object),
/// call anything else, or create closures. Conservative — a shape that could
/// observe the global object keeps the whole script on the global path.
fn certified_fn_allows(
    function: &syntax::ast::Function,
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
) -> bool {
    if function.is_async || function.is_generator || function.statement_position {
        return false;
    }
    certified_stmts_allows(&function.body.stmts, declared, certified)
}

fn certified_stmts_allows(
    stmts: &[Stmt],
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
) -> bool {
    stmts
        .iter()
        .all(|stmt| certified_stmt_allows(stmt, declared, certified))
}

fn certified_stmt_allows(
    stmt: &Stmt,
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
) -> bool {
    match &stmt.kind {
        StmtKind::Block(block) => certified_stmts_allows(&block.stmts, declared, certified),
        StmtKind::Empty | StmtKind::Debugger | StmtKind::Break(_) | StmtKind::Continue(_) => true,
        StmtKind::Expr(expr) => certified_expr_allows(expr, declared, certified),
        StmtKind::VarDecl { kind, decls } => {
            *kind == VarDeclKind::Var
                && decls.iter().all(|decl| {
                    matches!(&decl.pattern, BindingPattern::Ident(_))
                        && decl
                            .init
                            .as_ref()
                            .is_none_or(|init| certified_expr_allows(init, declared, certified))
                })
        }
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            certified_expr_allows(test, declared, certified)
                && certified_stmt_allows(consequent, declared, certified)
                && alternate
                    .as_deref()
                    .is_none_or(|stmt| certified_stmt_allows(stmt, declared, certified))
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            certified_expr_allows(test, declared, certified)
                && certified_stmt_allows(body, declared, certified)
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            let init_ok = match init {
                None => true,
                Some(ForInit::Expr(expr)) => certified_expr_allows(expr, declared, certified),
                Some(ForInit::VarDecl { kind, decls }) => {
                    *kind == VarDeclKind::Var
                        && decls.iter().all(|decl| {
                            matches!(&decl.pattern, BindingPattern::Ident(_))
                                && decl.init.as_ref().is_none_or(|init| {
                                    certified_expr_allows(init, declared, certified)
                                })
                        })
                }
            };
            init_ok
                && test
                    .as_ref()
                    .is_none_or(|expr| certified_expr_allows(expr, declared, certified))
                && update
                    .as_ref()
                    .is_none_or(|expr| certified_expr_allows(expr, declared, certified))
                && certified_stmt_allows(body, declared, certified)
        }
        StmtKind::Return(expr) => expr
            .as_ref()
            .is_none_or(|expr| certified_expr_allows(expr, declared, certified)),
        StmtKind::Throw(expr) => certified_expr_allows(expr, declared, certified),
        StmtKind::Labeled { body, .. } => certified_stmt_allows(body, declared, certified),
        StmtKind::ForOf {
            left, right, body, ..
        } => {
            matches!(
                left,
                ForBinding::VarDecl {
                    pattern: BindingPattern::Ident(_),
                    ..
                }
            ) && certified_expr_allows(right, declared, certified)
                && certified_stmt_allows(body, declared, certified)
        }
        // Nested functions/closures/classes, `with`, `try`, `switch`,
        // `for-in`, `using`: a shape that could observe the global object.
        StmtKind::FunctionDecl(_)
        | StmtKind::ClassDecl(_)
        | StmtKind::With { .. }
        | StmtKind::Try { .. }
        | StmtKind::Switch { .. }
        | StmtKind::ForIn { .. }
        | StmtKind::UsingDecl { .. } => false,
    }
}

fn certified_expr_allows(
    expr: &Expr,
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
) -> bool {
    match &expr.kind {
        ExprKind::Ident(name) => {
            let text = crux::lookup(*name).to_string_lossy();
            if matches!(
                text.as_str(),
                "globalThis" | "global" | "window" | "self" | "top" | "parent" | "frames"
            ) {
                return false;
            }
            // A declared name reads the stale slot on the global object —
            // unless it is a certified function's stable global binding.
            !declared.contains(name) || certified.contains(name)
        }
        ExprKind::Literal(_) => true,
        ExprKind::Paren(inner) => certified_expr_allows(inner, declared, certified),
        ExprKind::Unary { operand, .. } => certified_expr_allows(operand, declared, certified),
        ExprKind::Update { target, .. } => certified_expr_allows(target, declared, certified),
        ExprKind::Binary { left, right, .. } | ExprKind::Logical { left, right, .. } => {
            certified_expr_allows(left, declared, certified)
                && certified_expr_allows(right, declared, certified)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            certified_expr_allows(test, declared, certified)
                && certified_expr_allows(consequent, declared, certified)
                && certified_expr_allows(alternate, declared, certified)
        }
        ExprKind::Assign { target, value, .. } => {
            certified_expr_allows(target, declared, certified)
                && certified_expr_allows(value, declared, certified)
        }
        ExprKind::Member(member) => {
            certified_expr_allows(&member.object, declared, certified)
                && match &member.property {
                    MemberProperty::Computed(key) => {
                        certified_expr_allows(key, declared, certified)
                    }
                    _ => true,
                }
        }
        ExprKind::Array(array) => array.elements.iter().all(|element| match element {
            ArrayElement::Hole => true,
            ArrayElement::Expr(e) | ArrayElement::Spread(e) => {
                certified_expr_allows(e, declared, certified)
            }
        }),
        ExprKind::Object(object) => object.props.iter().all(|prop| match prop {
            ObjectProperty::Method { .. }
            | ObjectProperty::Get { .. }
            | ObjectProperty::Set { .. } => false,
            ObjectProperty::Init { key, value, .. } => {
                let key_ok = match key {
                    PropertyName::Ident(_) | PropertyName::Str(_) | PropertyName::Number(_) => true,
                    PropertyName::Computed(key_expr) => {
                        certified_expr_allows(key_expr, declared, certified)
                    }
                };
                key_ok && certified_expr_allows(value, declared, certified)
            }
            ObjectProperty::Spread(e) => certified_expr_allows(e, declared, certified),
        }),
        ExprKind::Template(template) => template
            .exprs
            .iter()
            .all(|expr| certified_expr_allows(expr, declared, certified)),
        ExprKind::Sequence(exprs) => exprs
            .iter()
            .all(|expr| certified_expr_allows(expr, declared, certified)),
        // A certified closure (global-blind body) may be created and escape
        // — calling it later reads only its captured env, never the global
        // object. `this`/`super`/uncertified closures/classes are out.
        ExprKind::Function(function) => certified_fn_allows(function, declared, certified),
        ExprKind::Arrow { is_async, body, .. } => {
            certified_arrow_allows(*is_async, body, declared, certified)
        }
        ExprKind::This
        | ExprKind::Super
        | ExprKind::Call(_)
        | ExprKind::New(_)
        | ExprKind::Class(_)
        | ExprKind::TaggedTemplate { .. }
        | ExprKind::PrivateIn { .. }
        | ExprKind::Yield { .. }
        | ExprKind::Await(_)
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => false,
    }
}

/// A certified arrow/function-expression closure: the same body scan as a
/// certified declaration. `Function` expressions go through
/// `certified_fn_allows` (same struct shape); an arrow's body may be a
/// bare expression.
fn certified_arrow_allows(
    is_async: bool,
    body: &syntax::ast::ArrowBody,
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
) -> bool {
    if is_async {
        return false;
    }
    match body {
        syntax::ast::ArrowBody::Expr(expr) => certified_expr_allows(expr, declared, certified),
        syntax::ast::ArrowBody::Block(block) => {
            certified_stmts_allows(&block.stmts, declared, certified)
        }
    }
}

/// Whether an expression evaluates to a "certified value": holding or
/// calling it cannot observe the frame-slot globals. A certified closure, a
/// literal, or a certified-call result (the callee's return is certified).
/// Used for the certified-return analysis and the top-level call gate (a
/// var assigned a certified value may be called).
fn certified_value_expr(
    expr: &Expr,
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
    return_certs: &HashMap<crux::AtomId, bool>,
    var_certs: &HashMap<crux::AtomId, bool>,
) -> bool {
    match &expr.kind {
        ExprKind::Literal(_) => true,
        ExprKind::Paren(inner) => {
            certified_value_expr(inner, declared, certified, return_certs, var_certs)
        }
        ExprKind::Function(function) => certified_fn_allows(function, declared, certified),
        ExprKind::Arrow { is_async, body, .. } => {
            certified_arrow_allows(*is_async, body, declared, certified)
        }
        ExprKind::Ident(name) => var_certs.get(name).copied().unwrap_or(false),
        ExprKind::Call(call) => match &call.callee.kind {
            ExprKind::Ident(name) => {
                certified.contains(name) && return_certs.get(name).copied().unwrap_or(false)
            }
            _ => false,
        },
        ExprKind::Unary { operand, .. } => {
            certified_value_expr(operand, declared, certified, return_certs, var_certs)
        }
        ExprKind::Binary { left, right, .. } | ExprKind::Logical { left, right, .. } => {
            certified_value_expr(left, declared, certified, return_certs, var_certs)
                && certified_value_expr(right, declared, certified, return_certs, var_certs)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            certified_value_expr(test, declared, certified, return_certs, var_certs)
                && certified_value_expr(consequent, declared, certified, return_certs, var_certs)
                && certified_value_expr(alternate, declared, certified, return_certs, var_certs)
        }
        ExprKind::Array(array) => array.elements.iter().all(|element| match element {
            ArrayElement::Hole => true,
            ArrayElement::Expr(e) | ArrayElement::Spread(e) => {
                certified_value_expr(e, declared, certified, return_certs, var_certs)
            }
        }),
        ExprKind::Object(object) => object.props.iter().all(|prop| match prop {
            ObjectProperty::Method { .. }
            | ObjectProperty::Get { .. }
            | ObjectProperty::Set { .. } => false,
            ObjectProperty::Init { key, value, .. } => {
                let key_ok = match key {
                    PropertyName::Ident(_) | PropertyName::Str(_) | PropertyName::Number(_) => true,
                    PropertyName::Computed(key_expr) => {
                        certified_expr_allows(key_expr, declared, certified)
                    }
                };
                key_ok && certified_value_expr(value, declared, certified, return_certs, var_certs)
            }
            ObjectProperty::Spread(e) => {
                certified_value_expr(e, declared, certified, return_certs, var_certs)
            }
        }),
        ExprKind::Template(template) => template
            .exprs
            .iter()
            .all(|e| certified_value_expr(e, declared, certified, return_certs, var_certs)),
        ExprKind::Sequence(exprs) => exprs
            .iter()
            .all(|e| certified_value_expr(e, declared, certified, return_certs, var_certs)),
        _ => false,
    }
}

/// The certified-return set (Cut 35 slice 3): a certified top-level
/// function's return value is certified when every `return` in its body is
/// a certified value (a literal, a certified closure, or a call to a
/// certified-return function). Fixpoint over the certified declarations —
/// the return value never feeds back into the body certification, so this
/// settles after the function set does. `var_certs` is never consulted: a
/// certified body cannot read a declared var, so an `Ident` return is a
/// param/local (unknown — uncertified).
fn certified_return_certs(
    stmts: &[Stmt],
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
) -> HashMap<crux::AtomId, bool> {
    let decls: Vec<&syntax::ast::Function> = stmts
        .iter()
        .filter_map(|stmt| match &stmt.kind {
            StmtKind::FunctionDecl(function)
                if function.name.is_some_and(|name| certified.contains(&name)) =>
            {
                Some(function)
            }
            _ => None,
        })
        .collect();
    let mut certs: HashMap<crux::AtomId, bool> = certified.iter().map(|n| (*n, false)).collect();
    loop {
        let mut changed = false;
        for function in &decls {
            let Some(name) = function.name else {
                continue;
            };
            if certs[&name] {
                continue;
            }
            if fn_returns_certified(function, declared, certified, &certs) {
                certs.insert(name, true);
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }
    certs
}

fn fn_returns_certified(
    function: &syntax::ast::Function,
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
    return_certs: &HashMap<crux::AtomId, bool>,
) -> bool {
    let var_certs = HashMap::new();
    returns_all_certified(
        &function.body.stmts,
        declared,
        certified,
        return_certs,
        &var_certs,
    )
}

fn returns_all_certified(
    stmts: &[Stmt],
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
    return_certs: &HashMap<crux::AtomId, bool>,
    var_certs: &HashMap<crux::AtomId, bool>,
) -> bool {
    for stmt in stmts {
        let ok = match &stmt.kind {
            StmtKind::Block(block) => {
                returns_all_certified(&block.stmts, declared, certified, return_certs, var_certs)
            }
            StmtKind::If {
                consequent,
                alternate,
                ..
            } => {
                returns_all_certified(
                    std::slice::from_ref(consequent.as_ref()),
                    declared,
                    certified,
                    return_certs,
                    var_certs,
                ) && alternate.as_deref().is_none_or(|stmt| {
                    returns_all_certified(
                        std::slice::from_ref(stmt),
                        declared,
                        certified,
                        return_certs,
                        var_certs,
                    )
                })
            }
            StmtKind::While { body, .. } | StmtKind::DoWhile { body, .. } => returns_all_certified(
                std::slice::from_ref(body),
                declared,
                certified,
                return_certs,
                var_certs,
            ),
            StmtKind::For { body, .. } => returns_all_certified(
                std::slice::from_ref(body),
                declared,
                certified,
                return_certs,
                var_certs,
            ),
            StmtKind::Labeled { body, .. } => returns_all_certified(
                std::slice::from_ref(body),
                declared,
                certified,
                return_certs,
                var_certs,
            ),
            StmtKind::Return(expr) => expr.as_ref().is_none_or(|expr| {
                certified_value_expr(expr, declared, certified, return_certs, var_certs)
            }),
            _ => true,
        };
        if !ok {
            return false;
        }
    }
    true
}

/// The vars assigned a certified value (Cut 35 slice 3): a top-level
/// `name = <certified value>` (initializer or plain `=` with an identifier
/// target) makes the var's value safe to call — a certified closure, a
/// literal, or a certified-call result. Multiple assignments AND (any
/// uncertified assignment makes the var unknown); compound/`++`/`--`
/// assignments mark the var unknown. Source order, so `var g = f` after
/// `var f = make(2)` sees `f`'s cert.
fn collect_var_certs(
    stmts: &[Stmt],
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
    return_certs: &HashMap<crux::AtomId, bool>,
    var_certs: &mut HashMap<crux::AtomId, bool>,
) {
    for stmt in stmts {
        var_certs_stmt(stmt, declared, certified, return_certs, var_certs);
    }
}

fn var_certs_stmt(
    stmt: &Stmt,
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
    return_certs: &HashMap<crux::AtomId, bool>,
    var_certs: &mut HashMap<crux::AtomId, bool>,
) {
    match &stmt.kind {
        StmtKind::Block(block) => {
            collect_var_certs(&block.stmts, declared, certified, return_certs, var_certs)
        }
        StmtKind::Expr(expr) => var_certs_expr(expr, declared, certified, return_certs, var_certs),
        StmtKind::VarDecl { decls, .. } => {
            for decl in decls {
                if let BindingPattern::Ident(name) = &decl.pattern
                    && let Some(init) = &decl.init
                {
                    let cert =
                        certified_value_expr(init, declared, certified, return_certs, var_certs);
                    var_certs
                        .entry(*name)
                        .and_modify(|c| *c &= cert)
                        .or_insert(cert);
                }
            }
        }
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            var_certs_expr(test, declared, certified, return_certs, var_certs);
            var_certs_stmt(consequent, declared, certified, return_certs, var_certs);
            if let Some(alternate) = alternate {
                var_certs_stmt(alternate, declared, certified, return_certs, var_certs);
            }
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            var_certs_expr(test, declared, certified, return_certs, var_certs);
            var_certs_stmt(body, declared, certified, return_certs, var_certs);
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            match init {
                Some(ForInit::Expr(expr)) => {
                    var_certs_expr(expr, declared, certified, return_certs, var_certs)
                }
                Some(ForInit::VarDecl { decls, .. }) => {
                    for decl in decls {
                        if let BindingPattern::Ident(name) = &decl.pattern
                            && let Some(init) = &decl.init
                        {
                            let cert = certified_value_expr(
                                init,
                                declared,
                                certified,
                                return_certs,
                                var_certs,
                            );
                            var_certs
                                .entry(*name)
                                .and_modify(|c| *c &= cert)
                                .or_insert(cert);
                        }
                    }
                }
                None => {}
            }
            if let Some(test) = test {
                var_certs_expr(test, declared, certified, return_certs, var_certs);
            }
            if let Some(update) = update {
                var_certs_expr(update, declared, certified, return_certs, var_certs);
            }
            var_certs_stmt(body, declared, certified, return_certs, var_certs);
        }
        StmtKind::Return(expr) => {
            if let Some(expr) = expr {
                var_certs_expr(expr, declared, certified, return_certs, var_certs);
            }
        }
        StmtKind::Throw(expr) => var_certs_expr(expr, declared, certified, return_certs, var_certs),
        StmtKind::Labeled { body, .. } => {
            var_certs_stmt(body, declared, certified, return_certs, var_certs)
        }
        StmtKind::ForOf { right, body, .. } => {
            var_certs_expr(right, declared, certified, return_certs, var_certs);
            var_certs_stmt(body, declared, certified, return_certs, var_certs);
        }
        StmtKind::Empty
        | StmtKind::Debugger
        | StmtKind::Break(_)
        | StmtKind::Continue(_)
        | StmtKind::FunctionDecl(_)
        | StmtKind::ClassDecl(_)
        | StmtKind::With { .. }
        | StmtKind::Try { .. }
        | StmtKind::Switch { .. }
        | StmtKind::ForIn { .. }
        | StmtKind::UsingDecl { .. } => {}
    }
}

fn var_certs_expr(
    expr: &Expr,
    declared: &HashSet<crux::AtomId>,
    certified: &HashSet<crux::AtomId>,
    return_certs: &HashMap<crux::AtomId, bool>,
    var_certs: &mut HashMap<crux::AtomId, bool>,
) {
    match &expr.kind {
        ExprKind::Paren(inner) => {
            var_certs_expr(inner, declared, certified, return_certs, var_certs)
        }
        ExprKind::Unary { operand, .. } => {
            var_certs_expr(operand, declared, certified, return_certs, var_certs)
        }
        ExprKind::Update { target, .. } => {
            if let Some(name) = assign_target_name(target) {
                var_certs.insert(name, false);
            }
            var_certs_expr(target, declared, certified, return_certs, var_certs);
        }
        ExprKind::Binary { left, right, .. } | ExprKind::Logical { left, right, .. } => {
            var_certs_expr(left, declared, certified, return_certs, var_certs);
            var_certs_expr(right, declared, certified, return_certs, var_certs);
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            var_certs_expr(test, declared, certified, return_certs, var_certs);
            var_certs_expr(consequent, declared, certified, return_certs, var_certs);
            var_certs_expr(alternate, declared, certified, return_certs, var_certs);
        }
        ExprKind::Assign {
            target, value, op, ..
        } => {
            if let Some(name) = assign_target_name(target) {
                let cert = if *op == AssignOp::Assign {
                    certified_value_expr(value, declared, certified, return_certs, var_certs)
                } else {
                    // A compound assignment produces an unknown value.
                    false
                };
                var_certs
                    .entry(name)
                    .and_modify(|c| *c &= cert)
                    .or_insert(cert);
            }
            var_certs_expr(target, declared, certified, return_certs, var_certs);
            var_certs_expr(value, declared, certified, return_certs, var_certs);
        }
        ExprKind::Member(member) => {
            var_certs_expr(&member.object, declared, certified, return_certs, var_certs);
            if let MemberProperty::Computed(key) = &member.property {
                var_certs_expr(key, declared, certified, return_certs, var_certs);
            }
        }
        ExprKind::Array(array) => {
            for element in &array.elements {
                match element {
                    ArrayElement::Hole => {}
                    ArrayElement::Expr(e) | ArrayElement::Spread(e) => {
                        var_certs_expr(e, declared, certified, return_certs, var_certs)
                    }
                }
            }
        }
        ExprKind::Object(object) => {
            for prop in &object.props {
                match prop {
                    ObjectProperty::Method { .. }
                    | ObjectProperty::Get { .. }
                    | ObjectProperty::Set { .. } => {}
                    ObjectProperty::Init { key, value, .. } => {
                        if let PropertyName::Computed(key_expr) = key {
                            var_certs_expr(key_expr, declared, certified, return_certs, var_certs);
                        }
                        var_certs_expr(value, declared, certified, return_certs, var_certs);
                    }
                    ObjectProperty::Spread(e) => {
                        var_certs_expr(e, declared, certified, return_certs, var_certs)
                    }
                }
            }
        }
        ExprKind::Template(template) => {
            for e in &template.exprs {
                var_certs_expr(e, declared, certified, return_certs, var_certs);
            }
        }
        ExprKind::Sequence(exprs) => {
            for e in exprs {
                var_certs_expr(e, declared, certified, return_certs, var_certs);
            }
        }
        ExprKind::Call(call) => {
            var_certs_expr(&call.callee, declared, certified, return_certs, var_certs);
            for arg in &call.args {
                match arg {
                    Argument::Expr(e) | Argument::Spread(e) => {
                        var_certs_expr(e, declared, certified, return_certs, var_certs)
                    }
                }
            }
        }
        ExprKind::New(new) => {
            var_certs_expr(&new.callee, declared, certified, return_certs, var_certs);
            for arg in &new.args {
                match arg {
                    Argument::Expr(e) | Argument::Spread(e) => {
                        var_certs_expr(e, declared, certified, return_certs, var_certs)
                    }
                }
            }
        }
        ExprKind::Ident(_)
        | ExprKind::Literal(_)
        | ExprKind::This
        | ExprKind::Super
        | ExprKind::Function(_)
        | ExprKind::Arrow { .. }
        | ExprKind::Class(_)
        | ExprKind::TaggedTemplate { .. }
        | ExprKind::PrivateIn { .. }
        | ExprKind::Yield { .. }
        | ExprKind::Await(_)
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => {}
    }
}

/// The identifier target of an assignment/update, if it writes a plain
/// variable (parentheses are transparent).
fn assign_target_name(expr: &Expr) -> Option<crux::AtomId> {
    match &expr.kind {
        ExprKind::Ident(name) => Some(*name),
        ExprKind::Paren(inner) => assign_target_name(inner),
        _ => None,
    }
}

/// Whether evaluating `expr` can write the named variable — directly, via
/// an assignment/update target. A certified script's expressions can write
/// a declared var only this way (certified calls never touch the slots), so
/// this is the full check for the `CallFastSlot` ordering guarantee.
fn expr_assigns_name(expr: &Expr, name: crux::AtomId) -> bool {
    match &expr.kind {
        ExprKind::Paren(inner) => expr_assigns_name(inner, name),
        ExprKind::Assign { target, value, .. } => {
            assign_target_name(target) == Some(name)
                || expr_assigns_name(target, name)
                || expr_assigns_name(value, name)
        }
        ExprKind::Update { target, .. } => {
            assign_target_name(target) == Some(name) || expr_assigns_name(target, name)
        }
        ExprKind::Unary { operand, .. } => expr_assigns_name(operand, name),
        ExprKind::Binary { left, right, .. } | ExprKind::Logical { left, right, .. } => {
            expr_assigns_name(left, name) || expr_assigns_name(right, name)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            expr_assigns_name(test, name)
                || expr_assigns_name(consequent, name)
                || expr_assigns_name(alternate, name)
        }
        ExprKind::Member(member) => {
            expr_assigns_name(&member.object, name)
                || match &member.property {
                    MemberProperty::Computed(key) => expr_assigns_name(key, name),
                    _ => false,
                }
        }
        ExprKind::Array(array) => array.elements.iter().any(|element| match element {
            ArrayElement::Hole => false,
            ArrayElement::Expr(e) | ArrayElement::Spread(e) => expr_assigns_name(e, name),
        }),
        ExprKind::Object(object) => object.props.iter().any(|prop| match prop {
            ObjectProperty::Method { .. }
            | ObjectProperty::Get { .. }
            | ObjectProperty::Set { .. } => false,
            ObjectProperty::Init { key, value, .. } => {
                (match key {
                    PropertyName::Ident(_) | PropertyName::Str(_) | PropertyName::Number(_) => {
                        false
                    }
                    PropertyName::Computed(key_expr) => expr_assigns_name(key_expr, name),
                }) || expr_assigns_name(value, name)
            }
            ObjectProperty::Spread(e) => expr_assigns_name(e, name),
        }),
        ExprKind::Template(template) => template.exprs.iter().any(|e| expr_assigns_name(e, name)),
        ExprKind::Sequence(exprs) => exprs.iter().any(|e| expr_assigns_name(e, name)),
        ExprKind::Call(call) => {
            expr_assigns_name(&call.callee, name)
                || call.args.iter().any(|arg| match arg {
                    Argument::Expr(e) | Argument::Spread(e) => expr_assigns_name(e, name),
                })
        }
        ExprKind::New(new) => {
            expr_assigns_name(&new.callee, name)
                || new.args.iter().any(|arg| match arg {
                    Argument::Expr(e) | Argument::Spread(e) => expr_assigns_name(e, name),
                })
        }
        ExprKind::Ident(_)
        | ExprKind::Literal(_)
        | ExprKind::This
        | ExprKind::Super
        | ExprKind::Function(_)
        | ExprKind::Arrow { .. }
        | ExprKind::Class(_)
        | ExprKind::TaggedTemplate { .. }
        | ExprKind::PrivateIn { .. }
        | ExprKind::Yield { .. }
        | ExprKind::Await(_)
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => false,
    }
}

/// Whether the expression contains a call-like node (`Call`, `New`, tagged
/// template) anywhere — such a node can run arbitrary code (a builtin that
/// writes the global callee, an uncertified function that assigns it), so a
/// fused callee-after-args read is unsafe with one in the arguments.
fn expr_contains_call(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::Paren(inner) => expr_contains_call(inner),
        ExprKind::Unary { operand, .. } => expr_contains_call(operand),
        ExprKind::Update { target, .. } => expr_contains_call(target),
        ExprKind::Binary { left, right, .. } | ExprKind::Logical { left, right, .. } => {
            expr_contains_call(left) || expr_contains_call(right)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            expr_contains_call(test)
                || expr_contains_call(consequent)
                || expr_contains_call(alternate)
        }
        ExprKind::Assign { target, value, .. } => {
            expr_contains_call(target) || expr_contains_call(value)
        }
        ExprKind::Member(member) => {
            expr_contains_call(&member.object)
                || match &member.property {
                    MemberProperty::Computed(key) => expr_contains_call(key),
                    _ => false,
                }
        }
        ExprKind::Array(array) => array.elements.iter().any(|element| match element {
            ArrayElement::Hole => false,
            ArrayElement::Expr(e) | ArrayElement::Spread(e) => expr_contains_call(e),
        }),
        ExprKind::Object(object) => object.props.iter().any(|prop| match prop {
            ObjectProperty::Method { .. }
            | ObjectProperty::Get { .. }
            | ObjectProperty::Set { .. } => false,
            ObjectProperty::Init { key, value, .. } => {
                (match key {
                    PropertyName::Ident(_) | PropertyName::Str(_) | PropertyName::Number(_) => {
                        false
                    }
                    PropertyName::Computed(key_expr) => expr_contains_call(key_expr),
                }) || expr_contains_call(value)
            }
            ObjectProperty::Spread(e) => expr_contains_call(e),
        }),
        ExprKind::Template(template) => template.exprs.iter().any(expr_contains_call),
        ExprKind::Sequence(exprs) => exprs.iter().any(expr_contains_call),
        ExprKind::Call(_) | ExprKind::New(_) | ExprKind::TaggedTemplate { .. } => true,
        ExprKind::Ident(_)
        | ExprKind::Literal(_)
        | ExprKind::This
        | ExprKind::Super
        | ExprKind::Function(_)
        | ExprKind::Arrow { .. }
        | ExprKind::Class(_)
        | ExprKind::PrivateIn { .. }
        | ExprKind::Yield { .. }
        | ExprKind::Await(_)
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => false,
    }
}

/// `ScriptSlots` layout when the script is a closed world whose declared
/// vars can live in frame slots, or the plain declared-name set when the
/// script qualifies only for direct global-object access (today's path —
/// anything that could observe the global object mid-script). `None` when
/// a construct could change binding resolution entirely (a `with`, a
/// `try`/`catch` whose parameter shadows a same-named global, a `switch`
/// with lexical cases, a `for-in`/`for-of`, or a direct `eval` call).
fn analyze_script_scope(
    stmts: &[Stmt],
) -> Option<(Option<ScriptSlots>, HashSet<String>, HashSet<crux::AtomId>)> {
    if !script_scan_allows(stmts) {
        return None;
    }
    let mut names = Vec::new();
    for name in crate::script::top_level_var_declared_names(stmts) {
        names.push(crux::intern_utf8(&name.to_string_lossy()));
    }
    let globals: HashSet<String> = names
        .iter()
        .map(|name| crux::lookup(*name).to_string_lossy())
        .collect();
    // Cut 35 slice 3: the assigned set is a prepass (the slot scan and the
    // certified-function analysis both need it), and the certified top-level
    // functions stay on the global object — their stable entry-instantiated
    // bindings — instead of taking a frame slot.
    let mut assigned = HashSet::new();
    collect_script_assigned(stmts, &mut assigned);
    let declared: HashSet<crux::AtomId> = names.iter().copied().collect();
    let certified = certified_functions(&names, &assigned, stmts);
    let return_certs = certified_return_certs(stmts, &declared, &certified);
    let mut var_certs = HashMap::new();
    collect_var_certs(stmts, &declared, &certified, &return_certs, &mut var_certs);
    let slots = {
        let mut scan = FastScopeScan::default();
        let slot_names: Vec<crux::AtomId> = names
            .iter()
            .copied()
            .filter(|name| !certified.contains(name))
            .collect();
        for name in &slot_names {
            scan.slots.insert(*name, scan.next_slot);
            scan.tdz.push(false);
            scan.next_slot += 1;
        }
        script_slots_allows(stmts, &certified, &var_certs).then(|| ScriptSlots {
            scope: ScopeInfo {
                frame_size: scan.next_slot,
                arity: 0,
                slots: scan.slots,
                tdz_store: scan.tdz,
                context_names: Vec::new(),
                context_tdz: Vec::new(),
                context_const: Vec::new(),
                context_param: Vec::new(),
                context_slots: HashMap::new(),
                arguments_slot: None,
                arguments_formals: None,
                this_slot: None,
                captured_this: None,
                args_alias: false,
                annex_b: Vec::new(),
                statement_fns: Vec::new(),
            },
            names: slot_names,
            assigned: assigned.clone(),
        })
    };
    Some((slots, globals, assigned))
}

/// Whether the script is a closed world for frame-slot vars (Cut 16): no
/// callable can observe the real global object while the slots are
/// authoritative (their staleness window is the whole script). Reject
/// `call`/`new` expressions (except direct calls to a certified function),
/// uncertified function declarations, `this`, closures (function/arrow/
/// class expressions and object methods/getters/setters), and any
/// `globalThis`-family identifier (a member access on it reaches the real
/// global object). `assigned` (the epilogue write-back set) is collected
/// by the prepass; `certified` is the global-blind function set (Cut 35
/// slice 3).
fn script_slots_allows(
    stmts: &[Stmt],
    certified: &HashSet<crux::AtomId>,
    var_certs: &HashMap<crux::AtomId, bool>,
) -> bool {
    stmts
        .iter()
        .all(|stmt| script_slots_stmt_allows(stmt, certified, var_certs))
}

fn script_slots_stmt_allows(
    stmt: &Stmt,
    certified: &HashSet<crux::AtomId>,
    var_certs: &HashMap<crux::AtomId, bool>,
) -> bool {
    match &stmt.kind {
        StmtKind::Block(block) => script_slots_allows(&block.stmts, certified, var_certs),
        StmtKind::Empty | StmtKind::Debugger | StmtKind::Break(_) | StmtKind::Continue(_) => true,
        StmtKind::Expr(expr) => script_slots_expr_allows(expr, certified, var_certs),
        StmtKind::VarDecl { decls, .. } => decls.iter().all(|decl| {
            // A destructuring pattern resolves through the environment
            // machinery, bypassing the frame slots — such a script must stay
            // on the global path.
            matches!(&decl.pattern, BindingPattern::Ident(_))
                && decl
                    .init
                    .as_ref()
                    .is_none_or(|init| script_slots_expr_allows(init, certified, var_certs))
        }),
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            script_slots_expr_allows(test, certified, var_certs)
                && script_slots_stmt_allows(consequent, certified, var_certs)
                && alternate
                    .as_deref()
                    .is_none_or(|stmt| script_slots_stmt_allows(stmt, certified, var_certs))
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            script_slots_expr_allows(test, certified, var_certs)
                && script_slots_stmt_allows(body, certified, var_certs)
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            let init_ok = match init {
                None => true,
                Some(ForInit::Expr(expr)) => script_slots_expr_allows(expr, certified, var_certs),
                Some(ForInit::VarDecl { decls, .. }) => decls.iter().all(|decl| {
                    matches!(&decl.pattern, BindingPattern::Ident(_))
                        && decl
                            .init
                            .as_ref()
                            .is_none_or(|init| script_slots_expr_allows(init, certified, var_certs))
                }),
            };
            init_ok
                && test
                    .as_ref()
                    .is_none_or(|expr| script_slots_expr_allows(expr, certified, var_certs))
                && update
                    .as_ref()
                    .is_none_or(|expr| script_slots_expr_allows(expr, certified, var_certs))
                && script_slots_stmt_allows(body, certified, var_certs)
        }
        StmtKind::Return(expr) => expr
            .as_ref()
            .is_none_or(|expr| script_slots_expr_allows(expr, certified, var_certs)),
        StmtKind::Throw(expr) => script_slots_expr_allows(expr, certified, var_certs),
        StmtKind::Labeled { body, .. } => script_slots_stmt_allows(body, certified, var_certs),
        StmtKind::ForOf {
            left, right, body, ..
        } => {
            // The for-of head binds each element — an assignment (collected
            // by the prepass).
            matches!(
                left,
                ForBinding::VarDecl {
                    pattern: BindingPattern::Ident(_),
                    ..
                }
            ) && script_slots_expr_allows(right, certified, var_certs)
                && script_slots_stmt_allows(body, certified, var_certs)
        }
        // Cut 35 slice 3: a certified (global-blind) top-level function
        // declaration cannot observe the slotified globals, so it no longer
        // disqualifies the frame path. `script_scan_allows` already rejects
        // `with`/`try`/`switch`/`for-in`/`using` (the whole script falls
        // back to the env path); the rest are kept exhaustive.
        StmtKind::FunctionDecl(function) => {
            function.name.is_some_and(|name| certified.contains(&name))
        }
        StmtKind::ClassDecl(_)
        | StmtKind::With { .. }
        | StmtKind::Try { .. }
        | StmtKind::Switch { .. }
        | StmtKind::ForIn { .. }
        | StmtKind::UsingDecl { .. } => false,
    }
}

fn script_slots_expr_allows(
    expr: &Expr,
    certified: &HashSet<crux::AtomId>,
    var_certs: &HashMap<crux::AtomId, bool>,
) -> bool {
    match &expr.kind {
        ExprKind::Ident(name) => {
            let text = crux::lookup(*name).to_string_lossy();
            !matches!(
                text.as_str(),
                "globalThis" | "global" | "window" | "self" | "top" | "parent" | "frames"
            )
        }
        ExprKind::This
        | ExprKind::Super
        | ExprKind::Function(_)
        | ExprKind::Arrow { .. }
        | ExprKind::Class(_) => false,
        ExprKind::Call(call) => {
            // Cut 35 slice 3: a direct call to a certified (global-blind)
            // top-level function — or a var assigned a certified value (a
            // certified closure, a certified-call result) — cannot observe
            // the slotified globals: a certified function's global binding
            // is stable (never assigned) and its body never reads a slot
            // var; a certified-value var's current value comes from the
            // slot, which is the script's own up-to-date copy.
            let callee_ok = match &call.callee.kind {
                ExprKind::Ident(name) => {
                    certified.contains(name) || var_certs.get(name).copied().unwrap_or(false)
                }
                _ => false,
            };
            callee_ok
                && call.args.iter().all(|arg| match arg {
                    Argument::Expr(e) | Argument::Spread(e) => {
                        script_slots_expr_allows(e, certified, var_certs)
                    }
                })
        }
        ExprKind::New(_) => false,
        ExprKind::Object(object) => object.props.iter().all(|prop| match prop {
            ObjectProperty::Method { .. }
            | ObjectProperty::Get { .. }
            | ObjectProperty::Set { .. } => false,
            ObjectProperty::Init { key, value, .. } => {
                let key_ok = match key {
                    PropertyName::Ident(_) | PropertyName::Str(_) | PropertyName::Number(_) => true,
                    PropertyName::Computed(key_expr) => {
                        script_slots_expr_allows(key_expr, certified, var_certs)
                    }
                };
                key_ok && script_slots_expr_allows(value, certified, var_certs)
            }
            ObjectProperty::Spread(expr) => script_slots_expr_allows(expr, certified, var_certs),
        }),
        ExprKind::Literal(_) => true,
        ExprKind::Array(array) => array.elements.iter().all(|element| match element {
            ArrayElement::Hole => true,
            ArrayElement::Expr(expr) | ArrayElement::Spread(expr) => {
                script_slots_expr_allows(expr, certified, var_certs)
            }
        }),
        ExprKind::Paren(inner) => script_slots_expr_allows(inner, certified, var_certs),
        ExprKind::Unary { operand, .. } => script_slots_expr_allows(operand, certified, var_certs),
        ExprKind::Update { target, .. } => script_slots_expr_allows(target, certified, var_certs),
        ExprKind::Binary { left, right, .. } => {
            script_slots_expr_allows(left, certified, var_certs)
                && script_slots_expr_allows(right, certified, var_certs)
        }
        ExprKind::Logical { left, right, .. } => {
            script_slots_expr_allows(left, certified, var_certs)
                && script_slots_expr_allows(right, certified, var_certs)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            script_slots_expr_allows(test, certified, var_certs)
                && script_slots_expr_allows(consequent, certified, var_certs)
                && script_slots_expr_allows(alternate, certified, var_certs)
        }
        ExprKind::Assign { target, value, .. } => {
            script_slots_expr_allows(target, certified, var_certs)
                && script_slots_expr_allows(value, certified, var_certs)
        }
        ExprKind::Member(member) => {
            let object_ok = script_slots_expr_allows(&member.object, certified, var_certs);
            let key_ok = match &member.property {
                MemberProperty::Computed(key) => {
                    script_slots_expr_allows(key, certified, var_certs)
                }
                _ => true,
            };
            object_ok && key_ok
        }
        ExprKind::Template(template) => template
            .exprs
            .iter()
            .all(|expr| script_slots_expr_allows(expr, certified, var_certs)),
        ExprKind::Sequence(exprs) => exprs
            .iter()
            .all(|expr| script_slots_expr_allows(expr, certified, var_certs)),
        ExprKind::PrivateIn { .. }
        | ExprKind::TaggedTemplate { .. }
        | ExprKind::Yield { .. }
        | ExprKind::Await(_)
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => false,
    }
}

/// Record the name an assignment/update writes: an identifier target (or a
/// parenthesized identifier); member/array targets write properties, not
/// the object's binding.
fn record_assign_target(expr: &Expr, assigned: &mut HashSet<crux::AtomId>) {
    match &expr.kind {
        ExprKind::Ident(name) => {
            assigned.insert(*name);
        }
        ExprKind::Paren(inner) => record_assign_target(inner, assigned),
        _ => {}
    }
}

// ---- Cut 17: accumulator loop counter body scan ----

/// The identifier an assignment/update writes, unwrapping parentheses
/// (`(i) = 5` and `(i)++` update the covered reference).
fn acc_target_name(target: &Expr) -> Option<crux::AtomId> {
    match &target.kind {
        ExprKind::Ident(name) => Some(*name),
        ExprKind::Paren(inner) => acc_target_name(inner),
        _ => None,
    }
}

/// Whether an expression provably evaluates to a Number (Cut 35 slice 22):
/// the accumulator-path loop counter lives in an `f64` field, so every
/// value that enters it must be a Number. A numeric literal qualifies, as
/// does `+expr` (it always yields a Number — or throws, and the throw
/// propagates before the store, never a BigInt), and `-expr` whose operand
/// is itself provably a Number (unary minus on a BigInt would yield a
/// BigInt). Everything else — idents, strings, calls, binary `+` (string
/// concat) — is rejected, falling back to the slot path.
fn expr_is_number(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::Literal(syntax::ast::Literal::Number(_)) => true,
        ExprKind::Unary {
            op: UnaryOp::Plus, ..
        } => true,
        ExprKind::Unary {
            op: UnaryOp::Minus,
            operand,
        } => expr_is_number(operand),
        ExprKind::Paren(inner) => expr_is_number(inner),
        _ => false,
    }
}

/// Whether the loop init provably stores a Number into the counter binding
/// (Cut 35 slice 22): `FastLoopBind` moves the init into the f64
/// `loop_counter` field, so the init must be a Number. A missing init, an
/// expression head, or a `var` head that doesn't write the counter leaves
/// the slot's pre-loop value unknown. When multiple declarations bind the
/// counter, the last one's initializer wins (each initializer compiles in
/// order), so only it needs the Number check.
fn for_init_counter_number(init: Option<&ForInit>, name: crux::AtomId) -> bool {
    match init {
        Some(ForInit::VarDecl { decls, .. }) => decls
            .iter()
            .rev()
            .find(|decl| matches!(&decl.pattern, BindingPattern::Ident(n) if *n == name))
            .is_some_and(|decl| decl.init.as_ref().is_some_and(expr_is_number)),
        _ => false,
    }
}

/// Whether a statement subtree uses the loop counter safely for the
/// accumulator (see `Compiler::acc_body_safe`).
fn acc_stmt_safe(stmt: &Stmt, name: crux::AtomId) -> bool {
    match &stmt.kind {
        StmtKind::Block(block) => block.stmts.iter().all(|s| acc_stmt_safe(s, name)),
        StmtKind::Empty | StmtKind::Debugger | StmtKind::Break(_) | StmtKind::Continue(_) => true,
        StmtKind::Expr(expr) => acc_expr_safe(expr, name, true),
        StmtKind::VarDecl { decls, .. } => decls.iter().all(|decl| {
            // A declaration (or re-declaration) of the counter rebinds it
            // through the slot, which is stale mid-loop.
            !matches!(&decl.pattern, BindingPattern::Ident(n) if *n == name)
                && decl
                    .init
                    .as_ref()
                    .is_none_or(|init| acc_expr_safe(init, name, false))
        }),
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            acc_expr_safe(test, name, false)
                && acc_stmt_safe(consequent, name)
                && alternate.as_deref().is_none_or(|s| acc_stmt_safe(s, name))
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            acc_expr_safe(test, name, false) && acc_stmt_safe(body, name)
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            let init_ok = match init {
                None => true,
                Some(ForInit::Expr(expr)) => acc_expr_safe(expr, name, false),
                Some(ForInit::VarDecl { decls, .. }) => decls.iter().all(|decl| {
                    !matches!(&decl.pattern, BindingPattern::Ident(n) if *n == name)
                        && decl
                            .init
                            .as_ref()
                            .is_none_or(|init| acc_expr_safe(init, name, false))
                }),
            };
            init_ok
                && test
                    .as_ref()
                    .is_none_or(|expr| acc_expr_safe(expr, name, false))
                && update
                    .as_ref()
                    .is_none_or(|expr| acc_expr_safe(expr, name, false))
                && acc_stmt_safe(body, name)
        }
        StmtKind::Return(expr) => expr
            .as_ref()
            .is_none_or(|expr| acc_expr_safe(expr, name, false)),
        StmtKind::Throw(expr) => acc_expr_safe(expr, name, false),
        StmtKind::Labeled { body, .. } => acc_stmt_safe(body, name),
        StmtKind::ForOf {
            left, right, body, ..
        } => {
            // A for-of head over the counter rebinds it per element.
            !matches!(
                left,
                ForBinding::VarDecl {
                    pattern: BindingPattern::Ident(n),
                    ..
                } if *n == name
            ) && acc_expr_safe(right, name, false)
                && acc_stmt_safe(body, name)
        }
        // Rejected by the certified-body/script scans before the accumulator
        // can fire (a slot counter implies a certified body); kept
        // exhaustive.
        StmtKind::FunctionDecl(_)
        | StmtKind::ClassDecl(_)
        | StmtKind::With { .. }
        | StmtKind::Try { .. }
        | StmtKind::Switch { .. }
        | StmtKind::ForIn { .. }
        | StmtKind::UsingDecl { .. } => false,
    }
}

/// Whether every labeled `break`/`continue` in an accumulator-path loop body
/// targets a label declared INSIDE the body. The acc path keeps the counter
/// in the `loop_counter` field and syncs it back to the binding with a
/// single `FastLoopStore` at the loop's END step; a labeled transfer to a
/// label outside the body (the loop's own label or an enclosing label) jumps
/// past that step, leaving the binding with its pre-loop value — observable
/// after the transfer. Unlabeled transfers always target the innermost
/// breakable construct inside the body or the loop itself, so they land at
/// or before the end step and are safe. Nested function bodies are not
/// walked: their breaks/continues can never reach this loop (an early error
/// if they cross a function boundary).
fn acc_body_label_transfers_inside(body: &Stmt) -> bool {
    fn walk(stmt: &Stmt, enclosing: &HashSet<crux::AtomId>) -> bool {
        match &stmt.kind {
            StmtKind::Block(block) => block.stmts.iter().all(|s| walk(s, enclosing)),
            StmtKind::Labeled { label, body } => {
                let mut labels = enclosing.clone();
                labels.insert(*label);
                walk(body, &labels)
            }
            StmtKind::If {
                consequent,
                alternate,
                ..
            } => {
                walk(consequent, enclosing)
                    && alternate.as_deref().is_none_or(|s| walk(s, enclosing))
            }
            StmtKind::While { body, .. } | StmtKind::DoWhile { body, .. } => walk(body, enclosing),
            StmtKind::For { body, .. } | StmtKind::ForOf { body, .. } => walk(body, enclosing),
            StmtKind::Break(Some(label)) | StmtKind::Continue(Some(label)) => {
                enclosing.contains(label)
            }
            StmtKind::Break(None) | StmtKind::Continue(None) => true,
            // Function/class declarations and the remaining statement kinds
            // hold no transfers that can reach this loop (or are rejected
            // from acc bodies by `acc_stmt_safe` anyway), so they are safe.
            _ => true,
        }
    }
    walk(body, &HashSet::new())
}

/// Whether an expression subtree uses the loop counter safely for the
/// accumulator. `statement` marks the expression's position: a simple
/// `counter = expr` or `counter++`/`counter--` is allowed only as a
/// statement (the loop protocol discards its value; in value position the
/// compiled `PopAcc`/`IncAcc` would not produce the expression's result).
fn acc_expr_safe(expr: &Expr, name: crux::AtomId, statement: bool) -> bool {
    match &expr.kind {
        // A read of the counter is always safe (any expression position).
        ExprKind::Ident(_) => true,
        ExprKind::Paren(inner) => acc_expr_safe(inner, name, statement),
        ExprKind::Assign {
            target, value, op, ..
        } => {
            let target_ok = match acc_target_name(target) {
                Some(target_name) => {
                    target_name != name
                        || (statement
                            && *op == AssignOp::Assign
                            // Cut 35 slice 22: the acc-path counter lives
                            // in an f64 field, so a statement-position
                            // `counter = expr` may enter the field only with
                            // a provably-Number expression (a String/BigInt
                            // result would corrupt the raw counter — those
                            // loops fall back to the slot path).
                            && expr_is_number(value))
                }
                None => true,
            };
            target_ok && acc_expr_safe(target, name, false) && acc_expr_safe(value, name, false)
        }
        ExprKind::Update { target, .. } => {
            let target_ok = match acc_target_name(target) {
                Some(target_name) => target_name != name || statement,
                None => true,
            };
            target_ok && acc_expr_safe(target, name, false)
        }
        ExprKind::Array(array) => array.elements.iter().all(|element| match element {
            ArrayElement::Hole => true,
            ArrayElement::Expr(e) | ArrayElement::Spread(e) => acc_expr_safe(e, name, false),
        }),
        ExprKind::Object(object) => object.props.iter().all(|prop| match prop {
            ObjectProperty::Method { .. }
            | ObjectProperty::Get { .. }
            | ObjectProperty::Set { .. } => false,
            ObjectProperty::Init { key, value, .. } => {
                let key_ok = match key {
                    PropertyName::Ident(_) | PropertyName::Str(_) | PropertyName::Number(_) => true,
                    PropertyName::Computed(key_expr) => acc_expr_safe(key_expr, name, false),
                };
                key_ok && acc_expr_safe(value, name, false)
            }
            ObjectProperty::Spread(e) => acc_expr_safe(e, name, false),
        }),
        ExprKind::Literal(_) => true,
        ExprKind::Unary { operand, .. } => acc_expr_safe(operand, name, false),
        ExprKind::Binary { left, right, .. } => {
            acc_expr_safe(left, name, false) && acc_expr_safe(right, name, false)
        }
        ExprKind::Logical { left, right, .. } => {
            acc_expr_safe(left, name, false) && acc_expr_safe(right, name, false)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            acc_expr_safe(test, name, false)
                && acc_expr_safe(consequent, name, false)
                && acc_expr_safe(alternate, name, false)
        }
        ExprKind::Member(member) => {
            let object_ok = acc_expr_safe(&member.object, name, false);
            let key_ok = match &member.property {
                MemberProperty::Computed(key) => acc_expr_safe(key, name, false),
                _ => true,
            };
            object_ok && key_ok
        }
        ExprKind::Call(call) => {
            acc_expr_safe(&call.callee, name, false)
                && call.args.iter().all(|arg| match arg {
                    Argument::Expr(e) | Argument::Spread(e) => acc_expr_safe(e, name, false),
                })
        }
        ExprKind::New(new) => {
            acc_expr_safe(&new.callee, name, false)
                && new.args.iter().all(|arg| match arg {
                    Argument::Expr(e) | Argument::Spread(e) => acc_expr_safe(e, name, false),
                })
        }
        ExprKind::Template(template) => {
            template.exprs.iter().all(|e| acc_expr_safe(e, name, false))
        }
        ExprKind::Sequence(exprs) => exprs.iter().all(|e| acc_expr_safe(e, name, false)),
        ExprKind::This
        | ExprKind::Super
        | ExprKind::Function(_)
        | ExprKind::Arrow { .. }
        | ExprKind::Class(_)
        | ExprKind::PrivateIn { .. }
        | ExprKind::TaggedTemplate { .. }
        | ExprKind::Yield { .. }
        | ExprKind::Await(_)
        | ExprKind::MetaProperty { .. }
        | ExprKind::ImportCall { .. } => false,
    }
}

fn script_scan_allows(stmts: &[Stmt]) -> bool {
    stmts.iter().all(script_stmt_allows)
}

fn script_stmt_allows(stmt: &Stmt) -> bool {
    match &stmt.kind {
        StmtKind::Block(block) => script_scan_allows(&block.stmts),
        StmtKind::Empty | StmtKind::Debugger | StmtKind::Break(_) | StmtKind::Continue(_) => true,
        StmtKind::Expr(expr) => script_expr_allows(expr),
        StmtKind::VarDecl { kind, decls } => {
            *kind == VarDeclKind::Var
                && decls
                    .iter()
                    .all(|decl| decl.init.as_ref().is_none_or(script_expr_allows))
        }
        StmtKind::If {
            test,
            consequent,
            alternate,
        } => {
            script_expr_allows(test)
                && script_stmt_allows(consequent)
                && alternate.as_deref().is_none_or(script_stmt_allows)
        }
        StmtKind::While { test, body } | StmtKind::DoWhile { body, test } => {
            script_expr_allows(test) && script_stmt_allows(body)
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
        } => {
            let init_ok = match init {
                None => true,
                Some(ForInit::Expr(expr)) => script_expr_allows(expr),
                Some(ForInit::VarDecl { kind, decls }) => {
                    *kind == VarDeclKind::Var
                        && decls
                            .iter()
                            .all(|decl| decl.init.as_ref().is_none_or(script_expr_allows))
                }
            };
            init_ok
                && test.as_ref().is_none_or(script_expr_allows)
                && update.as_ref().is_none_or(script_expr_allows)
                && script_stmt_allows(body)
        }
        StmtKind::Return(expr) => expr.as_ref().is_none_or(script_expr_allows),
        StmtKind::Throw(expr) => script_expr_allows(expr),
        StmtKind::Labeled { body, .. } => script_stmt_allows(body),
        StmtKind::FunctionDecl(_) | StmtKind::ClassDecl(_) => true,
        // `with` re-resolves every name against an object env; a `catch`
        // parameter shadows a same-named global inside its handler; a
        // `switch` case can hold lexical declarations; `for-in` heads have
        // their own binding machinery; `using` is lexical. All fall back
        // to the env path.
        StmtKind::With { .. }
        | StmtKind::Try { .. }
        | StmtKind::Switch { .. }
        | StmtKind::ForIn { .. }
        | StmtKind::UsingDecl { .. } => false,
        // A `for-of` with a simple `var` ident head binds via the global
        // cell / frame slot (`ForOfBindGlobal`/`ForOfBindLocal`) with no
        // per-iteration environment — the iterator protocol, the per-step
        // length/element re-read, and the close machinery are all VM-side
        // — so the loop stays on the fast-script path. A lexical head
        // (per-iteration environments), a destructuring head, or a body
        // with env-path statements keeps the whole script on the env path.
        StmtKind::ForOf {
            left, right, body, ..
        } => {
            matches!(
                left,
                ForBinding::VarDecl {
                    kind: VarDeclKind::Var,
                    pattern: BindingPattern::Ident(_),
                    ..
                }
            ) && script_expr_allows(right)
                && script_stmt_allows(body)
        }
    }
}

fn script_expr_allows(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::Literal(_)
        | ExprKind::Ident(_)
        | ExprKind::This
        | ExprKind::Function(_)
        | ExprKind::Arrow { .. }
        | ExprKind::Class(_)
        | ExprKind::Array(_)
        | ExprKind::Object(_) => true,
        ExprKind::Paren(inner) => script_expr_allows(inner),
        ExprKind::Unary { operand, .. } => script_expr_allows(operand),
        ExprKind::Update { target, .. } => script_expr_allows(target),
        ExprKind::Binary { left, right, .. } => {
            script_expr_allows(left) && script_expr_allows(right)
        }
        ExprKind::Logical { left, right, .. } => {
            script_expr_allows(left) && script_expr_allows(right)
        }
        ExprKind::Conditional {
            test,
            consequent,
            alternate,
        } => {
            script_expr_allows(test)
                && script_expr_allows(consequent)
                && script_expr_allows(alternate)
        }
        ExprKind::Assign { target, value, .. } => {
            script_expr_allows(target) && script_expr_allows(value)
        }
        ExprKind::Member(member) => {
            if matches!(member.property, MemberProperty::Private(_)) {
                return false;
            }
            script_expr_allows(&member.object)
                && match &member.property {
                    MemberProperty::Computed(key) => script_expr_allows(key),
                    _ => true,
                }
        }
        ExprKind::Call(call) => {
            // A direct `eval` call can see and change the script's
            // resolution; bail conservatively (matches the fast-body
            // certification).
            if matches!(&call.callee.kind, ExprKind::Ident(id)
                if crux::lookup(*id) == JsString::from_utf8("eval"))
            {
                return false;
            }
            script_expr_allows(&call.callee)
                && call.args.iter().all(|arg| match arg {
                    Argument::Expr(expr) => script_expr_allows(expr),
                    Argument::Spread(expr) => script_expr_allows(expr),
                })
        }
        ExprKind::New(new) => {
            script_expr_allows(&new.callee)
                && new.args.iter().all(|arg| match arg {
                    Argument::Expr(expr) => script_expr_allows(expr),
                    Argument::Spread(expr) => script_expr_allows(expr),
                })
        }
        ExprKind::Template(template) => template.exprs.iter().all(script_expr_allows),
        ExprKind::TaggedTemplate { tag, quasi } => {
            script_expr_allows(tag) && quasi.exprs.iter().all(script_expr_allows)
        }
        ExprKind::Sequence(exprs) => exprs.iter().all(script_expr_allows),
        ExprKind::MetaProperty { .. } => true,
        ExprKind::ImportCall { .. } => true,
        ExprKind::PrivateIn { .. } => false,
        ExprKind::Super => false,
        ExprKind::Yield { .. } | ExprKind::Await(_) => false,
    }
}
